-- Sources: data/i18n/ruRU. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_ruRU")
P.entries["quest:3514"] = {n="Мощь Орды",s="«Мощь Орды» — военная операция, заказанная орком Кадраком на границе Степей и Ясеневого леса. После перехваченного послания Орда отправляет героя высоко на Пик Каменного Когтя, чтобы убить дриаду Ринтариэль и водрузить знамя Орды прямо в Пещере Когтей.",h="«Мощь Орды» — военная операция, заказанная орком Кадраком на границе Степей и Ясеневого леса.",kw={"barrens","dryad","horde presence","kadrak","kadrak's flag","rynthariel","stonetalon peak","talon den","the runed scroll","степи","дриада","мощь орды","кадрак","знамя кадрака","ринтариэль","пик каменного когтя","пещера когтей","свиток с рунами"},ang={["class:Druid"]="Для друидов Орды поход на Пик Каменного Когтя, чтобы убить дриаду, дитя Кенария, показывает горькое политическое противоречие между верностью фракции и священными узами с природой.",["faction:Horde"]="Защита северных границ Степей необходима, чтобы сохранить контроль над центральными равнинами Калимдора и защитить молодые поселения от вторжений ночных эльфов.",["race:Orc"]="Орки считают решительное наступление Кадрака единственным подходящим ответом на вторжение на их территорию: оно демонстрирует силу и не оставляет Альянсу простора для маневра."},sec={{t="Перехваченное послание",b="Кадрак охраняет северную границу Степей и бдительно следит за посягательствами Альянса и ночных эльфов. Когда убит гонец со свитком с рунами, Кадрак расшифровывает послание и выясняет, что оно исходит от Ринтариэль Хранительницы Ключа, влиятельной дриады, обосновавшейся на Пике Каменного Когтя. Вместо того чтобы просто защищать горные перевалы, Кадрак выбирает агрессивный ответ, чтобы отбить у будущих разведчиков охоту соваться на земли Орды."},{t="Вызов в Пещере Когтей",b="Задание отправляет воинов Орды вглубь Пещеры Когтей — пещерного оплота над Пиком Каменного Когтя. Убийство Ринтариэль наносит прямой удар по согласованности действий местных ночных эльфов, а водружение знамени Орды Кадрака в самой пещере служит завершающим штрихом. Оставив красный стяг развеваться в сердце владений дриад, Орда ясно дает понять: вторжения в Степи будут встречены решительным насилием."}},faq={{q="Кто такой Кадрак и почему он приказывает нанести этот удар?",a="Кадрак — орк-воин, находящийся на северном пограничном аванпосте между Степями и Ясеневым лесом. Отвечая за защиту земель Орды от чужих посягательств, он приказывает нанести упреждающий ответный удар, когда обнаруживает, что гонцы Альянса проскальзывают через ближние перевалы.",al={"kadrak","who is kadrak","kadrak purpose","кадрак","кто такой кадрак","зачем кадрак"}},{q="Кто такая Ринтариэль Хранительница Ключа?",a="Ринтариэль — предводительница дриад, обитающая в Пещере Когтей на Пике Каменного Когтя. Она написала свиток с рунами, который нес перехваченный гонец, координируя передвижения Альянса и часовых в горных проходах.",al={"rynthariel","rynthariel the keymaster","talon den boss","ринтариэль","ринтариэль хранительница ключа","босс пещеры когтей"}},{q="Где находится Пещера Когтей?",a="Пещера Когтей — подземный комплекс пещер на западных склонах Пика Каменного Когтя, расположенный высоко в Когтистых горах.",al={"talon den location","where is talon den","rynthariel location","где пещера когтей","расположение пещеры когтей","где ринтариэль"}},{q="Зачем нужно водружать знамя Кадрака?",a="Водружение знамени служит психологическим предупреждением. Кадрак хочет, чтобы ночные эльфы и Альянс увидели красное знамя Орды над телом их павшей предводительницы и дважды подумали, прежде чем посылать новых разведчиков через Степи.",al={"why plant the flag","kadrak's flag","horde flag purpose","зачем водружать знамя","знамя кадрака","зачем знамя орды"}},{q="Как это задание связано с заданием «Свиток с рунами»?",a="«Мощь Орды» напрямую продолжает «Свиток с рунами». Это задание открывается, только когда игрок находит перехваченный пергамент у гонца Альянса и приносит его Кадраку для расшифровки.",al={"runed scroll connection","previous quest","horde presence prerequisite","связь со свитком с рунами","предыдущее задание","что нужно для мощи орды"}},{q="Почему Орду тревожат гонцы Альянса в Степях?",a="Степи — жизненно важный центр, связывающий Оргриммар, Громовой Утес и окрестные поселения. Если позволить гонцам Альянса и союзникам-ночным эльфам свободно проходить через горные проходы, это угрожает линиям снабжения и безопасности границ Орды.",al={"alliance in barrens","why fight dryads","barrens threat","альянс в степях","зачем сражаться с дриадами","угроза степям"}}},fp="14,289,21.458.0,19.453.0,48.272.0,32.218.0,31.138.0,46.235.0,50.212.0,65.240.0"}
P.entries["quest:3519"] = {n="Друг в беде",s="«Друг в беде» — срочная мольба о помощи от Иверрона, молодого ночного эльфа, страдающего от укусов ядовитых пауков в Тенистой долине. Сраженный жутким чудовищем Гитьис Зловещей, Иверрон посылает путников найти Диранию Серебряное Сияние, пока яд не погубил его.",h="«Друг в беде» — срочная мольба о помощи от Иверрона, молодого ночного эльфа, страдающего от укусов ядовитых...",kw={"aldrassil","dirania silvershine","githyiss","iverron","poison","shadowglen","spider","teldrassil","альдрассил","дирания серебряное сияние","гитьис","иверрон","яд","тенистая долина","паук","тельдрассил"},ang={["class:Druid"]="Друиды с ранних пор узнают, что нарушенное равновесие местной фауны может погубить неосторожных, и это подчеркивает острую необходимость понимать яды природы и противостоять им.",["race:NightElf"]="Для молодых кальдораев, начинающих обучение под сенью Альдрассила, беда Иверрона — суровое напоминание о том, что даже укромные ветви Тенистой долины больше не свободны от порчи и смертельной опасности."},sec={{t="Безрассудная затея",b="Раскидистые кроны Тенистой долины укрывают всевозможных животных, но соседние паутинные лощины таят куда более мрачные угрозы. Пренебрегнув прежними предостережениями, Иверрон подошел слишком близко к местным пещерам Паутинного леса и встретил Гитьис Зловещую, свирепого паука, чей яд быстро одолел молодого эльфа. Его мучают головокружение и слабость, и сам он добраться до безопасного места не может."},{t="Зов к Альдрассилу",b="Отчаянно пытаясь выжить, Иверрон просит любого прохожего поспешить к центральному древу Альдрассилу и предупредить Диранию Серебряное Сияние. Дирания, привыкшая присматривать за ним и знающая опасности долины, — его единственная надежда успеть приготовить спасительное противоядие, пока токсин не оказался смертельным."}},faq={{q="Кто такой Иверрон?",a="Иверрон — молодой ночной эльф, живущий в Тенистой долине на Тельдрассиле. Он часто забредает в опасные места вопреки предостережениям товарищей, из-за чего едва не погибает при встрече с Гитьис Зловещей.",al={"iverron lore","who is the poisoned elf","who gives a friend in need","предания об иверроне","кто отравленный эльф","кто выдает задание друг в беде"}},{q="Кто напал на Иверрона?",a="Его укусила Гитьис Зловещая, печально известный сильно ядовитый паук, обитающий в паучьей пещере в Тенистой долине.",al={"what bit iverron","who is githyiss","what spider poisoned him","кто укусил иверрона","кто такая гитьис","какой паук отравил его"}},{q="Кто такая Дирания Серебряное Сияние?",a="Дирания Серебряное Сияние — ночная эльфийка, живущая у Альдрассила в Тенистой долине. Она близкий друг и наставница Иверрона и умеет лечить ядовитые раны.",al={"dirania role","who to talk to for iverron","роль дирании","с кем говорить об иверроне"}},{q="Где происходит это задание?",a="Задание целиком происходит в Тенистой долине — укромной начальной долине ночных эльфов, расположенной высоко на вершине Тельдрассила.",al={"where is a friend in need","iverron location","где друг в беде","где иверрон"}},{q="Что происходит после доклада Дирании о состоянии Иверрона?",a="Дирания немедленно принимается готовить лекарство и посылает искателей приключений по роще за редкими реагентами, нужными для противоядия, пока Иверрон не поддался яду.",al={"what next after a friend in need","does iverron get saved","что дальше после друга в беде","спасут ли иверрона"}},{q="Почему в Тенистой долине есть смертоносные пауки?",a="Хотя Тенистая долина считается безопасным убежищем для молодых ночных эльфов, порча, распространяющаяся по Тельдрассилу, превратила диких зверей и тварей вроде пауков Паутинного леса в необычно агрессивных ядовитых хищников.",al={"why are there spiders in shadowglen","spider corruption teldrassil","почему пауки в тенистой долине","порча пауки тельдрассил"}}},fp="16,264,18.394.0,19.311.0,15.216.0,22.130.0,27.166.0,33.137.0,60.187.1,47.217.0"}
P.entries["quest:3521"] = {n="Противоядие для Иверрона",s="«Противоядие для Иверрона» — срочное задание в Тенистой долине: спасти отравленного разведчика-ночного эльфа. Собирая дикие грибы, лилии и паучий яд, искатели приключений помогают Дирании Серебряному Сиянию сварить лекарство, пока яд не завладел им полностью.",h="«Противоядие для Иверрона» — срочное задание в Тенистой долине: спасти отравленного разведчика-ночного эльфа.",kw={"aldrassil","antidote","dirania silvershine","hyacinth mushroom","iverron","moonpetal lily","shadowglen","shadowthread cave","webwood ichor","альдрассил","противоядие","дирания серебряное сияние","гиацинтовый гриб","иверрон","лунная лилия","тенистая долина","паучье логово","ихор паутинного леса"},ang={["class:Druid"]="Приготовление лекарств из местной флоры и нейтрализация природных ядов отражает основополагающее равновесие, которое друиды стремятся сохранять в дикой природе.",["profession:Herbalism"]="Сбор лунных лилий и гиацинтовых грибов показывает, что дикие растения Тельдрассила обладают сильными целебными свойствами при бережном обращении.",["race:NightElf"]="Забота о павших сородичах — священный долг в Тенистой долине, где нужен каждый защитник, чтобы оберегать молодое Мировое Древо."},sec={{t="Гонка с ядом",b="Разведывая ветви Тенистой долины, юный Иверрон стал жертвой ядовитых клыков местных пауков. Он лежит при смерти, и его спасение целиком зависит от знаний трав у Дирании Серебряного Сияния в Альдрассиле. Юноша быстро угасает, и ей нужно срочно приготовить особое снадобье, чтобы нейтрализовать едкий яд в его крови."},{t="Реагенты Тенистой долины",b="Dirania's recipe relies on the restorative flora of Teldrassil balanced against the venom itself. Hyacinth mushrooms, favored by the thieving grell to the south, provide an earthy base, while delicate Moonpetal lilies gathered from tranquil forest pools offer purifying qualities. To finish the draft, a sample of Webwood ichor must be extracted directly from the spiders prowling near Shadowthread Cave to tailor the cure to their specific poison."}},faq={{q="Кто такой Иверрон?",a="Иверрон — молодой ночной эльф из Тенистой долины, который подошел слишком близко к враждебным паукам Паутинного леса и был сражен их смертоносным ядом.",al={"iverron","who is iverron","who poisoned","иверрон","кто такой иверрон","кто отравил"}},{q="Кто выдает задание «Противоядие для Иверрона»?",a="Задание выдает и лекарство готовит Дирания Серебряное Сияние, помощница, находящаяся у великих ветвей Альдрассила в Тенистой долине.",al={"quest giver","dirania","dirania silvershine","персонаж, выдающий задание","дирания","дирания серебряное сияние"}},{q="Почему для противоядия нужен паучий ихор?",a="В традиционных травяных средствах добавление компонента из жидкостей тела самого существа или его яда помогает нейтрализовать конкретные токсины, поразившие жертву.",al={"why spider ichor","webwood ichor use","spider venom cure","зачем паучий ихор","применение ихора паутинного леса","лекарство от яда паука"}},{q="Где найти гиацинтовые грибы?",a="Hyacinth mushrooms grow at the bases of large trees throughout Shadowglen and can also be pried from the clutches of grell who hoard them to the south.",al={"where to find hyacinth mushrooms","hyacinth mushroom location","где найти гиацинтовые грибы","где растут гиацинтовые грибы"}},{q="Где растут лунные лилии?",a="Лунные лилии цветут по краям тихих пресноводных прудов, спрятанных на северо-западной стороне Альдрассила.",al={"moonpetal lily location","where are lilies","где лунные лилии","где растут лилии"}},{q="Где обитают пауки Паутинного леса?",a="Пауки Паутинного леса обитают в северных лесах Тенистой долины, особенно возле темного входа в Паучье логово.",al={"webwood spider location","spider location shadowglen","где пауки паутинного леса","где пауки в тенистой долине"}}},fp="18,226,20.372.0,22.448.0,15.139.0,39.140.0,40.160.0,35.151.0,31.121.0,38.116.0"}
P.entries["quest:3522"] = {n="Противоядие для Иверрона",s="В этом поручении искателю приключений предстоит успеть доставить свежесваренное лекарство отравленному разведчику-ночному эльфу. Застрявший у кишащей пауками пещеры в Тенистой долине, Иверрон полностью зависит от травяного снадобья Дирании Серебряного Сияния, пока сильная смесь не утратила действие.",h="В этом поручении искателю приключений предстоит успеть доставить свежесваренное лекарство отравленному...",kw={"antidote","dirania silvershine","iverron","shadowglen","teldrassil","venom","webwood spider","противоядие","дирания серебряное сияние","иверрон","тенистая долина","тельдрассил","яд","паук паутинного леса"},ang={["profession:Herbalism"]="Неустойчивость отвара показывает, как трудно работать с сырой лесной флорой: растительные составы почти сразу теряют жизненные свойства без должного хранения.",["race:NightElf"]="Для молодых ночных эльфов, обучающихся в Тенистой долине, спасение Иверрона — отрезвляющее напоминание о растущей порче и агрессии среди местной фауны Тельдрассила."},sec={{t="Гонка со временем",b="Дирания Серебряное Сияние готовит целебный отвар из свежесобранных ядовитых мешочков, корней лилий и гиацинтовых грибов, но его неустойчивая алхимическая природа создает серьезный риск. Лекарство сохраняет силу лишь пять минут после перегонки. Тот, кто несет флакон, должен без колебаний бежать от поляны прямо к северным высотам."},{t="Привычка попадать в беду",b="Иверрон стал жертвой пауков Паутинного леса, обитающих у курганов и пещер Тенистой долины. По его собственному признанию, у него несчастливая склонность попадать в опасные места, и он часто полагается на знание трав Дирании, чтобы выбраться из переделок. Даже выпив противоядие, он еще слаб и опасается враждебных пауков, которые все еще стерегут его путь домой."}},faq={{q="Почему на доставку противоядия дается ограниченное время?",a="Противоядие, приготовленное Диранией Серебряным Сиянием, основано на сырых природных ингредиентах и свежем яде. Его целебные свойства быстро ослабевают после приготовления, и оно становится совершенно бесполезным, если его не принять в течение пяти минут после того, как оно покинуло ее руки.",al={"why five minutes","antidote timer","timed quest","почему пять минут","таймер противоядия","задание на время"}},{q="Где находится Иверрон?",a="Иверрон сидит, привалившись к скалам снаружи северной пещеры в Тенистой долине, к северу от главной тропы через рощу.",al={"where is iverron","iverron location","find iverron","где иверрон","расположение иверрона","найти иверрона"}},{q="Как был отравлен Иверрон?",a="Его поразили ядовитые пауки Паутинного леса, обитающие на северных окраинах Тенистой долины, — агрессивная порода, расплодившаяся среди корней и пещер Тельдрассила.",al={"who poisoned iverron","why is iverron sick","iverron poison","кто отравил иверрона","почему иверрон болен","яд иверрона"}},{q="Что происходит после того, как Иверрон выпивает противоядие?",a="Хотя яд нейтрализован, Иверрон остается слишком слабым и потрясенным, чтобы безопасно идти самому, и просит помочь расчистить ближайших пауков Паутинного леса, преграждающих ему путь в безопасное место.",al={"what next iverron","after iverron antidote","iverron follow up","что дальше иверрон","после противоядия иверрона","продолжение задания иверрона"}},{q="Какие отношения связывают Диранию и Иверрона?",a="Дирания Серебряное Сияние — умелая травница и целительница в Тенистой долине, которая часто выручает Иверрона из его злоключений. Иверрон открыто признает, что попадать в неприятности для него обычное дело и что Дирания постоянно вытаскивает его из них.",al={"dirania and iverron","who is dirania to iverron","are they friends","дирания и иверрон","кем дирания приходится иверрону","они друзья"}},{q="Что будет, если противоядие испортится, не дойдя до него?",a="Если непостоянное зелье испортится до доставки, задание выполнить нельзя. Вам придется вернуться к Дирании Серебряному Сиянию в Тенистую долину, получить свежую порцию и повторить путь.",al={"antidote expired","failed timer","lost antidote","противоядие испортилось","провал таймера","потеряно противоядие"}}},fp="18,291,24.353.0,18.413.0,53.242.0,25.128.0,25.178.0,47.205.1,46.248.0,57.174.0"}
P.entries["quest:3524"] = {n="Останки на берегу",s="Задание «Останки на берегу» — расследование, начатое Гвеннид Блай'Леггонд в Аубердине по поручению Храма Луны. Массовые случаи выбрасывания гигантских морских созданий на побережье Темных берегов встревожили жречество ночных эльфов в Дарнассе. Искателям приключений поручено отогнать мурлоков-падальщиков и добыть скелетные образцы для изучения.",h="Задание «Останки на берегу» — расследование, начатое Гвеннид Блай'Леггонд в Аубердине по поручению Храма Луны.",kw={"auberdine","darkshore","darnassus","greymist murlocs","gwennyth bly'leggonde","sea creature bones","temple of the moon","washed ashore","аубердин","темные берега","дарнасс","мурлоки серой мглы","гвеннид блай'леггонд","кости морского существа","храм луны","останки на берегу"},ang={["class:Druid"]="Массовая гибель благородных морских обитателей — тревожный признак экологического разлада на побережье Калимдора, требующий пристального внимания.",["class:Priest"]="Служение Сестринству Элуны означает толкование духовных знамений и природных нарушений равновесия — именно это Гвеннид стремится понять по останкам морского существа.",["race:NightElf"]="Выбросы на берег нарушают хрупкое равновесие Темных берегов, и Сестринство Элуны вмешивается напрямую из Дарнасса."},sec={{t="Тревожное предзнаменование",b="Гигантские величественные обитатели глубин давно известны тем, что порой выбрасываются на туманные отмели Темных берегов. Однако в последнее время их гибель перестала быть печальным исключением и превратилась в нарастающую закономерность. Туши выброшенных левиафанов появляются на побережье в тревожном количестве. Для жриц Элуны, живущих в Храме Луны, такие беспричинные массовые выбросы — не просто природная странность, а возможное дурное знамение, угрожающее северному Калимдору."},{t="Падальщики мелководья",b="Чтобы понять, почему эти огромные звери выбрасываются на песок, ученая Гвеннид Блай'Леггонд была отправлена в портовый городок Аубердин. Ее задача — собирать биологические образцы и отправлять их на гиппогрифе в Дарнасс для тщательного изучения. Однако мурлоки Серой Мглы, заполонившие прибрежную полосу, облепили огромные туши, жадно пожирая останки и не давая полевым исследователям добраться до костей без вооруженной охраны."}},faq={{q="Почему на Темные берега выбрасывает гигантских морских созданий?",a="Точная причина все еще расследуется Храмом Луны. Редкие выбросы естественны, но внезапный рост их числа убедил ученых-ночных эльфов, что под волнами Великого моря скрывается более глубокое возмущение или дурное знамение.",al={"why beached creatures","sea creature strandings","dying sea beasts","почему выбросило существ","выбросы морских существ","гибель морских зверей"}},{q="Кто такая Гвеннид Блай'Леггонд?",a="Гвеннид Блай'Леггонд — исследовательница, отправленная из Дарнасса Храмом Луны. Находясь в Аубердине, она отвечает за описание прибрежных аномалий и сбор образцов с выброшенных левиафанов, которые отсылаются жрецам для анализа.",al={"gwennyth","who is gwennyth bly'leggonde","гвеннид","кто такая гвеннид блай'леггонд"}},{q="Где лежит существо к югу от Аубердина?",a="Скелетные останки лежат на берегу, недалеко к югу от причалов Аубердина. Огромная туша находится в прибое, окруженная враждебными мурлоками Серой Мглы, которые ее охраняют.",al={"creature location","sea creature bones location","where is the beached beast","где существо","где кости морского существа","где выброшенный зверь"}},{q="Что Дарнасс будет делать с костями морского существа?",a="Кости отправляют на гиппогрифе прямо в Дарнасс. Ученые и жрицы Храма Луны изучают костный мозг, строение и признаки разложения, чтобы выяснить, что выбросило зверя на берег: болезнь, скверная магия или противоестественный хищник.",al={"why collect bones","purpose of sea creature bones","darnassus bones","зачем собирать кости","назначение костей морского существа","кости дарнасс"}},{q="Почему мурлоки Серой Мглы собрались вокруг туши?",a="Племя Серой Мглы использует выброшенных гигантов как легкий источник пищи, орудий и поделок из кости. Заявив права на туши, мурлоки делают невозможным приближение безоружных ученых без риска для жизни.",al={"murlocs at whale","why murlocs around creature","мурлоки у кита","почему мурлоки вокруг существа"}},{q="Закончится ли это расследование после получения первых костей?",a="Нет. Туша к югу от города — лишь первое место. Гвеннид продолжает исследования, изучая других выброшенных левиафанов, погибших на обширном, окутанном туманом побережье Темных берегов.",al={"is this a chain","washed ashore follow up","это цепочка","продолжение останков на берегу"}}},fp="13,351,17.499.0,26.464.0,52.261.0,29.264.0,47.181.0,51.248.0,57.227.0,73.208.0"}
P.entries["quest:353"] = {n="Посылка для Грозовой Вершины",s="После работы в Квартале Дворфов кузнец Гриманд Элмор поручает путникам доставить только что откованный топор горному пехотинцу Гринджеру Грозовая Вершина. Для доставки посылки нужно отправиться на север через горы к стальгорнскому форпосту в Лок Модане.",h="После работы в Квартале Дворфов кузнец Гриманд Элмор поручает путникам доставить только что откованный топор...",kw={"axe","elmore","grimand","gringer","guard tower","loch modan","mountaineer","stormpike","топор","элмор","гриманд","гринджер","сторожевая башня","лок модан","горный пехотинец","грозовая вершина"},ang={["faction:Alliance"]="Доставка военных грузов между Штормградом и горными форпостами показывает практическое единство людей и дворфов.",["profession:Blacksmithing"]="Работа Гриманда Элмора — образец тонкой дворфийской металлургии, столь ценной, что горные стражи заказывают изделия через целые королевства.",["race:Dwarf"]="Грозовые Вершины пользуются большим почетом среди дворфов, и помощь брату-горцу на диком пограничье Лок Модана укрепляет узы клана."},sec={{t="Оружие для севера",b="Грозовые Вершины — один из самых уважаемых кланов Стальгорна, известный взыскательным вкусом и воинской гордостью. Когда горному пехотинцу Гринджеру Грозовая Вершина понадобилось новое оружие для дозорной службы, он обратился к прославленному кузнецу Гриманду Элмору из Квартала Дворфов Штормграда. Закончив топор, Элмор поручает посылку надежным путникам, чтобы она преодолела расстояние между столицей людей и пограничьем дворфов."},{t="На страже Лок Модана",b="Горный пехотинец Грозовая Вершина несет службу у северной сторожевой башни в Лок Модане и следит за землями, которым досаждают бродячие трогги и роющие норы кобольды. Пока слухи о беспорядках и разбое тревожат южные человеческие королевства, дворфийское пограничье сталкивается с собственными упорными угрозами. Свежезакаленный клинок дает Грозовой Вершине преимущество, нужное, чтобы удерживать горные перевалы."}},faq={{q="Кто такой горный пехотинец Грозовая Вершина?",a="Гринджер Грозовая Вершина — горный пехотинец Стальгорна из уважаемого клана Грозовой Вершины. Сейчас он несет службу у северной сторожевой башни в Лок Модане и защищает дорогу в долине от набегов троггов и других местных угроз.",al={"gringer stormpike","who is stormpike","mountaineer gringer stormpike","гринджер грозовая вершина","кто такой грозовая вершина","горный пехотинец гринджер грозовая вершина"}},{q="Что лежит в посылке?",a="В посылке лежит топор дворфийской работы, откованный на заказ Гримандом Элмором в Штормграде. Горный пехотинец Грозовая Вершина заказал клинок для борьбы с троггами и кобольдами, вторгающимися в Лок Модан.",al={"what am i delivering","stormpike parcel contents","grimand elmore weapon","что я доставляю","содержимое посылки грозовой вершины","оружие гриманда элмора"}},{q="Куда доставить посылку?",a="Горный пехотинец Грозовая Вершина несет службу у северной сторожевой башни в Лок Модане, у дороги, ведущей через холмы к северным горным границам.",al={"where is stormpike","how to find mountaineer stormpike","loch modan guard tower location","где грозовая вершина","как найти горного пехотинца грозовую вершину","где сторожевая башня лок модана"}},{q="Почему дворф из Лок Модана покупает оружие в Штормграде?",a="Гриманд Элмор — очень искусный дворф-оружейник из Квартала Дворфов Штормграда. Клан Грозовой Вершины ценит тонкую металлургию, и Гринджер заказал свой особый топор именно Элмору, несмотря на расстояние.",al={"why buy from stormwind","why elmore","dwarf ordering from human city","почему покупать в штормграде","почему элмор","дворф заказывает в городе людей"}},{q="Как это связано с заданием «Просьба Элмора»?",a="Эта доставка непосредственно продолжает задание «Просьба Элмора» и является следующей услугой, о которой Гриманд Элмор просит искателей приключений, готовых путешествовать между землями Альянса — Штормградом и Каз Моданом.",al={"elmore questline","quest before stormpikes delivery","how to start this quest","цепочка элмора","задание перед посылкой для грозовой вершины","как начать это задание"}},{q="Как добраться из Штормграда до Лок Модана?",a="Путники обычно садятся на Подземный поезд в Квартале Дворфов Штормграда, чтобы добраться до Стальгорна. От Великих врат Стальгорна восточная дорога спускается через заснеженные перевалы Дун Морога и проходит через Северные врата в долину Лок Модана.",al={"how to get to loch modan","travel to khaz modan","deeprun tram to loch modan","как добраться до лок модана","путь в каз модан","подземный поезд до лок модана"}}},fp="20,253,22.430.0,22.378.0,29.235.0,27.200.0,31.159.0,58.232.0,39.181.0,49.269.0"}
P.entries["quest:354"] = {n="Смерти в семье",s="Колман Фартинг, бывший работник мельницы, ныне живущий в Брилле, жаждет личной мести аристократической семье Агамондов. Убежденные остаться и защищать свои владения от Плети во время Третьей войны, Фартинг и его товарищи погибли вместе со своими упрямыми хозяевами, а Агамонды восстали бездумными рабами Короля-лича.",h="Колман Фартинг, бывший работник мельницы, ныне живущий в Брилле, жаждет личной мести аристократической семье...",kw={"agamand","agamand mills","brill","coleman farthing","deaths in the family","gregor agamand","nissa agamand","scourge","thurman agamand","tirisfal glades","агамонд","мельницы агамондов","брилл","колман фартинг","смерти в семье","грегор агамонд","нисса агамонд","плеть","турман агамонд","тирисфальские леса"},ang={["faction:Horde"]="Уничтожение верхушки Агамондов устраняет опасных командиров Плети, скрывающихся неприятно близко к Бриллу и северным подступам к Подгороду.",["race:Undead"]="Это задание отражает глубокие личные обиды, которые многие Отрекшиеся до сих пор носят из своей прежней жизни, и показывает сохраняющуюся травму падения Лордерона и горечь к тем, кто довел их до гибели."},sec={{t="Наследие гордыни",b="До того как Третья война опустошила Лордерон, семья Агамондов была самой богатой и влиятельной землевладельческой династией в Тирисфальских лесах. Их обширные мельницы и плодородные пастбища давали обильный урожай зерна, а на них трудились десятки арендаторов-земледельцев и мельников. Когда Чума нежизни поползла по королевству, Агамонды отказались бежать и покидать родовые владения, уверенные, что каменные стены и верные работники сдержат ужасы, наступающие с востока."},{t="Цена верности",b="Поверив заверениям своих господ, верные работники, подобно Колману Фартингу, остались защищать поместье. Оборона оказалась тщетной перед неумолимым натиском Плети. Агамонды и их работники были перебиты, а их тела гнили там, где упали, пока их не подняли в нежизнь. Фартинг в итоге освободился благодаря Сильване Ветрокрылой, но главы рода и наследники Агамонды остались в плену разума под властью Короля-лича и бродили по разрушенным мельницам как бездумные стражи Плети."},{t="Горькое возмездие",b="Теперь Колман Фартинг живет в Брилле и питает жгучую злобу к бывшим господам, чья надменность стоила ему человеческой жизни. Ища завершения и возмездия, он посылает бойцов Отрекшихся на Мельницы Агамондов, чтобы уничтожить Грегора, Ниссу и Турмана Агамондов. Фартинг открыто надеется, что за гниющими лицами его бывшие господа сохранили достаточно сознания, чтобы почувствовать ужас, когда их нежизнь будет насильственно прервана."}},faq={{q="Кто такие Агамонды?",a="Агамонды были самой богатой и процветающей семьей землевладельцев в Тирисфальских лесах до падения Лордерона. Они владели обширными Мельницами Агамондов и управляли ими, нанимая множество местных земледельцев и мельников.",al={"who are the agamands","agamand backstory","agamand mills history","кто такие агамонды","история агамондов","история мельниц агамондов"}},{q="Почему Колман Фартинг так зол на них?",a="При жизни Фартинг работал на их мельницах. Когда пришла Плеть, Агамонды убедили работников остаться и укреплять поместье, а не бежать. Фартинг считает их аристократическую гордыню прямой причиной того, что он и его товарищи погибли и стали нежитью.",al={"coleman farthing grudge","why does farthing hate the agamands","farthing motive","обида колмана фартинга","почему фартинг ненавидит агамондов","мотив фартинга"}},{q="Присоединились ли Агамонды к Отрекшимся?",a="Нет. В отличие от Колмана Фартинга и других Отрекшихся, обладающих свободной волей, Агамонды так и не освободились от власти Короля-лича. Они остаются бездумными приспешниками Плети, обитающими на разрушенных семейных мельницах.",al={"are agamands forsaken","why are the agamands scourge","who controls the agamands","агамонды отрекшиеся","почему агамонды в плети","кто управляет агамондами"}},{q="Каких членов семьи Агамондов нужно уничтожить?",a="В задании вам поручено выследить Грегора Агамонда, Ниссу Агамонд и Турмана Агамонда и собрать их останки в семейном поместье в подтверждение их уничтожения.",al={"who do you kill","agamand targets","which agamands","кого убить","цели агамонды","какие агамонды"}},{q="Где находятся Мельницы Агамондов?",a="Мельницы Агамондов находятся на севере Тирисфальских лесов, к северо-западу от Брилла. Некогда плодородное поместье состоит из нескольких разрушенных ветряных мельниц и домов, кишащих Плетью.",al={"where is agamand mills","agamand location","где мельницы агамондов","расположение агамондов"}},{q="Что Колман Фартинг делает с их останками?",a="Колман просит их останки лишь для подтверждения уничтожения. Трофей означает завершение его земных обид и доказательство того, что гордые господа, погубившие его, окончательно уничтожены.",al={"why collect remains","farthing remains","зачем собирать останки","останки фартинг"}}},fp="20,357,17.490.0,20.524.0,18.434.0,27.213.0,41.261.0,35.194.0,47.167.0,32.181.0,49.205.0"}
P.entries["quest:355"] = {n="Разговор с Севреном",s="После того как Колман Фартинг свел личные счеты на Мельницах Агамондов, мировой судья Севрен вызывает героя в Брилл. На мельницах скрывается не только горький призрак семьи: это действующая угроза Плети на северной границе поселения.",h="После того как Колман Фартинг свел личные счеты на Мельницах Агамондов, мировой судья Севрен вызывает героя в...",kw={"agamand mills","brill","coleman farthing","magistrate sevren","sevren","the family crypt","the haunted mills","tirisfal glades","мельницы агамондов","брилл","колман фартинг","мировой судья севрен","севрен","семейная усыпальница","населенные призраками мельницы","тирисфальские леса"},ang={["faction:Horde"]="Брилл — первая линия обороны Подгорода; защита окрестных земель от Плети жизненно важна для влияния Орды на севере Лордерона.",["race:Undead"]="Успех против безмозглой Плети приносит быстрое признание в Брилле: вы переходите от разовых подработок к прямой гражданской обороне под началом мирового судьи Севрена."},sec={{t="От мести к гражданскому долгу",b="Колман Фартинг искал личной мести бывшим соседям, Агамондам, и отправил путников на север перебить нежить, бродящую у мукомольных мельниц. Когда останки были доставлены, Колман понял, что его личная обида связана с более широкой тактической проблемой: все поместье Агамондов по-прежнему кишит безрассудно агрессивными приспешниками Плети прямо у порога Брилла."},{t="Призыв мирового судьи",b="Мировой судья Севрен отвечает за гражданскую и военную безопасность Брилла от имени Темной Госпожи. Узнав о герое, способном выжить в глубоких вылазках на населенные призраками фермерские земли, Севрен решает направить эти умелые руки к корню заразы — древней семейной усыпальнице Агамондов."}},faq={{q="Почему Колман Фартинг посылает меня к мировому судье Севрену?",a="Колман утолил собственную жажду мести воскресшему семейству Агамондов, но знает, что нежить на мельницах угрожает всему Бриллу. Он рассказал о вашем боевом мастерстве мировому судье Севрену, который организует местную оборону.",al={"why go to sevren","coleman farthing referral","who is magistrate sevren","зачем идти к севрену","колман фартинг направление","кто такой мировой судья севрен"}},{q="Где найти мирового судью Севрена?",a="Мировой судья Севрен находится в Брилле, в Тирисфальских лесах. Обычно его можно найти у здания ратуши: он руководит местными делами Отрекшихся.",al={"sevren location","where is magistrate sevren","find sevren","местонахождение севрена","где мировой судья севрен","найти севрена"}},{q="Какую угрозу представляют Мельницы Агамондов?",a="Мельницы лежат к северу от Брилла и по-прежнему кишат безмозглой Плетью. Если не вмешаться, ходячие мертвецы и неупокоенные духи, бродящие по полям, легко могут захватить город.",al={"agamand mills danger","why are mills a threat","опасность мельниц агамондов","чем опасны мельницы"}},{q="Что происходит после разговора с мировым судьей Севреном?",a="Севрен посылает вас в прямой рейд в Семейную усыпальницу Агамондов, чтобы уничтожить более глубокую угрозу Плети, привязывающую нежить к мельницам.",al={"next quest after sevren","what does sevren want","следующее задание после севрена","что нужно севрену"}},{q="Нужно ли в этом задании сразу возвращаться на мельницы?",a="Это короткое поручение — лишь переходное звено. Вы докладываете Севрену в Брилле, чтобы завершить дело Колмана, прежде чем принять следующее задание в усыпальнице.",al={"do i go back to the mills","is this quest just talking","возвращаться ли на мельницы","это задание только разговор"}},{q="Почему Брилл заботит семья Агамондов?",a="При жизни Агамонды были богатыми владельцами мельниц в округе и видными соседями в Тирисфале. После смерти их оскверненное поместье служит укрепленным плацдармом для безмозглой Плети.",al={"agamand importance","who are the agamands to brill","значение агамондов","кто такие агамонды для брилла"}}},fp="17,256,28.404.0,21.309.0,55.228.0,37.144.0,38.191.0,51.142.0,59.149.0,45.185.0"}
P.entries["quest:356"] = {n="Патруль в арьергарде",s="Патруль в арьергарде — военное разведывательное задание, которое дает страж смерти Линнея, чтобы защитить оборону Отрекшихся на восточной границе Тирисфаля. Бойцам поручено уничтожить заблудших порождений Плети и неупокоенных духов, преследующих Ферму Балнира, пока они не нарушили линии снабжения Бастиона.",h="Патруль в арьергарде — военное разведывательное задание, которое дает страж смерти Линнея, чтобы защитить...",kw={"balnir","bleeding horror","bulwark","linnea","scourge","tirisfal","wandering spirit","zygand","балнир","кровоточащий ужас","бастион","линнея","плеть","тирисфаль","блуждающий дух","зуганд"},ang={["faction:Horde"]="Удержание восточного рубежа Тирисфаля позволяет Орде сохранять свой шаткий плацдарм на севере Восточных королевств против легионов нежити.",["race:Undead"]="Для Отрекшихся защита тыла Бастиона — вопрос выживания; сломив присутствие Плети на Ферме Балнира, они не дают Королю-личу вновь протянуть руку к их родным землям."},sec={{t="Защита фланга Бастиона",b="Бастион — главный оплот, сдерживающий чуму и армии Западных Чумных земель от вторжения в Тирисфальские леса. Страж смерти Линнея отвечает за безопасность тыла на этом рубеже. Поскольку линия не может позволить себе делить силы из-за засад с тыла, любая нежить, прорвавшаяся мимо заслона, должна быть уничтожена, пока не перерезала линии снабжения фронта."},{t="Руины Фермы Балнира",b="Ферма Балнира, некогда известная по всему Лордерону разведением призовых королевских скакунов, пала в руины во время Третьей войны. Теперь, полностью зараженные, заросшие поля и рушащиеся конюшни служат укрытием для проникших Кровоточащих ужасов и неупокоенных Блуждающих духов. Очистка места лишает Короля-лича плацдарма в самом Тирисфале и защищает дорогу для подкреплений Орды."}},faq={{q="Почему этот патруль важен для Бастиона?",a="Бастион удерживает узкий пограничный проход против Западных Чумных земель. Если блуждающая Плеть обойдет укрепление с фланга или обоснуется за ним, защитники окажутся в бою на два фронта и потеряют линии снабжения, связывающие их с Бриллом и Подгородом.",al={"why do rear guard patrol","bulwark importance","why secure balnir","зачем патруль в арьергарде","важность бастиона","зачем защищать ферму балнира"}},{q="Кто дает это задание?",a="Страж смерти Линнея, офицер, стоящий у дороги, ведущей на восток в Чумные земли, назначает патруль и передает отчеты об успехе палачу Зуганду.",al={"who gives rear guard patrol","deathguard linnea","кто дает патруль в арьергарде","страж смерти линнея"}},{q="Какие существа обитают на Ферме Балнира?",a="Зараженная ферма кишит Кровоточащими ужасами — оживленными трупами, сшитыми некромантией, — и Блуждающими духами бывших жителей, погибших при первом натиске Плети.",al={"balnir farmstead mobs","what monsters are at balnir","bleeding horror","монстры фермы балнира","какие монстры у балнира","кровоточащий ужас"}},{q="Чем была Ферма Балнира до чумы?",a="До Третьей войны семья Балнир разводила призовых лошадей, известных по всему Королевству Лордерон, в том числе благородных скакунов, которых предпочитали лордеронские короли и рыцари.",al={"balnir lore","what was balnir farmstead","balnir history","предания о балнире","чем была ферма балнира","история балнира"}},{q="Кто такой палач Зуганд?",a="Палач Зуганд — старший командир Стражей смерти Отрекшихся в Брилле и начальник стража смерти Линнеи.",al={"executor zygand lore","who is zygand","палач зуганд предания","кто такой зуганд"}},{q="Почему Отрекшиеся просто не оставят восточную границу?",a="Оставив Бастион, Отрекшиеся откроют все Тирисфальские леса и врата Подгорода бесчисленным ордам Плети, идущим из Чумных земель.",al={"why defend the bulwark","why fight at the border","зачем защищать бастион","зачем сражаться на границе"}}},fp="17,315,28.410.0,29.392.0,45.261.0,24.159.0,42.198.0,48.176.0,23.111.0,55.164.0"}
P.entries["quest:357"] = {n="Личность лича",s="Личность лича — задание Подгорода, которое дает Бетор Ледострел в Магическом квартале. Желая узнать личность отшельника-лича с Озера Ясноводного, Бетор посылает порученца выкрасть его книгу заклинаний, чтобы оценить его силу и верность.",h="Личность лича — задание Подгорода, которое дает Бетор Ледострел в Магическом квартале.",kw={"bethor iceshard","brightwater lake","forsaken","magic quarter","necromancer","sylvanas","the lich's spellbook","undercity","бетор ледострел","озеро ясноводное","отрекшиеся","магический квартал","некромант","сильвана","книга заклинаний лича","подгород"},ang={["class:Mage"]="Маги, посещающие Бетора Ледострела в Магическом квартале, видят, как уцелевшие остатки магических традиций Лордерона и Даларана превращены в орудия выживания Отрекшихся.",["faction:Horde"]="Вербовка могущественных некромантов укрепляет северный рубеж Орды против неустанных атак Алого ордена и Плети.",["race:Undead"]="Для Отрекшихся возвращение независимой нежити доказывает, что освобождение от Короля-лича не было единичным чудом, и вместе с тем дает двору Сильваны жизненно важную некромантскую силу."},sec={{t="Отшельник на озере",b="К северу от Подгорода, в туманных водах Озера Ясноводного, на небольшом острове в добровольном изгнании живет одинокий лич. В отличие от безвольных пешек Короля-лича, этот некромант обладает собственной волей, но живет в глубокой паранойе. Убежденный, что любая нежить, приближающаяся к нему, — рабы Плети, посланные вернуть его в услужение, он натравливает призванных приспешников на всякого, кто ступит на его берег."},{t="Ценное приобретение",b="Слух о свободном личе в конце концов дошел до Бетора Ледострела, верховного мага, надзирающего за магами Подгорода. Бетор понял стратегическую важность такого существа: леди Сильвана Ветрокрылая ищет любую крупицу магического мастерства и любую способную волю, чтобы укрепить Отрекшихся против многочисленных врагов. Чтобы оценить, можно ли привлечь отшельника, Бетор требует доказательств его личности и некромантского мастерства."},{t="Найденный старый друг",b="После того как украденная книга заклинаний доставлена в Магический квартал, Бетор изучает ее тайнопись и узнает истинную личность лича: Гюнтер Чародей. При жизни Гюнтер был талантливым некромантом и близким соратником Бетора, пока чума не опустошила Лордерон. Это подтверждает, что Гюнтер не только независимая душа, но и старый союзник, чья возросшая некромантская сила могла бы принести большую пользу владениям Темной Госпожи."}},faq={{q="Кто посылает вас на это задание?",a="Задание дает Бетор Ледострел, могущественный маг Отрекшихся высокого ранга, находящийся в Магическом квартале Подгорода.",al={"quest giver","bethor iceshard location","who gives the lichs identity","персонаж, выдающий задание","где бетор ледострел","кто дает личность лича"}},{q="Почему лич нападает на всех, кто приближается к нему?",a="Лич по собственной воле освободился от власти Короля-лича, но ошибочно полагает, что вся остальная нежить в Лордероне по-прежнему остается порабощенными рабами Плети. Поэтому он приказывает приспешникам нападать на всех, кто приближается к его острову, защищая свою свободу.",al={"why is gunther hostile","why does the lich attack","brightwater lich hostile","почему гюнтер враждебен","почему лич нападает","враждебный лич ясноводного"}},{q="Где находится лагерь лича?",a="Он живет на острове посреди Озера Ясноводного, расположенного в Тирисфальских лесах прямо к северу от Руин Лордерона и Подгорода.",al={"where is the lich","brightwater lake island","gunther arcanus location","где лич","остров озера ясноводного","где гюнтер чародей"}},{q="Почему леди Сильвана хочет привлечь его к Отрекшимся?",a="Независимая нежить с высоким магическим талантом исключительно редка. Свободный некромант, способный владеть мощной магией смерти, дал бы Отрекшимся важную силу против Плети и Алого ордена.",al={"why recruit the lich","forsaken interest in gunther","sylvanas lich","зачем вербовать лича","интерес отрекшихся к гюнтеру","сильвана лич"}},{q="Кем оказывается лич?",a="Бетор сообщает, что лич — это Гюнтер Чародей, бывший маг Даларана и искусный некромант, близкий соратник Бетора по оружию до Третьей войны.",al={"lich identity","who is the lich","identity of the lich","личность лича","кто такой лич","кто этот лич"}},{q="Что происходит после доставки книги заклинаний?",a="Когда Бетор подтверждает личность Гюнтера, он отправляет вас обратно к Озеру Ясноводному с книгой заклинаний, чтобы убедить Гюнтера, что Отрекшиеся действительно свободны и хотят принять его.",al={"what next","return the book quest","after the lichs identity","что дальше","задание вернуть книгу","после личности лича"}}},fp="19,260,21.418.0,16.420.0,19.434.1,30.125.0,51.261.0,33.139.0,58.221.0,33.156.1,45.175.1"}
P.entries["quest:358"] = {n="Грабители могил",s="Мировой судья Севрен из Брилла поручает героям истребить гноллов-Гнилошкуров на Братской могиле к юго-западу от Фермы Гаррена. Этих нежитей-зверей Плеть послала разрывать трупы первых жертв чумы, чтобы пополнить свои ряды. Их уничтожение и добыча бальзамирующей лимфы защищает павших и помогает исследованиям Королевского фармацевтического общества.",h="Мировой судья Севрен из Брилла поручает героям истребить гноллов-Гнилошкуров на Братской могиле к юго-западу...",kw={"brill","embalming ichor","garren's haunt","graverobbers","magistrate sevren","mass grave","rot hide","tirisfal glades","брилл","бальзамирующая лимфа","ферма гаррена","грабители могил","мировой судья севрен","братская могила","гнилошкуры","тирисфальские леса"},ang={["faction:Horde"]="Пресечение усилий Плети по пополнению сил обеспечивает безопасность северного Лордерона и укрепляет позиции Орды против остатков сил Короля-лича.",["race:Undead"]="Для Отрекшихся недопущение того, чтобы Плеть поднимала бывших жителей Тирисфаля, избавляет павших соотечественников от ужасной участи безмозглого рабства."},sec={{t="Осквернение братских могил",b="Когда Чума нежизни впервые прокатилась по Тирисфальским лесам, мертвых становилось больше, чем можно было предать погребению по обряду. По всему северу вырыли огромные братские могилы, чтобы вместить чудовищные потери. До недавнего времени погребенные там останки избегали воскрешения. Теперь же Плеть напустила гноллов-Гнилошкуров на рвы к юго-западу от Фермы Гаррена, веля им выкапывать истлевшие останки для усиления армий Короля-лича."},{t="Алхимия Плети обращается против нее",b="Гнилошкуры живут благодаря бальзамирующей лимфе — алхимическому составу, сохраняющему и оживляющему их гниющие тела. Приказывая разведчикам убивать грабителей могил и добывать эту жидкость, мировой судья Севрен наносит сразу два удара: останавливает сбор Плетью свежих тел и доставляет ценные биологические образцы аптекарям в Брилле, желающим обратить искусство Короля-лича против него самого."}},faq={{q="Зачем Плеть раскапывает Братскую могилу?",a="В Братской могиле лежат бесчисленные жертвы первого прихода Чумы в Тирисфаль. Плеть намерена извлечь эти сохранившиеся тела, чтобы поднять новых солдат и пополнить свои армии против Отрекшихся.",al={"why are gnolls digging corpses","what does the scourge want with bodies","mass grave purpose","зачем гноллы выкапывают трупы","что плети нужно от тел","цель братской могилы"}},{q="Кто такие гноллы-Гнилошкуры?",a="Это гноллы-нежить, порабощенные Плетью. Оживленные и сохраняемые с помощью алхимической бальзамирующей лимфы, они служат падальщиками и ударными отрядами вокруг Фермы Гаррена и соседних могил.",al={"rot hide lore","undead gnolls tirisfal","what are rot hides","предания о гнилошкурах","гноллы-нежить тирисфаль","кто такие гнилошкуры"}},{q="Где находится Братская могила?",a="Братская могила лежит к юго-западу от Фермы Гаррена, в северных холмах Тирисфальских лесов, чуть севернее Брилла.",al={"where are graverobbers","mass grave location","garren's haunt mass grave","где грабители могил","местонахождение братской могилы","братская могила у фермы гаррена"}},{q="Зачем Отрекшимся бальзамирующая лимфа?",a="Мировой судья Севрен передает собранную лимфу аптекарям Отрекшихся, чтобы изучить, как Плеть оживляет и поддерживает своих младших рабов, и найти слабости, которыми можно воспользоваться в идущей войне.",al={"why collect embalming ichor","what is ichor for","ichor lore","зачем собирать бальзамирующую лимфу","для чего лимфа","предания о лимфе"}},{q="Кто приказывает убивать Грабителей могил?",a="Мировой судья Севрен, управитель Брилла от лица Отрекшихся, назначает награду, чтобы защитить границы Тирисфаля и добыть полезные реагенты для аптекарей.",al={"who gives graverobbers","magistrate sevren role","кто дает задание грабители могил","роль мирового судьи севрена"}},{q="Почему Отрекшихся волнует, что погибших от чумы поднимают?",a="Каждый труп, захваченный и поднятый Плетью, становится вражеским солдатом, идущим по воле Короля-лича, и напрямую угрожает недавно освобожденному королевству Отрекшихся.",al={"why do forsaken protect graves","why care about dead bodies","зачем отрекшиеся защищают могилы","зачем заботиться о мертвых телах"}}},fp="12,355,30.448.0,30.421.0,45.211.0,29.196.0,32.111.0,51.197.0,41.146.0,59.167.0"}
P.entries["quest:36"] = {n="Похлебка Западного Края",s="Похлебка Западного Края начинается как соседский обмен между бегущими поселенцами и теми немногими фермерами, что еще держатся на своей земле. Семья Верны Хмуробров вынуждена покинуть свои владения из-за разгула бандитизма, и перед отъездом Верна передает Сальме Сальден свой любимый местный рецепт.",h="Похлебка Западного Края начинается как соседский обмен между бегущими поселенцами и теми немногими фермерами...",kw={"cooking","farmer furlbrow","recipe","saldean's farm","salma saldean","stew","verna furlbrow","westfall","кулинария","фермер хмуробров","рецепт","ферма сальдена","сальма сальден","похлебка","верна хмуробров","западный край"},ang={["profession:Cooking"]="Это блюдо — образец походной кухни людей-поселенцев, превращающей добытую в степи дичь и неприхотливые корнеплоды в сытную еду.",["race:Human"]="Это поручение отражает упадок пограничья королевства Штормград, где простых сельских жителей постепенно изгоняют с родовых ферм в городское изгнание."},sec={{t="Переданный рецепт",b="Отъезд Хмуробровов показывает, как стремительно рушится жизнь в сельской местности Западного Края. Изгнанные с семейной земли ворами из Братства Справедливости и взбесившимися механическими жатками, Верна и Фермер Хмуробров грузят повозку, чтобы найти убежище за стенами Штормграда. Не желая, чтобы ее домашняя традиция исчезла вместе с фермой, Верна доверяет свой фирменный рецепт похлебки Западного Края соседке — Сальме Сальден."},{t="Солидарность поселенцев",b="Сальма Сальден все еще держится за свою усадьбу неподалеку, упорно не сдаваясь вместе с мужем, Фермером Сальденом. Получить рецепт Верны — горько-радостный миг: это означает потерю еще одного соседа из-за растущих беспорядков, но и сохраняет основу местной фермерской жизни. Получив инструкции, Сальма отправляется собирать простые ингредиенты, чтобы накормить тех, кто еще борется за выживание на границе."}},faq={{q="Почему Хмуробровы покидают свою ферму?",a="Воры и бандиты заполонили их поля, и работать на земле стало слишком опасно. Верна и Фермер Хмуробров чинят повозку, чтобы бежать в безопасный Штормград.",al={"why furlough leaving","furlbrows leaving westfall","why verna packing","почему хмуробровы уезжают","хмуробровы покидают западный край","почему верна собирает вещи"}},{q="Кто такая Сальма Сальден?",a="Сальма Сальден — поселенка из Западного Края, живущая на Ферме Сальдена, сразу за развилкой дороги от усадьбы Хмуробровов. Она с семьей продолжает обрабатывать землю, несмотря на царящее вокруг беззаконие.",al={"who is salma","salma saldean lore","кто такая сальма","сальма сальден предыстория"}},{q="Что такое похлебка Западного Края?",a="Это традиционное сытное местное блюдо из местных ингредиентов, которые растут на равнинах Западного Края; его издавна готовили в фермерских семьях.",al={"what is westfall stew","westfall stew recipe","что такое похлебка западного края","рецепт похлебки западного края"}},{q="Куда собираются отправиться Хмуробровы?",a="Они направляются на север, в безопасный Штормград, где, по мнению друзей Верны, ей самое место.",al={"where furlbrows going","furlbrow destination","куда едут хмуробровы","цель хмуробровов"}},{q="Где находится Ферма Сальдена?",a="Ферма Сальдена лежит сразу за развилкой главной дороги, к югу от тыквенного поля Хмуробровов в Западном Крае.",al={"saldean farm location","where is salma saldean","расположение фермы сальдена","где сальма сальден"}},{q="Дается ли за это задание сам рецепт?",a="Доставка письменных инструкций Сальме Сальден — лишь первый шаг. Чтобы приготовить блюдо, Сальма попросит помочь добыть простые ингредиенты для котла.",al={"recipe reward","do i get westfall stew recipe","награда рецепт","получу ли я рецепт похлебки западного края"}}},fp="13,281,18.429.0,20.436.0,41.185.0,21.209.0,22.153.0,39.112.0,32.116.0,49.182.0"}
P.entries["quest:360"] = {n="Возвращение к чиновнику",s="Возвращение к чиновнику завершает срочное разведывательное донесение между восточной границей Тирисфальских лесов и городком Брилл. Доложив Стражу смерти Линнее на ее заставе к востоку от Брилла, герои возвращаются, чтобы лично передать тревожные вести Мировому судье Севрену. В донесении подтверждается, что безмозглые слуги Короля-лича по-прежнему испытывают на прочность границы молодого государства Отрекшихся.",h="Возвращение к чиновнику завершает срочное разведывательное донесение между восточной границей Тирисфальских...",kw={"brill","bulwark","forsaken duties","linnea","scourge","sevren","tirisfal","брилл","бастион","долг отрекшихся","линнея","плеть","севрен","тирисфаль"},ang={["faction:Horde"]="Опора Орды в Восточных королевствах зависит от стабильности Тирисфальских лесов, поэтому оборона Бастиона крайне важна против ужасов нежити из Чумных земель.",["race:Undead"]="Доставка донесений из Бастиона напоминает о шаткости свободы Отрекшихся: хозяин, от которого вы сбежали, все еще скребется у порога вашего нового дома."},sec={{t="Донесения с границы",b="Восточная дорога из Тирисфальских лесов ведет прямо в разоренные руины Западных Чумных земель, где безраздельно властвует Плеть. Чтобы не дать полчищам нежити хлынуть в только что занятую родину, Отрекшиеся создали Бастион — укрепленный контрольный пункт, за которым наблюдают с заставы в тылу суровые часовые вроде Стража смерти Линнеи. Собрав донесения о том, что давит на восточные ворота, Линнея отправляет гонцов обратно на запад по Королевской дороге к Бриллу, пока вражеские лазутчики не воспользовались брешами."},{t="Клятва Севрена",b="Когда Мировой судья Севрен получает донесение в Брилле, оно подтверждает его худшие опасения: разведчики Плети находят пути в обход линии обороны или сквозь нее. Для Отрекшихся каждый ползущий упырь и безмозглый скелет — не просто военная помеха, но напоминание о рабстве, от которого они освободились во время падения Лордерона. Севрен непреклонен: как бы неослабно ни было наступление Короля-лича, свободная нежить никогда не отдаст обретенную независимость."}},faq={{q="Откуда это донесение?",a="Донесение исходит от Стража смерти Линнеи, расположившейся на заставе Стражей смерти к востоку от Брилла, на дороге к Бастиону. Она собирает донесения с заграждений, отделяющих Тирисфаль от наводненных Плетью Западных Чумных земель.",al={"quest origin","who sent this report","where is linnea","источник задания","кто прислал донесение","где линнея"}},{q="Почему Мирового судью Севрена тревожат эти вести?",a="В донесении сообщается Севрену, что силам Плети удалось проскользнуть мимо укреплений Бастиона. Для Отрекшихся в Брилле вторжения врага угрожают их юным поселениям и постоянно напоминают о попытках Короля-лича вернуть их себе.",al={"why is sevren worried","what does the report say","scourge threat","почему севрен встревожен","что говорится в донесении","угроза плети"}},{q="Кто такой Мировой судья Севрен?",a="Мировой судья Севрен — гражданский управитель Брилла. Из здания ратуши он руководит местной обороной, хозяйством и мобилизацией недавно восставших Отрекшихся в центральной части Тирисфальских лесов.",al={"sevren lore","who is the magistrate","севрен предыстория","кто такой судья"}},{q="Что такое Бастион?",a="Бастион — укрепленный форпост на главной дороге между Тирисфальскими лесами и Западными Чумными землями. Это главный заслон, не пускающий Плеть на земли Отрекшихся.",al={"bulwark lore","eastern border tirisfal","бастион предыстория","восточная граница тирисфаля"}},{q="Почему Отрекшиеся так сильно ненавидят Плеть?",a="Отрекшиеся были безмозглыми рабами Плети: убитые при жизни, они восстали в нежизни, чтобы убивать собственных сородичей. Обретя свободную волю, они презирают Короля-лича и боятся снова потерять рассудок под его властью.",al={"forsaken vs scourge","why hate lich king","отрекшиеся и плеть","почему ненавидят короля-лича"}},{q="Каким путем идет это сообщение?",a="Гонцы идут на запад по главной дороге от заставы Стража смерти Линнеи через центральную часть Тирисфальских лесов, пока не достигнут центра Брилла.",al={"route from bulwark to brill","road to brill","путь от бастиона до брилла","дорога в брилл"}}},fp="24,413,16.569.0,12.492.0,33.229.0,51.255.0,25.217.0,20.211.0,45.238.0,35.160.0"}
P.entries["quest:361"] = {n="Недоставленное письмо",s="Выцветшее, окровавленное послание, найденное среди скелетов в руинах Мельниц Агамондов и адресованное Иветте Фартинг. Оно рассказывает о трагической разлуке двух влюбленных, когда Плеть захлестнула Лордерон, и позволяет заглянуть в то, что Отрекшиеся оставили, променяв жизнь на нежизнь.",h="Выцветшее, окровавленное послание, найденное среди скелетов в руинах Мельниц Агамондов и адресованное Иветте...",kw={"agamand","brill","farthing","letter","scourge","tavern","thurman","undelivered","yvette","агамонд","брилл","фартинг","письмо","плеть","таверна","турман","недоставленное","иветта"},ang={["faction:Horde"]="Для путников в Брилле это найденное письмо — яркое свидетельство эмоциональной отстраненности, определяющей народ Отрекшихся.",["race:Undead"]="Письмо воплощает резкую, болезненную пропасть между смертными воспоминаниями Отрекшегося и его холодным, целеустремленным существованием под властью Королевы банши."},sec={{t="Весть, потерянная в годы падения",b="Это неотправленное письмо написал Турман Агамонд, старший сын главы рода Грегора Агамонда, и оно не дошло до адресата, пока семейное поместье не рухнуло в руины. Когда Чума нежизни поглотила Тирисфальские леса, Турман отказался покинуть родовой дом и родных. Среди ужасов нашествия он взялся за перо, чтобы написать последнее послание Иветте Фартинг, которую любил, пока королевство не обратилось в пепел."},{t="Разорванная связь",b="Когда письмо наконец попадает в руки Иветты Фартинг в таверне «Петля висельника» в Брилле, оно вызывает короткую мучительную вспышку памяти. Она вспоминает, как умоляла Турмана бежать с ней и ее отцом из Мельниц Агамондов, и сетует, что брат Турмана, Бранд, желал ему зла. Но тепло мимолетно. Как и многие Отрекшиеся, Иветта ожесточает сердце, отбрасывая смертные сожаления и заявляя, что любви нет места в ее новом существовании."}},faq={{q="Кто написал это письмо?",a="Письмо написал Турман Агамонд, старший сын Грегора Агамонда. Турман погиб, защищая семейные мельницы от Плети, вместе с остальными членами своего проклятого рода.",al={"author","thurman agamand","who is thurman","автор","турман агамонд","кто такой турман"}},{q="Кто такая Иветта Фартинг?",a="Иветта Фартинг — Отрекшаяся, которая сейчас живет в таверне Брилла. При жизни она с отцом бежала из сельской местности от Плети, оставив своего возлюбленного Турмана Агамонда.",al={"yvette","who is yvette","recipient","иветта","кто такая иветта","адресат"}},{q="Откуда взялось это письмо?",a="Письмо добывают у бродячих скелетов, блуждающих по разоренным землям и полям Мельниц Агамондов на западе Тирисфальских лесов.",al={"where to find letter","letter drop","letter location","где найти письмо","добыча письма","расположение письма"}},{q="Что произошло между Турманом и Иветтой?",a="До Третьей войны они были возлюбленными. Иветта умоляла Турмана оставить семейные мельницы и бежать с ней, но Турман остался верен родным и остался встретить Чуму.",al={"thurman and yvette","yvette backstory","what happened to them","турман и иветта","предыстория иветты","что с ними случилось"}},{q="Что делает Иветта, прочитав письмо?",a="Она недолго горюет о Турмане и проклинает Плеть и его брата Бранда, но быстро подавляет чувства. Она настаивает, что сожаления — удел слабых и что романтике нет места в ее существовании Отрекшейся.",al={"yvette reaction","what does yvette say","реакция иветты","что говорит иветта"}},{q="Кто такой Бранд Агамонд?",a="Бранд был братом Турмана. По словам Иветты, Бранд таил глубокую обиду и злой умысел против Турмана еще до того, как поместье пало жертвой Чумы.",al={"brand","brand agamand","who is brand","бранд","бранд агамонд","кто такой бранд"}}},fp="20,283,26.434.0,16.473.1,22.185.0,23.194.0,31.138.0,41.188.0,46.218.1,21.153.0"}
P.entries["quest:362"] = {n="Мельницы с привидениями",s="Колман Фартинг из Брилла жаждет мести бывшим землевладельцам, Агамондам, и требует собрать и уничтожить их неупокоенные останки. Это задание отправляет вас на север, к Мельницам Агамондов, чтобы упокоить Девлина Агамонда, острого на язык младшего сына поместья. Оно начинает горькую вендетту против семьи, не сумевшей защитить простой народ Тирисфаля от Чумы.",h="Колман Фартинг из Брилла жаждет мести бывшим землевладельцам, Агамондам, и требует собрать и уничтожить их...",kw={"agamand mills","brill","coleman farthing","devlin agamand","haunted mills","plague","scourge","tirisfal glades","мельницы агамондов","брилл","колман фартинг","девлин агамонд","мельницы с привидениями","чума","плеть","тирисфальские леса"},ang={["faction:Horde"]="Помощь Отрекшимся в Тирисфале означает помощь в зачистке опасных очагов Плети на границах Брилла и Подгорода.",["race:Undead"]="Это задание отражает глубокую классовую обиду, пережившую падение Лордерона: Отрекшиеся сохранили смертные обиды на землевладельческую знать, не защитившую их от Чумы."},sec={{t="Горький урожай",b="До Третьей войны Мельницы Агамондов были житницей севера Тирисфаля и принадлежали богатому землевладельческому роду. Когда Плеть захлестнула Лордерон, простой люд надеялся на защиту знатных землевладельцев, но не нашел ни убежища, ни спасения. Колман Фартинг уцелел в нежизни, но сердце его по-прежнему полно ненависти к семье, которой он служил. Вместо того чтобы дать им скитаться в вечных муках, Фартинг хочет мрачного удовлетворения: собрать их кости и растоптать их собственной пятой."},{t="Младший брат",b="Девлин Агамонд был младшим братом Турмана Агамонда. При жизни его помнили как слабого, злобного и острого на язык юнца, резко непохожего на кроткого старшего брата. Когда Чума нежизни проникла в поместье при мельницах, Девлин одним из первых поддался порче. Теперь, лишенный того хилого ума, что имел при жизни, его безмозглый труп без умолку щелкает зубами на северной дороге к семейным мельницам."}},faq={{q="Почему Колману Фартингу нужны останки Девлина?",a="Колман Фартинг винит богатый род Агамондов в том, что они бросили его и его родных, когда Плеть захлестнула Лордерон. Ища личной мести в нежизни, он хочет собрать кости Агамондов, чтобы выставить их на каминной полке и собственноручно стереть в пыль.",al={"why coleman want bones","coleman farthing motive","why kill devlin","почему колману нужны кости","мотив колмана фартинга","зачем убивать девлина"}},{q="Где можно найти Девлина Агамонда?",a="Девлин бродит у дороги к югу от Мельниц Агамондов на севере Тирисфальских лесов, безумно бормоча среди нежити, что блуждает на окраинах поместья.",al={"devlin location","find devlin agamand","where is devlin","где девлин","найти девлина агамонда","расположение девлина"}},{q="Каким был Девлин до Чумы?",a="По словам Колмана Фартинга, Девлин был мельче, слабее и заметно острее на язык, чем его высокий и мягкий старший брат Турман, — младший сын семьи Агамондов.",al={"who was devlin","devlin agamand lore","devlin agamand in life","кем был девлин","девлин агамонд предыстория","девлин агамонд при жизни"}},{q="Девлин — часть Плети или Отрекшийся?",a="Девлин — безмозглый раб Плети. В отличие от Отрекшихся Подгорода, он так и не вырвался из хватки Короля-лича и бездумно бродит по разоренным землям своей семьи.",al={"is devlin scourge","devlin faction","девлин плеть","фракция девлина"}},{q="Какие еще задания связаны с Мельницами Агамондов?",a="Задание «Смерти в семье» тоже отправляет Отрекшихся героев к Мельницам Агамондов, чтобы уничтожить остальных членов семьи Агамондов, так что естественно выполнять оба задания одновременно.",al={"agamand mills quests","quests near devlin","задания мельниц агамондов","задания возле девлина"}},{q="Что происходит после сдачи останков Девлина?",a="Приняв кости, Колман Фартинг велит вам поговорить с Севреном в Брилле, что в итоге ведет глубже в семейный склеп Агамондов.",al={"quest continuation","next quest after haunted mills","продолжение задания","следующее задание после мельниц с привидениями"}}},fp="17,376,16.522.0,19.471.0,48.283.0,34.162.0,39.191.0,42.174.0,46.184.0,47.147.1"}
P.entries["quest:363"] = {n="Резкое пробуждение",s="«Резкое пробуждение» — первое задание, которое получают только что пробудившиеся Отрекшиеся в склепах Могильника. Восстав из мертвых и освободившись от железной хватки Короля-лича, вы уходите прочь от печей для сожжения и спускаетесь с холма, чтобы узнать от жреца Тени Сарвиса правду о своем новом существовании.",h="«Резкое пробуждение» — первое задание, которое получают только что пробудившиеся Отрекшиеся в склепах...",kw={"deathknell","forsaken","lich king","mordo","rude awakening","sarvis","scourge","shadow priest sarvis","sylvanas","tirisfal glades","undertaker mordo","могильник","отрекшиеся","король-лич","мордо","резкое пробуждение","сарвис","плеть","жрец тени сарвис","сильвана","тирисфальские леса","мордо гробовщик"},ang={["class:Priest"]="Явившись к жрецу Тени Сарвису, вы сразу знакомитесь с Культом Забытой Тени, по-новому осмысляющим духовную преданность после обретения нежизни.",["faction:Horde"]="Это пробуждение помещает вас в хрупкую орбиту Орды — союза, рожденного острой необходимостью перед лицом общего вымирания.",["race:Undead"]="Этот миг определяет ваше возрождение: сбросив оковы Плети, вы создаете себе дерзкое свободное существование среди Отрекшихся."},sec={{t="Могильное начало",b="Открыть глаза в сырой подземной прохладе склепа Могильника — тревожное знакомство с нежизнью. Мордо гробовщик присматривает за свежепогребенными, разделяя воскрешенных на тех, кто вернул себе свободную волю, и тех, кому суждено попасть в горящие ямы. Для многих восстание из могилы означает пробуждение среди гнили, холодного камня и полной растерянности: по чистой случайности они ускользнули из хватки Плети."},{t="Разрыв хватки Ледяного Трона",b="Прежде чем дойти до часовни, пробудившиеся мертвецы должны осознать мрачную истину: когда-то они были безмозглыми орудиями Короля-лича. Именно леди Сильвана Ветрокрылая разбила это духовное рабство, позволив остаткам прежней человечности вернуть самостоятельное мышление. Выход из гробницы и спуск в Могильник — первый шаг в мир, где и живые, и Плеть видят в вас мерзость, подлежащую уничтожению."}},faq={{q="Почему я оказался в склепе?",a="Вы умерли, поддавшись чуме или насилию Третьей войны, и были похоронены в Тирисфальских лесах. Могильник — главный сборный пункт, где за телами наблюдают, чтобы понять, обретут ли они разум или поддадутся безмозглому разложению.",al={"why in crypt","where did i wake up","deathknell tomb","почему в склепе","где я проснулся","гробница могильника"}},{q="Кто такой Мордо гробовщик?",a="Мордо — смотритель склепа в Могильнике. Его долг — присматривать за пробудившимися, направлять сохранивших рассудок к городской часовне и уничтожать тех, кто очнулся без разума.",al={"undertaker mordo","who is mordo","gravekeeper","мордо гробовщик","кто такой мордо","могильщик"}},{q="Почему Мордо упомянул, что бросает людей в огонь?",a="Не каждый труп, поднятый из могилы, обретает свободную волю или ясные мысли. Те, кто пробудился совершенно безумным или лишь диким, не могут быть приняты в общество Отрекшихся; их уничтожают и сжигают, чтобы предотвратить буйство.",al={"burn bodies","toss into fire","cremation","сжигать тела","бросать в огонь","кремация"}},{q="Кто освободил меня от Короля-лича?",a="Леди Сильвана Ветрокрылая, Королева банши, освободилась от психического господства Короля-лича, когда его сила ослабла. Она собрала под своим знаменем других свободных нежитей и основала Отрекшихся, чтобы бороться как с прежним господином, так и с враждебными остатками живых.",al={"who freed me","sylvanas freed undead","why am i free","кто освободил меня","сильвана освободила нежить","почему я свободен"}},{q="Где находится жрец Тени Сарвис?",a="Сарвис находится в разрушенной часовне у подножия холма в Могильнике. Если выйти из склепа и пойти вниз по мощеной дорожке, вы придете прямо ко входу в часовню.",al={"find sarvis","sarvis location","where is the chapel","найти сарвиса","где сарвис","где часовня"}},{q="С кем сражаются Отрекшиеся?",a="Отрекшиеся ведут войну за выживание на два фронта: против Плети, которая стремится вернуть или уничтожить их, и против человеческих фанатиков и уцелевших поселений, не желающих отличать их от безмозглых чудовищ.",al={"forsaken enemies","who do we fight","undead enemies","враги отрекшихся","с кем мы сражаемся","враги нежити"}}},fp="14,297,17.438.0,38.437.0,21.234.0,24.224.0,52.222.0,32.260.0,38.192.0,38.215.0"}
P.entries["quest:364"] = {n="Безмозглые твари",s="Жрец Тени Сарвис поручает пробудившимся Отрекшимся истребить Безмозглых зомби и Несчастных зомби, бродящих по северным окраинам Могильника. Эти шаркающие трупы — рабы Плети, лишенные свободной воли и полностью подчиненные приказам Короля-лича.",h="Жрец Тени Сарвис поручает пробудившимся Отрекшимся истребить Безмозглых зомби и Несчастных зомби, бродящих по...",kw={"deathknell","forsaken","lich king","mindless ones","mindless zombie","scourge","shadow priest sarvis","wretched zombie","могильник","отрекшиеся","король-лич","безмозглые твари","безмозглый зомби","плеть","жрец тени сарвис","несчастный зомби"},ang={["class:Priest"]="Служба под началом жреца Тени Сарвиса знакомит вас с прагматичной, окрашенной тенью философией, которую Отрекшиеся приняли вместо покинувшего их Света.",["faction:Horde"]="Существование подобных рабов показывает, почему Орда так глубоко подозревала Отрекшихся, прежде чем принять их в свои ряды.",["race:Undead"]="Каждый зомби на окраинах деревни мог быть вашим соседом, родственником или другом при жизни — это прямое напоминание о том, чего вам удалось избежать и что случится, если Отрекшиеся падут."},sec={{t="Рабы Ледяного Трона",b="Не все, кто восстает из земли Лордерона, обретают разум. Когда власть Нер'зула ослабла, Отрекшиеся сбросили его ментальное господство, но бесчисленные трупы остаются пустыми оболочками, скованными его волей. На севере Могильника эти Безмозглые и Несчастные зомби бродят без иной цели, кроме грубого насилия. Для только что восставшей нежити упокоить их — первое горькое испытание: доказать свою самостоятельность, разорвав цепи тех, кто так и не освободился."},{t="Милосердие через уничтожение",b="Хотя жрец Тени Сарвис сожалеет, что эти огромные легионы мертвецов нельзя привлечь для укрепления отчаянной борьбы Отрекшихся, исцелить их невозможно. Безмозглая нежить — навсегда сломанные орудия убийства. Оставить их бродить — значит навлечь хаос на порог Могильника и дать Королю-личу легкую добычу. Их уничтожение — тактическая необходимость и мрачная точка для павших жителей Лордерона."}},faq={{q="Почему безмозглых зомби нельзя принять в ряды Отрекшихся?",a="Им не хватает разума, чтобы вырваться из-под власти Короля-лича. Жрец Тени Сарвис отмечает, что их численность была бы бесценна, но их разум полностью разрушен. Поскольку они не могут выбрать присоединение к леди Сильване, они остаются опасными рабами Плети, которых необходимо уничтожить.",al={"recruit mindless zombies","why kill them","can mindless zombies be cured","free the zombies","принять безмозглых зомби","почему убивать их","можно ли исцелить зомби","освободить зомби"}},{q="Кем эти зомби были раньше?",a="Это бывшие жители Лордерона, павшие во время Третьей войны от чумы нежизни. В отличие от вашего персонажа, они так и не вернули воспоминания, личность и собственную волю, когда хватка Короля-лича ослабла.",al={"who were the mindless ones","identity of mindless zombies","deathknell corpses","кто такие безмозглые","личность безмозглых зомби","трупы могильника"}},{q="Почему жрец Тени Сарвис руководит здесь обороной?",a="Жрец Тени Сарвис отвечает за первичный прием и выживание только что восставшей нежити в Могильнике. Он оценивает, хватит ли пробудившимся Отрекшимся стойкости и ясности ума, чтобы пережить суровую реальность их существования.",al={"who is sarvis","sarvis deathknell role","priest sarvis","кто такой сарвис","роль сарвиса в могильнике","жрец сарвис"}},{q="Чем Отрекшиеся отличаются от зомби Плети?",a="Свободной волей. Отрекшиеся вырвались из телепатической власти Короля-лича и обладают самоопределением, разумом и чувствами. Зомби Плети — пустые сосуды, которыми напрямую управляет злоба Короля-лича.",al={"scourge vs forsaken","difference between forsaken and mindless","why are some zombies mindless","плеть и отрекшиеся","разница между отрекшимися и безмозглыми","почему зомби безмозглые"}},{q="Представляют ли безмозглые зомби угрозу для Могильника?",a="Да. Блуждая к северу от деревни, они своей агрессией сразу угрожают новичкам, выходящим из могил, и жрецам Отрекшихся, пытающимся организовать поселение.",al={"deathknell danger","why clear northern deathknell","zombie threat","опасность могильника","зачем зачищать север могильника","угроза зомби"}},{q="Что это задание дает дальше?",a="Доказав силу в схватке с безмозглыми мертвецами, вы получите дальнейшие поручения по защите Могильника, например истребление скелетов Плети в задании «Игрушки-погремушки», и начнете первое обучение у наставника вашего класса.",al={"next quest after mindless ones","mindless ones followup","what comes next","следующее задание после безмозглых тварей","безмозглые твари продолжение","что дальше"}}},fp="17,262,27.477.0,25.437.0,62.279.0,33.243.0,56.225.0,60.214.0,48.185.0,31.204.0"}
P.entries["quest:365"] = {n="Поля Горя",s="«Поля Горя» — одно из первых заданий Отрекшихся, которое выдает Страж смерти Симмер на дороге к северу от Могильника. Новичкам поручено совершить набег на ферму живых людей и собрать тирисфальские тыквы для Королевского фармацевтического общества в Брилле.",h="«Поля Горя» — одно из первых заданий Отрекшихся, которое выдает Страж смерти Симмер на дороге к северу от...",kw={"apothecary johaan","brill","deathguard simmer","deathknell","fields of grief","royal apothecary society","scarlet crusade","tirisfal pumpkin","аптекарь юхан","брилл","страж смерти симмер","могильник","поля горя","королевское фармацевтическое общество","алый орден","тирисфальская тыква"},ang={["faction:Horde"]="Чтобы закрепиться в Тирисфальских лесах, необходимо сломить остатки человеческого присутствия и разрушить влияние Алого ордена на южных дорогах.",["profession:Herbalism"]="Аптекари сильно зависят от искаженной флоры Тирисфаля при создании смертоносных смесей, поэтому каждый местный корень и каждая культура становятся реагентом войны.",["race:Undead"]="Это задание — ваше первое военное поручение за пределами Могильника: вы доказываете готовность лишить прежних смертных сородичей средств к существованию ради Королевского фармацевтического общества."},sec={{t="Урок выживания",b="Для новых Отрекшихся авантюристов, только что восставших из склепов Могильника, выход на туманные дороги Тирисфальских лесов — первый урок враждебности. Страж смерти Симмер воплощает прагматичную злобу сил Сильваны Ветрокрылой: выжить — значит отнять то, чем владеют живые, и обратить это на более мрачные дела Подгорода."},{t="Набег на живых",b="Цели набега — смертные люди-фермеры, пытающиеся обрабатывать зараженную землю к западу от дороги, севернее Могильника. Страж смерти называет их плесенью, пожирающей землю как труп, но эти крестьяне цепляются за свои дома под шаткой защитой соседних башен Алого ордена. Похищение урожая наносит злобный удар по их запасам и удовлетворяет бесконечную потребность Королевского фармацевтического общества в реагентах."},{t="Припасы для Общества",b="Украденные тыквы доставляют прямо аптекарю Юхану, который проводит опытные исследования в Брилле. Королевское фармацевтическое общество часто использует местные сельскохозяйственные продукты и растения как основу для алхимических зелий, ядов и исследований чумы, призванных упрочить шаткие позиции Отрекшихся на севере Лордерона."}},faq={{q="Кто выдает задание «Поля Горя»?",a="Задание выдает Страж смерти Симмер. Он стоит на страже дороги на юге Тирисфальских лесов, чуть севернее тропы, ведущей из Могильника.",al={"quest giver","fields of grief quest starter","who starts fields of grief","персонаж, выдающий задания","кто дает поля горя","начало поля горя"}},{q="Куда нести тирисфальские тыквы?",a="Десять тыкв нужно доставить аптекарю Юхану в городок Брилл, дальше на север в Тирисфальских лесах.",al={"where to turn in pumpkins","pumpkin turn in","fields of grief hand in","куда сдать тыквы","сдача тыкв","поля горя сдать"}},{q="Почему в Тирисфальских лесах возделывают землю живые люди?",a="Эти крестьяне — остатки коренного населения Лордерона, пережившие Третью войну и чуму Плети. Они упрямо цепляются за свои дома в тени соседних застав Алого ордена, сопротивляясь власти Отрекшихся.",al={"why humans here","living humans tirisfal","why are humans in undead zone","почему здесь люди","живые люди тирисфаль","почему люди в землях нежити"}},{q="Зачем аптекарю Юхану тыквы?",a="Королевское фармацевтическое общество использует различные растения, зараженные культуры и биологический материал как испытательные средства и основу для алхимических смесей, ядов и опытных чум.",al={"why pumpkins","what are pumpkins for","apothecary johaan pumpkins","зачем тыквы","для чего тыквы","аптекарь юхан тыквы"}},{q="Кто патрулирует возле фермы?",a="Фанатики Алого ордена патрулируют окрестности от своей сторожевой башни неподалеку, защищая человеческое поселение и пытаясь уничтожить любую нежить, приближающуюся к полям.",al={"scarlet crusade near farm","who protects the farm","алый орден у фермы","кто охраняет ферму"}},{q="Что идет после «Полей Горя»?",a="После сдачи тыкв аптекарь Юхан сразу дает продолжение с тем же названием: вам вручают тыкву, пропитанную его новейшим составом, чтобы отнести пленному фанатику Алого ордена, которого держат в подвале Таверны «Петля висельника».",al={"next quest","fields of grief followup","what is after fields of grief","следующее задание","поля горя продолжение","что после полей горя"}}},fp="15,240,20.345.0,18.441.0,24.328.1,36.150.0,38.113.0,55.243.0,41.195.0,31.164.0,33.241.0"}
P.entries["quest:366"] = {n="Книга Гюнтера",s="Бетор Ледострел зачаровывает украденную книгу заклинаний Гюнтера Чародея, чтобы доказать свою свободу и привлечь бывшего коллегу по Кирин-Тору на сторону Отрекшихся. Когда фолиант возвращают на островное убежище Гюнтера, выясняется, что ни один из бывших волшебников не является рабом Короля-лича.",h="Бетор Ледострел зачаровывает украденную книгу заклинаний Гюнтера Чародея, чтобы доказать свою свободу и...",kw={"bethor iceshard","brightwater lake","dalaran","gunther arcanus","gunther's retreat","gunther's spellbook","kirin tor","return the book","thule ravenclaw","tirisfal glades","бетор ледострел","озеро ясноводное","даларан","гюнтер чародей","убежище гюнтера","книга заклинаний гюнтера","кирин-тор","книга гюнтера","тул коготь ворона","тирисфальские леса"},ang={["class:Mage"]="Этот обмен показывает глубокие узы между бывшими магами Кирин-Тора, которые узнают магические подписи друг друга даже сквозь завесу нежизни.",["faction:Horde"]="Привлечение независимых нежитных чародеев вроде Гюнтера укрепляет арканную мощь Подгорода против Плети и Алого ордена.",["race:Undead"]="Участь Гюнтера отражает исходную борьбу Отрекшихся: очнуться от кошмара безвольного рабства лишь для того, чтобы столкнуться с одиноким и враждебным миром."},sec={{t="Послание арканными чернилами",b="Узнав, что отступник-некромант на Озере Ясноводном — его старый товарищ Гюнтер Чародей, Бетор Ледострел придумал хитроумный способ связи. Ранее он приказал похитить книгу заклинаний Гюнтера, чтобы раскрыть личность некроманта, а теперь Бетор вплетает в ее страницы сложные чары. Это не требование и не вооруженные переговоры: чары служат арканной подписью и доказывают, что Бетор не только действует в Лордероне, но и полностью освободился от ментального ярма Короля-лича."},{t="Старый круг Даларана",b="До того как Третья война опустошила Лордерон, Бетор Ледострел, Гюнтер Чародей и Тул Коготь Ворона были соучениками и друзьями в Кирин-Торе в Даларане. Все трое поддались ужасам Чумы, но после смерти их пути резко разошлись. Тул принял Плеть и по-прежнему служит Королю-личу, а Бетор освободился вместе с королевой Сильваной. Считая, что Гюнтер мертв или порабощен, Бетор понял, что тот тоже обрел нежизнь по собственной воле, и это вызвало настойчивые попытки привлечь его к Отрекшимся."},{t="Недоверие на острове",b="Когда к Гюнтеру приближаются на его уединенном острове, он поначалу впадает в ярость, полагая, что любой, кто вторгся на Озеро Ясноводное, — либо агент Плети, желающий вновь его поработить, либо вор, укравший его магию. Вид личного гримуара и знакомый магический резонанс Бетора застают уединенного мага врасплох. Осознание того, что кто-то из его смертного прошлого разорвал оковы Плети, заставляет Гюнтера пересмотреть свою полную изоляцию."}},faq={{q="Почему Бетор зачаровал книгу заклинаний Гюнтера?",a="Бетор наделил украденный гримуар личной магической подписью, чтобы доказать Гюнтеру, что он действительно свободен от Короля-лича. Зная глубокую подозрительность Гюнтера и его ненависть к Плети, обычного посланника отвергли бы или уничтожили на месте.",al={"why enchant the book","gunthers book spell","what did bethor do to the book","зачем зачаровали книгу","книга заклинаний гюнтера","что бетор сделал с книгой"}},{q="Кем был Гюнтер Чародей до смерти?",a="Гюнтер Чародей был человеком, магом и ученым Кирин-Тора в Даларане. До Третьей войны он учился вместе с Бетором Ледострелом и Тулом Когтем Ворона и в итоге стал жертвой Чумы нежизни Плети.",al={"who is gunther arcanus","gunther backstory","gunther lore","кто такой гюнтер чародей","история гюнтера","предыстория гюнтера"}},{q="Почему Гюнтер прячется на Озере Ясноводном?",a="Освободившись от власти Короля-лича, Гюнтер считал, что он совершенно один в своей свободе. Он уединился на острове на Озере Ясноводном, чтобы его не выследила и не поработила вновь Плеть и не убили живые враги.",al={"why is gunther on the island","gunthers retreat lore","why did gunther leave","почему гюнтер на острове","убежище гюнтера","почему гюнтер ушел"}},{q="Кто такой Тул Коготь Ворона?",a="Тул Коготь Ворона был третьим членом круга учеников Кирин-Тора в Даларане, в который входили Бетор и Гюнтер. В отличие от Бетора и Гюнтера, разорвавших оковы, Тул добровольно остается верным некромантом на службе Плети в Серебряном бору.",al={"who is thule","thule ravenclaw lore","third friend","кто такой тул","тул коготь ворона","третий друг"}},{q="Почему Гюнтер считает игрока вором?",a="Ранее Бетор поручил Отрекшимся искателям приключений пробраться в святилище Гюнтера и украсть его книгу заклинаний, чтобы выяснить, кто занимается некромантией на озере. Гюнтер верно узнает в вернувшемся искателе приключений того, кто его обокрал.",al={"why does gunther call me a thief","did i steal gunthers book","stolen book","почему гюнтер называет меня вором","я украл книгу гюнтера","украденная книга"}},{q="Присоединяется ли Гюнтер к Отрекшимся сразу?",a="Нет, не сразу. Хотя Гюнтер потрясен тем, что Бетор жив и обладает свободной волей, он скептически относится к Отрекшимся и требует доказательств, что вы — враг Плети: призвать и уничтожить агента Плети Лилит Нефару у древнего алтаря близ южного побережья его острова.",al={"does gunther join sylvanas","gunther allegience","what happens next with gunther","присоединится ли гюнтер к сильване","на чьей стороне гюнтер","что будет дальше с гюнтером"}}},fp="15,264,23.517.0,25.541.0,22.469.1,43.260.0,39.214.0,42.244.0,23.240.0,45.256.0,43.282.1"}
P.entries["quest:367"] = {n="Новая чума",s="«Новая чума» — вводное задание в Брилле, раскрывающее главный стратегический замысел Отрекшихся. Аптекарь Юхан поручает новобранцам собрать кровь диких темных гончих, чтобы заложить основу для смертоносного возбудителя, заказанного лично леди Сильваной Ветрокрылой.",h="«Новая чума» — вводное задание в Брилле, раскрывающее главный стратегический замысел Отрекшихся.",kw={"apothecary","arthas","brill","darkhound","johaan","plague","scourge","sylvanas","tirisfal","аптекарь","артас","брилл","темная гончая","юхан","чума","плеть","сильвана","тирисфаль"},ang={["faction:Horde"]="Хотя Отрекшиеся вступили в Орду, их алхимические изыскания в Тирисфале целиком направлены на мрачное биологическое оружие, нацеленное на Нордскол.",["race:Undead"]="Это задание — ваш первый непосредственный вклад в главный проект Королевского фармацевтического общества: создание оружия, которое Сильвана намерена применить против Артаса."},sec={{t="Королевский указ",b="В сыром поселке Брилл аптекарь Юхан действует от имени Королевского фармацевтического общества по прямому указу Темной Госпожи. Сильвана Ветрокрылая поручила своим алхимикам создать недуг, какого Азерот еще не видел. Если изначальная чума нежизни служила Королю-личу, убивая людей и подчиняя их души, то это новое творение прямо предназначено уничтожить Артаса Менетила и разгромить легионы его Плети."},{t="Сырые ингредиенты",b="Создание биологического оружия, способного уничтожать нежить, требует мрачных опытов. Юхан полагает, что кровь местных зверей, начиная со свирепых темных гончих, бродящих во мраке Тирисфальских лесов, обладает важными химическими свойствами. Собирая флаконы этой оскверненной звериной крови, Юхан начинает выделять элементы, чтобы проверить, может ли природная стойкость и хищная биология местных созданий стать катализатором смертоносной заразы."}},faq={{q="Какова цель новой чумы?",a="Леди Сильвана поручила Королевскому фармацевтическому обществу создать недуг смертоноснее любого другого в Азероте. Главная стратегическая цель — полное уничтожение Артаса и его армии Плети.",al={"why make a new plague","purpose of new plague","what does the plague do","зачем создавать новую чуму","цель новой чумы","что делает чума"}},{q="Кто такой аптекарь Юхан?",a="Юхан — член Королевского фармацевтического общества, находящийся в поселке Брилл. Он проводит ранние полевые опыты, испытывая биологические соединения, собранные из местной фауны Тирисфаля.",al={"who is johaan","apothecary johaan lore","кто такой юхан","аптекарь юхан"}},{q="Зачем Юхану кровь темных гончих?",a="Исследования Юхана показывают, что кровь местных зверей может стать важной основой его алхимических формул. Кровь темных гончих нужна ему, чтобы проверить предварительные теории в лаборатории.",al={"why darkhound blood","what is the blood for","зачем кровь темных гончих","для чего нужна кровь"}},{q="Чем эта чума отличается от чумы Плети?",a="Изначальная Чума нежизни была создана Королем-личом, чтобы убивать живых и поднимать их рабами. Новая чума Сильваны специально разработана как оружие, призванное принести гибель нежитным легионам Артаса.",al={"difference between plagues","scourge plague vs forsaken plague","разница между чумами","чума плети и чума отрекшихся"}},{q="Кто приказал создать эту чуму?",a="Леди Сильвана Ветрокрылая лично приказала Королевскому фармацевтическому обществу создать ее, полагая, что алхимия Отрекшихся в сочетании с новообретенной магией — ключ к победе над Артасом.",al={"who started the plague research","who wants the plague","кто начал исследования чумы","кому нужна чума"}},{q="Что происходит после сбора крови?",a="Сбор крови темных гончих — лишь первый шаг в продолжающейся серии опытов. Юхан использует образцы, чтобы начать совершенствовать возбудитель в ходе дальнейших полевых испытаний в Тирисфальских лесах.",al={"what is the next step","does the plague work","каков следующий шаг","действует ли чума"}}},fp="12,280,15.467.0,15.451.0,35.200.0,25.185.0,37.199.0,54.223.0,40.179.0,39.187.0"}
P.entries["quest:368"] = {n="Новая чума",s="Это поручение дает аптекарь Юхан в Брилле: нужно собрать чешую местных мурлоков Злобного Плавника, обитающих на побережье Тирисфаля. Королевское фармацевтическое общество стремится использовать уникальные биологические реагенты, чтобы усовершенствовать свою новую заразу и обеспечить ее распространение за пределы отдельных жертв на более широкие популяции.",h="Это поручение дает аптекарь Юхан в Брилле: нужно собрать чешую местных мурлоков Злобного Плавника, обитающих...",kw={"a new plague","apothecary johaan","brill","murloc","royal apothecary society","tirisfal glades","vile fin scale","новая чума","аптекарь юхан","брилл","мурлок","королевское фармацевтическое общество","тирисфальские леса","чешуя злобного плавника"},ang={["faction:Horde"]="Хотя аптекари Отрекшихся открыто занимаются этими темными изысканиями в Тирисфальских лесах, полная цель и мощь чумы остаются деликатным вопросом, о котором в основном умалчивают перед менее безжалостными союзниками из Орды.",["race:Undead"]="Для Отрекшихся помощь аптекарю Юхану — прямой вклад в высшее оружие и защиту их народа: создание смертоносной чумы, разработанной специально для защиты их суверенных владений и уничтожения врагов."},sec={{t="Расширение масштабов заразы",b="Отравить одну цель — простая алхимия, но создание чумы, способной охватить целые земли, требует более сложных компонентов. Исследования аптекаря Юхана в Брилле зависят от создания болезни, способной самостоятельно распространяться и выживать в природе. Чтобы добиться заразности, он обращает внимание на прибрежных животных Тирисфальских лесов и видит в стойкой биологии прибрежных мурлоков Злобного Плавника многообещающий источник сырья."},{t="Реагенты Злобного Плавника",b="Северное и западное побережья Тирисфальских лесов терзают агрессивные племена мурлоков, известные как Злобный Плавник. Сбор их чешуи дает Юхану органические соединения, приспособленные к сырым и суровым условиям. Добавляя скользкую стойкую чешую мурлоков в свой растущий котел, аптекарь стремится усилить вирулентность и устойчивость к среде новой чумы Королевского фармацевтического общества."}},faq={{q="Какова цель исследований аптекаря Юхана?",a="Юхан разрабатывает новую чуму от имени Королевского фармацевтического общества и леди Сильваны. Его цель выходит далеко за рамки создания простых ядов: он работает над заразой, способной распространяться на целые популяции и земли и поражать как живых, так и Плеть.",al={"why make a new plague","johaan plague goal","what is johaan doing","зачем создавать новую чуму","цель чумы юхана","что делает юхан"}},{q="Почему Юхану нужна именно чешуя мурлоков?",a="Юхан обнаружил при первых опытах, что простым ядам не хватает биологической сложности для эффективного распространения. Прочная, покрытая слизью чешуя мурлоков Злобного Плавника содержит особые биологические соединения, необходимые, чтобы улучшить способность заразы выживать в природе и передаваться между носителями.",al={"why murloc scales","vile fin scale purpose","why scales for plague","зачем чешуя мурлоков","назначение чешуи злобного плавника","зачем чешуя для чумы"}},{q="Где можно найти мурлоков Злобного Плавника?",a="Мурлоки Злобного Плавника обитают на побережье Тирисфальских лесов, в основном вдоль северных пляжей у Великого моря и на западном берегу.",al={"where are murlocs tirisfal","vile fin location","murloc spots","где мурлоки в тирисфале","где злобный плавник","места мурлоков"}},{q="Кому подчиняется аптекарь Юхан?",a="Аптекарь Юхан — сотрудник Королевского фармацевтического общества, алхимической гильдии со штаб-квартирой в Подгороде, подчиняющейся непосредственно королеве Сильване Ветрокрылой.",al={"who leads the apothecaries","johaan boss","royal apothecary society leader","кто возглавляет аптекарей","начальник юхана","глава фармацевтического общества"}},{q="Каков следующий шаг в этой цепочке заданий?",a="После того как чешуя Злобного Плавника доставлена Юхану, он продолжает совершенствовать формулу, для чего нужны новые биологические компоненты, и в итоге испытывает свежесваренный штамм.",al={"what comes next","after vile fin scales","next plague quest","что дальше","после чешуи злобного плавника","следующее задание о чуме"}},{q="Беспокоит ли Отрекшихся использование частей мурлоков?",a="Ничуть. Королевское фармацевтическое общество известно своим прагматизмом и аморальностью и охотно берет части любых местных растений, животных или зверей, обладающих нужными для опытов биохимическими свойствами.",al={"murloc alchemy dangerous","why harvest murlocs","опасна ли алхимия мурлоков","зачем добывать мурлоков"}}},fp="12,324,24.478.0,21.415.0,49.271.0,48.303.0,40.162.0,37.170.0,42.194.0,52.205.0"}
P.entries["quest:3681"] = {n="Фолиант Божественности",s="«Фолиант Божественности» — вызов, адресованный начинающим паладинам-людям, посещающим Стальгорн. Мастер Брандар Железный Молот велит посвященным отправиться на юг, в Собор Света в Штормграде, где мастер Даториан Ралл руководит продвинутым обучением по священным фолиантам Божественности.",h="«Фолиант Божественности» — вызов, адресованный начинающим паладинам-людям, посещающим Стальгорн.",kw={"brandur ironhammer","cathedral of light","duthorian rall","ironforge","paladin","redemption","stormwind","tome of divinity","брандар железный молот","собор света","даториан ралл","стальгорн","паладин","искупление","штормград","фолиант божественности"},ang={["class:Paladin"]="Это задание знаменует ваш официальный переход от простого воинского новичка к рукоположенному служителю Света, способному направлять его глубочайшие исцеляющие чудеса.",["faction:Alliance"]="Совместное обучение святых воинов в Штормграде укрепляет духовную и военную связь между Стальгорном и королевством Штормград.",["race:Dwarf"]="Паладины-дворфы создали собственные гордые традиции в Каз Модане и принимают фолианты Божественности в Стальгорне, пока их собратья-люди отправляются в Штормград."},sec={{t="Вызов из Штормграда",b="Пока паладины-дворфы усердно тренируются под каменными сводами Высокого трона Стальгорна, более широкие традиции Серебряной Длани остаются тесно связанными с Церковью Священного Света в землях людей. Весть из Штормграда призывает многообещающих святых воинов явиться прямо к высшему духовенству и наставникам-паладинам Собора Света."},{t="Путь к собору",b="Мастер Брандар Железный Молот понимает, когда ученик готов постичь более глубокие тайны веры. Путешествие на юг — на Подземном поезде или через горные перевалы — приводит посвященных в Соборный квартал Штормграда, где Даториан Ралл готовит их к изучению священных фолиантов и овладению обрядами искупления."}},faq={{q="Почему наставник из Стальгорна отправляет меня в Штормград?",a="Собор Света Штормграда служит административным сердцем продвинутого обучения паладинов Альянса. Брандар Железный Молот направляет многообещающих посвященных к мастеру Даториану Раллу, чтобы они могли пройти особые канонические испытания, связанные со священными фолиантами Божественности.",al={"why go to stormwind","why send to duthorian rall","ironforge to stormwind paladin","зачем идти в штормград","зачем отправлять к даториану раллу","паладин из стальгорна в штормград"}},{q="Кто такой Брандар Железный Молот?",a="Брандар Железный Молот — наставник паладинов из числа дворфов, находящийся в Высоком троне Стальгорна. Он присматривает за посвященными, обучая их воинскому служению и направляя к высшим знаниям, когда их внутренняя связь со Светом крепнет.",al={"brandur ironhammer","who is brandur","брандар железный молот","кто такой брандар"}},{q="Кто такой Даториан Ралл?",a="Даториан Ралл — старший наставник паладинов и прелат, находящийся в Соборе Света в Штормграде. Он лично проверяет будущих паладинов суровыми духовными испытаниями, прежде чем доверить им фолианты Божественности.",al={"duthorian rall","who is duthorian","даториан ралл","кто такой даториан"}},{q="Что такое фолианты Божественности?",a="Фолианты Божественности — священные тексты и доктринальные руководства, которыми Церковь Священного Света обучает паладинов торжественным обрядам воскрешения, самопожертвования и непоколебимого сострадания.",al={"what is tome of divinity","tome of divinity meaning","что такое фолиант божественности","значение фолианта божественности"}},{q="Как быстрее всего добраться из Стальгорна в Штормград?",a="Самый быстрый и безопасный путь — Подземный поезд, инженерное чудо в Городе механиков Стальгорна, которое везет путников прямо под горами в самое сердце Штормграда.",al={"how to get to stormwind","deeprun tram to stormwind","как добраться до штормграда","подземный поезд до штормграда"}},{q="Обязательно ли это испытание для всех паладинов Альянса?",a="Нет. Этот вызов предназначен для паладинов-людей, которые изучают фолианты у Даториана Ралла в Соборе Света Штормграда. Паладины-дворфы проходят собственные испытания Фолианта Божественности в Стальгорне у Тизы Боевого Горна.",al={"do dwarves have to do this","paladin class quest requirement","должны ли дворфы это делать","требование классового задания паладина"}}},fp="16,279,24.376.0,25.366.0,52.278.0,26.237.0,22.229.0,31.194.0,58.194.0,49.208.0"}
P.entries["quest:369"] = {n="Новая чума",s="В Брилле аптекарь Юхан занят созданием мощного нового биологического средства для Отрекшихся. Изучая древние тексты, он узнает, что смертоносная чума прошлого сохранилась в яде ночных пауков востока Тирисфальских лесов, что вызывает срочную экспедицию за образцами.",h="В Брилле аптекарь Юхан занят созданием мощного нового биологического средства для Отрекшихся.",kw={"a new plague","apothecary johaan","brill","night web spider","royal apothecary society","tirisfal glades","venom","venomweb vale","новая чума","аптекарь юхан","брилл","ночной паук","королевское фармацевтическое общество","тирисфальские леса","яд","долина ядовитых пауков"},ang={["faction:Horde"]="Хотя исследователи Отрекшихся рады помощи союзников-орков и таурен, жуткий характер их биологических опытов часто тревожит остальную Орду.",["race:Undead"]="Для Отрекшихся создание уникального оружия — единственная надежная защита от неутомимых остатков Плети и крестоносцев Алого ордена, стоящих у их порога."},sec={{t="Раскопки древних зараз",b="Занимаясь алхимией для Королевского фармацевтического общества в Брилле, аптекарь Юхан изучает старые фолианты в поисках более смертоносных составов. Он находит записи о древнем море, унесшем тысячи жизней. Главное: тексты указывают, что смертоносный возбудитель сохранялся поколениями в местных паукообразных Тирисфальских лесов, и их яд стал ценным биологическим реагентом."},{t="Охота в Долине ядовитых пауков",b="Чтобы получить пригодный образец возбудителя, Юхан направляет посланников в восточную часть Тирисфальских лесов. К югу от Монастыря Алого ордена лежит Долина ядовитых пауков, окутанная туманом лощина, кишащая свирепыми ночными пауками. Сборщикам предстоит проникнуть в их логова и извлечь свежие ядовитые железы — последний ингредиент для опытного зелья Юхана."},{t="Приготовление окончательного состава",b="Получив собранный яд, Юхан добавляет его в кипящий котел к ранее собранным реагентам. Когда смесь выварена и готова, заразное начало от пауков завершает состав, приближая Королевское фармацевтическое общество к практическим полевым испытаниям."}},faq={{q="Зачем аптекарю Юхану паучий яд?",a="Юхан нашел старый текст о древней чуме, убившей тысячи, чей опасный штамм естественным образом сохранился в яде ночных пауков Тирисфаля. Он намерен использовать это заразное начало для своего состава.",al={"why spider venom","apothecary johaan spiders","spider venom use","зачем паучий яд","аптекарь юхан пауки","применение паучьего яда"}},{q="Где живут свирепые ночные пауки?",a="Они обитают на востоке Тирисфальских лесов, в Долине ядовитых пауков, к югу от Монастыря Алого ордена.",al={"where are night web spiders","night web spider location","venomweb vale location","где ночные пауки","местонахождение ночных пауков","где долина ядовитых пауков"}},{q="Какова цель исследований Королевского фармацевтического общества здесь?",a="Общество стремится синтезировать новый смертоносный штамм, способный истребить и Плеть, и живых, закрепив выживание и независимость Отрекшихся в Лордероне.",al={"why make a new plague","forsaken plague goals","royal apothecary society plague","зачем новая чума","цели чумы отрекшихся","королевское фармацевтическое общество чума"}},{q="Кто такой аптекарь Юхан?",a="Юхан — исследователь из числа Отрекшихся, находящийся в Брилле на службе Королевского фармацевтического общества. Он руководит местными химическими и биологическими опытами, сочетая темную алхимию с реагентами, собранными в Тирисфале.",al={"who is johaan","apothecary johaan lore","кто такой юхан","аптекарь юхан предания"}},{q="Что будет после сбора этого яда?",a="Когда Юхан выварит яд в своем зелье, он собирается испытать состав напрямую, чтобы выяснить, обладает ли полученное токсичное средство нужной смертоносностью.",al={"what happens next","new plague quest sequel","after a new plague 3","что дальше","продолжение новой чумы","после новой чумы 3"}},{q="Это та же чума, что создала Плеть?",a="Нет. Плеть распространяла Чуму нежизни, созданную Королем-личом. Аптекари Отрекшихся намеренно создают совершенно иное биологическое оружие собственной разработки.",al={"is this scourge plague","plague of undeath difference","это чума плети","отличие от чумы нежизни"}}},fp="12,290,29.416.0,25.374.0,29.310.1,45.238.0,44.104.0,65.174.0,25.203.0,42.163.1,49.187.0"}
P.entries["quest:37"] = {n="Пропавшие стражи",s="«Пропавшие стражи» — расследование, поручаемое стражником Томасом у восточного моста в Элвиннском лесу. Стражи Рольф и Малакай, посланные патрулировать берега реки против наступающих мурлоков, пропали, и Томас отчаянно нуждается в подтверждении их судьбы.",h="«Пропавшие стражи» — расследование, поручаемое стражником Томасом у восточного моста в Элвиннском лесу.",kw={"elwynn forest","find the lost guards","guard thomas","half-eaten body","malakai","malakai stone","murlocs","rolf","элвиннский лес","пропавшие стражи","стражник томас","полусъеденное тело","малакай","малакай стоун","мурлоки","рольф"},ang={["class:Paladin"]="Почтить павших защитников и вернуть их личные знаки — значит принести покой и справедливость солдатам, охранявшим границы королевства.",["faction:Alliance"]="Печальная гибель пехотинцев так близко к Штормграду показывает, насколько уязвимы внешние границы Элвинна перед нападениями зверей и мурлоков."},sec={{t="Исчезнувший патруль",b="Стражник Томас несет дозор у восточной переправы Элвиннского леса, где Королевский тракт подходит к Красногорью. Местные воды становятся все опаснее из-за набегов мурлоков. Несколько дней назад Томас отправил двух стражей Штормграда, Рольфа и Малакая, на север вдоль берегов разведать угрозу и разорить гнезда. Когда ни один не вернулся, Томасу пришлось признать, что насилие прервало их задание."},{t="Мрачная находка",b="Путь вдоль реки на север к берегам Озера Каменных Столбов ведет прямо в кишащие мурлоками земли. У кромки воды искатели приключений находят жуткую картину: полусъеденный труп в грязи. Рядом с изуродованными останками лежит гравированный медальон с именем «пехотинец Малакай Стоун», подтверждающий печальную судьбу одного из стражей; судьба Рольфа остается неизвестной."}},faq={{q="Кто выдает это задание и где его найти?",a="Это задание выдает стражник Томас. Он стоит у реки на восточной границе Элвиннского леса и охраняет мост, ведущий к Красногорью.",al={"quest giver","where is guard thomas","who starts find the lost guards","кто выдает задание","где стражник томас","кто начинает пропавшие стражи"}},{q="Кто эти пропавшие стражи?",a="Пропавшие — Рольф и Малакай, два пехотинца Штормграда, посланные стражником Томасом разведать берега реки и следить за агрессивными мурлоками.",al={"missing guards elwynn","who are rolf and malakai","lost guards names","пропавшие стражи элвинн","кто такие рольф и малакай","имена пропавших стражей"}},{q="Где найдены останки?",a="Полусъеденные останки пехотинца Малакая Стоуна лежат на восточном берегу реки к северу от поста стражника Томаса, у окраины поселения мурлоков.",al={"where is malakai corpse","half-eaten body location","lost guards location","где труп малакая","где полусъеденное тело","где пропавшие стражи"}},{q="Что убило Малакая?",a="Малакая одолели и съели речные мурлоки, наводнившие берега востока Элвиннского леса.",al={"how did malakai die","who killed the guards","как погиб малакай","кто убил стражей"}},{q="Что случилось с Рольфом?",a="Останки Малакая найдены у реки в одиночестве. Судьба Рольфа остается загадкой, для разгадки которой нужно искать глубже в лагерях мурлоков.",al={"where is rolf","did rolf survive","где рольф","выжил ли рольф"}},{q="Почему стражей отправили одних?",a="Поскольку армия Штормграда растянута по многим землям, небольшие гарнизоны, такие как пост стражника Томаса, вынуждены полагаться на минимальные патрули из двух человек для наблюдения за границами глуши.",al={"why were they sent","stormwind guard shortage","почему их отправили","нехватка стражи штормграда"}}},fp="20,276,17.435.0,14.405.1,47.161.0,27.149.0,28.162.1,20.112.1,22.144.1,35.178.0"}
P.entries["quest:370"] = {n="Война с Алым орденом",s="Палач Зуганд велит чемпионам Отрекшихся уничтожить капитана Перрина и его гарнизон в разрушенной башне к юго-западу от Брилла. Используя сведения, добытые в Могильнике, Отрекшиеся стремятся отбросить фанатичных крестоносцев, угрожающих их границам.",h="Палач Зуганд велит чемпионам Отрекшихся уничтожить капитана Перрина и его гарнизон в разрушенной башне к...",kw={"brill","captain perrine","executor arren","executor zygand","proof of demise","ruined tower","scarlet crusade","scarlet missionary","scarlet zealot","tirisfal glades","брилл","капитан перрин","палач аррен","палач зуганд","доказательство верности","разрушенная башня","алый орден","алый миссионер","алый фанатик","тирисфальские леса"},ang={["faction:Horde"]="Опора Орды в Восточных королевствах зависит от того, смогут ли Отрекшиеся защитить Тирисфальские леса от враждебных фанатиков-людей.",["race:Undead"]="Для Отрекшихся уничтожение Алого ордена — вопрос существования: фанатики не отличают свободную нежить от Плети."},sec={{t="Сведения в деле",b="Документы, добытые палачом Арреном у Алого ордена в Могильнике, раскрыли передвижения войск по Тирисфальским лесам. Не дожидаясь, пока фанатики начнут наступление на укрепленный Брилл, палач Зуганд использует эти трофейные сведения для упреждающих ударов по их полевым командирам."},{t="Угроза в разрушенной башне",b="Капитан Перрин, засевший в обветшалой сторожевой башне к юго-западу от Брилла, командует отрядом алых фанатиков и миссионеров. Оттуда орден пытается следить за передвижениями Отрекшихся и распространять влияние глубже в Тирисфаль, поэтому смерть Перрина важна для защиты юного королевства Темной Госпожи."}},faq={{q="Кто такой капитан Перрин?",a="Капитан Перрин — офицер Алого ордена, находящийся в разрушенной сторожевой башне к юго-западу от Брилла и командующий отрядом фанатиков и миссионеров, вторгшихся в Тирисфальские леса.",al={"captain perrine","perrine","who is perrine","капитан перрин","перрин","кто такой перрин"}},{q="Откуда Отрекшиеся получили сведения о капитане Перрине?",a="Палач Аррен добыл стратегические документы ордена при первой обороне Могильника; в них описаны назначения войск и расположение застав, включая пост Перрина.",al={"strategic documents zygand","arren's documents","scarlet documents deathknell","стратегические документы зуганда","документы аррена","алые документы могильник"}},{q="Почему алые миссионеры и фанатики оказались в Тирисфале?",a="Алый орден считает всех нежить мерзостью, подлежащей истреблению, служит ли она Плети или Отрекшимся. Его миссионеры и фанатики проникают глубоко в Тирисфаль, чтобы вести священную войну и вернуть Лордерон живым.",al={"why is scarlet crusade in tirisfal","scarlet missionaries tirisfal","scarlet zealots","почему алый орден в тирисфале","алые миссионеры тирисфаль","алые фанатики"}},{q="Как это задание вписывается в кампанию против ордена?",a="Это второй шаг тирисфальской кампании против ордена. Убийство Перрина уничтожает их местный разведпост, прежде чем палач Зуганд расширит операции против более крупных лагерей в лесах.",al={"at war with the scarlet crusade chain","what comes next after perrine","война с алым орденом цепочка","что дальше после перрина"}},{q="Можно ли выполнить это задание вместе с чем-то еще поблизости?",a="Да, оно напрямую связано с заданием «Доказательство верности», в котором страж смерти Буржес просит принести алые кольца-печатки, снятые с тех же крестоносцев, как доказательство верности Вариматрасу и Темной Госпоже.",al={"proof of demise pairing","quest pairing perrine","brill tower quests","доказательство верности","связка заданий перрин","задания башни брилла"}},{q="Кто такой палач Зуганд?",a="Палач Зуганд — главный военачальник в Брилле, отвечающий за безопасность Тирисфальских лесов и руководящий стратегическими наступлениями от имени Сильваны Ветрокрылой.",al={"zygand","executor zygand brill","зуганд","палач зуганд брилл"}}},fp="31,261,23.348.0,30.322.0,23.195.0,58.176.0,53.254.0,62.220.0,58.188.0,23.179.0"}
P.entries["quest:371"] = {n="Война с Алым орденом",s="Эта военная операция поручает защитникам Отрекшихся нанести удар по лагерю Алого ордена возле Фермы Балнира на юго-востоке Тирисфальских лесов. По приказу Палача Зуганда игроки уничтожают капитана Вакона и сопровождающих его монахов, чтобы остановить набеги крестоносцев на владения Темной Госпожи.",h="Эта военная операция поручает защитникам Отрекшихся нанести удар по лагерю Алого ордена возле Фермы Балнира...",kw={"arren","balnir","brill","crusader","friar","tirisfal","tower","vachon","zygand","аррен","балнир","брилл","крестоносец","монах","тирисфаль","башня","вакон","зуганд"},ang={["class:Priest"]="Схватка с монахами Алого ордена противопоставляет ваше владение Тьмой и искаженной силой Света догматичному, непреклонному фанатизму людей.",["faction:Horde"]="Уничтожение фанатиков Алого ордена держит открытым путь к Подгороду и обеспечивает связь Орды через север Лордерона.",["race:Undead"]="Каждый зачищенный пост крестоносцев в Тирисфальских лесах укрепляет границы вашего юного народа и защищает владения леди Сильваны от живых «очистителей»."},sec={{t="Надвигающаяся угроза",b="Пока Отрекшиеся стараются обезопасить периметр вокруг Брилла и Подгорода, Алый орден удерживает укрепленные очаги по всей округе. Донесения Палача Аррена, поступающие в город, предупреждают военное командование о нападениях крестоносцев из полуразрушенной сторожевой башни на юго-востоке Тирисфальских лесов, неприятно близко к заброшенной Ферме Балнира."},{t="Разрыв цепи командования",b="Понимая, что неорганизованные фанатики куда менее опасны, чем сплоченные отряды, Палач Зуганд направляет удар на их полевое руководство. Уничтожив капитана Вакона и монахов Алого ордена, усиливающих его людей священной магией, Отрекшиеся стремятся разрушить слаженность этой ячейки и подавить набеги людей на соседние земли Отрекшихся."}},faq={{q="Кто отдает приказ об этом ударе?",a="Приказ отдает Палач Зуганд, находящийся в городе Брилл. Он действует на основе разведданных с передовой, которые собрал и доставил Палач Аррен о передвижениях ордена возле Фермы Балнира.",al={"quest giver","who gives this quest","who is zygand","персонаж, выдающий задания","кто дает это задание","кто такой зуганд"}},{q="Где находится капитан Вакон?",a="Капитан Вакон и его свита монахов Алого ордена расположились в разрушенной сторожевой башне на юго-востоке Тирисфальских лесов, к востоку от Фермы Балнира.",al={"vachon location","where is vachon","where are scarlet friars","где вакон","местонахождение вакона","где монахи алого ордена"}},{q="Почему Палач Зуганд нацелился именно на монахов Алого ордена?",a="Монахи Алого ордена оказывают рядовым фанатикам важную магическую и духовную поддержку. Уничтожив их заклинателей, отряд ордена лишается защитных чар и исцеления, и его действия в поле оказываются полностью парализованы.",al={"why kill friars","scarlet friars","зачем убивать монахов","монахи алого ордена"}},{q="Какую угрозу для Брилла представляет разрушенная башня?",a="Башня дает Алому ордену хороший обзор и укрепленную точку для вылазок. Оттуда патрули крестоносцев легко могут устраивать засады на путников из числа Отрекшихся и нарушать снабжение по дорогам, ведущим на восток от Брилла.",al={"tower threat","why attack tower","balnir tower","угроза башни","зачем атаковать башню","башня балнира"}},{q="Как это связано с общим конфликтом с орденом?",a="Эта задача — третий этап тактической кампании Палача Зуганда по планомерному искоренению оплотов Алого ордена в Тирисфальских лесах: фанатиков нужно отбросить прежде, чем они осадят Подгород.",al={"scarlet war chain","war with the scarlet crusade lore","цепочка войны с алым орденом","война с алым орденом"}},{q="Что происходит после гибели капитана Вакона?",a="Хотя поражение Вакона замедляет продвижение крестоносцев на юго-востоке Тирисфаля, Палач Зуганд тут же обращает внимание на более крупные укрепления Алого ордена в других частях региона.",al={"next quest","what after vachon","vachon aftermath","следующее задание","что после вакона","последствия гибели вакона"}}},fp="31,311,22.384.0,29.365.0,23.197.0,32.149.0,60.235.0,48.217.0,61.221.0,43.184.0"}
P.entries["quest:372"] = {n="Война с Алым орденом",s="Это задание — завершение ранней кампании Палача Зуганда по защите Тирисфальских лесов от вторжений Алого ордена. Из Брилла агентов Отрекшихся направляют нанести удар прямо по капитану Мелраше и его личному авангарду в разрушенной сторожевой башне за Могилой Фаола.",h="Это задание — завершение ранней кампании Палача Зуганда по защите Тирисфальских лесов от вторжений Алого...",kw={"brill","captain melrache","executor zygand","faol's rest","scarlet bodyguard","scarlet crusade","tirisfal glades","брилл","капитан мелраше","палач зуганд","могила фаола","телохранитель алого ордена","алый орден","тирисфальские леса"},ang={["class:Rogue"]="Глубокий удар за линию врага, чтобы отрезать командира от его войска, — настоящее ремесло Стражей смерти.",["faction:Horde"]="Защита границ Тирисфаля оберегает уязвимый плацдарм Орды в Восточных королевствах.",["race:Undead"]="Для Отрекшихся каждый убитый крестоносец — на одного фанатика меньше, отрицающего их право на существование на родине, где они жили при жизни."},sec={{t="Удар по авангарду",b="Пока Отрекшиеся укрепляют власть над руинами Лордерона, Алый орден неустанно прощупывает границы Тирисфаля. Из сторожевой башни на возвышенности на севере Тирисфаля, за Могилой Фаола, ревностные крестоносцы организуют рейды против патрулей и земель Отрекшихся. Вместо того чтобы ждать очередного нападения, Палач Зуганд выбирает обезглавливание: уничтожить командование, направляющее местные набеги."},{t="Оплот капитана Мелраше",b="Этим северным лагерем командует капитан Мелраше, непреклонный офицер, которого неизменно сопровождают два верных телохранителя. Позиция Мелраше дает ордену обзор прибрежных дорог и окрестных лесов. Его смерть нарушает слаженность крестоносцев возле Брилла, устраняет прямую угрозу юному королевству леди Сильваны и отбрасывает фанатиков к более сильным укреплениям на востоке."}},faq={{q="Кто такой капитан Мелраше?",a="Капитан Мелраше — полевой командир Алого ордена, возглавляющий лагерь налетчиков в разрушенной башне на севере Тирисфальских лесов, за Могилой Фаола. Он вместе с личными телохранителями ведет агрессивные вылазки на земли Отрекшихся.",al={"melrache","captain melrache lore","who is the scarlet captain","мелраше","капитан мелраше","кто такой капитан алого ордена"}},{q="Где находится разрушенная башня?",a="Башня стоит в северной глуши Тирисфальских лесов, на утесах сразу за кладбищем Могила Фаола, с видом на северное побережье.",al={"melrache location","where is the tower","faol's rest tower","где мелраше","где башня","башня у могилы фаола"}},{q="Почему Палач Зуганд хочет смерти Мелраше?",a="Отряд Мелраше постоянно совершает набеги из своей башни, донимает войска Отрекшихся и угрожает безопасности Брилла и Подгорода. Зуганд приказывает убить его, чтобы сломить наступательный порыв ордена в этой местности.",al={"why kill melrache","zygand's motive","зачем убивать мелраше","мотив зуганда"}},{q="Как этот бой связан с большой войной против Артаса?",a="Палач Зуганд считает Алый орден опасным отвлечением. Устранение агрессивных офицеров ордена позволяет Отрекшимся укрепить контроль над Тирисфалем и сберечь силы для главной мести Королю-личу.",al={"arthas connection","why mention arthas","связь с артасом","при чем здесь артас"}},{q="Очищает ли гибель Мелраше Тирисфаль от Алого ордена?",a="Нет. Смерть Мелраше уничтожает ближайшую ячейку налетчиков и ослабляет давление на Брилл с севера, но поблизости у ордена остаются мощные оплоты, в том числе Монастырь Алого ордена на востоке.",al={"is scarlet crusade defeated","do they leave tirisfal","разбит ли алый орден","уйдут ли они из тирисфаля"}},{q="Что такое Могила Фаола?",a="Могила Фаола — уединенное, торжественное место захоронения на севере Тирисфаля, названное в честь Алонсуса Фаола, бывшего архиепископа Церкви Священного Света. Башня Мелраше стоит в суровых холмах сразу за ним.",al={"faols rest","faol resting place","могила фаола","место упокоения фаола"}}},fp="31,296,24.448.0,23.443.0,24.239.0,34.157.0,44.236.0,60.234.0,62.196.0,20.205.0"}
P.entries["quest:373"] = {n="Неотправленное письмо",s="Запечатанное письмо, найденное на теле Эдвина ван Клифа в глубинах Мертвых копей, адресовано Баросу Алекстону, главному архитектору Штормграда. Его доставка приоткрывает личные обиды и общую историю, связывающие главаря Братства Справедливости с мастерами-строителями города.",h="Запечатанное письмо, найденное на теле Эдвина ван Клифа в глубинах Мертвых копей, адресовано Баросу...",kw={"baros alexston","cathedral square","city hall","deadmines","defias","edwin vancleef","stonemasons","unsent letter","барос алекстон","соборная площадь","ратуша","мертвые копи","братство справедливости","эдвин ван клиф","каменщики","неотосланное письмо"},ang={["class:Rogue"]="Среди разбойников ван Клиф был легендой как непревзойденный боец и организатор; его личная переписка наглядно показывает, как легко дисциплина оперативника перерождается в самоубийственную одержимость.",["faction:Alliance"]="Доставка письма дает важное доказательство того, что угроза Братства Справедливости — не просто местное восстание вне закона, а целенаправленная вендетта с глубокими связями в гражданской администрации Штормграда.",["race:Human"]="Для людей Штормграда это письмо обнажает незажившие раны восстановления королевства и доказывает, что разбой, терзающий Западный Край, родился из политических предательств в их собственной столице."},sec={{t="Послание из могилы",b="Когда Эдвин ван Клиф падает на борту своего корабля в подземных глубинах Луноречья, он оставляет после себя не только разбитое восстание. В его одежде спрятано свежее запечатанное письмо. Странно, но главарь Братства Справедливости адресовал его не кому-то из своих преступных помощников или тайных покровителей, а чиновнику в сердце королевства, которое поклялся уничтожить: Баросу Алекстону, главному архитектору Штормграда."},{t="Архитекторы былых времен",b="Доставка письма в ратушу на Соборной площади раскрывает общее прошлое архитектора и разбойника. Алекстон, некогда равный ван Клифу в годы амбициозного восстановления Штормграда после Второй войны, не верит известию о смерти Эдвина. Хотя его ужасает падение главаря бандитов в бессмысленное насилие, Алекстон признает корень его горького похода: ван Клиф был непреклонным идеалистом, раздавленным предательством, и его справедливая обида переросла в разрушительное безумие."}},faq={{q="Где найти Неотосланное письмо?",a="Предмет «Неотосланное письмо» выпадает из Эдвина ван Клифа, последнего босса на броненосном корабле в подземелье Мертвые копи в Западном Крае.",al={"unsent letter drop","how to get unsent letter","who drops unsent letter","неотосланное письмо","как получить неотосланное письмо","у кого выпадает неотосланное письмо"}},{q="Кто такой Барос Алекстон?",a="Барос Алекстон — главный архитектор Штормграда. Он живет в здании ратуши на северо-восточном краю Соборной площади.",al={"baros alexston location","where is baros alexston","city architect stormwind","где барос алекстон","местонахождение бароса алекстона","главный архитектор штормграда"}},{q="Почему Эдвин ван Клиф писал главному архитектору?",a="Ван Клиф и Алекстон были собратьями-каменщиками и вместе восстанавливали Штормград после Второй войны. Даже ступив на путь разбоя, ван Клиф по-прежнему считал Алекстона бывшим товарищем, причастным к делу и предательству Гильдии каменщиков.",al={"why write baros","vancleef and baros relationship","letter to architect","зачем писать баросу","отношения ван клифа и бароса","письмо архитектору"}},{q="Что письмо раскрывает о ван Клифе?",a="Прочитав его, Алекстон отмечает, что ван Клиф до конца остался идеалистом и романтиком, но насквозь отравленным местью. Ван Клиф считал свою жестокую войну против королевства полностью оправданной отказом знати платить каменщикам.",al={"vancleef motive","what does the letter say","letter lore","мотив ван клифа","что в письме","предания письма"}},{q="Нужно ли пройти всю цепочку Братства Справедливости, прежде чем сдать это задание?",a="Нет. Хотя длинная цепочка заданий о Братстве Справедливости ведет прямо к ван Клифу, Неотосланное письмо может забрать и сдать любой искатель приключений Альянса, победивший его, независимо от прежнего прогресса в заданиях.",al={"quest prerequisite","can i do unsent letter early","do i need defias chain","требования к заданию","можно ли взять неотосланное письмо раньше","нужна ли цепочка братства справедливости"}},{q="Куда ведет эта цепочка заданий дальше?",a="Получив письмо, Алекстон направляет вас в Тюрьму допросить плененного главаря Братства Справедливости Базиля Тредда, который может знать больше о планах ван Клифа.",al={"next quest after unsent letter","lescovar chain","what follows baros alexston","следующее задание после неотосланного письма","цепочка лесковара","что дальше после бароса алекстона"}}},fp="17,283,24.417.0,17.538.1,34.141.0,22.142.0,53.249.0,43.264.0,77.208.0,36.174.1"}
P.entries["quest:374"] = {s="Доказательство верности — военный приказ Стража смерти Буржеса в Брилле, цель которого — сократить ряды Алого ордена в Тирисфальских лесах. Он был отдан по распоряжению Вариматраса, демонического лейтенанта Сильваны Ветрокрылой, и проверяет преданность солдата делу Отрекшихся. Рекрутам приказано снимать с павших крестоносцев перстни-печатки как вещественное доказательство их убийства.",h="Доказательство верности — военный приказ Стража смерти Буржеса в Брилле, цель которого — сократить ряды Алого...",kw={"brill","dark lady","deathguard burgess","executor zygand","proof of demise","scarlet crusade","scarlet insignia ring","tirisfal glades","varimathras","брилл","темная госпожа","страж смерти буржес","палач зуганд","доказательство верности","алый орден","перстень алого ордена","тирисфальские леса","вариматрас"},ang={["faction:Horde"]="Это задание показывает безжалостный настрой на тотальную войну, свойственный режиму Сильваны на севере, который отчасти направляет лорд ужаса Вариматрас.",["race:Undead"]="Для Отрекшихся каждый перстень крестоносца, принесенный в Брилл, означает одним фанатиком меньше из тех, кто поклялся очистить Лордерон от свободных волей нежити."},sec={{t="Поручение лорда ужаса",b="Кампания на севере Тирисфальских лесов не просто оборонительная, а скоординированная война на истребление. Вариматрас, лорд ужаса, который сдался и присягнул на верность Сильване Ветрокрылой, руководит многими наступательными операциями Отрекшихся против живых. Его указания передаются командирам, таким как Палач Зуганд, и офицерам на передовой, таким как Страж смерти Буржес. Буржес ясно излагает приказ: люди считаются паразитами, которых нужно изгнать из Лордерона, а фанатики-крестоносцы поблизости — ближайшая цель."},{t="Трофеи резни",b="Одних слов командирам Брилла недостаточно. Чтобы доказать покорность Темной Госпоже и ее помощнику, солдаты должны снимать перстни Алого ордена прямо с пальцев убитых фанатиков. Эти перстни несут символику Алого ордена и отмечают владельцев как заклятых врагов Отрекшихся. Горсть таких трофеев — неоспоримое доказательство гибели крестоносцев и свидетельство безоговорочной верности."}},faq={{q="Кто дает задание собрать эти перстни?",a="Приказ отдает Страж смерти Буржес, страж Отрекшихся, расквартированный в городке Брилл. Он действует по донесениям Палача Зуганда и следует общим военным целям, поставленным Вариматрасом.",al={"who gives proof of demise","quest giver","deathguard burgess quest","кто дает доказательство верности","персонаж, выдающий задания","задание стража смерти буржеса"}},{q="Почему Буржес требует именно перстни Алого ордена?",a="Перстни Алого ордена — неопровержимое вещественное доказательство гибели крестоносца. Фанатики носят их при себе, поэтому они удобные и бесспорные военные трофеи, подтверждающие преданность солдата руководству Отрекшихся.",al={"why rings","scarlet rings purpose","what are insignia rings","зачем перстни","назначение перстней алого ордена","что за перстни-печатки"}},{q="Кто такой Вариматрас и почему он упоминается?",a="Вариматрас — лорд ужаса, ставший союзником королевы Сильваны Ветрокрылой после того, как Отрекшиеся освободились от Короля-лича. Сейчас он служит ее главным помощником в Подгороде и руководит военной стратегией против уцелевших человеческих поселений в Лордероне, включая Алый орден.",al={"who is varimathras","dreadlord in undercity","why varimathras","кто такой вариматрас","лорд ужаса в подгороде","почему вариматрас"}},{q="Где находятся крестоносцы Алого ордена для этого задания?",a="Фанатики Алого ордена держат несколько вооруженных лагерей в Тирисфальских лесах, особенно возле своих сторожевых башен, гарнизонов и застав в северной и восточной частях лесов.",al={"where to find scarlet crusade","scarlet crusader locations","crusader camps tirisfal","где найти алый орден","расположение крестоносцев алого ордена","лагеря крестоносцев тирисфаль"}},{q="Как это связано с приказами Палача Зуганда?",a="Палач Зуганд руководит из Брилла общей кампанией против Алого ордена. Пока Зуганд направляет новобранцев на подрыв присутствия крестоносцев в поле, Буржес требует личные трофеи как доказательство покорности непосредственно Вариматрасу и Темной Госпоже.",al={"executor zygand connection","at war with the scarlet crusade link","связь с палачом зугандом","война с алым орденом"}},{q="Почему руководство Отрекшихся так враждебно к Алому ордену?",a="Алый орден считает всех мертвецов мерзостями, обреченными на священный огонь, и не различает безмозглую Плеть и свободных волей Отрекшихся. Поскольку орден яростно охотится на Отрекшихся у их границ, Сильвана и ее офицеры видят в нем смертельную угрозу, которую необходимо уничтожить.",al={"why fight scarlet crusade","forsaken vs scarlet crusade","why do forsaken hate humans","почему воевать с алым орденом","отрекшиеся против алого ордена","почему отрекшиеся ненавидят людей"}}},fp="15,380,28.552.0,19.449.0,44.188.0,60.252.0,43.285.0,54.187.0,50.270.0,65.325.0"}
P.entries["quest:3741"] = {n="Ожерелье Ниды",s="Рыбача на причале Приозерья, юная Нида потеряла дорогое ожерелье, подаренное отцом. Родители запретили детям соваться в опасные воды Озера Безмолвия, поэтому ее друг Шоун просит проходящих искателей приключений нырнуть и достать затонувшую памятную вещь.",h="Рыбача на причале Приозерья, юная Нида потеряла дорогое ожерелье, подаренное отцом.",kw={"effsee","glinting mud","lake everstill","lakeshire","necklace","nida","redridge","shawn","эффси","блестящий ил","озеро безмолвия","приозерье","ожерелье","нида","красногорье","шоун"},ang={["faction:Alliance"]="Помощь осажденным жителям Приозерья в мелких личных бедах подтверждает стремление Альянса защищать простых горожан, а не только бороться с крупными стратегическими угрозами."},sec={{t="День на причале",b="Дети Приозерья часто проводят дни за рыбалкой на берегу озера, стараясь сохранить обычное детство среди растущих угроз, окружающих Красногорье. Во время одной из таких вылазок юная Нида случайно уронила любимое ожерелье в глубины Озера Безмолвия. Безуспешно обыскав деревянные мостки и берега, ее друг Шоун обращается за помощью к умелым искателям приключений."},{t="Опасности Озера Безмолвия",b="Родители в городке строго запрещают детям плавать в озере, и не зря. В Озере Безмолвия полно агрессивных мурлоков и голодных пороговых акул, подстерегающих у самой поверхности. Паре деревенских ребятишек не достать вещь, потерянную в блестящем иле на дне, так что единственная надежда вернуть семейный подарок — помощь со стороны."}},faq={{q="Кто потерял ожерелье?",a="Ожерелье принадлежит Ниде, девочке из Приозерья. Это особый подарок от ее отца, поэтому потеря так ее огорчает.",al={"who is nida","who lost it","necklace owner","кто такая нида","кто потерял","владелец ожерелья"}},{q="Почему Шоун и Нида не могут сами нырнуть за ним?",a="Родители строго запрещают им плавать в Озере Безмолвия из-за опасностей под водой. Агрессивные мурлоки и хищные пороговые акулы делают воды слишком опасными для детей без присмотра.",al={"why not get it themselves","why kids not swimming","почему не достать самим","почему дети не плавают"}},{q="Куда попало ожерелье?",a="Ожерелье соскользнуло с причала и осело в куче блестящего ила на западном дне Озера Безмолвия.",al={"necklace location","where is necklace","where did it fall","местонахождение ожерелья","где ожерелье","куда упало"}},{q="Кто такая Эффси?",a="Эффси — домашняя кошечка Ниды, которая составляет ей компанию в Приозерье и охотно вместе с ней благодарит путников, вернувших ожерелье.",al={"effsee","nida cat","эффси","кошка ниды"}},{q="Кто просит найти ожерелье?",a="Шоун, друг Ниды, который рыбачил вместе с ней на причале, обращается к путникам от ее имени, потому что знает, как дорог ей этот подарок.",al={"who gives quest","shawn role","кто выдает задание","роль шоуна"}},{q="Почему это задание важно для Приозерья?",a="Хотя оно просто по сравнению с борьбой с гноллами или орками Черной горы, такие мелкие услуги дают уют и обыденность семьям, пытающимся мирно жить в городке под постоянной угрозой.",al={"lakeshire importance","why help kids","важность приозерья","зачем помогать детям"}}},fp="15,274,18.404.0,24.369.0,22.158.0,56.219.0,30.118.0,14.132.0,44.148.0,39.190.0"}
P.entries["quest:375"] = {n="Смертельный холод",s="В городке Брилл Отрекшаяся портниха Гретхен Дедмар борется с подкрадывающимся холодом смерти и тлена. Боясь, что наступающее безумие лишит ее возможности служить леди Сильване, она просит простые материалы, чтобы сшить себе теплое одеяло.",h="В городке Брилл Отрекшаяся портниха Гретхен Дедмар борется с подкрадывающимся холодом смерти и тлена.",kw={"brill","chill of death","coarse thread","duskbat pelt","gretchen dedmar","mindless state","plague of undeath","tirisfal glades","брилл","смертельный холод","грубая нить","шкурка сумеречной летучей мыши","гретхен дедмар","безмозглое состояние","чума нежизни","тирисфальские леса"},ang={["profession:Tailoring"]="Гретхен полагается на скромное рукоделие: она шила мешки для тел армии Сильваны, а теперь взялась за иглу, чтобы сделать простое одеяло из шкур.",["race:Undead"]="Борьба Гретхен — мрачное напоминание всем Отрекшимся, что освобождение от Короля-лича не защищает от телесного гниения и вечной угрозы безумия."},sec={{t="Подкрадывающийся холод",b="Для Отрекшихся нежизнь — не неизменное состояние вечной сохранности. По словам Гретхен Дедмар, не отступающая Чума нежизни пробегает по ее телу ледяной змеей, отнимая тепло из конечностей и грозя затянуть в безмозглое состояние, поражающее многих бродячих мертвецов в Тирисфальских лесах. Из-за дрожащих рук обычная работа почти невозможна."},{t="Служение Темной Госпоже",b="Несмотря на слабеющие силы, Гретхен отказывается оставить свой долг перед королевством Отрекшихся. Когда Сильвана Ветрокрылая впервые собрала освобожденных мертвецов, Гретхен шила погребальные саваны и мешки для тел павших солдат. Принося прочные шкурки сумеречных летучих мышей и грубую нить, путники помогают ей удерживать руки достаточно твердыми, чтобы сшить одеяло и продлить свою полезную службу делу Отрекшихся."}},faq={{q="Кто такая Гретхен Дедмар?",a="Гретхен Дедмар — Отрекшаяся, живущая в Брилле. Раньше она помогала зарождающимся военным усилиям Отрекшихся, сшивая мешки для тел павших бойцов леди Сильваны.",al={"gretchen dedmar","who is gretchen","brill tailor questgiver","гретхен дедмар","кто такая гретхен","портниха брилла"}},{q="Что такое «безмозглое состояние», которого боится Гретхен?",a="Безмозглое состояние — это умственный и телесный распад, настигающий некоторых мертвецов, когда иссякают остатки воли и некротической энергии, и они превращаются в диких бредущих существ, подобных тем, что бродят возле Брилла и Могильника.",al={"what is mindless state","why is gretchen losing her mind","forsaken becoming mindless","что такое безмозглое состояние","почему гретхен теряет рассудок","отрекшиеся теряют разум"}},{q="Почему Гретхен мерзнет, если она мертва?",a="Хотя в телах нежити нет живого кровообращения, Гретхен ощущает подкрадывающуюся чуму в жилах как неодолимый леденящий холод, от которого цепенеют суставы и дрожат руки.",al={"can undead feel cold","why are undead cold","chill of death meaning","чувствует ли нежить холод","почему нежить холодная","смертельный холод значение"}},{q="Зачем ей шкурки сумеречных летучих мышей и нить?",a="Гретхен нужны пять шкурок сумеречных летучих мышей и грубая нить, чтобы сшить толстое одеяло. Она надеется, что дополнительное тепло сохранит ее дрожащие руки послушными и она сможет продолжать работу.",al={"why duskbat pelts","what is the blanket for","зачем шкурки летучих мышей","для чего одеяло"}},{q="Где можно найти сумеречных летучих мышей?",a="Сумеречные летучие мыши гнездятся в лесах и на открытых полянах вокруг Брилла и на севере Тирисфаля.",al={"where are duskbats","duskbat pelt location","где сумеречные летучие мыши","где взять шкурки летучих мышей"}},{q="Связано ли это задание с другими поручениями в Брилле?",a="Это отдельное задание по помощи нуждающемуся жителю Брилла, показывающее тихие личные трудности недавно освобожденных Отрекшихся.",al={"chill of death follow up","gretchen dedmar chain","смертельный холод продолжение","цепочка гретхен дедмар"}}},fp="18,278,16.386.0,24.401.0,23.174.0,44.231.0,43.190.0,43.180.0,28.92.0,53.146.0"}
P.entries["quest:376"] = {n="Проклятые",s="«Проклятые» — начальное задание, которое Новобранец Элрет дает только что пробудившимся Отрекшимся в часовне Могильника. В обмен на материалы для грубой одежды и боевых повязок Элрет выдает годную к использованию броню, чтобы защитить молодую нежить от опасностей вокруг кладбища.",h="«Проклятые» — начальное задание, которое Новобранец Элрет дает только что пробудившимся Отрекшимся в часовне...",kw={"deathknell","duskbat wing","forsaken","novice elreth","scavenger paw","shadow priest sarvis","the damned","tirisfal glades","могильник","крыло сумеречной летучей мыши","отрекшиеся","новобранец элрет","лапа падальщика","жрец тени сарвис","проклятые","тирисфальские леса"},ang={["profession:Tailoring"]="Новобранец Элрет подчеркивает суровую необходимость полевого шитья в Лордероне, где перепонки крыльев и добытые шкуры заменяют чистую ткань.",["race:Undead"]="Для свежих Отрекшихся это задание — раннее проявление мрачной практичности их народа: выжить означает снимать снаряжение с павших предшественников и жить тем, что дает оскверненная земля."},sec={{t="Практичный обмен",b="Пробуждение в нежизни оставляет мало места тщеславию и сентиментальности. Новобранец Элрет принимает непрерывный поток свежих Отрекшихся, вытащенных из земли Могильника, и помогает жрецу Тени Сарвису. Между уходом за израненными солдатами и починкой одежды запасы опасно истощаются. Чтобы новички не развалились в первых испытаниях, Элрет отправляет их на окрестные поляны охотиться на местных сумеречных летучих мышей и волков-падальщиков, обменивая трофейную броню на сырые шкуры, крылья и жилы, необходимые для жизни лагеря."},{t="Унаследованная защита",b="Броня, которую предлагает Элрет, далека от безупречной кузнечной работы: это обноски, снятые с тех, кто не пережил пробуждения. Ее мрачные прощальные слова — надежда, что одежда послужит новому владельцу лучше, чем прежнему, — отражают холодный расчет выживания Отрекшихся. В Тирисфальских лесах ничто не пропадает, и каждый кусок кожи и ржавая кольчуга уже пережили как минимум одного мертвеца."}},faq={{q="Кто такой Новобранец Элрет?",a="Новобранец Элрет — аколит, находящийся в часовне Могильника. Она помогает жрецу Тени Сарвису: ухаживает за ранеными Отрекшимися, шьет полевое снаряжение и экипирует новых рекрутов, прежде чем их отправят навстречу опасности.",al={"novice elreth","who gives the damned quest","elreth","новобранец элрет","кто дает задание проклятые","элрет"}},{q="Зачем Элрет нужны лапы падальщиков и крылья сумеречных летучих мышей?",a="В Могильнике нет свежих поставок сырья. Элрет рассчитывает на местных тирисфальских животных, таких как сумеречные летучие мыши и волки-падальщики, чтобы добыть кожу, жилы и обрезки для починки обмундирования и перевязки раненых.",al={"why bat wings","why scavenger paws","elreth materials","зачем крылья летучих мышей","зачем лапы падальщиков","материалы элрет"}},{q="Откуда взялась броня в награду?",a="Броню снимают с павших рекрутов Отрекшихся, не переживших прежние стычки вокруг Могильника. Элрет пускает в дело все уцелевшее снаряжение, чтобы защитить следующую волну недавно восставших мертвецов.",al={"where does armor come from","elreth armor origin","откуда броня","происхождение брони элрет"}},{q="Где обитают эти существа?",a="Молодые падальщики и сумеречные летучие мыши гнездятся сразу к югу от Могильника. Несколько более сильные особи бродят к востоку, в сторону заставы Алого ордена.",al={"where to find scavengers","where are duskbats","duskbat locations","где найти падальщиков","где сумеречные летучие мыши","места обитания летучих мышей"}},{q="Как это задание связано с обороной Могильника?",a="Это основа полевой готовности. Жрец Тени Сарвис ждет, что все новоявленные Отрекшиеся будут сражаться с ближайшими угрозами, такими как безмозглая нежить и Алый орден, а Элрет следит, чтобы они выступили в прочной броне.",al={"why do this quest","deathknell defense","зачем это задание","оборона могильника"}},{q="Что происходит после помощи Новобранцу Элрет?",a="Умение пережить местных животных открывает новые задания вокруг Могильника: исполнить последнюю волю Марлы, разобраться с нашествием пауков в Паучьей низине и вернуть припасы по всему поселению.",al={"next quests after the damned","what comes after the damned","следующие задания после проклятых","что после проклятых"}}},fp="10,296,17.566.0,20.411.0,21.233.0,54.223.0,37.205.0,30.144.0,54.230.0,41.231.0"}
P.entries["quest:3765"] = {n="Проблема за морем",s="Аргос Шепот Ночи, ночной эльф, посланник, находящийся в Штормграде, ищет умелых искателей приключений, чтобы пересечь Великое море и помочь его брату на севере Калимдора. Его брат Гершал изучает распространяющийся экологический распад на Темных берегах, где свежие силы крайне необходимы.",h="Аргос Шепот Ночи, ночной эльф, посланник, находящийся в Штормграде, ищет умелых искателей приключений, чтобы...",kw={"argos","auberdine","corruption","darkshore","gershala","nightwhisper","stormwind","аргос","аубердин","порча","темные берега","гершал","шепот ночи","штормград"},ang={["faction:Alliance"]="Это поручение показывает зарождающиеся связи между ночными эльфами Калимдора и человеческим королевством Штормград за морем.",["race:Human"]="Путешествие на Темные берега дает людям-искателям приключений первое знакомство с древней культурой кальдораев, далекой от каменных замков Элвиннского леса.",["race:NightElf"]="Для ночных эльфов, оказавшихся вдали от дома, Аргос становится напоминанием о бедах, терзающих древние леса севера Калимдора."},sec={{t="Посланник в столице людей",b="Пока Штормград справляется с внутренними смутами и волнениями в регионах, по его каменным улицам можно встретить представителей далеких земель кальдораев. Аргос Шепот Ночи пришел в поисках опытных героев, готовых заглянуть за пределы человеческих границ. Кальдораи — относительно новые союзники Восточных королевств, формальной военной помощи мало, поэтому родственники и исследователи набирают тех независимых героев, кто откликнется на зов."},{t="Зов Темных берегов",b="Аргос указывает на Аубердин — туманный портовый городок на окутанном дымкой побережье Темных берегов. Там его брат Гершал проводит важные исследования зловещего недуга, поражающего местных животных и растения. Чтобы откликнуться на призыв, нужно совершить трудный путь на север через Болотину и пересечь Великое море — это первое настоящее знакомство путника с древними землями Калимдора."}},faq={{q="Кто такой Аргос Шепот Ночи?",a="Аргос Шепот Ночи — ночной эльф, гостящий в Штормграде. Он выступает своего рода посланником своей семьи и набирает опытных искателей приключений из Альянса, чтобы они отправились за море и помогли его брату Гершал на Темных берегах.",al={"argos","argos nightwhisper","who gives the corruption abroad","аргос","аргос шепот ночи","кто выдает задание проблема за морем"}},{q="Где находится Гершал Шепот Ночи?",a="Гершал Шепот Ночи находится в Аубердине — прибрежном поселении ночных эльфов на западном берегу Темных берегов на севере Калимдора.",al={"gershala location","where is gershala","turn in corruption abroad","где гершал","местонахождение гершал","сдать проблема за морем"}},{q="Почему Гершал нужна помощь?",a="Гершал исследует неестественную порчу, распространяющуюся по диким землям Темных берегов и поражающую местных животных, источники воды и растительность. Ему нужны опытные герои, чтобы собрать образцы и выяснить первопричину.",al={"why help gershala","what is wrong in darkshore","почему помочь гершал","что не так на темных берегах"}},{q="Как добраться из Штормграда в Аубердин?",a="Отправляйтесь на север из Штормграда через Подземный поезд в Стальгорн, пройдите через Дун Морог и Лок Модан в Болотину и сядьте в Гавани Менетилов на корабль, идущий в Аубердин на Темных берегах.",al={"how to reach auberdine","travel to darkshore from stormwind","как добраться до аубердина","путь на темные берега из штормграда"}},{q="Могу ли я выполнить это задание, если уже побывал на Темных берегах?",a="Если вы уже побывали в Аубердине и взяли у Гершал задание «Исследование порчи» напрямую у нее, вы больше не сможете взять или выполнить это вводное поручение от Аргоса.",al={"missed the corruption abroad","can i still do corruption abroad","пропустил проблема за морем","можно ли выполнить проблема за морем"}},{q="Кем друг другу приходятся Аргос и Гершал?",a="Аргос и Гершал Шепот Ночи — братья. Пока Гершал остается на передовой и изучает порчу на Темных берегах, Аргос отправился за море искать способных союзников в Штормграде.",al={"argos and gershala","are argos and gershala related","аргос и гершал","родственники ли аргос и гершал"}}},fp="21,260,29.443.0,21.434.0,26.241.0,39.148.0,28.237.0,41.205.0,51.184.0,52.192.0"}
P.entries["quest:377"] = {n="Преступление и наказание",s="«Преступление и наказание» — задание Альянса, начинающееся в Темнолесье: оно требует внесудебной казни расхитителя могил, заключенного в Тюрьме Штормграда. Член совета Миллстайп выдает заказ после того, как Дом знати отменил смертный приговор Сумеречного леса Декстрену Варду. Исполнение заказа утоляет жажду мести местных жителей и преподносит суровое предупреждение нерадивой столичной аристократии.",h="«Преступление и наказание» — задание Альянса, начинающееся в Темнолесье: оно требует внесудебной казни...",kw={"darkshire","dextren ward","duskwood","grave robber","house of nobles","millstipe","morbent fel","stockade","темнолесье","декстрен вард","сумеречный лес","расхититель могил","дом знати","миллстайп","морбент скверн","тюрьма"},ang={["class:Rogue"]="Поручение Миллстайпа — дерзкое политическое убийство, требующее скрытного проникновения в тюрьму строжайшего режима самой короны, чтобы обойти королевский указ.",["faction:Alliance"]="Задание вскрывает серьезные трения в сердце Альянса: бедствующее, заброшенное пограничье Темнолесья противостоит далеким высокомерным бюрократам Дома знати.",["race:Human"]="Для людей южных королевств этот заказ проверяет, на чьей вы стороне: далекой короны в Штормграде или отчаянных поселенцев, держащих рубеж в Сумеречном лесу."},sec={{t="Правосудие, которого не случилось, в Сумеречном лесу",b="Сумеречный лес и без того страдает от подкрадывающихся ужасов и равнодушия столицы. Когда Декстрена Варда поймали на раскапывании свежих трупов на кладбище Темнолесья, чтобы продать их некроманту Морбенту Скверну, правящий совет города не проявил милосердия. Лорд Элло Чернодрев приговорил расхитителя могил к отсечению головы. Но прежде чем упал топор, вмешался Дом знати, объявив Варда государственным узником и переведя его в строго охраняемые камеры Тюрьмы Штормграда."},{t="Оскорбление мертвых",b="Для члена совета Миллстайпа и скорбящих жителей Темнолесья спасение Варда от плахи было невыносимым оскорблением. Знать в своем защищенном городе полностью пренебрегла мучениями семей с границы, чьих умерших родных пустили на темное ремесло Скверна. Раздосадованный бюрократическим вмешательством Штормграда, Миллстайп нанимает отважных наемников, чтобы проникнуть в мятежную Тюрьму, убить Варда в камере и отсечь ему руку как доказательство казни."},{t="Послание короне",b="Убийство Варда — столько же политический акт, сколько и возмещение для пострадавших. Заказав убийство ценного узника, находящегося под замком самой короны, совет Темнолесья посылает Штормграду вызывающее послание. Если знать отказывается защищать Сумеречный лес и чтить его местные законы, город показал, что вершит собственное пограничное правосудие прямо под носом у регента."}},faq={{q="Почему член совета Миллстайп хочет смерти Декстрена Варда?",a="Варда поймали на разграблении кладбища Темнолесья: он продавал свежезахороненные трупы некроманту Морбенту Скверну. Лорд Чернодрев приговорил его к отсечению головы, но Дом знати Штормграда забрал его и заключил в Тюрьму.",al={"why kill dextren ward","what did dextren ward do","millstipe motivation","почему убить декстрена варда","что сделал декстрен вард","мотив миллстайпа"}},{q="Где находится Декстрен Вард?",a="Он содержится в глубине подземелья Тюрьма Штормграда в столице, в самом левом коридоре тюремного комплекса.",al={"dextren ward location","where is ward","how to find dextren ward","где декстрен вард","где вард","как найти декстрена варда"}},{q="Почему Штормград просто не казнил Декстрена Варда?",a="Дом знати присвоил себе юрисдикцию над Вардом по собственным нераскрытым причинам, отменив приговор Темнолесья и вызвав возмущение жителей Сумеречного леса, которые чувствуют себя брошенными столицей.",al={"why was ward imprisoned","why stockade not execution","почему вард в тюрьме","почему тюрьма а не казнь"}},{q="Почему Миллстайп требует руку Варда?",a="Член совета Миллстайп требует неопровержимого вещественного доказательства того, что приговор приведен в исполнение вопреки Дому знати, чтобы дать успокоение пострадавшим семьям Сумеречного леса.",al={"hand of dextren ward","why hand proof","рука декстрена варда","зачем рука доказательство"}},{q="Кто такой Морбент Скверн?",a="Морбент Скверн — могущественный некромант, обитающий в Сумеречном лесу: он оживляет мертвых и устраивает темные ритуалы, используя тела, которые поставляют беспринципные мерзавцы вроде Декстрена Варда.",al={"who is fel","morbent fel lore","кто такой скверн","морбент скверн предания"}},{q="Что это задание говорит об отношениях Сумеречного леса и Штормграда?",a="Оно показывает глубокую политическую обиду. Сумеречный лес чувствует себя заброшенным и незащищенным троном, а готовность совета отправить убийц в столичную тюрьму показывает, насколько натянутой стала эта верность.",al={"darkshire and stormwind politics","duskwood resentment","темнолесье и штормград политика","обида сумеречного леса"}}},fp="20,409,26.513.0,21.481.0,22.399.1,53.240.0,30.146.0,47.204.0,38.184.0,19.168.0,73.214.0"}
P.entries["quest:378"] = {s="Это задание отражает горькое стремление Мотли Каменщика отомстить дворфу из клана Черного Железа Каму Гневливому. Гневливый стал вдохновителем нападения на Мост Тандола, унесшего жизни защитников из Бронзобородов, включая брата Длиннокоса Мрачного. Недовольный политическим заключением виновного в Штормграде, Мотли нанимает искателя приключений, чтобы вершить дворфийское правосудие в Тюрьме.",h="Это задание отражает горькое стремление Мотли Каменщика отомстить дворфу из клана Черного Железа Каму...",kw={"dark iron war","deepfury","dun modr","longbraid","motley garmason","roggo","stockade","thandol span","война черного железа","гневливый","дун модр","длиннокос","мотли каменщик","рогго","тюрьма","мост тандола"},ang={["faction:Alliance"]="Это задание подчеркивает скрытые противоречия между юридическим прагматизмом Штормграда и непреклонным требованием Стальгорна прямой мести в военное время.",["race:Dwarf"]="Для дворфов из Бронзобородов расправа над Гневливым — торжественное дело: расплатиться по долгу крови и почтить соклановцев, павших при защите Моста Тандола.",["race:Human"]="Искателям приключений из людей придется признать изъяны дипломатии собственного королевства и обойти тюремные порядки Штормграда, чтобы удовлетворить кодекс правосудия своих дворфийских союзников."},sec={{t="Вражда через континенты",b="Север Болотины истекает кровью от вечных стычек между защитниками из Бронзобородов в Дун Модре и мятежными дворфами из клана Черного Железа. Когда Мост Тандола подвергся нападению, диверсия унесла жизни важных дворфов, включая брата Длиннокоса Мрачного. Разведданные, собранные Рогго, показали, что коварный удар спланировал Кам Гневливый. Однако вместо казни на передовой Гневливый оказался под стражей в Тюрьме Штормграда — его держат как политического узника, а не казнят за убийство."},{t="Дворфийское возмездие против человеческого закона",b="Находясь в Дун Модре, Мотли Каменщик отказывается позволить политическим расчетам Штормграда защищать военного преступника. По мнению Мотли, человеческая бюрократия поставила приличия выше долгов крови. Будучи связан долгом оставаться рядом с Длиннокосом в Болотине, Мотли поручает доверенным героям пройти глубоко под человеческую столицу, пробиться через мятежную Тюрьму и принести отсеченную голову Гневливого, чтобы раз и навсегда свести счеты клана."}},faq={{q="Кто такой Кам Гневливый?",a="Кам Гневливый — вероломный дворф из клана Черного Железа, организовавший разрушительное нападение на Мост Тандола. Его замысел напрямую привел к резне дворфов Стальгорна, охранявших пограничную переправу, из-за чего среди выживших в Дун Модре он стал обреченным.",al={"deepfury","kam deepfury lore","who is deepfury","гневливый","кам гневливый предания","кто такой гневливый"}},{q="Почему Кам Гневливый заключен в Штормграде, а не в Стальгорне?",a="Власти Штормграда схватили Гневливого и держат его в Тюрьме по нераскрытым политическим причинам. Пока человеческое руководство предпочитает использовать его как рычаг в дипломатии или разведке, дворфы Дун Модра видят в этом возмутительную волокиту, лишающую их немедленного правосудия.",al={"why is deepfury in stockade","why stockade prisoner","почему гневливый в тюрьме","почему тюрьма узник"}},{q="Почему Мотли Каменщик сам не выследит Гневливого?",a="Мотли связан честью и воинским долгом оставаться в Дун Модре рядом с Длиннокосом Мрачным, отбивая продолжающееся наступление клана Черного Железа на севере Болотины. Он не может бросить оборонительную линию ради путешествия на юг, в Штормград.",al={"why motley stay","why motley doesn't go","почему мотли остается","почему мотли не идет"}},{q="Что произошло на Мосту Тандола?",a="Клан Черного Железа совершил расчетливое нападение на мост Тандола, соединяющий Болотину с Нагорьем Арати. Атака подорвала важную артерию снабжения Альянса и привела к гибели нескольких защитников из Бронзобородов, включая брата Длиннокоса.",al={"thandol span attack","what happened thandol span","нападение на мост тандола","что случилось на мосту тандола"}},{q="Кто раскрыл роль Гневливого в нападении на Мост Тандола?",a="Дворф по имени Рогго сложил воедино разведданные, напрямую связавшие Гневливого с планом и исполнением наступления на Мост Тандола, и вручил Мотли доказательство, нужное для требования возмездия.",al={"who found deepfury","roggo intelligence","кто нашел гневливого","рогго разведка"}},{q="Известно ли руководству Штормграда об убийстве в их тюрьме?",a="Приказ об убийстве — несанкционированная дворфийская вендетта. Мотли намеренно обходит человеческие законные пути, уверенный, что солдаты короля Магни вправе казнить диверсанта, пока Тюрьму охватил хаос мятежа.",al={"stormwind know about hit","is deepfury kill sanctioned","знает ли штормград об убийстве","санкционировано ли убийство гневливого"}}},fp="18,399,26.538.0,33.423.0,20.255.0,65.283.0,55.238.0,34.269.0,57.198.0,73.237.0"}
P.entries["quest:38"] = {n="Похлебка Западного Края",s="Похлебка Западного Края — сытный местный рецепт, который готовит Сальма Сальден на ферме Сальденов. Блюдо собрано из того, что дают суровая живность и места сбора пищи в Западном Крае, и воплощает стойкий дух выживания местных поселенцев.",h="Похлебка Западного Края — сытный местный рецепт, который готовит Сальма Сальден на ферме Сальденов.",kw={"goretusk snout","murloc eye","okra","saldean farm","salma saldean","vulture meat","westfall","westfall stew","рыло кабана-секача","глаз мурлока","окра","ферма сальденов","сальма сальден","мясо грифа","западный край","похлебка западного края"},ang={["faction:Alliance"]="Пока при дворе Штормграда наслаждаются тонкими винами и изысканной птицей, пограничные форпосты Альянса полагаются на такие простые блюда, чтобы поддерживать оборону от местных угроз.",["profession:Cooking"]="Блюдо Сальмы — образец простой пограничной кухни: оно учит начинающих поваров превращать грубую дичь, резко пахнущие рыла и необычные дары побережья в укрепляющую еду.",["race:Human"]="Для людей за пределами защитных стен Элвиннского леса такие блюда, как похлебка Западного Края, воплощают стойкость и выносливость, необходимые, чтобы добывать пропитание в забытой житнице королевства."},sec={{t="Необходимость для поселенца",b="Западный Край — суровое пограничье, истерзанное бандитами, голодом и разъяренными зверями, и у поселенцев почти нет доступа к богатым кладовым Штормграда. Семьи вроде Сальденов научились обходиться тем, что дает земля. Похлебка Сальмы Сальден превращает то, что многие горожане сочли бы вредителями или несъедобными объедками, в питательную еду, способную поддерживать силы работников фермы."},{t="Ингредиенты выживания",b="В рецепт входит необычная смесь пограничных припасов: местная окра, чтобы сгустить кипящий бульон, жилистое мясо падальщиков, добытое у кружащих грифов, и рыла диких кабанов-секачей, что роют землю на равнинах. Печально известнее всего свежие глаза мурлоков, собранные у прибрежных налетчиков. Мысль о том, чтобы есть речных тварей и падальщиков, вызывает отвращение у изнеженных жителей Элвиннского леса, но повара Западного Края клянутся, что странное сочетание дает наваристое и укрепляющее блюдо."}},faq={{q="Почему в рецепте используются глаза мурлоков?",a="Фермеры Западного Края постоянно испытывают нехватку ресурсов и часто подвергаются набегам агрессивных мурлоков на побережье и у рек. Сальма Сальден добавляет в бульон свежие глаза мурлоков ради особой сочности и вкуса, превращая угрозу в практичный источник пищи.",al={"murloc eyes in food","why eat murlocs","murloc stew","глаза мурлока в еде","зачем есть мурлоков","похлебка из мурлоков"}},{q="Кто такая Сальма Сальден?",a="Сальма Сальден — поселенка Альянса, живущая вместе с мужем, фермером Сальденом, на ферме Сальденов на севере Западного Края. Известная гостеприимством и кулинарной находчивостью, она кормит путников и работников фермы, несмотря на наступающее в регионе бандитство и хаос.",al={"salma","salma saldean lore","who makes westfall stew","сальма","сальма сальден предания","кто готовит похлебку западного края"}},{q="Откуда берется окра?",a="Окра — одна из немногих выносливых овощных культур, которые еще собирают на бедствующих фермах Западного Края. При варке ее стручки выделяют сок, и он служит незаменимым загустителем для похлебок поселенцев.",al={"where to find okra","saldean okra","okra origin","где найти окру","окра сальденов","происхождение окры"}},{q="Считается ли похлебка Западного Края хорошей едой?",a="Для утонченной знати Штормграда бульон с вареными рылами кабанов-секачей и глазами мурлоков звучит омерзительно. Но для нищих фермеров и усталых странников Западного Края это теплое, сытное и горячо любимое блюдо, дарящее уют.",al={"does westfall stew taste good","is westfall stew gross","вкусная ли похлебка западного края","отвратительна ли похлебка западного края"}},{q="Почему Сальденам нужны искатели приключений для сбора ингредиентов?",a="Западный Край стал чрезвычайно опасным. Дикие кабаны-секачи, агрессивные грифы и враждебные мурлоки бродят по полям и пляжам, и собирать припасы слишком опасно для обычных фермеров, которым нужно оставаться и защищать свой дом.",al={"why gather ingredients","why salma needs help","зачем собирать ингредиенты","зачем сальме нужна помощь"}},{q="Какое животное дает мясо для похлебки?",a="Похлебка в основном готовится из жилистого мяса грифов, падальщиков, парящих над Западным Краем, а также из рыл диких кабанов-секачей, на которых охотятся на равнинах.",al={"what meat is in westfall stew","westfall stew meat","какое мясо в похлебке западного края","мясо в похлебке западного края"}}},fp="13,241,25.406.0,27.463.0,36.267.0,21.271.0,30.199.0,38.224.0,63.229.0,43.169.0"}
P.entries["quest:380"] = {n="Паучья низина",s="Паучья низина — раннее поручение Палача Аррена: очистить от пауков золотой рудник к северо-западу от Могильника. Из-за острой нехватки сырья молодым Отрекшимся нужно богатство рудника, чтобы поддерживать поселение и военные усилия. Недавно восставших новобранцев отправляют в запутанную пещеру, чтобы шаг за шагом истреблять заразу паукообразных.",h="Паучья низина — раннее поручение Палача Аррена: очистить от пауков золотой рудник к северо-западу от...",kw={"deathknell","executor arren","forsaken","gold mine","night web spider","night web's hollow","tirisfal glades","undercity","могильник","палач аррен","отрекшиеся","золотой рудник","паук паучьей низины","паучья низина","тирисфальские леса","подгород"},ang={["faction:Horde"]="Обеспечение ресурсов в Тирисфальских лесах крайне важно, чтобы закрепить положение Отрекшихся как надежного северного оплота Орды.",["profession:Mining"]="Пещера — один из немногих ближайших к Могильнику источников золотой руды, хотя густая паутина и хищные пауки делают поиск опасным.",["race:Undead"]="Это задание показывает суровую реальность павших Лордерона, вернувшихся к существованию: для выживания нужны обычные материалы вроде металла и монет, а не только месть живым и Плети."},sec={{t="Народ, нуждающийся в монете",b="Выживание недавно восставших Отрекшихся — это не только защита от Плети и воинов Алого ордена. Для создания молодого общества нужны сырьевые ресурсы, а драгоценных металлов вроде золота на севере Лордерона не хватало даже в пору могущества Альянса. Палач Аррен, руководящий операциями в Могильнике, понимает, что Отрекшиеся не смогут вооружиться, снарядиться и утвердиться без обеспеченного богатства."},{t="Зараженный рудник",b="Сразу к северо-западу от кладбища лежит Паучья низина — природная пещера с пригодной для добычи золотой жилой. К несчастью, чудовищные паукообразные заполонили туннели, затянув глубины плотной паутиной и наполнив их смертельным ядом. Не имея опытных солдат для полной зачистки, Аррен полагается на свежих новобранцев, которые должны проредить молодых и взрослых пауков, пока горняки не смогут выжечь паутину и добыть руду."}},faq={{q="Зачем нежити золотой рудник?",a="Даже в нежизни Отрекшимся нужно оплачивать военные усилия, закупать припасы и восстанавливать поселения в Тирисфальских лесах. В Лордероне всегда не хватало природных ресурсов, а создание нового государства, независимого и от Альянса, и от Плети, требует ценной валюты для торговли и приобретения снаряжения.",al={"why do forsaken need gold","why gold in deathknell","undead gold mine","зачем отрекшимся золото","зачем золото в могильнике","рудник нежити"}},{q="Кто такой Палач Аррен?",a="Палач Аррен — высшая военная власть в Могильнике. Ему поручено организовать недавно восставшую нежить и обеспечить безопасность ближайших окрестностей, и он направляет новобранцев на важные задачи: охоту на остатки Плети, сбор припасов и освоение местных ресурсов.",al={"executor arren lore","who gives night webs hollow","arren role","палач аррен предания","кто дает задание паучья низина","роль аррена"}},{q="Где находится Паучья низина?",a="Низина расположена к северо-западу от главного поселения и кладбища Могильника, среди скалистых утесов, окружающих уединенную долину в Тирисфальских лесах.",al={"where is night webs hollow","spider cave deathknell","night web mine location","где паучья низина","паучья пещера могильник","расположение паучьего рудника"}},{q="Смогут ли Отрекшиеся добывать золото сразу после этого задания?",a="Не сразу. Палач Аррен отмечает, что на полное истребление заразы уйдут недели или месяцы упорных усилий, после чего рабочие выжгут факелами повсеместную паутину, и только тогда горняки смогут безопасно разрабатывать жилы.",al={"is the mine cleared","do they get the gold","what happens to the spiders","расчищен ли рудник","получат ли они золото","что будет с пауками"}},{q="Почему Аррен не отправит целый отряд солдат зачистить пещеру?",a="Гарнизон Могильника растянут: он охраняет границы от бездумной Плети, бродящей на окраинах, и патрулирует местность против разведчиков Алого ордена. У Аррена просто нет лишних людей, чтобы выделить обычный отряд на борьбу с вредителями, поэтому он поручает расчищать рудник понемногу недавно восставшим новобранцам.",al={"why send recruits","why not use deathknell guards","arren lack of manpower","зачем посылать новобранцев","почему не стража могильника","нехватка людей у аррена"}},{q="Может ли яд пауков навредить нежити?",a="Хотя Отрекшиеся не кровоточат и не дышат, как живые, едкий яд пауков все же может прожигать сохраненную плоть и ослаблять оживленные конечности. Палач Аррен особо предупреждает новобранцев следить за резким жжением от яда и искать помощь, если они отравлены.",al={"does venom hurt undead","forsaken spider poison","are forsaken immune to poison","вредит ли яд нежити","яд пауков отрекшиеся","иммунны ли отрекшиеся к яду"}}},fp="18,377,24.436.0,17.440.0,35.318.0,22.269.0,36.168.0,68.238.0,71.289.0,33.262.0"}
P.entries["quest:381"] = {n="Алый орден",s="Это раннее поручение Палача Аррена предписывает недавно пробудившимся Отрекшимся устроить засаду на лагерь фанатиков Алого ордена к юго-востоку от Могильника. Оно становится мрачным знакомством с одним из самых фанатичных и упорных врагов Отрекшихся.",h="Это раннее поручение Палача Аррена предписывает недавно пробудившимся Отрекшимся устроить засаду на лагерь...",kw={"deathknell","executor arren","scarlet armbands","scarlet converts","scarlet crusade","scarlet initiates","tirisfal glades","могильник","палач аррен","алые повязки","новообращенные алого ордена","алый орден","послушники алого ордена","тирисфальские леса"},ang={["class:Priest"]="Столкновение с Алым орденом заставляет жрецов Отрекшихся осознать, как Свет, который они чтили в Лордероне, был искажен до фанатичной ненависти.",["faction:Horde"]="Неослабевающая агрессия Алого ордена показывает, почему Отрекшиеся искали взаимную оборону и защиту, которые предлагает Орда.",["race:Undead"]="Для недавно восставших Отрекшихся это задание — ранний урок того, как их видят живые: как чудовищ, заслуживающих лишь истребления, независимо от свободной воли."},sec={{t="Фанатичная угроза",b="Когда непосредственная опасность нашествия пауков устранена, Палач Аррен обращает внимание Могильника на подступающую угрозу. Отряд Алого ордена закрепился к юго-востоку от поселения. Эти фанатики не признают различий между безмозглыми слугами Плети и свободными Отрекшимися, поэтому их присутствие у границы — смертельная угроза недавно восставшим мертвецам."},{t="Упреждающий ответ",b="Понимая, что диалог невозможен со святыми фанатиками, считающими всякую мертвую плоть мерзостью, Аррен приказывает нанести упреждающий удар. Искателей приключений посылают уничтожить послушников и новообращенных Алого ордена, пока лагерь не превратился в организованное передовое наступление на Могильник. Принесенные трофеи — их багровые повязки — служат наглядным доказательством того, что выживание в Тирисфале нужно завоевывать силой."}},faq={{q="Кто такие воины Алого ордена?",a="Алый орден — экстремистское религиозное движение, стремящееся полностью истребить нежить. Обезумев от горя и религиозного рвения после падения Лордерона, они не различают безмозглых чудовищ Плети и разумных Отрекшихся и стремятся уничтожить и тех, и других без разбора.",al={"scarlet crusade lore","what is the scarlet crusade","scarlet zealots","алый орден предания","что такое алый орден","фанатики алого ордена"}},{q="Почему Алый орден разбил лагерь возле Могильника?",a="В Могильнике поднимают и собирают новых Отрекшихся. Алый орден устроил небольшой передовой форпост, чтобы наблюдать за местностью, застигать врасплох недавно восставшую нежить и собирать силы для уничтожения молодого поселения Отрекшихся.",al={"why are scarlets in deathknell","scarlet camp deathknell","почему алый орден в могильнике","лагерь алого ордена у могильника"}},{q="Почему Отрекшиеся наносят удар первыми, а не говорят?",a="Как отмечает Палач Аррен, крестоносцы ослеплены рвением и считают всех нежити мерзостями, которые необходимо уничтожить. Они не слушают доводов и не ведут переговоров с мертвыми, поэтому упреждающая резня остается для них единственной действенной защитой.",al={"can forsaken negotiate with scarlet crusade","why attack scarlets","могут ли отрекшиеся договориться с алым орденом","зачем нападать на алый орден"}},{q="Какого ранга бойцы Ордена находятся в этом лагере?",a="В лагере служат в основном новобранцы и ученики — новообращенные и послушники Алого ордена. Несмотря на низкое положение в иерархии Ордена, их рвение делает их опасными для недавно восставших Отрекшихся.",al={"who is in the camp","scarlet converts initiates","кто в лагере","новообращенные послушники алого ордена"}},{q="К чему приводит выполнение этого задания?",a="Донесения от начальства Палача Аррена в Брилле сообщают, что из Монастыря Алого ордена в лагерь отправлен гонец Ордена. Поэтому Палач Аррен поручает вам перехватить Красного гонца, чтобы узнать их боевые планы.",al={"what quest comes after","quest chain after scarlet crusade","какое задание следующее","цепочка заданий после алого ордена"}},{q="Кто такой Палач Аррен?",a="Палач Аррен — главный военный командир, отвечающий за безопасность и оборону Могильника и направляющий недавно пробудившихся Отрекшихся против окружающих угроз.",al={"arren role","who gives the quest","роль аррена","кто дает задание"}}},fp="19,246,18.444.0,22.407.0,28.300.0,51.242.0,50.244.0,47.220.0,42.238.1,22.164.0"}
P.entries["quest:382"] = {n="Красный гонец",s="Палач Аррен поручает только что восставшим Отрекшимся перехватить гонца, посланного из Монастыря Алого ордена в лагерь ордена близ Могильника. Перехват посыльного позволит добыть важные сведения о передвижениях Алого ордена в округе, пока фанатики не закрепились в долине. Это одна из первых наступательных операций по защите молодого убежища Отрекшихся.",h="Палач Аррен поручает только что восставшим Отрекшимся перехватить гонца, посланного из Монастыря Алого ордена...",kw={"brill","deathknell","executor arren","meven korgal","red messenger","scarlet crusade","scarlet documents","scarlet monastery","tirisfal glades","брилл","могильник","палач аррен","мевен коргал","красный гонец","алый орден","бумаги алого ордена","монастырь алого ордена","тирисфальские леса"},ang={["class:Rogue"]="Проникнуть в лагерь ордена, убить Мевена Коргала и похитить его донесения — настоящее дело для только что пробудившихся разбойников.",["faction:Horde"]="Разрушая планы Алого ордена на границах Могильника, новобранцы защищают северный рубеж недавно созданного оплота Орды в Восточных королевствах.",["race:Undead"]="Перехват этого гонца — серьезный удар по фанатикам, которые хотят убить вас во второй раз, едва вы успели освоиться в Лордероне."},sec={{t="Глаза на востоке",b="Слухи быстро расходятся по Тирисфальским лесам, даже среди мертвых. Начальство в Брилле сообщило Палачу Аррену, что Алый орден отправил посланника из своей твердыни — Монастыря Алого ордена — на запад, в Могильник. Хотя бойцы ордена держатся агрессивно по всему Лордерону, отправка гонца прямо к границе земель, где пробуждаются Отрекшиеся, говорит о слаженной попытке истребить новопробужденных мертвецов до того, как они организуют оборону."},{t="Перехват гонца",b="Гонец Мевен Коргал затерялся в небольшом лагере Алого ордена к востоку от Могильника: отличительной геральдики при нем не было. Палач Аррен велел нанести точечный удар, убить Коргала и забрать его донесения. Лишив гонца писем, местные фанатики потеряют возможность согласовывать действия с восточным штабом."},{t="Важные донесения",b="В захваченных Бумагах Алого ордена оказались пропаганда, записи разведчиков и прямые приказы фанатикам расширить лагерь близ разрушенной столицы. Главное — в бумагах есть стратегическая карта с позициями полевых командиров и агентов по всем лесам. Находка настолько ценна, что ее следует немедленно доставить высшему командованию в Брилле."}},faq={{q="Кто такой Красный гонец?",a="Гонец — Мевен Коргал, человек, посыльный на службе Алого ордена. Его отправили прямо из Монастыря Алого ордена доставить стратегические приказы фанатикам, засевшим близ Могильника.",al={"meven korgal","who is meven korgal","who is the messenger","scarlet messenger identity","мевен коргал","кто такой мевен коргал","кто такой гонец","личность гонца алого ордена"}},{q="Откуда прибыл гонец?",a="Его отправили из Монастыря Алого ордена — огромной укрепленной штаб-квартиры Алого ордена на северо-востоке Тирисфальских лесов.",al={"where did korgal come from","messenger origin","scarlet courier source","откуда пришел коргал","откуда гонец","источник гонца алого ордена"}},{q="Какие сведения нашли в бумагах?",a="В донесениях содержатся сводки разведчиков, приказы укреплять позиции близ разрушенного города Лордерон и стратегическая карта с местами расположения полевых командиров и агентов ордена.",al={"scarlet documents contents","what are the orders","what was korgal carrying","содержание бумаг алого ордена","какие там приказы","что нес коргал"}},{q="Куда дальше пойдут эти сведения?",a="Палач Аррен сразу передает карту и добытые сведения начальству в Брилле через следующее задание «Важные разведданные», давая всем силам Отрекшихся конкретные цели в Тирисфале.",al={"what happens to the documents","where to deliver scarlet papers","vital intelligence quest","что будет с бумагами","куда доставить бумаги алого ордена","задание важные разведданные"}},{q="Почему Алый орден подбирается так близко к Могильнику?",a="Алый орден считает, что всю нежить нужно истреблять без разбора. В Могильнике свободные мертвецы впервые выбираются из могил, и это идеальная цель для фанатиков, стремящихся уничтожить Отрекшихся до того, как те организуются.",al={"why are scarlets in deathknell","crusade in deathknell","why are zealots here","почему алые в могильнике","орден в могильнике","почему тут фанатики"}},{q="Кто сообщил Палачу Аррену о гонце?",a="Командование Отрекшихся в Брилле перехватило известие об отправке гонца из монастыря и передало весть Аррену, чтобы его люди на месте смогли перехватить посыльного.",al={"who warned arren","who sent report to arren","how did forsaken know","кто предупредил аррена","кто прислал донесение аррену","как узнали отрекшиеся"}}},fp="17,410,16.474.0,24.344.0,16.406.1,25.200.0,34.144.0,44.217.1,37.215.1,62.261.0,52.170.0"}
P.entries["quest:383"] = {n="Важные разведданные",s="«Важные разведданные» завершают обучение только что восставшего Отрекшегося в Могильнике. Получив перехваченные бумаги Алого ордена, гонец отправляется через Тирисфальские леса к Палачу Зуганду в Брилл.",h="«Важные разведданные» завершают обучение только что восставшего Отрекшегося в Могильнике.",kw={"brill","cold hearth manor","deathknell","documents","executor arren","executor zygand","scarlet crusade","tirisfal glades","vital intelligence","брилл","поместье остывший очаг","могильник","бумаги","палач аррен","палач зуганд","алый орден","тирисфальские леса","важные разведданные"},ang={["faction:Horde"]="Собранные здесь сведения помогают Отрекшимся укрепить власть над Тирисфальскими лесами и защитить северные врата Подгорода от вторжений ордена.",["race:Undead"]="Доставка перехваченных планов — своего рода обряд посвящения: доказав свою жизнеспособность после восстания из могилы, вы покидаете колыбель в Могильнике и вступаете в большую войну за Лордерон."},sec={{t="Прощание с Могильником",b="Расправившись с местными угрозами и перехватив гонца Алого ордена, новые рекруты из числа Отрекшихся готовы к более широкой службе. Палач Аррен вверяет добытые сведения игроку и отправляет его через укрытый каньон Могильника на восток по дороге к Бриллу, мимо Поместья «Остывший Очаг»."},{t="Решающий удар",b="По прибытии в Брилл Палач Зуганд изучает захваченную переписку. В бумагах — списки и сведения о действующих командирах Алого ордена в Тирисфальских лесах, что закладывает основу для точечных убийств, призванных расколоть руководство фанатиков и подорвать их дух."}},faq={{q="Какие сведения содержатся в Бумагах Алого ордена?",a="В захваченных бумагах указаны имена и назначения офицеров Алого ордена в Тирисфальских лесах. Палач Зуганд намерен использовать эти списки, чтобы быстрыми, деморализующими ударами уничтожить местное руководство.",al={"what are the scarlet documents","scarlet crusade documents contents","what intelligence was gathered","что за бумаги алого ордена","содержание бумаг алого ордена","какие разведданные собраны"}},{q="Где находится Палач Зуганд?",a="Палач Зуганд стоит в Брилле, у Ратуши Брилла, на главной площади города.",al={"where is zygand","find executor zygand","executor zygand location","где зуганд","найти палача зуганда","где палач зуганд"}},{q="Как добраться до Брилла из Могильника?",a="Идите по дороге на север из Могильника. На развилке, ведущей в Тирисфальские леса, сверните на восточную тропу, пройдите мимо Поместья «Остывший Очаг» и по крытому мосту попадете прямо в Брилл.",al={"path to brill","how to get to brill","directions to brill","путь в брилл","как добраться до брилла","дорога в брилл"}},{q="Почему это задание означает конец пребывания в Могильнике?",a="Могильник — первое испытание для только что пробудившихся Отрекшихся. Когда вы помогли защитить поселок и собрали полезные сведения об Алом ордене, Палач Аррен передает вас под начало старших командиров в Брилле.",al={"done with deathknell","why leave deathknell","is this the last deathknell quest","закончил могильник","почему уходить из могильника","последнее задание могильника"}},{q="Кто такой Палач Аррен?",a="Палач Аррен — офицер Отрекшихся, который отвечает за операции, безопасность и первичное обустройство новопробужденной нежити в Могильнике.",al={"who is arren","arren lore","кто такой аррен","аррен предания"}},{q="Что будет после сдачи этих бумаг?",a="Доставив бумаги, вы вливаетесь в общие военные усилия Отрекшихся в Брилле: вас ждут задания в Тирисфальских лесах, направленные на разгром местных лагерей Алого ордена и остатков Плети.",al={"what comes next","next quest after vital intelligence","что дальше","следующее задание после важных разведданных"}}},fp="18,224,18.335.0,17.310.1,57.238.0,33.112.0,38.199.0,49.254.0,22.140.0,46.226.0"}
P.entries["quest:384"] = {n="Кабаньи ребрышки в пиве",kw={"beer basted boar ribs","crag boar","dun morogh","kharanos","ragnar thunderbrew","rhapsody malt","thunderbrew distillery","кабаньи ребрышки в пиве","скальный кабан","дун морог","каранос","рагнар громовар","болтливое пиво","таверна громоварка"},ang={["faction:Alliance"]="Даже бытовые нехватки в таверне Караноса вызваны общими военными усилиями Альянса: местные жители покидают свои ремесла, откликаясь на призыв к оружию.",["profession:Cooking"]="Искатели приключений, интересующиеся домашней кухней, могут узнать секрет сочетания солодового напитка с дичью прямо у одного из самых известных пивоваров Дун Морога.",["race:Dwarf"]="Для дворфов крепкий эль и жареный кабан — основа горного гостеприимства, поэтому снабжение таверны — дело местной гордости."},sec={{t="Таверна в беде",b="Таверна «Громоварка» в Караносе славится крепким дворфийским элем и сытной едой. Главное блюдо — легендарные Кабаньи ребрышки в пиве. Но трактирщик Рагнар Громовар попал в затруднение: местный охотник, обычно снабжавший кладовую свежим мясом, недавно вступил в королевскую армию, чтобы усилить фронт Альянса, и у Рагнара полно желающих поесть, но кладовые совершенно пусты."},{t="Секретный ингредиент",b="Чтобы приготовить блюдо, нужно добыть свежее мясо жестких скальных кабанов, что бродят по заснеженным предгорьям вокруг Караноса. Но настоящая магия рецепта — в маринаде. Рагнар настаивает на свежем Болтливом пиве прямо из бочек таверны. Солод размягчает жесткое мясо, превращая грубую горную дичь в сочное угощение, достойное похвалы дворфа."}},faq={{q="Почему у Рагнара Громовара не хватает мяса?",a="Обычный поставщик мяса Рагнара, местный горный охотник, покинул Каранос и вступил в королевскую армию, чтобы поддержать операции Альянса за границей, и таверна осталась без постоянных поставок дичи.",al={"why ragnar need boar ribs","what happened to ragnar meat supplier","who supplies the ribs","зачем рагнару ребрышки кабана","что случилось с поставщиком мяса рагнара","кто поставляет ребрышки"}},{q="Откуда берется Болтливое пиво?",a="Болтливое пиво варят и подают прямо в таверне «Громоварка» в Караносе; его можно получить у трактирщика за стойкой.",al={"where get rhapsody malt","how to get malt for ragnar","who sells rhapsody malt","где взять болтливое пиво","как достать пиво для рагнара","кто продает болтливое пиво"}},{q="Какие кабаны дают ребрышки?",a="Мясо добывают у скальных кабанов, что бродят по холмам, сугробам и замерзшим долинам вокруг Караноса в Дун Мороге.",al={"which boars drop ribs","where find boar ribs dun morogh","crag boars dun morogh","какие кабаны дают ребрышки","где найти ребрышки кабана дун морог","скальные кабаны дун морога"}},{q="В чем секрет рецепта ребрышек Рагнара?",a="Секрет в том, чтобы вымачивать жесткие кабаньи ребрышки в Болтливом пиве: оно делает мясо северной дичи нежным и придает ему насыщенный вкус дворфийского пивоварения.",al={"secret to beer basted ribs","beer basted boar ribs secret","секрет ребрышек в пиве","секрет кабаньих ребрышек в пиве"}},{q="Кто сражается на передовой в королевской армии?",a="Новобранцы-дворфы регулярно вступают в Королевскую армию, чтобы поддерживать Альянс в продолжающихся конфликтах с троггами, вторжениями Черного Железа и на более широких военных фронтах по всем Восточным королевствам.",al={"why did the trapper enlist","what war is the kings army fighting","alliance front lines 25 adp","почему охотник пошел в армию","с кем воюет королевская армия","передовая альянса"}},{q="Где находится таверна «Громоварка»?",a="Таверна «Громоварка» — главная таверна и постоялый двор Караноса, расположенный у главной дороги через центр Дун Морога.",al={"where is thunderbrew distillery","where is ragnar thunderbrew","kharanos inn location","где громоварка","где рагнар громовар","постоялый двор каранос"}}},fp="21,285,16.444.0,21.389.0,40.191.0,35.147.0,36.133.0,42.154.0,55.187.0,44.132.0"}
P.entries["quest:385"] = {n="Охота на кроколисков",s="Приют Странников в Лок Модане ведет стабильную, хотя и опасную торговлю шкурами и мясом местных кроколисков. Марек Железносерд регулярно ищет выносливых следопытов, готовых отправиться на берега и острова озера, чтобы добывать этих ценных зверей. Для охотников, желающих испытать себя в схватке с щелкающими челюстями и прочной шкурой, Озеро Лок сулит и азарт, и прибыль.",h="Приют Странников в Лок Модане ведет стабильную, хотя и опасную торговлю шкурами и мясом местных кроколисков.",kw={"crocolisk hunting","crocolisk meat","crocolisk skin","dwarf hunter","farstrider lodge","loch modan","marek ironheart","the loch","охота на кроколисков","мясо кроколиска","шкура кроколиска","дворф-охотник","приют странников","лок модан","марек железносерд","озеро лок"},ang={["class:Hunter"]="Приют Странников — идеальное испытательное поле для начинающих стрелков и повелителей зверей, проверяющих свою выдержку на водных чудовищах Лок Модана.",["profession:Cooking"]="Жесткое постное мясо кроколиска дает кострам на границе сытную основу для наваристых похлебок и жаркого.",["race:Dwarf"]="Горцы гордятся тем, что покоряют дикие земли Лок Модана, считая охоту на кроколисков и практичным способом выжить, и честным заработком."},sec={{t="Прибыльная добыча",b="Лок Модан славится спокойными горными водами, но под их поверхностью озеро скрывает свирепых хищников. Кроколиски обитают на мелководье и илистых берегах, из-за чего переправа или рыбалка становятся опасными для неосторожных. Однако для лесных жителей, живущих в Приюте Странников, эти опасные рептилии — ценная дичь. Ремесленники и портные по всему Каз Модану постоянно ищут прочные шкуры кроколисков, чтобы делать из них грубые доспехи и кожаные изделия, а простые таверны платят хорошие деньги за свежие куски их вкусного постного мяса из хвоста."},{t="Челюсти на мелководье",b="Охота на кроколисков Озера Лок — не занятие для начинающих охотников. Эти твари обитают главным образом у скалистых островков, разбросанных по озеру, и обладают сокрушающими кости челюстями с острейшими зубами. Ветераны-дворфы вроде Марека Железносерда носят множество шрамов от схваток с этими зверями и предупреждают новичков, что один неверный шаг в воде может стоить конечности. Чтобы успешно снять шкуру и разделать тушу, нужны терпение, прочная сталь и готовность войти прямо во владения рептилии."}},faq={{q="Почему в Лок Модане охотятся на кроколисков?",a="Торговцы и ремесленники ценят шкуры кроколисков за то, что из них делают грубую одежду и кожаные доспехи, а их мясо считается вкусным местным лакомством. Приют Странников ведет стабильную торговлю этими ресурсами, снабжая торговцев, проезжающих через Каз Модан.",al={"why hunt crocolisks","crocolisk meat skin use","why marek wants crocs","зачем охотиться на кроколисков","мясо и шкура кроколиска","зачем Мареку кроколиски"}},{q="Где обычно встречаются кроколиски?",a="Кроколиски обитают на илистом мелководье, на берегах и особенно на скалистых островах в центре Озера Лок.",al={"crocolisk location","where to find crocs loch modan","where are crocolisks","где найти кроколисков","кроколиски лок модан","расположение кроколисков"}},{q="Кто такой Марек Железносерд?",a="Марек Железносерд — опытный дворфийский горец и охотник, живущий в Приюте Странников на юго-востоке Лок Модана. Он торгует материалами, добытыми из местных животных, и любит рассказывать истории о том, как ему удавалось уцелеть в опасных встречах с самыми свирепыми зверями Озера Лок.",al={"marek ironheart","who gives crocolisk hunting","quest giver marek","марек железносерд","кто дает охоту на кроколисков","задание марека"}},{q="Чем так опасна охота на них?",a="Кроколиски Лок Модана — агрессивные хищники, защищающие свою территорию, с огромной силой челюстей и зубами как кинжалы. Охотникам приходится заходить на глубину или на уединенные островки, рискуя попасть во внезапную засаду на местности, выгодной рептилиям.",al={"are crocs dangerous","danger of crocolisks","why are crocs hard to hunt","опасны ли кроколиски","опасность кроколисков","почему трудно охотиться"}},{q="Безопасно ли мясо кроколиска и съедобно ли оно?",a="Да, мясо кроколиска ценят пограничные повара и посетители таверн по всем землям дворфов за плотную текстуру и насыщенный сытный вкус, если его правильно разделать и зажарить.",al={"can you eat crocolisk","crocolisk meat edible","croc taste","можно ли есть кроколиска","съедобное мясо кроколиска","вкус кроколиска"}},{q="Что такое Приют Странников?",a="Приют Странников — живописный форпост на юго-востоке Лок Модана, служащий убежищем и сборным пунктом для охотников, следопытов и горцев Альянса, наблюдающих за дикими уголками долины.",al={"what is farstrider lodge","farstrider lodge purpose","where is farstrider lodge","что такое приют странников","назначение приюта странников","где приют странников"}}},fp="17,359,18.540.0,20.509.0,40.256.0,39.128.0,23.240.0,37.235.0,43.171.0,29.194.0"}
P.entries["quest:386"] = {n="Что происходит?",s="«Что происходит?» — задание Альянса, которое дает Стражник Бертон в Приозерье, возмущенный политическими проволочками вокруг орка-военного преступника. Игроков направляют в Тюрьму Штормграда, чтобы казнить Таргорра Ужасного, прежде чем продажная знать организует его побег.",h="«Что происходит?» — задание Альянса, которое дает Стражник Бертон в Приозерье, возмущенный политическими...",kw={"berton","blackrock","executioner","gath'ilzogg","lakeshire","redridge","stockade","targorr","бертон","черная гора","палач","гат'илзогг","приозерье","красногорье","тюрьма","таргорр"},ang={["class:Paladin"]="Обойти продажные судебные отсрочки, чтобы воздать по заслугам нераскаявшемуся палачу, — значит поставить под вопрос баланс между писаным законом и подлинной нравственной справедливостью.",["faction:Alliance"]="Задание обнажает растущий разрыв между пограничными гарнизонами на передовой вроде Приозерья и корыстными политическими интригами в дворянских кругах Штормграда.",["race:Human"]="Для людей королевства казнь Таргорра — это возмездие за злодеяния, совершенные против местных городских стражников и ополчения во время вторжения орков Черной горы в Красногорье."},sec={{t="Мясник в подвешенном состоянии",b="Таргорр Ужасный прославился в Красногорье как главный палач при генерале Гат'Илзогге, вожде орков Черной горы, закрепившихся в Крепости Каменной Стражи. Даже среди захватчиков из клана Черной горы он был известен дикой жестокостью и лично руководил пытками и казнями многих защитников Красногорья. После пленения его перевели в тюрьму строгого режима в столице — Тюрьму Штормграда — и приговорили к смерти за злодеяния против королевства."},{t="Коррупция в высших кругах",b="Несмотря на официальный смертный приговор Таргорру, казнь застопорилась из-за вмешательства неназванного дворянина из Дома знати Штормграда. Стражник Бертон, несущий службу в уязвимом Приозерье, видит насквозь политические интриги и подозревает подвох или взятку, призванную обеспечить скорое освобождение этого зверя. Взяв правосудие в свои руки, Бертон нанимает надежных искателей приключений, чтобы они проникли в охваченную мятежом тюрьму и исполнили приговор без бюрократических помех."}},faq={{q="Кто такой Таргорр Ужасный?",a="Таргорр Ужасный — элитный орк из клана Черной горы, служивший главным палачом при генерале Гат'Илзогге в Красногорье. Известный пытками захваченных солдат-людей, он был в конце концов пойман и заключен в Тюрьму Штормграда.",al={"targorr","who is targorr","targorr lore","таргорр","кто такой таргорр","предания о таргорре"}},{q="Почему Штормград до сих пор не казнил Таргорра?",a="Хотя он приговорен к смерти, его казнь на неопределенный срок отложил влиятельный дворянин в столице. Стражник Бертон подозревает политическую коррупцию или скрытый подвох, призванный пощадить или использовать орка-полководца.",al={"why is targorr alive","noble stay of execution","почему таргорр жив","отсрочка казни дворянином"}},{q="Кто дает задание «Что происходит?»?",a="Задание дает Стражник Бертон. Он несет службу в Приозерье в Красногорье, охраняя поселок от постоянных вторжений орков Черной горы.",al={"quest giver","where to get quest","кто выдает задание","где взять задание"}},{q="Где можно найти Таргорра Ужасного?",a="Таргорра держат в Тюрьме Штормграда, расположенной в районе каналов Штормграда. Обычно его можно найти запертым в камере в центральном блоке тюрьмы.",al={"targorr location","where is targorr","где таргорр","расположение таргорра"}},{q="Кто такой генерал Гат'Илзогг?",a="Генерал Гат'Илзогг — полководец, командующий силами орков Черной горы, занявшими Крепость Каменной Стражи в восточном Красногорье; Таргорр служил под его началом палачом.",al={"gath'ilzogg","blackrock general redridge","гат'илзогг","генерал черной горы красногорье"}},{q="Почему Стражник Бертон берет дело в свои руки?",a="Бертон видел, как солдаты Красногорья страдали и гибли под клинками Таргорра. Возмущенный тем, что политики в Штормграде обращаются с безжалостным убийцей как с политической пешкой, он обходит официальную бюрократию, чтобы свершилось истинное правосудие.",al={"berton motive","why bypass nobles","мотив бертона","почему обойти дворян"}}},fp="20,283,23.504.0,25.501.1,25.235.0,42.214.0,41.149.0,37.179.0,27.169.0,54.232.0"}
P.entries["quest:3861"] = {n="Куд-кудаааа!",s="«Куд-кудаааа!» — необычное тайное взаимодействие, позволяющее искателю приключений завоевать доверие обычной домашней птицы. Подражая куриному кудахтанью и предложив подходящее зерно, путешественники могут получить редкое яйцо, из которого вылупится пернатый спутник.",h="«Куд-кудаааа!» — необычное тайное взаимодействие, позволяющее искателю приключений завоевать доверие обычной...",kw={"chicken","chicken egg","cluck","poultry","saldean","saldean farm","special chicken feed","westfall chicken","курица","куриное яйцо","куд-куда","птица","сальден","ферма сальденов","цыплячий корм","курица западный край"},ang={["faction:Alliance"]="Задание связано с фермой Сальденов в Западном Крае, поэтому этот странный пернатый ритуал стал любимой историей юных искателей приключений Альянса, исследующих истерзанное сельское королевство.",["profession:Cooking"]="Цыплячий корм, нужный птице, вполне съедобен, хотя большинство поваров предпочитают приберечь грубое зерно для птиц, а не грызть его самим."},sec={{t="Странное общение",b="Большинство путников почти не замечают простых кур, бродящих по фермам Азерота, но эти птицы обладают на удивление проницательным нравом. Если искатель приключений достаточно долго подражает их движениям и кудахтанью, курица перестает бездумно клевать землю и с необычным интересом смотрит на смертного. В этот краткий миг связи птица выцарапывает в пыли буквы, намекая на свой голод и указывая любопытному на фермера, который может ее накормить."},{t="Корм от фермера",b="Чтобы исполнить загадочную просьбу птицы, нужно раздобыть Цыплячий корм. В Западном Крае семья Сальден держит такое зерно для своей птицы. Если показать этот особый корм и подбодрить курицу, она жадно склюет угощение. В ответ курица снесет теплое свежее яйцо, из которого можно вырастить верного спутника."}},faq={{q="Как курица дает задание?",a="Если несколько раз подряд подражать птице куриными жестами или взмахами рук перед ней, она в конце концов замрет и с любопытством осмотрит вас. После этого курица начинает реагировать и сообщает о своем голоде, выцарапывая имя в пыли.",al={"chicken quest start","how to talk to chicken","cluck quest unlock","начало задания с курицей","как говорить с курицей","открыть задание куд-куда"}},{q="Что курица пишет в пыли?",a="Курица выцарапывает на земле буквы «S-A-L-D-E-A-N» и уходит. Это указывает путнику на Фермера Сальдена и его жену на ферме Сальденов в центральной части Западного Края, которые продают особое зерно, нужное птице.",al={"chicken scratch words","what does the chicken write","saldean chicken","слова курицы","что пишет курица","курица сальден"}},{q="Где взять Цыплячий корм?",a="Farmer Saldean stocks Special Chicken Feed at the Saldean Farm in Westfall.",al={"chicken feed vendor","where to buy chicken feed","saldean feed","продавец корма для кур","где купить корм для кур","корм сальден"}},{q="Можно ли сделать это с любой курицей в мире?",a="На жест может откликнуться любая обычная домашняя курица в обитаемых землях, хотя чаще всего их встречают на человеческих фермах, например в Западном Крае.",al={"which chickens work","does any chicken work","where to find chicken","какие куры подходят","подойдет ли любая курица","где найти курицу"}},{q="Как выполнить задание, когда есть корм?",a="Найдите курицу, имея при себе Цыплячий корм, и восторженно поприветствуйте ее. Курица выжидающе посмотрит на вас, примет корм и снесет под собой яйцо, которое вы сможете подобрать.",al={"how to turn in cluck","feed chicken egg","cluck quest hand in","как сдать куд-куда","покормить курицу яйцо","сдать задание куд-куда"}},{q="Что дают за выполнение задания?",a="Накормленная курица откладывает у своих лап яйцо. Если его подобрать, вы получите предмет «Куриное яйцо», позволяющий призвать собственную верную курицу из Западного Края, которая будет сопровождать вас в приключениях.",al={"cluck quest reward","chicken egg pet","westfall chicken reward","награда за куд-куда","питомец куриное яйцо","награда курица западный край"}}},fp="6,255,19.473.0,17.376.0,33.248.0,44.238.0,42.75.0,46.180.0,53.202.0,40.192.0"}
P.entries["quest:387"] = {n="Подавление бунта",s="Глубоко под мостовыми Штормграда в Тюрьме, где царил строгий режим, начался полный хаос. После согласованного побега, который возглавили заключенные члены Братства Справедливости, Тюремщик Телвотер срочно нанимает искателей приключений, чтобы перебить бунтующих заключенных и восстановить порядок, пока столица не узнала, насколько на самом деле скомпрометирована тюрьма.",h="Глубоко под мостовыми Штормграда в Тюрьме, где царил строгий режим, начался полный хаос.",kw={"convicts","defias","insurgents","quell the uprising","stockade","stormwind","uprising","warden thelwater","преступники","братство справедливости","мятежники","подавление бунта","тюрьма","штормград","бунт","тюремщик телвотер"},ang={["class:Paladin"]="Восстановление порядка в недрах города проверяет грань между праведным правосудием и отчаянной смертельной расправой над мятежными гражданами.",["faction:Alliance"]="Мятеж в Тюрьме происходит прямо под улицами Штормграда, что говорит о катастрофическом провале безопасности в самом сердце главного королевства Альянса.",["race:Human"]="Многие заключенные из Братства Справедливости, сражающиеся в камерах, — бывшие каменщики королевства и простые люди, доведенные до мятежа, поэтому кровавый бунт стал для жителей Штормграда болезненным гражданским конфликтом."},sec={{t="Тюрьма, отнятая заключенными",b="Тюрьма была построена, чтобы содержать самых опасных преступников, заговорщиков и разбойников, угрожавших Королевству Штормград. Однако внезапный и жестокий мятеж, устроенный заключенными агентами Братства Справедливости, вырвал власть над тюремными блоками из рук стражи. Тюрьма захвачена, коридоры забиты вооруженными преступниками, и обычные порядки рухнули полностью. Вместо организованного отвоевания тюрьмы власти полагаются на приезжих героев, которые должны пробиться сквозь бунт."},{t="Отчаяние и сокрытие",b="Приказ Тюремщика Телвотера казнить заключенных из Братства Справедливости на месте говорит и об отчаянии, и о желании спасти себя. Подозревая в согласованном мятеже происки извне, тюремщик боится, что, если знать или Дом знати узнает о потере контроля над тюрьмой, он лишится должности. Объявив смерть немедленным наказанием за мятеж, Телвотер надеется, что грубая сила сломит дух заключенных и подавит бунт, пока слух не просочился за ворота у каналов."}},faq={{q="Почему Тюремщик Телвотер просит искателей приключений подавить бунт?",a="Стража Тюрьмы потеряла контроль над внутренними камерами из-за бунтующих заключенных из Братства Справедливости. Тюремщик Телвотер боится лишиться должности, если о масштабах катастрофы узнает руководство Штормграда, поэтому нанимает умелых наемников, чтобы уничтожить зачинщиков и быстро восстановить порядок.",al={"why hire adventurers","thelwater motivation","why the stockade quest","зачем нанимать авантюристов","мотивы телвотера","почему задание в тюрьме"}},{q="Кто те заключенные, которые бунтуют в Тюрьме?",a="Основу мятежа составляют схваченные члены Братства Справедливости — простые заключенные, закоренелые преступники и организованные мятежники, — которых заперли, пока братство вело тайную войну по всему Западному Краю и Элвиннскому лесу.",al={"who is rioting","defias prisoners stockade","who broke out","кто бунтует","заключенные братства справедливости тюрьма","кто сбежал"}},{q="Считает ли Телвотер, что бунт устроили изнутри?",a="Да. Тюремщик Телвотер открыто подозревает злой умысел: он считает, что столь внезапный и полный мятеж не мог случиться просто так, без вмешательства извне или бреши в охране внутри города.",al={"was it treason","foul play stockade","inside job prison","это измена","злой умысел тюрьма","предательство в тюрьме"}},{q="Где происходит этот бунт?",a="Бунт удается сдерживать — но с трудом — внутри Тюрьмы, подземной тюрьмы строгого режима у каналов в Квартале магов Штормграда.",al={"where is the stockade","stockade entrance","prison location","где тюрьма","вход в тюрьму","расположение тюрьмы"}},{q="Что будет после убийства бунтовщиков из Братства Справедливости?",a="Хотя уничтожение мятежников ослабляет ряды бунтовщиков, по вашем возвращении Тюремщик Телвотер признает, что кризис куда глубже простой потасовки и требует новых ударов по важным предводителям в глубине камер.",al={"does the prison get safe","after quell the uprising","станет ли тюрьма безопасной","после подавления бунта"}},{q="Разрешено ли применять смертельную силу ко всем сбежавшим заключенным?",a="Тюремщик Телвотер объявляет, что законное наказание за активный мятеж во время захвата тюрьмы — немедленная смерть, и приказывает героям казнить заключенных, преступников и мятежников на месте, чтобы принудить уцелевших к покорности.",al={"why kill them","punishment for insurgency","is killing prisoners legal","зачем их убивать","наказание за мятеж","законно ли убивать заключенных"}}},fp="18,357,28.523.0,24.501.0,64.309.0,44.251.0,50.208.0,36.161.0,51.238.0,56.236.0"}
P.entries["quest:388"] = {n="Цвет крови",s="«Цвет крови» — личное поручение Никовы Раскол, скорбящей бабушки, живущей в Штормграде. Охваченная гневом из-за убийства юного внука в городской тюрьме, она нанимает искателей приключений, чтобы те отправились в Тюрьму и добыли фирменные красные банданы банды Братства Справедливости в качестве возмездия.",h="«Цвет крови» — личное поручение Никовы Раскол, скорбящей бабушки, живущей в Штормграде.",kw={"color of blood","defias brotherhood","mac raskol","nikova raskol","red wool bandana","stockade","stormwind","цвет крови","братство справедливости","мак раскол","никова раскол","красная шерстяная бандана","тюрьма","штормград"},ang={["faction:Alliance"]="Смерть Мака Раскола обнажает нагрузку на внутреннюю оборону Штормграда и показывает страшную цену отправки опытных солдат вдали от столицы.",["race:Human"]="Люди — жители Штормграда — принимают на себя основной удар насилия Братства Справедливости как на окрестных фермах, так и в самих стенах города."},sec={{t="Мальчик на тюремной стене",b="Когда регулярные войска Штормграда отправили на дальние фронты, оборона города легла на добровольцев-новобранцев и городскую молодежь. Внуку Никовы Раскол, Маку, было всего четырнадцать лет, когда он взялся за оружие и встал на стражу в Тюрьме. Ему поручили присматривать за закоренелыми преступниками и мятежными членами Братства Справедливости, и юный страж оказался в крайне опасной обстановке, намного превосходившей его опыт."},{t="Знаки неповиновения",b="За решеткой схваченные члены Братства Справедливости начали раздирать выданные им шерстяные тюремные одеяла и мастерить из лоскутов самодельные красные банданы. Эти грубые повязки служили опознавательными цветами банды и показывали, что даже в стенах тюрьмы они верны Братству. Когда юный Мак отчитал заключенных и попытался навести дисциплину, они ударили мальчика ножом в спину, и он остался лежать мертвым на каменном полу."},{t="Горе и месть",b="Опустошенная бессмысленной смертью Мака, Никова жаждет хладнокровной мести, а не официальной волокиты. Она посылает храбрых искателей приключений в глубины Тюрьмы, чтобы они перебили бунтующих заключенных и принесли десять их дорогих красных бандан — символов цвета пролитой крови ее внука. Эти кровавые трофеи приносят разбитой семье мрачное чувство завершенности."}},faq={{q="Кто такая Никова Раскол?",a="Никова Раскол — пожилая жительница Штормграда, чей четырнадцатилетний внук Мак недавно был убит, когда нес службу стражником в Тюрьме.",al={"nikova raskol","quest giver","who gives color of blood","никова раскол","персонаж, выдающий задание","кто выдает задание цвет крови"}},{q="Почему опасных заключенных охранял четырнадцатилетний мальчик?",a="Поскольку значительная часть регулярной армии Штормграда была отправлена на передовую, городу пришлось полагаться на неопытных местных жителей и юнцов, чтобы занять оборонительные посты, в том числе охранять заключенных в Тюрьме.",al={"why was mac a guard","mac age","child guard","почему мак стал стражником","возраст мака","ребенок на страже"}},{q="Почему заключенные из Братства Справедливости носят красные шерстяные банданы?",a="Красные банданы — объединяющий символ Братства Справедливости. Сидя в Тюрьме, заключенные раздирали шерстяные тюремные одеяла, чтобы сделать красные повязки и сохранить преступную солидарность.",al={"why red bandanas","wool bandanas lore","defias red scarves","почему красные банданы","шерстяные банданы предание","красные повязки братства справедливости"}},{q="Как погиб Мак Раскол?",a="Мак застал заключенных за тем, как они раздирали шерстяные одеяла на повязки банды Братства Справедливости, и отчитал их. В ответ на упрек заключенные ударили четырнадцатилетнего стражника ножом в спину.",al={"how did mac die","who killed mac","what happened to mac","как погиб мак","кто убил мака","что случилось с маком"}},{q="Что Никова делает с банданами?",a="Она хранит их как доказательство возмездия. Глядя на рваные шерстяные знаки, она скорбит о бессмысленной потере внука, но находит покой, зная, что убившие его понесли наказание.",al={"what happens to the bandanas","nikova bandanas","что происходит с банданами","банданы никовы"}},{q="Где происходит это задание?",a="Задание отправляет вас в Тюрьму — тюрьму строгого режима Штормграда в районе каналов, где заключенные из Братства Справедливости открыто взбунтовались.",al={"where do i get the bandanas","color of blood location","где взять банданы","расположение цвета крови"}}},fp="18,310,24.437.0,18.444.0,19.391.0,21.159.0,57.203.0,51.210.0,23.191.0,38.188.0,33.153.0"}
P.entries["quest:389"] = {n="Базиль Тредд",s="После находки неотправленного письма в Мертвых копях городской архитектор Барос Алекстон направляет следователей к Базилю Тредде, правой руке предводителя Братства Справедливости. Тредд заключен под улицами Штормграда в Тюрьме строгого режима и знает о неугасших замыслах Братства.",h="После находки неотправленного письма в Мертвых копях городской архитектор Барос Алекстон направляет...",kw={"baros alexston","bazil thredd","defias","edwin vancleef","stonemasons guild","stormwind","the stockade","unsent letter","warden thelwater","барос алекстон","базиль тредд","братство справедливости","эдвин ван клиф","гильдия каменщиков","штормград","тюрьма","неотправленное письмо","тюремщик телвотер"},ang={["class:Rogue"]="Тредд олицетворяет закаленную, организованную преступную ветвь Братства Справедливости, сменившую строительные молотки на заточки и уличное насилие.",["faction:Alliance"]="Даже после гибели Эдвина ван Клифа угроза Братства Справедливости проникает в самое сердце столицы через небезопасные камеры Тюрьмы.",["race:Human"]="Восстание Гильдии каменщиков подчеркивает глубокий, незаживший политический разлом между правящей знатью Штормграда и простолюдинами, построившими город своими руками."},sec={{t="Горькая история",b="Увидев улики из Мертвых копей, Барос Алекстон признает, что у него с Эдвином ван Клифом общее прошлое. Оба были ведущими мастерами Гильдии каменщиков, отстраивавшими Штормград из пепла Первой и Второй войны. Когда великолепные белые стены и башни королевства были закончены, знать отказалась платить каменщикам обещанные деньги. Некоторым старшим мастерам предложили теплые чиновничьи места, чтобы их утихомирить, но ван Клиф не бросил рядовых рабочих и повел яростный бунт за пределы города, основав Братство Справедливости."},{t="Путь в Тюрьму",b="Чтобы разгадать весь замысел ван Клифа и узнать, что Братство еще планирует против Штормграда, Алекстон направляет следователей к Базилю Тредде. Когда-то главный помощник ван Клифа во время восстания каменщиков, Тредд был схвачен и заключен в городскую тюрьму под каналами Квартала магов. Но добраться до него непросто: у ворот тюрьмы Тюремщик Телвотер сообщает, что заключенные устроили настоящий мятеж, превратив Тюрьму в поле боя."}},faq={{q="Кто такой Базиль Тредд?",a="Базиль Тредд был главным помощником Эдвина ван Клифа в Гильдии каменщиков, а позже в первом восстании Братства Справедливости. После пленения властями Штормграда его заключили в глубине Тюрьмы.",al={"bazil thredd lore","who is thredd","thredd backstory","базиль тредд предание","кто такой тредд","история тредда"}},{q="Почему Барос Алекстон посылает вас поговорить с Треддом?",a="Изучив неотправленное письмо из Мертвых копей, Алекстон понимает, что угроза Штормграду не ограничивается Мертвыми копями. Он считает, что Тредд, бывшая правая рука ван Клифа, знает о внутренних делах и оставшихся замыслах Братства лучше всех.",al={"why talk to thredd","baros alexston motive","why go to stockade","зачем говорить с треддом","мотив бароса алекстона","зачем идти в тюрьму"}},{q="Почему Гильдию каменщиков предали?",a="Когда каменщики завершили масштабное восстановление Штормграда после Второй войны, Дом знати отказался выполнять финансовые договоренности, оставив рабочих без платы и в нищете. Ван Клиф отверг тайные подачки за молчание и вместо этого повел бунт за ворота города.",al={"why werent stonemasons paid","defias motive","stonemason riot reason","почему не заплатили каменщикам","мотив братства справедливости","причина бунта каменщиков"}},{q="Где находится Тюрьма?",a="Вход в Тюрьму спрятан у каналов в северо-восточной части Квартала магов Штормграда. Тюремщик Телвотер стоит сразу за порогом и пытается сдержать рвущихся наружу заключенных.",al={"where is stockade","stockade entrance","how to find warden thelwater","где тюрьма","вход в тюрьму","как найти тюремщика телвотера"}},{q="Что происходит в Тюрьме, когда вы прибываете?",a="Тюрьма погрузилась в полный хаос. Базиль Тредд и другие заключенные одолели стражу, отперли камеры и захватили нижние залы, а Тюремщик Телвотер из последних сил не дает бунту выплеснуться на улицы Штормграда.",al={"why is thelwater mad","stockade crisis","what happened in the stockade","почему телвотер зол","кризис в тюрьме","что случилось в тюрьме"}},{q="Как Барос Алекстон избежал вступления в Братство Справедливости?",a="В отличие от ван Клифа, который отказался от любых компромиссов и выбрал вооруженное восстание, Алекстон был одним из старших мастеров гильдии, принявших государственную службу у королевства, и в конце концов стал главным архитектором города.",al={"is baros defias","baros alexston stonemason","барос из братства справедливости","барос алекстон каменщик"}}},fp="12,340,16.585.0,22.503.1,20.220.0,54.289.0,39.292.0,30.217.0,54.279.0,48.217.0"}
P.entries["quest:39"] = {n="Донесение Томаса",s="«Донесение Томаса» доставляет мрачные сведения из восточной части Элвиннского леса в штаб гарнизона Златоземья. Стражник Томас поручает искателю приключений известить маршала Дугхана о гибели двух стражников и неудержимом росте местных племен мурлоков. Донесение показывает, насколько тонким слоем растянуто военное присутствие Штормграда в самом сердце его владений.",h="«Донесение Томаса» доставляет мрачные сведения из восточной части Элвиннского леса в штаб гарнизона...",kw={"elwynn forest","goldshire","guard thomas","malakai","marshal dughan","murlocs","report","rolf","элвиннский лес","златоземье","стражник томас","малакай","маршал дугхан","мурлоки","донесение","рольф"},ang={["class:Warrior"]="Для воинов на службе королевству гибель Малакая и Рольфа подчеркивает суровую реальность пограничной гарнизонной службы против неутомимых нечеловеческих врагов.",["faction:Alliance"]="Доставка донесения Томаса показывает уязвимость в сердце главного королевства Альянса: даже дороги за пределами столицы выходят из-под контроля гарнизонов.",["race:Human"]="Защитники-люди остро ощущают эти потери: безопасность их родины подрывается нехваткой людей и растущими вторжениями врагов."},sec={{t="Дурные вести с востока",b="Стражник Томас, стоящий на мостах, ведущих в глушь восточного Элвиннского леса, дошел до предела. Его отряд следит за движением по реке и беспорядками на границе, но понес тяжелые потери: стражники Малакай и Рольф погибли от рук агрессивных племен мурлоков. Людей остается все меньше, сдержать водную угрозу не удается, и Томас вынужден срочно отправить гонца по дороге обратно в Златоземье."},{t="Гарнизон на грани",b="Когда маршал Дугхан получает донесение в таверне «Гордость Льва», новости подтверждают его худшие стратегические опасения. Златоземье и без того с трудом поддерживает обычные патрули, борясь с нашествием кобольдов и бандитами из Братства Справедливости, а подкреплений из Штормграда нет вовсе. Потеря двух опытных стражников и мысль о том, что мурлоки вскоре могут угрожать самому Златоземью, показывают, насколько близка к краху оборона региона."}},faq={{q="Кто такие Малакай и Рольф?",a="Малакай и Рольф были штормградскими стражниками, служившими в восточной части Элвиннского леса под началом стражника Томаса. Во время патруля у рек и озер оба были захвачены врасплох и убиты агрессивными племенами мурлоков, наводнившими водоемы.",al={"malakai and rolf","who died","dead guards","малакай и рольф","кто погиб","погибшие стражники"}},{q="Почему стражник Томас просит искателя приключений доставить донесение?",a="У стражника Томаса просто не осталось людей. Его застава страдает от острой нехватки бойцов, и если он покинет пост или отправит одного из немногих уцелевших дозорных, восточные мосты останутся совсем без защиты.",al={"why guard thomas needs help","why courier","cant thomas send a guard","почему стражнику томасу нужна помощь","почему гонец","не может томас послать стражника"}},{q="Чем мурлоки угрожают Златоземью?",a="Как отмечает маршал Дугхан, прочитав послание, неудержимое присутствие мурлоков вдоль восточных рек быстро расширяется на запад. Без достаточного числа стражников для обороны периметра Дугхан опасается, что бои дойдут до окраин самого Златоземья уже в течение недели.",al={"murloc threat","will murlocs attack goldshire","how bad are murlocs","угроза мурлоков","нападут ли мурлоки на златоземье","насколько опасны мурлоки"}},{q="Почему Штормград не присылает подкрепления в Элвиннский лес?",a="Военные ресурсы Штормграда опасно растянуты по нескольким фронтам, а политический паралич в столице после исчезновения короля Вариана Ринна усугубляет положение. Отдаленные поселения и пограничные мосты в основном предоставлены сами себе и полагаются на местную стражу и наемных искателей приключений.",al={"why no stormwind army","where are the troops","why are defenses thin","почему нет армии штормграда","где войска","почему слабая оборона"}},{q="Что происходит после того, как маршал Дугхан прочтет донесение?",a="Понимая, что гарнизону не хватает людей, чтобы остановить натиск, маршал Дугхан должен искать другие способы снарядить и поддержать тех, кто готов держать оборону, и обращает внимание на добычу припасов и доспехов для защиты региона.",al={"next quest","what does dughan do","chain after report","следующее задание","что делает дугхан","цепочка после донесения"}},{q="Где служит стражник Томас?",a="Стражник Томас несет службу в восточной части Элвиннского леса и охраняет мосты через реки, отделяющие сердце леса от более диких земель у границы с Красногорьем.",al={"guard thomas location","where is thomas","thomas location","где стражник томас","где томас","местонахождение томаса"}}},fp="22,365,25.464.0,33.463.0,25.231.0,63.236.0,45.270.0,57.314.0,51.250.0,32.191.0"}
P.entries["quest:3901"] = {n="Игрушки-погремушки",s="«Игрушки-погремушки» — раннее испытание, которое жрец Тени Сарвис поручает только что пробудившимся Отрекшимся в Могильнике. Уничтожая двенадцать скелетов-погремушек, свежие мертвецы доказывают стойкость перед Плетью и показывают, что у них достаточно силы воли, чтобы защищать свою завоеванную свободу.",h="«Игрушки-погремушки» — раннее испытание, которое жрец Тени Сарвис поручает только что пробудившимся...",kw={"deathknell","forsaken","rattlecage","sarvis","scourge","skeletons","tirisfal","undead","могильник","отрекшиеся","погремушка","сарвис","плеть","скелеты","тирисфаль","нежить"},ang={["class:Priest"]="Служба непосредственно под началом жреца Тени Сарвиса дает недавно восставшим жрецам ранний взгляд на безжалостный прагматизм духовного пути Отрекшихся.",["faction:Horde"]="Испытания в Могильнике закаляют новых солдат Отрекшихся, делая их умелыми бойцами, готовыми защищать свою юную фракцию и оборонять Тирисфальские леса.",["race:Undead"]="Схватка со скелетами-погремушками — суровое напоминание о том, что ждет любого Отрекшегося, чей разум дрогнет; она противопоставляет вашу с трудом завоеванную самостоятельность бездумному рабству Плети."},sec={{t="Проверка решимости",b="Расправившись с бездумными зомби, бродящими по Могильнику, недавно восставшие Отрекшиеся сразу получают более суровое испытание. Жрец Тени Сарвис направляет новобранцев против скелетов-погремушек, бродящих на окраинах поселения. Эти оживленные кости лишены разума и самообладания, но бьют сильнее и сражаются яростнее, чем разлагающиеся трупы поблизости. Выжить в их грохочущих засадах значит доказать, что новобранец не дрогнет под внезапным натиском."},{t="Защита завоеванной свободы",b="Для Сарвиса и руководства Могильника уничтожение скелетов служит двойной цели. Оно защищает хрупкое убежище от натиска остатков власти Короля-лича и отсеивает тех новобранцев, что не справляются. Те, кто терпит неудачу или медлит, рискуют разделить судьбу бездумных бедолаг, блуждающих по лесу. Победа над скелетами-погремушками доказывает Сарвису, что новобранец обладает стойкостью, нужной, чтобы жить в мире, ненавидящем само его существование."}},faq={{q="Кто такие скелеты-погремушки?",a="Скелеты-погремушки — бездумная нежить, по-прежнему подчиненная Королю-личу. Лишенные плоти и разума, они бродят по окраинам Могильника и нападают на всякого, кто встретится на пути.",al={"rattlecages","what are rattlecage skeletons","who are the skeletons","погремушки","что такое скелеты-погремушки","кто такие скелеты"}},{q="Почему жрец Тени Сарвис хочет уничтожения скелетов?",a="Сарвис хочет проверить боевые умения и силу воли только что пробудившихся Отрекшихся под давлением. Кроме того, сокращение числа агрессивных скелетов защищает Могильник от натиска Плети.",al={"why kill skeletons","sarvis purpose","reason for rattling rattlecages","зачем убивать скелетов","цель сарвиса","почему игрушки-погремушки"}},{q="Где найти скелетов-погремушек?",a="Они бродят у северной и северо-восточной границ долины Могильника, сразу за деревней, где ходят бездумные зомби.",al={"rattlecage location","where to find rattlecage skeletons","skeleton spawns deathknell","где погремушки","где найти скелетов-погремушек","скелеты могильник"}},{q="Что происходит после выполнения этого задания?",a="Сарвис считает ваше начальное обучение завершенным и объявляет, что вы доказали, что достойны свободы. Затем он направляет вас к другим предводителям Могильника, чтобы помочь более широким операциям Отрекшихся.",al={"next quest after rattling rattlecages","what to do after","sarvis next step","следующее задание после игрушек-погремушек","что делать дальше","следующий шаг сарвиса"}},{q="Почему одни мертвецы свободны, а эти скелеты остаются бездумными?",a="Когда телепатическая хватка Короля-лича ослабла после Третьей войны, часть нежити вырвалась на свободу и вернула себе разум, образовав Отрекшихся. Конструкции и простые оживленные кости, как скелеты-погремушки, не сохранили ни личности, ни воли и остались целиком подчинены Плети.",al={"why are skeletons mindless","forsaken vs scourge free will","how did forsaken wake up","почему скелеты бездумны","отрекшиеся и плеть свобода воли","как очнулись отрекшиеся"}},{q="Кто такой жрец Тени Сарвис?",a="Жрец Тени Сарвис — надзиратель Отрекшихся в часовне Могильника. Он оценивает вновь восставших мертвецов, направляет их в пробуждении и следит, чтобы они были достаточно сильны для жизни свободными существами.",al={"who is sarvis","sarvis lore","shadow priest sarvis role","кто такой сарвис","сарвис предания","роль жреца тени сарвиса"}}},fp="24,308,17.519.0,27.476.0,30.195.0,59.198.0,41.132.0,41.200.0,63.280.0,28.203.0"}
P.entries["quest:3902"] = {s="«Поиски старой одежды» — раннее снабженческое задание, которое Страж смерти Салтен дает только что пробудившимся Отрекшимся в Могильнике. Пока свежая нежить выбирается из земли, Отрекшиеся должны собирать брошенные коробки и ящики по всему зараженному поселению, чтобы снарядить новичков. Это показывает острую нужду народа Сильваны, вынужденного подбирать оставленные вещи, чтобы просто выжить.",h="«Поиски старой одежды» — раннее снабженческое задание, которое Страж смерти Салтен дает только что...",kw={"deathguard saltain","deathknell","forsaken supplies","scavenged goods","scavenging deathknell","tirisfal glades","undead starter quest","страж смерти салтен","припасы отрекшихся","собранные вещи","поиски старой одежды","тирисфальские леса","стартовое задание нежити"},ang={["faction:Horde"]="Хотя Отрекшиеся состоят в союзе с далекой Ордой за морем, такие форпосты, как Могильник, вынуждены справляться с повседневным выживанием отчаянным сбором вещей на месте, а не за счет чужой помощи.",["race:Undead"]="Это задание показывает суровый этос вашей новой нежизни: никто в Азероте не проявит жалости или милосердия, и Отрекшиеся должны добывать свое будущее из грязи сами."},sec={{t="Прагматичное воскрешение",b="Только что восставшие Отрекшиеся пробуждаются в мрачном мире распада и лишений. В отличие от развитых государств с оживленными путями снабжения и арсеналами, свободная нежить в Могильнике почти ничего не имеет. Грубое требование Стража смерти Салтена отражает безжалостную практичность, необходимую, чтобы создать армию из кладбищенской земли: каждый годный лоскут ткани, кожи и железа нужно принести, чтобы одеть и вооружить тех, кто еще выбирается из могил."},{t="Выживание в Тирисфале",b="Могильник усеян остатками прежних человеческих жителей и припасами, брошенными при падении королевства под натиском Плети. Чтобы пригодные материалы не гнили в ящиках по всему поселению, Стражи смерти привлекают новорожденную нежить к сбору вещей. Как поясняет Салтайн, Отрекшиеся не ждут милостыни от мира живых и должны полагаться только на собственное трудолюбие, чтобы встать на ноги."}},faq={{q="Зачем Стражу смерти Салтену собранные вещи?",a="Страж смерти Салтен собирает снаряжение для постоянного потока только что пробудившихся Отрекшихся, встающих на соседнем кладбище. Без найденной одежды, сапог и инструментов новобранцы бродили бы по зараженным холмам безоружными и беззащитными.",al={"why scavenge goods","saltain purpose","why look for boxes","зачем собирать вещи","цель салтена","зачем искать коробки"}},{q="Где найти собранные вещи?",a="Вещи разбросаны грудами коробок и ящиков по всему Могильнику, возле заброшенных зданий и в тихих уголках поселения.",al={"where are boxes","scavenged goods locations","deathknell boxes","где коробки","места старых вещей","коробки могильник"}},{q="Кто такой Страж смерти Салтен?",a="Салтен — прагматичный Страж смерти, служащий в Могильнике; он оценивает свежих новобранцев-мертвецов и привлекает их к работе, поддерживая порядок и выживание суровой дисциплиной.",al={"who is saltain","deathguard saltain lore","кто такой салтен","страж смерти салтен предания"}},{q="Почему у Отрекшихся здесь нет обычных военных припасов?",a="Отрекшиеся — молодая, осажденная фракция, пробивающая себе место среди враждебных живых и подчиненной чужой воле Плети. В Могильнике ресурсов в обрез, и им приходится подбирать и использовать все, что осталось в руинах.",al={"why no gear","forsaken supply shortage","deathknell equipment","почему нет снаряжения","нехватка припасов отрекшихся","снаряжение могильник"}},{q="Что происходит после выполнения этого задания?",a="Салтен награждает новобранца предметом брони из общих запасов, закрепляя его превращение из неиспытанного трупа в дельного солдата Темной Госпожи.",al={"next quest","scavenging reward","следующее задание","награда за поиски"}},{q="Почему в Могильнике сейчас восстает так много новой нежити?",a="Остаточная некромантическая магия и сохраняющееся проклятие почвы Тирисфаля приводят к тому, что мертвые жители Лордерона постепенно вырываются из разрушенной хватки Короля-лича и выходят из могил растерянными, нуждаясь в немедленном руководстве.",al={"why rising","new recruits deathknell","why fresh undead","почему восстают","новобранцы могильник","почему свежая нежить"}}},fp="21,412,24.448.0,23.443.0,49.247.0,36.164.0,26.178.0,60.245.0,40.192.0,58.221.0"}
P.entries["quest:3903"] = {n="Милли Осворт",s="Милли Осворт — короткое поручение, которое Заместитель судьи Виллем в Аббатстве Североземья доверяет многообещающим новобранцам. Искателям приключений предстоит пересечь территорию аббатства и помочь Милли, местной жительнице, чья повозка и средства к существованию в опасности. Это задание знаменует переход от зачистки земель аббатства к помощи страдающим мирным жителям Элвиннского леса.",h="Милли Осворт — короткое поручение, которое Заместитель судьи Виллем в Аббатстве Североземья доверяет...",kw={"deputy willem","elwynn forest","harvest","milly osworth","northshire abbey","stables","wagon","заместитель судьи виллем","элвиннский лес","урожай","милли осворт","аббатство североземья","конюшни","повозка"},ang={["faction:Alliance"]="Это задание показывает, как тяжело приходится местным силам Альянса в Североземье: стражникам приходится полагаться на проходящих мимо искателей приключений, чтобы защитить жителей от новых угроз.",["race:Human"]="Для юных людей, начинающих путь в Североземье, замена Виллема показывает дух общины, необходимый, чтобы удерживать Элвиннский лес."},sec={{t="Надежные руки",b="Проявив себя в борьбе с ворами из Братства Справедливости, наступающими на Долину Североземья, новобранцы привлекают внимание Заместителя судьи Виллема. Увидев способную и готовую помочь подмогу, Виллем направляет искателей приключений к своей подруге Милли Осворт. Это не официальное дело гарнизона, а личная услуга: помощь мирной жительнице, оказавшейся в ловушке растущих беспорядков в долине."},{t="Беда у конюшен",b="Милли Осворт ждет у своей повозки на другой стороне Аббатства Североземья, возле конюшен. Заместитель судьи Виллем остается на посту, защищая аббатство, а проблемы Милли требуют решительных действий в долине, на которые перегруженный гарнизон стражи просто не может выделить людей."}},faq={{q="Кто посылает вас поговорить с Милли Осворт?",a="Это задание вам дает Заместитель судьи Виллем, стоящий у главных ворот Аббатства Североземья, после того как вы докажете свою надежность, расправившись с бандитами из Братства Справедливости.",al={"who gives milly osworth","quest giver milly osworth","where to get milly osworth quest","кто дает задание милли осворт","персонаж, выдающий задание милли осворт","где взять задание милли осворт"}},{q="Где найти Милли Осворт?",a="Милли Осворт находится у своей повозки на другой стороне Аббатства Североземья, возле конюшен, недалеко от виноградников на юго-востоке.",al={"milly osworth location","where is milly","where is milly osworth","где милли осворт","где найти милли","местонахождение милли осворт"}},{q="Почему Заместитель судьи Виллем не может сам помочь Милли?",a="Караульные обязанности привязывают Виллема к Аббатству Североземья. Долина страдает от бандитов и вредителей, и у местного гарнизона нет лишних людей для частных дел мирных жителей.",al={"why doesnt willem help","willem duties","why help milly","почему виллем не помогает","обязанности виллема","зачем помогать милли"}},{q="Что нужно для получения этого задания?",a="Вы должны выполнить для Заместителя судьи Виллема задание «Братство воров», прежде чем он сочтет вас достаточно надежным, чтобы помогать Милли.",al={"milly osworth requirements","brotherhood of thieves follow up","how to unlock milly osworth quest","требования милли осворт","братство воров продолжение","как открыть задание милли осворт"}},{q="С чем Милли нужна помощь?",a="Милли не справляется со своим урожаем и повозкой среди местных беспорядков, что напрямую ведет к заданию по спасению ее урожая в долине.",al={"what does milly want","milly problem","milly harvest troubles","чего хочет милли","проблема милли","урожай милли"}},{q="Кем Милли Осворт приходится Заместителю судьи Виллему?",a="Виллем называет Милли просто другом в беде, жительницей Североземья, о которой он заботится, хотя и прикован к своему посту.",al={"willem and milly","is milly related to willem","how does willem know milly","виллем и милли","родственница ли милли виллема","откуда виллем знает милли"}}},fp="13,339,26.360.0,22.301.0,42.163.0,33.141.0,43.184.0,45.127.0,31.158.0,38.141.0"}
P.entries["quest:3904"] = {n="Урожай Милли",s="Урожай Милли — простое поручение, порожденное растущим бандитским кризисом в Североземье. После того как головорезы из Братства Справедливости вынудили местную фермершу Милли Осворт бросить собранный виноград на виноградниках, искателю приключений предстоит пройти через занятые поля и вернуть ее средства к существованию, пока их не украли или не растоптали.",h="Урожай Милли — простое поручение, порожденное растущим бандитским кризисом в Североземье.",kw={"crates","defias","elwynn forest","grapes","milly osworth","milly's harvest","northshire abbey","northshire vineyards","ящики","братство справедливости","элвиннский лес","виноград","милли осворт","урожай милли","аббатство североземья","виноградники североземья"},ang={["faction:Alliance"]="Возвращая урожай Милли, юные новобранцы Альянса впервые наглядно сталкиваются с проблемой Братства Справедливости, зреющей всего в нескольких милях от Штормграда.",["race:Human"]="Для людей, начинающих путь в Североземье, защита мелких фермеров вроде Милли — основной долг защитников трудового люда Элвиннского леса."},sec={{t="Брошенный урожай",b="Собирая виноград на юго-восточных полях Долины Североземья, Милли Осворт была вынуждена спасаться бегством, когда разбойники из Братства Справедливости заполонили лозы. В панике она бросила собранный урожай в ведрах и ящиках по всем занятым рядам. Гарнизон перегружен, и она боится, что даже если стража прогонит захватчиков, тяжелые сапоги и беспорядочная драка раздавят все, что бандиты еще не унесли."},{t="Североземье под угрозой",b="Бандиты, нагло занявшие рабочие виноградники, показывают, насколько хрупкой стала безопасность Североземья. Внимание Штормграда обращено в другую сторону, стражи в долине не хватает, и обычным жителям вроде Милли остается рассчитывать на новобранцев и странников, которые защитят их имущество и обеспечат аббатство едой и вином."}},faq={{q="Кто такая Милли Осворт?",a="Милли Осворт — местная фермерша, работающая на Виноградниках Североземья. Она выращивает и собирает виноград долины, жизненно важный для виноделия Североземья, но пришедшее Братство Справедливости изгнало ее с полей.",al={"milly osworth","who is milly","grape lady","милли осворт","кто такая милли","женщина с виноградом"}},{q="Почему стража Североземья не может вернуть урожай?",a="Стражи в Долине Североземья не хватает, и она занята сдерживанием повсеместной угрозы со стороны бандитов и кобольдов. Милли также опасается, что неуклюжая военная зачистка просто втопчет ее нежный виноград в грязь.",al={"why don't guards help","northshire guards","lazy guards","почему стража не помогает","стража североземья","ленивая стража"}},{q="Что Братство Справедливости делает на виноградниках?",a="Братство Справедливости проникло в Долину Североземья, чтобы нарушить местное производство, донимать жителей и захватывать ресурсы прямо под носом у стражи Штормграда.",al={"why defias in vineyards","defias grapes","defias northshire","почему братство справедливости на виноградниках","виноград братства справедливости","братство справедливости североземье"}},{q="Где находятся ящики?",a="Ведра и ящики с урожаем разбросаны по земле на Виноградниках Североземья к юго-востоку от Аббатства Североземья, среди враждебных разбойников из Братства Справедливости, патрулирующих ряды.",al={"crate locations","where to find grapes","where is harvest","где ящики","где найти виноград","где урожай"}},{q="Что будет после того, как Милли вернет виноград?",a="Когда урожай в безопасности, Милли просит искателей приключений отнести ее «Уведомление о поставке винограда» Брату Нилзу в Аббатство Североземья, чтобы урожай был должным образом учтен и переработан в вино.",al={"next quest","after milly's harvest","what next","следующее задание","после урожая милли","что дальше"}},{q="Почему виноград важен для Аббатства Североземья?",a="Долина Североземья производит знаменитое вино и снабжает церковную общину аббатства. Урожай Милли поддерживает и местную торговлю, и погреба, которые содержит Братство Североземья.",al={"northshire wine","why grapes matter","вино североземья","почему важен виноград"}}},fp="15,286,18.474.0,25.381.0,21.225.0,53.229.0,43.180.0,29.189.0,46.191.1,45.188.0"}
P.entries["quest:3905"] = {n="Уведомление о поставке винограда",s="Когда урожай Милли Осворт спасен от воров из Братства Справедливости, она составляет уведомление с учетом возвращенного винограда. Доставив эту книгу Брату Нилзу в Аббатство Североземья, вы поможете братству пополнить знаменитые запасы вина. Это небольшая, но сладкая победа для осажденной долины.",h="Когда урожай Милли Осворт спасен от воров из Братства Справедливости, она составляет уведомление с учетом...",kw={"brother neals","defias","elwynn","grape manifest","harvest","milly osworth","northshire abbey","vineyard","wine","брат нилз","братство справедливости","элвиннский лес","уведомление о поставке винограда","урожай","милли осворт","аббатство североземья","виноградник","вино"},ang={["class:Priest"]="В Аббатстве Североземья вино ценится и как дар гостеприимства, и как священный напиток, связывая практическое земледелие с обрядами братства.",["faction:Alliance"]="Обеспечение местных запасов пищи в Североземье помогает сохранять самодостаточность главного оплота Штормграда для набора и исцеления.",["race:Human"]="Для юных людей, начинающих путь, помощь Милли и Брату Нилзу защищает одну из любимых пасторальных традиций королевства."},sec={{t="Урожай долины",b="Долина Североземья известна по всему Элвиннскому лесу плодородной почвой и тихими садами, а виноградники дают урожай, важный и для местного пропитания, и для церковной торговли. Когда воры и бандиты захватили восточные поля, они поставили под угрозу не только фрукты: они перерезали снабжение аббатства вином и едой. Теперь, когда урожай вывезен с занятых участков, уведомление официально учитывает каждую возвращенную меру."},{t="Глоток на колокольне",b="Брат Нилз заведует пищей и напитками Аббатства Североземья, но больше известен любовью пробовать местные вина высоко на тихой колокольне. Пока разбойники угрожают прямо за воротами, поступление свежего винограда дает братству повод поднять тост за Свет и ненадолго вздохнуть с облегчением."}},faq={{q="Что такое «Уведомление о поставке винограда»?",a="«Уведомление о поставке винограда» — опись, написанная фермершей Милли Осворт после того, как ее урожай винограда отбит у воров из Братства Справедливости. В ней записан спасенный урожай, чтобы интендант аббатства мог официально пополнить погреба.",al={"grape manifest item","what is manifest","millys manifest","уведомление о поставке винограда","что такое уведомление","уведомление милли"}},{q="Кто такой Брат Нилз?",a="Брат Нилз — монах, живущий в Аббатстве Североземья и отвечающий за запасы еды и напитков. Он проводит много времени, пробуя вина на колокольне аббатства.",al={"brother neals","who is neals","monk in bell tower","брат нилз","кто такой нилз","монах на колокольне"}},{q="Где найти Брата Нилза?",a="Брат Нилз находится в Аббатстве Североземья и отдыхает на колокольне с видом на окрестности.",al={"neals location","where is brother neals","find brother neals","где нилз","где брат нилз","найти брата нилза"}},{q="Почему урожай винограда так важен для Североземья?",a="Североземье производит знаменитое вино и свежие припасы, которые поддерживают местное духовенство и военных. Срыв сбора урожая угрожает и ежедневным запасам, и литургическим припасам по всему Элвиннскому лесу.",al={"why grapes matter","northshire wine lore","milly harvest significance","почему важен виноград","предания о вине североземья","значение урожая милли"}},{q="Кто угрожал урожаю Милли?",a="Разбойники из Братства Справедливости заняли восточные поля Долины Североземья, прогнали Милли Осворт и спрятали ее урожай в ящиках по всем виноградникам, пока искатели приключений не отбросили их.",al={"who stole the grapes","grape thieves","bandits in vineyards","кто украл виноград","воры винограда","бандиты на виноградниках"}},{q="Что будет после передачи уведомления Брату Нилзу?",a="Нилз дарует свое благословение во имя Света, радуясь, что погреба аббатства останутся полны свежего вина, несмотря на бандитские беды в долине.",al={"quest aftermath","does neals make wine","what follows grape manifest","что после задания","делает ли нилз вино","что после уведомления"}}},fp="14,327,20.445.0,22.363.0,27.228.0,21.183.0,30.103.0,44.209.0,36.181.0,53.170.0"}
P.entries["quest:391"] = {n="Бунтовщики в тюрьме",s="«Бунтовщики в тюрьме» — задание Альянса, которое дает Тюремщик Телвотер у ворот тюрьмы Штормграда. Чтобы подавить продолжающееся восстание и доказать свою преданность городской страже, вам приказано спуститься в хаос и убить главаря бунтовщиков Базиля Тредда.",h="«Бунтовщики в тюрьме» — задание Альянса, которое дает Тюремщик Телвотер у ворот тюрьмы Штормграда.",ang={["class:Rogue"]="Проникновение в бунт дает мрачное представление о том, что происходит, когда тайная подпольная сеть Братства Справедливости теряет всякие ограничения.",["faction:Alliance"]="Полномасштабное восстание прямо под Кварталом магов угрожает стабильности Штормграда, пока король пропал, а силы королевства растянуты.",["race:Human"]="Многие бунтовщики — агенты Братства Справедливости и недовольные каменщики, которые обратились против собственного королевства после спора о восстановлении."},sec={{t="Кровь на камне",b="Глубоко под мостовой Квартала магов Тюрьма погрузилась в полное беззаконие. Преступники, повстанцы из Братства Справедливости и жестокие головорезы вырвались на свободу и захватили камеры, превратив здание в неприступную зону боев. Тюремщик Телвотер и его стража отчаянно держатся у входа и не могут пробиться внутрь и обычными средствами восстановить порядок."},{t="Цена доверия",b="Подозревая каждого, кто интересуется Базилем Треддом, Тюремщик Телвотер устраивает жестокую проверку верности. Вместо простой встречи он приказывает вам пробиться через бушующие камеры, убить Тредда в его камере и вернуться с отрубленной головой предводителя мятежников. Лишь убив главу восстания, чужак может доказать, что не заодно с мятежом."},{t="Оборванная нить",b="Убийство Базиля Тредда наносит решающий удар по организации бунта, но лишает возможности получить от него прямые ответы о заговоре, охватившем Штормград. Увидев голову Тредда, удивленный Телвотер признает, что смерть узника может сделать тюрьму снова управляемой, и делится собственными догадками о тайных связях Тредда до начала мятежа."}},faq={{q="Кто дает задание «Бунтовщики в тюрьме»?",a="Задание дает Тюремщик Телвотер, стоящий сразу за входным туннелем Тюрьмы в Квартале магов Штормграда.",al={"who gives the stockade riots","stockade riots quest giver","where to start stockade riots","кто дает бунтовщики в тюрьме","персонаж, выдающий задание бунтовщики в тюрьме","где начать бунтовщики в тюрьме"}},{q="Что нужно сделать, чтобы выполнить задание?",a="Вы должны отправиться в тюремное подземелье, найти главаря Базиля Тредда в восточном блоке камер, убить его и вернуть его отрубленную голову Тюремщику Телвотеру.",al={"stockade riots objective","how to beat stockade riots","бунтовщики в тюрьме цель","как выполнить бунтовщики в тюрьме"}},{q="Где в Тюрьме находится Базиль Тредд?",a="От входа идите по северному коридору до Т-образного перекрестка, затем по восточному блоку камер. Базиль Тредд находится в центральной камере трехкомнатного помещения, которое охраняет огр Хрупконог.",al={"where is thredd","bazil thredd location","how to find thredd","где тредд","где базиль тредд","как найти тредда"}},{q="Почему Тюремщик Телвотер хочет смерти Базиля Тредда?",a="Базиль Тредд — главный зачинщик восстания в тюрьме. Телвотер считает, что обезглавить мятеж — единственный способ для стражи вернуть контроль над взбунтовавшимися камерами, а заодно убедиться, что вы не работаете на мятежников втайне.",al={"why kill thredd","why thelwater wants thredd dead","зачем убивать тредда","почему телвотер хочет смерти тредда"}},{q="Что будет после выполнения задания «Бунтовщики в тюрьме»?",a="После передачи головы Тредда Тюремщик Телвотер направляет вас на следующий этап расследования: в задании «Таинственный посетитель» вам предстоит выяснить, кто была загадочная фигура, навещавшая тюрьму перед бунтом.",al={"stockade riots follow up","what comes after stockade riots","бунтовщики в тюрьме продолжение","что после бунтовщиков в тюрьме"}},{q="Могут ли игроки Орды получить это задание?",a="Нет. «Бунтовщики в тюрьме» — строго задание Альянса, так как подземелье находится в глубине столицы, Штормграда.",al={"is stockade riots alliance only","horde stockade riots","бунтовщики в тюрьме только альянс","орда бунтовщики в тюрьме"}}},fp="18,266,18.405.0,18.403.1,16.404.1,39.127.0,43.165.0,50.209.0,49.279.0,49.224.1,36.116.0"}
P.entries["quest:392"] = {n="Таинственный посетитель",s="После подавления восстания в Тюрьме тюремщик Телвотер сообщает о тревожной находке, касающейся предводителя мятежников Базиля Тредда. В течение нескольких месяцев до бунта к Тредду регулярно приходил таинственный человек с подлинными бумагами на имя Маелика.",h="После подавления восстания в Тюрьме тюремщик Телвотер сообщает о тревожной находке, касающейся предводителя...",kw={"baros alexston","bazil thredd","curious visitor","defias","maelik","stockade","stonemasons","warden thelwater","барос алекстон","базиль тредд","таинственный посетитель","братство справедливости","маелик","тюрьма","каменщики","тюремщик телвотер"},ang={["class:Rogue"]="То, что тихий посетитель беспрепятственно прошел в тюрьму строгого режима с надлежащими документами, показывает тонкость и мастерство опытных лазутчиков.",["faction:Alliance"]="Выследить таинственного связного Базиля Тредда крайне важно, чтобы искоренить сторонников Братства Справедливости, открыто действующих в столице.",["race:Human"]="Подделанные или санкционированные пропуска обнажают глубокую уязвимость и возможную коррупцию внутри самого правительства Королевства Штормград."},sec={{t="Нарушение порядка",b="Базиль Тредд провел первые годы заключения в Тюрьме Штормграда всеми брошенный бывшими соратниками — так считали стражники. Все изменилось за несколько месяцев до бунта, когда к Тредду стал раз или два в неделю приходить тихий посетитель. Он проходил все проверки, предъявлял надлежащие документы и называл себя Маеликом. Тюремщик Телвотер, поняв, что эти визиты, вероятно, помогли подготовить кровавое восстание, записывает описание внешности и отправляет искателей приключений к городскому архитектору Баросу Алекстону, чтобы выяснить, кем на самом деле был этот посетитель."},{t="Связи с каменщиками",b="Барос Алекстон, тесно работавший с Эдвином ван Клифом и Гильдией каменщиков до их мятежа, оказывается втянут в расследование. Имя Маелик ему ничего не говорит, а описание внешности подошло бы бесчисленным бывшим мастерам, но то, что у посетителя был действительный пропуск, указывает на нечто гораздо более серьезное, чем обычные преступники, проскользнувшие мимо стражи. Эта тайна показывает, насколько глубоко сторонники и агенты Братства Справедливости проникли в городское управление Штормграда."}},faq={{q="Кто такой таинственный посетитель, упомянутый в задании?",a="Посетитель назвался Маеликом. Он раз или два в неделю в течение нескольких месяцев до бунта в Тюрьме навещал заключенного Базиля Тредда, предъявляя, по всей видимости, подлинные документы.",al={"who is maelik","thredd visitor","curious visitor identity","кто такой маелик","посетитель тредда","личность таинственного посетителя"}},{q="Почему тюремщик Телвотер посылает вас к Баросу Алекстону?",a="Барос Алекстон — городской архитектор Штормграда, некогда работавший вместе с Эдвином ван Клифом и Гильдией каменщиков. Поскольку Братство Справедливости возникло из каменщиков, Телвотер надеется, что Алекстон узнает посетителя по прежним связям в гильдии.",al={"why baros alexston","who is baros","turn in to baros","почему барос алекстон","кто такой барос","сдать задание баросу"}},{q="Как Маелик проник в Тюрьму незамеченным?",a="Маелик предъявил подлинные документы, полностью удовлетворявшие требованиям проверки. У стражи не было законных оснований отказать ему во входе, что говорит либо о бюрократической ошибке, либо о продажных чиновниках внутри управления королевства, помогших ему пройти.",al={"how did visitor get in","maeliks papers","stockade security failure","как посетитель проник внутрь","бумаги маелика","провал охраны тюрьмы"}},{q="Какую роль Базиль Тредд сыграл в тюремном бунте?",a="Базиль Тредд был заключенным предводителем Братства Справедливости в Тюрьме. Он организовал и возглавил жестокое восстание среди заключенных — согласованные действия, вероятно, подготовленные во время его встреч с Маеликом.",al={"who is bazil thredd","what did thredd do","кто такой базиль тредд","что сделал тредд"}},{q="Что происходит после того, как Барос Алекстон читает описание?",a="Алекстон не узнает ни имя Маелик, ни описание внешности, данное Телвотером. Однако, признав, что посетитель наверняка связан с кем-то в городе, он соглашается продолжить расследование, чтобы выяснить, кто этот незнакомец на самом деле.",al={"does baros recognize maelik","what happens next","узнал ли барос маелика","что дальше"}},{q="Почему посетитель важен для расследования дела Братства Справедливости?",a="Регулярные визиты показывают, что бунт в Тюрьме не был стихийной вспышкой беззаконной ярости, а продуманным замыслом Братства Справедливости, осуществленным при помощи кого-то с высоким уровнем доступа к официальной документации Штормграда.",al={"defias conspiracy","why does the visitor matter","заговор братства справедливости","почему важен посетитель"}}},fp="19,284,20.566.0,23.523.1,50.195.0,53.245.0,55.250.0,52.218.0,56.243.0,64.208.0"}
P.entries["quest:3921"] = {kw={"broken samophlange","mor'shan rampart","samophlange","sludge fen","sputtervalve","the barrens","undermine","wenikee boltbucket","сломанный самофланец","застава мор'шан","самофланец","нефтяное болото","пароклапан","степи","подкопье","венаки бенике"},ang={["faction:Horde"]="Лагерь Венаки стоит в тени Заставы Мор'шан — важнейшего укрепленного рубежа, защищающего земли Орды в северных Степях от вражеских вторжений из Ясеневого леса.",["profession:Engineering"]="Инженеры оценят непреодолимое любопытство, которое вызывает самофланец: даже когда ни Пароклапан, ни Венаки не знают его назначения, одни лишь сложные шестерни требуют изучения."},sec={{t="Досадная неудача",b="Sputtervalve's ambition outpaced his mechanical finesse. After having an adventurer extract the mysterious samophlange from the Venture Company's control console at the Sludge Fen, Sputtervalve couldn't resist bragging to his fellow engineers in Undermine. Unfortunately, his tinkering took a turn for the worse, leaving the delicate contraption broken. Desperate to deliver on his claims, he needs someone with sharper technical acumen to diagnose the damage and repair it."},{t="Механик у Заставы",b="Венаки Бенике разбила лагерь у дороги к югу от Заставы Мор'шан — оборонительного рубежа, разделяющего северные Степи и Ясеневый лес. Любознательная и изобретательная, она легко увлекается сложными механизмами. Увидев сломанный самофланец, она сразу заинтересовалась его внутренними шестернями и, бросив все дела, принялась разбираться, как его восстановить."}},faq={{q="Почему самофланец сломан?",a="Пароклапан попытался изучить устройство и повозиться с ним после того, как оно было извлечено из консоли в Нефтяном болоте, но повредил сложные внутренние механизмы.",al={"why broke","how did it break","sputtervalve broke it","почему сломан","как он сломался","пароклапан сломал его"}},{q="Кто такая Венаки Бенике?",a="Это изобретательная гоблинша-механик, живущая к югу от Заставы Мор'шан на границе северных Степей и Ясеневого леса и известная своим умением обращаться со сложными механизмами.",al={"who is wenikee","boltbucket location","where is wenikee","кто такая венаки","где найти бенике","где венаки"}},{q="Почему Пароклапану так важно его починить?",a="Пароклапан уже похвастался перед коллегами в Подкопье, что заполучил устройство. Если он не предоставит работающий прибор, его репутация и положение серьезно пострадают.",al={"why fix samophlange","sputtervalve undermine","why does he care","зачем чинить самофланец","пароклапан подкопье","почему он переживает"}},{q="Знает ли Венаки, для чего нужен самофланец?",a="Нет. Когда ей впервые показывают его, она спрашивает, что вообще такое самофланец, но звук сложных шестерен завораживает ее, и она хочет починить его просто чтобы увидеть, что он делает.",al={"does she know what it is","what is a samophlange to her","знает ли она что это","что такое самофланец для нее"}},{q="Где находится Застава Мор'шан?",a="Застава Мор'шан — укрепленный форпост Орды на северной границе Степей, охраняющий проход в Ясеневый лес.",al={"mor'shan rampart location","where is rampart","barrens ashenvale border","где застава мор'шан","где застава","граница степей и ясеневого леса"}},{q="Что происходит после того, как Венаки осматривает сломанное устройство?",a="Заинтересовавшись конструкцией, Венаки Бенике соглашается починить самофланж, но ему нужны определенные механические детали, начиная с металлических заготовок, хранящихся в ведрах с инструментами Торговой Компании в Нефтяном болоте, чтобы снова запустить шестерни.",al={"what next","nugget slugs","samophlange next step","что дальше","металлические заготовки","следующий шаг самофланец"}}},fp="18,313,17.474.0,27.433.0,30.180.0,26.182.0,51.202.0,51.177.0,38.131.0,54.232.1"}
P.entries["quest:3922"] = {n="Металлические заготовки",s="«Металлические заготовки» — задание в северных Степях, которое дает эксцентричная механичка Венаки Бенике. Горя желанием починить найденный самофланец и поэкспериментировать с ним, она поручает искателям приключений обыскать буровые работы Торговой Компании в Нефтяном болоте в поисках запчастей.",h="«Металлические заготовки» — задание в северных Степях, которое дает эксцентричная механичка Венаки Бенике.",kw={"barrens","nugget slugs","samophlange","sludge fen","tool buckets","venture company","wenikee boltbucket","степи","металлические заготовки","самофланец","нефтяное болото","ведра с инструментами","торговая компания","венаки бенике"},ang={["faction:Horde"]="Вторжения Торговой Компании в Нефтяное болото — постоянная экологическая напасть для Орды, поэтому любой повод украсть их припасы приветствуется.",["profession:Engineering"]="Любой практикующий инженер узнает характерные признаки гоблинской работы задолго до того, как поспешный ремонт Венаки взорвется у нее перед лицом."},sec={{t="Инженерные нужды Венаки",b="Завладев хитроумным самофланцем, Венаки Бенике решила повозиться со странной машиной и понять, как она работает. Однако точная гоблинская механика требует особых деталей. Не имея материалов, Венаки посылает помощников стащить заготовки калибра семнадцать с половиной у местных рабочих Торговой Компании, которые беспечно оставляют тяжелые ведра с инструментами возле нефтяных вышек в Нефтяном болоте."},{t="Взрывной прорыв",b="Чтобы собрать пятнадцать специальных металлических заготовок, приходится уворачиваться от рабочих и лесорубов Торговой Компании, хозяйничающих в болотах к востоку от дороги. Получив детали, Венаки тут же ставит самофланец на землю и начинает его настраивать. Как и подобает гоблинской инженерии, гремучая смесь неподходящих деталей и поспешной сборки приводит к внезапному катастрофическому взрыву — Венаки потрясена, но на удивление не падает духом."}},faq={{q="Что такое металлическая заготовка?",a="На языке гоблинской инженерии металлические заготовки — это небольшие стандартные металлические крепежные детали или компоненты боеприпасов. Венаки нужны заготовки калибра семнадцать с половиной, чтобы подключить их к хрупким внутренним шестерням самофланца.",al={"nugget slug","nugget slugs","what are nugget slugs","металлическая заготовка","металлические заготовки","что такое металлические заготовки"}},{q="Кто такая Венаки Бенике?",a="Венаки Бенике — независимый механик, разбивший лагерь у главной тропы в северных Степях. Она одержимо увлечена сложными механизмами, особенно самофланцами, несмотря на очевидную опасность.",al={"wenikee","who is wenikee","wenikee boltbucket","венаки","кто такая венаки","венаки бенике"}},{q="Где найти металлические заготовки?",a="Их собирают из ведер с инструментами, разбросанных по Нефтяному болоту — промышленному лагерю по заготовке леса и добыче нефти, который Торговая Компания устроила к востоку от небольшой стоянки Венаки у дороги.",al={"where are tool buckets","find nugget slugs","sludge fen buckets","где ведра с инструментами","найти металлические заготовки","ведра нефтяное болото"}},{q="Что происходит, когда Венаки чинит самофланец?",a="Как только Венаки получает детали и принимается за машину, та перегружается и взрывается прямо у нее перед лицом, показывая опасную взрывоопасность плохо настроенных механизмов.",al={"does the samophlange work","samophlange explosion","wenikee explosion","работает ли самофланец","взрыв самофланца","взрыв венаки"}},{q="Зачем Торговой Компании Нефтяное болото?",a="Торговая Компания устроила Нефтяное болото, чтобы разрабатывать недра и добывать нефть и другие природные ресурсы на болотах Степей, загрязняя окрестности тяжелыми буровыми установками и нефтеперерабатывающими заводами.",al={"why venture co sludge fen","sludge fen purpose","venture company barrens","зачем торговая компания нефтяное болото","назначение нефтяного болота","торговая компания степи"}},{q="Открывает ли это задание новые поручения?",a="Да. После неудачной попытки починки Венаки отправляет вас в Оргриммар к Рилли Грязегобу, бывшему инженеру Торговой Компании, в рамках задания «Рилли Грязегоб».",al={"what comes next","follow up quest","after nugget slugs","что дальше","следующее задание","после металлических заготовок"}}},fp="12,275,27.451.0,23.471.1,22.242.0,26.252.0,33.198.0,50.201.1,45.208.0,41.165.1"}
P.entries["quest:3923"] = {n="Рилли Грязегоб",s="Это задание отправляет приключенца с поврежденным самофланжем от изобретателя Венаки Бенике прямо в Оргриммар. Ища специалиста, который действительно понимает происхождение устройства, Венаки направляет вас к Рилли Грязегобу, бывшему инженеру Торговой Компании, работающему в механической мастерской Ногга.",h="Это задание отправляет приключенца с поврежденным самофланжем от изобретателя Венаки Бенике прямо в Оргриммар.",kw={"broken and battered samophlange","nogg's machine shop","orgrimmar","rilli greasygob","samophlange","valley of honor","venture company","wenikee boltbucket","сломанный и помятый самофланж","механическая мастерская ногга","оргриммар","рилли грязегоб","самофланж","аллея чести","торговая компания","венаки бенике"},ang={["faction:Horde"]="Орда полагается на городские мастерские вроде мастерской Ногга в Оргриммаре, чтобы переделывать трофейные механизмы у хищных синдикатов, наживающихся на Калимдоре.",["profession:Engineering"]="Каждый инженер знает, когда пора отложить гаечный ключ; осознание Бенике, что новые шкалы лишь ухудшат дело, ведет прямо к профессиональным тайнам, хранимым бывшими корпоративными техниками."},sec={{t="Когда изобретательство бессильно",b="Венаки Бенике попыталась определить неисправность самофланжа, найденного на буровой площадке Торговой Компании в Степях. К несчастью, дополнительные датчики лишь подтвердили, что устройство вот-вот полностью развалится. Понимая, что новые рычаги и шкалы могут окончательно погубить прибор, Бенике признала поражение и решила передать задачу тому, кто обладает закрытыми знаниями."},{t="Бывший работник Компании",b="Чтобы разобраться во внутреннем устройстве механизма, Бенике отправляет путников в Аллею Чести Оргриммара, в механическую мастерскую Ногга. Там работает Рилли Грязегоб, инженер, некогда освоивший ремесло в беспощадных рядах Торговой Компании. Грязегоб сразу узнает механизм и поражается, что кто-то уцелел, роясь в спорных владениях картеля в Степях."}},faq={{q="Кто такой Рилли Грязегоб?",a="Рилли Грязегоб — гоблин-инженер, работающий в механической мастерской Ногга в Аллее Чести Оргриммара. Раньше он работал на Торговую Компанию, поэтому редко кто так хорошо знает технологии картеля, включая загадочные устройства вроде самофланжа.",al={"rilli greasygob","who is rilli","nogg machine shop rilli","рилли грязегоб","кто такой рилли","рилли в мастерской ногга"}},{q="Почему Венаки Бенике не смогла починить самофланж сама?",a="Венаки Бенике пыталась определить неисправность самофланжа, подключив дополнительные датчики, но они показали, что его конструкция стремительно разрушается. Поняв, что беспорядочное ковыряние лишь погубит хрупкий прибор, она решила, что нужен тот, кто сам работал над изделиями Торговой Компании.",al={"why send to rilli","boltbucket failure","wenikee cant fix","почему к рилли","неудача бенике","венаки не может починить"}},{q="Где находится Рилли Грязегоб?",a="Рилли Грязегоб находится в механической мастерской Ногга в Аллее Чести, в северо-восточном районе Оргриммара.",al={"rilli greasygob location","where is greasygob","find rilli","где рилли грязегоб","где грязегоб","найти рилли"}},{q="Какую роль играет в этом Торговая Компания?",a="Самофланж нашли на карьере Торговой Компании в Нефтяном болоте на севере Степей. Это особая технология Торговой Компании, поэтому только бывшие ее сотрудники, такие как Рилли Грязегоб, способны правильно обслуживать и понимать ее.",al={"venture co connection","why venture company","who made the samophlange","торговая компания","при чем торговая компания","кто создал самофланж"}},{q="Что будет после передачи самофланжа Рилли?",a="Узнав устройство, Рилли Грязегоб решает, что для его полноценной работы или восстановления нужны официальные инструкции Торговой Компании, и приключенцы отправляются за Руководством по самофланжу.",al={"what next after rilli","samophlange questline continuation","что дальше после рилли","продолжение цепочки самофланжа"}},{q="Что вообще такое самофланж?",a="Похоже, никто толком не знает. Это замысловатое, странное устройство Торговой Компании, полное шестеренок; даже Венаки Бенике пришлось спрашивать, что это, а Рилли нужно собственное руководство Компании, чтобы в нем разобраться.",al={"what is a samophlange","samophlange explained","что такое самофланж","самофланж объяснение"}}},fp="15,302,20.416.0,20.397.0,23.282.0,60.312.0,33.129.0,43.286.0,51.219.1,29.220.0"}
P.entries["quest:3924"] = {n="Руководство по самофланжу",s="Руководство по самофланжу — задание, которое выдает гоблин-инженер Рилли Грязегоб в Оргриммаре. Решив починить сломанный самофланж, Рилли отправляет приключенцев обратно в Степи, чтобы вырвать у его бывшего соперника из Торговой Компании закрытые инструкции по эксплуатации устройства.",h="Руководство по самофланжу — задание, которое выдает гоблин-инженер Рилли Грязегоб в Оргриммаре.",kw={"barrens","boss copperplug","boulder lode mine","manual","orgrimmar","rilli greasygob","samophlange","sputtervalve","venture company","степи","начальник медная пробка","каменный карьер","руководство","оргриммар","рилли грязегоб","самофланж","пароклапан","торговая компания"},ang={["faction:Horde"]="Помощь гоблинам-специалистам в Оргриммаре позволяет получить ценные технические трофеи и нанести ответный удар по хищным операциям Торговой Компании на соседних землях.",["profession:Engineering"]="Инженеры оценят абсурдную секретность гоблинской корпоративной интеллектуальной собственности, где сложные схемы разрывают на части и прячут, чтобы коллеги не скопировали изобретения."},sec={{t="Корпоративное соперничество и профессиональные тайны",b="В наемничьих рядах Торговой Компании технические знания — это валюта. Рилли Грязегоб раньше работал вместе с начальником Медноклином, надзирателем, который с параноидальной скрытностью оберегал устройство загадочного самофланжа. Вместо того чтобы делиться руководством, Медноклин раздавал отдельные страницы лишь доверенным подчиненным, оставляя равных себе, как Рилли, в полном неведении."},{t="Проникновение в Каменный карьер",b="Чтобы разобраться в сложном механизме, привезенном из Степей, Рилли отправляет путников проникнуть в Каменный карьер на северо-востоке Степей. Чтобы добыть руководство, нужно найти самого начальника Медноклина и собрать разрозненные страницы, розданные им на работах в карьере, чтобы получить полное руководство по ремонту непонятного устройства."}},faq={{q="Что такое Руководство по самофланжу?",a="Это техническое руководство пользователя с описанием устройства и порядка ремонта самофланжа — сложного и причудливого механизма, который использует Торговая Компания.",al={"what is the manual","samophlange manual item","user manual","что за руководство","руководство по самофланжу предмет","инструкция"}},{q="Кто такой начальник Медноклин?",a="Начальник Медноклин — надзиратель Торговой Компании в Каменном карьере на северо-востоке Степей. Он бывший соперник Рилли Грязегоба и ревниво прятал секреты эксплуатации и страницы руководства по самофланжу.",al={"copperplug","who is copperplug","boss copperplug","медная пробка","кто такой медная пробка","начальник медная пробка"}},{q="Где находится Каменный карьер?",a="Каменный карьер врезан в горы на северо-востоке Степей, к северу от Перекрестка и к западу от побережья.",al={"boulder lode location","where is boulder lode","find boulder lode mine","где каменный карьер","расположение каменного карьера","найти каменный карьер"}},{q="Зачем Рилли Грязегобу нужно руководство?",a="Рилли считает, что сможет починить и запустить сломанный самофланж, привезенный из Степей, но закрытая и запутанная конструкция устройства требует официальных инструкций по эксплуатации.",al={"why rilli wants manual","why fix samophlange","зачем рилли руководство","зачем чинить самофланж"}},{q="Какое отношение к заданию имеет Пароклапан?",a="Пароклапан — знакомый из Кабестана, который сначала искал сведения об устройстве и поддерживает связь с Рилли, передавая благодарность и плату за добытые чертежи механизма.",al={"sputtervalve connection","ratchet goblin sputtervalve","пароклапан","гоблин пароклапан из кабестана"}},{q="Что будет после возвращения руководства?",a="Рилли с восторгом забирает руководство, чтобы изучить его в надежде наконец наладить механизм, хотя починка столь загадочного устройства остается трудной механической головоломкой.",al={"quest conclusion","does rilli fix it","конец задания","починит ли рилли"}}},fp="18,269,37.423.0,28.378.1,31.173.0,23.230.0,39.144.0,41.211.0,41.209.0,42.189.0"}
P.entries["quest:393"] = {n="Тень прошлого",s="Тень прошлого — задание Альянса, расследование, ведущее от городского архитектора Бароса Алекстона к Мастеру Матиасу Шоу, главе ШРУ. После расспросов о таинственном посетителе, говорившем с заключенным главарем Братства Справедливости Базилем Треддом, след уходит от публичных строительных скандалов к тайной разведке Штормграда.",h="Тень прошлого — задание Альянса, расследование, ведущее от городского архитектора Бароса Алекстона к Мастеру...",kw={"baros alexston","bazil thredd","gregor lescovar","maelik","marzon","mathias shaw","shadow of the past","si:7","stormwind","барос алекстон","базиль тредд","грегор лесковар","маелик","марзон","матиас шоу","тень прошлого","шру","штормград"},ang={["class:Rogue"]="Доклад Мастеру Матиасу Шоу в Старом городе дает разбойникам прямой взгляд на вершину искусства шпионажа и политического наблюдения Альянса.",["faction:Alliance"]="Этот этап расследования отмечает точку, где мелкий разбой Братства Справедливости напрямую смыкается с продажной знатью Штормграда.",["race:Human"]="Для людей Штормграда это задание показывает, насколько раздроблен правящий класс королевства в отсутствие короля Вариана Ринна."},sec={{t="Зацепка в тенях",b="Расспросив Тюремщика Телвотера о подозрительных посетителях главного заключенного Тюрьмы, Базиля Тредда, следователи зашли с Баросом Алекстоном в тупик. Городской архитектор не может назвать таинственную личность, но указывает на человека, чье дело — знать все секреты, шепотом передаваемые в столице: Мастера Матиаса Шоу, главу тайной разведки ШРУ."},{t="Разоблачение посетителя",b="Доставка запечатанного описания в штаб ШРУ в Старом городе дает немедленный результат. Шоу быстро разгадывает вымышленное имя посетителя — «Маелик». Узнав приметы профессионального убийцы, сбрасывающего имена как плащи, Шоу опознает в нем убийцу, чаще всего называющего себя Марзон."},{t="Предательство среди знати",b="Шоу сообщает, что Марзона сейчас нанимает лорд Грегор Лесковар, штормградский дворянин, и без того известный лживостью. Это открывает пугающую истину: преступное восстание Братства Справедливости — не просто далекий мятеж в Западном Крае, а заговор, проникший глубоко в аристократические залы Штормграда."}},faq={{q="Кто посылает вас к Матиасу Шоу?",a="Барос Алекстон, городской архитектор Штормграда, направляет вас к Матиасу Шоу, признав, что не может опознать посетителя, описанного в записях тюремщика Тюрьмы. Алекстон напоминает Шоу о старом личном долге, чтобы привлечь внимание главы шпионов.",al={"who gives this quest","quest giver shadow of the past","кто дает это задание","персонаж, выдающий задание тень прошлого"}},{q="Где находится Мастер Матиас Шоу?",a="Мастер Матиас Шоу находится в штабе ШРУ в Старом городе Штормграда. Здание служит тайным нервным центром для разбойников, разведчиков и офицеров разведки короны.",al={"mathias shaw location","where is shaw","find mathias shaw","где матиас шоу","где шоу","найти матиаса шоу"}},{q="Кто был таинственным посетителем Тюрьмы?",a="Посетитель назвался Маеликом, но Матиас Шоу опознает в нем печально известного убийцу, которого часто называют Марзон. Шоу отмечает, что профессиональные убийцы постоянно берут и бросают прозвища, а Марзон — просто еще одна маска.",al={"who is maelik","who is thredds visitor","who is the assassin","кто такой маелик","кто посетитель тредда","кто убийца"}},{q="Почему в это замешан лорд Грегор Лесковар?",a="По словам Матиаса Шоу, убийца Марзон состоит на жалованье у лорда Грегора Лесковара, штормградского дворянина, известного темными делами. Это напрямую связывает заключенное руководство Братства Справедливости с аристократией Штормграда.",al={"who does marzon work for","lescovar connection","на кого работает марзон","связь с лесковаром"}},{q="Что означает ШРУ?",a="ШРУ расшифровывается как Штормградское разведывательное управление, 7-й отдел. Это тайное оперативное и шпионское подразделение Королевства Штормград, собирающее сведения и выполняющее тайные задания в стране и за рубежом.",al={"what is si7","si:7 meaning","что такое шру","шру значение"}},{q="Почему Барос Алекстон имеет влияние на ШРУ?",a="Барос Алекстон упоминает, что Матиас Шоу должен ему услугу, но намеренно не раскрывает подробностей. Как главный архитектор города, Алекстон, вероятно, знает подземные ходы, тайные проходы и планировку зданий Штормграда, что оказалось бесценным для шпионской сети.",al={"why does shaw owe baros","baros and shaw connection","почему шоу должен баросу","связь бароса и шоу"}}},fp="18,335,21.391.0,21.315.1,25.328.2,30.249.0,37.192.0,47.220.1,37.216.1,25.204.0,44.293.0"}
P.entries["quest:394"] = {n="Голова чудовища",s="После убийства вероломного лорда Грегора Лесковара это задание направляет вас от Иллинга Триаса к Мастеру Матиасу Шоу в Старый город. Доклад о смерти Лесковара укрепляет ваше положение в тайной разведке Штормграда.",h="После убийства вероломного лорда Грегора Лесковара это задание направляет вас от Иллинга Триаса к Мастеру...",kw={"elling trias","head of the beast","lescovar","mathias shaw","old town","si:7","stormwind","иллинг триас","голова чудовища","лесковар","матиас шоу","старый город","шру","штормград"},ang={["class:Rogue"]="Доклад лично Матиасу Шоу служит важным обрядом посвящения, подтверждая вашу надежность главе главной теневой организации Штормграда.",["faction:Alliance"]="Устранение продажных аристократов внутри Штормграда помогает стабилизировать державу в период глубоко дестабилизирующего отсутствия короля Вариана Ринна."},sec={{t="Дело закрыто",b="Лорд Лесковар сражен прежде, чем его заговоры против державы принесли плоды, и непосредственная угроза руководству Штормграда устранена. Торговец сыром и опытный агент Иллинг Триас сразу уводит вас от места преступления в тени Старого города, предостерегая не кружить голову придворной похвалой."},{t="Доклад главе шпионов",b="В скрытых покоях Старого города Мастер Матиас Шоу руководит тайным аппаратом королевства через ШРУ. Получив весть о гибели Лесковара, Шоу отмечает ваше мастерство и беспощадность, тепло хвалит вашу действенность и благодарит за великую услугу народу Штормграда."}},faq={{q="В чем цель этого задания?",a="Это краткое задание поручает вам дойти от Иллинга Триаса до Мастера Матиаса Шоу в Старом городе Штормграда, чтобы подтвердить, что лорд Грегор Лесковар убит.",al={"head of the beast quest","what do i do in head of the beast","задание голова чудовища","что делать в голове чудовища"}},{q="Кто такой Матиас Шоу?",a="Матиас Шоу — глава ШРУ, тайной разведывательной службы и гильдии убийц Штормграда, незаметно действующей из Старого города.",al={"shaw","master shaw","si7 leader","шоу","мастер шоу","глава шру"}},{q="Почему Иллинг Триас посылает вас к Шоу, а не к дворцовой страже?",a="Триас действует в глубине разведки Штормграда. Поскольку Лесковар был видным дворянином, виновным в государственной измене, разбираться с последствиями нужно скрытно, а не устраивать публичный скандал среди стражи.",al={"why shaw not guards","why report to shaw","почему шоу а не стража","почему докладывать шоу"}},{q="Какую угрозу Лесковар представлял для Штормграда?",a="Лорд Грегор Лесковар действительно строил заговоры с подрывными агентами против короны и безопасности столицы, предавая державу изнутри знати.",al={"lescovar threat","what did lescovar do","угроза лесковара","что сделал лесковар"}},{q="Что будет после доклада о смерти Лесковара?",a="Матиас Шоу готовится закрыть дело о заговоре и направляет вас к окончательному разрешению подрывной угрозы, нависшей над Штормградом.",al={"next quest after head of the beast","what comes next","следующее задание после голова чудовища","что дальше"}},{q="Где можно найти Матиаса Шоу?",a="Матиас Шоу находится в командном здании ШРУ, укрытом в Старом городе в восточных кварталах Штормграда.",al={"shaw location","where is mathias shaw","где шоу","где матиас шоу"}}},fp="21,255,17.347.1,26.301.0,34.163.0,20.135.0,67.217.0,43.160.0,46.147.0,32.127.0"}
P.entries["quest:395"] = {n="Гибель братства",s="«Гибель братства» — завершение тайной операции против лорда Грегора Лесковара в Крепости Штормграда. После смерти предателя-дворянина Мастер Матиас Шоу отправляет вас к городскому архитектору Баросу Алекстону и предостерегает: не говорите, кто на самом деле нанес смертельный удар.",h="«Гибель братства» — завершение тайной операции против лорда Грегора Лесковара в Крепости Штормграда.",kw={"baros alexston","brotherhood's end","defias","elling trias","gregor lescovar","mathias shaw","si:7","stormwind keep","барос алекстон","гибель братства","братство справедливости","иллинг триас","грегор лесковар","матиас шоу","шру","крепость штормграда"},ang={["class:Rogue"]="Предостережения Матиаса Шоу отражают негласное правило операций ШРУ: вершить правосудие королевства молча и никогда не требовать публичной славы за кровь дворянина.",["faction:Alliance"]="Раскрытие заговора Братства Справедливости в Крепости Штормграда доказывает, что королевству угрожает подрыв не только от бандитов по всей стране, но и изнутри собственных дворянских залов.",["race:Human"]="Для людей Штормграда это поручение замыкает круг мятежа каменщиков, начавшегося на улицах города много лет назад, и обеспечивает справедливость, не разрывая королевство на части."},sec={{t="Незавершенные дела в тени",b="После убийства лорда Грегора Лесковара и его связного из Братства Справедливости, Марзона Бесшумного Клинка, Мастер Матиас Шоу советует соблюдать крайнюю осторожность. Убийство высокопоставленного дворянина в королевской крепости чревато политическими опасностями, даже если Лесковар увяз в измене по уши. Шоу советует рассказать Баросу Алекстону о заговоре Братства Справедливости лишь в общих чертах, а о вашей роли убийцы и об участии разбойника-сыроторговца Иллинга Триаса умолчать полностью."},{t="Вздох облегчения",b="Барос Алекстон, городской архитектор, некогда помогавший отстраивать Штормград как каменщик, встречает весть о гибели Лесковара с огромным облегчением. Алекстон и другие видные участники восстановления города были намеченными целями мести Эдвина ван Клифа после того, как каменщиков выгнали без платы. Теперь, когда Лесковар умолк, а заговор расстроен, Алекстон считает, что непосредственная угроза расправы над архитекторами и знатью королевства наконец миновала."}},faq={{q="Что происходит в задании «Гибель братства»?",a="Убрав лорда Грегора Лесковара в Крепости Штормграда, вы докладываете Мастеру Матиасу Шоу в ШРУ. Шоу велит вам явиться к городскому архитектору Баросу Алекстону, который тревожно ждет вестей: удалось ли сорвать заговор Братства Справедливости против правителей города.",al={"what is brotherhoods end","brotherhoods end quest overview","brotherhoods end summary","что такое гибель братства","гибель братства задание","гибель братства описание"}},{q="Почему Шоу велит не признаваться в убийстве Лесковара?",a="Лорд Грегор Лесковар был знатным вельможей из Дома знати Штормграда. Хотя было доказано, что он был в сговоре с Братством Справедливости, публичное признание в убийстве аристократа в королевской крепости грозит политическим скандалом и мстительными проверками. Шоу знает жестокую политику города и советует оставить это деяние безымянным.",al={"why hide lescovar death","why lie about lescovar","shaw advice lescovar","зачем скрывать смерть лесковара","почему лгать о лесковаре","совет шоу лесковар"}},{q="Почему никто не должен упоминать Иллинга Триаса?",a="Иллинг Триас притворяется простым торговцем сыром в Торговом квартале, но на деле он опытный агент, тесно связанный с ШРУ, и в прошлом знаменитый разбойник. Раскрытие его участия в разоблачении заговора погубило бы его прикрытие и поставило под угрозу его обширную подпольную сеть.",al={"why hide trias","trias secret","selling trias cheese vendor","зачем скрывать триаса","тайна триаса","триас торговец сыром"}},{q="Почему Барос Алекстон лично опасался Братства Справедливости?",a="Барос Алекстон был членом Гильдии каменщиков и помогал отстраивать Штормград вместе с Эдвином ван Клифом. Когда Дом знати отказался платить рабочим, каменщики подались в разбойники, а Алекстон, оставшийся на службе города, оказался прямо на линии мести ван Клифа.",al={"why does alexston care","baros alexston vancleef","alexston defias connection","почему алекстон переживает","барос алекстон ван клиф","алекстон братство справедливости"}},{q="Означает ли это задание конец угрозы Братства Справедливости?",a="Хотя задание устраняет главного сторонника Эдвина ван Клифа в Доме знати, присутствие Братства Справедливости оно не уничтожает полностью. Однако потеря Лесковара наносит решающий удар по их проникновению в управление Штормграда и предотвращает немедленный переворот изнутри городских стен.",al={"is the defias destroyed","are the defias dead now","does brotherhood end finish defias","уничтожено ли братство справедливости","братство справедливости мертво","гибель братства конец братства"}},{q="Куда ведет расследование дальше?",a="Обрадованный вашим успехом в устранении заговорщиков, Барос Алекстон готовит для короля доклад о Братстве Справедливости и просит вас лично доставить его на приеме в Крепости Штормграда в задании «Аудиенция у короля».",al={"what quest is next","next after brotherhoods end","who do i see next","какое задание дальше","что после гибели братства","к кому идти дальше"}}},fp="17,288,25.495.1,18.484.0,34.259.0,56.347.0,39.294.1,61.307.0,50.287.0,40.239.1"}
P.entries["quest:396"] = {n="Аудиенция у короля",kw={"audience with the king","baros alexston","brotherhood's end","defias report","edwin vancleef","katrana prestor","stormwind keep","varian wrynn","аудиенция у короля","барос алекстон","гибель братства","доклад о братстве справедливости","эдвин ван клиф","катрана престор","крепость штормграда","вариан ринн"},ang={["class:Rogue"]="Вход в высший зал власти ради доклада о падении Эдвина ван Клифа напоминает, как тонка грань между королевским агентом и главой вне закона.",["faction:Alliance"]="Доставка этого доклада завершает один из крупнейших внутренних кризисов, угрожавших главному человеческому королевству Альянса.",["race:Human"]="Для людей Штормграда эта аудиенция — горько-сладкий рубеж: она мстит за ужас, пронесшийся по Западному Краю, но тихо обнажает хрупкое состояние королевства без короля."},sec={{t="Королевский вызов",b="После поражения Эдвина ван Клифа и разгрома заговора под Луноречьем городской архитектор Барос Алекстон составляет официальное досье для Короны. Алекстон настаивает, что перед монархом должен предстать искатель приключений, сокрушивший преступное предприятие Братства. Пронеся подробный доклад через большие каналы к Крепости Штормграда, посланник прибывает в ожидании аудиенции у государя."},{t="Пустой трон",b="Upon stepping into the royal court, the bearer of the report does not find King Varian Wrynn awaiting them. Instead, royal adviser Lady Katrana Prestor receives the dossier on the Crown's behalf. Prestor smoothly dismisses the monarch's absence, explaining that King Varian is away on an extended diplomatic mission and cannot offer congratulations in person. She accepts the report, commends the hero for sparing Stormwind from VanCleef's schemes, and offers a reward in the missing king's name, neatly filing away the grim truth of the brotherhood's uprising."}},faq={{q="Почему доклад доставляю я, а не Барос Алекстон?",a="Барос Алекстон считает, что вы заслужили эту честь своей работой в поле. Раз вы сами выследили заговор Братства Справедливости в Западном Крае и штурмовали Мертвые копи, Алекстон настаивает, чтобы вы лично представили выводы и получили признание Короны.",al={"why deliver report","baros alexston report","audience with king delivery","зачем доставлять доклад","доклад бароса алекстона","аудиенция у короля доставка"}},{q="Где король Вариан Ринн?",a="Короля Вариана Ринна нет в Крепости Штормграда. Официально придворные объясняют, что король в тайной дипломатической поездке, а его юный сын Андуин остается на троне под регентством верховного лорда Болвара Фордрагона.",al={"where is the king","why isnt varian here","where is varian wrynn","missing king","где король","почему вариана нет","где вариан ринн","пропавший король"}},{q="Кто на самом деле принимает доклад о Братстве Справедливости?",a="Леди Катрана Престор принимает вас в королевском дворе. Как главная советница трона, она принимает доклад Бароса Алекстона, хвалит вас за устранение Эдвина ван Клифа и выдает награду от имени Короны.",al={"who finishes the quest","who do i talk to in keep","who takes report","кто завершает задание","с кем говорить в крепости","кто принимает доклад"}},{q="Завершает ли это задание цепочку заданий о Братстве Справедливости?",a="Да. Это задание — формальное политическое завершение обширной истории Братства Справедливости, которая начинается в первых заданиях Западного Края и проходит через подземелье Мертвые копи.",al={"end of defias chain","is this the last defias quest","deadmines aftermath","конец цепочки братства справедливости","последнее задание братства справедливости","после мертвых копей"}},{q="Почему леди Катрана Престор так пренебрежительно относится к отсутствию короля?",a="Престор демонстрирует полное самообладание, чтобы сохранить порядок при дворе. Уверяя посетителей, что король Вариан просто занят далекими государственными делами, регентство пытается приглушить тревогу о местонахождении Короны.",al={"why is prestor calm","prestor diplomatic mission","prestor excuse","почему престор спокойна","престор дипломатическая поездка","престор отговорка"}},{q="Что станет с Братством Справедливости после этого?",a="После смерти Эдвина ван Клифа и срыва их грандиозного проекта «Джаггернаут» руководство Братства разгромлено. Однако разрозненные разбойники и остатки по-прежнему донимают Западный Край, Красногорье и переулки Штормграда.",al={"are defias gone","what happens to defias now","is the brotherhood destroyed","исчезло ли братство справедливости","что станет с братством справедливости","уничтожено ли братство"}}},fp="25,413,15.443.0,15.561.1,58.256.0,27.227.0,37.219.0,53.162.0,71.228.0,50.215.0"}
P.entries["quest:397"] = {n="За достойную службу",s="«За достойную службу» — задание чернокнижников в Штормграде. Выполняя поручение Зардета Черного Когтя, чернокнижники докладывают собранию под «Забитым ягненком», чтобы завершить службу и получить награду.",h="«За достойную службу» — задание чернокнижников в Штормграде.",kw={"a noble brew","black claw","imp","lord wishock","stormwind","the slaughtered lamb","zardeth","zggi","благородный напиток","черный коготь","бес","лорд вишлок","штормград","забитый ягненок","зардет","згги"},ang={["class:Warlock"]="Это поручение показывает беспощадный прагматизм, необходимый для выживания в Штормграде: защищать свой ковен, устраняя любопытных вельмож, прежде чем они натравят на вас городскую стражу.",["faction:Alliance"]="Под безупречными шпилями и набожностью Штормграда скрыта теневая изнанка, где запретные чернокнижники тайно убирают знатных наблюдателей, чтобы защитить свое присутствие."},sec={{t="Молчание, купленное во тьме",b="Под поверхностью Штормграда последователи темных искусств существуют на шатком попустительстве. Когда знатные власти, такие как лорд Вишлок, грозят раскрыть или нарушить их тайные занятия, ковен действует решительно. Подстроив смерть Вишлока отравленным напитком, чернокнижники сохраняют свое укрытие под «Забитым ягненком»."},{t="Дар мастера",b="Получив весть, что Вишлок выпил свой последний напиток, Зардет Черный Коготь считает непосредственную угрозу устраненной. В награду за то, что стража и любопытные вельможи остались в стороне, Зардет поручает своему хныкающему слуге, бесу Згги, передать верному последователю темный знак благодарности."}},faq={{q="Кто такой Зардет Черный Коготь?",a="Зардет Черный Коготь — видный чернокнижник, тайно действующий в Штормграде. Он оберегает скрытых темных магов города от обнаружения местной знатью, беспощадно устраняя всех, кто слишком пристально вглядывается в их запретное ремесло.",al={"who is zardeth","zardeth role","black claw leader","кто такой зардет","роль зардета","глава черного когтя"}},{q="Что случилось с лордом Вишлоком?",a="Лорду Вишлоку дали специально приготовленное ядовитое пойло, изготовленное скрытыми чернокнижниками Штормграда. Его устранение гарантирует, что знатный дом больше не будет расследовать и тревожить темных практиков, творящих ритуалы под улицами города.",al={"did wishock die","what was the brew for","lord wishock fate","умер ли вишлок","для чего было пойло","судьба лорда вишлока"}},{q="Кто такой Згги?",a="Згги — бес, связанный службой с Зардетом Черным Когтем. Злобный и жадный, Згги мечтает прибрать сокровища хозяина себе, но страшится наказания, которое последовало бы за любым открытым неповиновением приказам Зардета.",al={"who is the imp zggi","zggi servant","кто такой бес згги","слуга згги"}},{q="Почему чернокнижники избрали целью лорда Вишлока?",a="Вишлок представлял реальную угрозу беспокойства и разоблачения для ковена чернокнижников Штормграда. Положив конец его вмешательству, чернокнижники купили безопасность, позволяющую заниматься демонологией и магией тени, не опасаясь знати.",al={"why kill wishock","wishock threat","зачем убивать вишлока","угроза вишлока"}},{q="Где заканчивается эта цепочка заданий?",a="Задание завершается у беса Згги, находящегося рядом с Зардетом Черным Когтем в святилище чернокнижников под «Забитым ягненком» в Квартале магов Штормграда.",al={"where do i turn in you have served us well","zggi location","где сдать за достойную службу","где згги"}},{q="Почему это задание доступно только чернокнижникам?",a="Операция связана с тонкой внутренней политикой собрания и незаконным убийством. Доверяя такую смертоносную хитрость лишь проверенным ученикам-чернокнижникам, они предотвращают предательство и скрывают это деяние от властей Альянса.",al={"is this warlock only","why warlock quest","только ли для чернокнижников","почему задание чернокнижника"}}},fp="23,238,27.357.0,17.326.1,33.270.0,30.245.1,12.225.0,46.223.0,37.168.0,49.232.0"}
P.entries["quest:398"] = {n="Разыскивается: Червеглаз",s="«Разыскивается: Червеглаз» — официальная награда за смерть, вывешенная на доске объявлений Брилла руководством Отрекшихся этого города. Известный гнолл грабит ближайшие кладбища и фермы, поставляя трупы прямо Плети Короля-лича. Палач Зуганд требует доказательства казни этого существа, чтобы обезопасить земли вокруг Фермы Гаррена.",h="«Разыскивается: Червеглаз» — официальная награда за смерть, вывешенная на доске объявлений Брилла...",kw={"bounty","brill","executor zygand","garren's haunt","gnoll","graverobber","lich king","maggot eye","tirisfal glades","награда","брилл","палач зуганд","ферма гаррена","гнолл","расхититель могил","король-лич","червеглаз","тирисфальские леса"},ang={["faction:Horde"]="Северные границы Тирисфаля нужно усмирить, чтобы Орда могла сохранить надежный плацдарм в Лордероне против остатков Плети.",["race:Undead"]="Каждый труп, украденный Червеглазом, — павший собрат, вновь превращенный в порабощенную марионетку Короля-лича. Расправа над ним — вопрос и обороны своего народа, и личной мести."},sec={{t="Страшное преступление",b="В Тирисфальских лесах мертвые далеко не покоятся с миром. Гнолл по прозвищу Червеглаз заслужил суровый смертный приговор не просто за мародерство, а за активное сотрудничество с Королем-личом. Хотя гноллов обычно считают дикими тварями, движимыми простым голодом, Червеглаз систематически раскапывал трупы и собирал останки, чтобы пополнять ряды армии Плети."},{t="Правосудие в Брилле",b="Для Отрекшихся, чье существование зависит от освобождения из-под власти Короля-лича, возвращать мертвых сородичей в военную машину Плети — одно из тягчайших преступлений. Палач Зуганд, надзирающий за местной военной охраной порядка в Брилле, назначил эту награду, чтобы положить конец грабежу могил возле Фермы Гаррена. Чтобы получить награду, исполнитель должен отсечь лапу Червеглаза как неоспоримое доказательство того, что зверь больше не потревожит Тирисфаль."}},faq={{q="Кто такой Червеглаз?",a="Червеглаз — печально известный гнолл, бродящий по северным районам Тирисфальских лесов. Даже среди сородичей его считают мерзким: он грабит фермы возле Фермы Гаррена и собирает трупы для Плети.",al={"maggot eye lore","who is maggot eye","maggot eye gnoll","червеглаз предания","кто такой червеглаз","гнолл червеглаз"}},{q="Почему Отрекшиеся хотят его смерти?",a="Он приговорен к смерти за то, что напрямую поставлял свежеукраденные трупы армии Плети Короля-лича. Лишить Плеть солдат и ресурсов жизненно важно для выживания Отрекшихся.",al={"why kill maggot eye","maggot eye crimes","why bounty maggot eye","зачем убивать червеглаза","преступления червеглаза","награда за червеглаза"}},{q="Где обычно можно найти Червеглаза?",a="Он скрывается в старой разрушенной хижине на Ферме Гаррена — разоренной усадьбе к северу от Брилла.",al={"maggot eye location","where is maggot eye","find maggot eye","где червеглаз","червеглаз местонахождение","найти червеглаза"}},{q="Кто выплачивает награду?",a="Палач Зуганд в центре Брилла принимает доказательство убийства и выдает награду города от лица военных властей Отрекшихся.",al={"who turns in maggot eye","maggot eye quest turn in","brill bounty rewarder","кому сдать червеглаза","сдать задание червеглаз","награда брилл"}},{q="Зачем Палачу Зуганду его лапа?",a="По старому закону пограничного правосудия уникальный физический трофей, например лапа Червеглаза, служит неоспоримым доказательством смерти до выплаты награды.",al={"why maggot eye paw","paw proof","maggot eyes paw","зачем лапа червеглаза","лапа доказательство","лапа червеглаза"}},{q="Гноллы союзники Плети?",a="Обычно гноллы действуют сами по себе, движимые голодом и жадностью, но Червеглаз именно торгует трупами или поставляет их Плети, что делает его исключительно опасным пособником.",al={"gnolls and scourge","do gnolls work for lich king","scourge gnolls","гноллы и плеть","работают ли гноллы на короля-лича","гноллы плети"}}},fp="18,338,13.390.0,16.470.0,18.197.0,34.185.0,34.117.0,35.144.0,38.156.0,35.185.0"}
P.entries["quest:399"] = {s="Барос Алекстон, городской архитектор, живущий на Соборной площади Штормграда, просит помочь вернуть утерянную семейную реликвию из юности. Старое поместье его семьи в Западном Крае сгорело и попало в руки воров, оставив лишь погребенные воспоминания.",h="Барос Алекстон, городской архитектор, живущий на Соборной площади Штормграда, просит помочь вернуть утерянную...",ang={["faction:Alliance"]="Путешествие в Западный Край по поручению столичных деятелей подчеркивает растущую пропасть между безопасными улицами Штормграда и незащищенными пограничными землями рядом.",["race:Human"]="Судьба Поместья Алекстона отражает медленный упадок йоменов Западного Края, где поколения людей-фермеров лишились земель из-за беззакония у самых ворот Штормграда."},sec={{t="Корни строителя",b="Хотя Барос Алекстон теперь известный архитектор в Штормграде, его ранняя жизнь была куда скромнее. Задолго до того как он стал проектировать каменные работы и городские здания, он рос мальчишкой, трудясь на полях Западного Края. Путь от возделывания земли до советов градостроителям — редкий взлет в королевстве, но он по-прежнему глубоко привязан к скромным истокам, определившим его путь."},{t="Трагедия в Западном Крае",b="Как и многие усадьбы Западного Края, Поместье Алекстона стало жертвой беззакония, охватившего область. Бандиты и бродяги подожгли дом, лишив отца Бароса средств к существованию. В хаосе поджога и захвата семейные реликвии были брошены. Барос просит храбрых путников отправиться в разоренное, кишащее бандитами поместье к западу от Сторожевого холма и вернуть его первый компас — памятную вещь, спрятанную до падения дома."}},faq={{q="Кто такой Барос Алекстон?",a="Барос Алекстон — городской архитектор Штормграда, живущий у Соборной площади. Несмотря на высокое положение в столице, он вырос обычным сыном фермера в Западном Крае, а затем покинул деревню, чтобы освоить искусство строительства.",al={"baros alexston","who is baros","city architect","барос алекстон","кто такой барос","городской архитектор"}},{q="Где находится Поместье Алекстона?",a="Поместье расположено прямо к западу от Сторожевого холма в центральной части Западного Края. Как и многие владения в округе, оно сожжено и захвачено ворами и разбойниками из сброда Братства Справедливости.",al={"alexston farmstead location","where is the farm","alexston farm","поместье алекстона местонахождение","где ферма","ферма алекстона"}},{q="Почему компас важен для Бароса?",a="Компас имеет исключительно сентиментальную ценность. Это был самый первый навигационный инструмент Бароса еще с детства на ферме, символ его пути от сельского труженика до архитектора-проектировщика. Для его нынешнего ремесла он бесполезен, но это незаменимая реликвия прошлого.",al={"why compass","what is the compass","simple compass","зачем компас","что за компас","простой компас"}},{q="Кто сжег ферму Алекстонов?",a="Ферму разорили воры и преступники, терроризирующие Западный Край. Поскольку войска королевства растянуты и не могут защитить отдаленные усадьбы, бандиты захватили землю и изгнали семью Алекстонов.",al={"who burned the farm","why was farm destroyed","westfall farm burned","кто сжег ферму","почему разрушена ферма","сожженная ферма западный край"}},{q="Где на ферме можно найти компас?",a="Компас спрятали до бегства семьи, и его можно найти в небольшом сундуке среди обугленных руин главного дома.",al={"compass location","where is compass","hidden compass","где компас","местонахождение компаса","спрятанный компас"}},{q="Что случилось с отцом Бароса?",a="Отец Бароса пережил налет на усадьбу и бежал с фермы. Хотя он не смог вынести пожитки из огня и от бандитов, он помнил, где семья спрятала ценные памятные вещи перед бегством.",al={"baros father","alexston father","who is baros's dad","отец бароса","отец алекстона","кто отец бароса"}}},fp="17,260,17.404.0,19.467.0,22.252.0,40.197.0,38.276.0,34.211.0,43.141.0,32.214.0"}
P.entries["quest:40"] = {n="Водяная нечисть",s="«Водяная нечисть» — короткое задание-поручение от Реми Повторюха на востоке Элвиннского леса. Встревоженный сообщениями о хищниках-амфибиях, подбирающихся к водным путям, Реми посылает путников предупредить маршала Дугхана в Златоземье. Это поручение показывает ограниченность ресурсов местного гарнизона Штормграда в борьбе с новыми угрозами из глуши.",h="«Водяная нечисть» — короткое задание-поручение от Реми Повторюха на востоке Элвиннского леса.",kw={"a fishy peril","elwynn forest","further concerns","goldshire","marshal dughan","murloc","remy two times","водяная нечисть","элвиннский лес","новые заботы","златоземье","маршал дугхан","мурлок","реми повторюх"},ang={["faction:Alliance"]="Это поручение показывает бюрократическую и логистическую нагрузку на местную стражу Штормграда, вынуждающую городок полагаться на независимых искателей приключений для проверки слухов.",["race:Human"]="Для людей, защищающих родину, вторжение в восточные водные пути бьет по самому дорогому: знакомые ручьи становятся опасными охотничьими угодьями водных тварей."},sec={{t="Мольба с востока",b="Торгуя на восточных дорогах Элвиннского леса, Реми Повторюх встревожен странной новой угрозой. Мурлоки начали подбираться вверх по ручьям и мелководью вглубь суши, мешая рыбной ловле и угрожая мирным путникам. Убежденный, что местная стража не замечает надвигающуюся беду, Реми умоляет прохожих передать весть в сердце городка."},{t="Перегруженный гарнизон",b="Получив донесение в Златоземье, маршал Дугхан остается скептичен. Ему поручено защищать королевство, пока королевские силы заняты в других местах, и он уже поглощен яростным возрождением гноллов Речной Лапы и разбойников Братства Справедливости. Без подтвержденных военных разведданных маршал отказывается отвлекать своих немногочисленных людей на слухи о рыболюдях в восточных ручьях."}},faq={{q="Кто выдает задание «Водяная нечисть»?",a="Задание выдает Реми Повторюх, нервный торговец, путешествующий по дорогам восточного Элвиннского леса.",al={"quest giver a fishy peril","who starts a fishy peril","remy quest","кто выдает водяная нечисть","кто начинает водяная нечисть","задание реми"}},{q="Почему Реми Повторюха беспокоят мурлоки?",a="Реми видел, как мурлоки поднимаются по рекам восточного Элвинна, распугивают местную рыбу и нападают на путников у воды.",al={"why remy scared","murloc problem elwynn","fishy peril lore","почему реми напуган","проблема мурлоков элвинн","водяная нечисть предания"}},{q="Почему маршал Дугхан не посылает войска сразу?",a="Маршал Дугхан считает слухи среди мирных жителей непроверенными. Поскольку гарнизон Златоземья занят нападениями гноллов и организованным разбоем, он не может отправить солдат без официальных донесений военных разведчиков.",al={"why dughan ignores murlocs","marshal dughan response","why no troops east","почему дугхан игнорирует мурлоков","ответ маршала дугхана","почему нет войск на востоке"}},{q="Что происходит после этого задания?",a="Маршал Дугхан продолжает этот разговор заданием «Новые заботы», требуя надежного подтверждения от разведчиков, прежде чем направлять королевские ресурсы на восток.",al={"what comes after a fishy peril","next quest after fishy peril","further concerns quest","что после водяная нечисть","следующее задание после водяная нечисть","новые заботы задание"}},{q="Где сдать задание «Водяная нечисть»?",a="Задание сдается маршалу Дугхану в таверне Гордость Льва в Златоземье или рядом с ней.",al={"where turn in fishy peril","fishy peril turn in","dughan location","где сдать водяная нечисть","сдача водяная нечисть","где дугхан"}},{q="Частью какой большей угрозы в Элвинне являются мурлоки?",a="Хотя мурлоки кажутся примитивными и непредсказуемыми, их агрессивное заселение внутренних озер, таких как озеро Каменной Пирамиды и Озеро Хрустальное, наряду с нападениями гноллов и бандитов угрожает сельской торговле и земледелию.",al={"murlocs in elwynn","are murlocs dangerous elwynn","мурлоки в элвинне","опасны ли мурлоки элвинн"}}},fp="13,347,20.389.0,19.388.0,34.118.0,46.140.0,49.208.0,32.157.0,44.98.0,53.204.0"}
P.entries["quest:400"] = {n="Инструменты для Сталежара",s="«Инструменты для Сталежара» — одно из первых поручений Альянса по доставке, знакомящее покидающих Каранос путников с ближайшей механической мастерской в Поселке Сталежара. Тарек Чернокамень отправляет вас по дороге со свежим ящиком тяжелого оборудования для Белдина Сталежара, мастера осадных машин, который изнашивает гаечные ключи и трещотки быстрее, чем поставщики города успевают их подвозить.",h="«Инструменты для Сталежара» — одно из первых поручений Альянса по доставке, знакомящее покидающих Каранос...",kw={"arclight spanner","beldin steelgrill","dun morogh","fang-ratchet","kharanos","pilot stonegear","siege engine","steelgrill's depot","tharek blackstone","тангенциальный вращатель","белдин сталежар","дун морог","клыкастая трещотка","каранос","пилот камнекожиц","осадная машина","поселок сталежара","тарек чернокамень"},ang={["profession:Engineering"]="Ремесло Белдина держится на точных инженерных инструментах вроде тангенциальных вращателей и клыкастых трещоток, что показывает, какую нагрузку механизированная война создает для изготовленных инструментов.",["race:Dwarf"]="Бронетанковая война дворфов целиком зависит от полевых ремонтных станций вроде Поселка Сталежара, благодаря которым могучие осадные машины Стальгорна продолжают катиться по заснеженным перевалам.",["race:Gnome"]="Тангенциальные вращатели и сложные трещотки, которые изнашивает Белдин, — отличительные черты точной инженерии гномьей школы, приспособленной к грубой дворфийской броне."},sec={{t="Мастер, не щадящий инструмент",b="Белдин Сталежар слывет в Дун Мороге лучшим механиком осадных машин в горах, но его яростная манера работы сильно изнашивает мастерскую. По словам Тарека Чернокамня из Караноса, Сталежар ломает тангенциальные вращатели и инструменты почти так же быстро, как приходят местные ящики с поставками. Когда в Караносе собирают новую партию прочного снаряжения, любого, кто идет на северо-восток, быстро просят отнести тяжелый груз в поселок."},{t="Чтобы двигатели работали",b="Прибыв в Поселок Сталежара, путники видят двор, полный дыма, смазки и работающих на холостом ходу железных боевых машин. У Белдина скопилось множество срочных военных ремонтов, включая важную работу над осадной машиной Пилота Камнекожица. Белдин сломал последнюю клыкастую трещотку за считаные часы до вашего прибытия, и доставленный ящик стал настоящим спасением для гусеничного бронепарка Стальгорна."}},faq={{q="Куда отнести инструменты?",a="Идите на северо-восток из Караноса по дороге к Стальгорну. Белдин Сталежар работает под открытым небом в Поселке Сталежара, среди стоящих осадных машин и танков.",al={"where is steelgrill","where to deliver tools","beldin steelgrill location","где сталежар","куда доставить инструменты","белдин сталежар где"}},{q="Кто такой Белдин Сталежар?",a="Белдин Сталежар — известный дворф-механик и специалист по осадным машинам, управляющий Поселком Сталежара в Дун Мороге. Он руководит ремонтом, доработкой и обслуживанием техники для опытных пилотов механизированных бронетанковых сил Стальгорна.",al={"who is beldin","beldin lore","siege engine tech","кто такой белдин","белдин предания","механик осадных машин"}},{q="Почему Белдин ломает так много инструментов?",a="Осадные машины — огромные, тяжело бронированные боевые машины, скрепленные массивными железными деталями. Работа с такими усиленными корпусами требует огромного рычага и грубой силы, из-за чего при срочном ремонте регулярно ломаются хрупкие тангенциальные вращатели и клыкастые трещотки.",al={"why broken tools","arclight spanners breaking","steelgrill tools","почему сломаны инструменты","тангенциальные вращатели ломаются","инструменты сталежара"}},{q="Чью осадную машину чинит Белдин?",a="Когда вы доставляете инструменты, Белдин как раз заканчивает важный ремонт осадной машины Пилота Камнекожица, опытного дворфа-пилота, расквартированного в поселке.",al={"pilot stonegear tank","what engine is broken","stonegear siege engine","танк пилота камнекожица","какая машина сломана","осадная машина камнекожица"}},{q="Что такое Поселок Сталежара?",a="Поселок Сталежара — механическая площадка и мастерская под открытым небом к северо-востоку от Караноса. Это место сбора опытных пилотов осадных машин и танковых экипажей, которые испытывают, настраивают и чинят свои бронированные гусеницы.",al={"what is the depot","depot purpose","steelgrill workshop","что такое поселок","назначение поселка","мастерская сталежара"}},{q="Почему Тарек Чернокамень просит искателя приключений отнести их?",a="Тарек только что собрал последний заказ Сталежара на инструменты и искал надежного путника, идущего на северо-восток, чтобы отнести тяжелый ящик. Он предлагал скромную плату и знакомство с опытными пилотами, собравшимися дальше по дороге.",al={"why ask me","tharek delivery reason","почему меня","причина доставки тарека"}}},fp="20,365,26.482.0,27.390.0,26.185.0,25.237.0,36.265.0,36.176.0,27.222.0,59.214.0"}
P.entries["quest:401"] = {n="Ожидание перевода",kw={"abercrombie","darkshire","duskwood","ello ebonlocke","sirra von'indi","translation","аберкромби","темнолесье","сумеречный лес","элло чернодрев","шира фон-инди","перевод"},ang={["class:Mage"]="Маги, изучающие тайные письмена и руны, узнают темный, затяжной отзвук проклятого послания, когда его содержание раскрывается.",["faction:Alliance"]="Хрупкая безопасность Темнолесья висит на волоске."},sec={{t="Минута перевода",b="After receiving the mysterious note penned by the hermit Abercrombie, Sirra Von'Indi requires only a short spell to decipher its text. As a resident scholar aiding the Night Watch and town leadership, she undertakes the task without realizing immediately what horrors the message conceals."},{t="Зловещий холод",b="Как только Шира заканчивает переписывать текст, атмосфера ощутимо меняется. Комнату накрывает внезапная тяжесть, будто на округу опустился плотный черный занавес. Расшифрованная записка предвещает Темнолесью великую опасность: на деле безобидные поручения Аберкромби были частью зловещего замысла мести."}},faq={{q="Who is Sirra Von'Indi?",a="Sirra Von'Indi is an educated scholar residing in Darkshire's Town Hall. She assists Mayor Ello Ebonlocke and the local authorities by translating ancient scripts, strange documents, and ciphered messages brought in from the gloomy wilds of Duskwood.",al={"sirra von'indi","who is sirra","sirra duskwood","шира фон-инди","кто такой шира","шира сумеречный лес"}},{q="Какую записку переводит Шира?",a="Записку написал Аберкромби, отшельник, живущий уединенно в хижине у западной границы Сумеречного леса. Вы выполнили для него ряд поручений, прежде чем эта записка попала к Шире на перевод.",al={"what is the note","abercrombie note","what did abercrombie write","что за записка","записка аберкромби","что написал аберкромби"}},{q="Почему воздух становится тяжелым, когда она заканчивает?",a="Внезапный гнетущий холод — предвестие неминуемой беды: что бы ни говорилось в записке, для Темнолесья это мрачные вести, и ее полный смысл станет ясен, когда перевод попадет к лорду Элло Чернодреву.",al={"why does air grow heavy","black curtain over land","duskwood dark air","почему воздух тяжелеет","черный занавес над землей","сумеречный лес темный воздух"}},{q="Кому дальше отнести переведенное письмо?",a="Закончив перевод, Шира просит вас отнести леденящие душу слова прямо через комнату мэру Элло Чернодреву, чтобы Ночной Дозор мог подготовиться к грядущему.",al={"where do i take the translation","who gets the note next","next step after sirra","куда отнести перевод","кому отдать записку","что делать после ширы"}},{q="Действительно ли Аберкромби враг Темнолесья?",a="Аберкромби выдает себя за безобидного отшельника-старика, которому нужна помощь, чтобы выжить. Тяжелый ужас, нависающий, когда Шира заканчивает перевод, говорит о том, что в его записке мрачные вести для Темнолесья, и полный смысл станет ясен, когда она попадет к лорду Элло Чернодреву.",al={"is abercrombie evil","hermit enemy","abercrombie lore","аберкромби злодей","отшельник враг","аберкромби предыстория"}},{q="Почему нужно ее ждать?",a="Translating ancient ciphers takes time and focus. The brief delay gives Sirra a moment to parse the hermit's handwriting and coded phrasing before producing the readable transcript for the mayor.",al={"why wait for sirra","how long do i wait","sirra waiting","зачем ждать ширу","сколько ждать","шира ожидание"}}},fp="24,279,23.289.0,16.331.1,22.250.0,31.215.1,46.197.2,46.183.0,46.274.2,32.195.0"}
P.entries["quest:4021"] = {n="Контратака!",s="После планомерного уничтожения их вождей в Степях кентавры Колкар отчаянно наносят ответный удар из Пустошей. Вторгшееся войско идет прямо на заставу Регтара Врата Смерти к западу от Перекрестка, и дело заканчивается ожесточенной схваткой с полководцем Кром'заром.",h="После планомерного уничтожения их вождей в Степях кентавры Колкар отчаянно наносят ответный удар из Пустошей.",kw={"barrens","bunkers","centaur","counterattack","crossroads","desolace","kolkar","kromzar","regthar deathgate","warlord krom'zar","степи","бункеры","кентавр","контратака","перекресток","пустоши","колкар","кромзар","регтар врата смерти","полководец кром'зар"},ang={["class:Warrior"]="Стоять рядом с грантами заставы против неослабевающих атак кентавров-захватчиков — классическое испытание выносливости на передовой и боевой дисциплины.",["faction:Horde"]="Оборона бункеров закрепляет власть Орды над центральными Степями и защищает важные линии снабжения между Дуротаром, Мулгором и Перекрестком.",["race:Tauren"]="Разгром вторжения Кром'зара приносит равнинам столь необходимую безопасность, отбрасывая древнюю и злобную кентаврскую угрозу, веками преследовавшую народ тауренов."},sec={{t="Месть из Пустошей",b="Кампания против кентавров Колкар в Степях ударила в самое сердце их племенного руководства. После гибели Барака Кодобана, Верога Дервиша и Хэрзул Кровавая Отметина оставшиеся кентавры оказались разбиты и лишены руководства. В ответ на это унижение весть разнеслась на запад через горы, в их родовые земли в Пустошах. Вместо того чтобы разбежаться по равнинам, новый отряд закаленных воинов Колкар сплотился и вошел в Степи, горя жаждой крови и возмездия молодым лагерям Орды."},{t="Оборона бункеров",b="Карательное войско нападает на укрепленные бункеры Орды к западу от Перекрестка, которыми командует Регтар Врата Смерти. Волны захватчиков Колкар штурмуют линию обороны и яростно сражаются с расквартированными грантами Орды. Во главе этого отряда стоит полководец Кром'зар, грозный предводитель, чье знамя служит захватчикам боевым кличем. Удержав линию под натиском, убив Кром'зара и сорвав его боевое знамя, защитники навсегда ломают хребет кентаврской угрозе на центральных равнинах."}},faq={{q="Почему Колкар нападают именно на эту заставу?",a="Регтар Врата Смерти организовал планомерные убийства вождей Колкар у плодородных оазисов Степей. Желая отомстить за павших вождей, кентавры двинулись прямо на его укрепленные бункеры к западу от Перекрестка, чтобы сокрушить командный пункт Орды, ответственный за это.",al={"why attack regthar","why barrens bunker attacked","centaur counterattack reason","почему атакуют регтара","почему напали на бункер в степях","причина контратаки кентавров"}},{q="Откуда взялось это подкрепление кентавров?",a="Вторгшееся войско пришло через западные горные перевалы из Пустошей — сурового бесплодного края, где живет большинство кланов кентавров.",al={"where do kolkar come from","kolkar reinforcements source","desolace centaur","откуда пришли колкар","источник подкрепления колкар","кентавры пустошей"}},{q="Кто такой полководец Кром'зар?",a="Полководец Кром'зар — предводитель карательного войска Колкар, посланного из Пустошей. Он лично ведет натиск на бункеры Регтара и сражается под особым боевым знаменем, пока его не убивают защитники Орды.",al={"who is kromzar","krom'zar lore","warlord kromzar","кромзар","кром'зар предыстория","полководец кромзар"}},{q="Узнает ли Тралл об этой битве?",a="Да. Когда ему предъявляют разорванные остатки знамени Кром'зара, Регтар Врата Смерти обещает отправить официальное донесение напрямую вождю Траллу в Оргриммар, в знак признания защиты Степей.",al={"thrall counterattack","does thrall hear about this","warchief reward","тралл контратака","узнает ли тралл","награда вождя"}},{q="Что станет с присутствием Колкар после этой битвы?",a="Поражение полководца Кром'зара ломает последнюю организованную наступательную силу Колкар в центральных Степях, обеспечивая безопасность торговых путей вокруг Перекрестка и оставляя уцелевшие племена разобщенными и без вождей.",al={"are kolkar defeated","barrens centaur fate","end of kolkar questline","побеждены ли колкар","судьба кентавров степей","конец цепочки заданий колкар"}},{q="Для чего нужен обрывок знамени Кром'зара?",a="Обрывок боевого стяга Кром'зара — неопровержимое вещественное доказательство гибели полководца, символ полного краха вторжения кентавров.",al={"kromzar banner","banner piece quest item","why take banner","знамя кромзара","обрывок знамени предмет задания","зачем брать знамя"}}},fp="14,297,23.552.0,22.519.1,51.294.0,49.158.0,24.214.0,36.186.1,54.218.1,48.164.0"}
P.entries["quest:403"] = {n="Охраняемый бочонок громопойла",s="Охраняемый бочонок громопойла стоит в погребе Таверны «Громоварка» в Караносе. Это ценный запас знаменитого дворфийского рода пивоваров, который день и ночь охраняют, чтобы воры и соперники не вмешались в их ремесло.",h="Охраняемый бочонок громопойла стоит в погребе Таверны «Громоварка» в Караносе.",kw={"dun morogh","dwarven brew","guarded thunderbrew barrel","jarven thunderbrew","kharanos","thunder ale","thunderbrew distillery","дун морог","дворфийское пиво","охраняемый бочонок громопойла","ярвен громовар","каранос","громовой эль","таверна громоварка"},ang={["class:Rogue"]="Пробраться в погреб и стащить бочонок крепкого дворфийского эля — классическая работа, но бдительный дворф у бочки делает тихую кражу куда сложнее.",["race:Dwarf"]="Любой дворф понимает, что тайное пиво семьи стоит защищать жизнью и здоровьем, и упрямое бдение Ярвена в погребе вполне естественно."},sec={{t="Погреб под охраной",b="В холодных снегах Дун Морога мало что охраняют так ревностно, как хороший эль. Под половицами таверны «Громоварка» в Караносе спокойно выдерживаются крепкие бочки мощного напитка. Семья не рискует и ставит бдительных стражей, таких как Ярвен Громовар, прямо у бочек, чтобы ни одна капля не была испорчена или украдена."},{t="Семейная гордость и соперничество",b="Дворфийское пивоварение — такая же серьезная наука, как кузнечное дело или добыча руды. Громовары чрезвычайно гордятся своими особыми рецептами, особенно крепкими партиями громового эля. Между жадными троггами, крадущимися по Дун Морогу, и злобным пивоваренным соперничеством по всему Альянсу бдительное присутствие Ярвена гарантирует, что жидкое золото семьи останется нетронутым, пока его не откроют как положено."}},faq={{q="Почему я не могу открыть этот бочонок?",a="Ярвен Громовар стоит прямо там, в подвале, и несет стражу. Пока он на посту, никому не позволено трогать бочки семьи Громоваров.",al={"cannot open barrel","why cant i touch the ale","jarven guarding barrel","не открыть бочонок","почему нельзя трогать эль","ярвен охраняет бочонок"}},{q="Кто такой Ярвен Громовар?",a="Ярвен — член клана Громоваров, поставленный в погребе таверны в Караносе. Его главная обязанность — присматривать за лучшим элем семьи и не давать ворам и смутьянам портить запасы.",al={"who is jarven","jarven lore","dwarf in cellar","кто такой ярвен","ярвен предыстория","дворф в погребе"}},{q="Где находится этот бочонок?",a="Бочонок стоит в погребе под таверной «Громоварка» в городке Каранос в Дун Мороге.",al={"where is the guarded barrel","cellar location","thunderbrew basement","где охраняемый бочонок","расположение погреба","подвал громоваров"}},{q="Почему Громовары так строго охраняют свой эль?",a="Для дворфов пивоварение — почитаемое ремесло и семейное наследие. Из-за конкурентов, хитрых воров и близких угроз вроде троггов и лепрогномов редкие выдержанные бочки громового эля требуют постоянной защиты.",al={"why guard ale","importance of thunderbrew ale","зачем охранять эль","важность громового эля"}},{q="Это часть другого задания?",a="Да. Оно связано с заданием Марлетта Ячменовар «Злейшие соперники», в котором нужно тайком подкинуть бочонок ячменоварского «Ошпаривателя» к бочкам громового эля Громоваров.",al={"thunderbrew questline","what quest is this for","цепочка заданий громоваров","для какого задания это"}},{q="Можно ли отвлечь или сдвинуть Ярвена?",a="Да. У Ярвена строгий приказ не трогать запасы, но он признается, что не отказался бы попробовать громового эля. Если принести ему эль в задании «Отвлечь Ярвена», он отвлечется от бочек.",al={"how to get past jarven","distract jarven","как пройти мимо ярвена","отвлечь ярвена"}}},fp="26,247,20.375.0,26.375.0,29.170.0,26.228.0,29.117.0,51.213.0,30.165.0,32.197.0"}
P.entries["quest:404"] = {n="Грязная работа",s="«Грязная работа» — раннее военное поручение Стража смерти Диллинжера в Брилле. Оно направляет искателей приключений отбросить бездумно агрессивную Плеть, подступающую к старому мосту к западу от поселения. Доказательства уничтожения чудовищ обеспечивают безопасность дороги и облегчают положение защитников Тирисфаля.",h="«Грязная работа» — раннее военное поручение Стража смерти Диллинжера в Брилле.",kw={"a putrid task","brill","deathguard dillinger","putrid claw","ravaged corpse","rotting dead","scourge","tirisfal glades","грязная работа","брилл","страж смерти диллинжер","гнилой коготь","изувеченный труп","гниющий мертвец","плеть","тирисфальские леса"},ang={["faction:Horde"]="Защита Брилла гарантирует, что молодое присутствие Орды в Восточных королевствах сохранит надежный оплот против Плети.",["race:Undead"]="Для Отрекшихся уничтожение Плети глубоко личное дело: это месть неумолимой силе, которая когда-то держала их разум в плену."},sec={{t="Удержание моста",b="Брилл стоит на важном перекрестке в восточных Тирисфальских лесах, и любой подход врага прямо угрожает оплоту Отрекшихся. Бездумная Плеть постоянно просачивается на запад через водные пути и скапливается вокруг разрушенных остатков старого каменного моста. Без регулярных патрулей, отбрасывающих их, бредущие трупы быстро перекрыли бы путь между Бриллом и западными фермами."},{t="Счеты с бездумными",b="Для Отрекшихся Плеть, бродящая у их границ, — не просто стратегическая помеха, а оскорбление. Каждый бездумный вурдалак и гниющий труп напоминает о рабстве и муках, от которых отреклись последователи леди Сильваны Ветрокрылой. Стражи смерти вроде Диллинжера с мрачным удовлетворением давят прежних поработителей и требуют отрубленные когти как жестокое доказательство того, что бездумные мертвецы упокоены навсегда."}},faq={{q="Кто дает это задание?",a="Это поручение дает Страж смерти Диллинжер, офицер стражи Отрекшихся, стоящий у западного выхода из Брилла в Тирисфальских лесах.",al={"quest giver","where to get putrid task","deathguard dillinger quest","персонаж, выдающий задания","где взять грязную работу","задание стража смерти диллинжера"}},{q="Зачем Стражу смерти Диллинжеру гнилые когти?",a="Когти служат жутким доказательством смерти. Стражам смерти нужно подтверждение, что бродячая Плеть полностью уничтожена, а не просто немного оттеснена от главной дороги.",al={"why putrid claws","claws reason","зачем гнилые когти","причина когтей"}},{q="Где найти гниющих мертвецов?",a="Они бродят по заросшим полям и берегам рек сразу к западу от Брилла, густо скапливаясь вокруг старого каменного моста.",al={"rotting dead location","where are the ghouls","old bridge location","где гниющие мертвецы","где вурдалаки","где старый мост"}},{q="Почему в Тирисфальских лесах есть Плеть?",a="Хотя Отрекшиеся отвоевали у Плети столицу Лордерона и окрестные леса, Плеть просочилась в Тирисфальские леса и заполонила местность к западу от Брилла, возле старого моста.",al={"why scourge here","scourge in tirisfal","почему здесь плеть","плеть в тирисфале"}},{q="Что происходит после выполнения этого задания?",a="Расчистка моста обнаруживает более серьезные проблемы на ближайших фермах, и Страж смерти Диллинжер отправляет вас дальше на запад осмотреть захваченные мельницы.",al={"next quest","what follows putrid task","следующее задание","что после грязной работы"}},{q="Разве Отрекшиеся и Плеть — не одно и то же?",a="Нет. Отрекшиеся — свободная нежить, сбросившая телепатический контроль Короля-лича и борющаяся за свою независимость. Плеть остается бездумными рабами, подчиненными Железной воле Ледяного Трона.",al={"difference between forsaken and scourge","aren't they all undead","разница между отрекшимися и плетью","разве все не нежить"}}},fp="13,320,18.395.0,29.415.0,21.135.0,48.186.0,33.121.0,41.206.0,40.159.1,52.202.0"}
P.entries["quest:405"] = {n="Блудный лич",s="После вашей службы в Брилле против остатков Плети и гноллов-гнилошкуров мировой судья Севрен направляет вас на юг, в Подгород. Бетору Ледострелу, известному архимагу из Магического квартала, нужен способный исполнитель для деликатного задания, связанного со сбежавшим личем.",h="После вашей службы в Брилле против остатков Плети и гноллов-гнилошкуров мировой судья Севрен направляет вас...",kw={"bethor iceshard","brill","magic quarter","magistrate sevren","prodigal lich","sevren's orders","tirisfal glades","undercity","бетор ледострел","брилл","магический квартал","мировой судья севрен","блудный лич","распоряжения севрена","тирисфальские леса","подгород"},ang={["class:Mage"]="Доклад Бетору Ледострелу дает возможность встретиться с одним из сильнейших мастеров тайной магии и магии льда среди Отрекшихся.",["faction:Horde"]="Привлечение независимых или могущественных некромантических сил укрепляет шаткую власть Отрекшихся над руинами Лордерона против общих врагов.",["race:Undead"]="Первые прямые приказы из столицы означают ваш переход от местной службы в ополчении Брилла к исполнению более масштабной политической воли Подгорода."},sec={{t="Вызов в столицу",b="Доказав свои способности в разрушенном городке Брилл, мировой судья Севрен счел вас достойным более серьезных дел Отрекшихся. Бетор Ледострел, грозный маг, живущий в Магическом квартале Подгорода, потребовал агента, испытанного в боях с Плетью. Севрен вручает вам официальные распоряжения и отправляет под руины Лордерона, в подземные коридоры столицы Отрекшихся."},{t="Блудный лич",b="Севрен признается, что не знает всех подробностей, но говорит, что задание состоит в поиске и вербовке отбившегося от рук лича. Личи — одни из самых смертоносных заклинателей, созданных Плетью, поэтому любая встреча с ними опасна. Когда вы передаете распоряжения Бетору на вершине его магического убежища, холодный маг сразу переходит к делу: он хочет понять, достаточно ли силен тот, кого прислал судья Брилла, для такой опасной добычи."}},faq={{q="Кто посылает меня с этим заданием?",a="Мировой судья Севрен, чиновник Отрекшихся, управляющий городком Брилл в Тирисфальских лесах, посылает вас с письменными распоряжениями прямо к Бетору Ледострелу.",al={"who gives the prodigal lich","quest giver prodigal lich","sevren orders","кто выдает задание блудный лич","персонаж, выдающий задание блудный лич","распоряжения севрена"}},{q="Где найти Бетора Ледострела?",a="Бетор Ледострел живет в Магическом квартале Подгорода. Обычно его можно найти на вершине центрального возвышения, окруженного тайными энергиями.",al={"where is bethor","bethor iceshard location","how to find bethor","где бетор","бетор ледострел местонахождение","как найти бетора"}},{q="О каком поручении говорится в распоряжениях?",a="Бетор намерен привлечь на службу скитающегося лича-отступника, но сначала ему нужен агент, способный выследить улики о личности и местонахождении лича.",al={"what is the lich mission","who is the wayward lich","prodigal lich purpose","в чем задание про лича","кто такой блудный лич","цель блудного лича"}},{q="Почему Бетору нужен агент, испытанный в боях с Плетью?",a="Личи — мастера некромантии льда и смерти, изначально подчиненные Королю-личу. Чтобы справиться со свободным или одиноким личом, нужен тот, кто уже доказал, что способен выжить среди угроз нежити Плети.",al={"why scourge testing","why does bethor need me","почему испытание плетью","зачем я нужен бетору"}},{q="Какое задание нужно выполнить, прежде чем получить это?",a="Вы должны выполнить предыдущее поручение мирового судьи Севрена — «Грабители могил»: перебить гноллов-гнилошкуров и похитителей могил на Ферме Гаррена.",al={"prodigal lich prequest","how to unlock prodigal lich","предыдущее задание блудного лича","как открыть блудного лича"}},{q="Что будет после доклада Бетору?",a="Когда вы передадите распоряжения Севрена, Бетор предложит задание «Личность лича»: исследовать предметы и улики, чтобы выяснить, кем было это загадочное существо при жизни.",al={"what is next after prodigal lich","prodigal lich follow up","что дальше после блудного лича","продолжение блудного лича"}}},fp="17,270,22.406.0,14.453.0,26.151.0,32.145.0,44.161.0,60.223.0,64.144.0,37.179.0"}
P.entries["quest:407"] = {n="Поля Горя",s="Задание «Поля Горя» завершает эксперимент аптекаря Юхана по превращению обычных тыкв, собранных на Ферме Соллидена, в оружие. Пропитав урожай своим новейшим алхимическим составом, Юхан посылает вас накормить отравленным овощем плененного рыцаря Алого ордена, томящегося в Брилле.",h="Задание «Поля Горя» завершает эксперимент аптекаря Юхана по превращению обычных тыкв, собранных на Ферме...",kw={"apothecary johaan","brill","captured scarlet zealot","fields of grief","gallows end tavern","laced pumpkin","royal apothecary society","tirisfal glades","аптекарь юхан","брилл","пленный ревнитель из алого ордена","поля горя","таверна петля висельника","отравленная тыква","королевское фармацевтическое общество","тирисфальские леса"},ang={["faction:Horde"]="Биохимические исследования Королевского фармацевтического общества нередко тревожат новых союзников Отрекшихся, но остаются ключевыми для защиты Тирисфальских лесов для Орды.",["race:Undead"]="Для Отрекшихся этот опыт показывает безжалостный прагматизм, необходимый, чтобы выжить среди смертных фанатиков на юге и армий Короля-лича на севере."},sec={{t="Оружие изобретательности",b="Аптекарь Юхан из Королевского фармацевтического общества считает, что Отрекшиеся должны использовать любое тактическое преимущество, чтобы отбиться от Плети с севера и вторжений людей с юга. Вместо того чтобы полагаться только на клинки или темное колдовство, Общество стремится использовать обычные продукты этой земли. Отравив тыквы, добытые у смертных фермеров Фермы Соллидена, Юхан хочет доказать, что даже обычные овощи можно превратить в орудие смерти во имя Темной Госпожи."},{t="Испытание в подвале",b="Подопытный ждет под половицами таверны «Петля висельника» в Брилле. Скованный и голодный пленный ревнитель из Алого ордена встречает гостей из Отрекшихся привычным фанатичным неповиновением, взывая к Свету, чтобы изгнать нежить. Но голод быстро ломает его волю. Приняв отравленную тыкву за настоящее облегчение, пленник жадно съедает ее и тут же превращается в гниющего вурдалака, после чего безжизненно падает в грязь."}},faq={{q="Почему аптекарь Юхан использует для яда тыкву?",a="Юхан хочет показать, что обычные культуры можно превратить в неприметное и эффективное оружие против живых. Пропитывая алхимическими смесями обычные продукты с соседних человеческих ферм, Королевское фармацевтическое общество проверяет способы доставки, основанные на базовых потребностях смертных врагов в пище.",al={"why a pumpkin","why poison pumpkin","laced pumpkin lore","почему тыква","почему отравленная тыква","предыстория отравленной тыквы"}},{q="Кто пленник в подвале таверны?",a="Пленник — пленный ревнитель из Алого ордена, фанатик, захваченный силами Отрекшихся в Тирисфальских лесах. Ослабев от голода и одиночества, ревнитель держится за религиозный пыл, пока ему не предлагают еду.",al={"who is captured zealot","zealot in gallows end","brill cellar prisoner","кто пленный ревнитель","ревнитель в петле висельника","пленник в подвале брилла"}},{q="Что станет с ревнителем из Алого ордена после того, как он съест тыкву?",a="Съев отравленную тыкву, ревнитель быстро превращается в голодного вурдалака, бесцельно бродит по полу подвала и вскоре падает замертво, доказывая смертельную силу состава Юхана.",al={"what happens to zealot","zealot transformation","does zealot turn into ghoul","что станет с ревнителем","превращение ревнителя","превратится ли ревнитель в вурдалака"}},{q="Где находится подвал таверны «Петля висельника»?",a="Подвал находится прямо под таверной «Петля висельника» в Брилле. Пандус за стойкой ведет вниз, в помещение, где стражи Отрекшихся держат пленников.",al={"how to find cellar","where is zealot located","gallows end cellar entrance","как найти подвал","где находится ревнитель","вход в подвал петли висельника"}},{q="Чего добивается здесь Королевское фармацевтическое общество?",a="Общество работает под началом леди Сильваны Ветрокрылой, создавая биологические и алхимические средства, способные уничтожить и Плеть, и смертных врагов вроде Алого ордена. Мелкие опыты на пленных в Брилле служат пробными испытаниями этих составов.",al={"apothecary society goal","why test plague","royal apothecary society tirisfal","цель фармацевтического общества","зачем испытывать чуму","королевское фармацевтическое общество тирисфаль"}},{q="Почему Алый орден действует в Тирисфальских лесах?",a="Алый орден считает всю нежить мерзостью, подлежащей истреблению, и не делает различий между безмозглой Плетью и свободными Отрекшимися. Его лагеря и гарнизоны разбросаны по бывшему королевству Лордерон: орден хочет вернуть эти земли священным огнем.",al={"scarlet crusade tirisfal","why are scarlets here","crusade presence brill","алый орден тирисфаль","почему здесь алые","присутствие ордена в брилле"}}},fp="15,285,21.512.0,15.454.1,56.294.0,41.226.0,60.216.1,40.175.0,60.263.0,53.268.0"}
P.entries["quest:408"] = {n="Семейный склеп",s="«Семейный склеп» — задание Орды, в котором игрокам нужно сразиться с Плетью в Семейной усыпальнице Агамондов. По приказу мирового судьи Севрена в Брилле герои должны уничтожить восставших предков Агамондов и убить командира-скелета Плети, капитана Даргола.",h="«Семейный склеп» — задание Орды, в котором игрокам нужно сразиться с Плетью в Семейной усыпальнице Агамондов.",kw={"agamand family crypt","agamand mills","brill","captain dargol","magistrate sevren","rotting ancestor","scourge","the family crypt","tirisfal glades","wailing ancestor","семейная усыпальница агамондов","мельницы агамондов","брилл","капитан даргол","мировой судья севрен","гниющий предок","плеть","семейный склеп","тирисфальские леса","стенающий предок"},ang={["faction:Horde"]="Защита Тирисфальских лесов жизненно важна для закрепления Орды в Восточных королевствах: она устраняет непосредственные угрозы ее северному оплоту.",["race:Undead"]="Для Отрекшихся капитан Даргол воплощает все, от чего они бежали: рабство под властью Короля-лича. Упокоение поднятых предков — и самозащита, и мрачный долг, необходимый, чтобы разорвать хватку Плети на их родине."},sec={{t="Тревога в Тирисфале",b="Хотя Отрекшиеся отвоевали в Тирисфальских лесах хрупкие владения, остатки Плети Короля-лича по-прежнему прочно засели в сельской местности. Мельницы Агамондов, когда-то процветавший центр производства муки в Лордероне, стали опасным оплотом Плети. Мировой судья Севрен в Брилле с тревогой следит за этим наращиванием сил, зная, что каждая пядь земли, уступленная безмозглой нежити, подрывает независимость Отрекшихся."},{t="Осквернение гробницы",b="Центр местной оккупации Плети — Семейная усыпальница Агамондов, где обосновался командир-скелет капитан Даргол. Темной некромантией Даргол поднял из покоя поколения мертвых Агамондов, превратив их в гниющих и стенающих предков, чтобы пополнить свои ряды. Севрен посылает агентов Отрекшихся очистить усыпальницу, упокоить потревоженных мертвых и отсечь голову Дарголу, чтобы нарушить согласованность действий Плети на севере Тирисфальских лесов."}},faq={{q="Кто такой капитан Даргол?",a="Капитан Даргол — офицер Плети из скелетов, расквартированный в Семейной усыпальнице Агамондов. Из этой гробницы он командует местными силами Плети и с помощью некромантии поднимает предков Агамондов, чтобы вести их против Отрекшихся.",al={"captain dargol","who is dargol","dargol lore","капитан даргол","кто такой даргол","предыстория даргола"}},{q="Почему мирового судью Севрена волнуют Мельницы Агамондов?",a="Мельницы Агамондов — крупный плацдарм Плети, опасно близкий к Бриллу и Подгороду. Если его не остановить, растущая армия поднятых предков капитана Даргола может начать наступление на недавно освобожденные поселения Отрекшихся.",al={"why brill cares","sevren agamand","agamand importance","почему брилл беспокоится","севрен агамонд","важность агамондов"}},{q="Кто такие стенающие и гниющие предки?",a="Это умершие предки богатого рода Агамондов. Вместо мирного покоя в родовых усыпальницах их тела и души были осквернены и подчинены воле Плети темными искусствами капитана Даргола.",al={"wailing ancestors","rotting ancestors","agamand ancestors","стенающие предки","гниющие предки","предки агамондов"}},{q="Что происходит после гибели Даргола?",a="Если вернуть череп капитана Даргола мировому судье Севрену, это разрушит централизованное руководство Плети на мельницах. Севрен называет победу решающим ударом для Отрекшихся и ранним шагом к полному изгнанию влияния Короля-лича из Лордерона.",al={"crypt aftermath","end of agamand chain","dargol defeated","последствия в склепе","конец цепочки агамондов","даргол повержен"}}},fp="16,263,21.443.0,17.474.0,22.229.0,56.241.0,42.242.0,36.258.1"}
P.entries["quest:409"] = {n="Доказательство преданности",s="«Доказательство преданности» — решающее испытание Гюнтера Чародея: он хочет узнать, служите ли вы свободным Отрекшимся или Королю-личу. Чтобы заслужить доверие отшельника-некроманта, вас посылают призвать и уничтожить Лилит Нефару, опасного агента Плети, скрывающегося возле его острова.",h="«Доказательство преданности» — решающее испытание Гюнтера Чародея: он хочет узнать, служите ли вы свободным...",kw={"bethor iceshard","brightwater lake","candle of beckoning","gunther arcanus","lillith nefara","proving allegiance","scourge altar","tirisfal glades","бетор ледострел","озеро ясноводное","манящая свеча","гюнтер чародей","лиллит нефара","доказательство преданности","алтарь плети","тирисфальские леса"},ang={["class:Mage"]="Бетор Ледострел и Гюнтер Чародей — значительные таланты тайной магии и некромантии в Лордероне; демонстрация ваших способностей завоевывает профессиональное уважение могущественного собрата по магии.",["race:Undead"]="Для Отрекшихся освободить Гюнтера из изоляции — личное дело: это доказывает собрату по нежити, что никому из них не придется одному встречать гнев Плети или живых."},sec={{t="Подозрения затворника",b="Гюнтер Чародей уединился на острове посреди Озера Ясноводного с тех пор, как восстал нежитью, яростно оберегая свою независимость. Хотя чары Бетора Ледострела на книге заклинаний Гюнтера подтвердили, что посланник не несет мерзкой скверны Плети, слов и чар недостаточно для мнительного отшельника. Чтобы заслужить его доверие, чужак должен решительным насилием показать враждебность к приспешникам Короля-лича."},{t="Убийство Лилит Нефары",b="К югу от убежища Гюнтера стоит залитый кровью ритуальный алтарь Лилит Нефары, грозного агента Плети в Тирисфальских лесах. С помощью особой Манящей свечи проситель пробуждает Лилит из теней, чтобы сразиться с ней в открытом бою. Победа над агентом разрушает давнюю уверенность Гюнтера в том, что лишь он один из нежити смог вырваться из железной хватки Короля-лича."}},faq={{q="Почему Гюнтеру Чародею нужны доказательства?",a="Гюнтер выжил как независимая нежить, никому не доверяя. Окруженный Плетью, Алым орденом и другими угрозами в Тирисфале, он полагает, что любой посетитель из нежити может оказаться агентом Короля-лича, посланным подчинить его, пока тот не прольет кровь Плети.",al={"why does gunther doubt me","gunther trust","почему гюнтер сомневается во мне","доверие гюнтера"}},{q="Кто такая Лилит Нефара?",a="Лилит Нефара — могущественный агент Плети, действующий на южных берегах Озера Ясноводного. Она орудует возле древнего кровавого алтаря рядом с островом Гюнтера, служа длани Короля-лича в лесах.",al={"who is lillith","lillith nefara lore","кто такая лиллит","лиллит нефара предыстория"}},{q="Что такое Манящая свеча?",a="Манящая свеча — ритуальный предмет, который берут из ящика на острове Гюнтера. Если поставить и зажечь ее на кровавом алтаре, из места упокоения появится Лилит Нефара, и с ней можно сразиться.",al={"candle of beckoning","how to summon lillith","манящая свеча","как призвать лиллит"}},{q="К какому осознанию приходит Гюнтер после поражения Лилит?",a="Победа над Лилит заставляет Гюнтера принять поразительную истину: он не уникален. До этого испытания он искренне считал себя единственным в Лордероне, кто освободился от телепатического господства Короля-лича.",al={"gunther reaction","gunther epiphany","реакция гюнтера","прозрение гюнтера"}},{q="Где происходит это противостояние?",a="Ритуал проходит у алтаря на берегу озера, недалеко от южного побережья острова Гюнтера на Озере Ясноводном, в восточной части Тирисфальских лесов.",al={"where is the altar","lillith location","где алтарь","где лиллит"}},{q="Что происходит после доказательства преданности?",a="Когда сомнения Гюнтера рассеяны, он наконец соглашается выслушать посланников Подгорода и пересмотреть свое одинокое изгнание, что подготавливает его официальное вступление в ряды Отрекшихся леди Сильваны.",al={"what next after proving allegiance","after lillith dies","что дальше после доказательства преданности","после смерти лиллит"}}},fp="18,296,22.459.0,29.425.1,36.262.0,22.209.0,32.209.0,60.227.1,41.156.0,43.205.1"}
P.entries["quest:410"] = {n="Спящая тень",s="«Спящая тень» — темный ритуал, который проводится в разрушенных усадьбах Тирисфальских лесов. Поставив мистическую свечу на старый пропитанный кровью стол, путник призывает беспокойный дух, связанный с темными обрядами верности Отрекшихся.",h="«Спящая тень» — темный ритуал, который проводится в разрушенных усадьбах Тирисфальских лесов.",kw={"bloody table","candle of beckoning","dormant shade","forsaken ritual","lillith nefara","proving allegiance","tirisfal glades","окровавленный стол","манящая свеча","спящая тень","ритуал отрекшихся","лиллит нефара","доказательство преданности","тирисфальские леса"},ang={["class:Priest"]="Жрецы тьмы воспринимают зов свечи как упражнение в теневом общении, возвращающее беспокойную блуждающую душу в физическую схватку.",["class:Warlock"]="Чернокнижники понимают силу привязывания духов к залитым кровью алтарям, поэтому этот ритуал для них — привычный способ управлять границей между жизнью и смертью.",["race:Undead"]="Для Отрекшихся ритуалы над окровавленными руинами бывших домов Лордерона — мрачное напоминание о том, что их новое существование выковано смертью, темной магией и непоколебимой верностью Темной Госпоже."},sec={{t="Жуткий алтарь",b="Среди оскверненных руин Тирисфальских лесов стоит потрепанный окровавленный обеденный стол. Это не обычный заброшенный предмет домашней мебели, а материальный центр зловещего призыва. Покрытый засохшей кровью и оставленный во мраке, стол служит самодельной ритуальной плитой, где задерживаются смерть и темная магия."},{t="Манящая свеча",b="Чтобы пробудить то, что таится в этом месте, нужно поставить Манящую свечу на окровавленную поверхность и зажечь ее. Свет свечи рассекает мрак Тирисфаля и вызывает дух Лилит Нефары из-за завесы смерти. Это намеренное некромантическое вмешательство, призванное испытать тех, кто стремится доказать свою доблесть и преданность."}},faq={{q="Зачем зажигать свечу на столе?",a="Если зажечь Манящую свечу на потрепанном окровавленном столе, появится тень Лилит Нефары — опасное видение, которое необходимо уничтожить.",al={"why light candle","dormant shade objective","table ritual","зачем зажигать свечу","цель спящей тени","ритуал у стола"}},{q="Кто появляется в ходе этого ритуала?",a="Ритуал вызывает Лилит Нефару, дух нежити, обитающий в разрушенных усадьбах Тирисфальских лесов.",al={"who spawns","dormant shade ghost","who is the shade","кто появляется","призрак спящей тени","кто эта тень"}},{q="Как это связано с доказательством преданности Отрекшихся?",a="Призыв и уничтожение Лилит Нефары — важное испытание в задании «Доказательство преданности». Оно показывает готовность и способность новобранца Отрекшихся изгонять упорные видения в Тирисфале.",al={"proving allegiance connection","why kill lillith","forsaken test","доказательство преданности","зачем убивать лиллит","испытание отрекшихся"}},{q="Где проходит этот ритуал?",a="Ритуал проводится в старой разрушенной усадьбе в Тирисфальских лесах, у потрепанного деревянного обеденного стола, покрытого засохшей кровью.",al={"table location","where is the table","lilliths dinner table","место стола","где стол","обеденный стол лиллит"}},{q="Может ли любой зажечь свечу?",a="Зажечь пламя на алтаре может любой, у кого есть Манящая свеча и кто проходит испытания преданности Отрекшихся.",al={"who can do the ritual","class requirements","candle ritual","кто может провести ритуал","требования к классу","ритуал со свечой"}},{q="Стол сам по себе населен призраками?",a="Сам стол — мрачная реликвия падения Лордерона, пропитанная насилием и остаточной темной энергией, которая позволяет Манящей свече закрепить и проявить спящую тень.",al={"is the table magical","why the bloody table","стол магический","почему окровавленный стол"}}},fp="17,242,16.332.0,23.379.1,56.146.0,31.106.0,59.199.0,34.124.0,28.139.0,31.177.0"}
P.entries["quest:411"] = {n="Возвращение блудного лича",s="«Возвращение блудного лича» завершает усилия по вербовке Гюнтера Чародея в ряды Отрекшихся. Доказав свои намерения и вернув его гримуар, вы относите самоцвет тайного общения Бетору Ледострелу в Подгород.",h="«Возвращение блудного лича» завершает усилия по вербовке Гюнтера Чародея в ряды Отрекшихся.",kw={"arcanus","bethor","brightwater lake","gunther","iceshard","lich","nether gem","prodigal","undercity","чародей","бетор","озеро ясноводное","гюнтер","ледострел","лич","самоцвет пустоты","блудный","подгород"},ang={["class:Mage"]="Наблюдая, как Бетор общается с Гюнтером, видишь безупречное слияние традиционного даларанского волшебства и темной некромантии, которую практикуют в Магическом квартале Подгорода.",["faction:Horde"]="Вербовка независимого некроманта высшего уровня, такого как Гюнтер, значительно укрепляет магические позиции Орды в Восточных королевствах.",["race:Undead"]="Освобождение Гюнтера без вмешательства Королевы банши — живое доказательство силы воли, на которую способны павшие Лордерона."},sec={{t="Редкое примирение",b="Гюнтер Чародей провел годы в изоляции на острове на озере Ясноводном. Он освободился от власти Короля-лича силой собственной воли и не знал, что Сильвана Ветрокрылая освободила Лордерон. Озлобленный и подозрительный к чужакам, Гюнтер не доверял посланникам Подгорода, пока искатель приключений не вернул ему книгу заклинаний и не доказал свою враждебность к Плети. Убедившись, что гость не враг, Гюнтер доверил ему Самоцвет Пустоты, чтобы связаться с бывшим коллегой."},{t="Общение в Магическом квартале",b="Вернувшись в Квартал магов Подгорода, посланник передает Самоцвет Пустоты Бетору Ледострелу. Бетор направляет силу самоцвета и вызывает эфирный образ Гюнтера прямо в убежище. Благодаря этому магическому общению лич, достигший могущества самостоятельно, официально соглашается примкнуть к делу Отрекшихся. Заполучить некроманта такого независимого мастерства — огромная удача для молодого королевства Темной Госпожи, усиливающая его магическую защиту и от Плети, и от живых."}},faq={{q="Кто такой Гюнтер Чародей?",a="Гюнтер Чародей — исключительно могущественный некромант, самостоятельно освободившийся от ментального господства Короля-лича. Он жил в уединенном изгнании на острове на озере Ясноводном и считал всю прочую нежить безвольными рабами, пока искатели приключений не доказали обратное.",al={"gunther arcanus lore","who is the prodigal lich","gunther undercity","предания о гюнтере чародее","кто такой блудный лич","гюнтер в подгороде"}},{q="Кто такой Бетор Ледострел?",a="Бетор Ледострел — старший маг и ученый, живущий в Магическом квартале Подгорода. Он старый коллега Гюнтера Чародея и координировал усилия по его поиску и вербовке в ряды Отрекшихся.",al={"bethor lore","who is bethor","iceshard undercity","предания о бееторе","кто такой бетор","ледострел подгород"}},{q="Что делает Самоцвет Пустоты?",a="Самоцвет Пустоты — зачарованный артефакт, предоставленный Гюнтером Чародеем. Когда Бетор Ледострел направляет в него тайную силу, он создает призрачный образ Гюнтера, позволяя двум заклинателям разговаривать на большом расстоянии.",al={"what is the nether gem","gunther gem","что такое самоцвет пустоты","самоцвет гюнтера"}},{q="Почему Гюнтер соглашается присоединиться к Отрекшимся?",a="Гюнтер годами боялся, что он единственная свободная нежить в Лордероне. Убедившись, что Отрекшиеся Сильваны действительно свободны от Плети и активно борются с Королем-личом, он охотно клянется в верности и возобновляет связи с бывшими соратниками.",al={"why join forsaken","gunther allegiance","зачем присоединяться к отрекшимся","верность гюнтера"}},{q="Почему в задании Гюнтера называют личем?",a="Хотя Гюнтер имеет обычный скелетообразный и разложившийся облик Отрекшегося, а не парящий облик лича Плети в ореоле льда, он стал личем самостоятельно благодаря глубокому мастерству в некромантии и непреклонной воле.",al={"is gunther a real lich","gunther lich form","настоящий ли гюнтер лич","облик лича гюнтера"}},{q="Что происходит, когда вы сдаете Самоцвет Пустоты?",a="После доставки Бетор активирует самоцвет и вызывает образ Гюнтера в Магическом квартале. Проекция движется к Бетору, начиная давно ожидаемую встречу, а затем исчезает.",al={"nether gem turn in event","what happens at bethor","событие сдачи самоцвета","что происходит у бетора"}}},fp="25,239,21.524.0,30.488.1,23.268.0,23.205.0,28.233.0,44.270.1,41.239.0,45.193.1"}
P.entries["quest:412"] = {n="Операция \"Перенаправление\"",s="«Операция „Перенаправление“» — смелое инженерное предприятие Раззла Шустреца в Караносе. После трагедии Гномрегана Раззл и Оззи Триггервольт стремятся обратить ужасное превращение своих пострадавших сородичей в лепрогномов с помощью экспериментального устройства — рекомбобулятора.",h="«Операция „Перенаправление“» — смелое инженерное предприятие Раззла Шустреца в Караносе.",kw={"dun morogh","gnomeregan","gyromechanic gear","kharanos","leper gnome","ozzie togglevolt","razzle sprysprocket","recombobulator","restabilization cog","дун морог","гномреган","гиромеханическая шестеренка","каранос","лепрогном","оззи триггервольт","раззл шустрец","рекомбобулятор","стабилизирующая шестерня"},ang={["profession:Engineering"]="Инженеры оценят необычные ухищрения Раззла: хитроумные стабилизирующие шестерни, трещотки и вязкий электрогель для воздействия на биофизическую радиацию.",["race:Gnome"]="Для гномов это задание — отчаянная, искренняя надежда спасти потерянных родных и друзей, превратившихся в агрессивные оболочки при падении их столицы."},sec={{t="Лекарство от бедствия",b="Когда Гномреган затопили радиацией, чтобы избавиться от троггов, захватчиков это не уничтожило, а большинство гномов превратилось в безумных больных лепрогномов. Не желая мириться с тем, что эта трагическая мутация необратима, изобретатель Раззл Шустрец вместе с Оззи Триггервольтом разрабатывает технологическое лекарство — рекомбобулятор. Их дерзкая цель — вернуть мутировавших собратьев к здоровью и рассудку."},{t="Сбор деталей у пострадавших",b="Для создания хрупкого прототипа нужны точные детали — стабилизирующие шестерни и гиромеханические шестеренки. По иронии судьбы, эти важные детали добывают прямо с враждебных лепрогномов, бродящих за запертыми воротами Гномрегана. Собирая механический хлам со своих искаженных братьев и сестер, Раззл надеется собрать устройство, которое отменит их общую трагедию."}},faq={{q="Для чего предназначен рекомбобулятор?",a="Рекомбобулятор — экспериментальная машина, созданная Раззлом Шустрецом и Оззи Триггервольтом, чтобы обратить ужасные мутагенные последствия радиации Гномрегана и излечить лепрогномов.",al={"what is recombobulator","purpose of recombobulator","recombobulate meaning","что такое рекомбобулятор","назначение рекомбобулятора","значение рекомбобуляции"}},{q="Кто такие Раззл Шустрец и Оззи?",a="Это гномы-изобретатели, работающие в Караносе в Дун Мороге. После падения Гномрегана они посвятили свои инженерные таланты изучению кризиса и созданию технологических решений, чтобы спасти свой изгнанный и облученный народ.",al={"who is razzle","who is ozzie togglevolt","razzle sprysprocket lore","кто такой раззл","кто такой оззи триггервольт","предания о раззле шустреце"}},{q="Почему за пределами Гномрегана есть лепрогномы?",a="Во время вторжения троггов в Гномреган в город выпустили радиацию, чтобы уничтожить тварей. Расчет обернулся катастрофой: троггов это не остановило, а многих выживших гномов свело с ума и превратило во враждебных лепрогномов.",al={"why are gnomes lepers","how did leper gnomes happen","gnomeregan radiation","почему гномы прокаженные","как появились лепрогномы","радиация гномрегана"}},{q="Откуда берутся детали для рекомбобулятора?",a="Их добывают прямо с безумных лепрогномов, бродящих у входа в Гномреган на западе Дун Морога, — на их телах все еще остается технологическое оборудование.",al={"where to get cogs and gears","restabilization cogs source","gyromechanic gears","где взять шестерни и шестеренки","источник стабилизирующих шестерен","гиромеханические шестеренки"}},{q="Работает ли рекомбобулятор на самом деле?",a="Раззл утверждает, что с правильными деталями, гидросмазкой и подстройкой электрогелевой массы машина вернет гномам нормальный облик. Однако гномья инженерия известна своей непредсказуемостью, и сможет ли она действительно обратить токсичное облучение, неясно.",al={"did recombobulator cure them","can leper gnomes be cured","recombobulator success","вылечил ли рекомбобулятор","можно ли вылечить лепрогномов","успех рекомбобулятора"}}},fp="25,321,23.462.0,29.415.0,42.202.0,38.259.0,46.255.0,52.187.0,38.271.0"}
P.entries["quest:413"] = {n="\"Мерцающий портер\"",s="После создания экспериментального «Мерцающего портера» в Поселке Пивоваров Регольд Ячменовар просит путников доставить свежий бочонок его брату Велларту. Велларт — дворф, горный пехотинец, стоящий на южной сторожевой башне у прохода к Лок Модану, где на холодном посту крепкий напиток особенно кстати.",h="После создания экспериментального «Мерцающего портера» в Поселке Пивоваров Регольд Ячменовар просит путников...",kw={"dun morogh","kharanos","mountaineer barleybrew","rejold barleybrew","shimmer stout","south gate pass","wellart","дун морог","каранос","горный пехотинец ячменовар","регольд ячменовар","мерцающий портер","южные врата","велларт"},ang={["faction:Alliance"]="Снабжение бдительных горных пехотинцев помогает поддерживать сеть стражи, защищающей дорогу между Дун Морогом и Лок Моданом.",["race:Dwarf"]="Для дворфов делиться элем с родными так же важно, как охранять горные проходы, поэтому такая доставка — неотъемлемая часть жизни на границе Стальгорна."},sec={{t="Семейный рецепт на границе",b="Регольд Ячменовар довел до совершенства свое новое творение — «Мерцающий портер», используя мерцающие листья, собранные на ледяных утесах Дун Морога. Пока остальные Ячменовары посвящают свое мастерство чанам и бочкам Поселка Пивоваров, брат Регольда Велларт избрал жизнь горного пехотинца. Зная об одиноком карауле на границе, Регольд посылает свежий бочонок с проезжими путниками — и как братскую услугу, и как настоящую пробу."},{t="Южная сторожевая башня",b="Велларт Ячменовар несет службу на южной сторожевой башне у Южных врат, ведущих в Лок Модан. Высоко на горном проходе горные пехотинцы терпят пронизывающие ветры и редкие нападения зверей, присматривая за путниками на горной дороге. Напитки на исходе, а скука одолевает, и Велларт находит, что «Мерцающий портер» бьет как следует — так, что в темной горной ночи его взор будто проясняется."}},faq={{q="Кто такой горный пехотинец Ячменовар?",a="Горный пехотинец Велларт Ячменовар — брат Регольда Ячменовара. В отличие от родни, варящей эль в Поселке Пивоваров, Велларт пошел служить в горные пехотинцы Дун Морога и охраняет высокий проход, соединяющий Дун Морог с Лок Моданом.",al={"who is wellart barleybrew","wellart barleybrew","mountaineer barleybrew lore","кто такой велларт ячменовар","велларт ячменовар","предания о горном пехотинце ячменоваре"}},{q="Где находится южная сторожевая башня?",a="Башня стоит на восточной границе Дун Морога и охраняет Южные врата, которые прорезают горы по пути в соседнюю долину Лок Модан.",al={"where is southern guard tower","mountaineer barleybrew location","where is wellart","где южная сторожевая башня","где горный пехотинец ячменовар","где велларт"}},{q="Чем особенен «Мерцающий портер»?",a="«Мерцающий портер» варят из особых мерцающих листьев, собранных в заснеженной глуши. По словам Велларта, после него глаза ярко блестят и кажется, будто видишь сквозь тьму.",al={"what does shimmer stout do","shimmer stout effect","что делает мерцающий портер","эффект мерцающего портера"}},{q="Что происходит после того, как Велларт выпьет портер?",a="Велларту напиток так понравился, что он просит путников отнести еще один бочонок в Лок Модан и поделиться им с горным пехотинцем Кэдреллом, патрулирующим дорогу через Телсамар.",al={"what is next after shimmer stout","next quest after shimmer stout","что дальше после мерцающего портера","следующее задание после мерцающего портера"}}},fp="13,336,31.460.0,26.445.0,30.240.0,42.161.0,33.223.0,44.176.1"}
P.entries["quest:414"] = {n="Портер для Кэдрелла",s="«Портер для Кэдрелла» — задание Альянса на доставку: оно уводит путников из заснеженных высот Дун Морога в умеренную долину Лок Модана. Вам доверяют бочонок только что доведенного до совершенства «Мерцающего портера» Регольда Ячменовара, и вы несете крепкий напиток через границу, чтобы поделиться им с горным пехотинцем Кэдреллом, патрулирующим Телсамар.",h="«Портер для Кэдрелла» — задание Альянса на доставку: оно уводит путников из заснеженных высот Дун Морога в...",kw={"ale","barleybrew","cask","dun morogh","kadrell","loch modan","rejold","shimmer stout","thelsamar","эль","ячменовар","бочонок","дун морог","кэдрелл","лок модан","регольд","мерцающий портер","телсамар"},ang={["faction:Alliance"]="Это задание служит естественной нитью, выводящей героев Альянса из заснеженных стартовых земель Дун Морога в более широкие пределы Лок Модана.",["race:Dwarf"]="Доставить бочонок горного эля через границу — настоящее дворфийское товарищество: оно связывает пивоваров Поселка Пивоваров с пограничными дозорами, охраняющими Каз Модан."},sec={{t="Вкус за горами",b="Попробовав новый «Мерцающий портер», созданный его братом Регольдом, горный пехотинец Ячменовар убежден, что он слишком хорош, чтобы оставаться только в Дун Мороге. Он служит на восточном пограничном посту, охраняющем горные перевалы, и поглядывает в сторону сородичей, охраняющих соседние земли. Служба горного пехотинца-дворфа бывает холодной и изматывающей, а крепкому сердцу нужен крепкий напиток. Желая получить честную оценку от собрата по дозору, Ячменовар отправляет бочонок на восток с проходящими путниками, идущими в Лок Модан."},{t="Дорога в Телсамар",b="Это путешествие — своего рода обряд посвящения для молодых дворфов и гномов-искателей приключений, проведших первые дни среди заснеженных скал Дун Морога. Пройдя на юго-восток через Форт у Южных врат и по длинным туннелям, прорубленным в горной породе, путники внезапно выходят в более теплую, лесистую котловину Лок Модана. Горный пехотинец Кэдрелл, патрулирующий дорогу через поселение Телсамар, охотно прерывает дозор, чтобы откупорить бочонок, и обнаруживает, что новый рецепт Ячменовара поразительно крепок."}},faq={{q="Кто такой горный пехотинец Кэдрелл?",a="Горный пехотинец Кэдрелл — дворф-защитник, служащий в Лок Модане. Он проводит дни, патрулируя главную дорогу, которая проходит прямо через поселок Телсамар.",al={"kadrell","who is kadrell","mountaineer kadrell location","кэдрелл","кто такой кэдрелл","где горный пехотинец кэдрелл"}},{q="Что такое «Мерцающий портер»?",a="«Мерцающий портер» — крепкий особый эль, который варит Регольд Ячменовар на пивоварне в Поселке Пивоваров в западном Дун Мороге; он славится головокружительной крепостью и бодрящим теплом.",al={"what is shimmer stout","shimmer stout","rejold brew","что такое мерцающий портер","мерцающий портер","пиво регольда"}},{q="Как добраться из Дун Морога в Лок Модан?",a="От восточных застав в Дун Мороге идите на юго-восток через горные туннели мимо Южных врат. Выйдя в Лок Модан, следуйте по дороге: она раздваивается и ведет на северо-восток прямо к прибрежному поселению Телсамар.",al={"how to get to loch modan","road to thelsamar","dun morogh to loch modan","как попасть в лок модан","дорога в телсамар","из дун морога в лок модан"}},{q="Почему Ячменовар хочет, чтобы Кэдрелл попробовал пиво?",a="Горный пехотинец Ячменовар и горный пехотинец Кэдрелл — собратья по дворфийским горным пехотинцам. Ячменовар так впечатлен новым рецептом брата, что хочет, чтобы его товарищ по оружию из соседней долины тоже его оценил.",al={"why send stout to kadrell","barleybrew kadrell connection","зачем отправлять портер кэдреллу","ячменовар и кэдрелл"}},{q="Что Кэдрелл думает о напитке?",a="Сделав глоток, Кэдрелл поражается крепости напитка и клянется бородой Магни, что портер кружит ему голову и делает тело таким легким, что он готов взлететь.",al={"kadrell reaction","is shimmer stout good","реакция кэдрелла","хорош ли мерцающий портер"}},{q="Ведет ли это задание к другим заданиям?",a="Хотя оно завершает цепочку доставки «Мерцающего портера», начатую в Дун Мороге, доставка бочонка приводит путников прямо в Телсамар, где открывается множество новых заданий и поручений по всему Лок Модану.",al={"stout to kadrell follow up","what comes next","портер для кэдрелла продолжение","что дальше"}}},fp="16,342,28.538.0,21.546.0,27.167.0,22.186.0,42.233.0,49.233.0,36.180.0,38.204.0"}
P.entries["quest:415"] = {n="Новое пиво Регольда",s="«Новое пиво Регольда» — поручение Альянса в Дун Мороге, призывающее искателя приключений вернуться в Поселок Пивоваров. Создав новый напиток с собранным звездолистом, пивовар Регольд Ячменовар хочет, чтобы надежный друг попробовал его последний рецепт. Это звено между сбором припасов для пивоварения и распространением его драгоценного «Мерцающего портера» по горному королевству.",h="«Новое пиво Регольда» — поручение Альянса в Дун Мороге, призывающее искателя приключений вернуться в Поселок...",kw={"ale","brew","brewnall village","dun morogh","pilot bellowfiz","rejold barleybrew","shimmer stout","shimmerweed","tharek blackstone","эль","пиво","поселок пивоваров","дун морог","пилот толстопуз","регольд ячменовар","мерцающий портер","звездолист","тарек чернокамень"},ang={["faction:Alliance"]="Крепкий дворфийский эль поддерживает гарнизоны Альянса по всем Восточным королевствам и не дает падать духу в суровых пограничных фортах вроде Дун Морога.",["race:Dwarf"]="Для дворфа вряд ли есть почесть выше, чем получить личное приглашение от уважаемого пивовара сделать первый глоток из свежего бочонка."},sec={{t="Зов в Поселок Пивоваров",b="В Дун Мороге быстро разлетается молва, когда дворф-пивовар находит золотую жилу в своем погребе. Когда звездолист добыт на суровых склонах, местные знакомые — Тарек Чернокамень или пилот Толстопуз — просят проходящих искателей приключений вернуться в Поселок Пивоваров. Регольд Ячменовар закончил брожение своих опытных партий и хочет поделиться плодами с тем, кто это сделал возможным."},{t="Вкус плодов труда",b="Поселок Пивоваров живет особым искусством эля, и новая партия Ячменовара — не простой напиток. Добавив местные травы в сусло, он получил особый напиток — «Мерцающий портер». Прежде чем отправить бочки в соседние форты и к жаждущим посетителям Лок Модана, Регольд настаивает, чтобы первый глоток достался искателю приключений, рискнувшему жизнью ради этих трав."}},faq={{q="Кто отправляет меня обратно к Регольду Ячменовару?",a="Союзники в Дун Мороге, такие как Тарек Чернокамень или пилот Толстопуз, сообщают вам, что Регольд просит вас вернуться в Поселок Пивоваров.",al={"who starts rejolds new brew","quest giver","where to get quest","кто дает новое пиво регольда","персонаж, выдающий задание","где взять задание"}},{q="Где находится Поселок Пивоваров?",a="Поселок Пивоваров приютился в западной части Дун Морога, на берегу Заледеневшего озера.",al={"where is brewnall","brewnall village location","rejold barleybrew location","где поселок пивоваров","поселок пивоваров расположение","где регольд ячменовар"}},{q="Из чего сделан новый напиток Регольда?",a="Регольд сварил новый напиток, добавив в свои традиционные рецепты эля дикий звездолист — необычное растение, растущее в холодных скалах Дун Морога.",al={"what is in the brew","what did rejold make","shimmerweed recipe","что в пиве","что сварил регольд","рецепт со звездолистом"}},{q="Что будет после разговора с Регольдом?",a="Регольд предлагает вам попробовать новое творение, а затем поручает доставить бочонок «Мерцающего портера» его брату Велларту, горному пехотинцу, служащему в южной сторожевой башне на границе с Лок Моданом.",al={"next quest","what comes next","rejold chain","следующее задание","что дальше","цепочка регольда"}},{q="Почему Регольд хочет, чтобы именно я попробовал?",a="Поскольку вы помогли ему добыть редкий звездолист для опытного рецепта, Регольд считает правилом дворфийской учтивости дать вам первым попробовать готовый напиток.",al={"why does rejold want me","who tested the beer","почему регольд выбрал меня","кто пробовал пиво"}},{q="Как называется готовый напиток?",a="Опытная смесь получила название «Мерцающий портер» по главному ингредиенту, придающему ей особую крепость.",al={"what drink did he make","drink name","rejold's beer","какой напиток он сварил","название напитка","пиво регольда"}}},fp="17,374,21.398.0,26.387.0,39.158.0,26.112.0,35.166.0,37.214.1,47.180.0,39.118.0"}
P.entries["quest:4161"] = {n="Рецепт кальдораев",s="«Рецепт кальдораев» — урок равновесия от Заррина, наставника по кулинарии в Доланааре. Собирая точное число паучьих ног по всему Тельдрассилу, начинающие повара узнают, что пропитание от природы требует сдержанности и уважения.",h="«Рецепт кальдораев» — урок равновесия от Заррина, наставника по кулинарии в Доланааре.",kw={"cooking","dolanaar","kaldorei","recipe of the kaldorei","spider kabob","teldrassil","zarrin","кулинария","доланаар","кальдораи","рецепт кальдораев","паучий шашлычок","тельдрассил","заррин"},ang={["profession:Cooking"]="Это задание — раннее знакомство с кулинарией дикой природы в Тельдрассиле; наградой служит рецепт паучьего шашлычка кальдораев.",["race:NightElf"]="Урок подкрепляет основу мировоззрения кальдораев: гармонию с природой, достигаемую сдержанностью и стремлением брать лишь необходимое."},sec={{t="Дети звезд",b="За гостиницей в Доланааре Заррин присматривает за кипящим котлом и рассказывает молодым искателям приключений о традициях своего народа. Задолго до наших дней ночные эльфы называли себя кальдораями, что значит «дети звезд». Для Заррина понимание этого наследия предков начинается не на поле боя, а в отношениях между охотником, его пищей и окружающими ветвями Тельдрассила."},{t="Брать только необходимое",b="Суть урока — в сдержанности. Заррин поручает ученикам собрать мелкие паучьи ноги у лесных паукообразных близ Тенистой долины, но строго велит взять ровно семь, не больше. В культуре ночных эльфов жизнь в гармонии с природой требует брать лишь необходимое и отвечать дикой природе добром. Это хрупкое равновесие нужно хранить даже в тяжелые времена — эта философия превращает простой паучий шашлычок в нравственную дисциплину."}},faq={{q="Кто такой Заррин?",a="Заррин — ночной эльф, наставник по кулинарии, который присматривает за котлом позади гостиницы в Доланааре. Он учит молодых искателей приключений готовить, подчеркивая важность ценностей предков-кальдораев.",al={"zarrin","who is zarrin","dolanaar cook","cooking trainer dolanaar","заррин","кто такой заррин","повар доланаара","учитель кулинарии доланаар"}},{q="Почему Заррин настаивает на сборе ровно семи паучьих ног?",a="Заррин подчеркивает, что кальдораи должны жить в гармонии с природой, беря лишь необходимое для выживания. Сбор строго нужного количества воспитывает уважение к живому лесу и сохраняет природное равновесие.",al={"why seven legs","why only seven","take no more than seven","почему семь ног","почему только семь","не больше семи"}},{q="Что означает слово «кальдораи»?",a="На дарнасском языке «кальдораи» переводится как «дети звезд» — это древнее название, которым народ ночных эльфов называет себя тысячи лет.",al={"what does kaldorei mean","kaldorei meaning","children of the stars","что значит кальдораи","значение слова кальдораи","дети звезд"}},{q="Где собирают паучьи ноги?",a="Ноги можно добыть у лесных пауков, бродящих по лесам Тельдрассила за пределами защищенных границ Тенистой долины.",al={"where do spiders drop legs","spider leg location","which spiders","с каких пауков падают ноги","где взять паучьи ноги","какие пауки"}},{q="Что ночные эльфы готовят из паучьих ног?",a="Заррин учит искателей приключений готовить паучий шашлычок кальдораев — традиционное блюдо дикой природы, превращающее мясо лесных пауков в питательную еду в дорогу.",al={"what is the recipe","kaldorei spider kabob","spider food","какой рецепт","паучий шашлычок кальдораев","еда из пауков"}},{q="Все ли пауки в Тельдрассиле дают нужные ноги?",a="Нет. Молодые пауки в защищенной Тенистой долине не дают подходящих ног для рецепта Заррина; нужно охотиться на пауков, бродящих по просторным лесам Тельдрассила.",al={"do shadowglen spiders work","shadowglen spider legs","подходят ли пауки тенистой долины","паучьи ноги тенистой долины"}}},fp="22,251,21.408.0,26.479.0,14.195.0,63.221.0,35.166.0,35.128.0,45.165.0,51.189.0"}
P.entries["quest:417"] = {n="Месть пилота",s="След пропавшего пилота дворфийской осадной машины приводит к замерзшему телу в глуши Дун Морога. Среди останков найден личный дневник Хильдельва, где описана его роковая схватка со свирепым хищником по прозвищу Шелудивый Коготь; он оставил предсмертное желание отомстить.",h="След пропавшего пилота дворфийской осадной машины приводит к замерзшему телу в глуши Дун Морога.",kw={"dun morogh","hammerfoot","hildelve","ice claw bear","ironforge siege brigade","mangeclaw","revenge","дун морог","большеног","хильдельв","медведь-ледолап","осадная бригада стальгорна","шелудивый коготь","месть"},ang={["class:Hunter"]="Выследить необычайно свирепого вожака зверей вроде Шелудивого Когтя в ледяных ветрах Дун Морога — настоящее испытание на выживание в горах.",["faction:Alliance"]="Пилоты Стальгорна — важная часть обороны дворфов и Альянса, поэтому поиск пропавших пилотов — первостепенный долг.",["race:Dwarf"]="Отомстить за павшего брата из Осадной бригады Стальгорна — дело чести: так память о Хильдельве будет почтена, а его убийца наказан."},sec={{t="Последняя запись",b="Пилот Хильдельв не пережил времени, проведенного в суровых заснеженных скалах. Когда путники находят его останки, рядом они обнаруживают его дневник. В последних строках Хильдельв описал жестокую схватку с огромным медведем-ледолапом, которого назвал Шелудивым Когтем. Он сумел поначалу отбиться от чудовища, но раны были тяжелыми, и зверь вернулся, чтобы добить ослабевшего пилота."},{t="Предсмертное желание пилота",b="Зная, что конец близок, Хильдельв записал в дневнике последнюю просьбу — возмездие чудовищу, отнявшему его жизнь. Возвращение к пилоту Большеногу с дневником и когтем, вырванным у поверженного зверя, приносит мрачное завершение Осадной бригаде Стальгорна, чтит память погибшего товарища и избавляет горные тропы от смертельной угрозы."}},faq={{q="Кто такой Хильдельв?",a="Пилот Хильдельв — дворф, пилот осадной машины и член Осадной бригады Стальгорна. После поломки машины он отправился пешком в горы Дун Морога; его друг пилот Большеног послал на поиски людей, и те обнаружили лишь его останки в снегу.",al={"hildelve","who is the dead dwarf","lost pilot","хильдельв","кто мертвый дворф","пропавший пилот"}},{q="Кто такой Шелудивый Коготь?",a="Шелудивый Коготь — исключительно крупный и свирепый медведь-ледолап, бродящий по склонам Дун Морога. Он напал на пилота Хильдельва из засады и нанес смертельные раны, а затем вернулся, чтобы убить его.",al={"mangeclaw","ice claw bear","who killed hildelve","шелудивый коготь","медведь-ледолап","кто убил хильдельва"}},{q="Кто такой пилот Большеног?",a="Пилот Большеног — опытный пилот осадной машины, служащий в Дун Мороге и состоящий в Осадной бригаде Стальгорна. Глубоко встревоженный пропажей друга Хильдельва, он отправляет искателей приключений в глушь выяснить, что случилось.",al={"hammerfoot","pilot hammerfoot","большеног","пилот большеног"}},{q="Почему смерть Хильдельва важна для Стальгорна?",a="Осадная бригада Стальгорна зависит от обученных пилотов и машин, которые ведут разведку и охраняют горные земли вокруг столицы. Потеря опытного пилота вроде Хильдельва — тяжелый удар по рядам бригады.",al={"why care about hildelve","siege brigade importance","почему важен хильдельв","значение осадной бригады"}},{q="Где начинается эта цепочка заданий?",a="Все начинается с того, что пилот Большеног предлагает задание «Пропавший пилот» и просит вас найти его пропавшего друга. Это приводит к находке тела Хильдельва, с которой начинается «Месть пилота».",al={"how to start a pilot's revenge","lost pilot quest chain","как начать месть пилота","цепочка пропавшего пилота"}},{q="Какие доказательства нужно принести Большеногу?",a="Вы должны предъявить и «Записи Хилдельва», найденные на теле пилота, и «Грязный коготь», снятый с туши Шелудивого Когтя, в доказательство того, что зверь убит.",al={"mangeclaw proof","what items needed","доказательство шелудивого когтя","какие предметы нужны"}}},fp="17,284,13.421.0,20.347.0,17.276.0,18.193.0,24.239.0,46.214.0,34.187.0,46.159.0"}
P.entries["quest:418"] = {n="Телсамарские кровяные колбаски",s="В оживленном Телсамаре повариха Видра Жаркий Очаг кормит местных рабочих и шахтеров знаменитым блюдом нагорий — кровяными колбасками. Для этой сытной дворфийской еды нужны свежие ингредиенты из окрестностей Лок Модана.",h="В оживленном Телсамаре повариха Видра Жаркий Очаг кормит местных рабочих и шахтеров знаменитым блюдом нагорий...",kw={"bear meat","blood sausage","boar intestines","cooking","loch modan","spider ichor","thelsamar","vidra hearthstove","медвежье мясо","кровяная колбаса","кишки кабана","кулинария","лок модан","паучья сукровица","телсамар","видра жаркий очаг"},ang={["faction:Alliance"]="Помощь Видре позволяет кормить местных работников Телсамара, которые поддерживают важную инфраструктуру и раскапывают древние руины по всему Лок Модану.",["profession:Cooking"]="За сбор ингредиентов для Видры начинающие повара получают подлинный рецепт кровяной колбасы, пополняя запас сытных походных блюд.",["race:Dwarf"]="Кровяная колбаса — классическая дворфийская еда для души, воплощающая суровые кулинарные вкусы горных кланов Каз Модана."},sec={{t="Сытное блюдо нагорий",b="В Телсамаре всегда хватает голодных ртов. Между непоседливыми детьми и усталыми шахтерами, возвращающимися из раскопок Сталекрута, Видра Жаркий Очаг трудится у печи таверны без отдыха. Чтобы накормить жителей, она полагается на местную кулинарную традицию, известную по всему Лок Модану: пряные кровяные колбаски из зверей, бродящих по суровым горным перевалам."},{t="Необычные приправы",b="Традиционная кровяная колбаса готовится из свежей крови, приправленного мяса и натуральной оболочки, но рецепт Видры отражает суровую практичность дворфов. Оболочкой служат кишки кабана, плотной начинкой — медвежье мясо, а паучья сукровица придает резкую, острую нотку. Добывать ядовитую жидкость и потроха не для слабонервных, но результат — любимое блюдо региона, которое путники быстро учатся ценить."}},faq={{q="Кто такая Видра Жаркий Очаг?",a="Видра Жаркий Очаг — местная повариха и хозяйка в Телсамаре, живущая в таверне «Крепкое пойло». Она очень гордится тем, что кормит трудолюбивый народ Лок Модана, особенно рабочих с ближних раскопок.",al={"vidra","who is vidra","thelsamar cook","видра","кто такая видра","повариха телсамара"}},{q="Почему в рецепте используется паучья сукровица?",a="Видра добавляет паучью сукровицу как особую приправу, чтобы придать колбаскам фирменную остроту. Вкусы дворфов известны своей выносливостью, а ядовитая жидкость дает резкий вкус, с которым не сравнятся обычные травы.",al={"spider ichor in sausage","why spider ichor","spider spice","паучья сукровица в колбасе","почему паучья сукровица","паучья приправа"}},{q="Кто ест телсамарские кровяные колбаски?",a="Колбаски кормят местных горожан, шумных детей и усталых рабочих, каждый вечер возвращающихся с изнурительных смен на раскопках Сталекрута.",al={"who eats blood sausage","why make sausage","кто ест кровяную колбасу","зачем делать колбасу"}},{q="Где найти ингредиенты?",a="Все три составляющие — черные медведи, горные кабаны и лесные пауки-засадники — бродят по диким землям и лесистым холмам вокруг озера в Лок Модане.",al={"where to get bear meat","where to get boar intestines","ingredient locations","где взять медвежье мясо","где взять кишки кабана","где найти ингредиенты"}},{q="Какая оболочка используется для колбасок?",a="Видра использует натуральную оболочку из очищенных кишок местных горных кабанов. Она получается прочной и удерживает плотное медвежье мясо и приправленную начинку целыми над огнем.",al={"sausage casings","boar intestines","casing recipe","оболочка для колбас","кишки кабана","рецепт оболочки"}},{q="Могут ли путники научиться готовить эти колбаски?",a="Да. Если искатель приключений принесет Видре ингредиенты, она охотно поделится рецептом, и путники со знанием кулинарии смогут сами приготовить это сытное дворфийское блюдо.",al={"can i cook blood sausage","sausage recipe","cooking recipe","можно ли приготовить кровяную колбасу","рецепт колбасы","кулинарный рецепт"}}},fp="24,260,22.374.0,21.436.0,25.226.0,37.208.0,34.162.0,32.154.0,37.168.0,42.169.0"}
P.entries["quest:419"] = {n="Пропавший пилот",s="Пилот Большеног опасается худшего за своего товарища Мори Хильдельва, который после поломки осадной машины отправился пешком в скалистые холмы Дун Морога. Хильдельв искал редкую руду, необходимую для мощного пороха, но прошли дни, а в горах эхом звучит тревожный рев.",h="Пилот Большеног опасается худшего за своего товарища Мори Хильдельва, который после поломки осадной машины...",kw={"blastpowder","brigadier vest","dun morogh","lost pilot","mori hildelve","pilot hammerfoot","siege engine","порох","жилет бригадира","дун морог","пропавший пилот","мори хильдельв","пилот большеног","осадная машина"},ang={["profession:Engineering"]="Экспедиция Хильдельва показывает неустанные поиски дворфами нестабильных минералов для получения мощной взрывчатки и пороха.",["race:Dwarf"]="Гибель опытного водителя осадной машины от диких зверей задевает дворфов за живое и напоминает о смертельных опасностях, подстерегающих даже на задворках Каз Модана."},sec={{t="Прерванные поиски",b="Дворфийские осадные машины — грозное оружие, но даже железные гусеницы с трудом справляются с коварными зубчатыми хребтами Дун Морога. Исследуя склоны в поисках редкого месторождения минерала для высококачественного пороха, пилот Мори Хильдельв загнал машину слишком высоко на крутой холм и сломал ее. Не смутившись поломкой, Хильдельв приказал своему товарищу, пилоту Большеногу, остаться и охранять разбитую технику, а сам пошел пешком выше, в замерзшую глушь."},{t="Эхо в снегах",b="Прошли дни, а Хильдельв не вернулся в лагерь. Глубокой ночью со скалистых утесов стали доноситься странные свирепые звериные рыки, и легкое нетерпение Большенога сменилось подступающим ужасом. Хотя Хильдельв слыл крепким, как гвозди, выжить на морозных высотах Дун Морога без механизированной брони и серьезной поддержки среди хищников — опасная авантюра."},{t="Мрачная находка",b="Путь по следам Хильдельва вверх по склонам ведет не к заблудившемуся разведчику, а к замерзшей трагедии. Тело дворфа лежит под открытым небом, растерзанное и обобранное горными падальщиками. В безжизненной руке крепко зажаты наспех исписанные заметки, а на изуродованном теле все еще висит жилет бригадира, подтверждающий, что отважный осадный инженер встретил безвременный и насильственный конец."}},faq={{q="Почему пилот Хильдельв оказался в глуши один?",a="Хильдельв искал редкий вид руды, нужный для изготовления высококачественного дворфийского пороха. Когда его осадная машина сломалась на крутом горном склоне, он решил идти дальше пешком по утесам, не оставляя поисков.",al={"why hildelve left","what was hildelve doing","pilot hildelve mission","почему хильдельв ушел","что делал хильдельв","миссия пилота хильдельва"}},{q="Кто отправляет вас искать Хильдельва?",a="Пилот Большеног, друг Хильдельва и такой же водитель осадной машины, просит путников разузнать, что случилось. Ему приказали остаться и охранять их поврежденную технику, пока Хильдельв разведывал путь.",al={"who gives quest","lost pilot quest giver","кто выдает задание","персонаж, выдающий задание пропавший пилот"}},{q="Что случилось с осадной машиной Хильдельва?",a="Хильдельв попытался загнать свою тяжелую машину прямо на крутой ледяной склон в поисках руды, сломал механизмы, и она застряла в снегу.",al={"broken siege engine","why engine broke","сломанная осадная машина","почему сломалась машина"}},{q="Что убило пилота Хильдельва?",a="Hammerfoot has heard beastly growls in the hills and fears for Hildelve. The pilot's fate is discovered by following his trail.",al={"hildelve killer","how did pilot die","who killed hildelve","убийца хильдельва","как погиб пилот","кто убил хильдельва"}},{q="Какие доказательства находят у тела Хильдельва?",a="Hammerfoot asks you to find Hildelve after he continued the ore search on foot. Any evidence of what happened to him is uncovered at the end of the search.",al={"hildelve evidence","hildelve corpse items","proof of death","улики хильдельва","вещи с тела хильдельва","доказательство смерти"}},{q="Что происходит после обнаружения тела Хильдельва?",a="Finding Hildelve reveals what happened during his search. The investigation then continues with the evidence found there.",al={"what next lost pilot","revenge quest","что дальше пропавший пилот","задание о мести"}}},fp="14,294,18.502.0,18.409.0,16.398.1,51.231.0,35.194.0,41.156.0,27.127.1,42.155.1,49.121.1"}
P.entries["quest:420"] = {n="Наблюдения Сенира",s="Это поручение завершает цепочку разведки из Холодной долины: завершенный отчет Грелина Белоборода нужно пронести через кишащий троггами перевал к его брату Сениру в Каранос. Оно связывает уединенные тренировочные земли Старой Наковальни с более серьезными бедами Дун Морога. По откровенному приему Сенира путники впервые видят политические трения между полевыми разведчиками и Сенатом Стальгорна.",h="Это поручение завершает цепочку разведки из Холодной долины: завершенный отчет Грелина Белоборода нужно...",kw={"coldridge valley","dun morogh","grelin whitebeard","grelin's report","ironforge senate","kharanos","mountaineer thalos","senir whitebeard","troggs","холодная долина","дун морог","грелин белобород","отчет грелина","сенат стальгорна","каранос","горный пехотинец талос","сенир белобород","трогги"},ang={["faction:Alliance"]="Помощь разведчикам в координации сведений сохраняет безопасность Дун Морога в то время, когда Штормград парализован внутренними раздорами и не может выделить помощь северным союзникам.",["race:Dwarf"]="Переход из защищенной учебной долины в Каранос знаменует ваш настоящий выпуск в оборону Каз Модана и дает первое представление о том, как полевые разведчики спорят с осторожным Сенатом Стальгорна.",["race:Gnome"]="Путь через перевал в Каранос приближает изгнанных гномов к главным центрам Дун Морога и к продолжающимся усилиям по поддержке их хозяев-дворфов."},sec={{t="Через туннель в Каранос",b="После того как Грелин Белобород вернул свой украденный дневник у троллей Мерзлогривов, он готовит подробный отчет об опасностях долины для брата Сенира. Горный пехотинец Талос, охраняющий ворота из Холодной долины, поручает доставить это донесение проходящим искателям приключений. Покинуть относительное уединение начальной долины значит рискнуть пройти туннель в горе, который недавно захватили свирепые трогги, нападающие на всех путников. Те, кто пробьется, выходят на заснеженные дороги центрального Дун Морога и по главной дороге приходят в уютный Каранос."},{t="Ворчливый прием и политика Сената",b="Сенир Белобород, которого находят греющимся за выпивкой в таверне «Громоварка» в Караносе, встречает новичков грубоватым гостеприимством горцев. Читая записи Грелина, Сенир посмеивается над резкой риторикой брата. Грелин щедро ссылается на имя короля Магни Бронзоборода, требуя срочных действий, и Сенир замечает, что такая настойчивость наверняка раздражит упрямый Сенат Стальгорна. Сенир признает, что отстал с подачей собственных наблюдений из-за лютого холода, но донесение Грелина возвращает его к делу и открывает новую работу по наблюдению за враждебными силами на заснеженных равнинах."}},faq={{q="Почему горный пехотинец Талос поручает доставить отчет путнику?",a="Горный пехотинец Талос поставлен удерживать оборону туннеля Холодной долины от агрессивных троггов. Он не может покинуть пост, поэтому, когда мимо проходит способный искатель приключений, поручает ему благополучно доставить донесение Грелина в Каранос.",al={"why thalos asks you","thalos courier","who gives this quest","почему талос просит вас","талос курьер","кто выдает это задание"}},{q="Кто такой Сенир Белобород?",a="Сенир Белобород — дворф-разведчик и брат Грелина Белоборода. Расквартированный в Караносе, он собирает полевые донесения разведки о местных угрозах, чтобы передавать высшему командованию в Стальгорне.",al={"who is senir","senir whitebeard kharanos","senir background","кто такой сенир","сенир белобород каранос","биография сенира"}},{q="Что содержится в отчете Грелина?",a="Отчет содержит выводы Грелина о действиях троллей Мерзлогривов и их вторжениях в Холодную долину. Написанный в спешке, он ссылается на власть короля Магни Бронзоборода, требуя от властей подкреплений и внимания.",al={"what does the report say","grelin report contents","grelins report lore","что говорится в отчете","содержание отчета грелина","отчет грелина предания"}},{q="Почему Сенир говорит, что отчет Грелина вызовет переполох в Сенате?",a="Грелин настойчиво ссылается на имя короля Магни, требуя действий. В политике Стальгорна опора на королевские указы может обойти или оспорить бюрократическую власть и гордость дворфийского Сената, раздражая членов совета, предпочитающих формальные обсуждения.",al={"senate feathers ruffled","senir ironforge senate","why is the senate mad","переполох в сенате","сенир сенат стальгорна","почему сенат зол"}},{q="Чем опасен туннель между Холодной долиной и Караносом?",a="Клан троггов-камнечелюстей недавно выбрался из глубоких подземных трещин и захватил горный туннель, нападая на всех дворфийских путников, торговцев и посыльных, пытающихся пройти.",al={"coldridge tunnel dangerous","trogg tunnel dun morogh","why are troggs in the tunnel","туннель холодной долины опасен","трогги в туннеле дун морога","почему в туннеле трогги"}},{q="Куда ведет дорога после доставки этого донесения?",a="Прибытие в Каранос вовлекает искателей приключений в общую оборону Дун Морога. Позже Сенир Белобород просит помочь в расследовании новых угроз от Мерзлогривов и троггов, а городские руководители направляют помощь в Поселок Пивоваров, Стальгорн и дальние фермы.",al={"what next after senir","next quest after senirs observations","where does kharanos lead","что дальше после сенира","следующее задание после наблюдений сенира","куда ведет каранос"}}},fp="20,421,30.616.0,36.628.0,63.254.0,24.192.0,27.234.0,70.252.0,66.193.0,55.260.0"}
P.entries["quest:421"] = {n="Проявить себя",s="«Проявить себя» — вводное задание Орды, которое выдает Далар Ткач Рассвета в Гробнице в Серебряном бору. Чтобы помочь кампании Отрекшихся против южных земель людей и дворфов, искатели приключений должны проредить диких воргенов, бродящих у дороги. Это первый шаг в раскрытии последствий тайной магии, вызванных верховным магом Аругалом.",h="«Проявить себя» — вводное задание Орды, которое выдает Далар Ткач Рассвета в Гробнице в Серебряном бору.",kw={"arugal","dalar dawnweaver","moonrage whitescalps","prove your worth","sepulcher","shadowfang keep","silverpine forest","worgen","аругал","далар ткач рассвета","белоскальпы лунной ярости","проявить себя","гробница","крепость темного клыка","серебряный бор","воргены"},ang={["class:Mage"]="Задание Далара Ткача Рассвета служит суровым предостережением магам о катастрофических рисках безрассудного колдовства призыва, олицетворением которых стал Аругал.",["faction:Horde"]="Усмирение дебрей Серебряного бора обеспечивает Орде беспрепятственную военную дорогу на юг Лордерона.",["race:Undead"]="Для Отрекшихся зачистка Серебряного бора необходима, чтобы защитить границы Подгорода и устранить угрозы, оставленные провалами Даларана."},sec={{t="Защита южного пути",b="Леди Сильвана Ветрокрылая и ее помощник, повелитель ужаса Вариматрас, намерены обезопасить земли к югу от Тирисфальских лесов, включая поселения людей и дворфов. Однако путь через Серебряный бор по-прежнему полон опасностей. Вместо открытого плацдарма Отрекшиеся обнаруживают, что их линии снабжения и передовые базы находятся под угрозой диких воргенов Лунной Ярости, бродящих по заросшим соснами холмам."},{t="Порча Аругала",b="Появление этих тварей — не естественное явление. Далар Ткач Рассвета прямо указывает на Аругала, опального бывшего мага Даларана, который во время вторжения Плети выпустил в этот край воргенов из иных миров. С тех пор Аругал занял Крепость Темного Клыка и позволил своим диким созданиям наводнить лес. Прежде чем Далар доверит солдатам более глубокое расследование колдовства Аругала, новобранцы должны доказать свою боевую доблесть, истребив ближайших белоскальпов Лунной Ярости."}},faq={{q="Кто такой Далар Ткач Рассвета?",a="Далар Ткач Рассвета — маг из числа Отрекшихся, расквартированный в Гробнице. Он руководит усилиями по противодействию магическим угрозам в Серебряном бору, в первую очередь стремясь обезвредить верховного мага Аругала и его стаю диких воргенов.",al={"dalar dawnweaver","who gives prove your worth","sepulcher questgiver","далар ткач рассвета","кто дает задание проявить себя","гробница задания"}},{q="Где находятся белоскальпы Лунной Ярости?",a="Белоскальпы бродят неподалеку от главной дороги у подножия холма, на котором стоит Гробница, и наводняют леса и разрушенные усадьбы в центре Серебряного бора.",al={"where are whitescalps","moonrage whitescalps location","whitescalp farm","где белоскальпы","белоскальпы лунной ярости расположение","фарм белоскальпов"}},{q="Почему Орду волнуют воргены в Серебряном бору?",a="Серебряный бор — важнейший стратегический путь, соединяющий Подгород с южными землями. Леди Сильване и Вариматрасу нужен безопасный проход, чтобы проецировать силу на юг, и агрессивные стаи воргенов стали недопустимой угрозой.",al={"why kill worgen","forsaken worgen problem","why clear silverpine","зачем убивать воргенов","проблема воргенов отрекшихся","зачем зачищать серебряный бор"}},{q="Как Аругал связан с этими созданиями?",a="Верховный маг Аругал призвал воргенов из иного измерения, чтобы сражаться с Плетью, находясь на службе в Даларане. Призванные твари одичали и довели Аругала до безумия от чувства вины, после чего он удалился в Крепость Темного Клыка, чтобы взращивать проклятие.",al={"how did worgen get here","arugal worgen connection","who summoned worgen","как воргены попали сюда","связь аругала с воргенами","кто призвал воргенов"}},{q="Что происходит после того, как вы проявите себя перед Даларом?",a="Когда вы докажете боевые навыки, убив белоскальпов, Далар Ткач Рассвета напрямую привлечет вас к своей кампании по уничтожению влияния Аругала через цепочку заданий «Безрассудство Аругала».",al={"next quest","what follows prove your worth","arugal's folly start","следующее задание","что после проявить себя","начало безрассудства аругала"}},{q="Участвует ли Альянс в этом задании?",a="Нет. «Проявить себя» — задание исключительно для Орды, его выдают на заставе Отрекшихся в Гробнице.",al={"can alliance do prove your worth","alliance silverpine","может ли альянс проявить себя","альянс серебряный бор"}}},fp="16,363,30.409.0,15.491.0,24.214.0,43.153.0,51.229.0,47.219.0,47.211.0,39.97.0"}
P.entries["quest:422"] = {n="Безрассудство Аругала",kw={"arugal","dalar dawnweaver","dusty spellbooks","kirin tor","remedy of arugal","sepulcher","silverpine","worgen","аругал","далар ткач рассвета","пыльные книги заклинаний","кирин-тор","зелье аругала","гробница","серебряный бор","воргены"},ang={["class:Mage"]="Для магов из числа Отрекшихся изучение трудов Аругала — наглядный урок о том, насколько губительной может стать магия, если применять ее без дисциплины и должной предусмотрительности.",["faction:Horde"]="Присутствие Орды в Серебряном бору оспаривают дикие твари; обезвредить Аругала необходимо для создания устойчивых линий снабжения из Лордерона.",["race:Undead"]="Серебряный бор — западный щит Подгорода. Отвоевать его у диких воргенов необходимо, чтобы защитить границы Темной Госпожи."},sec={{t="Насмешка мага",b="Далар Ткач Рассвета, честолюбивый маг из Отрекшихся, обитающий в склепах Гробницы, не питает уважения к верховному магу Аругалу. По мнению Ткача Рассвета, Аругал был посредственным чародеем, чье членство в Кирин-Торе вызывало недоумение, а познания в магии казались дилетантскими. Но чудовищных тварей, бродящих по Серебряному бору, нельзя игнорировать. Чтобы сломить власть Аругала над этим краем, Ткач Рассвета намерен разобрать заклинания, выпустившие воргенов на Лордерон."},{t="Остатки на ферме",b="Before seizing Shadowfang Keep, Arugal resided at a secluded wheat farm just north of the river bridge. Deathstalker scouts spotted discarded spellbooks preserved on the upper floor of the farmhouse, though lingering beasts prevented them from recovering the texts. Sifting through the dusty grimoires yields the incantation known as the Remedy of Arugal, revealing crucial insights into the unnatural curse spreading across Silverpine Forest."}},faq={{q="Кто такой Далар Ткач Рассвета?",a="Далар Ткач Рассвета — маг из числа Отрекшихся, расквартированный в Гробнице в Серебряном бору. Преданный Сильване Ветрокрылой, он стремится изучить и обратить против верховного мага Аругала его магические практики, чтобы отвоевать эти земли для Отрекшихся.",al={"dalar dawnweaver","who gives arugal's folly","sepulcher mage","далар ткач рассвета","кто дает безрассудство аругала","маг гробницы"}},{q="What is the Remedy of Arugal?",a="Это конкретное заклинание, записанное в брошенных книгах Аругала со времен, когда он жил на ферме к северу от моста. Далару Ткачу Рассвета нужно это заклинание, чтобы изучить магические основы работ Аругала.",al={"remedy of arugal","arugal's remedy","what is the book"}},{q="Где находятся старые книги заклинаний Аругала?",a="Пыльные книги заклинаний хранятся на верхнем этаже заброшенного фермерского дома на пшеничной ферме к северу от мостового перехода на севере Серебряного бора.",al={"where are the books","dusty spellbooks location","farmhouse books","где книги","пыльные книги заклинаний расположение","книги в доме на ферме"}},{q="Почему Ткач Рассвета смотрит на Аругала свысока?",a="Ткач Рассвета считает Аругала посредственным чародеем, чьи познания в магии были поверхностными и прозрачными. Он недоумевает, как Кирин-Тор вообще принял Аругала в свои ряды в Даларане.",al={"why dawnweaver hate arugal","dawnweaver opinion on arugal","почему ткач рассвета ненавидит аругала","мнение ткача рассвета об аругале"}},{q="Почему это задание важно для Отрекшихся?",a="Воргены, созданные Аругалом, убивают воинов Отрекшихся и угрожают их власти над Серебряным бором. Изучив его заклинания, Отрекшиеся надеются устранить угрозу и закрепить этот край за Темной Госпожой.",al={"forsaken interest in arugal","why do forsaken care about arugal","интерес отрекшихся к аругалу","почему отрекшихся волнует аругал"}},{q="Что происходит, если тронуть пыльные книги заклинаний?",a="Потревоженные гримуары привлекают воргена Лунной Ярости, затаившегося в доме. Он тут же нападает на любого, кто пытается рыться в оставленных Аругалом записях.",al={"spellbook trap","moonrage darkrunner attack","ловушка книг заклинаний","нападение воргена лунной ярости"}}},fp="14,388,17.472.0,25.443.1,24.235.0,29.220.0,42.159.0,40.202.0,43.209.0,49.169.0"}
P.entries["quest:423"] = {n="Безрассудство Аругала",s="Это задание отправляет агентов Отрекшихся добывать зачарованные кандалы у воргенов Лунной Ярости, бродящих по Серебряному бору. Далар Ткач Рассвета, изучая записи Аругала, хочет понять, как беглый маг искусственно укреплял свою нестабильную магию. Изучение этих оков приближает Отрекшихся к уничтожению угрозы воргенов в этом крае.",h="Это задание отправляет агентов Отрекшихся добывать зачарованные кандалы у воргенов Лунной Ярости, бродящих по...",kw={"arugal","dalar dawnweaver","dalaran","darksoul","glutton","kirin tor","sepulcher","shackles","silverpine","worgen","аругал","далар ткач рассвета","даларан","темнодух","обжора","кирин-тор","гробница","оковы","серебряный бор","воргены"},ang={["class:Mage"]="Маги из числа Отрекшихся оценят язвительную профессиональную критику Далара: Аругал восполнял шаткие магические основы, направляя силу через вещественные зачарованные оковы.",["faction:Horde"]="Зачистка лесов Серебряного бора обеспечивает безопасный проход по большой дороге, соединяющей Тирисфаль с южными землями.",["race:Undead"]="Для Отрекшихся защита Серебряного бора от диких воргенов необходима, чтобы уберечь южную границу Тирисфальских лесов и укрепить владения королевы Сильваны."},sec={{t="Лазейка шарлатана",b="Осмотрев найденные исследования Аругала, Далар Ткач Рассвета выражает полное презрение к бывшему собрату по ремеслу. По словам Далара, Аругал никогда не был достоин служить Даларану, а тем более заниматься высшим колдовством в самый тяжелый час королевства. Чтобы восполнить посредственный талант, Аругал полагался на зачарованные реликвии и снаряжение, усиливавшие и связывавшие призванных воргенов. Далару нужны образцы этих предметов, чтобы разобрать магическую нить, удерживающую чудовищ вместе."},{t="Оковы Лунной Ярости",b="Проклятые жители Серебряного бора, превращенные в воргенов Лунной Ярости, бродят по лесам, неся вещественные воплощения связующих чар Аругала. Обжоры Лунной Ярости и темнодухи Лунной Ярости рыщут к северу и востоку от Гробницы. Их тяжелые оковы, в металл которых вплетена остаточная магическая энергия, служат ценнейшими образцами для исследований Ткача Рассвета против Крепости Темного Клыка."}},faq={{q="Зачем Далару Ткачу Рассвета оковы воргенов?",a="Далар установил, что Аругал использовал зачарованные предметы, чтобы восполнить слабый магический талант. Изучив зачарованные оковы обжор и темнодухов Лунной Ярости, Далар надеется извлечь их магическую энергию и понять, как Аругал управляет своими тварями.",al={"why collect shackles","purpose of worgen shackles","dalar dawnweaver plan","зачем собирать оковы","назначение оков воргенов","план далара ткача рассвета"}},{q="Кем был Аругал до того, как сошел с ума в Серебряном бору?",a="Аругал был магом Даларана. По словам Далара Ткача Рассвета, в Кирин-Торе его считали посредственным талантом, но во время Третьей войны он прибегнул к запретному призыву из иных миров, чтобы выпустить воргенов против Плети.",al={"arugal backstory","who is arugal","arugal dalaran","прошлое аругала","кто такой аругал","аругал даларан"}},{q="Где найти обжор и темнодухов Лунной Ярости?",a="Эти свирепые воргены бродят в глуши к северу и востоку от Гробницы в Серебряном бору, рыская возле старых руин и лесных троп.",al={"where to find gluttons","darksoul location","worgen locations silverpine","где найти обжор","расположение темнодухов","воргены серебряный бор"}},{q="Почему Отрекшихся так беспокоит Аругал?",a="Воргены Аругала наводнили Серебряный бор и напрямую угрожают Гробнице и контролю Отрекшихся над землями к югу от Тирисфальских лесов. Обезвредить его магию необходимо, чтобы защитить северное королевство.",al={"forsaken worgen threat","why fight arugal","угроза воргенов отрекшимся","зачем бороться с аругалом"}},{q="Что Далар Ткач Рассвета думает о Даларане?",a="Далар питает горькое презрение к бывшим собратьям в Даларане и считает их глупцами за то, что они доверили Аругалу обязанности, с которыми он не мог справиться.",al={"dalar dalaran opinion","dalar on kirin tor","мнение далара о даларане","далар о кирин-торе"}},{q="Работает ли Аругал с Плетью?",a="Нет. Аругал изначально призвал воргенов, чтобы сражаться с Плетью и защитить Даларан. Но твари одичали и довели его до безумия, и он объявил Крепость Темного Клыка своими личными владениями.",al={"arugal scourge alliance","is arugal scourge","аругал плеть альянс","аругал за плеть"}}},fp="14,340,17.472.0,21.423.0,47.253.0,48.236.0,52.133.0,46.211.0,44.162.0,35.193.0"}
P.entries["quest:424"] = {n="Безрассудство Аругала",s="«Безрассудство Аругала» — ключевое задание в продолжающейся кампании Гробницы против влияния безумного верховного мага в Серебряном бору. Далар Ткач Рассвета поручает искателям приключений из Орды проникнуть в Серебряный рудник и казнить оскверненного бригадира Мрачнона Белесого, чтобы обеспечить войска Вариматраса ценными рудными запасами.",h="«Безрассудство Аругала» — ключевое задание в продолжающейся кампании Гробницы против влияния безумного...",kw={"arugal's folly","dalar dawnweaver","deep elem mine","grimson the pale","sepulcher","silverpine forest","varimathras","безрассудство аругала","далар ткач рассвета","серебряный рудник","мрачнон белесый","гробница","серебряный бор","вариматрас"},ang={["class:Mage"]="Изучение того, как неудержимые заклинания и превращения Аругала просочились в шахты, дает жуткий урок магической безрассудности.",["profession:Mining"]="Богатые подземные жилы Серебряного рудника привлекают всех в окрестных холмах: после уничтожения враждебных оскверненных рабочих здесь можно добывать ценную руду.",["race:Undead"]="Каждое стратегическое владение, отбитое у безумных рабов Аругала, дает Отрекшимся сырой металл для укрепления их юной страны против живых и Плети."},sec={{t="Захват глубин",b="Распутывая темные чары, которые верховный маг Аругал наслал на лес, Далар Ткач Рассвета получает срочные сведения от Отрекшихся темноловов. Дикая магия, распространяющаяся из Крепости Темного Клыка, добралась до Серебряного рудника в юго-восточных холмах и превратила шахтеров в одичавших несчастных. В руднике залегает ценная руда, необходимая для военных нужд Подгорода, но нынешние обитатели делают его совершенно непригодным."},{t="Отсеченная голова",b="В самом сердце зараженных штолен скрывается Мрачнон Белесый, оскверненный надсмотрщик, который управляет обезумевшими остатками шахтеров в подземных туннелях. Ткач Рассвета приказывает нанести немедленный обезглавливающий удар: если Мрачнон будет убит, а его голову доставят в Гробницу, разрозненные рабочие шахты утратят согласованность, и Отрекшиеся труженики смогут занять выработку для лорда Вариматраса."}},faq={{q="Кто такой Мрачнон Белесый?",a="Мрачнон Белесый — бригадир Серебряного рудника. Как и многие работники и жители юга Серебряного бора, он подпал под оскверняющее магическое влияние экспериментов верховного мага Аругала и превратился в уродливое существо, надзирающее за зараженным подземным логовом.",al={"grimson","who is grimson","deep elem foreman","мрачнон","кто такой мрачнон","бригадир серебряного рудника"}},{q="Где находится Серебряный рудник?",a="Серебряный рудник лежит в скалистых холмах к юго-востоку от Гробницы в Серебряном бору. Его туннели глубоко врезаются в склон холма и кишат проклятыми шахтерами и дикими тварями.",al={"deep elem mine location","where is deep elem","where to find grimson","где серебряный рудник","расположение серебряного рудника","где найти мрачнона"}},{q="Почему Вариматраса волнует добыча руды?",a="Вариматрас руководит стратегическим расширением власти Отрекшихся. Богатые ресурсы Серебряного рудника, такие как железо и камень, жизненно важны для вооружения войск и укрепления крепостей по всему Лордерону.",al={"why varimathras want mine","varimathras interest","зачем вариматрасу рудник","интерес вариматраса"}},{q="Что происходит после гибели Мрачнона?",a="Далар Ткач Рассвета забирает голову Мрачнона как доказательство победы и снова обращает внимание на главную угрозу, готовясь нанести удар прямо в средоточие надвигающегося влияния Аругала.",al={"after arugals folly 3","what next","next quest","после безрассудства аругала 3","что дальше","следующее задание"}},{q="Какая магия осквернила рудник?",a="Верховный маг Аругал выпустил в Серебряном бору дикую потустороннюю магию и проклятия воргенов. Эта оскверненная энергия проникла к подземным рабочим Серебряного рудника, свела их с ума и исказила их разум.",al={"arugals magic in mine","what corrupted deep elem","mine curse","магия аругала в руднике","что осквернило серебряный рудник","проклятие рудника"}},{q="Кто такие темноловы, о которых говорит Далар Ткач Рассвета?",a="Темноловы — тайная разведывательная служба армии Отрекшихся, действующая из таких застав, как Гробница, чтобы следить за передвижениями вражеских войск и местными аномалиями.",al={"darkstalkers","who are darkstalkers","темноловы","кто такие темноловы"}}},fp="14,310,19.434.0,16.381.0,24.267.0,36.167.0,51.201.0,36.180.0,38.201.0,55.192.0"}
P.entries["quest:425"] = {n="Ивар Нечистый",s="«Ивар Нечистый» — задание в Серебряном бору, завершающее разведывательную миссию Стражей смерти Ран и Квинна Йорика. Запертая на ферме, известной как Делянка Ивара, Ран просит путников из Орды уничтожить свирепого вурдалака Ивара Нечистого, чтобы Квинн мог оправиться от ран и завершить отчет для Верховного палача Хадрика.",h="«Ивар Нечистый» — задание в Серебряном бору, завершающее разведывательную миссию Стражей смерти Ран и Квинна...",kw={"deathstalkers","ghoul","hadrec","ivar","ivar patch","ivar the foul","quinn yorick","rane yorick","sepulcher","стражи смерти","вурдалак","хадрик","ивар","делянка ивара","ивар нечистый","квинн йорик","ран йорик","гробница"},ang={["class:Rogue"]="Помощь Стражам смерти показывает опасности скрытной разведки, когда вас застают врасплох голодные ужасы Плети.",["faction:Horde"]="Уничтожая остатки Плети, как Ивар, силы Орды защищают важные линии снабжения и стратегические земли для военных усилий Отрекшихся в Лордероне.",["race:Undead"]="Миссия подчеркивает опасный долг Стражей смерти и показывает, что одиноким разведчикам Отрекшихся, загнанным в угол за линией фронта, приходится полагаться на странствующих героев."},sec={{t="Сорванная миссия",b="Брат и сестра Ран и Квинн Йорик были отправлены Стражами смерти на разведку по Серебряному бору по поручению Верховного палача Хадрика в Гробнице. Их разведка внезапно и жестоко оборвалась, когда они шли через ферму в северной части леса: на них напал злобный вурдалак Ивар Нечистый."},{t="Угроза в амбаре",b="Хотя разведчикам удалось спастись, Квинн был сильно изувечен в схватке. Даже после лекарства из алхимических средств, приготовленного из лесных зверей, Квинн слишком слаб, чтобы идти. Зная, что Ивар бродит в соседнем амбаре и ждет, пока Ран ослабит бдительность, Ран призывает искателей приключений из Орды ворваться в амбар, отсечь Ивару голову и навсегда обезопасить усадьбу."}},faq={{q="Кто такой Ивар Нечистый?",a="Ивар Нечистый — опасный вурдалак Плети, обитающий на севере Серебряного бора. Он захватил ферму, ныне известную как Делянка Ивара, устраивает засады на прохожих и терзает разведчиков Отрекшихся.",al={"who is ivar","ivar the foul lore","what is ivar the foul","кто такой ивар","ивар нечистый предыстория","что такое ивар нечистый"}},{q="Где можно найти Ивара Нечистого?",a="Ивар скрывается в полуразвалившемся амбаре на Делянке Ивара, к северу от разрушенного фермерского дома, где укрылись Ран и Квинн Йорик.",al={"ivar location","where is ivar","ivar the foul barn","где ивар","местонахождение ивара","амбар ивара нечистого"}},{q="Кто такие Ран и Квинн Йорик?",a="Ран и Квинн Йорик — Отрекшиеся брат и сестра, Стражи смерти. Верховный палач Хадрик отправил их составить карту и изучить действия врага в Серебряном бору, но их подстерег Ивар.",al={"who is rane yorick","yorick brothers","who is quinn yorick","кто такая ран йорик","брат и сестра йорик","кто такой квинн йорик"}},{q="Почему Ран просит искателя приключений убить Ивара?",a="Квинн был тяжело изувечен при первой встрече и все еще выздоравливает. Ран должна оставаться рядом с братом и защищать его от внезапных нападений Плети, поэтому сама выследить вурдалака она не может.",al={"why kill ivar","why doesn't rane fight","зачем убивать ивара","почему ран не сражается"}},{q="Кто получает отчет о смерти Ивара?",a="Верховный палач Хадрик, военачальник в Гробнице в Серебряном бору, получает официальные журналы разведчиков, в которых Ран обещает отметить помощь искателя приключений.",al={"who is hadrec","who sent the yoricks","кто такой хадрик","кто послал йориков"}},{q="Что происходит после гибели Ивара?",a="Убийство Ивара Нечистого завершает испытание Стражей смерти на Делянке Ивара. Когда непосредственная угроза устранена, у Квинна появляется время исцелиться, прежде чем брат и сестра закончат осмотр леса.",al={"what next after ivar","quest after ivar","что после ивара","задание после ивара"}}},fp="13,362,18.349.0,22.391.0,21.202.0,33.149.0,30.219.0,45.228.0,40.204.0,33.200.1"}
P.entries["quest:426"] = {n="Нападение на мельницы",s="По поручению Стража смерти Диллинжера в Брилле солдаты Отрекшихся должны сломить опору Плети у близлежащих Мельниц Агамондов. Безмозглая нежить собирается среди разрушенных ветряных мельниц и грозит создать передовую базу опасно близко к поселениям Тирисфальских лесов. Чтобы остановить это, новобранцам нужно разгромить ряды скелетов-солдат и костяных чародеев.",h="По поручению Стража смерти Диллинжера в Брилле солдаты Отрекшихся должны сломить опору Плети у близлежащих...",kw={"agamand mills","blackened skulls","brill","darkeye bonecaster","deathguard dillinger","notched ribs","scourge","the mills overrun","tirisfal glades","мельницы агамондов","почерневшие черепа","брилл","костяной чародей темного глаза","страж смерти диллинжер","зазубренные ребра","плеть","нападение на мельницы","тирисфальские леса"},ang={["class:Warrior"]="Схватка с бронированными скелетами на Мельницах Агамондов — суровое боевое испытание против неумолимых врагов, не чувствующих боли и не знающих пощады.",["faction:Horde"]="Удержание Тирисфальских лесов крайне важно для сохранения единственного плацдарма Орды на севере Лордерона, поэтому уничтожение плацдармов Плети — тактический приоритет.",["race:Undead"]="Для Отрекшихся изгнание Плети с Мельниц Агамондов — личное дело: так они защищают свои новые суверенные земли и громят безмозглых рабов Короля-лича, державших их в оковах."},sec={{t="Нависшая угроза мельницам",b="Мельницы Агамондов когда-то были сельскохозяйственным сердцем Тирисфальских лесов, но после Третьей войны их ветряки возвышаются над куда более мрачной жатвой. Силы Плети, подчиненные Королю-личу, начали стягиваться на эти земли. Если безмозглые рабы захватят мельницы, у них появится укрепленная база, откуда можно углубиться в Тирисфаль и ударить прямо по молодым владениям Отрекшихся."},{t="Доказательство уничтожения",b="Страж смерти Диллинжер не тратит время на сантименты. Отвечая за укрепление Брилла и охрану территории, Диллинжер приказывает новобранцам выследить гремящих скелетов и солдат с расколотыми черепами, а также костяных чародеев Темного Глаза. Требуя зазубренные ребра и почерневшие черепа как доказательство уничтожения, Диллинжер следит, чтобы скелеты были физически разбиты, а безмозглые остатки отброшены к Чумным землям до начала наступления."}},faq={{q="Почему Плеть собирается у Мельниц Агамондов?",a="Плеть пытается создать передовой плацдарм на западе Тирисфаля. Если она закрепится на Мельницах Агамондов, то сможет устраивать согласованные набеги вглубь лесов и напрямую угрожать ближайшим поселениям Отрекшихся, таким как Брилл.",al={"why agamand mills","scourge at the mills","why the mills","почему мельницы агамондов","плеть на мельницах","почему мельницы"}},{q="Кто такой Страж смерти Диллинжер?",a="Страж смерти Диллинжер — часовой Отрекшихся, расквартированный в Брилле. Он координирует тактические удары по местным угрозам в Тирисфальских лесах, особенно по наступающей Плети и враждебным стаям гноллов, угрожающим дороге.",al={"deathguard dillinger lore","who is dillinger","dillinger brill","страж смерти диллинжер","кто такой диллинжер","диллинжер брилл"}},{q="Где находятся Мельницы Агамондов?",a="Мельницы Агамондов расположены к северу от главной западной дороги в Тирисфальских лесах. Если идти на запад от Брилла через мост и свернуть на северную развилку, вы выйдете прямо к заметным разрушенным ветрякам.",al={"where is agamand mills","mills location","how to get to the mills","где мельницы агамондов","расположение мельниц","как добраться до мельниц"}},{q="Зачем Диллинжеру ребра и черепа?",a="Диллинжеру нужно осязаемое доказательство того, что передовая Плети разбита. Зазубренные ребра скелетов-пехотинцев и почерневшие черепа костяных чародеев подтверждают, что отряд разгромлен и истреблен.",al={"notched ribs blackened skulls","why ribs and skulls","зазубренные ребра почерневшие черепа","зачем ребра и черепа"}},{q="Каковы отношения между Отрекшимися и Плетью?",a="Отрекшиеся — нежить, освободившаяся от умственного господства Короля-лича. Плеть остается безмозглыми послушными рабами воли Короля-лича и стремится уничтожить Отрекшихся и вернуть Лордерон своему хозяину.",al={"forsaken vs scourge","why fight other undead","отрекшиеся и плеть","почему сражаться с другой нежитью"}},{q="Что будет после зачистки этих сил Плети?",a="Уничтожение пехоты — лишь первый ход против заразы на Мельницах Агамондов. Диллинжер и Стражи смерти продолжают продвигаться вглубь мельниц, чтобы расправиться с остающимися там командирами и темными силами.",al={"what comes next","after the mills overrun","что дальше","после нападения на мельницы"}}},fp="17,379,29.436.0,20.469.0,47.249.0,28.232.0,36.199.0,40.228.0,67.234.0,42.239.0"}
P.entries["quest:427"] = {n="Война с Алым орденом",s="Палач Зуганд в Брилле руководит походом Отрекшихся против Алого ордена в Тирисфальских лесах. По сведениям, добытым Палачом Арреном, вас отправляют уничтожить алых воинов, стоящих в сторожевой башне к западу от Фермы Соллидена. Этот штурм — первое наступление войск Отрекшихся, призванное изгнать рьяных крестоносцев из их владений.",h="Палач Зуганд в Брилле руководит походом Отрекшихся против Алого ордена в Тирисфальских лесах.",kw={"brill","deathguard","scarlet crusade","scarlet warriors","solliden farmstead","sylvanas","tirisfal glades","zygand","брилл","страж смерти","стражи смерти","алый орден","алые воины","ферма соллидена","сильвана","тирисфальские леса","зуганд"},ang={["faction:Horde"]="Создание безопасной границы вокруг Тирисфальских лесов и Подгорода необходимо, чтобы Орда получила постоянный плацдарм в Восточных королевствах.",["race:Undead"]="Для Отрекшихся Алый орден — горькая ирония: это живые бывшие соотечественники, которые клеймят их чудовищами и стремятся истребить, вместо того чтобы скорбеть о трагическом падении Лордерона."},sec={{t="Война на два фронта",b="Молодое государство Отрекшихся под началом леди Сильваны Ветрокрылой сталкивается с угрозами сразу на нескольких фронтах. Пока Стражи смерти настороженно следят за растущими армиями Короля-лича, фанатичные смертные из Алого ордена оспаривают власть Отрекшихся над их бывшей родиной. Орден считает всю нежить мерзостью, которую нужно уничтожить огнем и клинком, не замечая, что Отрекшиеся освободились от власти Плети."},{t="Удар по западному форпосту",b="Благодаря разведывательным документам, добытым Палачом Арреном в Могильнике, Палач Зуганд теперь точно знает, где расположены лагеря и форпосты фанатиков в Тирисфальских лесах. Поскольку обычные гарнизоны Стражей смерти заняты сдерживанием Плети, для прямого удара привлекают независимых бойцов Отрекшихся. Первый удар направлен на сторожевую башню к западу от Фермы Соллидена, где собираются алые воины и угрожают западным подступам к Бриллу."}},faq={{q="Почему Алый орден враждебен к Отрекшимся?",a="Алый орден — экстремистское человеческое братство, цель которого — истребление нежити. Он не делает различия между безвольной Плетью, которой управляет Король-лич, и свободными Отрекшимися, верными леди Сильване: любое существо из нежити для него — зараженное чумой чудовище, которое надо сжечь.",al={"why scarlet hate undead","scarlet crusade motivation","why are they attacking","почему алый орден ненавидит нежить","мотивы алого ордена","почему они нападают"}},{q="Кто такой Палач Зуганд?",a="Палач Зуганд — старший военный офицер Стражей смерти Отрекшихся в Брилле. Он руководит тактическим развертыванием сил, защищает дороги вокруг подступов к столице и руководит наступательными ударами против ближайших сил Алого ордена и Плети.",al={"who is zygand","brill quest giver executor","zygand lore","кто такой зуганд","палач в брилле","зуганд предания"}},{q="Как Отрекшиеся получили сведения о позициях Алого ордена?",a="Важные тактические документы добыли новобранцы Палача Аррена в Могильнике. В них описаны маршруты патрулей, форпосты и лагеря Алого ордена по всему Тирисфалю, и Палач Зуганд получил сведения, нужные для организации точечных контрударов.",al={"scarlet documents","arren intelligence","how did they find the tower","документы алого ордена","сведения аррена","как нашли башню"}},{q="Где находятся алые воины?",a="Алые воины удерживают оборонительную башню к западу от Фермы Соллидена, в западной сельской местности Тирисфальских лесов.",al={"scarlet warrior location","where is the tower","solliden farmstead tower","где алые воины","где башня","башня фермы соллидена"}},{q="Почему Стражи смерти не разбираются с орденом сами?",a="Регулярные силы Стражей смерти растянуты на наблюдение за Плетью, чьи войска растут с каждой ночью под влиянием Короля-лича. Поскольку обычных солдат нельзя отвлечь от сдерживания, Зуганд полагается на честолюбивых вольных бойцов, которые уничтожают членов ордена.",al={"why send players","where is the deathguard","why help zygand","зачем посылают игроков","где стражи смерти","зачем помогать зуганду"}},{q="Положит ли это задание конец присутствию Алого ордена в Тирисфале?",a="Нет. Нападение на западную сторожевую башню — лишь первый удар в кампании из четырех частей, которой руководит Палач Зуганд, чтобы уничтожить командование и форпосты Алого ордена в этих землях.",al={"is this the last scarlet quest","scarlet crusade quest chain","последнее ли это задание против алого ордена","цепочка заданий алого ордена"}}},fp="31,374,15.451.0,28.465.0,55.294.0,23.263.0,59.270.0,39.141.0,55.272.0,55.181.0"}
P.entries["quest:428"] = {n="Пропавшие стражи смерти",s="«Пропавшие стражи смерти» — разведывательное задание, которое дает Верховный палач Хадрик в Гробнице. Два разведчика Отрекшихся, Ран и Квинн Йорик, пропали несколько недель назад при осмотре заброшенных ферм на севере Серебряного бора. Поиски раскрывают не только их судьбу, но и опасности, угрожающие власти Отрекшихся в этом краю.",h="«Пропавшие стражи смерти» — разведывательное задание, которое дает Верховный палач Хадрик в Гробнице.",kw={"deathstalkers","hadrec","quinn yorick","rane yorick","reconnaissance","scourge","sepulcher","silverpine","стражи смерти","хадрик","квинн йорик","ран йорик","разведка","плеть","гробница","серебряный бор"},ang={["class:Rogue"]="Йорики — собратья по ремеслу теней. Вид опытных Стражей смерти, прижатых к земле, резко напоминает, что одной скрытности недостаточно, чтобы выжить среди северных ужасов.",["faction:Horde"]="Удержание Серебряного бора обеспечивает безопасный путь между Подгородом и южными землями Лордерона, поэтому подобная разведка критически важна для безопасности Орды.",["race:Undead"]="Агенты Отрекшихся знают: каждый пропавший соратник — возможная брешь в их хрупкой обороне Серебряного бора. Спасая своих, они оберегают Гробницу от внезапного нападения."},sec={{t="Тишина с севера",b="Стражи смерти служат глазами, ушами и скрытыми кинжалами леди Сильваны и Отрекшихся. Когда агенты умолкают, командование это замечает. Верховный палач Хадрик несколько недель назад отправил разведчиков Ран и Квинна Йориков на север Серебряного бора наблюдать за заброшенными фермами и следить за движениями врага. Не получив ни гонца, ни донесения с момента их ухода, Хадрик опасается, что двое нашли мрачный конец от рук Плети или чего похуже."},{t="Северная опасность",b="Север Серебряного бора полон опасностей: он лежит между разоренными поместьями Лордерона и сумрачными границами Тирисфальских лесов. Бродячая нежить, хищные звери и дикие воргены делают путь без сопровождения опасным даже для опытных разбойников. Чтобы найти Йориков, нужно обыскать ветхие северные фермы, где началась их разведка, в надежде добыть сведения, собранные ими до того, как опасность настигла их."},{t="В ловушке теней",b="Идя по их следу, вы обнаруживаете, что Ран и Квинн Йорик живы, хотя едва сохраняют свободу. Они спаслись от нападения вурдалака Ивара Нечистого, но Квинна сильно изувечили, и теперь Стражи смерти загнаны в угол на ферме, а вурдалак бродит неподалеку. Их спасение глубже втягивает Отрекшихся в борьбу с дикими угрозами у самой дороги."}},faq={{q="Кто такие Ран и Квинн Йорик?",a="Ран и Квинн Йорик — два разведчика Отрекшихся из Стражей смерти, разведывательно-диверсионного крыла Отрекшихся. Их отправили на север Серебряного бора наблюдать за местными фермами, после чего они пропали.",al={"who are the yoricks","who are the lost deathstalkers","rane and quinn lore","кто такие йорики","кто такие пропавшие стражи смерти","ран и квинн предания"}},{q="Почему Верховный палач Хадрик беспокоится о них?",a="Хадрик руководит военными операциями Отрекшихся из Гробницы. Потеряв связь с двумя важными разведчиками, Отрекшиеся остаются слепы к враждебным действиям на северных границах, особенно с учетом близости Плети.",al={"why hadrec care","who sent the yoricks","hadrec lost scouts","почему хадрик беспокоится","кто послал йориков","пропавшие разведчики хадрика"}},{q="Где пропали Йорики?",a="Они исчезли при разведке на севере Серебряного бора. Их маршрут проходил по разбросанным ветхим фермам к северу от Гробницы.",al={"where are the deathstalkers","yorick location","where to find rane and quinn","где стражи смерти","где йорики","где найти рана и квинна"}},{q="Какие угрозы ждут Стражей смерти на севере Серебряного бора?",a="Север Серебряного бора наводнен бродячими остатками Плети, свирепыми хищниками и неестественными воргенами в лесах — все они смертельно опасны для одиноких разведчиков.",al={"what happened to them","silverpine dangers","why did they go missing","что с ними случилось","опасности серебряного бора","почему они пропали"}},{q="Что происходит после того, как пропавшие Стражи смерти найдены?",a="Когда вы находите Ран Йорик, появляется срочная задача — помочь израненным разведчикам оправиться в задании «Звериные сердца», которое ведет к схватке с местными угрозами, например с Иваром Нечистым.",al={"what is the next quest","after lost deathstalkers","quest chain after yorick","следующее задание","после пропавших стражей смерти","цепочка заданий после йорик"}},{q="Что представляют собой Стражи смерти как организация?",a="Стражи смерти — главная гильдия шпионажа, разведки и убийств Отрекшихся, тайный авангард Темной Госпожи в Лордероне.",al={"what are deathstalkers","deathstalker order","forsaken assassins","кто такие стражи смерти","орден стражей смерти","убийцы отрекшихся"}}},fp="18,356,24.446.0,18.446.0,22.389.1,30.233.0,49.246.0,32.162.0,62.175.0,53.178.1,45.164.0"}
P.entries["quest:429"] = {n="Звериные сердца",s="«Звериные сердца» — задание Орды в Серебряном бору, которое дает Ран Йорик. Чтобы спасти брата Квинна от ран, нанесенных вурдалаком Иваром Нечистым, вы должны добыть бесцветные сердца воргов и доставить их аптекарю Ренферрелу в Гробницу для алхимического снадобья.",h="«Звериные сердца» — задание Орды в Серебряном бору, которое дает Ран Йорик.",kw={"apothecary renferrel","discolored worg heart","ivar the foul","maldens orchard","quinn yorick","rane yorick","sepulcher","silverpine forest","wild hearts","аптекарь ренферрел","бесцветное сердце ворга","ивар нечистый","сад мальдена","квинн йорик","ран йорик","гробница","серебряный бор","звериные сердца"},ang={["class:Rogue"]="Вид опытных Стражей смерти, сраженных свирепым вурдалаком, мрачно напоминает о скрытности и смертоносности, необходимых, чтобы выжить в глуши Лордерона.",["race:Undead"]="Задание подчеркивает практичную безжалостность Отрекшихся: даже в братских узах выживание зависит от добытых органов и холодной алхимической науки, а не от божественной милости."},sec={{t="A Brother's Desperation",b="После неудачной вылазки, из-за которой Стражи смерти застряли на ферме на севере Серебряного бора, Ран Йорик ухаживает за тяжело раненным братом Квинном. Свирепый вурдалак Ивар Нечистый изувечил Квинна, и тот не поправляется. Понимая, что обычный отдых не восстановит мертвое тело, разорванное с такой жестокостью, Ран обращается к мрачному искусству Королевского фармацевтического общества, чтобы собрать брата заново."},{t="Алхимия земель, оскверненных Плетью",b="Волки Серебряного бора не избежали темной порчи, терзающей север Лордерона. У местных воргов испорченные, обесцвеченные сердца, содержащие особенно сильные эссенции. Хотя обычному взгляду они отвратительны, аптекари Королевского общества научились перегонять эти зараженные органы в составы, способные оживить иссохшую плоть Отрекшихся."},{t="Холодный долг Ренферрела",b="Аптекарь Ренферрел, находящийся в Гробнице, воспринимает случившееся с досадой, а не сочувствием. Леди Сильвана Ветрокрылая лично поручила ему срочные исследования, и Ренферрел возмущается тем, что Королевское фармацевтическое общество считают полевыми лекарями для неловких разведчиков. Тем не менее он принимает жуткие ингредиенты и готовит снадобье, чтобы агенты Темной Госпожи оставались в строю."}},faq={{q="Почему Квинну Йорику для исцеления нужны сердца воргов?",a="Тело Отрекшихся исцеляется не так, как у живых. Получив тяжелые раны от вурдалака Ивара Нечистого, Квинн нуждается в особой алхимической помощи. Королевское фармацевтическое общество использует зараженные, обесцвеченные сердца воргов Серебряного бора для приготовления укрепляющих настоев, подходящих для тканей нежити.",al={"why worg hearts","quinn healing","healing potion recipe","зачем сердца воргов","исцеление квинна","рецепт лечебного зелья"}},{q="Где найти бесцветные сердца воргов?",a="Ворги бродят по лесам центральной части Серебряного бора, особенно в диких местах между дорогой, где застряли Йорики, и Садом Мальдена на востоке.",al={"where are the worgs","worg locations silverpine","worg heart farming","где ворги","места воргов серебряный бор","добыча сердец воргов"}},{q="Кто такой Ивар Нечистый?",a="Ивар Нечистый — опасный вурдалак, затаившийся на ферме, где укрылись Йорики. Он напал на Ран и Квинна Йориков во время разведки, и хотя оба спаслись, Квинна он тяжело изувечил.",al={"who is ivar","ivar the foul lore","ghoul ivar","кто такой ивар","ивар нечистый предания","вурдалак ивар"}},{q="Почему аптекарь Ренферрел недоволен этим поручением?",a="Аптекарь Ренферрел находится в Гробнице по прямому приказу Сильваны Ветрокрылой, чтобы продвигать важные исследования чумы. Он считает провал разведывательных заданий Стражей смерти позором и лишним отвлечением от своих более значительных алхимических опытов.",al={"why is renferrel mad","renferrel dialogue","renferrel's attitude","почему ренферрел зол","диалог ренферрела","отношение ренферрела"}},{q="Что происходит после передачи сердец Ренферрелу?",a="Когда Ренферрел обработает обесцвеченные сердца, он отправляет вас обратно к Ран и Квинну Йорикам с укрепляющим зельем, чтобы Квинн смог достаточно оправиться и отомстить.",al={"next quest after wild hearts","what to do with the potion","следующее задание после звериных сердец","что делать с зельем"}},{q="Почему Стражам смерти нужна помощь искателя приключений?",a="Ран Йорик не может покинуть брата из-за тяжести ран Квинна и опасности новых засад со стороны бродячей Плети и зверей. Она полагается на проходящих мимо путников Орды, чтобы они добыли органы и доставили просьбу в Гробницу.",al={"why can't rane get the hearts","deathstalker failure","почему ран не может достать сердца","неудача стражей смерти"}}},fp="11,272,23.436.0,36.339.0,21.397.1,47.300.0,46.193.0,21.198.0,48.277.0,50.171.1,54.250.0"}
P.entries["quest:430"] = {n="Назад к Квинну",s="«Назад к Квинну» — задание Орды в Серебряном бору: герой доставляет укрепляющее снадобье, приготовленное аптекарем Ренферрелом, раненому Стражу смерти Квинну Йорику. Квинн, ослабевший и оказавшийся в ловушке на Делянке Ивара к северу от Гробницы, нуждается в снадобье, прежде чем сможет думать о возвращении к службе.",h="«Назад к Квинну» — задание Орды в Серебряном бору: герой доставляет укрепляющее снадобье, приготовленное...",kw={"apothecary renferrel","deathstalker erland","deathstalkers","ivar patch","quinn yorick","quinn's potion","sepulcher","silverpine forest","аптекарь ренферрел","страж смерти эрланд","стражи смерти","делянка ивара","квинн йорик","зелье квинна","гробница","серебряный бор"},ang={["class:Rogue"]="Помощь собратьям из Стражей смерти показывает опасную сторону разведки, когда на разведчиков внезапно нападают стайные хищники.",["faction:Horde"]="Спасение разведчиков, застрявших за линией фронта, крайне важно для укрепления позиций Орды в Серебряном бору против диких стай воргенов.",["race:Undead"]="Это задание показывает практическую пользу Королевского фармацевтического общества, которое снабжает необходимыми укрепляющими смесями разведчиков Темной Госпожи, чтобы они могли действовать во враждебных землях."},sec={{t="Горькое снадобье",b="После сбора сердец диких зверей для Королевского фармацевтического общества аптекарь Ренферрел в Гробнице варит укрепляющее зелье, призванное помочь Квинну Йорику. У Ренферрела нет времени на сантименты и обходительность: он быстро передает смесь и возвращается к своим тайным алхимическим исследованиям, а герою приходится снова бежать с поручением в глушь."},{t="Передышка на Делянке Ивара",b="Квинн Йорик прячется вместе с сестрой, Стражем смерти Ран Йорик, среди разрушенной фермы, известной как Делянка Ивара. Тяжело раненный вурдалаком Иваром Нечистым и неспособный идти по вражеской земле, Квинн выпивает снадобье сразу по прибытии героя. Хотя смесь возвращает ему достаточно сил, чтобы со временем отправиться в путь, окрестности по-прежнему полны опасностей, особенно из-за злобного надзора вурдалака, затаившегося неподалеку."}},faq={{q="Где находится Квинн Йорик?",a="Квинн Йорик укрывается на Делянке Ивара — заброшенной ферме к северу от Гробницы, на западных утесах Серебряного бора.",al={"where is quinn","quinn yorick location","ivar patch location","где квинн","где находится квинн йорик","где делянка ивара"}},{q="Кто приготовил зелье для Квинна?",a="Зелье сварил аптекарь Ренферрел, алхимик Королевского фармацевтического общества, работающий в склепах Гробницы. Для него он использовал сердца диких зверей, собранные в лесу.",al={"who brewed the potion","apothecary renferrel potion","кто сварил зелье","зелье аптекаря ренферрела"}},{q="Почему Квинн не мог двигаться самостоятельно?",a="Вурдалак Ивар Нечистый напал на Квинна из засады и сильно изувечил его, когда тот разведывал местность с сестрой. Квинн оказался беспомощным и зависел от сестры Ран и лекарств.",al={"why is quinn stuck","quinn yorick injured","почему квинн не может идти","квинн йорик ранен"}},{q="Что происходит после передачи зелья Квинну?",a="Выпитое снадобье возвращает Квинну силы, и он может нанести ответный удар Ивару Нечистому — опасному вурдалаку, угрожающему их убежищу.",al={"what next after return to quinn","next quest after quinn","что дальше после назад к квинну","следующее задание после квинна"}},{q="Кто сестра Квинна?",a="Сестра Квинна — Страж смерти Ран Йорик. Она осталась рядом с ним на Делянке Ивара, чтобы защищать его и обеспечивать их выживание.",al={"quinn yorick sister","quinn sister","сестра квинна йорика","сестра квинна"}},{q="Заботит ли аптекаря Ренферрела судьба Квинна?",a="Ренферрел почти не проявляет личного участия: для него снадобье — лишь поручение. Он отпускает героя и возвращается к своим тайным исследованиям для Королевского фармацевтического общества.",al={"does renferrel care","renferrel attitude","заботится ли ренферрел","отношение ренферрела"}}},fp="15,315,16.399.0,25.448.0,30.150.0,30.177.0,40.192.0,43.151.1,22.130.0,50.195.0"}
P.entries["quest:431"] = {n="Манящие свечи",s="«Манящие свечи» — короткое задание: нужно собрать особые ритуальные свечи, найденные в Тирисфальских лесах. Эти жуткие сальные свечи пропитаны темными обрядами, и их забирают прямо из ящиков, оставленных в тени руин Лордерона.",h="«Манящие свечи» — короткое задание: нужно собрать особые ритуальные свечи, найденные в Тирисфальских лесах.",kw={"candles of beckoning","crate of candles","forsaken","occult","ritual taper","tirisfal glades","undercity","манящие свечи","ящик со свечами","отрекшиеся","оккультизм","ритуальная свеча","тирисфальские леса","подгород"},ang={["class:Priest"]="Жрецы тьмы понимают, какая осторожность требуется при обращении с предметами, созданными для вызова задержавшихся духов и незримых сущностей.",["class:Warlock"]="Знатоки темных искусств сразу узнают особое сало и магический отклик, свойственные ритуальным манящим свечам.",["race:Undead"]="Для Отрекшихся сбор оккультных предметов в Тирисфале — вопрос и выживания, и изучения: опасные артефакты не должны попасть во вражеские руки."},sec={{t="Сало и темные обряды",b="The crate on Gunther's Retreat supplies the Candle of Beckoning used in his test of allegiance. Gunther asks an adventurer to take a candle to the old, bloody altar just off the island's southern coast, light it, and confront the Scourge agent Lillith Nefara."},{t="Возвращенная реликвия",b="Ящик с этими свечами стоит в Приюте Гюнтера — на острове в Озере Ясноводном, где обитает лич Гюнтер Чародей. Для испытания, которое Гюнтер задает в задании «Доказательство преданности», нужна всего одна свеча: зажженная на старом окровавленном алтаре у южного берега острова, она пробуждает агента Плети Лилит Нефару."}},faq={{q="Для чего нужны Манящие свечи?",a="A Candle of Beckoning is lit on the bloody altar near Gunther's Retreat to awaken Lillith Nefara for Gunther's test of allegiance.",al={"what are candles of beckoning","purpose of candles","what do candles do","что такое манящие свечи","для чего нужны свечи","что делают свечи"}},{q="Где можно найти эти свечи?",a="Они хранятся в ящике со свечами в Приюте Гюнтера — на острове Гюнтера Чародея в Озере Ясноводном в Тирисфальских лесах.",al={"where to find candles of beckoning","candle crate location","crate of candles","где найти манящие свечи","где ящик со свечами","ящик со свечами"}},{q="Кто изготовил эти свечи?",a="The source does not name their maker. Gunther keeps a crate of candles on his island for the test he sets in Proving Allegiance.",al={"who made candles of beckoning","candle creator","who made the crate","кто сделал манящие свечи","создатель свечей","кто сделал ящик"}},{q="Зачем Орде или Отрекшимся эти свечи?",a="Одна свеча нужна для испытания Гюнтера Чародея в задании «Доказательство преданности». Зажженная на окровавленном алтаре у южного берега его острова, она пробуждает агента Плети Лилит Нефару, и ее уничтожение доказывает, что вы — враг Короля-лича.",al={"why forsaken need candles","why retrieve candles","why horde candles","зачем отрекшимся свечи","зачем забирать свечи","зачем орде свечи"}},{q="Может ли любой воспользоваться свечой?",a="Манящую свечу ставят на окровавленный обеденный стол Лиллит и зажигают, чтобы призвать ее для испытания Гюнтера.",al={"can i light it","how to use candle","use candle of beckoning","можно ли зажечь","как использовать свечу","использовать манящую свечу"}},{q="Связаны ли свечи с Плетью?",a="The candle awakens Lillith Nefara, a powerful Scourge agent. Gunther asks you to destroy her to prove you are the Lich King's enemy.",al={"is this scourge magic","are candles scourge","scourge cult candles","это магия плети","связаны ли свечи с плетью","свечи культа плети"}}},fp="20,256,21.259.0,17.324.0,48.130.0,30.124.0,26.128.0,41.225.0,31.108.0,38.132.0"}
P.entries["quest:432"] = {n="Проклятые трогги!",s="Штейгер Камнелоб в отчаянии: трогги полностью захватили его работы в Карьере Гол'Болар. Свирепые и агрессивные твари разгромили его горное оборудование и бочки с порохом, и он в ярости требует мести. Сам он сражаться не может из-за слабеющего зрения и меткости, поэтому платит отважным героям, чтобы они спустились в карьер и истребили грубых Головолов.",h="Штейгер Камнелоб в отчаянии: трогги полностью захватили его работы в Карьере Гол'Болар.",kw={"dun morogh","gol'bolar","powder","quarry","rockjaw","skullthumper","stonebrow","troggs","дун морог","гол'болар","порох","карьер","каменные челюсти","головол","камнелоб","трогги"},ang={["profession:Mining"]="Карьер Гол'Болар — важная дворфийская каменоломня и рудник. Изгнание захватчиков — первый шаг к тому, чтобы кирки снова заработали.",["race:Dwarf"]="Нашествие троггов в Каз Модане задевает каждого дворфа за живое. Видя, как бездумные трогги изгнали каменотесов Гол'Болара, вы воспринимаете месть в карьере как личное дело."},sec={{t="Хаос в карьере",b="Карьер Гол'Болар был гордым и прибыльным дворфийским разрезом в заснеженных холмах восточного Дун Морога. Процветание закончилось внезапно, когда подземные трогги прорвались сквозь породу и заполонили нижние уступы. Дикари не просто заняли туннели — они устроили безудержный разгром, ломая леса и взрывая драгоценные бочки со взрывчатым порохом."},{t="Кипящая ярость Камнелоба",b="Наблюдая с безопасного гребня за гибелью дела всей своей жизни, Штейгер Камнелоб дошел до грани удара. Раздосадованный старческими руками и плохой меткостью, он надеется на странников и новобранцев Альянса, которые осуществят его жажду мести. Сокращение рядов крепких Головолов из племени Каменных Челюстей приносит ему краткое облегчение, но удовлетворить его гнев может лишь полное истребление."}},faq={{q="Где находится Карьер Гол'Болар?",a="Карьер Гол'Болар расположен в восточном Дун Мороге, к югу от главной дороги, ведущей на восток к вратам Лок Модана. Штейгер Камнелоб стоит на краю, над зараженными троггами выработками.",al={"gol'bolar location","where is the quarry","stonebrow location","где гол'болар","где карьер","где камнелоб"}},{q="Почему трогги нападают на карьер?",a="Трогги живут глубоко под землей по всему Каз Модану. Дворфийские выработки часто вскрывают подземные пещеры с гнездами троггов, и те яростно устремляются на поверхность, быстро захватывая действующие шахты.",al={"why troggs here","trogg invasion reason","почему здесь трогги","причина нашествия троггов"}},{q="Кто такой Штейгер Камнелоб?",a="Штейгер Камнелоб — дворф-надзиратель Карьера Гол'Болар. Озлобленный, вспыльчивый и обеспокоенный угасающими боевыми навыками, он направляет всех желающих бойцов на уничтожение троггов.",al={"stonebrow","who gives quest","камнелоб","кто выдает задание"}},{q="Кто такой Головол из племени Каменных Челюстей?",a="Головолы из племени Каменных Челюстей — грубые бойцы передовой у троггов, занявших Карьер Гол'Болар. Они полагаются на физическую силу и примитивные дубины, чтобы крушить чужаков.",al={"skullthumper","skullthumpers","головол","головолы"}},{q="Почему Камнелоб не может сам очистить карьер?",a="Камнелоб признает, что зрение и меткость уже не те, что в молодости. Из-за возраста он предпочитает нанять героев, а не рисковать быть сокрушенным в выработках карьера.",al={"why doesn't stonebrow fight","почему камнелоб не сражается"}},{q="Что трогги разрушают в карьере?",a="Помимо нарушения горных работ, трогги активно ломают тяжелое оборудование и взрывают припасы, в том числе драгоценные бочки с дворфийским порохом.",al={"trogg destruction","what are troggs breaking","разрушения троггов","что ломают трогги"}}},fp="21,380,19.389.0,24.414.0,26.196.0,40.201.0,25.198.0,31.181.0,45.201.0,45.165.0"}
P.entries["quest:433"] = {n="Слуга народа",s="Сенатор Мер Каменная Реликвия из Стальгорна лично прибыл в Карьер Гол'Болар, чтобы справиться с внезапным вторжением троггов, угрожающим горным работам Дун Морога. Желая вернуть карьер, он нанимает героев для истребления агрессивных Костоломов из племени Каменных Челюстей, чтобы шахтеры могли вернуться к работе.",h="Сенатор Мер Каменная Реликвия из Стальгорна лично прибыл в Карьер Гол'Болар, чтобы справиться с внезапным...",kw={"bonesnapper","dun morogh","gol'bolar","quarry","rockjaw","senate","stonehallow","trogg","костолом","дун морог","гол'болар","карьер","каменные челюсти","сенат","каменная реликвия","трогг"},ang={["faction:Alliance"]="Ресурсы Стальгорна важны для всего Альянса, поэтому защита карьеров Дун Морога — экономическая необходимость.",["profession:Mining"]="Шахтеры остро чувствуют закрытие Гол'Болара: богатые жилы камня и руды остаются брошенными под дубинами захватчиков-троггов.",["race:Dwarf"]="Прорыв троггов в Гол'Боларе бьет прямо по промышленности вашей родины и вновь доказывает, чем оборачивается глубокая добыча, когда она встречается с подземными ужасами."},sec={{t="Сенатор в поле",b="Редко встретишь члена Сената Стальгорна в грязи и слякоти спорной шахты, но Сенатор Мер Каменная Реликвия — не обычный политик. Он служит и правящему органу дворфов, и ученой Лиге исследователей, и лично взял на себя организацию ответа на нашествие троггов в Карьере Гол'Болар. Не дожидаясь медленных законодательных мер, он напрямую нанимает умелых наемников и путников для истребления захватчиков."},{t="The Disaster at Gol'Bolar",b="Карьер Гол'Болар был важным источником камня и минеральных богатств Дун Морога, но глубокие раскопки вскрыли ранее запечатанные подземные пустоты. Примитивные дикие трогги племени Каменных Челюстей хлынули в выработки, круша хрупкое горное оборудование и изгоняя мирных рабочих. Цель Каменной Реликвии — истребить свирепых Костоломов из племени Каменных Челюстей и дать гарнизонам горных пехотинцев закрепиться в карьере и восстановить добычу железа."}},faq={{q="Кто такой Сенатор Мер Каменная Реликвия?",a="Мер Каменная Реликвия — дворфийский сановник, служащий в Сенате Стальгорна и состоящий в Лиге исследователей. Он напрямую и лично занимается угрозой троггов в Карьере Гол'Болар, а не отсиживается за городскими стенами.",al={"stonehallow","senator stonehallow","who is the senator","каменная реликвия","сенатор каменная реликвия","кто такой сенатор"}},{q="Почему Карьер Гол'Болар захвачен троггами?",a="Дворфийские шахтеры копали слишком глубоко под карьером и невольно вскрыли пещеры, где жило племя троггов Каменных Челюстей. Твари хлынули в открытые выработки, разбили машины и заставили рабочих бежать.",al={"why are troggs at gol bolar","quarry troggs","what happened to the quarry","почему трогги в гол'болар","трогги в карьере","что случилось с карьером"}},{q="Кто такие Костоломы из племени Каменных Челюстей?",a="Костоломы из племени Каменных Челюстей — бойцы грубой силы в подземном клане троггов. Они владеют примитивным оружием и берут свирепостью, чтобы одолеть дворфийских шахтеров и защитников.",al={"rockjaw bonesnapper","bonesnappers","bonesnapper troggs","костолом каменных челюстей","костоломы","трогги костоломы"}},{q="Каков план после уничтожения троггов?",a="Когда первые силы троггов будут истреблены, Сенатор Каменная Реликвия намерен привести горных пехотинцев Стальгорна, чтобы как следует укрепить карьер, восстановить разбитые машины и возобновить добычу.",al={"stonehallow plan","what happens next gol bolar","план каменной реликвии","что дальше в гол'болар"}},{q="Почему здесь участвует Лига исследователей?",a="Сенатор Каменная Реликвия связан с Лигой исследователей, члены которой часто изучают древние раскопки, подземные руины и вторжения троггов в горах Каз Модана.",al={"explorers league mining","why league here","лига исследователей и добыча","почему здесь лига"}},{q="Где находится Карьер Гол'Болар?",a="Карьер Гол'Болар лежит в юго-восточном Дун Мороге, врезанный в заснеженные холмы к югу от дороги между Караносом и Южными вратами на пути к Лок Модану.",al={"gol bolar location","where is quarry","где гол'болар","где карьер"}}},fp="18,290,22.491.0,25.474.0,32.261.0,44.230.0,30.186.0,47.196.0,43.203.0,34.155.0"}
P.entries["quest:434"] = {n="Нападение!",s="«Нападение!» — ответственное задание в Крепости Штормграда: гном-изобретатель Тирион и торговец сыром Иллинг Триас организуют тайную операцию. Приключенцы помогают провести скрытую ловушку в королевских садах, чтобы застать заговорщиков-предателей на месте преступления.",h="«Нападение!» — ответственное задание в Крепости Штормграда: гном-изобретатель Тирион и торговец сыром Иллинг...",kw={"defias","elling trias","lescovar","marzon","priestess tyriona","silent blade","spybot","stormwind keep","the attack","tyrion","братство справедливости","иллинг триас","лесковар","марзон","жрица тириона","бесшумный клинок","шпионобот","крепость штормграда","нападение","тирион"},ang={["class:Rogue"]="Задание отражает сложные теневые операции преступного мира разбойников и доказывает, что сырные лавки и тихие уголки садов нередко обладают большей политической властью, чем официальные советы.",["faction:Alliance"]="Казнь Лесковара устраняет из Крепости Штормграда предателя, связанного с Братством Справедливости, хотя и обнажает опасные слабости в руководстве, окружающем юного короля Андуина.",["race:Human"]="Для людей Штормграда эта засада раскрывает горькую правду: бандитский кризис, терзающий Западный Край и Красногорье, тайно подпитывается дворянами из их собственного королевского дворца."},sec={{t="Засада в саду",b="После расследования, организованного шпионом Тирионом и торговцем сыром Иллингом Триасом, все части головоломки встают на место в Крепости Штормграда. Тирион уже сообщил Марзону, что ему и лорду Грегору Лесковару пора встретиться снова, подбросив по пути ложные сведения. Затем он отправляет искусно сделанного автомата, замаскированного под жрицу Тириону, в библиотеку крепости, чтобы сообщить Лесковару о прибытии гостя. Лесковар отпускает стражу и выходит в тихий сад крепости на встречу с Марзоном Бесшумным Клинком, убийцей, связанным с Братством Справедливости."},{t="Измена в крепости",b="Скрываясь в тени, следователи слушают, как Лесковар и Марзон подтверждают давние подозрения: высшая знать Штормграда действует заодно с заговором Братства Справедливости, угрожающим королевству. Когда изменнический разговор заканчивается, ловушка захлопывается. И Лесковара, и Бесшумного Клинка нужно быстро убрать во дворе, пока королевская стража не вернулась и не нашла дворянина мертвым на булыжной мостовой. Это действие надежно лишает Братство Справедливости одного из глубочайших оплотов в самом центре власти."},{t="Теневые игры",b="Хотя непосредственная угроза устранена, последствия оставляют тревожные вопросы. Иллинг Триас испытывает огромное удовлетворение, сводя личные счеты с Марзоном, хотя и досадует, что его частные уловки косвенно помогли Матиасу Шоу и ШРУ. Смерть Лесковара служит неоспоримым доказательством гнили при дворе и намекает, что Братство Справедливости действовало не в одиночку, а кто-то из знати позволил ему разрастись."}},faq={{q="Кто такой лорд Грегор Лесковар?",a="Лорд Грегор Лесковар — видный дворянин Штормграда, живущий в Крепости Штормграда. Под маской придворного величия он тайно сотрудничал с Братством Справедливости, используя свое положение и влияние, чтобы помогать подрывать королевство изнутри, прямо во дворце.",al={"lescovar","who is lescovar","gregor lescovar","лесковар","кто такой лесковар","грегор лесковар"}},{q="Кто такой Марзон Бесшумный Клинок?",a="Марзон Бесшумный Клинок — смертоносный убийца, представляющий Братство Справедливости. Он служит прямым тайным посредником между преступниками и лордом Лесковаром, передавая сообщения и строя планы, пока его не заманили в садовую ловушку Тириона.",al={"marzon","silent blade","who is marzon","марзон","бесшумный клинок","кто такой марзон"}},{q="Почему Иллинга Триаса волнует эта операция?",a="Хотя на вид Иллинг Триас лишь мастер тонких сортов сыра, он влиятельный разбойник с глубокими связями в преступном мире Штормграда. Марзон охотился на людей, близких к Триасу, и тот решил организовать падение убийцы, даже если это попутно помогло Матиасу Шоу и ШРУ.",al={"trias role","why is cheese guy involved","elling trias why","роль триаса","почему замешан торговец сыром","иллинг триас зачем"}},{q="Как Тириону удается выманить Лесковара наружу?",a="Тирион задействует искусно сделанного автомата, замаскированного под жрицу Тириону. Переодетый бот проходит мимо дворцовой стражи в библиотеку и сообщает Лесковару о прибытии гостя, после чего тот отсылает стражу и проводит тайную встречу в саду. Тирион уже сообщил Марзону, что пора встретиться снова, подбросив при этом ложные сведения.",al={"spybot disguise","tyriona","how does lescovar get lured","шпионобот","маскировка","тириона","как выманили лесковара"}},{q="Почему стража сразу не защищает Лесковара?",a="Лесковар отпускает стражу перед встречей, чтобы сохранить в тайне свои преступные дела с Братством Справедливости. Это короткое уединение позволяет следователям устроить засаду и убить и Лесковара, и Марзона, пока королевская стража не вмешалась.",al={"why don't guards help lescovar","guards lescovar","почему стража не помогает лесковару","стража лесковар"}},{q="Что происходит после гибели Лесковара?",a="После смерти Лесковара и Марзона Иллинг Триас отправляет вас в Старый город сообщить мастеру Матиасу Шоу из ШРУ, что угроза в лице Лесковара устранена, в задании «Голова чудовища».",al={"what next after the attack","head of the beast","что дальше после нападения","голова чудовища"}}},fp="11,281,15.571.0,19.505.1,12.444.2,28.266.1,31.240.1,48.285.0,48.370.1,50.223.1,37.183.1"}
P.entries["quest:435"] = {n="Сопровождая Эрланда",s="Загнанный в укрытие хищниками, рыщущими вокруг, страж смерти Эрланд нуждается в сопровождении через Серебряный бор, чтобы воссоединиться с напарником. Если безопасно довести его через дикие земли, он окажется прямо рядом со стражем смерти Ран Йорик.",h="Загнанный в укрытие хищниками, рыщущими вокруг, страж смерти Эрланд нуждается в сопровождении через...",kw={"deathstalker erland","deathstalkers report","ivar patch","rane yorick","silverpine forest","wolves","страж смерти эрланд","отчет стражей смерти","делянка ивара","ран йорик","серебряный бор","волки"},ang={["faction:Horde"]="Помощь изолированным стражам смерти обеспечивает Орде важную передовую разведку для сил, продвигающихся вперед из Гробницы.",["race:Undead"]="Стражи смерти Отрекшихся сильно полагаются на командную работу и скрытность; разведчик, прижатый обычными зверями, показывает, насколько опасны дикие земли Серебряного бора для недавно восставших."},sec={{t="В ловушке у волков",b="Даже опытные разведчики Отрекшихся порой оказываются бессильны перед суровой природой Серебряного бора. Страж смерти Эрланд загнан в полуразрушенное убежище, окруженный изголодавшимися волками, готовыми вырвать остатки плоти из его иссохшего тела. В одиночку прорваться сквозь стаю — самоубийство."},{t="Опасный переход",b="Цель Эрланда находится возле Делянки Ивара, где дозор несет его напарник Страж смерти Ран Йорик. Путь лежит прямо через земли хищных волков. Когда его проведут мимо хищников, Эрланд рывком преодолевает последний отрезок и добирается до безопасного поста Ран Йорик, где разведчики могут свести свои сведения для Подгорода."}},faq={{q="Почему волки охотятся на разведчика-нежить?",a="Как сухо замечает Эрланд, звери Серебряного бора, должно быть, отчаянно голодны, если считают иссохший труп Отрекшегося подходящей едой. Дикие звери леса известны крайней агрессивностью ко всему, что движется по их территории.",al={"why wolves attack undead","why eat undead","erland wolves","почему волки нападают на нежить","почему едят нежить","эрланд волки"}},{q="Кому докладывает страж смерти Эрланд?",a="Эрланд докладывает стражу смерти Ран Йорик, своему напарнику по разведке, расквартированному в соседнем доме фермы у Делянки Ивара. Вместе они следят за угрозами в лесу для Отрекшихся.",al={"who is rane yorick","who does erland report to","erland partner","кто такой ран йорик","кому докладывает эрланд","напарник эрланда"}},{q="Куда ведет сопровождение?",a="Эрланд выходит из своего убежища через дикие земли к Делянке Ивара, в итоге вбегает в дом на ферме и поднимается наверх к стражу смерти Ран Йорик.",al={"escort destination","where does erland go","erland route","цель сопровождения","куда идет эрланд","маршрут эрланда"}},{q="Что происходит после спасения Эрланда?",a="Когда Эрланд благополучно воссоединяется с Ран Йорик, двое разведчиков готовят свои данные. Затем Ран Йорик поручает вам отнести их сводное донесение в Гробницу в задании «Отчет стражей смерти».",al={"what next after escorting erland","the deathstalkers report quest","what follows erland escort","что дальше после сопровождения эрланда","задание отчет стражей смерти","что после сопровождения эрланда"}},{q="Встречаются ли во время сопровождения другие угрозы?",a="Основная опасность исходит от стай волков, патрулирующих открытую местность между исходным местом Эрланда и фермой у Делянки Ивара.",al={"escort enemies","what attacks erland","what is on the road","враги сопровождения","кто нападает на эрланда","что на дороге"}},{q="Какую роль играют стражи смерти в Серебряном бору?",a="Стражи смерти — элитные разбойники, разведчики и убийцы Отрекшихся. В Серебряном бору их высылают впереди основных гарнизонов выслеживать разрозненные отряды Плети, вторжения воргенов, диких зверей и передвижения Альянса.",al={"what are deathstalkers","deathstalker role","deathstalker lore","кто такие стражи смерти","роль стража смерти","предания о стражах смерти"}}},fp="16,237,18.340.0,22.346.0,43.243.0,40.184.0,27.171.0,37.227.1,54.145.0,46.229.0"}
P.entries["quest:436"] = {n="Раскопки Сталекрута",s="«Раскопки Сталекрута» — задание Альянса, связывающее Телсамар с идущими к востоку от озера археологическими раскопками. Джерн Шлеморог подозревает неладное из-за необъяснимых задержек поставок и отправляет приключенца выяснить, что мешает отряду геолога Сталекрута. Добравшись до места раскопок, он быстро узнает правду: неумолимая орда троггов захватила руины.",h="«Раскопки Сталекрута» — задание Альянса, связывающее Телсамар с идущими к востоку от озера археологическими...",kw={"excavation","explorers league","fellhew","hornhelm","ironband","loch modan","thelsamar","troggs","раскопки","лига исследователей","рудокол","шлеморог","сталекрут","лок модан","телсамар","трогги"},ang={["faction:Alliance"]="Защита Лок Модана требует держать важные торговые дороги и места исследований свободными от подземной угрозы наступающих племен троггов.",["race:Dwarf"]="Каждые раскопки в Каз Модане — попытка раскрыть правду о происхождении дворфов и наследии титанов, поэтому безопасность отряда Сталекрута жизненно важна для Стальгорна."},sec={{t="Заминка в предгорьях",b="В городке Телсамар Джерн Шлеморог следит за грузами, отправляемыми через Лок Модан Лиге исследователей. Несмотря на стабильный поток провизии и инструментов, раскопки под руководством геолога Сталекрута сообщают о минимальных успехах. Зная Сталекрута как честного, усердного дворфа, Шлеморог опасается, что работу нарушило нечто недоброе, а не простая лень."},{t="Нашествие троггов",b="Добравшись до места раскопок в восточных холмах, вы узнаете истинную причину задержки. Исследователь Магмар Рудокол сообщает, что свирепые трогги наводнили раскопки, донимая дворфов и разбрасывая их находки. Лига не может завершить изучение древних камней, пока дикие захватчики не будут отброшены."}},faq={{q="Кто отправляет вас на Раскопки Сталекрута?",a="Джерн Шлеморог, находящийся в Телсамаре, просит вас проверить раскопки. Он заметил отсутствие успехов, несмотря на регулярные поставки припасов, и хочет, чтобы кто-то на месте все выяснил.",al={"quest starter","who gives quest","jern hornhelm role","выдающий задание","кто дает задание","роль джерна шлеморога"}},{q="Где находятся раскопки?",a="Раскопки лежат в предгорьях к востоку от озера. Путникам из Телсамара нужно обойти южный край воды и идти по тропе на восток, в холмы.",al={"dig site location","where is ironbands excavation","how to get there","место раскопок","где раскопки сталекрута","как добраться"}},{q="Кто такой Магмар Рудокол?",a="Магмар Рудокол — исследователь, помогающий геологу Сталекруту на раскопках. Он руководит повседневной работой и снабжением на месте и разъясняет обстановку посланникам из Телсамара.",al={"fellhew","who is magmar fellhew","turn in npc","рудокол","кто такой магмар рудокол","персонаж сдачи задания"}},{q="Почему на раскопках застопорилась работа?",a="Экспедицию остановили свирепые трогги. Существа хлынули в руины, сорвав раскопки и заставив Лигу сосредоточиться на самообороне.",al={"why slow","delay reason","what happened to the dig","почему медленно","причина задержки","что случилось с раскопками"}},{q="Что будет после выполнения этого задания?",a="Магмар Рудокол поручает вам помочь отряду вернуть утраченное и сразу переходит к заданию «Сбор идолов», чтобы вернуть реликвии, украденные троггами.",al={"next quest","followup","gathering idols quest","следующее задание","продолжение","задание сбор идолов"}},{q="Что ищет здесь Лига исследователей?",a="Экспедиция геолога Сталекрута ищет древние реликвии и каменную кладку под Лок Моданом, чтобы пролить свет на историю дворфов и их давно забытое происхождение.",al={"excavation purpose","dwarf dig reason","ancient ruins loch modan","цель раскопок","зачем дворфы копают","древние руины лок модан"}}},fp="21,362,27.369.0,21.338.1,39.196.0,37.165.0,22.195.0,36.172.0,44.168.0,47.148.0"}
P.entries["quest:437"] = {n="Мертвое поле",s="«Мертвое поле» — штурмовое задание верховного палача Хадрика из Гробницы. Разведчики Отрекшихся выяснили, что гноллы Гнилошкуры, заполонившие заброшенную северную ферму, ведомы и охраняются банши Плети Ночной Плетью, уничтожение которой критически важно для защиты Серебряного бора.",h="«Мертвое поле» — штурмовое задание верховного палача Хадрика из Гробницы.",kw={"banshee","dead fields","hadrec","nightlash","rot hide","scourge","sepulcher","silverpine","банши","мертвое поле","хадрик","ночная плеть","гнилошкуры","плеть","гробница","серебряный бор"},ang={["faction:Horde"]="Разрыв хватки Плети на севере Серебряного бора помогает защитить путь, соединяющий Подгород с южными землями Лордерона.",["race:Undead"]="Для Отрекшихся уничтожение Ночной Плети — личный удар по Плети и мрачное напоминание о призрачных муках, от которых Сильвана и ее банши освободились."},sec={{t="Чума на полях",b="К северу от Гробницы лежит заброшенная ферма, известная как Мертвое поле. Когда-то обычные пахотные земли ныне задушены гноллами Гнилошкурами — чумными падальщиками, заполонившими окрестности Серебряного бора. Верховный палач Хадрик ранее посылал небольшие отряды, чтобы выбить их, но каждое наступление захлебывалось из-за неестественной магической защиты."},{t="Хватка банши",b="Гнилошкуры действуют не просто по дикому инстинкту — их подкрепляет Плеть. Банши по имени Ночная Плеть надзирает за местностью и темным колдовством разгоняет бойцов Отрекшихся, когда гноллам грозит гибель. Хадрик посылает героев Орды истреблять гноллов, пока Ночная Плеть не будет выманена, и требует ее призрачную сущность как доказательство ее смерти."}},faq={{q="Где находится Мертвое поле?",a="Мертвое поле расположено к северу от Гробницы в Серебряном бору. Это заросшая, гниющая ферма, сильно захваченная гноллами Гнилошкурами.",al={"dead fields location","where is dead field","where to find dead fields","где мертвое поле","расположение мертвого поля","как найти мертвое поле"}},{q="Кто такая Ночная Плеть?",a="Ночная Плеть — банши Плети, которая командует гноллами Гнилошкурами на Мертвом поле и защищает их, используя темную магию, чтобы отгонять прежние штурмовые отряды Отрекшихся.",al={"who is nightlash","nightlash lore","banshee nightlash","кто такая ночная плеть","предания о ночной плети","банши ночная плеть"}},{q="Почему гноллы работают с банши?",a="Гноллы Гнилошкуры Серебряного бора заражены чумой нежизни. Плеть использует таких, как Ночная Плеть, чтобы направлять этих бешеных тварей как передовую пехоту против Отрекшихся.",al={"why rot hides with scourge","gnoll scourge connection","rot hide gnolls lore","почему гнилошкуры с плетью","связь гноллов и плети","гноллы гнилошкуры предания"}},{q="Как выманить Ночную Плеть?",a="Ночная Плеть остается скрытой, пока гноллов под ее защитой не перебьют в большом количестве. Если убить достаточно Гнилошкур, она вынуждена появиться посреди поля, чтобы защитить свои владения.",al={"how to spawn nightlash","where is nightlash","nightlash not there","как призвать ночную плеть","где ночная плеть","ночной плети нет"}},{q="Кто выдает задание «Мертвое поле»?",a="Верховный палач Хадрик, военный командир Отрекшихся, расквартированный в Гробнице, выдает это задание в рамках своей кампании по защите региона.",al={"who gives the dead fields","dead fields quest giver","hadrec quest","кто дает мертвое поле","выдающий задание мертвое поле","задание хадрика"}},{q="Что происходит после уничтожения Ночной Плети?",a="Сущность Ночной Плети, принесенная верховному палачу Хадрику, доказывает, что Плеть потеряла важное присутствие на севере Серебряного бора, и Хадрик обращает ваше внимание на Старую переправу на западе.",al={"dead fields followup","what comes after dead fields","продолжение мертвого поля","что после мертвого поля"}}},fp="15,298,24.359.0,19.359.0,34.148.0,17.160.0,38.198.0,30.193.0,36.144.0,42.198.1"}
P.entries["quest:438"] = {n="Старая переправа",s="Верховный палач Хадрик направляет героев Отрекшихся к востоку от Гробницы, чтобы они осмотрели Старую переправу. Пристань на берегу озера кишит Плетью и гнилошкурами, что вызывает тревогу из-за расширения влияния врага на берегах озера Лордамер.",h="Верховный палач Хадрик направляет героев Отрекшихся к востоку от Гробницы, чтобы они осмотрели Старую...",kw={"corpse laden boat","decrepit ferry","fenris isle","high executor hadrec","lordamere lake","rot hide","sepulcher","silverpine","лодка с трупами","старая переправа","остров фенриса","верховный палач хадрик","озеро лордамер","гнилошкуры","гробница","серебряный бор"},ang={["faction:Horde"]="Защита окрестностей озера Лордамер обеспечивает безопасность линий снабжения Орды в Серебряном бору от вторжений Плети с севера.",["race:Undead"]="Для Отрекшихся любой плацдарм Плети в Серебряном бору — прямая угроза существованию границ Тирисфальских лесов и Подгорода."},sec={{t="Взгляд через озеро",b="После подавления Плети на Мертвом поле Верховный палач Хадрик обратил стратегический взор на восточные водные пути Серебряного бора. Старая переправа, некогда обычная переправа между материковым Лордероном и островными поместьями озера Лордамер, незаметно превратилась в оживленный улей нежити. Хадрик отправил разведчиков выяснить, что привлекло слуг Короля-лича к этим гнилым причалам."},{t="Мрачный груз",b="Добравшись до переправы, вы видите не только гнилошкуров, бесцельно бродящих по болотистым берегам. У пристани стоит затопленная плоскодонка, полная заботливо завернутых, сохраненных трупов. Глядя сквозь туман над озером Лордамер, можно различить причалы на Острове Фенриса напротив — жуткая линия снабжения доставляет тела прямо к островной крепости."}},faq={{q="Кто посылает вас к Старой переправе?",a="Верховный палач Хадрик, военный командир Отрекшихся в Гробнице в Серебряном бору, дает это задание после того, как вы поможете очистить Мертвое поле.",al={"who gives the decrepit ferry quest","hadrec quest ferry","quest giver decrepit ferry","кто дает задание старая переправа","задание хадрика переправа","персонаж, выдающий задание старая переправа"}},{q="Где находится Старая переправа?",a="Переправа лежит к востоку от Гробницы на западном берегу озера Лордамер, там, где речушки с суши впадают в открытую воду.",al={"decrepit ferry location","where is the ferry silverpine","how to find decrepit ferry","старая переправа расположение","где переправа серебряный бор","как найти старую переправу"}},{q="Какие существа обитают у Старой переправы?",a="Местность захвачена нежитью Плети, в основном гноллами-гнилошкурами и оживленными скелетами, патрулирующими берег и окрестные причалы.",al={"mobs at decrepit ferry","what enemies are at the ferry","decrepit ferry monsters","монстры у старой переправы","какие враги у переправы","старая переправа мобы"}},{q="Что вы обнаружите у переправы?",a="Вы находите лодку, полную трупов, наполовину вытащенную из воды. В ней лежат завернутые тела, которые собирались переправить через озеро на Остров Фенриса.",al={"what is at the ferry","ferry turn in object","what is in the boat","что у переправы","объект сдачи задания переправа","что в лодке"}},{q="Почему Плеть интересуется переправой?",a="Переправа служит перевалочным пунктом через озеро Лордамер, позволяя Плети перевозить свежие трупы прямо в свою крепость на Острове Фенриса.",al={"why are scourge at decrepit ferry","ferry scourge purpose","зачем плеть у старой переправы","цель плети на переправе"}},{q="Какое задание следует за заданием «Старая переправа»?",a="Осмотр лодки с трупами сразу ведет к заданию «Необычная находка», в котором вам предстоит исследовать действия гноллов и связь с Островом Фенриса.",al={"next quest after decrepit ferry","decrepit ferry follow up","следующее задание после старой переправы","продолжение старой переправы"}}},fp="18,254,20.437.0,12.363.1,36.171.0,36.128.0,41.137.0,34.149.0,42.159.0,38.159.0"}
P.entries["quest:439"] = {n="Необычная находка",s="Осмотр баржи с трупами на озере Лордамер выявляет кольцо с гравировкой на руке недавно умершей женщины. Доклад Верховному палачу Хадрику в Гробнице раскрывает зловещую картину: гноллы-гнилошкуры грабят братские могилы Тирисфальских лесов и отправляют тела на Остров Фенриса.",h="Осмотр баржи с трупами на озере Лордамер выявляет кольцо с гравировкой на руке недавно умершей женщины.",kw={"corpse laden boat","deliah","deliah's ring","fenris isle","hadrec","rot hide clues","rot hide gnolls","sepulcher","лодка с трупами","делия","кольцо делии","остров фенриса","хадрик","необычная находка","гноллы-гнилошкуры","гробница"},ang={["faction:Horde"]="Хадрик координирует действия Орды из Гробницы, чтобы защитить Серебряный бор от растущих лагерей чудовищ, таких как стая гнилошкуров на Острове Фенриса.",["race:Undead"]="Осквернение братских могил Тирисфаля задевает Отрекшихся за живое: их павших родичей и еще не восставших собратьев увозят как сырье для алхимических ужасов гноллов."},sec={{t="Жуткий груз",b="Осматривая брошенную лодку, полную трупов, на берегу озера Лордамер, разведчики Отрекшихся обнаруживают, что не все мертвецы — древние останки. Из груды падали торчит неприкрытая, отмеченная чумой рука недавно убитой женщины с простым кольцом, на котором выгравировано: «Для Делии». Сама лодка говорит о согласованной доставке, а не о бессмысленном пиршестве падальщиков."},{t="Грабители могил",b="Когда кольцо Делии доставлено Верховному палачу Хадрику в Гробницу, командир Отрекшихся быстро складывает улики воедино. Так недавно погребенное тело могло прийти лишь из обширных братских могил за границей, в Тирисфальских лесах. Гноллы-гнилошкуры, наводнившие Серебряный бор, не просто бродят по лесу: они методично выкапывают человеческие трупы и переправляют их через воду на Остров Фенриса со зловещими, неведомыми целями."}},faq={{q="Что такое лодка с трупами?",a="Это старая переправа, пришвартованная у берегов озера Лордамер в Серебряном бору. Гноллы-гнилошкуры используют ее, чтобы перевозить выкопанные человеческие трупы через воду в свою крепость на Острове Фенриса.",al={"corpse boat","decrepit ferry boat","lake boat","лодка с трупами","лодка старой переправы","лодка на озере"}},{q="Кто такая Делия?",a="Делия была человеческой жертвой чумы, чье тело недавно похоронили в братских могилах Тирисфальских лесов. Ее труп украли гноллы-гнилошкуры, оставив лишь кольцо с гравировкой как улику для следователей.",al={"deliah lore","who is deliah","for deliah ring","предания о делии","кто такая делия","кольцо для делии"}},{q="Зачем гноллы собирают мертвые тела?",a="Гнилошкуры — гноллы-нежить на службе у Плети. Они не поедают тела, а грабят братские могилы Тирисфаля и отправляют трупы в крепость Плети на Острове Фенриса.",al={"why do gnolls want corpses","rot hide corpses","fenris isle dead bodies","зачем гноллам трупы","гнилошкуры трупы","трупы остров фенриса"}},{q="Кто такой Верховный палач Хадрик?",a="Верховный палач Хадрик — военный командир Отрекшихся в Гробнице в Серебряном бору. Он руководит обороной от местных угроз, включая диких гноллов-гнилошкуров, волшебников Даларана и воргенов.",al={"hadrec","sepulcher commander","executor hadrec","хадрик","командир гробницы","палач хадрик"}},{q="Откуда взялись трупы в лодке?",a="По словам Верховного палача Хадрика, свежесть тел указывает на то, что их выкопали из братских могил в соседних Тирисфальских лесах, где наспех хоронили жертв Плети и чумы.",al={"boat corpses origin","tirisfal graves boat","происхождение трупов в лодке","тирисфальские могилы лодка"}},{q="Что происходит после доклада Хадрику об этой улике?",a="Хадрик отправляет агентов бороться с угрозой гнилошкуров прямо на Острове Фенриса и добыть образцы гнилой сукровицы, которую те перерабатывают. Также начинается расследование о том, кем была Делия, и возвращение ее кольца.",al={"after rot hide clues","deliah ring follow up","после необычной находки","кольцо делии продолжение"}}},fp="14,310,16.398.0,21.442.1,30.217.0,15.220.0,37.183.1,28.227.0,44.200.0,49.221.1"}
P.entries["quest:440"] = {n="Кольцо с гравировкой",s="Верховный палач Хадрик посылает героя в Брилл с найденным обручальным кольцом, на котором выгравировано имя женщины по имени Делия. Мировой судья Севрен изучает городские записи, чтобы выяснить, кто она, и откуда взялось кольцо.",h="Верховный палач Хадрик посылает героя в Брилл с найденным обручальным кольцом, на котором выгравировано имя...",kw={"brill","deliah","deliah's ring","gnolls","high executor hadrec","magistrate sevren","mass grave","rot hide","silverpine","the engraved ring","брилл","делия","кольцо делии","гноллы","верховный палач хадрик","мировой судья севрен","братская могила","гнилошкуры","серебряный бор","кольцо с гравировкой"},ang={["faction:Horde"]="Не дать гноллам-гнилошкурам осквернять подконтрольные Орде могилы в Тирисфальских лесах — вопрос не только возмездия, но и безопасности территорий.",["race:Undead"]="Для Отрекшихся кольцо Делии — тихое напоминание о хрупких нитях, связывающих их прошлую жизнь с мрачным, холодным настоящим в Лордероне."},sec={{t="Памятная вещь из Серебряного бора",b="Во время расследования о гноллах-гнилошкурах на северных окраинах Серебряного бора разведчики нашли кольцо с гравировкой и именем Делия. Вместо того чтобы выбросить безделушку, Верховный палач Хадрик велит вам отнести ее через границу в Брилл. Мировой судья Севрен ведет городские записи и книги погребений Тирисфаля, так что он вероятнее всех сможет выяснить, кто она, хотя Хадрик глубоко сомневается, что кого-то из Отрекшихся это еще волнует."},{t="Украдено из земли",b="Получив кольцо в Брилле, Мировой судья Севрен подтверждает, что Делия действительно жила здесь, умерла и была погребена в братской могиле города. Находка ее украшения у гнилошкуров в Серебряном бору раскрывает зловещее осквернение: гноллы, искаженные чумой, грабят братские могилы и тайно увозят трупы на юг для опытов Плети. Севрен жаждет увидеть гноллов истребленными."}},faq={{q="Кто такая Делия?",a="Deliah is the name engraved on the recovered ring. Hadrec asks you to consult Magistrate Sevren's records in Brill to learn who she was.",al={"who is deliah","deliah lore","deliah ring","кто такая делия","предания о делии","кольцо делии"}},{q="Почему кольцо Делии нашли в Серебряном бору?",a="The ring was recovered during the Rot Hide investigation. Sevren's records may help explain whose keepsake it was and how it came to Silverpine.",al={"why do gnolls have the ring","rot hide ring","how did ring get to silverpine","почему у гноллов кольцо","кольцо гнилошкуров","как кольцо попало в серебряный бор"}},{q="Почему Верховный палач Хадрик сомневается, что кольцо важно?",a="Хадрик отмечает, что нежизнь часто стирает смертные привязанности. Он полагает, что возлюбленный Делии либо мертв, либо, если восстал Отрекшимся, совершенно равнодушен к смертным клятвам и воспоминаниям.",al={"hadrec dialogue","why hadrec cynical","forsaken feelings","диалог хадрика","почему хадрик циничен","чувства отрекшихся"}},{q="Какую роль в этом задании играет Мировой судья Севрен?",a="Как мировой судья Брилла, Севрен ведет местные городские записи и книги умерших, что позволяет ему подтвердить личность Делии и место ее погребения.",al={"sevren brill","magistrate sevren role","who is sevren","севрен брилл","роль мирового судьи севрена","кто такой севрен"}},{q="Союзны ли гноллы-гнилошкуры Плети?",a="Да. Гноллы-гнилошкуры Серебряного бора заражены чумой Плети, действуют под темным влиянием и собирают трупы для некромантических целей.",al={"are rot hides scourge","gnoll scourge","silverpine gnolls","гнилошкуры плеть","гноллы плеть","гноллы серебряного бора"}},{q="Куда ведет это расследование дальше?",a="Magistrate Sevren consults Brill's records to identify Deliah. What he learns provides the next lead in the investigation.",al={"what next after engraved ring","next quest","deliah continuation","что дальше после кольца с гравировкой","следующее задание","продолжение делии"}}},fp="17,227,24.501.0,20.398.1,15.136.1,49.144.1,53.180.0,52.158.0,48.163.0,40.122.1"}
P.entries["quest:441"] = {n="Роли, который живет в Подгороде",s="Это задание продолжает расследование из Брилла в Подгород: героя просят доставить найденное семейное кольцо вдовцу по имени Роли. Кольцо, найденное на украденном теле женщины, предназначенном для Острова Фенриса, указывает на трагедию среди бывших жителей Лордерона. Его доставка запускает мрачную погоню за местью.",h="Это задание продолжает расследование из Брилла в Подгород: героя просят доставить найденное семейное кольцо...",kw={"a husband's revenge","brill","deliah","deliah's ring","raleigh","sevren","trade quarter","undercity","месть мужа","брилл","делия","кольцо делии","роли","севрен","торговый квартал","подгород"},ang={["faction:Horde"]="Проносить памятные вещи старого Лордерона через ворота Подгорода — значит видеть мрачную реальность жизни ваших союзников Отрекшихся.",["race:Undead"]="Холодная реакция Роли на трагическую гибель жены отражает душевную травму, общую для Отрекшихся, чьи смертные привязанности истлели и превратились в горький гнев."},sec={{t="Трагическая реликвия",b="В Брилле Мировой судья Севрен сопоставил улики об украденном трупе и кольце с гравировкой, принадлежавшем женщине по имени Делия. Надеясь подтвердить его происхождение и вернуть семье, Севрен отправил нашедшего в глубь подземных залов Подгорода к оставшемуся в живых мужу Делии, Роли."},{t="Холодные сердца, горькая месть",b="В шумном Торговом квартале Подгорода Роли Андреан без колебаний узнает кольцо бывшей жены. Как и многих Отрекшихся, нежизнь лишила его способности скорбеть и сожалеть о смерти и осквернении Делии. Но там, где нежные чувства угасли, осталась непреклонная жажда возмездия, и Роли замышляет месть тем, кто потревожил ее последний покой."}},faq={{q="Кто выдает это задание?",a="Это задание выдает Мировой судья Севрен в городке Брилл в Тирисфальских лесах сразу после того, как вы вернете ему Кольцо Делии.",al={"where do i get raleigh and the undercity","quest giver","magistrate sevren quest","где взять роли, который живет в подгороде","кто выдает задание","задание мирового судьи севрена"}},{q="Где находится Роли Андреан?",a="Роли Андреан находится в Торговом квартале Подгорода среди торговцев и ремесленников подземного города.",al={"raleigh location","where is raleigh","trade quarter raleigh","где роли","местонахождение роли","торговый квартал роли"}},{q="Чье кольцо нужно доставить?",a="Кольцо принадлежало Делии, женщине из Брилла, которая была женой Роли Андреана до падения Лордерона.",al={"deliah ring","who was deliah","whose ring is this","кольцо делии","кто была делия","чье это кольцо"}},{q="Почему Роли не скорбит по умершей жене?",a="Как Отрекшийся, Роли признает, что нежные чувства, такие как горе и любовь, остыли в его нежитьем сердце. Вместо них оставшиеся страсти превратились в холодную жажду мести.",al={"raleigh reaction","does raleigh care","why is raleigh cold","реакция роли","заботит ли роли","почему роли холоден"}},{q="Что происходит после этого задания?",a="Сдача кольца ведет прямо к заданию «Месть мужа», в котором Роли посылает вас отомстить за осквернение его жены.",al={"next quest","follow up to raleigh","what comes after","следующее задание","продолжение роли","что дальше"}},{q="Как изначально нашли кольцо Делии?",a="Кольцо было найдено во время задания «Необычная находка»: его сняли с руки Делии среди завернутых трупов в лодке у Старой переправы в Серебряном бору.",al={"ring origin","where did the ring come from","происхождение кольца","откуда взялось кольцо"}}},fp="25,342,17.328.0,29.425.1,22.131.0,33.129.0,30.110.0,40.199.0,30.130.1,38.162.0"}
P.entries["quest:442"] = {n="Атака на остров Фенриса",s="«Атака на остров Фенриса» — решающий боевой приказ Верховного палача Хадрика уничтожить оплот Плети в Серебряном бору. Чтобы разорвать хватку Короля-лича на Озере Лордамер, агенты Отрекшихся отправляются штурмовать Крепость Фенриса и добыть голову некроманта Тула Когтя Ворона.",h="«Атака на остров Фенриса» — решающий боевой приказ Верховного палача Хадрика уничтожить оплот Плети в...",kw={"fenris isle","hadrec","lake lordamere","scourge","sepulcher","silverpine forest","thule ravenclaw","остров фенриса","хадрик","озеро лордамер","плеть","гробница","серебряный бор","тул коготь ворона"},ang={["class:Mage"]="Бетор Ледострел и аптекарь Ренферрел внимательно следят за магическими последствиями гибели Тула, зачарованные яростным рассеиванием его некротических плетений.",["faction:Horde"]="Закрепление Орды на Восточных королевствах во многом зависит от того, что Отрекшиеся удерживают Серебряный бор и Тирисфаль от соперничающих сил и бродячей Плети.",["race:Undead"]="Для Отрекшихся уничтожение Тула Когтя Ворона — личное возмездие. Разгром аванпостов Плети доказывает, что их восстание против воли Короля-лича абсолютно."},sec={{t="Очищение Озера Лордамер",b="Уже несколько недель Остров Фенриса остается ядовитым нарывом в сердце Озера Лордамер. Пока Отрекшиеся укрепляли западные дороги и закреплялись в Гробнице, Плеть окопалась в Крепости Фенриса. Этим островным аванпостом командует могущественный некромант Тул Коготь Ворона, и он угрожает не только Серебряному бору, но и южным водным путям, ведущим к самому Подгороду. Верховный палач Хадрик понимает: Отрекшиеся никогда не будут по-настоящему держать Серебряный бор, пока слуга Короля-лича проводит мерзкие опыты прямо у их восточных берегов."},{t="Падение Тула Когтя Ворона",b="Чтобы штурмовать Крепость Фенриса, нужно проложить путь через толпы гноллов-гнилошкуров и бредущую нежить, а затем встретиться с Тулом Когтем Ворона в его твердыне. Тул применяет мерзкие некромантические проклятия и усиливает свои удары, высасывая жизненные силы нападающих темной магией. После его поражения отсеченная голова Тула служит неоспоримым доказательством его гибели. Некромантический выброс при его падении так силен, что аптекарь Ренферрел улавливает магические ударные волны даже в Гробнице."}},faq={{q="Почему Верховный палач Хадрик хочет смерти Тула Когтя Ворона?",a="Тул Коготь Ворона — искусный некромант, возглавляющий Плеть на Острове Фенриса. Оставленные без внимания, столь укрепившиеся силы Плети угрожают оплоту Отрекшихся в Гробнице и водным путям через Озеро Лордамер. Хадрик требует его голову как подтверждение того, что региональное командование Плети окончательно разгромлено.",al={"why kill thule","hadrec motives","fenris isle threat","зачем убивать тула","мотивы хадрика","угроза острова фенриса"}},{q="Где находится Тул Коготь Ворона?",a="Тул Коготь Ворона обитает в глубине разрушенного замка на Острове Фенриса, посреди Озера Лордамер к востоку от Серебряного бора. Он держит двор в нижнем общем зале крепости, под охраной нежити и уродливых прислужников.",al={"thule ravenclaw location","where is thule","find thule","где тул коготь ворона","где тул","найти тула"}},{q="Что происходит, когда Тул Коготь Ворона умирает?",a="Когда Тул уничтожен, огромный выброс темной некромантической энергии отдается эхом по всей округе. В Гробнице аптекарь Ренферрел улавливает ударную волну распадающейся магии, а Верховный палач Хадрик называет этот удар крупным стратегическим триумфом Отрекшихся.",al={"thule death reaction","what happens after thule dies","реакция на смерть тула","что будет после смерти тула"}},{q="Кто контролирует остров Фенриса до этой атаки?",a="Остров Фенриса находится под прямой оккупацией Плети. Тул Коготь Ворона использует островной замок как плацдарм, командуя и поднятой нежитью, и гноллами-гнилошкурами, изуродованными порчей, чтобы терроризировать воды Озера Лордамер.",al={"who holds fenris isle","fenris isle faction","is fenris isle scourge","кто держит остров фенриса","фракция острова фенриса","плеть на острове фенриса"}},{q="Почему Зелье Бетора было важно для этого задания?",a="Тул накладывает «Порчу Когтя Ворона» — ослабляющее проклятие, которое уменьшает силу противников и увеличивает его собственную. Бетор Ледострел во время предыдущих операций приготовил алхимическое зелье именно для нейтрализации этого некротического проклятия.",al={"hex of the ravenclaw cure","bethor potion thule","counter thule hex","лекарство от порчи когтя ворона","зелье бетора тул","против порчи тула"}},{q="Каково стратегическое значение Острова Фенриса для Отрекшихся?",a="Остров Фенриса лежит на Озере Лордамер, на границе Серебряного бора и предгорий Хилсбрада. Захват или нейтрализация острова устраняет действующий вражеский аванпост, способный совершать нападения на Серебряный бор, и убирает крупное присутствие Плети с границ Лордерона.",al={"why fenris isle matters","fenris isle importance","почему важен остров фенриса","значение острова фенриса"}}},fp="22,298,22.586.0,27.508.1,56.327.0,33.244.0,39.284.1,45.230.0,51.252.0,66.261.0"}
P.entries["quest:443"] = {n="Лимфа Гнилошкуров",s="«Лимфа Гнилошкуров» — задание Орды в Серебряном бору, которое выдает Верховный палач Хадрик в Гробнице. Желая понять неестественных гноллов-гнилошкуров, заполонивших Остров Фенриса, перед началом атаки руководство Отрекшихся поручает искателям приключений добыть для изучения мерзкую загадочную жидкость, текущую в жилах этих существ.",h="«Лимфа Гнилошкуров» — задание Орды в Серебряном бору, которое выдает Верховный палач Хадрик в Гробнице.",kw={"apothecary renferrel","fenris isle","high executor hadrec","lordamere lake","rot hide gnolls","rot hide ichor","sepulcher","silverpine forest","аптекарь ренферрел","остров фенриса","верховный палач хадрик","озеро лордамер","гноллы гнилошкуры","лимфа гнилошкуров","гробница","серебряный бор"},ang={["faction:Horde"]="Остров Фенриса лежит на восточной окраине Серебряного бора и остается опасной тактической зоной, если силы Орды, охраняющие окрестные земли, не следят за ним.",["race:Undead"]="Для Отрекшихся понимание биологических ужасов и созданных болезней — одновременно наука и инстинкт выживания. Изучение жидкости Гнилошкуров позволяет Королевскому фармацевтическому обществу определить, угрожает ли эта зараза их владениям в Лордероне."},sec={{t="Неестественная биология",b="Гноллы Гнилошкуры из Серебряного бора — совсем не обычные дикие гуманоиды. Разлагающиеся, агрессивные и пропитанные запахом порчи, они занимают стратегические позиции, например на острове Фенриса посреди озера Лордамер. Верховный палач Хадрик понимает, что их неестественная стойкость связана с той странной жидкостью, что течет в их телах, и требует добыть образцы, прежде чем посылать солдат в дорогостоящую атаку."},{t="Анализ аптекаря",b="Королевское фармацевтическое общество постоянно присутствует в Гробнице, а аптекарь Ренферрел специализируется на биологических и химических аномалиях. Доставив образцы этой гнилой лимфы гнилошкуров Ренферрелу, Отрекшиеся надеются выяснить происхождение гноллов, понять, кто их создает, и найти уязвимости для боя."}},faq={{q="Что такое лимфа Гнилошкуров?",a="Это неестественная гнилостная жидкость, текущая в телах гноллов-гнилошкуров на Острове Фенриса. Вместо обычной крови эта мерзкая смесь поддерживает их подобное нежити разлагающееся состояние и дает им необычайную стойкость.",al={"what is the ichor","rot hide fluid","gnoll ichor","что такое лимфа","жидкость гнилошкуров","лимфа гноллов"}},{q="Зачем Верховному палачу Хадрику образцы лимфы?",a="Хадрик планирует атаку на Остров Фенриса, но военная мудрость требует сначала понять врага. Получив образцы жидкости для изучения аптекарем Ренферрелом, Отрекшиеся надеются выяснить, кто создал Гнилошкуров, и найти их биологическую слабость.",al={"why collect ichor","hadrec's goal","why hadrec wants ichor","зачем собирать лимфу","цель хадрика","зачем хадрику лимфа"}},{q="Где находятся гноллы-гнилошкуры?",a="Они обитают на Острове Фенриса, к востоку через Озеро Лордамер от Старой переправы в Серебряном бору. Берег острова, лагеря и окрестные разрушенные земли заполонили разные виды Гнилошкуров, включая громил и чумных ткачей.",al={"where do i find rot hides","rot hide gnoll location","fenris gnolls","где найти гнилошкуров","где гноллы гнилошкуры","гноллы острова фенриса"}},{q="Кто такой аптекарь Ренферрел?",a="Ренферрел — исследователь Королевского фармацевтического общества, работающий у склепа в Гробнице. Он изучает местные поветрия, чуму и странные биологические угрозы по всему Серебряному бору от имени Отрекшихся.",al={"who is renferrel","apothecary renferrel role","кто такой ренферрел","аптекарь ренферрел"}},{q="Что происходит после того, как Ренферрел получает лимфу?",a="Получив образцы, Ренферрел приступает к анализу химического состава жидкости, чтобы проследить происхождение Гнилошкуров, — это ведет к заданию «Происхождение Гнилошкуров».",al={"next quest after rot hide ichor","rot hide ichor follow up","следующее задание после лимфы гнилошкуров","продолжение лимфы гнилошкуров"}},{q="Почему Отрекшихся волнуют гноллы?",a="Гноллы-гнилошкуры удерживают Остров Фенриса — важный оплот на Озере Лордамер у границ земель Отрекшихся. Кроме того, их разлагающееся состояние и чумные способности говорят о постороннем вмешательстве, что может прямо угрожать безопасности Подгорода.",al={"why forsaken fight gnolls","gnoll threat silverpine","почему отрекшиеся воюют с гноллами","угроза гноллов серебряный бор"}}},fp="14,339,17.384.0,19.349.0,23.228.0,56.260.0,38.245.0,28.226.0,48.167.0,38.259.0"}
P.entries["quest:444"] = {n="Происхождение Гнилошкуров",s="«Происхождение Гнилошкуров» — задание Отрекшихся, связывающее исследования Королевского фармацевтического общества в Серебряном бору с чародейским мастерством Подгорода. Проанализировав гнилостную жидкость гноллов, аптекарь Ренферрел отправляет искателя приключений к Бетору Ледострелу, чтобы выяснить магическое происхождение этих разлагающихся тварей.",h="«Происхождение Гнилошкуров» — задание Отрекшихся, связывающее исследования Королевского фармацевтического...",kw={"apothecary renferrel","bethor iceshard","magic quarter","rot hide ichor","rot hide origins","sample ichor","silverpine forest","undercity","аптекарь ренферрел","бетор ледострел","магический квартал","лимфа гнилошкуров","происхождение гнилошкуров","образец лимфы","серебряный бор","подгород"},ang={["class:Mage"]="Роль Бетора Ледострела показывает, что тайное прорицание и ученое колдовство остаются важнейшими средствами разгадки темных тайн, недоступных обычной алхимии.",["class:Warlock"]="Обнаружение скверны и магии чернокнижников, смешанных с некромантией в лимфе гнилошкуров, указывает на намеренное запретное колдовство в глуши Серебряного бора.",["race:Undead"]="Это задание демонстрирует сотрудничество Королевского фармацевтического общества и тайных мастеров Подгорода, которые сочетают науку и колдовство, чтобы защитить Лордерон."},sec={{t="Смесь смерти и скверны",b="Исследуя жидкость гноллов-гнилошкуров, заполонивших Серебряный бор, аптекарь Ренферрел разлагает мерзкое вещество на основные элементы. Предварительная перегонка показывает нечто куда более странное, чем обычная болезнь гноллов: лимфа несет безошибочный двойной след некромантии и магии чернокнижников. Поняв, что одна алхимия не раскроет всей сути колдовства, Ренферрел поручает агенту доставить подготовленный образец прямо в столицу для тайного изучения."},{t="Встреча с магом",b="Образец доставляют Бетору Ледострелу, опытному Отрекшемуся магу, живущему высоко в Магическом квартале Подгорода. Бетор не состоит в Королевском фармацевтическом обществе, но его глубокое знание тайных и темных дисциплин делает его бесценным помощником в расшифровке необычных плетений силы. Получив мерзкий флакон, Бетор обнаруживает древние могущественные чары, которых не встречал годами, и сразу готовит заклинание прорицания, чтобы выяснить, кто сплел эту скверную магию."}},faq={{q="Кто посылает игрока на это задание?",a="Аптекарь Ренферрел, алхимик Королевского фармацевтического общества, работающий в Серебряном бору в Гробнице, дает это поручение после изучения лимфы, добытой у ближайших гноллов-гнилошкуров.",al={"who starts rot hide origins","where do i get rot hide origins","кто дает происхождение гнилошкуров","где взять происхождение гнилошкуров"}},{q="Почему Ренферрел отправляет образец Бетору Ледострелу?",a="Ренферрел обнаруживает, что лимфа гнилошкуров пропитана некромантической магией и магией чернокнижников. Поскольку одна алхимия не объясняет действующих чар, он обращается к тайным познаниям Бетора Ледострела в Подгороде, чтобы определить магическое происхождение лимфы.",al={"why bethor iceshard","why give sample to mage","почему бетор ледострел","почему отдать образец магу"}},{q="Где находится Бетор Ледострел?",a="Бетор Ледострел живет в Магическом квартале Подгорода среди исследователей тайной магии и учителей.",al={"bethor location","where is bethor iceshard","где бетор","где бетор ледострел"}},{q="Кто такие Гнилошкуры?",a="Гнилошкуры — гноллы-нежить, бродящая по Серебряному бору. В отличие от обычных неразумных зверей, их разложение вызвано искусственно мерзкими магическими опытами.",al={"what are rot hides","rot hide gnolls silverpine","кто такие гнилошкуры","гноллы гнилошкуры серебряный бор"}},{q="Что происходит, когда вы доставляете образец Бетору?",a="Бетор узнает в жидкости древнюю могущественную магию и отмечает, что очень давно не встречал именно этих заклинаний. Он сразу начинает читать заклинание прорицания, чтобы найти источник магии.",al={"what does bethor do","bethor iceshard reaction","что делает бетор","реакция бетора ледострела"}},{q="Какое задание следующее?",a="После этой доставки и прорицания Бетор посылает искателя приключений выполнять задание «Тул Коготь Ворона», чтобы разыскать мага-отступника, повинного в порче гноллов.",al={"next quest after rot hide origins","follow up to rot hide origins","следующее задание после происхождения гнилошкуров","продолжение происхождения гнилошкуров"}}},fp="16,341,29.531.0,22.497.1,35.194.0,54.252.0,33.109.0,23.165.0,51.233.0,22.175.1"}
P.entries["quest:445"] = {n="Доставка в Серебряный бор",s="Это поручение — важное курьерское задание, связывающее исследования Королевского фармацевтического общества в Брилле с его работой в Серебряном бору. По поручению аптекаря Юхана вы доставляете ценные результаты аптекарю Ренферрелу в Гробницу, чтобы помочь в создании Новой чумы Темной Госпожи.",h="Это поручение — важное курьерское задание, связывающее исследования Королевского фармацевтического общества в...",kw={"brill","delivery to silverpine forest","johaan","new plague","renferrel","royal apothecary society","sepulcher","silverpine","брилл","доставка в серебряный бор","юхан","новая чума","ренферрел","королевское фармацевтическое общество","гробница","серебряный бор"},ang={["faction:Horde"]="Хотя алхимические исследования Отрекшихся нередко вызывают недоумение у других союзников Орды, безопасный проход и курьерская работа на дороге Серебряного бора обеспечивают защиту северных земель.",["race:Undead"]="Доставка этих исследований — прямая служба леди Сильване и выживанию Отрекшихся, помощь в осуществлении главной цели Королевского фармацевтического общества."},sec={{t="Общество, объединенное целью",b="Королевское фармацевтическое общество действует под прямым командованием леди Сильваны Ветрокрылой и занимается созданием Новой чумы, способной уничтожить как живых, так и Плеть. Изолированные лаборатории на землях Отрекшихся не могут работать в отрыве друг от друга: выживание и прогресс требуют постоянной связи. В Брилле аптекарь Юхан собрал результаты опытов, которые необходимо без промедления передать другим исследователям."},{t="Форпост на юге",b="Серебряный бор — следующий рубеж расширения и исследований Отрекшихся. Аптекарь Ренферрел, находясь в Гробнице, руководит биохимическими испытаниями среди таких местных угроз, как воргены Лунной Ярости, разбойники-люди и уцелевшие силы Плети. Получив записи Юхана из Тирисфальских лесов, Ренферрел включает новые алхимические данные в собственные местные опыты, продвигая великий замысел Общества."}},faq={{q="Почему аптекарь Юхан отправляет эти документы?",a="От членов Королевского фармацевтического общества ожидают, что они будут делиться открытиями, чтобы ускорить создание Новой чумы. Юхану нужно, чтобы его последние результаты из Тирисфальских лесов доставили на юг, где другие исследователи смогут развить его работу.",al={"why courier findings","johaan notes","why send research","зачем доставлять результаты","записи юхана","зачем отправлять исследования"}},{q="Где находится Гробница?",a="Гробница — главный форпост Отрекшихся в Серебряном бору. Она лежит к югу от границы с Тирисфальскими лесами и к юго-западу от Подгорода, у главной дороги, вьющейся через лес.",al={"where is sepulcher","finding renferrel","sepulcher location","где гробница","как найти ренферрела","расположение гробницы"}},{q="Кто такой аптекарь Ренферрел?",a="Ренферрел — видный член Королевского фармацевтического общества, находящийся в Гробнице. Он руководит полевыми испытаниями и изучает необычные ингредиенты, найденные в Серебряном бору, отчитываясь перед высшим руководством Общества в Подгороде.",al={"renferrel role","who is renferrel","renferrel silverpine","роль ренферрела","кто такой ренферрел","ренферрел серебряный бор"}},{q="Что такое Новая чума, о которой говорит Юхан?",a="Новая чума — особая алхимическая зараза, создаваемая Королевским фармацевтическим обществом по приказу леди Сильваны Ветрокрылой. Она предназначена для истребления как живых врагов, так и немертвых слуг Короля-лича.",al={"new plague","sylvanas plague","what plague","новая чума","чума сильваны","какая чума"}},{q="Что за Некрополь упоминает Ренферрел?",a="Ренферрел упоминает, что должен отправить образцы в «Некрополь», но в этом разговоре не уточняется, какой именно некрополь он имеет в виду.",al={"necropolis renferrel","renferrel samples","samples to necropolis","некрополь ренферрел","образцы ренферрела","образцы в некрополь"}},{q="Почему используют искателя приключений, а не официальных гонцов?",a="Курьеры Отрекшихся сталкиваются на дорогах с опасностями: одичавшие воргены, агрессивные звери и враждебные выжившие люди. Доверив исследования здоровому искателю приключений, можно быть уверенным, что хрупкие алхимические записи дойдут до Гробницы целыми, а заодно получить еще одного помощника для местных дел.",al={"why me courier","why adventurer messenger","почему я курьер","почему искатель приключений посыльный"}}},fp="29,303,26.443.0,20.420.0,49.239.0,31.198.0,28.249.0,43.230.0,42.132.0,53.277.0"}
P.entries["quest:446"] = {n="Тул Коготь Ворона",s="После обнаружения странного ихора Гнилошкур в Серебряном бору Бетор Ледострел признает в этом мерзком веществе дело рук своего бывшего коллеги-предателя Тула Когтя Ворона. Чтобы помочь Отрекшимся отразить гноллов Гнилошкур, Бетор готовит особый свиток с контрзаклинаниями для аптекаря Ренферрела.",h="После обнаружения странного ихора Гнилошкур в Серебряном бору Бетор Ледострел признает в этом мерзком...",kw={"apothecary renferrel","bethor iceshard","fenris isle","rot hide","scourge","sepulcher","silverpine","thule ravenclaw","аптекарь ренферрел","бетор ледострел","остров фенриса","гнилошкуры","плеть","гробница","серебряный бор","тул коготь ворона"},ang={["class:Mage"]="Конфликт Бетора и Тула подчеркивает трагический раскол среди бывших магов Лордерона: одни пали жертвой некромантии, другие сохранили арканную дисциплину даже в нежизни.",["faction:Horde"]="Искоренение остатков Плети в Лордероне закрепляет единственный плацдарм Орды в Восточных королевствах.",["race:Undead"]="Для Отрекшихся жизненно важно остановить Тула Когтя Ворона: его власть над Островом Фенриса угрожает и Гробнице, и западным подступам к Столице."},sec={{t="Коллега, ставший предателем",b="Когда курьер приносит образец ихора Гнилошкур Бетору Ледострелу в Квартал магов Подгорода, опытный чародей сразу узнает характерный арканный резонанс. Это дистиллят Тула Когтя Ворона, некогда блестящего и многообещающего молодого мага, учившегося вместе с Бетором до Третьей войны. Движимый жаждой темной силы, Тул бросил собратьев и присягнул Плети и Королю-личу, отказавшись от человечности задолго до падения Лордерона."},{t="Хозяин Острова Фенриса",b="Бетор встревожен известием, что Коготь Ворона не только пережил войну, но и укрепился в Крепости Фенриса на Острове Фенриса посреди озера Лордамер. Оттуда Тул командует гноллами Гнилошкур, наделяя их мерзкой магией и посылая тревожить границы Отрекшихся. Опираясь на глубокое знание арсенала чар бывшего соратника, Бетор пишет особый свиток, призванный нейтрализовать фирменные проклятия и обереги Тула."},{t="Алхимические контрмеры",b="Получив свиток Бетора, курьер возвращается в Гробницу и передает его аптекарю Ренферрелу из Королевского фармацевтического общества. Увлеченный мощными заклинаниями, записанными магом Подгорода, Ренферрел начинает сочетать высшую магию с алхимическими зельями Общества. Полученная смесь создана специально для того, чтобы разрушить порчу Когтя Ворона и расчистить путь к штурму Крепости Фенриса."}},faq={{q="Кто такой Тул Коготь Ворона?",a="Тул Коготь Ворона был многообещающим молодым человеком-магом, обученным в Даларане и учившимся вместе с Бетором Ледострелом. Когда Король-лич начал распространять порчу по Лордерону, Тул предал собратьев ради службы Плети и в итоге возглавил гноллов Гнилошкур на Острове Фенриса.",al={"thule lore","who is thule","thule ravenclaw backstory","предания о туле","кто такой тул","история тула когтя ворона"}},{q="Почему Бетор Ледострел знает магию Тула?",a="Бетор и Тул были коллегами и собратьями-чародеями до падения Лордерона. Поскольку они вместе изучали тайные искусства, Бетор хорошо знаком с любимыми заклинаниями, магической теорией и проклятиями Тула.",al={"bethor and thule","how does bethor know thule","bethor iceshard connection","бетор и тул","откуда бетор знает тула","связь бетора ледострела"}},{q="Для чего нужен Свиток Бетора?",a="Свиток Бетора содержит сложные контрзаклинания, созданные специально для разрушения чар Тула. Аптекарь Ренферрел использует их, чтобы сварить алхимическое зелье, защищающее бойцов Отрекшихся от порчи Когтя Ворона.",al={"bethors scroll","scroll purpose","what does the scroll do","свиток бетора","назначение свитка","что делает свиток"}},{q="Чем гноллы Гнилошкуры опасны в Серебряном бору?",a="В отличие от обычных диких зверей, гноллы Гнилошкуры организованы и усилены Тулом Когтем Ворона с помощью некромантии Плети. Из своего оплота на Острове Фенриса они устраивают организованные набеги на поселения и патрули Отрекшихся по всему Серебряному бору.",al={"rot hide gnolls","why fight gnolls","fenris isle gnolls","гноллы гнилошкуры","зачем сражаться с гноллами","гноллы острова фенриса"}},{q="Где происходит это задание?",a="Задание начинается у Бетора Ледострела в Магическом квартале Подгорода и завершается у аптекаря Ренферрела в Гробнице в Серебряном бору.",al={"thule ravenclaw turn in","where to turn in thule ravenclaw","scroll delivery location","тул коготь ворона сдать","где сдать тула когтя ворона","место доставки свитка"}},{q="Что происходит после того, как Ренферрел получает свиток?",a="Когда противоядие готово, Ренферрел отправляет вас доложить Верховному палачу Хадрику перед полномасштабным штурмом Острова Фенриса, чтобы уничтожить Тула Когтя Ворона и вернуть остров.",al={"what happens next","after thule ravenclaw quest","fenris isle attack","что дальше","после задания тул коготь ворона","атака на остров фенриса"}}},fp="15,336,26.474.0,25.452.1,26.422.1,23.293.0,44.223.0,33.236.0,51.260.0,33.154.0,49.184.1"}
P.entries["quest:447"] = {n="Рецептура смерти",s="«Рецептура смерти» — алхимическое поручение аптекаря Ренферрела из Гробницы в Серебряном бору. Герои собирают сердца гризли и кровь паукообразных и доставляют нестойкие биологические реагенты Мастеру аптекарю Фаранеллу в Подгород, чтобы помочь в создании смертоносной Новой чумы Отрекшихся.",h="«Рецептура смерти» — алхимическое поручение аптекаря Ренферрела из Гробницы в Серебряном бору.",kw={"faranell","new plague","renferrel","royal apothecary society","silverpine","skittering dark","undercity","фаранелл","новая чума","ренферрел","королевское фармацевтическое общество","серебряный бор","струящаяся тьма","подгород"},ang={["faction:Horde"]="Пока аптекари Отрекшихся добиваются победы с помощью смертоносных биологических составов, такие жуткие методы держатся в строгой тайне от руководства Орды в Калимдоре, чтящего честь.",["race:Undead"]="Вклад в исследования чумы, которые ведет Королевское фармацевтическое общество, — один из высших долгов, который может взять на себя честолюбивый Отрекшийся, чтобы защитить свое хрупкое королевство от Плети и людей."},sec={{t="Оружие против двух врагов",b="Находясь на передовой в Серебряном бору, аптекарь Ренферрел понимает мрачный расклад, стоящий перед народом Сильваны. Окруженным неисчислимыми легионами Артаса и уцелевшими остатками человечества, им не на что надеяться в обычной войне. Главная цель Отрекшихся — создать Новую чуму, рукотворную заразу, способную сгноить и живых людей, и немертвую Плеть. Полевые исследования Ренферрела показали, что сочетание паучьего яда из Струящейся Тьмы с токсинами, скопившимися в сердцах местных медведей, дает смертоносную основу."},{t="Отправка в Апотекариум",b="Когда органы и кровь собраны в глуши Серебряного бора, их нужно доставить под руины Лордерона, в сердце Апотекариума. Там Мастер аптекарь Фаранелл руководит великим замыслом Королевского фармацевтического общества. Фаранелл тут же принимает образцы Ренферрела и проверяет их заразные свойства, совершенствуя формулы, которые однажды могут обеспечить превосходство Отрекшихся на всем континенте."}},faq={{q="Для чего собирать сердца медведей и кровь пауков?",a="Исследования аптекаря Ренферрела показали, что паучья кровь из Струящейся Тьмы смертельно реагирует в сочетании с токсинами из сердец седых медведей. Вместе эти реагенты служат важным сырьем для испытаний и разработки Новой чумы Королевского фармацевтического общества.",al={"why bear hearts","why spider blood","what is this recipe for","зачем сердца медведей","зачем паучья кровь","для чего этот рецепт"}},{q="Кто такой Мастер аптекарь Фаранелл?",a="Мастер аптекарь Фаранелл — глава Королевского фармацевтического общества, находящийся в квартале Апотекариума в Подгороде. Он руководит всеми исследованиями по созданию Новой чумы от имени леди Сильваны Ветрокрылой.",al={"faranell lore","who is faranell","master apothecary","предания о фаранелле","кто такой фаранелл","мастер аптекарь"}},{q="Почему Отрекшиеся хотят создать Новую чуму?",a="Отрекшиеся уступают Плети числом и презираемы живыми людьми, поэтому им не хватает военной силы для затяжной обычной войны. Особая Новая чума создается, чтобы истреблять и живых противников, и немертвую Плеть, обеспечивая их выживание и самостоятельность.",al={"why make new plague","forsaken plague motivation","new plague lore","зачем создавать новую чуму","мотив отрекшихся","предания о новой чуме"}},{q="Где находится аптекарь Ренферрел?",a="Аптекарь Ренферрел проводит исследования в Гробнице, главном поселении Отрекшихся в Серебряном бору.",al={"renferrel location","where is renferrel","где ренферрел","местонахождение ренферрела"}},{q="Где находится Струящаяся Тьма?",a="Струящаяся Тьма — кишащая паукообразными глушь к северо-западу от Гробницы в Серебряном бору, где обитают гигантские пауки, чья кровь нужна Ренферрелу.",al={"skittering dark location","where to find spiders silverpine","где струящаяся тьма","где найти пауков в серебряном бору"}},{q="Продолжается ли это задание?",a="Да. Мастер аптекарь Фаранелл использует доставленные реагенты для продолжения опытов, что напрямую ведет к дальнейшим заданиям в Апотекариуме по доработке и испытанию смертоносной смеси.",al={"recipe for death follow up","is there a part 2","продолжение рецептуры смерти","есть ли вторая часть"}}},fp="18,338,25.584.0,28.450.0,63.277.0,34.222.0,48.270.0,38.130.0,29.169.0,33.190.0"}
P.entries["quest:448"] = {n="Доложиться Хадрику",s="«Доложиться Хадрику» — военное донесение Орды, направляющее героев в Гробнице к полевому командиру Серебряного бора. После расследования аптекаря Ренферрела и Бетора Ледострела о присутствии Плети на озере Лордамер Верховный палач Хадрик координирует военную подготовку, необходимую для штурма острова Фенриса. Это переход от магической разведки к прямым тактическим боевым действиям.",h="«Доложиться Хадрику» — военное донесение Орды, направляющее героев в Гробнице к полевому командиру...",kw={"fenris","hadrec","iceshard","ravenclaw","renferrel","sepulcher","silverpine","thule","фенрис","хадрик","ледострел","коготь ворона","ренферрел","гробница","серебряный бор","тул"},ang={["faction:Horde"]="Гробница координирует западную оборону Орды в Лордероне, прикрывая подступы к руинам Столицы как от застав Плети, так и от уцелевших людей.",["race:Undead"]="Для Отрекшихся Тул Коготь Ворона воплощает порабощающую волю Короля-лича, подступившую к самому порогу, поэтому его уничтожение жизненно важно для выживания их народа."},sec={{t="Обострение в Серебряном бору",b="Пока аптекарь Ренферрел и маг Бетор Ледострел прилагали немало усилий, чтобы определить угрозу, исходящую от мятежного некроманта Тула Когтя Ворона, одного научного изучения оказалось мало, чтобы сокрушить растущий оплот Плети. Поскольку Коготь Ворона активно подчинял беспокойных мертвецов на всем острове Фенриса, Ренферрел понял, что проблема выходит далеко за рамки алхимических или магических решений. Остановить распространяющуюся заразу могли лишь крепкая сталь и дисциплинированные силы военных Отрекшихся, и дело перешло со столов аптекарей прямо на стол командира."},{t="Арсенал Верховного палача",b="Верховный палач Хадрик, расположившийся в склепах Гробницы, руководит от имени Темной Госпожи всеми стратегическими операциями в Серебряном бору. Когда до него дошли мрачные предупреждения Бетора о Когте Ворона, Хадрик действовал без промедления: он знал, что укрепившийся на западном берегу Лордамера некромант смертельно опасен для флангов Подгорода. Чтобы удар по островной крепости удался, Хадрик открывает оружейную местного гарнизона и снаряжает бойцов авангарда, прежде чем отправить их прямо в бой."}},faq={{q="Кто такой Верховный палач Хадрик?",a="Верховный палач Хадрик — командующий военными силами Отрекшихся, расквартированными в Гробнице. Он руководит обороной на передовой и наступательными операциями по всему Серебряному бору и подчиняется напрямую руководству Подгорода.",al={"hadrec","who is hadrec","sepulcher commander","хадрик","кто такой хадрик","командир гробницы"}},{q="Почему аптекарь Ренферрел отправляет вас к Хадрику?",a="Аптекарь Ренферрел и Бетор Ледострел обнаружили, что Тул Коготь Ворона собрал на острове Фенриса опасное войско Плети. Поскольку для уничтожения укрепившегося некроманта нужны военная сила и надлежащее снаряжение, а не одна алхимия, Ренферрел направляет вас к командиру гарнизона.",al={"why report to hadrec","renferrel hadrec connection","почему доложиться хадрику","ренферрел и хадрик"}},{q="Где находится Гробница?",a="Гробница — укрепленное поселение Отрекшихся и комплекс склепов в центре Серебряного бора. Это главный оплот Орды и плацдарм для операций в регионе.",al={"where is sepulcher","sepulcher location","где гробница","расположение гробницы"}},{q="Кто такой Тул Коготь Ворона?",a="Тул Коготь Ворона — могущественный некромант Плети, захвативший крепость Фенриса на острове Фенриса посреди озера Лордамер. Он поднимает мертвых и создает действующий плацдарм прямо у восточного берега Серебряного бора.",al={"thule ravenclaw","thule lore","тул коготь ворона","предания о туле"}},{q="Что происходит после доклада Хадрику?",a="Хадрик выдает вам припасы из оружейной Гробницы и приказывает немедленно нанести военный удар по острову Фенриса, чтобы уничтожить Тула Когтя Ворона и сломить власть Плети над озером Лордамер.",al={"what next after hadrec","next quest hadrec","что дальше после хадрика","следующее задание хадрик"}},{q="Кто такой Бетор, о котором говорит Хадрик?",a="Бетор Ледострел — маг из Отрекшихся, живущий в Магическом квартале Подгорода. Его магические прорицания помогли выяснить истинную природу и опасность ритуалов Тула Когтя Ворона.",al={"who is bethor","bethor iceshard","кто такой бетор","бетор ледострел"}}},fp="16,408,24.571.0,27.524.0,28.235.0,49.294.0,31.183.0,23.194.0,39.189.0,34.181.0"}
P.entries["quest:449"] = {n="Отчет стражей смерти",s="«Отчет стражей смерти» — важное военное курьерское поручение: доставить донесение Верховному палачу Хадрику в Гробницу. Позаботившись о раненых стражах смерти на севере, вы несете их разведданные о неожиданной активности Плети высшему командованию Отрекшихся. Это донесение меняет оценку Отрекшимися их положения в Серебряном бору.",h="«Отчет стражей смерти» — важное военное курьерское поручение: доставить донесение Верховному палачу Хадрику в...",kw={"deathstalker","erland","hadrec","quinn","rane yorick","report","scourge","sepulcher","silverpine","undercity","страж смерти","эрланд","хадрик","квинн","ран йорик","донесение","плеть","гробница","серебряный бор","подгород"},ang={["class:Rogue"]="Стражи смерти — вершина шпионажа Отрекшихся; доставка их важных донесений показывает, что вы заодно с главными теневыми агентами Темной Госпожи.",["faction:Horde"]="Борьба Отрекшихся за Серебряный бор против Плети жизненно важна для создания надежного плацдарма Орды на севере Лордерона.",["race:Undead"]="Доставка этих сведений напрямую способствует расширению Подгорода и подтверждает вашу надежность в глазах Верховного палача Хадрика и сети стражей смерти."},sec={{t="Разведка с передовой",b="Стражи смерти — глаза, уши и кинжалы Темной Госпожи, они проникают в дикие земли впереди обычных войск. Возле границы Тирисфаля и Серебряного бора передовой дозор встретил жестокое сопротивление, пока наносил на карту передвижения врага. Страж смерти Квинн едва пережил свои раны, а Эрланд с боем пробился к безопасности, но их разведка добыла сведения, крайне важные для занятия Отрекшимися Серебряного бора."},{t="Фактор Плети",b="Когда Верховный палач Хадрик изучает запечатанный полевой отчет, тот подтверждает мрачные вести: бездумные силы Плети присутствуют в Серебряном бору гораздо плотнее и агрессивнее, чем предполагали стратеги Подгорода. Командованию Гробницы придется готовиться не просто к занятию заброшенных людских деревушек и усмирению диких зверей, но и к организованному сопротивлению Плети в борьбе за регион."}},faq={{q="Что такое донесение стражей смерти?",a="Это полевое донесение, написанное Стражем смерти Ран Йорик от имени ее раненого разведывательного отряда. В нем собраны наблюдения о враждебных угрозах, особенно о неожиданной активности Плети на севере Серебряного бора, и эти данные доставляются напрямую региональному командиру в Гробнице.",al={"deathstalker report","what is the report","what did yorick give me","донесение стражей смерти","что за донесение","что дал мне йорик"}},{q="Кто такой Верховный палач Хадрик?",a="Верховный палач Хадрик — военный командир, отвечающий за операции Отрекшихся в Серебряном бору. Находясь в Гробнице, он координирует разведчиков, оборонительные рубежи и общую кампанию по изгнанию из региона как Плети, так и враждебных людей.",al={"hadrec","high executor hadrec","sepulcher commander","хадрик","верховный палач хадрик","командир гробницы"}},{q="Why was the report's information a surprise to Hadrec?",a="Руководство Отрекшихся считало, что Плеть в Серебряном бору рассеяна и малочисленна по сравнению с тяжелыми боями в Тирисфальских лесах и Чумных землях. Потери и открытия стражей смерти доказали, что приспешники Короля-лича закрепились и опасны даже так далеко на юге.",al={"why surprised","hadrec reaction","scourge in silverpine","почему удивлен","реакция хадрика","плеть в серебряном бору"}},{q="Кто такие стражи смерти?",a="Стражи смерти — элитный тайный орден Отрекшихся: убийцы, шпионы и передовые разведчики, подчиняющиеся напрямую леди Сильване Ветрокрылой. Они действуют на спорных территориях и устраняют угрозы до прихода регулярной армии.",al={"deathstalkers","deathstalker lore","forsaken rogues","стражи смерти","предания о стражах смерти","разбойники отрекшихся"}},{q="Где находится Гробница?",a="Гробница — склеп и главный лагерь в центре Серебряного бора, к западу от главной дороги с севера на юг. Это основной гарнизон и место отдыха сил Отрекшихся, действующих в этих землях.",al={"where is sepulcher","sepulcher location","где гробница","расположение гробницы"}},{q="Что происходит после того, как Хадрик прочтет донесение?",a="Осознав серьезность положения и растущие угрозы в Серебряном бору, Хадрик направляет вас к другим специалистам в Гробнице, начиная с аптекаря Ренферрела, чтобы помочь в разработке мер против местных угроз.",al={"next quest","what now","after hadrec","следующее задание","что теперь","после хадрика"}}},fp="25,369,22.462.0,18.412.0,32.304.0,28.257.0,54.284.0,26.262.0,31.240.0,43.254.0"}
P.entries["quest:4495"] = {n="Добрый друг",s="Дирания Серебряное Сияние тревожится, когда ее постоянный гость Иверрон не приходит вовремя в Альдрассил. Зная, что он часто бывает на холмах возле кишащего пауками Паучьего логова на севере, она просит проходящих мимо искателей приключений найти его.",h="Дирания Серебряное Сияние тревожится, когда ее постоянный гость Иверрон не приходит вовремя в Альдрассил.",kw={"a good friend","aldrassil","dirania silvershine","iverron","shadowglen","shadowthread cave","spiders","teldrassil","добрый друг","альдрассил","дирания серебряное сияние","иверрон","тенистая долина","паучье логово","пауки","тельдрассил"},ang={["class:Druid"]="Друиды, помнящие о природном равновесии, поймут, что агрессивные лесные пауки возле Паучьего логова — признак более широкой порчи, поразившей великое древо.",["race:NightElf"]="Для юных кальдораев, начинающих путь под Альдрассилом, исполнение просьбы Дирании — ранний урок общинной ответственности и распространяющихся угроз, тревожащих некогда мирную долину."},sec={{t="Пропавший гость",b="В тихих ветвях Тенистой долины жизнь течет по заведенному порядку, и любое отклонение сразу бросается в глаза. Дирания Серебряное Сияние, занимаясь делами под защитой кроны Альдрассила, привыкла, что Иверрон приходит к ней каждый день как по часам. Когда проходят часы, а его все нет, тревога заставляет ее искать помощи у тех, кто отправляется в дикие края."},{t="Опасность у Паучьего логова",b="Иверрон, как известно, любит бродить у северных лощин Тенистой долины, несмотря на растущую угрозу со стороны лесных пауков. Поскольку Паучье логово кишит агрессивными паукообразными, сходить с проторенных троп все опаснее для неосторожных путников. На неровных склонах к западу от входа в пещеру находится Иверрон, прячущийся и отчаянно нуждающийся в помощи."}},faq={{q="Кто такая Дирания Серебряное Сияние?",a="Дирания Серебряное Сияние — ночной эльф, живущая в Тенистой долине под Альдрассилом. Она каждый день дружески общается с Иверроном и сразу замечает, когда он не приходит в обычное время.",al={"dirania","dirania silvershine lore","who starts a good friend","дирания","предания о дирании серебряное сияние","кто дает задание добрый друг"}},{q="Кто такой Иверрон?",a="Иверрон — ночной эльф из Тенистой долины, известный тем, что бродит по холмам возле Паучьего логова. Не явившись на ежедневную встречу с Диранией Серебряным Сиянием, он оказывается застрявшим на утесах к западу от входа в пещеру.",al={"iverron","where is iverron","who is the missing friend","иверрон","где иверрон","кто пропавший друг"}},{q="Где можно найти Иверрона?",a="Иверрон прячется среди камней и кустов на склоне холма прямо к западу от входа в Паучье логово, в северной части Тенистой долины.",al={"iverron location","finding iverron","shadowthread cave iverron","где иверрон","поиски иверрона","паучье логово иверрон"}},{q="Почему северная пещера считается опасной?",a="Паучье логово и окрестные склоны кишат ядовитыми лесными пауками. Растущая порча в Тельдрассиле растревожила этих тварей, и теперь в этой местности опасно одиноким путникам.",al={"why is shadowthread cave dangerous","spiders in shadowglen","spider cave teldrassil","почему паучье логово опасно","пауки в тенистой долине","паучья пещера тельдрассил"}},{q="Что происходит после того, как вы найдете Иверрона?",a="Когда вы находите Иверрона, он рассказывает, что его злоключение у паучьей пещеры поставило его в отчаянное положение, и в следующем задании, «Друг в беде», начинаются поиски лечения.",al={"quest after a good friend","next step for iverron","a friend in need quest","задание после добрый друг","что дальше с иверроном","задание друг в беде"}},{q="Почему Дирания так быстро забеспокоилась об Иверроне?",a="Иверрон навещает Диранию каждый день в один и тот же час. Поскольку он опоздал на несколько часов и часто бродил возле опасных паучьих лощин, она боялась худшего.",al={"why is dirania worried","iverron routine","why did dirania notice","почему дирания волнуется","распорядок иверрона","почему дирания заметила"}}},fp="13,242,17.400.0,26.395.0,27.205.0,15.221.0,27.147.0,46.204.0,35.181.1,48.196.0"}
P.entries["quest:45"] = {n="Судьба Рольфа",s="«Судьба Рольфа» — задание Альянса в Элвиннском лесу: нужно пройти по следу двух пропавших стражников Штормграда. После того как у берега озера Каменных Столбов найдены изувеченные останки стражника Малакая, след перепончатых лап ведет на восток, во враждебную деревню мурлоков, чтобы узнать, что стало с его товарищем Рольфом.",h="«Судьба Рольфа» — задание Альянса в Элвиннском лесу: нужно пройти по следу двух пропавших стражников...",kw={"elwynn forest","guard thomas","malakai","murlocs","rolf","rolf hartford","stone cairn lake","элвиннский лес","стражник томас","малакай","мурлоки","рольф","рольф хартфорд","озеро каменных столбов"},ang={["class:Warrior"]="Стоя над телом Рольфа Хартфорда, воин получает суровое напоминание о кровавой реальности, с которой сталкиваются пехотинцы на передовой, служащие королевству.",["faction:Alliance"]="Находка Рольфа подтверждает уязвимость сельских границ Штормграда, где нехватка гарнизонов оставляет обычные патрули беззащитными перед смертоносными нападениями из дикой природы."},sec={{t="След перепончатых лап",b="Стражник Томас отправил патрули в восточную часть Элвиннского леса для отпора растущим угрозам, но двое стражников, Малакай и Рольф, пропали у берегов озера Каменных Столбов. Осмотр наполовину съеденных останков Малакая показывает перепончатые следы в грязи, ведущие на восток вдоль кромки воды прямо к жалкому лагерю мурлоков."},{t="Конец патруля",b="След приводит вас в сердце прибрежного поселения мурлоков. Там лежит еще один труп, ограбленный этими тварями. На шее павшего солдата висит медальон с надписью, подтверждающей, что это пехотинец Рольф Хартфорд: ни один из стражников не пережил засады."}},faq={{q="Кем был Рольф?",a="Рольф Хартфорд был пехотинцем Штормграда, назначенным патрулировать восточную часть Элвиннского леса вместе со стражником Малакаем под началом Стражника Томаса. Обоих стражников одолели и убили мурлоки у озера Каменных Столбов.",al={"who is rolf","footman rolf","rolf hartford","кто такой рольф","пехотинец рольф","рольф хартфорд"}},{q="Где находится тело Рольфа?",a="Труп Рольфа лежит дальше на восток вдоль южного берега озера Каменных Столбов, в деревне мурлоков у границы озера.",al={"rolf location","where is rolf","find rolf","где рольф","местонахождение рольфа","найти рольфа"}},{q="Почему стражники оказались возле озера Каменных Столбов?",a="Стражник Томас расставил стражников вдоль рек и озер востока Элвиннского леса, чтобы следить за вторжениями мурлоков и гноллов, но малочисленные патрули оказались уязвимы для внезапных согласованных нападений.",al={"why were guards lost","what were guards doing","guard patrol elwynn","почему пропали стражники","что делали стражники","патруль элвиннский лес"}},{q="Как подтвердить, что труп принадлежит Рольфу?",a="На шее изувеченного трупа висит металлический медальон с четкой надписью «Пехотинец Рольф Хартфорд».",al={"rolf medallion","identifying rolf","медальон рольфа","опознание рольфа"}},{q="Что происходит после того, как вы найдете Рольфа?",a="Когда печальная судьба Малакая и Рольфа подтверждена, вам поручают вернуться на запад, к мосту у Лесопилки Восточной долины, и сообщить Стражнику Томасу мрачные новости.",al={"next quest after rolf","what to do after rolf","следующее задание после рольфа","что делать после рольфа"}},{q="Представляют ли мурлоки озера Каменных Столбов необычную угрозу?",a="Активность мурлоков в Элвиннском лесу стала необычно агрессивной и организованной: они продвигаются вглубь суши к озеру Каменных Столбов и рекам, угрожая местной торговле и одиноким патрулям.",al={"murloc threat elwynn","why murlocs attacking","угроза мурлоков элвиннский лес","почему мурлоки нападают"}}},fp="20,314,24.348.0,17.298.1,13.206.1,29.137.1,46.199.0,46.115.1,32.168.1,54.175.0"}
P.entries["quest:450"] = {n="Рецептура смерти",s="Мастер аптекарь Фаранелл поручает авантюристам Орды вернуть утерянные исследования аптекаря Берара из Деревни Погребальных Костров. Берар стал жертвой темной магии верховного мага Аругала и оставил важные записи о древней порче, уничтожившей всю водную жизнь озера Лордамер.",h="Мастер аптекарь Фаранелл поручает авантюристам Орды вернуть утерянные исследования аптекаря Берара из Деревни...",kw={"arugal","berard","faranell","journal","lordamere","pyrewood","renferrel","sepulcher","аругал","берар","фаранелл","журнал","лордамер","погребальных костров","ренферрел","гробница"},ang={["faction:Horde"]="Помощь Королевскому фармацевтическому обществу в Серебряном бору помогает защитить границы Отрекшихся от диких ужасов, выпущенных Аругалом.",["race:Undead"]="Королевское фармацевтическое общество проявляет холодный прагматизм: когда многообещающий коллега вроде Берара теряется в безумии, его личная трагедия игнорируется ради спасения его смертоносных исследований."},sec={{t="Разум, потерянный во тьме",b="До своего падения аптекарь Берар считался одним из самых многообещающих исследователей Королевского фармацевтического общества. Он служил в Деревне Погребальных Костров и изучал прошлые экологические катастрофы, чтобы помочь алхимическим изысканиям Отрекшихся. Однако когда верховный маг Аругал обрушил свое темное колдовство на Серебряный бор, Берар поддался проклятию и превратился в безвольного слугу, подчиненного воле мага."},{t="Тайны озера Лордамер",b="Хотя Мастер аптекарь Фаранелл считает Берара пропащим, его исследования по-прежнему чрезвычайно ценны для Общества. Берар каталогизировал свойства забытой чумы, давным-давно уничтожившей всю водную жизнь озера Лордамер. Если вернуть его журнал из трактира Деревни Погребальных Костров и доставить его аптекарю Ренферрелу в Гробницу, Королевское фармацевтическое общество сможет приспособить эти смертоносные свойства для арсенала Темной Госпожи."}},faq={{q="Кто такой аптекарь Берар?",a="Аптекарь Берар был талантливым исследователем Королевского фармацевтического общества в Серебряном бору. Его многообещающая карьера оборвалась, когда верховный маг Аругал наслал на край темное проклятие, разрушившее разум Берара и превратившее его в раба в Деревне Погребальных Костров.",al={"berard lore","who was berard","apothecary berard pyrewood","берар","кто такой берар","аптекарь берар","деревня погребальных костров"}},{q="Зачем Королевскому фармацевтическому обществу журнал Берара?",a="До угасания рассудка Берар документировал древнюю чуму, давным-давно убившую всю водную жизнь озера Лордамер. Общество ищет эти записи, чтобы понять опасный возбудитель и включить его смертоносные механизмы в свои исследования.",al={"why get the journal","berards journal purpose","lake lordamere plague notes","зачем нужен журнал","журнал берара","записи о чуме озера лордамер"}},{q="Где находится журнал Берара?",a="Журнал хранится в кабинете Берара на верхнем этаже трактира Деревни Погребальных Костров, в дальней части деревни. Пораженный болезнью аптекарь по-прежнему охраняет свои прежние покои.",al={"where is the journal","find berard journal","pyrewood inn journal","где журнал","найти журнал берара","журнал в трактире"}},{q="Кому передают найденный журнал?",a="Журнал нужно доставить аптекарю Ренферрелу, который руководит полевой работой Королевского фармацевтического общества из Гробницы в Серебряном бору.",al={"who turns in berard journal","who do i bring the journal to","where take journal","кому сдать журнал берара","кому отнести журнал","куда нести журнал"}},{q="Что случилось с Деревней Погребальных Костров?",a="Деревня Погребальных Костров попала под оскверняющее влияние верховного мага Аругала, который наслал темную магию из соседней Крепости Темного Клыка. Проклятие искажает разум и тела жителей, подчиняя их темной воле Аругала.",al={"pyrewood curse","what is wrong with pyrewood","arugal curse pyrewood","проклятие деревни","что с деревней погребальных костров","проклятие аругала"}},{q="Кто такой Мастер аптекарь Фаранелл?",a="Мастер аптекарь Фаранелл возглавляет Королевское фармацевтическое общество и руководит его работой из Апотекариума в Подгороде. Он лично наблюдает за созданием новых болезней и ядов, призванных защитить Отрекшихся и уничтожить их врагов.",al={"faranell","who gives recipe for death","apothecary leader undercity","фаранелл","кто дает рецептура смерти","глава аптекарей подгород"}}},fp="18,279,21.406.0,29.469.1,25.269.0,60.266.0,34.183.0,35.156.0,34.221.0,34.245.0"}
P.entries["quest:451"] = {n="Рецептура смерти",s="«Рецептура смерти» завершает расследование находок павшего исследователя: авантюристам поручено собрать редкие биологические реагенты на озере Лордамер. Добыв собранные мхи и странную опухоль, Отрекшиеся доставляют важные компоненты Мастеру аптекарю Фаранеллу в Подгород. Эта работа напрямую служит главной цели Королевского фармацевтического общества — созданию Новой чумы.",h="«Рецептура смерти» завершает расследование находок павшего исследователя: авантюристам поручено собрать...",kw={"a recipe for death","apothecarium","berard","dawning isles","faranell","hardened tumor","lake creeper","lake lordamere","lake skulker","new plague","renferrel","vile fin","рецептура смерти","апотекариум","берар","рассветные острова","фаранелл","затвердевшая опухоль","озерный ползун","озеро лордамер","озерный скрытень","новая чума","ренферрел","злобный плавник"},ang={["faction:Horde"]="Хотя аптекари Отрекшихся рады помощи союзных бойцов Орды, они тщательно оберегают тонкие химические секреты и предельную разрушительную мощь своей Новой чумы.",["race:Undead"]="Завершая незаконченные опыты Берара, вы напрямую воплощаете замысел Темной Госпожи: каждый разум Отрекшихся служит выживанию народа даже после смерти."},sec={{t="Наследие исследований",b="Потеря аптекаря Берара из-за проклятия Аругала стала ударом для Королевского фармацевтического общества, но его полевой журнал сохранил важные сведения о пораженной порчей биологии Серебряного бора и озера Лордамер. Аптекарь Ренферрел, служащий в Гробнице, изучил найденные записи Берара и обнаружил, что тот описал многообещающие свойства местных пресноводных организмов. Чтобы жертва Берара не пропала даром, Ренферрел поручает героям Орды исполнить замысел погибшего коллеги."},{t="Опасности озера Лордамер",b="Чтобы собрать указанные Бераром реагенты, нужно отправиться на Рассветные острова — окутанные туманом острова на восточных водах озера Лордамер. Озерные скрытни и озерные ползуны, населяющие эти острова, собирают особые виды мха, выживающие в оскверненной воде. Более неуловима затвердевшая опухоль — странный нарост, замеченный Бераром у свирепых племен мурлоков Злобного Плавника, гнездящихся на островках и южном берегу озера возле Янтарной мельницы."},{t="Топливо для Апотекариума",b="После сбора образцы минуют Гробницу и доставляются прямо в Апотекариум в Подгороде, в руки Мастера аптекаря Фаранелла. Фаранелл видит в этих странных мутациях незаменимые шаги к созданию Новой чумы, способной уничтожить и Плеть, и живых врагов. Исследования Берара быстро вливаются в котлы Общества, приближая Отрекшихся к их главному оружию."}},faq={{q="Зачем Королевскому фармацевтическому обществу мох и опухоль?",a="В полевом журнале аптекаря Берара отмечено, что водные мхи с озерных тварей и странные затвердевшие опухоли местных мурлоков Злобного Плавника обладают уникальными биологическими свойствами. Мастер аптекарь Фаранелл использует эти редкие мутировавшие реагенты, чтобы варить и совершенствовать Новую чуму Королевского фармацевтического общества.",al={"why moss and tumor","apothecary recipe ingredients","what is the tumor for","зачем мох и опухоль","ингредиенты рецепта аптекарей","для чего опухоль"}},{q="Кем был Берар?",a="Аптекарь Берар был исследователем Королевского фармацевтического общества в Серебряном бору. После того как проклятие Аругала превратило его в безвольного слугу, его найденный полевой журнал дал аптекарю Ренферрелу и Мастеру аптекарю Фаранеллу важные сведения о реагентах, необходимых для продолжения его работы.",al={"apothecary berard","who is berard","berard journal","аптекарь берар","кто такой берар","журнал берара"}},{q="Где находятся Рассветные острова?",a="Рассветные острова — группа небольших островов в восточной части озера Лордамер, к востоку от Серебряного бора. Они кишат озерными скрытнями, озерными ползунами и племенами враждебных мурлоков Злобного Плавника.",al={"where are dawning isles","dawning isles location","lake skulker location","где рассветные острова","расположение рассветных островов","где озерные скрытни"}},{q="Кто такой Мастер аптекарь Фаранелл?",a="Мастер аптекарь Фаранелл — глава Королевского фармацевтического общества, работающий в глубинах Апотекариума Подгорода. Он руководит всеми исследованиями и разработками в области химической войны, биологических смесей и создания Новой чумы по поручению леди Сильваны Ветрокрылой.",al={"faranell","who is faranell","master apothecary faranell","фаранелл","кто такой фаранелл","мастер аптекарь фаранелл"}},{q="Почему у мурлоков Злобного Плавника растут затвердевшие опухоли?",a="Воды и берега вокруг озера Лордамер сильно искажены порчей и близкими магическими конфликтами. Затвердевшие опухоли у Злобного Плавника — редкие ненормальные наросты, вызванные зараженной средой, и потому они крайне интересны Отрекшимся с научной точки зрения.",al={"why murloc tumor","vile fin tumor lore","hardened tumor murlocs","почему опухоли у мурлоков","опухоль злобного плавника","затвердевшая опухоль мурлоков"}},{q="Как это задание связано с Новой чумой?",a="Вся цепочка «Рецептура смерти» — это сбор ингредиентов, напрямую связанный с созданием Новой чумы. Пока младшие аптекари вроде Ренферрела расшифровывают и собирают местные материалы, все направляется прямо в главные чумоварни Фаранелла в Подгороде.",al={"new plague connection","a new plague questline","is this the plague","связь с новой чумой","цепочка новая чума","это та самая чума"}}},fp="18,408,20.532.0,29.463.0,24.468.1,60.317.0,15.305.0,36.217.0,34.298.0,49.290.0,46.301.0"}
P.entries["quest:4512"] = {s="В шумных залах Стальгорна гном-исследователь Ларис Обалдуй стремится раскрыть эволюционные тайны Азерота, изучая слизь и ил. Заинтригованный странным интересом Королевского фармацевтического общества к этим мерзким лужам, он поручает авантюристам Альянса отправиться в оскверненный Оскверненный лес и набрать образцы в склянки.",h="В шумных залах Стальгорна гном-исследователь Ларис Обалдуй стремится раскрыть эволюционные тайны Азерота...",kw={"cursed ooze","explorers league","felwood","gnomeregan","ironforge","laris geardawdle","ooze","royal apothecary society","slime","tainted ooze","проклятая слизь","лига исследователей","оскверненный лес","гномреган","стальгорн","ларис обалдуй","слизь","королевское фармацевтическое общество","оскверненная слизь"},ang={["faction:Alliance"]="Наблюдение за привычками Королевского фармацевтического общества дает Альянсу важные сведения о том, какие зловещие зелья может готовить Подгород.",["race:Dwarf"]="Хотя традиционные дворфы-раскопщики предпочитают камень и металл студенистой жиже, Лига исследователей все же выигрывает от эксцентричного рвения Ларис.",["race:Gnome"]="Ларис воплощает неустанное интеллектуальное рвение гномов, восстанавливающих репутацию и гордость после горестной потери Гномрегана."},sec={{t="Странная одержимость",b="Пока большинство ученых Лиги исследователей заняты древними реликвиями титанов или погребенными родословными дворфов, Ларис Обалдуй сосредоточил пытливый ум на более хлюпкой теме — слизи. Эти живые лужи повсеместно встречаются на болотах, в проклятых лесах и сырых руинах и не поддаются обычной биологической классификации. Увидев, как аптекари Отрекшихся собирают образцы слизи по всему Лордерону, Ларис решил понять, чем эти студенистые ужасы так интересны алхимикам Подгорода."},{t="Первичная секреция",b="Ларис придерживается спорной теории: слизь — не просто неестественные паразиты или побочный продукт магии, а первичные выделения, тесно связанные с самим рождением планеты Азерот. Чтобы доказать эту гипотезу, он отправляет отважных разведчиков за океан, в пораженный порчей полог Оскверненного леса, чтобы поймать образцы Проклятой и Оскверненной слизи в специально изготовленные банки."},{t="Доказать ценность гномов",b="За научными устремлениями Ларис скрывается глубоко личный мотив, общий для многих его изгнанных сородичей. После разрушительного радиоактивного падения Гномрегана тысячи гномов нашли приют как беженцы в Великой кузне Стальгорна. Добившись прорывного открытия для Лиги исследователей, Ларис надеется заставить замолчать скептиков-дворфов и доказать, что прием гномов в горный город был не простой милостью, а прочным вкладом в науку Альянса."}},faq={{q="Кто такой Ларис Обалдуй?",a="Ларис Обалдуй — гном-исследователь и ученый, живущий в Стальгорне. Работая вместе с Лигой исследователей, он посвящает себя изучению биологического происхождения слизи по всему Азероту.",al={"laris geardawdle","who is the quest giver","gnome ooze guy","ларис обалдуй","кто выдает задание","гном и слизь"}},{q="Почему Ларис так интересуется слизью?",a="Ларис подозревает, что слизь может быть связана с происхождением планеты Азерот как первичные выделения. Кроме того, заметив, что Королевское фармацевтическое общество Отрекшихся активно собирает образцы слизи, он хочет раскрыть их тайные свойства раньше Орды.",al={"why study slimes","why ooze jars","ooze theory","зачем изучать слизь","зачем банки со слизью","теория слизи"}},{q="Где собирать образцы слизи?",a="Образцы нужно собирать с Проклятой и Оскверненной слизи, бродящей по оскверненным чащам Оскверненного леса на севере Калимдора, используя пустые стеклянные емкости, которые выдает Ларис.",al={"where are the oozes","tainted ooze location","cursed ooze location","где слизь","где оскверненная слизь","где проклятая слизь"}},{q="Зачем Отрекшиеся собирают слизь?",a="Королевское фармацевтическое общество постоянно экспериментирует с токсинами, порчей и биологическими ужасами, развивая алхимию Отрекшихся. Интерес к сырой слизи говорит ученым Альянса, что эти создания содержат опасные или мутагенные соединения.",al={"undercity oozes","royal apothecary society slime","why do forsaken want ooze","слизь подгорода","слизь королевского фармацевтического общества","зачем отрекшимся слизь"}},{q="Как это задание связано с падением Гномрегана?",a="Ларис ощущает давление положения беженца в Стальгорне после потери Гномрегана из-за троггов и радиации. Он уверен, что крупный научный триумф для Лиги исследователей докажет, что предоставление убежища гномам действительно было стоящим для принимающих дворфов.",al={"gnomeregan connection","dwarf gnome relations","gnome refugees ironforge","связь с гномреганом","отношения дворфов и гномов","гномы беженцы стальгорн"}},{q="Что происходит после сдачи образцов?",a="Ларис сразу начинает испытывать образцы в своей лаборатории в Стальгорне, развивая теории о таксономии слизи и ее стихийном происхождении.",al={"slime quest follow up","what next after ooze jars","продолжение задания про слизь","что дальше после банок со слизью"}}},fp="30,342,20.525.0,24.368.0,21.478.0,24.213.0,39.279.0,37.177.0,38.240.0,54.270.0,43.163.0"}
P.entries["quest:4513"] = {n="Долгий путь слизнюка",s="После первых исследований оскверненных образцов гном-исследователь Ларис Обалдуй ищет незараженные образцы слизи, чтобы понять, как эти странные существа приспосабливаются к среде. Поняв, что слизь впитывает порчу таких мест, как Оскверненный лес, он отправляет искателей приключений искать и собирать чистые, незагрязненные образцы по всему Калимдору.",h="После первых исследований оскверненных образцов гном-исследователь Ларис Обалдуй ищет незараженные образцы...",kw={"felwood","glutinous ooze","ironforge","laris geardawdle","ooze research","pure sample jars","un'goro crater","оскверненный лес","клейкий слизень","стальгорн","ларис обалдуй","исследование слизи","образцы чистой слизи","кратер ун'горо"},ang={["faction:Alliance"]="Отправляясь из Стальгорна, искатели приключений Альянса должны пройти по диким землям Калимдора и помочь научным изысканиям гномов.",["race:Gnome"]="Ларис воплощает истинно гномий научный метод: он настаивает на выделении переменных и поиске незагрязненной контрольной группы, прежде чем делать широкие выводы."},sec={{t="Вопрос чистоты",b="Laris Geardawdle's preliminary experiments in Ironforge hit an immediate stumbling block: the oozes he previously examined were thoroughly polluted by the dark energies of Felwood. While this demonstrated that oozes absorb and reflect the traits of their surroundings, it left him without a control group. To understand the baseline nature of ooze life, he needs specimens untouched by demonic taint or urban filth."},{t="В поисках первобытной слизи",b="Найти незараженную слизь нелегко на Азероте, израненном порчей и войной. След приводит далеко на юг, в доисторическую долину кратера Ун'Горо, где в изолированной первозданной экосистеме обитают клейкие слизни. Добывая образцы у этих диких существ, искатели приключений дают Ларису редкий чистый материал, нужный, чтобы выяснить, как эти бесформенные создания взаимодействуют с живыми биомами Азерота."}},faq={{q="Зачем Ларису Обалдую нужны образцы чистой слизи?",a="Его прежние образцы были заражены порочной энергией Оскверненного леса. Чтобы проверить теорию о том, что слизь приспосабливается к окружению и отражает его, Ларису нужны чистые образцы из незагрязненной среды в качестве контрольных.",al={"why pure ooze","laris pure slime","what is pure ooze","зачем чистая слизь","ларис чистая слизь","что такое чистая слизь"}},{q="Где находится чистая слизь?",a="Чистые образцы можно добыть у клейких слизней, обитающих в буйных доисторических дебрях кратера Ун'Горо на юге Калимдора.",al={"where find pure ooze","pure sample jars location","where are pure slimes","где найти чистую слизь","где взять образцы чистой слизи","где чистые слизни"}},{q="Кто такой Ларис Обалдуй?",a="Это любознательный гном-исследователь из Стальгорна, всецело преданный разгадке биологических тайн слизи Азерота.",al={"who is laris","laris geardawdle lore","кто такой ларис","ларис обалдуй предыстория"}},{q="Чем слизь так интересна исследователям?",a="Слизь обладает уникальной биологической приспособляемостью: она легко впитывает и отражает магические, природные и порочные свойства мест, где обитает.",al={"why study slime","ooze lore","зачем изучать слизь","предания о слизи"}},{q="Продолжает ли это прежнее задание Ларису?",a="Да. Ранее Ларис просил добыть слизь для начала исследований, но первые образцы оказались сильно заражены демонической порчей Оскверненного леса, поэтому теперь нужны незапятнанные образцы.",al={"previous quest laris","what came before this","прошлое задание ларис","что было раньше"}},{q="Что Ларис собирается делать с образцами?",a="Он хочет сравнить чистые образцы с оскверненными, чтобы понять, как перемены в среде влияют на живых существ и, в более широком смысле, на население Азерота.",al={"laris ooze research","what is slime used for","исследования слизи ларис","для чего нужна слизь"}}},fp="30,358,18.415.0,25.423.1,49.245.0,33.139.0,24.150.0,47.160.0,43.173.0,46.177.0"}
P.entries["quest:452"] = {n="Засада в деревне",s="«Засада в деревне» — важная операция, которую Стражи смерти проводят в проклятой Деревне Погребальных Костров. Убив местный человеческий совет, Отрекшиеся надеются ослабить власть верховного мага Аругала над проклятыми жителями и подорвать силу его крепости, нависающей над деревней.",h="«Засада в деревне» — важная операция, которую Стражи смерти проводят в проклятой Деревне Погребальных Костров.",kw={"arugal","deathstalker faerleia","faerleia","lord mayor morrison","pyrewood ambush","pyrewood council","shadowfang keep","silverpine forest","аругал","страж смерти фарлия","фарлия","лорд-мэр моррисон","засада в деревне","совет погребальных костров","крепость темного клыка","серебряный бор"},ang={["class:Rogue"]="Засада — классическое ремесло Стражей смерти: проникнуть в твердыню врага, затаиться и устранить вражеских командиров в их собственном оплоте.",["faction:Horde"]="Разрушение сети марионеток Аругала ослабляет более серьезную угрозу, нависшую над путем Орды через Серебряный бор к южным границам.",["race:Undead"]="Для Отрекшихся удержание юга Серебряного бора жизненно важно для защиты границ Подгорода, а истребление приспешников Аругала приближает их к захвату Погребальных Костров."},sec={{t="Удар по марионеткам",b="В здании ратуши Деревни Погребальных Костров затаилась Страж смерти Фарлия, ожидая местных правителей. Пока верховный маг Аругал заперся в Крепости Темного Клыка и занят темным колдовством, он полагается на местный совет Погребальных Костров как на подставных лиц, поддерживающих порядок среди пораженных жителей. Фарлия намерена быстрой засадой уничтожить это руководство, надеясь, что без посредничества совета дикие воргены, бродящие по окрестным лесам и улицам деревни, вырвутся из-под власти Аругала."},{t="Удар по верхушке",b="Засада нацелена на каждого члена городской власти и завершается смертью лорда-мэра Моррисона. Перебив советников, когда они входят в зал заседаний, Отрекшиеся наносят тяжелый удар по административной вертикали деревни. В Подгороде видят в этой бойне не просто месть, а стратегическое условие для полного захвата Деревни Погребальных Костров и осады безумного верховного мага в Крепости Темного Клыка."}},faq={{q="Кто такая Страж смерти Фарлия?",a="Страж смерти Фарлия — агент ведущей гильдии шпионажа и убийств Отрекшихся, Стражей смерти. Действуя в тылу врага, она закрепилась прямо в Деревне Погребальных Костров, чтобы координировать удары по местной инфраструктуре верховного мага Аругала.",al={"faerleia","deathstalker faerleia","who gives pyrewood ambush","фарлия","страж смерти фарлия","кто дает задание засада в деревне"}},{q="Почему Отрекшиеся хотят смерти совета Погребальных Костров?",a="Аругал использует совет как политических марионеток, чтобы проклятые жители оставались покорными и подконтрольными. Отрекшиеся считают, что устранение этих лидеров ввергнет Погребальные Костры в хаос и заставит воргенов обратиться против Аругала.",al={"why kill pyrewood council","pyrewood council purpose","pyrewood council lore","зачем убивать совет погребальных костров","цель совета погребальных костров","предания о совете погребальных костров"}},{q="Кто возглавляет совет Погребальных Костров?",a="Совет возглавляет лорд-мэр Моррисон, который до засады Стражей смерти ведал городскими делами вместе с советниками, такими как Смитерс, Тэтчер и Брансуик.",al={"lord mayor morrison","pyrewood mayor","who runs pyrewood","лорд-мэр моррисон","мэр погребальных костров","кто управляет погребальными кострами"}},{q="Где проходит эта засада?",a="Засада проходит в здании городской ратуши в Деревне Погребальных Костров, на юге Серебряного бора, недалеко по дороге от Крепости Темного Клыка.",al={"pyrewood ambush location","where is faerleia","town hall pyrewood","место засады в деревне","где фарлия","ратуша погребальных костров"}},{q="Какова связь между советом и Аругалом?",a="Совет служит административным рупором Аругала. Пока Аругал заперт в Крепости Темного Клыка и ставит темные опыты, совет управляет жителями, которые с наступлением ночи превращаются в свирепых зверей.",al={"arugal council","is council working for arugal","arugal control pyrewood","аругал совет","совет работает на аругала","аругал власть над погребальными кострами"}},{q="Освободит ли гибель совета Погребальные Костры от проклятия?",a="Нет. Устранение совета лишает Аругала смертных марионеток, но не снимает волчье проклятие с жителей, и Отрекшимся приходится бороться за город, полный враждебных неуправляемых чудовищ.",al={"is pyrewood cured","does ambush cure worgen","curse broken pyrewood","излечены ли погребальные костры","лечит ли засада воргенов","проклятие снято погребальные костры"}}},fp="15,270,20.530.0,21.461.1,29.277.0,53.236.0,31.171.0,34.166.0,56.242.0,54.207.1"}
P.entries["quest:453"] = {n="Поиски таинственного незнакомца",s="«Поиски таинственного незнакомца» — задание Альянса: нужно разыскать неуловимого незнакомца, связанного с трагедией на ферме Свена Йоргена. Следуя подсказкам Хозяина таверны Смиттса в Темнолесье, путники прочесывают населенные призраками леса на западе в поисках беглеца.",h="«Поиски таинственного незнакомца» — задание Альянса: нужно разыскать неуловимого незнакомца, связанного с...",kw={"darkshire","duskwood","finding the shadowy figure","raven hill","scarlet raven tavern","sven yorgen","tavernkeep smitts","темнолесье","сумеречный лес","поиски таинственного незнакомца","вороний холм","таверна алый ворон","свен йорген","хозяин таверны смиттс"},ang={["class:Rogue"]="Выследить охваченного паникой подозреваемого в густом лесу, окутанном тенями, требует острой наблюдательности и навыков следопыта, чтобы отличить слухи от настоящих следов.",["faction:Alliance"]="Понять бегство Трясунчика важно, чтобы осознать растущую тьму, угрожающую южным рубежам королевства."},sec={{t="По следу призрака",b="После просьбы Свена Йоргена выяснить, кто тот таинственный человек, что бежал с его разоренной фермы, поиски привели прямо в таверну «Алый ворон». Хозяин таверны Смиттс сообщил несколько важных наблюдений: беглец был полностью чужим в Темнолесье, крайне нервным и дерганым и поспешно покинул слабо освещенную окраину города, скрывшись в глуши на западе."},{t="Разоблачение Трясунчика",b="След незнакомца на запад, в сумрак, в конце концов приводит к самому Трясунчику, дрожащему от страха среди опасностей Сумеречного леса. Столкнувшись с дневником, найденным на разоренной ферме, Трясунчик в нервном изнеможении падает и признается, что именно он написал этот потрепанный дневник. Он вовсе не расчетливый злодей, а напуганный свидетель, бежавший от ужасов, обрушившихся на этот край, и намекает, что дневник отражает лишь часть всего кошмара."}},faq={{q="Кто такой таинственный незнакомец?",a="Таинственный незнакомец — это Трясунчик, пугливый странник, который невольно записал мрачные события на ферме Свена Йоргена, прежде чем бежать на запад, в лес.",al={"shadowy figure identity","who is jitters","who is the stranger","личность таинственного незнакомца","кто такой трясунчик","кто такой незнакомец"}},{q="Куда, по словам Хозяина таверны Смиттса, ушел незнакомец?",a="Смиттс говорит, что тот человек был чужаком, выглядел насмерть перепуганным и бежал из Темнолесья на запад, рискнув отправиться в опасную глушь.",al={"where did he go","where is jitters","which way west","куда он пошел","где трясунчик","в какую сторону на запад"}},{q="Почему Трясунчик бежал с фермы Свена?",a="Трясунчик стал свидетелем несказанных ужасов, обрушившихся на ферму, и бежал, спасая жизнь, опасаясь, что то, что уничтожило семью Свена, придет следом за ним.",al={"why did jitters run","what happened at sven farm","why is jitters scared","почему трясунчик убежал","что случилось на ферме свена","почему трясунчик напуган"}},{q="Что за книга найдена на ферме Свена?",a="Это дневник, написанный Трясунчиком, с подробностями зловещих событий перед резней на ферме. Когда его показывают Трясунчику, тот признает, что там рассказана лишь половина истории.",al={"book from sven's farm","jitters journal","what is the diary","книга с фермы свена","дневник трясунчика","что за дневник"}},{q="Где можно найти Трясунчика?",a="Трясунчик прячется в западной глуши Сумеречного леса, укрываясь возле лагеря в Вороньем Холме вдали от Темнолесья и хищных зверей леса.",al={"jitters location","where is jitters in duskwood","jitters coordinates","где трясунчик","где трясунчик в сумеречном лесу","координаты трясунчика"}},{q="Что будет после того, как найти Трясунчика?",a="Когда Трясунчик признается, что написал дневник, он готовит полный рассказ о том, что произошло на самом деле, и направляет вас обратно к Свену Йоргену с правдой.",al={"what next","after finding jitters","where do i go next","что дальше","после поисков трясунчика","куда идти дальше"}}},fp="26,291,23.400.0,17.476.1,26.167.1,49.142.0,41.154.1,38.173.1,27.152.1,35.154.1"}
P.entries["quest:454"] = {n="После засады",s="После нападения дворфов Черного Железа, сорвавшего доставку взрывного порошка на южные раскопки в Лок Модане, Хальдар делит обязанности с напарником Мираном. Не желая рисковать и снова попасть в засаду в одиночку, Миран просит надежного сопровождающего, чтобы благополучно доставить оставшиеся припасы к месту раскопок.",h="После нападения дворфов Черного Железа, сорвавшего доставку взрывного порошка на южные раскопки в Лок Модане...",kw={"ambush","blasting powder","dark iron","excavation","huldar","loch modan","miran","saean","засада","взрывной порошок","черное железо","раскопки","хальдар","лок модан","миран","саеан"},ang={["faction:Alliance"]="Открытые линии снабжения в Лок Модане позволяют исследованиям Лиги продолжаться, а южным перевалам — оставаться под контролем Альянса.",["profession:Mining"]="Взрывной порошок — жизненная сила глубоких подземных раскопок, поэтому защита этих бочек важна для любого серьезного горного предприятия.",["race:Dwarf"]="Защита снабжения Стальгорна от коварных диверсантов Черного Железа напрямую сохраняет безопасность горных перевалов и рудников вашей родины."},sec={{t="Нарушенное снабжение",b="Перевозить взрывчатый горный порошок по холмам Лок Модана никогда не было просто, но открытая враждебность дворфов Черного Железа превратила обычную работу в смертельно опасное дело. После засады, устроенной Саеаном и его сообщниками, возчики Хальдар и Миран лишились привычного порядка. Бочки разбросаны, дорога опасна, и напарникам приходится разделить усилия: Хальдар охраняет то, что осталось, а Миран готовится отправиться дальше со следующим грузом."},{t="Дорога к раскопкам",b="Раскопки по всему Лок Модану зависят от постоянных поставок взрывного порошка, нужного, чтобы дробить камень и добывать реликвии титанов. Миран хорошо знает, что новая засада может ждать на любом гребне вдоль пути. Найдя попутчика до того, как закрепить груз, возчик надеется обойти все ловушки, которые дворфы Черного Железа еще держат в запасе."}},faq={{q="Кто такие Хальдар и Миран?",a="Хальдар и Миран — дворфы-возчики, перевозящие тяжелые бочки со взрывным порошком через Лок Модан для местных раскопок.",al={"who is huldar","who is miran","powder haulers loch modan","кто такой хальдар","кто такой миран","возчики порошка лок модан"}},{q="Почему Хальдар и Миран не могут ехать вместе?",a="После засады на их маршруте груз остался уязвим. Они разделили обязанности: Хальдар остается охранять оставшиеся бочки, а Миран отправляется вперед с первой партией.",al={"why split up","why split powder","почему разделились","почему разделили порошок"}},{q="Кто напал на груз?",a="Группа враждебных дворфов Черного Железа во главе с Саеаном устроила засаду на возчиков, пытаясь сорвать операции Альянса и захватить или уничтожить их горную взрывчатку.",al={"who ambushed them","who is saean","кто устроил засаду","кто такой саеан"}},{q="Куда Миран везет порошок?",a="Миран везет бочки на южные раскопки в Лок Модане, где отряду Геолога Сталекрута нужен взрывной порошок, чтобы расчищать породу и вскрывать погребенные руины.",al={"where is powder going","miran destination","куда идет порошок","куда направляется миран"}},{q="Почему в Лок Модане так усиленно охраняют взрывной порошок?",a="Взрывной порошок необходим для раскопок Лиги исследователей, но в чужих руках он крайне опасен. Лазутчики Черного Железа, действующие по всему району, стремятся сорвать поставки и ослабить власть Стальгорна над этой землей.",al={"why protect blasting powder","powder importance","зачем охранять взрывной порошок","важность порошка"}},{q="Что будет после разговора с Мираном?",a="Когда Миран закончит последнюю проверку повозки и груза, он попросит вас сопроводить его по дороге, чтобы груз дошел до места раскопок целым.",al={"next step after the ambush","what does miran do","что делать после засады","что делает миран"}}},fp="16,289,23.478.0,19.361.0,25.143.0,43.214.0,26.159.0,33.173.0,56.254.0,36.164.0"}
P.entries["quest:4542"] = {n="Письмо на Заставу Вольного Ветра",s="«Письмо на Заставу Вольного Ветра» — задание Орды: путникам нужно доставить срочное донесение от Храбреца Лунного Рога у пограничных подъемников, ведущих вниз, в Тысячу Игл. В письме Дозорного утесов Долгорога предупреждают о том, что набеги кентавров на местные караваны усиливаются. Там же высказываются первые опасения по поводу подозрительного, замкнутого поведения соседнего клана Зловещего Тотема.",h="«Письмо на Заставу Вольного Ветра» — задание Орды: путникам нужно доставить срочное донесение от Храбреца...",kw={"brave moonhorn","centaur","cliffwatcher longhorn","freewind post","grimtotem","message to freewind post","thousand needles","urgent message","храбрец лунный рог","кентавр","дозорный утесов долгорог","застава вольного ветра","зловещий тотем","письмо на заставу вольного ветра","тысяча игл","срочное письмо"},ang={["faction:Horde"]="Застава Вольного Ветра — жизненно важная опора Орды на просторах Тысячи Игл. Поддержание связи между дозорными застав и руководством поселения необходимо для защиты торговых путей в пустыне.",["race:Tauren"]="Для тауренов кентавры — исконные, заклятые соперники на протяжении многих поколений. Предупреждение Лунного Рога мрачно напоминает, что древние враги по-прежнему охотятся на тропах Калимдора, пока растет напряжение в отношениях с замкнутым кланом Зловещего Тотема."},sec={{t="Предупреждение для каньона",b="Храбрец Лунный Рог несет дозор у западных подступов к каньону и следит за дорогами, ведущими вниз, в Тысячу Игл. Агрессия кентавров резко выросла, поэтому связь между пограничными дозорными и местным руководством жизненно важна. Лунный Рог поручает проходящим мимо искателям приключений из Орды доставить срочное донесение на юго-восток, к Дозорному утесов Долгорогу — командиру, чья застава находится на вершине столовой горы, в поселении Застава Вольного Ветра."},{t="Растущая опасность и неспокойные сородичи",b="Получив письмо, Долгорог подтверждает тяжелое положение: недавно кентавры-мародеры перехватили и перебили снабженческий караван, и теперь Заставе Вольного Ветра отчаянно нужны ответный удар и оборона. Не меньше тревожит и прощальное предостережение Лунного Рога сторониться местных тауренов клана Зловещего Тотема: их необычное странное и враждебное поведение указывает на более глубокий раскол, зреющий в засушливых равнинах."}},faq={{q="Кто отправляет письмо на Заставу Вольного Ветра?",a="Срочное донесение для доставки вам вручает Храбрец Лунный Рог, таурен-разведчик, несущий дозор у западного входа в Тысячу Игл.",al={"quest giver","who starts message to freewind post","brave moonhorn","выдающий задание","кто дает письмо на заставу вольного ветра","храбрец лунный рог"}},{q="Кто получает срочное письмо?",a="Дозорный утесов Долгорог получает письмо на вершине высокой столовой горы, в поселении Застава Вольного Ветра к юго-востоку от Великого Подъемника.",al={"where to turn in","cliffwatcher longhorn location","freewind post leader","куда сдавать","где дозорный утесов долгорог","глава заставы вольного ветра"}},{q="О чем сообщается в срочном письме?",a="В письме Заставу Вольного Ветра предупреждают о резком росте числа нападений кентавров и притеснений караванов на тропах внизу.",al={"message contents","what is the message about","содержание письма","о чем письмо"}},{q="Почему Храбрец Лунный Рог беспокоится из-за Зловещего Тотема?",a="Лунный Рог отмечает, что члены соседнего клана Зловещего Тотема ведут себя странно и отчужденно по отношению к другим тауренам, и советует путникам держаться от них подальше.",al={"grimtotem warning","why avoid grimtotem","предупреждение о зловещем тотеме","почему избегать зловещего тотема"}},{q="Что происходит после того, как Долгорог читает письмо?",a="Разгневанный недавней резней снабженческого каравана, Дозорный утесов Долгорог сразу отдает приказ о карательных действиях против местных кентавров в следующем задании — «Усмирение кентавров».",al={"next quest","after message to freewind post","следующее задание","после письма на заставу вольного ветра"}},{q="Как добраться до Заставы Вольного Ветра с дна каньона?",a="Идите по главной дороге каньона на восток до подножия огромной столовой горы-иглы, затем поднимитесь на деревянной платформе подъемника прямо в деревню.",al={"getting to freewind post","how to get up freewind post","как добраться до заставы вольного ветра","как подняться на заставу вольного ветра"}}},fp="24,367,25.430.0,28.406.0,39.133.0,32.131.0,36.119.0,50.154.0,46.184.0,53.150.0"}
P.entries["quest:455"] = {n="Альгазская битва",s="«Альгазская битва» — срочное военное задание: пробиться через Дун Альгаз, важнейший горный проход между Лок Моданом и Болотиной. Орки клана Драконьей Пасти закрепились в туннелях и грозят перерезать жизненно важную связь Стальгорна с Гаванью Менетилов. Искателям приключений нужно перебить орочий авангард и доставить весть о вторжении Валстагу Сталезубу.",h="«Альгазская битва» — срочное военное задание: пробиться через Дун Альгаз, важнейший горный проход между Лок...",kw={"dragonmaw","dun algaz","loch modan","menethil harbor","pass","rockgar","valstag ironjaw","wetlands","драконья пасть","дун альгаз","лок модан","гавань менетилов","проход","рокхар","валстаг сталезуб","болотина"},ang={["faction:Alliance"]="Гавань Менетилов — главные ворота Альянса между Восточными королевствами и западными землями; поддержание сухопутного пути открытым важно для всей фракции.",["race:Dwarf"]="Расчистка Дун Альгаза защищает исконные горные проходы Каз Модана и сохраняет важнейшую связь между Стальгорном и его западной морской гаванью."},sec={{t="Перерезанная артерия",b="Дун Альгаз — единственный сухопутный горный проход, прорезающий скалы между Лок Моданом и болотистой низиной Болотины. Для дворфов Стальгорна этот каменный коридор необходим для торговли, переброски войск и снабжения Гавани Менетилов — главного прибрежного порта Альянса в этом регионе. Если проход падет, связь Стальгорна с западными морями будет фактически задушена, а изолированные форпосты останутся без дворфийских подкреплений."},{t="Натиск Драконьей Пасти",b="Хотя остатки клана Драконьей Пасти давно скрываются в холмах и руинах Болотины после Второй войны, их внезапное организованное наступление на Дун Альгаз — это агрессивная эскалация. Вместо того чтобы отсиживаться в болотных убежищах, разведчики и грунты Драконьей Пасти захватили туннели и укрепили проход. Горный пехотинец Рокхар вербует отважных путников Альянса, чтобы прорвать эту блокаду, перебив наступающих орков, и доставить весть о нападении прямо Валстагу Сталезубу в Гавани Менетилов."}},faq={{q="Почему Дун Альгаз так важен для Альянса?",a="Дун Альгаз — единственная прямая горная дорога между Лок Моданом и Болотиной. Она соединяет сердце Каз Модана с Гаванью Менетилов, главным портом Альянса для морских перевозок.",al={"why dun algaz matters","dun algaz importance","why clear the pass","почему важен дун альгаз","значение дун альгаза","зачем зачищать проход"}},{q="Кто такие орки Драконьей Пасти, занявшие проход?",a="Клан Драконьей Пасти — остатки Старой Орды, печально известные порабощением красных драконов во время Второй войны. После поражения разрозненные отряды отступили в Болотину, а теперь продвинулись на юг, в проход, чтобы захватить стратегические узкие места.",al={"who are the dragonmaw","why are orcs in dun algaz","dragonmaw clan lore","кто такие драконья пасть","почему орки в дун альгазе","история клана драконьей пасти"}},{q="Куда ведет это задание?",a="Когда вы пробьетесь через проход и уничтожите засевших там грунтов и разведчиков, дорога ведет на север через Болотину и на развилке поворачивает на запад, к Гавани Менетилов, где нужно доложить Валстагу Сталезубу.",al={"where do i go after algaz gauntlet","who gets the report","where is valstag ironjaw","куда идти после альгазской битвы","кому отдать донесение","где валстаг сталезуб"}},{q="Почему Валстага Сталезуба удивляет донесение?",a="Драконья Пасть обычно прячется в скрытых лагерях среди болотистых холмов Болотины. Их дерзкий натиск на дворфийские туннели Дун Альгаза означает неожиданный и тревожный переход к организованной агрессии.",al={"valstag reaction","why did orcs attack algaz","реакция валстага","почему орки напали на альгаз"}},{q="Кто приказывает штурмовать проход?",a="Горный пехотинец Рокхар, дворфийский стражник на северной границе Лок Модана, приказывает нанести удар, чтобы орки не укрепились и не отрезали связь с побережьем.",al={"who gives the quest","mountaineer rockgar mission","кто дает задание","задание горного пехотинца рокхара"}},{q="Что происходит после завершения этой битвы?",a="Доставка донесения Валстагу Сталезубу предупреждает гарнизон Гавани Менетилов о непосредственной угрозе и открывает новые возможности помочь дворфам в обороне от Драконьей Пасти в Болотине.",al={"next quest after algaz gauntlet","what to do in menethil","следующее задание после альгазской битвы","что делать в гавани менетилов"}}},fp="18,392,16.475.0,19.509.0,46.206.0,46.258.0,29.208.0,47.209.0,35.200.0,42.200.0"}
P.entries["quest:456"] = {n="Природное равновесие",s="«Природное равновесие» — вводное задание для недавно пробудившихся ночных эльфов в Тенистой долине. Его выдает Опекун Илталайн: юным искателям приключений поручено сократить разросшиеся популяции молодых ночных саблезубов и чертополоховых кабанов. Задание знакомит новых героев с древним долгом кальдораев — оберегать и сохранять природную гармонию Тельдрассила.",h="«Природное равновесие» — вводное задание для недавно пробудившихся ночных эльфов в Тенистой долине.",kw={"aldrassil","balance of nature","ilthalaine","kaldorei","nightsaber","shadowglen","teldrassil","thistle boar","альдрассил","природное равновесие","илталайн","кальдораи","ночной саблезуб","тенистая долина","тельдрассил","чертополоховый кабан"},ang={["class:Druid"]="Для начинающих друидов это истребление — прямой урок суровой правды опеки Кенария: защита дикой природы порой требует пролить кровь ради спасения целого.",["class:Hunter"]="Умение выслеживать и истреблять агрессивных животных — основа единения каждого охотника со зверями Калимдора.",["race:NightElf"]="Это задание — первый шаг вашего пути взрослого защитника кальдораев: вы учитесь тому, что равновесие природы требует активного вмешательства и уважения."},sec={{t="Хрупкая гармония",b="Тельдрассил может казаться диким и древним, но его экосистемы молоды и хрупки. В Тенистой долине, под раскидистыми ветвями Великого Древа, сильные весенние дожди нарушили тонкий цикл леса. Некоторые популяции животных размножились сверх того, что земля способна прокормить, и угрожают истощить ресурсы долины и ввергнуть всю экосистему в голод. Сохранение леса требует активной опеки."},{t="Зов Опекуна",b="Опекун Илталайн присматривает за лесами Тенистой долины и следит, чтобы ни один элемент не взял верх над другими. Чтобы предотвратить массовый голод среди животных, он посылает молодых ночных эльфов в рощу проредить чертополоховых кабанов и хищных ночных саблезубов. Эта обязанность неприглядна, но жизненно важна: она закладывает основу философии кальдораев — гармония с природой требует активного равновесия и трудных решений."}},faq={{q="Почему нужно убивать ночных саблезубов и кабанов?",a="Сильные весенние дожди вызвали бурный рост популяций молодых ночных саблезубов и чертополоховых кабанов. Тенистая долина может прокормить лишь ограниченное число животных, а разросшиеся стада рискуют истощить рощу и обречь на голод себя и других существ.",al={"why kill boars","why kill nightsabers","balance of nature reason","зачем убивать кабанов","зачем убивать саблезубов","причина природного равновесия"}},{q="Кто такой Опекун Илталайн?",a="Опекун Илталайн — страж из числа кальдораев, несущий службу в Тенистой долине. Его священный долг — следить за животным и растительным миром рощи, чтобы гармония природы оставалась нерушимой.",al={"who is ilthalaine","quest giver","conservator ilthalaine lore","кто такой илталайн","выдающий задание","история опекуна илталайна"}},{q="Где происходит это задание?",a="Задание происходит в Тенистой долине — уединенном лесном уголке среди ветвей Тельдрассила, Мирового Древа у побережья северного Калимдора.",al={"quest location","where is shadowglen","starting area night elf","место задания","где тенистая долина","стартовая зона ночных эльфов"}},{q="Что дальше после выполнения этого задания?",a="Илталайн поручает вам вторую часть истребления, а также вручает знак вашего класса, который указывает путь к первому наставнику в Альдрассиле.",al={"follow up quest","next quest in chain","следующее задание","продолжение цепочки"}}},fp="21,366,18.438.0,22.425.0,51.232.0,30.178.0,33.157.0,43.162.0"}
P.entries["quest:457"] = {n="Природное равновесие",s="Это задание продолжает усилия Опекуна Илталайна по сохранению хрупкой экологии Тенистой долины: нужно сократить число взрослых чертополоховых кабанов и шелудивых ночных саблезубов. Поскольку животный мир Тельдрассила бесконтрольно размножается, стражам-ночным эльфам приходится вмешаться, чтобы хищники и собиратели не оголили ветви.",h="Это задание продолжает усилия Опекуна Илталайна по сохранению хрупкой экологии Тенистой долины: нужно...",kw={"aldrassil","balance of nature","culling","ilthalaine","mangy nightsaber","shadowglen","teldrassil","thistle boar","альдрассил","природное равновесие","истребление","илталайн","шелудивый ночной саблезуб","тенистая долина","тельдрассил","чертополоховый кабан"},ang={["class:Druid"]="Учения друидов ставят гармонию выше сентиментальности: сокращение разросшихся стай сохраняет великую паутину жизни.",["class:Hunter"]="Охота на быстрых саблезубов и упрямых кабанов учит выслеживанию и истреблению — навыкам, необходимым, чтобы держать природу в равновесии.",["race:NightElf"]="Для юных ночных эльфов это задание — первый урок суровой правды опеки над дикой природой Тельдрассила."},sec={{t="Бремя опеки",b="Хотя истребление молодых животных стабилизирует будущий рост, взрослые популяции Тенистой долины тоже представляют непосредственную угрозу экосистеме Мирового Древа. Опекун Илталайн направляет юных защитников вглубь леса охотиться на взрослых чертополоховых кабанов и старых шелудивых ночных саблезубов, пока их ненасытный аппетит не истощил скудную флору и дичь."},{t="Хищник и жертва",b="К северу от Альдрассила лес меняется: молодые детеныши уступают место пятнистым ночным саблезубам и агрессивным кабанам, роющим землю. Хотя убивать диких существ — мрачный долг, учение кальдораев считает контролируемую охоту необходимой обязанностью ради защиты всего леса от экологического краха."}},faq={{q="Почему Опекун Илталайн приказывает истреблять этих зверей?",a="Без вмешательства растущие популяции чертополоховых кабанов и ночных саблезубов истощили бы жизненно важные ресурсы Тенистой долины, и земля стала бы бесплодной, неспособной поддерживать жизнь на ветвях Тельдрассила.",al={"why kill boars and sabers","why balance of nature","reason for hunting","зачем убивать кабанов и саблезубов","зачем природное равновесие","причина охоты"}},{q="Где находятся шелудивые ночные саблезубы и чертополоховые кабаны?",a="Они бродят по северной половине Тенистой долины, за ветвями Альдрассила. Ищите саблезубов с пятнистой шкурой, а не с полосатой, как у молодых детенышей поближе к убежищу.",al={"where are mangy nightsabers","thistle boar location","where to find them","где шелудивые саблезубы","где чертополоховые кабаны","где их найти"}},{q="Кто такой Опекун Илталайн?",a="Опекун Илталайн — смотритель Тенистой долины, отвечающий за здоровье стартовой поляны Тельдрассила и помогающий недавно пробудившимся ночным эльфам поддерживать равновесие леса.",al={"who is ilthalaine","conservator ilthalaine lore","кто такой илталайн","история опекуна илталайна"}},{q="Как это связано с верованиями ночных эльфов о природе?",a="Ночные эльфы почитают природу, но опека требует сдерживать чрезмерный рост. Если один вид размножится и вытеснит другие, это вредит лесу в целом, поэтому истребление — печальный, но жизненно важный долг.",al={"night elf nature beliefs","why druids kill animals","kaldorei balance","верования ночных эльфов о природе","почему друиды убивают животных","равновесие кальдораев"}},{q="Это конец цепочки «Природное равновесие»?",a="Это второй и последний шаг начальной цепочки «Природное равновесие», хотя вскоре появляются другие задания, связанные с более глубокой, неестественной порчей, терзающей животных Тельдрассила.",al={"does balance of nature continue","what comes after balance of nature","продолжается ли природное равновесие","что после природного равновесия"}},{q="Почему ночных саблезубов называют шелудивыми?",a="Это старые, более грубые хищники, бродящие по окраинам поляны; их многочисленность подрывает запасы пищи Тенистой долины, из-за чего многие из них облезлые и агрессивные.",al={"why mangy","what is wrong with the sabers","почему шелудивые","что не так с саблезубами"}}},fp="21,315,23.352.0,17.307.0,57.207.0,58.197.0,30.197.0,54.205.0,47.185.0,43.168.0"}
P.entries["quest:458"] = {n="Защитница леса",s="Защитница леса — вводное задание в Тенистой долине, которое выдает друид Мелитар Олений Шлем. Встревоженный шепотом лесных духов, Мелитар просит вас найти Тариндреллу, неуловимую дриаду, неожиданно вернувшуюся в рощу. Ее появление намекает, что под сенью Тельдрассила назревает нечто тревожное.",h="Защитница леса — вводное задание в Тенистой долине, которое выдает друид Мелитар Олений Шлем.",kw={"aldrassil","dryad","melithar staghelm","shadowglen","tarindrella","teldrassil","woodland protector","альдрассил","дриада","мелитар олений шлем","тенистая долина","тариндрелла","тельдрассил","защитница леса"},ang={["class:Druid"]="Друиды высоко чтят дриад как родню по природе; отклик на появление Тариндреллы — это первый зов беречь равновесие Изумрудного Сна и лесов.",["race:NightElf"]="Для юных ночных эльфов, покидающих Альдрассил, встреча с одной из дочерей Кенария становится первым прямым долгом в сохранении гармонии их молодого Мирового Древа."},sec={{t="Шепот в долине",b="Обучая новичков под ветвями Альдрассила, Мелитар Олений Шлем получает тревожные знамения от лесных духов. Дриада Тариндрелла, считающаяся защитницей дикой природы, вновь появилась в Тенистой долине после многолетнего отсутствия в лесах Калимдора. Поскольку дриады редко появляются без причины, Мелитар опасается нарушения природного равновесия."},{t="В поисках дриады",b="По донесению разведки Часовых недавно пробудившиеся защитники отправляются к юго-западу от Альдрассила, в окрестные леса. Встреча с Тариндреллой подтверждает правоту Мелитара: дочь Кенария действительно вернулась, чтобы противостоять подступающей порче, поразившей курган и окрестные поляны."}},faq={{q="Кто выдает это задание?",a="Мелитар Олений Шлем, друид-ночной эльф, находящийся на нижних платформах Альдрассила в Тенистой долине, выдает это задание только что пробудившимся искателям приключений.",al={"quest giver","who gives quest","melithar quest","персонаж, выдающий задания","кто дает задание","задание мелитара"}},{q="Где найти Тариндреллу?",a="Тариндрелла находится в лесу к юго-западу от Альдрассила, неподалеку от лесных троп Тенистой долины.",al={"tarindrella location","where is tarindrella","find dryad","где тариндрелла","расположение тариндреллы","найти дриаду"}},{q="Кто такая Тариндрелла?",a="Тариндрелла — дриада, одна из бессмертных дочерей Кенария. Дриады, почитаемые как защитницы леса, глубоко связаны со здоровьем леса и редко вмешиваются напрямую, если природе не грозит серьезная опасность.",al={"who is tarindrella","tarindrella lore","dryad shadowglen","кто такая тариндрелла","предания о тариндрелле","дриада тенистая долина"}},{q="Почему Мелитар обеспокоен ее возвращением?",a="Присутствие Тариндреллы не ощущалось в лесах Калимдора годами. Ее внезапное появление среди недавно выросших ветвей Тельдрассила говорит о том, что в роще что-то неладно.",al={"why is melithar worried","melithar staghelm concern","почему мелитар встревожен","мелитар олений шлем беспокойство"}},{q="Что будет после встречи с Тариндреллой?",a="Разговор с Тариндреллой завершает поручение и сразу переходит в ее просьбу о помощи: она привлекает вас к расследованию того, откуда в Тенистой долине взялись зараженные растения и животные.",al={"next quest","what next","tarindrella followup","следующее задание","что дальше","продолжение тариндреллы"}},{q="Родственник ли Мелитар Олений Шлем верховному друиду Фэндралу Оленьему Шлему?",a="Мелитар носит ту же фамилию, что и верховный друид Фэндрал Олений Шлем, предводитель ночных эльфов-друидов в Дарнассе, хотя о родстве между ними ничего не известно; Мелитар занят наставничеством юных друидов в Тенистой долине.",al={"melithar fandral relation","is melithar staghelm related","мелитар и фэндрал родство","родственник ли мелитар олений шлем"}}},fp="22,332,20.372.0,17.314.1,22.148.0,29.106.0,19.222.0,43.198.0,39.182.0,59.238.0"}
P.entries["quest:4581"] = {n="Кайнет Штиль",s="Это задание отправляет курьера Альянса из Астранаара на восток, в древний форпост Лесная Песнь. Неся донесение разведки от Часовой Шиндрелл Огненный Всполох, путники разыскивают друида Кайнета Штиля, чтобы помочь ему следить за распространением порчи по древним лесам.",h="Это задание отправляет курьера Альянса из Астранаара на восток, в древний форпост Лесная Песнь.",kw={"ashenvale","astranaar","corruption","druid","forest song","kayneth stillwind","nightsong woods","shindrell swiftfire","ясеневый лес","астранаар","порча","друид","лесная песнь","кайнет штиль","леса ночной песни","шиндрелл огненный всполох"},ang={["class:Druid"]="Для друидов помощь Кайнету Штилю — основополагающий долг: она напрямую поддерживает непрерывную борьбу Круга Кенария за исцеление Ясеневого леса от распространяющейся демонической и стихийной порчи.",["faction:Alliance"]="Путь из центра Ясеневого леса в восточные Леса Ночной Песни необходим для налаживания устойчивой связи и обороны как от угроз дикой природы, так и от вторжения Орды.",["race:NightElf"]="Часовых и странствующих кальдораев объединяет долг поддерживать связь между важными оплотами, такими как Астранаар, и отдаленными владениями, такими как Лесная Песнь."},sec={{t="Донесение на восток",b="В городке Астранаар Часовая Шиндрелл Огненный Всполох несет дозор над западной частью леса. До нее доходит весть от друида Кайнета Штиля, находящегося далеко в Лесной Песни, на востоке Ясеневого леса. Глубоко встревоженный переменами в поведении животных и темными знамениями на побережье и в лесах, Кайнет запросил официальную оценку безопасности региона. Огненный Всполох записывает свои наблюдения в запечатанную записку, доверяя ее крепкому путнику, который доставит донесение через опасный центр леса."},{t="Стражи Лесной Песни",b="Чтобы добраться до Лесной Песни, нужно пройти через дикие Леса Ночной Песни, которым угрожают наступающие сатиры, враждебные звери и набеги Орды с юга. У святилища Лесной Песни Кайнет Штиль изучает хрупкое равновесие природных духов Ясеневого леса. Донесение Огненного Всполоха подтверждает его мрачные подозрения: оскверняющее влияние в лесу не случайно и не мимолетно, и друидам потребуется дополнительная помощь, чтобы противостоять злу, пускающему корни."}},faq={{q="Где находится Кайнет Штиль?",a="Кайнета Штиля можно найти в Лесной Песни — тихом убежище ночных эльфов в Лесах Ночной Песни на дальнем востоке Ясеневого леса, к северу от главной дороги.",al={"where is kayneth","kayneth stillwind location","find kayneth stillwind","где кайнет","где найти кайнета штиля","кайнет штиль расположение"}},{q="Кто выдает это задание?",a="Задание выдает Часовая Шиндрелл Огненный Всполох, находящаяся в поселении ночных эльфов Астранаар на западе Ясеневого леса.",al={"quest giver","who starts kayneth stillwind","where do i start","персонаж, выдающий задания","кто дает задание кайнета штиля","с чего начать"}},{q="Что написано в Записке Шиндрелл?",a="В записке содержится подробное донесение о безопасности: о происшествиях на западном побережье Ясеневого леса и в лесах вокруг Астранаара. Оно написано, чтобы помочь Кайнету Штилю расследовать неестественную порчу в лесу.",al={"shindrell's note contents","what did shindrell write","shindrell note","содержание записки шиндрелл","что написала шиндрелл","записка шиндрелл"}},{q="Почему Кайнет Штиль исследует лес?",a="Как друид, Кайнет стремится сохранять природное равновесие. Он опасается, что по Ясеневому лесу расползается темное, всепроникающее зло, и ему нужны донесения Часовых с мест, чтобы отследить, где оно укореняется.",al={"why does kayneth care","kayneth stillwind motive","druid corruption","почему кайнет обеспокоен","мотив кайнета штиля","порча друид"}},{q="Безопасна ли Лесная Песнь для путников Альянса?",a="Сама Лесная Песнь — мирное убежище Альянса с дружелюбными часовыми и друидами. Однако окрестные Леса Ночной Песни полны враждебных зверей и оскверненных сатиров, из-за чего дорога туда опасна.",al={"is forest song safe","alliance town forest song","forest song guards","безопасна ли лесная песнь","поселение альянса лесная песнь","стража лесной песни"}},{q="Что будет после доставки записки?",a="Изучив донесение Шиндрелл, Кайнет Штиль выясняет, какова природа порчи леса, и привлекает путников к прямым действиям против оскверненных сил, угрожающих региону.",al={"what comes next","follow up quest","kayneth continuation","что дальше","следующее задание","продолжение кайнета"}}},fp="17,280,22.550.0,23.508.0,35.173.0,21.133.0,28.218.0,50.204.0,43.217.0,39.207.0"}
P.entries["quest:459"] = {n="Защитница леса",s="Тариндрелла, дриада, опекающая Тенистую долину, стремится выяснить причину внезапной агрессии местных существ и исчезновения соседних фурболгов. Изучая диких греллов и собирая образцы оскверненного Мха Скверны, искатели приключений убеждаются, что темная магия начала гнездиться в корнях Мирового Древа.",h="Тариндрелла, дриада, опекающая Тенистую долину, стремится выяснить причину внезапной агрессии местных существ...",kw={"athridas bearmantle","fel moss","gnarlpine","grell","grellkin","shadowglen","tarindrella","teldrassil","атридас медвежья шкура","мох скверны","скрюченная сосна","грелл","греллы","тенистая долина","тариндрелла","тельдрассил"},ang={["class:Druid"]="Друиды связаны священными узами с духами и дриадами леса; изучение оскверненного Мха Скверны жизненно важно для распознавания духовного недуга, поразившего Мировое Древо.",["race:NightElf"]="Для юных кальдораев, отправляющихся из Альдрассила, это задание — первое тревожное осознание того, что их священный новый дом уязвим для порчи изнутри."},sec={{t="Порча в роще",b="Даже в уединенных высях Тенистой долины безмятежная природа Тельдрассила начала давать трещины. Дриады вроде Тариндреллы заметили, что по лесу прокатилась темная перемена. Некогда мирные фурболги покинули родовые берлоги и объединились в агрессивное племя Скрюченной Сосны, а дикие греллы и их сородичи начали заполонять лесные тропы."},{t="Оскверненная поросль",b="Тариндрелла подозревает, что неестественная порча питает враждебность леса. Убивая кишащих греллов и собирая образцы Мха Скверны, вы получаете неопровержимое доказательство темных чар, въевшихся в ветви Тельдрассила. Когда мрачная правда подтверждена, Тариндрелла направляет юных защитников в деревню Доланаар, на встречу с друидом Атридасом Медвежьей Шкурой."}},faq={{q="Кто такая Тариндрелла?",a="Тариндрелла — дриада-наблюдательница, обитающая в глуши Тенистой долины. Как дочь Кенария, она посвятила себя сохранению растений и животных рощи и предупреждению защитников-ночных эльфов, когда порча угрожает равновесию.",al={"tarindrella","who is the questgiver","shadowglen dryad","тариндрелла","кто выдает задание","дриада тенистой долины"}},{q="Что такое Мох Скверны?",a="Мох Скверны — оскверненная поросль, пропитанная темной магией, которая начала облеплять животных в Тенистой долине. Он приводит в ярость и уродует существ вроде греллов, толкая их к неестественной агрессии.",al={"fel moss","what is fel moss","moss corruption","мох скверны","что такое мох скверны","порча мха"}},{q="Что случилось с фурболгами в Тенистой долине?",a="Фурболги, некогда мирно жившие в роще, покинули свои исконные жилища. Оскверненные коварной гнилью, расползающейся по Тельдрассилу, они объединились под знаменем враждебного племени Скрюченной Сосны.",al={"furbolg mystery","gnarlpine tribe","where did the furbolgs go","тайна фурболгов","племя скрюченной сосны","куда делись фурболги"}},{q="Куда ведет расследование дальше?",a="Убедившись, что Мох Скверны укоренился в Тенистой долине, Тариндрелла направляет путников вглубь Тельдрассила, в поселение Доланаар. Там друид Атридас Медвежья Шкура изучает, как шире распространяется эта порча по Мировому Древу.",al={"next quest","where do i go after","athridas bearmantle","следующее задание","куда идти дальше","атридас медвежья шкура"}},{q="Кто такие греллы и их сородичи?",a="Греллы и их сородичи — проказливые мелкие лесные духи, обитающие среди ветвей Тельдрассила. Обычно это буйные вредители, но под воздействием оскверняющих сил, например Мха Скверны, они становятся свирепо агрессивными.",al={"grells","grellkin","what are grells","греллы","сородичи греллов","кто такие греллы"}},{q="Почему в Тельдрассиле есть порча?",a="Хотя Тельдрассил был выращен, чтобы вернуть ночным эльфам утраченное бессмертие и дать им новое убежище, темные силы начали просачиваться в его ветви и обитающих в нем существ, тревожа друидов и лесных духов, охраняющих его.",al={"why is teldrassil corrupted","shadowglen corruption","почему тельдрассил осквернен","порча тенистой долины"}}},fp="22,329,21.359.0,14.372.0,19.237.0,17.205.0,44.231.0,40.255.0,29.210.0,40.231.0"}
P.entries["quest:46"] = {n="Награда за мурлоков",s="Армия Штормграда объявила публичную награду за мурлоков, расплодившихся в восточной части Элвиннского леса. Гарнизон перегружен, и Стражник Томас рассчитывает на странствующих искателей приключений, которые должны проредить лагеря на берегах Озера Каменных Столбов и южных водоемов, пока мурлоки не заполонили фермы и дороги региона.",h="Армия Штормграда объявила публичную награду за мурлоков, расплодившихся в восточной части Элвиннского леса.",kw={"bounty","elwynn","fins","foragers","guard thomas","lurkers","marshal dughan","murlocs","stone cairn lake","награда","элвиннский лес","плавники","собиратели","стражник томас","соглядатаи","маршал дугхан","мурлоки","озеро каменных столбов"},ang={["class:Hunter"]="Болотистые берега и заросшие камышом отмели у Озера Каменных Столбов — идеальное поле для выслеживания проворных водных хищников, действующих стаей.",["faction:Alliance"]="Очистка водных путей защищает важные линии снабжения и сельские усадьбы между Златоземьем и границей с Красногорьем.",["race:Human"]="Для жителей Штормграда этот контракт — яркое напоминание о том, как слабо защищено их королевство прямо у сердца столицы."},sec={{t="Угроза на водных путях",b="Хотя западные дороги Элвиннского леса сравнительно безопасны, на востоке в водах растет земноводное нашествие. Мурлоки-соглядатаи и собиратели основали агрессивные береговые поселения вокруг Озера Каменных Столбов и у развилки южных ручьев. То, что поначалу казалось мелкой неприятностью, быстро переросло в территориальную экспансию: вооруженные мурлоки нападают на путников и вторгаются в человеческие поселения."},{t="Растянутая оборона",b="Стражник Томас, дежурящий на восточном мосту у границы с Красногорьем, оказался между внешними угрозами и местным беспорядком. Король Вариан Ринн пропал, а военное командование Штормграда погрязло в бюрократическом параличе, поэтому городские гарнизоны редко получают запрошенное подкрепление. Маршал Дугхан и местные офицеры обратились к официальным наградам, платя монетой за отрубленные плавники, чтобы сдержать водяной натиск."}},faq={{q="Почему в Элвиннском лесу назначена награда за мурлоков?",a="Мурлоки основали растущие лагеря у Озера Каменных Столбов и на южных ручьях восточной части Элвиннского леса. Их отряды собирателей угрожают окрестным фермам, дорогам и путникам, поэтому Армия Штормграда платит искателям приключений за сокращение их числа.",al={"why kill murlocs","murloc bounty reason","why bounty on murlocs","зачем убивать мурлоков","причина награды за мурлоков","почему награда за мурлоков"}},{q="Кто платит награду?",a="Награду финансирует Армия Штормграда через командование Златоземья под началом маршала Дугхана, а Стражник Томас выступает контактом на месте и выплачивает деньги путникам у восточной речной переправы.",al={"who rewards this quest","who pays the bounty","stormwind army bounty","кто награждает за задание","кто платит награду","награда армии штормграда"}},{q="Где расположены поселения мурлоков?",a="Основные колонии находятся на берегах и островах Озера Каменных Столбов на севере, а также на берегах рек на юге, где разветвляется восточный ручей.",al={"murloc locations elwynn","where are elwynn murlocs","stone cairn lake murlocs","мурлоки элвиннского леса","где мурлоки элвиннского леса","мурлоки озера каменных столбов"}},{q="Почему стражники Штормграда не справляются сами?",a="Армия Штормграда сильно распылена по королевству из-за политических раздоров, отсутствия руководства и разбоя. На таких постах, как мост Стражника Томаса, всего несколько человек, и они не могут вести длительные наступательные операции против береговых племен.",al={"why guard thomas needs help","why aren't guards fighting murlocs","guard shortage elwynn","почему стражнику томасу нужна помощь","почему стража не бьет мурлоков","нехватка стражи элвиннский лес"}},{q="Какое доказательство уничтожения требует Стражник Томас?",a="Стражник Томас просит рваные плавники мурлоков, снятые прямо с соглядатаев и собирателей, обитающих в восточных водах Элвиннского леса.",al={"what drops torn murloc fins","quest proof","murloc fins","с кого падают рваные плавники мурлоков","доказательство задания","плавники мурлоков"}},{q="Знает ли маршал Дугхан о серьезности проблемы с мурлоками?",a="Да. Стражник Томас отмечает, что маршал Дугхан весьма встревожен положением с мурлоками на востоке Элвиннского леса, поэтому добрые вести об уничтоженных поселениях жизненно важны для местного боевого духа.",al={"marshal dughan murlocs","is goldshire aware","dughan reaction","маршал дугхан мурлоки","знают ли в златоземье","реакция дугхана"}}},fp="17,321,25.447.0,18.433.0,43.252.0,29.203.0,41.164.0,54.267.0,49.126.0,66.180.0"}
P.entries["quest:460"] = {n="В целости и сохранности",s="«В целости и сохранности» начинается, когда искатель приключений находит живую отрубленную голову Аларика, бывшего слуги некроманта Тула Когтя Ворона на Острове Фенриса. Аларик умоляет перенести его через Крепость Фенриса к безымянной могиле возле конюшен, где похоронены остальные его останки.",h="«В целости и сохранности» начинается, когда искатель приключений находит живую отрубленную голову Аларика...",kw={"alaric","fenris isle","fenris keep","rot hide","shallow grave","silverpine","talking head","thule ravenclaw","аларик","остров фенриса","крепость фенриса","гнилошкуры","неглубокая могила","серебряный бор","говорящая голова","тул коготь ворона"},ang={["class:Mage"]="Извращенная защита Тула, превратившая оборонительное заклинание в неизбежное проклятие расчлененной нежизни, служит суровым предостережением о том, что бывает, когда тайная магия искажена некромантией.",["race:Undead"]="Защитники Отрекшихся увидят в вероломном колдовстве Тула Когтя Ворона символ жестоких ужасов, которые творили по всему Лордерону чародеи на стороне Плети."},sec={{t="Преданный телохранитель",b="До своей жуткой участи Аларик был главным слугой и личным телохранителем Тула Когтя Ворона, могущественного мага на стороне Плети, обосновавшегося в Крепости Фенриса в Серебряном бору. Когда регион охватила Чума нежизни, Тул заявил, что защитит Аларика от нее своим тайным колдовством. Вместо этого извращенная защита навсегда заключила Аларика в мучительное состояние нежизни, а его сознание осталось полностью ясным в отрубленных частях тела."},{t="Игрушка Гнилошкуров",b="Создав гнолльских Гнилошкуров и заразив местные стаи некромантическим разложением, Тул обратился против собственного телохранителя. Некромант обезглавил Аларика и бросил его живую говорящую голову свирепым гноллам в качестве жуткой забавы. Пока Гнилошкуры тащили его тело в наспех вырытую неглубокую могилу за конюшнями крепости, голову они оставили себе как мрачную игрушку, пока не вмешался чужак."},{t="Воссоединение частей",b="Когда вы добираетесь до наспех вырытой земли возле конюшен, отрубленная голова Аларика воссоединяется с обезглавленным туловищем. Хотя Аларик по-прежнему скован проклятием нежизни, которое наложил на него Тул, возвращение частей тела приносит ему горькое облегчение."}},faq={{q="Кто такой Аларик?",a="Аларик был главным слугой и личным телохранителем Тула Когтя Ворона в Крепости Фенриса. Тул наложил на него неестественное заклинание под видом защиты от Чумы нежизни, но вместо этого оно обрекло его на вечную нежизнь.",al={"alaric","who is the talking head","talking head silverpine","аларик","кто такая говорящая голова","говорящая голова серебряный бор"}},{q="Почему Аларику отрубили голову?",a="Тул Коготь Ворона обезглавил Аларика вскоре после завершения своих опытов по созданию гнолльских Гнилошкуров. Затем некромант бросил отрубленную, но живую голову Аларика гноллам как игрушку.",al={"why is alaric a head","who cut off alarics head","почему аларик голова","кто отрубил голову аларику"}},{q="Где находится могила Аларика?",a="Его тело лежит в безымянной наспех вырытой неглубокой могиле на Острове Фенриса, во дворе Крепости Фенриса, рядом с конюшнями.",al={"where is alarics body","shallow grave location","where is the grave fenris","где тело аларика","где неглубокая могила","где могила остров фенриса"}},{q="Кто такие гноллы-Гнилошкуры?",a="Гноллы-Гнилошкуры — местные гноллы Острова Фенриса, превращенные в гниющих чудовищ, оскверненных нежизнью, в результате некромантических опытов Тула Когтя Ворона.",al={"rot hides","rot hide gnolls","fenris isle gnolls","гнилошкуры","гноллы гнилошкуры","гноллы острова фенриса"}},{q="Кто такой Тул Коготь Ворона?",a="Тул Коготь Ворона — человек-волшебник и некромант Плети, захвативший Крепость Фенриса посреди Озера Лордамер. Он использовал ее как лабораторию, чтобы осквернять гноллей и распространять влияние Плети.",al={"thule","thule ravenclaw","тул","тул коготь ворона"}},{q="Что происходит после того, как вы находите могилу?",a="После воссоединения с останками Аларик помогает вам найти замаскированный тайник с мощным жезлом, который затем можно вернуть магу Даларана Бетору Ледострелу в Подгороде.",al={"what next resting in pieces","resting in pieces followup","что дальше в целости и сохранности","в целости и сохранности продолжение"}}},fp="17,285,20.472.0,26.428.0,20.243.1,14.229.0,24.194.0,32.138.0,29.171.0,23.196.0,38.185.1"}
P.entries["quest:461"] = {n="Замаскированный тайник",s="Обнаружив разговорчивые останки Аларика в неглубокой могиле за Крепостью Фенриса, искатели приключений получают указание вернуться в цитадель. Следуя воспоминаниям умершего человека, они ищут забытую нишу за пыльным стеллажом, чтобы даровать ему последний покой и забрать древнюю реликвию.",h="Обнаружив разговорчивые останки Аларика в неглубокой могиле за Крепостью Фенриса, искатели приключений...",kw={"alaric","dusty shelf","fenris keep","hidden niche","rot hide","silverpine forest","thule ravenclaw","аларик","пыльный шкаф","крепость фенриса","замаскированный тайник","гнилошкуры","серебряный бор","тул коготь ворона"},ang={["class:Mage"]="Скрытая ниша хранит тайное наследие Крепости Фенриса: в ней спрятаны артефакты, напрямую связанные с бывшими волшебниками Даларана, такими как Тул Коготь Ворона.",["faction:Horde"]="Возвращение реликвий из сердца Крепости Фенриса подрывает позиции Тула на Острове Фенриса и помогает походу Отрекшихся за контроль над Серебряным бором.",["race:Undead"]="Для Отрекшихся иметь дело с беспокойными говорящими останками — привычное дело, но стремление Аларика к мирному покою среди человеческих руин напоминает о землях, которые им достались."},sec={{t="Беспокойная просьба",b="Даже после смерти Аларик хранит яркие воспоминания о Крепости Фенриса в ее лучшие дни. Он рад, что разведчики Орды извлекли его из неглубокой безымянной могилы, но его скелет отказывается просто так отправляться в Гробницу. Вместо этого он предлагает ценные сведения: в юго-западной башне крепости есть замаскированный тайник с предметом, которым очень дорожили Тул Коготь Ворона и его собратья-маги."},{t="Погребенный в стенах",b="Пробравшись мимо гнолльских Гнилошкуров, заполонивших островную крепость, путники несут останки Аларика по каменным коридорам. На верхних уровнях за пыльным книжным шкафом находится тайник, о котором он говорил. Когда его открывают, Аларик просит лишь замуровать его в древней кладке крепости, найдя утешение в покое внутри стен, где он провел счастливейшие дни своей жизни, вдали от жадных челюстей гноллей."}},faq={{q="Кто такой Аларик?",a="Аларик был бывшим главным слугой и телохранителем Тула Когтя Ворона в Крепости Фенриса, обезглавленным Тулом после создания гнолльских Гнилошкуров. Найденный погребенным у крепости в неглубокой могиле, его оживший дух помогает искателям приключений из Орды в обмен на достойное место упокоения в любимой цитадели.",al={"alaric lore","who is alaric","whose bones are these","предания об аларике","кто такой аларик","чьи это кости"}},{q="Где находится замаскированный тайник?",a="Замаскированный тайник скрыт в юго-западной башне Крепости Фенриса, за неприметным пыльным книжным шкафом на верхнем этаже.",al={"where is dusty shelf","where is the niche","hidden niche location","где пыльный шкаф","где ниша","где замаскированный тайник"}},{q="Какой предмет спрятан в нише?",a="В скрытой нише лежит старый жезл, которым когда-то дорожили Тул Коготь Ворона и его бывшие собратья из Даларана, а также другие вещи, которые Аларик оставляет тем, кто ему помог.",al={"what is in the niche","fenris keep treasure","thule item","что в нише","сокровище крепости фенриса","предмет тула"}},{q="Почему Аларик хочет остаться в Крепости Фенриса?",a="Аларик считает время, прожитое в Крепости Фенриса, лучшими днями своей жизни. Замурованные в каменной кладке, его останки обретают покой и защиту от гноллей-падальщиков, бродящих по дворам.",al={"why leave alaric in fenris","alaric resting place","почему оставить аларика в крепости фенриса","место упокоения аларика"}},{q="Что происходит после того, как вы находите шкаф?",a="После того как Аларик замурован в нише, а жезл забран, искатели приключений отправляются обратно в Подгород, чтобы передать реликвию Бетору Ледострелу.",al={"quest after hidden niche","what do i do with the wand","задание после замаскированного тайника","что делать с жезлом"}},{q="Почему Аларик велел вам оставить его сапоги?",a="Когда его кости извлекли из неглубокой могилы, Аларик в шутку настоял на том, чтобы оставить старые сапоги в земле, заметив, что они все равно никогда ему не подходили.",al={"alaric boots","leave boots behind","сапоги аларика","оставить сапоги"}}},fp="16,303,18.412.0,19.443.1,14.318.0,34.140.0,34.179.0,48.220.0,37.148.1,50.167.0"}
P.entries["quest:463"] = {n="Страж Природы",s="«Страж Природы» — задание Альянса, направляющее путников дальше вглубь болот Болотины. По поручению Первого помощника Фитсиммонса из Гавани Менетилов искатели приключений отправляются на северо-восток, в топи, на поиски таинственного существа, которое, по слухам, обитает среди зверей.",h="«Страж Природы» — задание Альянса, направляющее путников дальше вглубь болот Болотины.",kw={"dun modr","fitzsimmons","greenwarden","menethil","rethiel","tramping paws","wetlands","дун модр","фитсиммонс","страж природы","менетил","ретиль","вытоптанные луга","болотина"},ang={["class:Druid"]="Хотя простые портовые рабочие видят в Ретиле болотное чудовище, друиды сразу узнают присутствие древнего хранителя, связанного с природным равновесием.",["race:NightElf"]="Ночные эльфы, путешествующие вдали от Калимдора, находят знакомое, утешительное эхо древних стражей природы даже в сырой грязной почве Каз Модана."},sec={{t="Трактирные слухи и болотные байки",b="В доках Гавани Менетилов моряки и странники взахлеб рассказывают истории о звере, затаившемся в болоте. Первый помощник Фитсиммонс описывает Стража Природы как ходячий аппетит и предостерегает легковерных искателей: стоит сойти с сухой дороги, и «старина Зеленый» перекусит пополам. Для портового люда все огромное, что скрывается в мутных водах, — просто очередная людоедская опасность топей."},{t="Хранитель топей",b="Те, кто достаточно храбр, чтобы последовать указаниям к востоку от развилки в сторону Дун Модра, обнаруживают, что трактирные байки совершенно далеки от истины. Страж Природы — не бездумный хищник, а Ретиль, могучий древний защитник, связанный с дикой порослью Болотины. Вместо того чтобы пожирать забредших глупцов, Ретиль скорбит о порче земли и призывает смертных помочь очистить зараженные топи."}},faq={{q="Кто такой Страж Природы?",a="Страж Природы — это Ретиль, древний хранитель природы, обитающий в Болотине. Прибрежные моряки считают его свирепым чудовищем, но на деле он мудрый защитник, связанный с растениями и дикой природой.",al={"who is greenwarden","greenwarden identity","who is rethiel","кто такой страж природы","личность стража природы","кто такой ретиль"}},{q="Где найти Стража Природы?",a="Ретиль находится в болотах к востоку от главной дороги, возле развилки, ведущей к Дун Модру, на севере Болотины.",al={"greenwarden location","where is rethiel","greenwarden coordinates","где страж природы","где ретиль","координаты стража природы"}},{q="Почему Первый помощник Фитсиммонс считает Стража Природы опасным?",a="Фитсиммонс знает лишь трактирные слухи и суеверия Гавани Менетилов. Поскольку Болотина кишит зверями, моряки полагают, что любое гигантское существо среди крокодилов и хищников — просто очередной людоед.",al={"why is fitzsimmons scared","is the greenwarden evil","почему фитсиммонс боится","страж природы злой"}},{q="Что Ретиль хочет от путников?",a="Ретиль ищет защитников, которые позаботились бы о Болотине — по его словам, она плачет от гноящихся ран. Он велит посетителям охранять животных и усмирять угрозы, нарушающие местную экосистему.",al={"what does the greenwarden do","rethiel purpose","why meet the greenwarden","что делает страж природы","цель ретиля","зачем встречаться со стражем природы"}},{q="Что происходит после встречи со Стражем Природы?",a="Когда вы поговорите с Ретилем, он признает, что природа отзывается о вас хорошо, и даст вам задание «Вытоптанные луга», чтобы помочь справиться с бедами, терзающими топи.",al={"next quest after greenwarden","tramping paws quest","следующее задание после стража природы","задание вытоптанные луга"}},{q="Нужно ли для выполнения этого задания с кем-то сражаться?",a="Нет. Для задания нужно лишь пережить путь через Болотину и поговорить с Ретилем в его роще посреди топей.",al={"greenwarden combat","do i fight greenwarden","страж природы бой","сражаться со стражем природы"}}},fp="15,275,27.411.0,25.395.1,23.200.0,33.129.0,67.232.0,38.197.0,43.166.0,54.131.0"}
P.entries["quest:464"] = {n="Боевые знамена",s="Капитан Крепкий Кулак в Гавани Менетилов поручает защитникам Альянса напасть на лагерь орков клана Драконьей Пасти к северо-востоку от поселения и захватить их боевые знамена. Остатки орков, разбитые и рассеянные после Второй войны, вновь начали набираться сил в топях Болотины.",h="Капитан Крепкий Кулак в Гавани Менетилов поручает защитникам Альянса напасть на лагерь орков клана Драконьей...",kw={"captain stoutfist","dragonmaw","grim batol","menethil harbor","nek'rosh","nekros","war banners","wetlands","капитан крепкий кулак","драконья пасть","грим батол","гавань менетилов","нек'рош","некрос","боевые знамена","болотина"},ang={["class:Warrior"]="Нападение на военный лагерь станет прямым испытанием вашей доблести в схватке с закаленными ветеранами Второй войны, которые сражаются с безрассудной яростью даже без своих драконьих скакунов.",["faction:Alliance"]="Гавань Менетилов — важнейшая связующая нить между Штормградом, Стальгорном и северными землями; если позволить враждебному лагерю орков закрепиться поблизости, под угрозой окажется весь торговый морской путь.",["race:Dwarf"]="Драконья Пасть осквернила древнюю дворфийскую твердыню Грим Батол и обагрила войной окрестные горы, поэтому каждый павший воин Драконьей Пасти — это мера давно отложенного правосудия."},sec={{t="Остатки клана Драконьей Пасти",b="Во время Второй войны клан Драконьей Пасти подчинил себе красный драконий род из горной крепости Грим Батол. Когда их мерзкая власть пала, освобожденные драконы с яростной жаждой мести обратились против поработителей и почти истребили орков. Немногие выжившие бежали из Грим Батола в высокие горы к востоку от Раскопок Вельгара и укрылись там от гнева красного драконьего рода."},{t="Растущий лагерь",b="Хотя долгое время считалось, что клан разбит окончательно, Драконья Пасть вновь заявила о себе. К северо-востоку от Гавани Менетилов эти свирепые выжившие разбили действующий военный лагерь и водрузили свои багровые знамена среди болот. Понимая опасность агрессивного отряда орков так близко от портового поселения, капитан Крепкий Кулак хочет сократить их ряды и сорвать гордые боевые знамена как доказательство их поражения."},{t="Наследие Некроса",b="Захватив знамена, Крепкий Кулак сообщает, что вновь собравшихся орков возглавляет Нек'рош, сын небезызвестного чернокнижника Некроса. Некрос подчинял пленных красных драконов темным колдовством, пока оно не рассеялось, и бывшие пленники разорвали его на части. Теперь его сын, жаждущий мести, командует выжившими, одержимый навязчивой местью великим зверям, убившим его отца."}},faq={{q="Кто такие орки клана Драконьей Пасти в Болотине?",a="Это остатки клана орков, поработившего красный драконий род во время Второй войны. Потеряв власть над драконами, они были безжалостно истреблены и рассеяны, а выжившие бежали из Грим Батола и укрылись в горах и болотах.",al={"dragonmaw orcs wetlands","who are dragonmaw","wetlands orcs","орки драконьей пасти болотина","кто такие драконья пасть","орки болотины"}},{q="Зачем капитану Крепкому Кулаку их боевые знамена?",a="Крепкий Кулак считает недавно укрепленный лагерь к северо-востоку от Гавани Менетилов серьезной угрозой для поселения. Он требует боевые знамена орков как вещественное доказательство того, что солдаты Альянса совершили налет на лагерь и ослабили их боевую мощь.",al={"why collect banners","captain stoutfist banners","зачем собирать знамена","капитан крепкий кулак знамена"}},{q="Что стало с драконами клана Драконьей Пасти?",a="Когда темная магия, державшая драконов в плену, ослабла, красный драконий род обратился против поработителей. Драконы яростно преследовали орков Драконьей Пасти по всему Каз Модану и почти полностью истребили клан.",al={"what happened to the dragons","dragonmaw dragons","что стало с драконами","драконы драконьей пасти"}},{q="Кто теперь возглавляет клан Драконьей Пасти?",a="Клан возглавляет Нек'рош, сын прежнего предводителя Драконьей Пасти Некроса. Нек'рош сплотил выживших и поклялся отомстить красным драконам, убившим его отца.",al={"dragonmaw leader","who is nek'rosh","предводитель драконьей пасти","кто такой нек'рош"}},{q="Где скрывался клан Драконьей Пасти до создания этого лагеря?",a="Бежав из Грим Батола, выжившие орки прятались в суровых горах к востоку от Раскопок Вельгара, а затем отправились в болота Болотины и построили там лагерь.",al={"where did dragonmaw hide","dragonmaw refuge","где прятался клан драконьей пасти","убежище драконьей пасти"}},{q="Связаны ли эти орки клана Драконьей Пасти с Ордой Тралла?",a="Нет. Эти остатки клана Драконьей Пасти — независимые изгои, движимые местью и стремлением выжить, и действуют совершенно вне новой Орды, основанной вождем Траллом в Калимдоре.",al={"are dragonmaw in horde","dragonmaw thrall horde","драконья пасть в орде","драконья пасть тралл орда"}}},fp="11,292,25.388.0,19.393.0,20.404.1,43.247.0,50.237.0,46.196.0,33.172.1,57.173.0,56.174.0"}
P.entries["quest:465"] = {n="Гамбит Нек'роша",s="«Гамбит Нек'роша» — срочное боевое задание, которое дает капитан Крепкий Кулак в Гавани Менетилов. Узнав, что вождь Нек'рош построил осадные орудия, чтобы обстрелять беззащитный портовый город, пока подкрепление отрезано у Дун Альгаза, Альянс отправляет отважных добровольцев вглубь болот сжечь катапульты Драконьей Пасти до начала штурма.",h="«Гамбит Нек'роша» — срочное боевое задание, которое дает капитан Крепкий Кулак в Гавани Менетилов.",kw={"captain stoutfist","catapults","dragonmaw","dun algaz","menethil harbor","nek'rosh","nek'rosh's gambit","wetlands","капитан крепкий кулак","катапульты","драконья пасть","дун альгаз","гавань менетилов","нек'рош","гамбит нек'роша","болотина"},ang={["class:Warrior"]="Штурм укрепленного вражеского лагеря ради уничтожения тяжелой осадной артиллерии требует агрессивной тактики на передовой и жестокого рукопашного боя.",["faction:Alliance"]="Поскольку Дун Альгаз скован боями, Альянсу приходится полагаться на отважных добровольцев, а не на регулярные армии, чтобы сорвать планы военной машины Драконьей Пасти.",["race:Dwarf"]="Гавань Менетилов — врата дворфов Бронзобородов к западному морю; потеря ее из-за осадных орудий Драконьей Пасти подорвала бы морское сообщение Стальгорна."},sec={{t="Надвигающаяся осада",b="Пока искатели приключений Альянса сражались с рейдерскими отрядами Драконьей Пасти, дворфийские разведчики раскрыли истинные замыслы клана. Вождь Нек'рош руководил постройкой полноценных осадных катапульт в лагерях Болотины. Его цель дерзка и губительна: привести осадные машины к Гавани Менетилов, разбить стены крепости и уничтожить главный торговый порт Альянса на западном побережье."},{t="Отрезаны у Дун Альгаза",b="Опасность для Гавани Менетилов усугубляется узким проходом у Дун Альгаза. Ожесточенные стычки и активность зеленокожих в горном проходе фактически отрезают низины от главных гарнизонов Стальгорна. Без скорой помощи из Каз Модана капитан Крепкий Кулак не может выделить отряд для охраны окрестностей, и упреждающая диверсия против катапульт остается единственным шансом гавани на спасение."},{t="Огонь в лагере",b="Вооружившись Дворфийским трутом, разведчики должны проникнуть прямо в сердце лагеря Драконьей Пасти. Поджог громоздких деревянных машин лишит Нек'роша артиллерии, оставит его воинов беззащитными и отнимет огневую мощь, необходимую для разрушения обороны Менетила, пока с самим полководцем не придется сразиться."}},faq={{q="Кто такой Нек'рош?",a="Нек'рош — безжалостный вождь, возглавляющий остатки клана Драконьей Пасти в Болотине. Он ведет прямую военную кампанию с целью осадить Гавань Менетилов.",al={"nekrosh","chieftain nek'rosh","who is nek rosh","некрош","вождь нек'рош","кто такой нек рош"}},{q="Почему Гавани Менетилов грозит такая опасность?",a="Город сильно зависит от морской торговли и отделен от Стальгорна. Поскольку проходы у Дун Альгаза забиты сражениями, подкрепление не может прибыть по суше, и город не способен выдержать массированную осаду.",al={"menethil danger","why harbor vulnerable","threat to menethil","опасность менетила","почему гавань уязвима","угроза гавани менетилов"}},{q="В чем цель этого задания?",a="Вам поручено принести Дворфийский трут в лагерь Драконьей Пасти, чтобы поджечь и уничтожить их осадные катапульты, пока их не двинули на Гавань Менетилов.",al={"gambit objective","what do i do","catapult mission","цель гамбита","что делать","задание катапульты"}},{q="Кто дает это поручение?",a="Приказ отдает капитан Крепкий Кулак, дворфийский офицер, руководящий обороной гавани и кампанией против Драконьей Пасти.",al={"quest giver","who gives nekrosh gambit","stoutfist role","персонаж, выдающий задание","кто дает гамбит нек'роша","роль крепкого кулака"}},{q="Что происходит после уничтожения катапульт?",a="Когда осадные машины обратятся в пепел, угрозу нужно устранить окончательно, выследив и убив самого вождя Нек'роша.",al={"after catapults","next quest","what next","после катапульт","следующее задание","что дальше"}},{q="Почему Стальгорн не может прислать войска на помощь Менетилу?",a="Дорога, соединяющая Лок Модан с Болотиной, проходит через Дун Альгаз, который находится под ожесточенными нападениями и засадами врагов, и надежное сообщение по суше прервано.",al={"dun algaz block","why no reinforcements","ironforge help","блокада дун альгаза","почему нет подкрепления","помощь стальгорна"}}},fp="17,367,15.415.0,20.398.0,22.310.0,16.169.0,38.240.0,33.170.0,27.139.0,46.147.1,49.160.0"}
P.entries["quest:466"] = {n="Поиски огневита",s="Пилот Камнекожиц в Поселке Сталежара ищет образцы летучей руды огневита, обнаруженной в Болотине. Полагая, что ее взрывные свойства могут совершить переворот в артиллерийских боеприпасах, он поручает шахтерам отправиться на север и добыть опасный минерал из уединенной пещеры.",h="Пилот Камнекожиц в Поселке Сталежара ищет образцы летучей руды огневита, обнаруженной в Болотине.",kw={"algaz gate","artillery","cannon shells","dun morogh","incendicite","mining","ore","pilot stonegear","steelgrill's depot","wetlands","врата альгаза","артиллерия","пушечные снаряды","дун морог","огневит","горное дело","руда","пилот камнекожиц","поселок сталежара","болотина"},ang={["profession:Engineering"]="Взрывчатые составы, грозящие подорвать своих создателей, — обычное дело для инженеров-изобретателей, ищущих очередной большой взрыв.",["profession:Mining"]="Добыча огневита требует опытных рук с киркой; летучесть минерала делает бережное извлечение жилы настоящим испытанием мастерства шахтера.",["race:Dwarf"]="Дворфийские инженеры и артиллеристы славятся продвижением технологий пороха, и освоение огневитовых снарядов вполне вписывается в осадные традиции Каз Модана."},sec={{t="Опасная находка",b="Слух о редком и нестабильном минерале, известном как огневит, дошел до летчиков и механиков Поселка Сталежара. Говорят, богатые жилы находятся в пещере к северо-западу от Врат Альгаза, в сырых болотах Болотины. Огневит крайне реактивен и опасен в обращении, и за ним закрепилась слава руды, взрывающейся перед лицом неосторожных шахтеров."},{t="Боеприпасы будущего",b="Там, где другие видят опасность для шахтеров, Пилот Камнекожиц видит военный потенциал. При правильной обработке огневит мог бы стать разрушительным топливом или зарядом для дворфийской артиллерии, создавая снаряды, способные разрушать укрепленную оборону. Камнекожиц стремится добыть сырые образцы, чтобы отважные, а может, и безрассудные исследователи могли начать испытывать способы плавки, не сровняв поселок с землей."}},faq={{q="Для чего используется руда огневита?",a="Огневит — крайне летучий взрывчатый минерал. Пилот Камнекожиц намерен испытать способы плавки, чтобы использовать его реактивные свойства для мощных артиллерийских боеприпасов и пушечных снарядов.",al={"incendicite uses","what does incendicite do","применение огневита","для чего нужен огневит"}},{q="Где находят огневит?",a="Жилы руды расположены в системе пещер к северо-западу от Врат Альгаза, в южных горах Болотины.",al={"incendicite location","where to get incendicite","где найти огневит","расположение огневита","где добыть огневит"}},{q="Кто такой Пилот Камнекожиц?",a="Пилот Камнекожиц — дворфийский летчик, служащий в Поселке Сталежара в Дун Мороге, который вместе с механиками и осадными инженерами совершенствует дворфийские боевые машины.",al={"pilot stonegear","who gives this quest","пилот камнекожиц","кто дает это задание"}},{q="Почему для добычи этой руды нужна кирка?",a="Огневит встречается в естественных рудных жилах, а не в россыпях на поверхности. Шахтеру нужно достаточное мастерство, чтобы безопасно выбить хрупкую взрывоопасную руду из породы, не вызвав взрыва.",al={"do i need mining","mining skill needed","нужна ли горное дело","нужный навык горного дела"}},{q="Безопасно ли обращаться с огневитом?",a="Нет. Руда печально известна своей нестабильностью и представляет серьезную угрозу случайного взрыва при добыче, перевозке и плавке.",al={"is incendicite dangerous","does incendicite explode","опасен ли огневит","взрывается ли огневит"}},{q="Как это связано с заданием «Найдите Камнекожца»?",a="Это задание напрямую продолжает «Найдите Камнекожца», в котором Пилот Камнекожиц сначала собирал сведения о возможных новых материалах, а затем направил искателей в Болотину.",al={"stonegear search followup","quest chain","продолжение найдите камнекожца","цепочка заданий"}}},fp="22,275,20.352.0,21.392.0,33.191.0,27.125.0,23.168.0,47.204.0,30.135.0,44.188.0"}
P.entries["quest:467"] = {n="Найдите Камнекожца",s="«Найдите Камнекожца» — поручение Альянса, направляющее отважных путников к Пилоту Камнекожицу в Поселке Сталежара в Дун Мороге. Увлеченный оператор осадной машины прослышал о диковинном минерале и ищет смелого исследователя, который добудет свежее топливо для боеприпасов его танка.",h="«Найдите Камнекожца» — поручение Альянса, направляющее отважных путников к Пилоту Камнекожицу в Поселке...",kw={"dun morogh","incendicite","kadrell","longbeard","pilot stonegear","siege engine","steelgrill's depot","stonegear","дун морог","огневит","кэдрелл","длиннобород","пилот камнекожиц","осадная машина","поселок сталежара","камнекожиц"},ang={["profession:Engineering"]="Инженеры, проводящие дни за возней со взрывчаткой, оценят преданность Камнекожица делу усиления огневой мощи своего танка.",["profession:Mining"]="Шахтерам, интересующимся диковинными и горючими породами, придутся по душе слухи Камнекожица о редкой подземной руде.",["race:Dwarf"]="Для дворфийских горных пехотинцев и механиков помочь собрату-пилоту в Поселке Сталежара — почетный долг по совершенствованию арсенала Каз Модана.",["race:Gnome"]="Гномы-изобретатели легко оценят стремление Пилота Камнекожица вывести обычное осадное оружие за пределы привычных норм безопасности."},sec={{t="Амбиции изобретателя",b="Дворфийские осадные машины — легендарные инженерные творения, но их операторы редко оставляют все как есть. По Стальгорну и Лок Модану быстро расходится слух, что Пилот Камнекожиц, служащий неподалеку от столицы, замышляет усилить удар своей боевой машины. Направит ли путников к нему Пилот Длиннобород или Горный пехотинец Кэдрелл, их просто просят встретиться с честолюбивым пилотом и выслушать его предложение."},{t="Путь в Поселок Сталежара",b="Пилот Камнекожиц устроил мастерскую в Поселке Сталежара — на испытательном полигоне и сборном дворе у дороги к востоку от Караноса. Среди лязга шестерен и клубов пара Камнекожиц высматривает старателей, достаточно смелых, чтобы добыть редкую летучую руду, способную поднять огневую мощь его танка на невиданную высоту."}},faq={{q="Кто выдает это задание?",a="К Пилоту Камнекожицу вас может направить либо Пилот Длиннобород в Стальгорне, либо Горный пехотинец Кэдрелл на дороге в Лок Модане.",al={"quest giver","who starts stonegear search","where to get quest","персонаж, выдающий задание","кто начинает найдите камнекожца","где взять задание"}},{q="Где найти Пилота Камнекожица?",a="Пилот Камнекожиц служит в Поселке Сталежара в Дун Мороге, неподалеку по тропе к северо-востоку от Караноса.",al={"stonegear location","where is pilot stonegear","steelgrills depot stonegear","где камнекожиц","где пилот камнекожиц","поселок сталежара камнекожиц"}},{q="Что нужно Пилоту Камнекожицу?",a="Камнекожиц любит дорабатывать свою осадную машину и одержим поисками редких залежей минералов, способных резко усилить огневую мощь боеприпасов его танка.",al={"stonegear goal","why does stonegear want me","what does stonegear want","цель камнекожица","зачем я нужен камнекожицу","что хочет камнекожиц"}},{q="Какое задание следует за этим?",a="Когда вы доложите Пилоту Камнекожицу в поселке, он даст вам задание «Поиски огневита» — добыть летучую руду в Болотине.",al={"next quest","stonegear follow up","what comes after stonegears search","следующее задание","продолжение камнекожиц","что после найдите камнекожца"}},{q="Доступно ли это задание только Альянсу?",a="Да, Пилот Камнекожиц и его знакомые — верные члены армии Стальгорна и Альянса.",al={"can horde do stonegears search","faction requirement","может ли орда взять найдите камнекожца","требование фракции"}},{q="Почему поселок интересуется дикой рудой?",a="Дворфийские инженеры и пилоты танков постоянно экспериментируют с новыми зажигательными составами, пиротехникой и летучими элементами, чтобы дать своим боевым машинам преимущество над троггами, Черным Железом и дикими зверями.",al={"why siege engine ore","dwarf tank gunpowder","зачем руда осадной машине","дворфийский танк порох"}}},fp="18,285,21.429.0,29.324.0,22.130.0,33.107.0,31.162.0,28.155.0,28.99.0,41.202.0"}
P.entries["quest:468"] = {n="Отчитайтесь перед горным пехотинцем Рокхаром.",s="Отчитайтесь перед горным пехотинцем Рокхаром — подготовительное задание Альянса, направляющее искателей приключений на север от сторожевых постов Лок Модана к Дун Альгазу. Горный пехотинец Кэдрелл отправляет способных путников к Рокхару, который организует важную экспедицию в сырые низины Болотины. Это задание служит проходом, соединяющим родину дворфов с северными землями.",h="Отчитайтесь перед горным пехотинцем Рокхаром — подготовительное задание Альянса, направляющее искателей...",kw={"dun algaz","ironforge","kadrell","loch modan","mountaineer","rockgar","scouting","wetlands","дун альгаз","стальгорн","кэдрелл","лок модан","горный пехотинец","разведка","рокхар","болотина"},ang={["faction:Alliance"]="Защита Дун Альгаза обеспечивает беспрепятственное сухопутное сообщение с Гаванью Менетилов, главным западным портом Альянса в Восточных королевствах.",["race:Dwarf"]="Отклик на призыв собратьев-горных пехотинцев укрепляет важнейшую сухопутную связь между сердцем Стальгорна и владениями дворфов в Болотине."},sec={{t="Дорога к северным вратам",b="Дун Альгаз — важнейшая артерия между Лок Моданом и болотистыми просторами Болотины. Укрепленный проход, встроенный в северный горный хребет, давно обеспечивает безопасное движение торговцев, гонцов и военных отрядов между Стальгорном и поселениями Альянса дальше на север. Из-за растущей напряженности на границах горный пехотинец Кэдрелл пристально следит за проходящими путниками и набирает выносливых добровольцев для усиления северных застав."},{t="Миссия пошла не так",b="Горный пехотинец Кэдрелл поначалу отправляет новобранцев, рассчитывая на обычную разведку, но в Дун Альгазе все оказывается куда опаснее. Прибыв к северным вратам, искатели приключений обнаруживают, что горный пехотинец Рокхар готовится к настоящему бою, а не к мирной разведке. Враждебные силы, заполонившие проход, быстро превращают простую разведку в жестокую, тяжелую борьбу за контроль над ущельем."}},faq={{q="Кто дает задание отчитаться перед Рокхаром?",a="Задание дает горный пехотинец Кэдрелл. Он расположился в Телсамаре, напротив таверны «Крепкое пойло», и наблюдает за главной дорогой, ведущей к горному проходу.",al={"who starts report to mountaineer rockgar","quest giver rockgar","kadrell quest","кто начинает отчитайтесь перед рокхаром","персонаж, выдающий задания рокхар","задание кэдрелл"}},{q="Где найти горного пехотинца Рокхара?",a="Горный пехотинец Рокхар стоит к северу по дороге из Лок Модана и охраняет вход в горные туннели Дун Альгаза.",al={"rockgar location","where is rockgar","mountaineer rockgar spot","где рокхар","местонахождение рокхара","горный пехотинец рокхар"}},{q="Почему это задание в Дун Альгазе так важно?",a="Дун Альгаз — главный сухопутный путь, соединяющий Лок Модан с Болотиной. Чтобы Альянс мог поддерживать цепочки снабжения, военную связь и безопасное сообщение с Гаванью Менетилов и далее, проход необходимо держать свободным.",al={"why go to dun algaz","dun algaz importance","wetlands route","зачем идти в дун альгаз","важность дун альгаза","путь в болотину"}},{q="Что происходит после встречи с горным пехотинцем Рокхаром?",a="Рокхар сразу привлекает вас к заданию «Альгазская битва» и сообщает, что задуманная разведка превратилась в кровавую схватку за очистку горных туннелей от враждебных сил.",al={"what comes after report to rockgar","rockgar follow up","next quest after rockgar","что после отчитайтесь перед рокхаром","продолжение рокхара","следующее задание после рокхара"}},{q="Какого уровня должен быть искатель приключений для этого задания?",a="Задание рассчитано на опытных путников примерно 20–21 уровня, которые заканчивают дела в Лок Модане и готовятся к опасной Болотине.",al={"rockgar quest level","level for dun algaz","when to go to wetlands","уровень задания рокхара","уровень для дун альгаза","когда идти в болотину"}},{q="Доступно ли это задание персонажам Орды?",a="Нет. Горные пехотинцы Стальгорна беззаветно преданы королю Магни Бронзобороду и Альянсу, поэтому принять задание могут только искатели приключений Альянса.",al={"can horde do this quest","horde report to rockgar","может ли орда взять задание","орда отчитайтесь перед рокхаром"}}},fp="29,377,26.479.0,19.428.1,41.167.0,37.132.0,51.228.0,47.202.1,56.163.0,44.149.0"}
P.entries["quest:4681"] = {n="Останки на берегу",s="«Останки на берегу» — расследование, начатое Гвеннид Блай'Леггонд в Аубердине, чтобы изучить погибших морских обитателей вдоль окутанного туманом побережья Темных берегов. От имени Храма Луны в Дарнассе она отправляет искателей приключений осмотреть скелет гигантской морской черепахи, лежащий под водой к западу от деревни. Исследование должно объяснить, почему столько морских существ выбрасывается на берег или гибнет у побережья.",h="«Останки на берегу» — расследование, начатое Гвеннид Блай'Леггонд в Аубердине, чтобы изучить погибших морских...",kw={"auberdine","beached creature","darkshore","darnassus","gwennyth bly'leggonde","sea turtle","sea turtle remains","teldrassil","temple of the moon","аубердин","выброшенное существо","темные берега","дарнасс","гвеннид блай'леггонд","морская черепаха","останки морской черепахи","тельдрассил","храм луны"},ang={["class:Druid"]="Массовая гибель и беспорядочное бегство древних морских тварей Темных берегов намекают на порчу или нарушение равновесия природы, исходящие из вод вокруг Тельдрассила.",["class:Priest"]="Это расследование помогает жрицам Элуны из Храма Луны, которые следят за духовным и природным благополучием северного Калимдора.",["race:NightElf"]="Аубердин — врата между Тельдрассилом и материком; свидетельство того, что морская жизнь бежит от вашего нового дома, — тревожное предзнаменование."},sec={{t="Тревожный прилив",b="Туманные пляжи Темных берегов стали кладбищем океанских гигантов. Выброшенные на берег громадины и утонувшие левиафаны усеивают пески и мелководье, приводя в недоумение ночных эльфов Аубердина. Уже изучив выбросившееся на берег морское существо, Гвеннид Блай'Леггонд поручает путникам нырнуть в воды к западу от причалов, возле затонувшего судна, осмотреть кости огромной морской черепахи и собрать доказательства для Храма Луны."},{t="Бегство от Мирового Древа",b="Конечная цель Гвеннид — собрать достаточно вещественных доказательств, чтобы подать официальный отчет жрицам Элуны в Дарнассе. Ее первые выводы указывают на крайне тревожную гипотезу: эти мирные морские животные гибнут не случайно, а намеренно бегут от чего-то в открытом море — возможно, в водах, окружающих сам Тельдрассил."}},faq={{q="Почему морские существа выбрасываются на берег Темных берегов?",a="The cause is still unknown. Gwennyth needs samples from the stranded creatures so she can file a report with the Temple of the Moon and continue the research.",al={"why turtles dying","beached creatures darkshore","why beached whales","почему гибнут черепахи","выброшенные существа темные берега","почему выбрасываются киты"}},{q="Кто такая Гвеннид Блай'Леггонд?",a="Гвеннид Блай'Леггонд — исследовательница из ночных эльфов, живущая в Аубердине и напрямую подчиняющаяся Храму Луны в Дарнассе. Она документирует волну мертвых морских существ, выброшенных на берег вдоль побережья Темных берегов.",al={"gwennyth","auberdine researcher","quest giver washed ashore","гвеннид","исследователь аубердина","персонаж, выдающий задания останки на берегу"}},{q="Где находится скелет морской черепахи?",a="Скелет морской черепахи лежит на дне океана строго к западу от причалов Аубердина, рядом с обломками затонувшего судна у побережья Темных берегов.",al={"turtle remains location","where skeletal turtle","sea turtle bones","где останки черепахи","где скелет черепахи","кости морской черепахи"}},{q="Какое отношение к этому имеет Храм Луны?",a="Храм Луны ведает экологическими и духовными вопросами земель ночных эльфов. Гвеннид нужны вещественные образцы, чтобы представить жрицам официальный отчет о странной массовой гибели.",al={"why darnassus care","temple of the moon role","priestesses of elune involvement","почему дарнасс интересуется","роль храма луны","участие жриц элуны"}},{q="Есть ли еще выброшенные на берег существа?",a="Да. Гвеннид отмечает, что выброшенные существа разбросаны по всему побережью Темных берегов, и призывает искателей приключений обыскивать пески и собирать останки других выбросившихся громад.",al={"other beached sea creatures","more sea creature quests","darkshore beached behemoth","другие выброшенные морские существа","еще задания про морских существ","выброшенные громадины темные берега"}},{q="Чем отличаются два задания «Останки на берегу»?",a="Первое задание отправляет вас осмотреть существо, выброшенное на ближайший пляж, а следующее просит проплыть к западу от причалов и осмотреть затонувший скелет морской черепахи.",al={"washed ashore part 1 vs part 2","two washed ashore quests","washed ashore chain","останки на берегу часть 1 и часть 2","два задания останки на берегу","цепочка останки на берегу"}}},fp="13,421,17.452.0,26.368.1,50.158.0,29.222.0,41.151.0,54.205.0,41.183.0,62.180.0"}
P.entries["quest:469"] = {n="Ежедневная доставка",s="«Ежедневная доставка» — поручение от дворфа-охотника Эйнара Камнехвата, который просит путников, идущих в Гавань Менетилов, доставить местному кожевнику выделанные шкуры кроколисков. Вместо того чтобы сталкиваться с домашними неурядицами, Эйнар полагается на проходящих мимо искателей приключений, чтобы поддерживать поставки.",h="«Ежедневная доставка» — поручение от дворфа-охотника Эйнара Камнехвата, который просит путников, идущих в...",kw={"crocolisk skins","einar stonegrip","james halloran","menethil harbor","sida","tanner","wetlands","шкуры кроколисков","эйнар камнехват","джеймс халлоран","гавань менетилов","сида","кожевник","болотина"},ang={["faction:Alliance"]="Гавань Менетилов — главные морские врата, соединяющие владения Стальгорна с северными континентами, поэтому простые товары, такие как кожа кроколисков, жизненно важны для снаряжения местных стражей и портовых рабочих.",["race:Dwarf"]="Даже вдали от Стальгорна дворфы ведут торговлю в сырых низинах, хотя семейные ссоры, судя по всему, оказываются труднее болотных тварей."},sec={{t="Неохотный курьер",b="В болотах Эйнар Камнехват зарабатывает на жизнь охотой на местную живность, особенно на агрессивных кроколисков, подстерегающих у водных путей. Он собирает множество ценных шкур, но доставить их можно только дома, в Гавани Менетилов. Не желая встречаться с женой Сидой в тяжелый период их брака, Эйнар предпочитает оставаться в поле и передавать свертки проходящим путникам."},{t="Торговля в Менетиле",b="Шкуры предназначены для Джеймса Халлорана, кожевника из Гавани Менетилов. Халлоран зависит от регулярных поставок от местных охотников, чтобы шить сапоги и выделывать кожу для торговцев и моряков, проходящих через порт. Заметив недельное отсутствие Эйнара, кожевник легко догадывается о семейной ссоре, стоящей за доставкой через посредников, и размышляет, что его жене, возможно, придется вмешаться и уладить дело с Сидой."}},faq={{q="Почему Эйнар Камнехват не доставляет шкуры сам?",a="Эйнар признается, что у его жены Сиды в последнее время дурное настроение. Чтобы не сталкиваться с ее нравом, он задерживается в Болотине и нанимает проходящих путников доставлять его товар в город.",al={"why einar hiding","einar wife problem","why won't einar go home","почему эйнар прячется","проблемы эйнара с женой","почему эйнар не идет домой"}},{q="Кто такой Джеймс Халлоран?",a="Джеймс Халлоран — кожевник и мастер по кожам из Гавани Менетилов. Он скупает сырые шкуры у местных охотников, чтобы выделывать их и продавать как сапоги и готовые кожаные изделия.",al={"halloran tanner","who is james halloran","кожевник халлоран","кто такой джеймс халлоран"}},{q="Кто такая Сида?",a="Сида — жена Эйнара Камнехвата, живущая в Гавани Менетилов. Ее недавнее скверное настроение — главная причина, почему Эйнар проводит дни в болотах, избегая возвращения домой.",al={"einar wife","who is sida","жена эйнара","кто такая сида"}},{q="Какие шкуры нужно доставить?",a="Доставка состоит из связки шкур кроколисков, добытых у крупных рептилий, населяющих трясины и водные пути Болотины.",al={"what skins","daily delivery items","какие шкуры","предметы ежедневной доставки"}},{q="Знает ли Халлоран, почему Эйнар избегает Гавани Менетилов?",a="Да. Когда вы передаете сверток, Халлоран замечает, что Эйнар не появлялся почти неделю, и сразу догадывается, что причина — неурядицы с Сидой.",al={"does halloran know","tanner reaction","знает ли халлоран","реакция кожевника"}},{q="Где происходит эта доставка?",a="Доставка начинается у Эйнара Камнехвата на дороге в Болотине и заканчивается в мастерской Джеймса Халлорана в Гавани Менетилов на западном побережье.",al={"where turn in","daily delivery location","где сдать","место ежедневной доставки"}}},fp="14,294,19.419.0,20.429.0,54.184.0,22.178.0,12.166.0,41.139.0,57.157.0,36.158.0"}
P.entries["quest:47"] = {n="Золотая пыль",s="«Золотая пыль» — одно из первых заданий на добычу, которое предлагает Реми Повторюх из Златоземья. Нервный торговец платит искателям приключений за сбор необработанной золотой пыли у кобольдов, заполонивших шахты Элвиннского леса. Это честная работа для начинающих путников, но странные связи Реми намекают, что за его делом стоит нечто большее, чем простая обработка металла.",h="«Золотая пыль» — одно из первых заданий на добычу, которое предлагает Реми Повторюх из Златоземья.",kw={"elwynn forest","fargodeep mine","gold dust","goldshire","jasperlode mine","kobold","remy two times","элвиннский лес","рудник подземных глубин","золотая пыль","златоземье","яшмовая шахта","кобольд","реми повторюх"},ang={["class:Rogue"]="Приглушенные манеры Реми и знак от безымянных «компаньонов» несут безошибочный запах подпольных синдикатов, действующих под безмятежной поверхностью Златоземья.",["faction:Alliance"]="То, что важнейшие залежи золота и руды Элвиннского леса удерживают дикие кобольды, а не королевские рудокопы, показывает, насколько истощены военные силы королевства.",["profession:Mining"]="Шахтеры, обыскивающие Рудник Подземных Глубин и Яшмовую шахту, обнаружат кобольдов прямо у богатейших медных жил, так что их придется выбить ради добычи руды."},sec={{t="Город карманов и кирок",b="Златоземье лежит на перекрестке дорог Элвиннского леса, где встречаются торговцы, городская стража и усталые путники. Среди них — Реми Повторюх, подозрительный тип: привычка повторять слова скрывает его острое чутье на выгоду. Вместо того чтобы нанимать дорогостоящие бригады шахтеров для добычи сырья, Реми пользуется странствующими искателями приключений, заходящими в таверну «Гордость Льва». Его предложение просто: добыть золотую пыль, припрятанную местными вредителями, и обменять ее прямо на деньги."},{t="Добыча кобольдов",b="Кобольды полностью захватили самые ценные подземные выработки Элвиннского леса — Рудник Подземных Глубин на юге и Яшмовую шахту на северо-востоке. Прокладывая ходы в темноте в поисках любимых свечей и блестящих безделушек, эти крысоподобные землекопы собирают в сумках остатки породы и крупицы неочищенной руды. Отгонять их — в интересах королевства, но сбор их пыли превращает истребление вредителей в доходное дело."},{t="Тени за прилавком",b="Реми утверждает, что щедро платит из чисто торговых соображений, но его награды таят скрытые предостережения. Получив пыль, он вручает помощникам небольшой знак, представляющий его «компаньонов». В Элвиннском лесу, который все сильнее душат организованные бандиты, неоплаченные каменщики и тайные сети, действующие в тени Штормграда, молчаливые посредники Реми могут замышлять для этого золота нечто куда большее, чем обычная деревенская торговля."}},faq={{q="Кто такой Реми Повторюх?",a="Реми Повторюх — эксцентричный местный торговец, обосновавшийся у таверны «Гордость Льва» в Златоземье. Он известен тем, что повторяет концы своих фраз, скупает ценные материалы у странствующих искателей приключений и поддерживает связи с темными личностями.",al={"remy two times","who gives gold dust exchange","remy in goldshire","реми повторюх","кто выдает задание золотая пыль","реми в златоземье"}},{q="Откуда у кобольдов золотая пыль?",a="Кобольды проводят жизнь, прокладывая ходы в рудных жилах Элвиннского леса, например в Руднике Подземных Глубин и Яшмовой шахте. Пока они скребут и роют породу в поисках сокровищ и свечного воска, необработанные золотые крупицы и пыль скапливаются в их карманах и сумках.",al={"why do kobolds have gold dust","where does gold dust come from","почему у кобольдов золотая пыль","откуда берется золотая пыль"}},{q="Где найти шахты, о которых говорит Реми?",a="Кобольдов с золотой пылью можно найти главным образом в Руднике Подземных Глубин и рядом с ним, к югу от Златоземья, а также в Яшмовой шахте на северо-востоке, у границы с Лесопилкой Восточной долины.",al={"where are the mines","where to find kobolds elwynn","где шахты","где найти кобольдов элвиннский лес"}},{q="Почему Штормград позволяет кобольдам управлять их шахтами?",a="Король Вариан Ринн пропал, а Дом знати отказывается выделять войска для окраин, поэтому городская стража Штормграда растянута до предела. Местные гарнизоны не могут очистить шахты, и они остаются во власти кобольдов, а сражаются независимые путники.",al={"why aren't the mines guarded","why did stormwind lose the mines","почему шахты не охраняются","почему штормград потерял шахты"}},{q="Используется ли золотая пыль в кузнечном деле или торговле?",a="В необработанном виде, как ее носят кобольды, золотая пыль слишком мелкая и нечистая для обычной кузнечной работы. Ее продают как сырье торговцам вроде Реми, которые собирают и очищают ее по своим частным каналам.",al={"what is gold dust used for","can you smelt gold dust","для чего нужна золотая пыль","можно ли переплавить золотую пыль"}}},fp="18,350,27.491.0,18.444.0,26.430.1,24.246.0,31.255.0,45.216.0,56.269.0,45.222.0"}
P.entries["quest:470"] = {n="Прожорливый слизнюк",s="Совершая обычное паломничество к Гробнице Железноборода, Сида испугалась мерзких слизней, бродивших среди курганов, и бросила в них свою сумку, чтобы отвлечь. Не в силах снова встретиться с ползучей слизью, она просит отважных искателей приключений в Гавани Менетилов отыскать тварь, проглотившую ее вещи.",h="Совершая обычное паломничество к Гробнице Железноборода, Сида испугалась мерзких слизней, бродивших среди...",kw={"dun modr","ironbeard's tomb","menethil harbor","ooze","ooze-covered bag","sida","sida's bag","wetlands","дун модр","гробница железноборода","гавань менетилов","слизень","сумка в слизи","сида","сумка сиды","болотина"},ang={["faction:Alliance"]="Гавань Менетилов — главная жизненная артерия Альянса на пути через коварную Болотину, и помощь напуганным жителям помогает сохранять порядок и безопасность в этом важном порту.",["race:Dwarf"]="В Гробнице Железноборода покоятся останки почитаемого предка-дворфа, поэтому осквернение курганов мерзкими слизнями — оскорбление для любого приверженца Бронзобородов."},sec={{t="Паническое бегство",b="Сида, путешественница из Гавани Менетилов, регулярно отправляется на северо-восток Болотины, чтобы почтить память в Гробнице Железноборода. Во время последнего визита она увидела древний курган, кишащий мерзкими, сочащимися слизнями. Охваченная паникой при виде бесформенных тварей, она швырнула сумку в одну из них. Существо просто поглотило сумку целиком, но это дало Сиде время убежать в безопасный портовый город."},{t="Слизь Гробницы Железноборода",b="Место погребения прославленного героя-дворфа Железноборода находится неподалеку от спорной крепости Дун Модр. Несмотря на историческое почитание, окрестные болота подвержены порче, привлекая бесформенных кислотных слизней, которые поглощают все, что окажется у них на пути. Сида не помнит, какая именно тварь проглотила ее дорогие вещи, поэтому путникам предстоит обыскать окрестности гробницы и пробиться сквозь ползучую заразу, чтобы вернуть ее промокшую сумку."}},faq={{q="Кто такая Сида?",a="Сида — путешественница из Альянса, живущая в Гавани Менетилов. Она регулярно совершает паломничества в Болотину, к Гробнице Железноборода, и эта привычка недавно едва не стоила ей жизни, когда на нее напали враждебные слизни.",al={"sida","who gives quest","who is sida","сида","кто выдает задание","кто такая сида"}},{q="Где находится Гробница Железноборода?",a="Гробница Железноборода находится на северо-востоке Болотины, к югу от Дун Модра. Местность вокруг каменного кургана кишит едкими болотными слизнями.",al={"ironbeard tomb location","where is ironbeard","where are the oozes","где гробница железноборода","где железобород","где слизни"}},{q="Какой слизень проглотил сумку Сиды?",a="Сида запаниковала во время нападения и не может отличить тварей друг от друга. Любой из бродячих слизней у Гробницы Железноборода может хранить в себе ее переваренные вещи.",al={"which ooze","ooze with bag","where is the bag","какой слизень","слизень с сумкой","где сумка"}},{q="Зачем Сида приходила к Гробнице Железноборода?",a="Сида приходит к гробнице каждую неделю, чтобы почтить память древнего дворфа, погребенного там, но ее мирный обычай прервало неожиданное появление слизней.",al={"why sida visit tomb","sida weekly visit","зачем сида ходит к гробнице","сида каждую неделю"}},{q="Что будет после возвращения сумки?",a="Получив склизкую сумку в Гавани Менетилов, Сида вытряхивает содержимое на землю, чтобы забрать свои личные вещи. Сама испорченная сумка кажется ей слишком отвратительной, чтобы оставлять ее себе, и она отдает очищенную сумку искателю приключений, который ее вернул.",al={"what was in the bag","bag reward","что было в сумке","награда сумка"}},{q="Связано ли это с дворфами Черного Железа неподалеку?",a="Хотя Дун Модр к северу охвачен конфликтом с кланом Черного Железа, слизни, наводнившие Гробницу Железноборода, — дикие болотные хищники, обитающие в сырых, гниющих уголках Болотины, а не дворфийские солдаты.",al={"dark iron connection","dun modr connection","связь с черным железом","связь с дун модром"}}},fp="24,293,18.440.0,26.476.0,12.219.0,26.174.0,32.181.0,39.173.0,40.254.1,48.227.0"}
P.entries["quest:471"] = {n="Тяжкая судьба помощника",s="«Тяжкая судьба помощника» — договор Альянса, который предлагает кожевник Джеймс Халлоран из Гавани Менетилов. Он отправил юного помощника в болота, но того изувечили гигантские кроколиски, и теперь Халлоран нанимает умелого искателя приключений, чтобы закончить опасную добычу и свести счеты.",h="«Тяжкая судьба помощника» — договор Альянса, который предлагает кожевник Джеймс Халлоран из Гавани Менетилов.",kw={"apprentice's duties","crocolisk","giant crocolisk","james halloran","leatherworking","menethil harbor","murloc hovels","wetlands","young crocolisk skins","тяжкая судьба помощника","кроколиск","гигантский кроколиск","джеймс халлоран","кожевничество","гавань менетилов","лачуги мурлоков","болотина","шкуры молодых кроколисков"},ang={["class:Hunter"]="Болотные верховные хищники — грозные цели, и выслеживание взрослых гигантских кроколисков проверяет умение следопыта ориентироваться в мутных водах среди агрессивных зверей.",["faction:Alliance"]="Гавань Менетилов — связующее звено между Каз Моданом и остальным Альянсом, поэтому безопасность и самообеспеченность местных ремесленников жизненно важны для выживания порта."},sec={{t="Суровое ученичество",b="Ремесленникам в приграничных портах вроде Гавани Менетилов приходится полагаться на местное сырье, но окрестные топи беспощадны. Джеймс Халлоран отправил юного помощника в болота снимать шкуры с гигантских кроколисков Болотины. Когда юноша не вернулся, Халлоран разыскал его и нашел жестоко изувеченным хищными тварями."},{t="Шкуры и возмездие",b="Хотя местная повитуха считает, что помощник выживет, мальчик был искалечен и потерял ногу при нападении. Халлорану нужно пополнить запасы, и он хочет отомстить тварям, напавшим на того, кого считает почти сыном, поэтому нанимает странствующих искателей приключений отправиться на север вдоль побережья, миновать лачуги мурлоков и выследить гигантских кроколисков."}},faq={{q="Кто такой Джеймс Халлоран?",a="Джеймс Халлоран — кожевник и скорняк из Гавани Менетилов. Для своего ремесла он полагается на шкуры местных животных Болотины.",al={"james halloran","who gives apprentice duties","menethil tanner","джеймс халлоран","кто выдает задание тяжкая судьба помощника","кожевник менетил"}},{q="Что случилось с помощником Халлорана?",a="Халлоран отправил помощника в болото добыть шкуры гигантских кроколисков. Хищники напали на мальчика и тяжело изувечили его: он потерял ногу, хотя городская повитуха надеется, что он выживет.",al={"what happened to apprentice","who got mauled","apprentice leg","что случилось с помощником","кого изувечили","нога помощника"}},{q="Где обитают гигантские кроколиски?",a="Гигантские кроколиски бродят по болотам и северному побережью Болотины, сразу за прибрежными поселениями мурлоков к северу от Гавани Менетилов.",al={"where are giant crocs","crocolisk location wetlands","giant crocolisk spot","где гигантские кроколиски","кроколиски болотина","место гигантских кроколисков"}},{q="Какое задание предшествует этому?",a="Этому заданию предшествует «Шкуры молодых кроколисков»: сначала Халлоран просит искателей приключений охотиться на кроколисков помельче, а затем переходит к гигантским, ранившим его помощника.",al={"prereq for apprentice duties","previous quest","crocolisk quest chain","предыдущее задание для тяжкая судьба помощника","предыдущее задание","цепочка заданий про кроколисков"}},{q="Почему Халлоран по-прежнему хочет получить шкуры после трагедии?",a="У Халлорана все еще есть дело и заказы, которые нужно выполнять, но им движет и гнев. Он рад, если искатель приключений выследит и убьет тварей, изувечивших мальчика, которого он любит как сына.",al={"why need skins","halloran motivation","зачем нужны шкуры","мотив халлорана"}},{q="Предлагает ли Халлоран вам ученичество?",a="Увидев вашу работу, Халлоран шутливо говорит, что мог бы взять вас в новые помощники, но тут же отбрасывает эту мысль, замечая, что вы слишком стары и явно предназначены для иной судьбы.",al={"can i become apprentice","apprentice offer","могу ли я стать помощником","предложение ученичества"}}},fp="19,296,22.331.0,21.386.0,22.164.0,39.221.0,39.143.0,43.179.0,57.199.0,42.194.0"}
P.entries["quest:472"] = {n="Падение Дун Модра",s="Дун Модр, северная дворфийская крепость над Мостом Тандола, пала под жестоким натиском дворфов Черного Железа. Тяжелораненый уцелевший в Гавани Менетилов ищет искателя приключений из Альянса, который отправится на север и выяснит, остались ли в живых командир Длиннокос Мрачный и хоть кто-то из гарнизона.",h="Дун Модр, северная дворфийская крепость над Мостом Тандола, пала под жестоким натиском дворфов Черного Железа.",kw={"dark iron","dun modr","harlo barnaby","longbraid the grim","menethil harbor","thandol span","wetlands","черное железо","дун модр","харло барнаби","длиннокос мрачный","гавань менетилов","мост тандола","болотина"},ang={["faction:Alliance"]="Падение Дун Модра перерезает безопасное сообщение по суше между Стальгорном и северными операциями Альянса в Нагорье Арати, оставляя северный путь уязвимым для диверсий.",["race:Dwarf"]="Для дворфов бойня горцев Стальгорна и осквернение Дун Модра сородичами из южного клана — горькое личное оскорбление, требующее крови в ответ."},sec={{t="Сломленный северный бастион",b="Дун Модр издавна был опорой северного Каз Модана и охранял важную дорогу и мост, соединяющие Болотину с Нагорьем Арати через Мост Тандола. После засады у самого моста гарнизон поспешно отступил за стены крепости, чтобы перегруппироваться. Не успели восстановить линии обороны, как силы Черного Железа ударили превосходящим числом, перебили защитников и вынудили их к отчаянной эвакуации."},{t="Отчаянное бегство",b="Харло Барнаби, молодой солдат среди защитников, был тяжело ранен: во время беспорядочного отступления шальной топор попал ему в спину. Сочтя раны смертельными, Длиннокос Мрачный и оставшиеся бойцы привязали Барнаби к последней уцелевшей лошади и отправили его на юг, в Гавань Менетилов. Барнаби выжил, но очнулся в портовой таверне, терзаемый чувством вины выжившего, и не зная, удалось ли кому-то из товарищей спастись из бойни."},{t="Мрачные остатки",b="Глубоко в северных болотах возле захваченной крепости Длиннокос Мрачный все еще жив и удерживает вместе жалкую горстку выживших. Ветеран-командир рад узнать, что юный Харло пережил тяжелую рану, но сталкивается с суровой тактической реальностью: Дун Модр прочно удерживают дворфы Черного Железа, а в его залах засели головорезы и диверсанты, угрожающие всему пути между Каз Моданом и человеческими землями на севере."}},faq={{q="Что случилось с Дун Модром?",a="Дун Модр был захвачен враждебными дворфами Черного Железа. Гарнизон уже пострадал от засады у соседнего Моста Тандола, и прежде чем он успел укрепить оборону внутри города, дворфы Черного Железа напали и уничтожили большую часть защищавшего его полка.",al={"why is dun modr destroyed","who attacked dun modr","dun modr lore","почему разрушен дун модр","кто напал на дун модр","предания дун модра"}},{q="Кто такой Харло Барнаби?",a="Харло Барнаби — солдат из Стальгорна, служивший в Дун Модре и едва переживший его падение. Раненный в спину брошенным топором во время отступления, он был привязан командиром к единственной уцелевшей лошади гарнизона и отправлен на юг, в Гавань Менетилов, за медицинской помощью.",al={"who is harlo","harlo barnaby lore","wounded soldier in menethil","кто такой харло","харло барнаби предания","раненый солдат в менетиле"}},{q="Где находится Длиннокос Мрачный?",a="Командир Длиннокос Мрачный укрылся в глуши недалеко от занятого врагом города Дун Модр, у северной дороги, ведущей к Мосту Тандола.",al={"where is longbraid","longbraid location","find longbraid","где длиннокос","местонахождение длиннокоса","найти длиннокоса"}},{q="Почему Дун Модр важен стратегически?",a="Дун Модр — самое северное поселение и укрепление в Болотине. Он охраняет южный подход к Мосту Тандола, единственному наземному мосту, который связывает Каз Модан с Нагорьем Арати и Лордероном.",al={"why care about dun modr","thandol span connection","зачем нужен дун модр","мост тандола связь"}},{q="Кто атакует Дун Модр?",a="Нападающие — дворфы Черного Железа, члены вероломного клана с юга, которые продвинулись на север в Болотину, чтобы разрушать такие объекты, как Мост Тандола, и досаждать землям Стальгорна.",al={"who took dun modr","dark irons in wetlands","кто захватил дун модр","дворфы черного железа в болотине"}},{q="Что будет после встречи с Длиннокосом?",a="Когда вы убедитесь, что Длиннокос жив, и сообщите ему, что Барнаби выжил, Длиннокос призовет вас к мрачной миссии мести и возмездия против сил Черного Железа, занявших руины Дун Модра.",al={"fall of dun modr follow up","what comes after fall of dun modr","продолжение падения дун модра","что после падения дун модра"}}},fp="16,308,25.422.0,18.468.0,16.439.1,26.272.0,21.275.0,36.164.1,40.225.0,34.205.0,37.206.1"}
P.entries["quest:4722"] = {n="Останки морской черепахи",s="На туманных, изрезанных прибоем берегах Темных берегов лежит туша огромной морской черепахи, выброшенной на сушу, вокруг которой роятся мурлоки-падальщики. Хотя туша обглодана, из останков все еще можно добыть пригодные биологические образцы. Натуралисты в Аубердине собирают такие образцы, чтобы отправить их в Храм Луны в Дарнассе для научного изучения.",h="На туманных, изрезанных прибоем берегах Темных берегов лежит туша огромной морской черепахи, выброшенной на...",kw={"auberdine","beached","darkshore","darnassus","gwennyth bly'leggonde","murloc","remains","sea turtle","аубердин","выброшенный на берег","темные берега","дарнасс","гвеннид блай'леггонд","мурлок","останки","морская черепаха"},ang={["class:Druid"]="Друиды видят в выброшенной морской жизни и мурлоках-падальщиках признаки экологического дисбаланса на Темных берегах, требующего пристального наблюдения и исцеления.",["race:NightElf"]="Необъяснимое выбрасывание древних морских существ на берег указывает на более глубокое нарушение в водах Калимдора и побуждает исследователей Аубердина и Дарнасса изучать каждого выброшенного левиафана."},sec={{t="Выброшенный на берег левиафан",b="На длинном побережье Темных берегов часто оказываются жертвы Великого моря, в том числе огромные древние морские черепахи, которые прибиваются к берегу после смерти или выбрасываются на сушу в смятении. Туши быстро привлекают падальщиков. Враждебные мурлоки Серой Мглы устроили вокруг скелета этой черепахи грубые лагеря и срезают плоть и панцирь. Несмотря на их промысел, среди останков нередко остаются целыми пригодные образцы костей, панциря или тканей."},{t="Полевые исследования для Дарнасса",b="Гвеннид Блай'Леггонд, находящаяся в поселении Аубердин, работает полевым исследователем и документирует необычную морскую жизнь и экологические нарушения вдоль побережья. Ночные эльфы наблюдают за этими выброшенными зверями с почтением и научным любопытством. Подходящие останки тщательно каталогизируют и готовят к отправке ученым Дарнасса, желающим понять, почему так много морских гигантов оказывается на берегу."}},faq={{q="Почему на Темных берегах так много выброшенных морских существ?",a="Бурные воды и сильные прибрежные течения Темных берегов естественным образом выносят на песок плавучие обломки и умирающих морских зверей. Ученые ночных эльфов подозревают, что неестественные возмущения в глубинах океана гонят морскую жизнь на мелководье, и местные натуралисты изучают каждое выброшенное тело.",al={"why dead sea turtle","darkshore beached creatures","why stranded","почему мертвая морская черепаха","выброшенные существа темные берега","почему выбросило на берег"}},{q="Кому нужны останки морской черепахи?",a="Гвеннид Блай'Леггонд, исследовательница из ночных эльфов в Аубердине, собирает у искателей приключений выброшенные на берег образцы для натуралистов и ученых из Дарнасса.",al={"who do i turn this in to","gwennyth auberdine","where to turn in turtle remains","кому сдавать это","гвеннид аубердин","куда сдать останки черепахи"}},{q="Почему мурлоки собрались вокруг черепахи?",a="Местные мурлоки Серой Мглы — оппортунисты, подбирающие все, что выносит на берег. Выброшенная гигантская морская черепаха дает им много мяса, прочной шкуры и костей для орудий и жилищ.",al={"murlocs near turtle","greymist scavengers","murloc camp","мурлоки у черепахи","падальщики серой мглы","лагерь мурлоков"}},{q="Что происходит с образцами после того, как их получит Гвеннид?",a="Гвеннид упаковывает пригодные образцы тканей и костей для отправки через море в Дарнасс, где ученые и жрицы изучают их, чтобы следить за здоровьем и поведением прибрежной экосистемы.",al={"what does darnassus do with remains","turtle sample research","что дарнасс делает с останками","исследование образцов черепахи"}},{q="Это единственное выброшенное существо на побережье?",a="Нет. На длинном побережье Темных берегов лежат несколько морских черепах и другие выброшенные морские исполины, и многие из них дают образцы для ученых Аубердина.",al={"other beached animals","more dead turtles","washed ashore creatures","другие выброшенные животные","еще мертвые черепахи","существа на берегу"}},{q="Священны ли морские черепахи для ночных эльфов?",a="Ночные эльфы чтят коренных зверей Калимдора как часть природного равновесия под покровительством Элуны и диких богов. Хотя морские черепахи не являются отдельными божественными воплощениями, их неожиданная гибель и выбрасывание на берег считаются серьезными экологическими предупреждениями.",al={"night elf turtles","druids and turtles","ночные эльфы черепахи","друиды и черепахи"}}},fp="18,339,20.466.0,28.445.0,57.302.0,33.169.0,43.209.0,56.204.0,50.168.0,42.250.0"}
P.entries["quest:4723"] = {n="Останки морской твари",s="На окутанном туманом берегу Туманного Предела лежит огромная туша морского молотильщика, куда крупнее любых обитателей мелководья Темных берегов. Пока местные мурлоки роются в падали, натуралисты в Аубердине ищут образцы костей, чтобы понять, почему такие колоссальные глубоководные звери выбрасываются на берег.",h="На окутанном туманом берегу Туманного Предела лежит огромная туша морского молотильщика, куда крупнее любых...",kw={"auberdine","beached","bones","darkshore","gwennyth bly'leggonde","mist's edge","murloc","sea creature","thresher","аубердин","выброшенный на берег","кости","темные берега","гвеннид блай'леггонд","туманный предел","мурлок","морское существо","молотильщик"},ang={["class:Druid"]="Друиды, стремящиеся сохранить природную гармонию, видят в выброшенном на берег левиафане тревожный признак нарушения в экосистеме Сокрытого Моря.",["race:NightElf"]="Выбрасывание существ на берег у Темных берегов — тревожный признак дисбаланса в окружающих водах, побуждающий натуралистов Аубердина и Дарнасса провести исследование, пока не погибло еще больше морских обитателей."},sec={{t="Гигант на мелководье",b="Побережье Туманного Предела привыкло к кораблекрушениям и выброшенным приливом обломкам, но внезапное появление огромных останков молотильщика тревожит. Существо намного крупнее местных животных, а значит, пришло из глубин, далеких от спокойных вод Сокрытого Моря. Хотя прибрежные мурлоки жадно роятся вокруг туши и пируют, у них не хватит ни сил, ни слаженности, чтобы одолеть левиафана такого размера. Хищник погиб от чего-то совсем другого, прежде чем его вынесло на берег."},{t="Исследования в Дарнассе",b="Гвеннид Блай'Леггонд в Аубердине руководит полевыми работами по сбору костей и биологических образцов у выброшенной на берег крупной фауны Темных берегов. Исследователи ночных эльфов в Дарнассе надеются, изучив скелеты и образцы тканей, определить, что гонит этих океанских гигантов на гибельные пески: болезнь, возмущения в глубинах или волшебная порча."}},faq={{q="Какой зверь был выброшен на берег?",a="Это останки гигантского молотильщика, водного хищника, намного крупнее молотильщиков, которых обычно замечают у берегов Темных берегов.",al={"what creature is this","what is the dead monster","what animal is dead on the beach","что это за существо","что за мертвый монстр","какое животное мертво на берегу"}},{q="Убили ли его мурлоки?",a="Нет. Хотя мурлоки роятся вокруг туши и питаются гниющим мясом, наблюдатели отмечают, что они слишком слабы, даже большими группами, чтобы охотиться на глубоководного исполина такого размера.",al={"did murlocs kill the thresher","did murlocs kill the sea creature","убили ли мурлоки молотильщика","убили ли мурлоки морское существо"}},{q="Почему морские существа выбрасываются на берег у Темных берегов?",a="Точная причина неизвестна. Исследователи ночных эльфов подозревают незримые возмущения в океане, болезнь или экологическое неблагополучие, из-за которых глубоководная фауна заплывает на мелководье, где выбрасывается на берег и гибнет.",al={"why are threshers dying","why do creatures beach themselves","почему умирают молотильщики","почему существа выбрасываются на берег"}},{q="Кто такая Гвеннид Блай'Леггонд?",a="Гвеннид Блай'Леггонд — исследовательница из ночных эльфов, живущая в Аубердине. Она собирает образцы костей и биологические образцы у выброшенных на берег животных Темных берегов и отправляет их в Дарнасс для детального изучения.",al={"who is gwennyth","who takes the bones in auberdine","кто такая гвеннид","кто принимает кости в аубердине"}},{q="Куда отправляют собранные кости?",a="После того как Гвеннид каталогизирует и подготовит образцы в Аубердине, их отправляют ученым и натуралистам в столицу, Дарнасс, для анатомического и магического исследования.",al={"where do bones go","what does auberdine do with bones","куда уходят кости","что аубердин делает с костями"}},{q="Где находится эта туша?",a="Туша лежит прямо на песчаном берегу Туманного Предела, на западном побережье Темных берегов.",al={"carcass location","where is the beached sea creature","где туша","где выброшенное морское существо"}}},fp="20,316,23.473.0,20.362.0,42.139.0,24.183.0,59.202.0,29.205.0,35.182.0,30.99.0"}
P.entries["quest:4725"] = {n="Останки морской черепахи",s="На прибрежной полосе Темных берегов лежит туша огромной морской черепахи с обломками повозки на спине, кишащая мурлоками Серой Мглы, которые пользуются случаем. В отличие от других мертвых морских исполинов на побережье, это существо еще при жизни использовали как вьючное животное змееподобные наги, и умерло оно на песке.",h="На прибрежной полосе Темных берегов лежит туша огромной морской черепахи с обломками повозки на спине...",kw={"auberdine","beached","carriage","darkshore","greymist","gwennyth bly'leggonde","naga","sea turtle","strangely marked box","аубердин","выброшенный на берег","повозка","темные берега","серая мгла","гвеннид блай'леггонд","наги","морская черепаха","ящик с необычными знаками"},ang={["faction:Alliance"]="Расследование выбросов дает важные сведения стражам Аубердина: они следят и за нашествием мурлоков, и за ростом организованных набегов нагов.",["race:NightElf"]="Появление на Темных берегах вьючных зверей нагов подтверждает: исконные враги кальдораев активно укрепляют плацдармы неприятно близко к Дарнассу."},sec={{t="Зверь в упряжи",b="Окутанные туманом берега Темных берегов страдают от тревожного числа выброшенных морских гигантов, но история этой черепахи гораздо зловещее. На ее огромном панцире закреплена обветшавшая повозка, брошенная и гниющая в приливе. В отличие от других выброшенных существ, этот гигант умер не от болезни или естественного истощения: разумные погонщики заставили его служить и выгнали на берег."},{t="Падальщики на мелководье",b="Туша недолго оставалась нетронутой. Местные мурлоки Серой Мглы быстро облепили останки и устроили логово среди гниющего мяса и растащенных досок. Среди мусора мурлоков и разбитого остова морской повозки лежит целый контейнер с необычными знаками, оставленный прежними хозяевами животного."},{t="Снабжение нагов",b="Когда необычный контейнер доставляют Гвеннид Блай'Леггонд в Аубердин, картина проясняется. На контейнере знаки нагов, а упряжь совпадает с той, что у повозок, на которых змеиный народ перевозит оружие и военные припасы из морских глубин. Мертвая черепаха — прямое доказательство того, что наги готовят вторжения на север Темных берегов, а найденный предмет спешно отправляют в Дарнасс для дальнейшего изучения."}},faq={{q="Почему на панцире морской черепахи повозка?",a="Повозка принадлежала нагам, которые используют гигантских морских черепах как вьючных и осадных животных. С помощью таких повозок они перевозят припасы и оружие из глубин на побережье Темных берегов.",al={"turtle carriage","why carriage on turtle","harnessed turtle","повозка на черепахе","почему повозка на черепахе","черепаха в упряжи"}},{q="Что внутри повозки?",a="Среди обломков брошенной повозки лежит ящик с необычными знаками. Руны говорят о том, что он принадлежит нагам, поэтому ученые в Аубердине решили отправить его в Дарнасс для официального изучения.",al={"turtle box","strangely marked box","box in turtle carriage","ящик черепахи","ящик с необычными знаками","ящик в повозке черепахи"}},{q="Почему вокруг черепахи собрались мурлоки?",a="Мурлоки Серой Мглы обитают на побережье и регулярно обшаривают кораблекрушения и выброшенные туши. Они сделали останки гигантской черепахи источником пищи и гнездом.",al={"murlocs around turtle","greymist murlocs turtle","why murlocs eating turtle","мурлоки вокруг черепахи","мурлоки серой мглы черепаха","почему мурлоки едят черепаху"}},{q="Кто изучает выброшенных на берег существ на Темных берегах?",a="Гвеннид Блай'Леггонд в Аубердине руководит расследованием волны выбросов морских существ и каталогизирует реликвии и странные материалы, найденные на их останках.",al={"who studies beached sea creatures","auberdine researcher","gwennyth bly'leggonde role","кто изучает выброшенных морских существ","исследователь аубердина","гвеннид блай'леггонд"}},{q="Чем эта черепаха отличается от других выброшенных существ на Темных берегах?",a="Многие существа выбрасываются на берег из-за болезни, порчи или морской беды, но эта черепаха была явно приручена, несла тяжелое грузовое снаряжение, и наги намеренно выгнали ее на берег.",al={"other beached turtles","why this turtle different","turtle mystery darkshore","другие черепахи на берегу","чем эта черепаха отличается","тайна черепахи темные берега"}},{q="Что происходит с ящиком после Аубердина?",a="Гвеннид Блай'Леггонд регистрирует находку в Аубердине и отправляет ящик нагов в Дарнасс, где эльфийское руководство анализирует растущую угрозу на северных границах.",al={"where does box go","box sent to darnassus","what does auberdine do with box","куда отправляют ящик","ящик отправлен в дарнасс","что аубердин делает с ящиком"}}},fp="18,292,18.443.0,26.318.0,17.446.1,50.206.0,28.200.0,43.167.0,47.167.0,73.206.0,47.174.0"}
P.entries["quest:4727"] = {n="Останки морской черепахи",s="На северном берегу Темных берегов лежит огромный скелет выброшенной морской черепахи, почему-то не тронутый местными мурлоками Серой Мглы. Образец ее останков собирают и доставляют Гвеннид Блай'Леггонд в Аубердин от имени Храма Луны. Натуралисты и жрицы хотят выяснить, почему эти морские великаны выбрасываются на берег и почему даже падальщики не решаются подойти.",h="На северном берегу Темных берегов лежит огромный скелет выброшенной морской черепахи, почему-то не тронутый...",kw={"auberdine","beached","carcass","darkshore","greymist","gwennyth bly'leggonde","murloc","remains","sea turtle","temple of the moon","аубердин","выброшенный на берег","туша","темные берега","серая мгла","гвеннид блай'леггонд","мурлок","останки","морская черепаха","храм луны"},ang={["class:Druid"]="Друиды внимательно следят за побережьем и глубоко встревожены тем, что падальщики вроде мурлоков не трогают мертвых: это может указывать на неестественную скверну в воде.",["class:Priest"]="Служить Храму Луны значит распространять заботу Элуны на все живое и расследовать смерти, нарушающие гармонию природы.",["race:NightElf"]="Необъяснимая гибель величественных морских существ у Темных берегов и то, что их избегают, указывают на растущее неравновесие, угрожающее исконным землям кальдораев."},sec={{t="Странное отсутствие",b="Северное побережье Темных берегов кишит мурлоками Серой Мглы, которые жадно подбирают все съедобное, что приносит Сокрытое Море. Но скелет огромной черепахи остался почти нетронутым. Просто ли мурлоки не заметили добычу или намеренно избегают останков по неведомой причине — это тревожная загадка для тех, кто изучает экологию берега."},{t="Изучение побережья",b="В Аубердине Гвеннид Блай'Леггонд собирает образцы выброшенных исполинов для Храма Луны. Жрицы ночных эльфов стараются понять, что тревожит воды Темных берегов, и по фрагментам скелетов определяют, что губит древних обитателей моря: болезнь, магическая порча или гнусные морские хищники."}},faq={{q="Что это за останки морской черепахи?",a="Это огромный скелет древней морской черепахи, выброшенной на берег на севере Темных берегов. Необычность находки и отсутствие падальщиков делают ее предметом изучения ночных эльфов.",al={"turtle carcass","sea turtle skeleton","what is this turtle","туша черепахи","скелет морской черепахи","что это за черепаха"}},{q="Почему мурлоки избегают туши?",a="Мурлоки Серой Мглы обычно разрывают любую тушу на берегу, но эти останки не тронули. Гвеннид Блай'Леггонд и Храм Луны подозревают, что падальщиков отпугивает неестественная скверна или невидимая опасность, связанная с гибелью существа.",al={"why aren't murlocs eating it","greymist murlocs turtle","why avoid carcass","почему мурлоки не едят","мурлоки серой мглы черепаха","почему избегают туши"}},{q="Кто такая Гвеннид Блай'Леггонд?",a="Гвеннид Блай'Леггонд — исследовательница из числа ночных эльфов, живущая в Аубердине. От имени Храма Луны она собирает образцы морской фауны, выброшенной на берега Темных берегов.",al={"gwennyth auberdine","who wants turtle remains","turtle quest turn in","гвеннид аубердин","кому нужны останки черепахи","сдача задания про черепаху"}},{q="Почему Храм Луны интересуется выброшенными морскими существами?",a="Жрицы Элуны хранят равновесие и заботятся о природе на севере Калимдора. Поскольку морские существа гибнут у Темных берегов в необычных количествах, Храм изучает биологические образцы, чтобы определить недуг, вредящий морям.",al={"temple of the moon turtle","why study turtles","elune marine life","храм луны черепаха","зачем изучать черепах","элуна морская жизнь"}},{q="Где находится эта морская черепаха?",a="Эта туша лежит на песчаном северном побережье Темных берегов, рядом с землями, где обитают племена мурлоков Серой Мглы.",al={"where is the turtle","beached sea turtle location","turtle darkshore","где черепаха","местонахождение морской черепахи","черепаха темные берега"}},{q="Есть ли на Темных берегах другие выброшенные существа?",a="Да. На берегах Темных берегов лежит множество выброшенных морских существ и гигантских черепах, и каждое побуждает исследователей Аубердина выяснять, почему гибнут морские исполины.",al={"other beached creatures","more sea turtles","beached sea creature quests","другие выброшенные существа","еще морские черепахи","задания про выброшенных морских существ"}}},fp="18,422,17.401.0,22.356.0,31.200.0,41.278.0,29.170.0,65.262.0,44.140.0,50.191.0"}
P.entries["quest:4728"] = {n="Останки морской твари",s="На туманном побережье Темных берегов лежит огромная туша морского млекопитающего, брошенная посреди раскопок. Разбросанные инструменты и пустая тачка говорят о прерванной экспедиции: образец достался мурлокам-падальщикам и любопытным взглядам путников.",h="На туманном побережье Темных берегов лежит огромная туша морского млекопитающего, брошенная посреди раскопок.",kw={"auberdine","beached","bones","darkshore","explorers league","gwennyth","murloc","sea creature","аубердин","выброшенный на берег","кости","темные берега","лига исследователей","гвеннид","мурлок","морское существо"},ang={["faction:Alliance"]="Эта находка показывает совместные усилия Дарнасса и Лиги исследователей из Стальгорна по изучению тайн Калимдора.",["race:Dwarf"]="Брошенные вокруг туши инструменты принадлежат вашим сородичам из Лиги исследователей, которых местные мурлоки прогнали с места раскопок.",["race:NightElf"]="Храм Луны глубоко встревожен неестественной частотой, с которой огромные морские существа гибнут и выбрасываются на священные берега Темных берегов."},sec={{t="Прерванные раскопки",b="Туша на песках Темных берегов принадлежит огромному морскому млекопитающему, частично выпотрошенному и сильно разъеденному морскими брызгами. Вокруг разлагающегося остова разбросаны ржавая тачка и брошенные инструменты — очевидно, кто-то пытался организованно изучить зверя, но был прогнан или в спешке покинул место."},{t="Лига и мурлоки",b="Брошенное снаряжение принадлежало дворфам-исследователям из Лиги исследователей, работавшим на Темных берегах. Их изучение туши резко оборвалось, когда на место налетели местные мурлоки и объявили выброшенного великана своей добычей. Гвеннид Блай'Леггонд в Аубердине от имени Храма Луны охотно принимает любые собранные образцы костей для дальнейшего изучения неестественных выбросов на побережье."}},faq={{q="Что это за существо лежит на берегу?",a="Это останки гигантского морского млекопитающего, выброшенного на берег Темных берегов. Вид точно не установлен, но зверь достаточно велик, чтобы привлечь и мурлоков-падальщиков, и дворфов-исследователей.",al={"beached sea creature identity","what is this carcass","what died here","кто выброшен на берег","что это за туша","кто здесь умер"}},{q="Кто оставил инструменты и тачку?",a="Инструменты оставили дворфы из Лиги исследователей. Они устроили раскопки, чтобы изучить выброшенного зверя, но на них напали враждебные прибрежные мурлоки и прогнали, прежде чем они закончили.",al={"who left the tools","abandoned wheelbarrow darkshore","who was digging here","кто оставил инструменты","брошенная тачка темные берега","кто здесь копал"}},{q="Зачем Гвеннид Блай'Леггонд эти кости?",a="Гвеннид Блай'Леггонд собирает образцы от имени Храма Луны в Дарнассе. Ночные эльфы активно изучают странное и тревожное явление: огромные морские существа гибнут и выбрасываются на берега Темных берегов.",al={"why does gwennyth want bones","temple of the moon sea creature","auberdine sea bones","зачем гвеннид кости","храм луны морские существа","кости аубердин"}},{q="Почему вокруг туши бродят мурлоки?",a="Мурлоков привлек огромный запас мяса и жира, и они прогнали дворфов-ученых, чтобы кормиться останками и защищать их.",al={"murlocs around carcass","why are murlocs here","murloc scavengers","мурлоки вокруг туши","почему здесь мурлоки","мурлоки-падальщики"}},{q="Лига исследователей — официальный союзник Аубердина?",a="Да. Как и другие члены Альянса, Лига исследователей присутствует на Темных берегах и сотрудничает с местными властями ночных эльфов, часто делясь отчетами о научных открытиях и исследованиях побережья.",al={"explorers league auberdine","dwarves in darkshore","explorers league alliance darkshore","лига исследователей аубердин","дворфы на темных берегах","лига исследователей альянс темные берега"}},{q="Есть ли другие выброшенные существа на побережье Темных берегов?",a="Да. Множество огромных морских зверей и скелетов выбросило на туманные пляжи Темных берегов по всей их длине, что говорит о сильном беспокойстве в водах у Калимдора.",al={"more beached creatures","other carcasses darkshore","multiple beached sea creatures","еще выброшенные существа","другие туши темные берега","много выброшенных морских существ"}}},fp="20,263,19.355.0,26.441.0,41.207.0,42.209.0,48.236.0,44.162.0,63.233.0,60.181.0"}
P.entries["quest:473"] = {n="Доклад капитану Крепкому Кулаку",s="Доклад капитану Крепкому Кулаку — военный приказ Альянса в Гавани Менетилов. После первых стычек с кланом Драконьей Пасти у Дун Альгаза Валстаг Сталезуб направляет проверенных бойцов в крепость гавани для координации более глубокой обороны. Капитан Крепкий Кулак командует местным гарнизоном и организует прямые удары по укрепившимся оркам по всей Болотине.",h="Доклад капитану Крепкому Кулаку — военный приказ Альянса в Гавани Менетилов.",kw={"captain stoutfist","dragonmaw","dun algaz","menethil harbor","menethil keep","valstag ironjaw","war room","wetlands","капитан крепкий кулак","драконья пасть","дун альгаз","гавань менетилов","крепость менетил","валстаг сталезуб","зал войны","болотина"},ang={["class:Warrior"]="Валстаг Сталезуб ценит боевое мастерство и направляет опытных бойцов передовой прямо под тактическое командование капитана Крепкого Кулака.",["faction:Alliance"]="Гавань Менетилов служит главными воротами для товаров и подкреплений между южными королевствами и Каз Моданом; потеря дороги из-за набегов орков нанесла бы тяжелый удар по торговле Альянса.",["race:Dwarf"]="Защита торгового пути между Гаванью Менетилов и вратами Стальгорна жизненно важна для безопасности Каз Модана, поэтому это поручение — настоящее дело дворфов."},sec={{t="Растущая угроза",b="Хотя дворфы-горные пехотинцы давно следят за узкими горными перевалами Дун Альгаза, возрождение клана Драконьей Пасти нельзя удержать в пределах одного лишь Лок Модана. Валстаг Сталезуб понимает, что эти орки движутся вовне, устраивают лагеря и угрожают всей болотистой местности. Защита перевала — лишь первый шаг более масштабной кампании по охране дороги в Стальгорн."},{t="Зал войны Менетилов",b="Глубоко в Крепости Менетил находится зал войны, где капитан Крепкий Кулак руководит обороной порта Альянса. Перед лицом нападений диверсантов из клана Черного Железа, местных зверей и болотных мурлоков капитан полагается на способных добровольцев в борьбе с внешними военными угрозами. Рекомендация Валстага подтверждает, что вы достаточно закалены, чтобы выполнять прямые приказы против военной машины Драконьей Пасти."}},faq={{q="Кто направляет меня к капитану Крепкому Кулаку?",a="Валстаг Сталезуб, находящийся в Крепости Менетил в Гавани Менетилов, направляет вас с докладом к капитану Крепкому Кулаку после того, как вы проявите себя в бою с местными орками клана Драконьей Пасти.",al={"who gives this quest","quest giver","valstag ironjaw","кто выдает это задание","персонаж, выдающий задания","валстаг сталезуб"}},{q="Где находится капитан Крепкий Кулак?",a="Капитан Крепкий Кулак находится в Крепости Менетил, в самом сердце Гавани Менетилов на западе Болотины. Его можно найти склонившимся над тактическими картами в зале войны крепости.",al={"captain stoutfist location","where is stoutfist","menethil war room","капитан крепкий кулак","где крепкий кулак","зал войны менетил"}},{q="Почему орки Драконьей Пасти — приоритет для Крепости Менетил?",a="Клан Драконьей Пасти владеет древними твердынями по всей Болотине и представляет агрессивную угрозу торговым дорогам, соединяющим Гавань Менетилов со Стальгорном. Поскольку их силы продвигаются за Дун Альгаз, гарнизон не может игнорировать их растущие лагеря.",al={"why fight dragonmaw","dragonmaw threat","orcs in wetlands","зачем сражаться с драконьей пастью","угроза драконьей пасти","орки в болотине"}},{q="Что происходит после доклада капитану Крепкому Кулаку?",a="Когда вы докладываете капитану Крепкому Кулаку, он прямо включает вас в наступление на клан Драконьей Пасти и отправляет громить их лагеря и уничтожать их боевые знамена в болотах.",al={"what next","followup quest","after report to stoutfist","что дальше","следующее задание","после доклада крепкому кулаку"}},{q="Кто такие орки Драконьей Пасти в Болотине?",a="Драконья Пасть — остатки старой Орды, которые прославились тем, что поработили красных драконов у Грим Батола во время Второй войны. Хотя Грим Батол был сломлен, уцелевшие отряды закрепились по всей болотистой местности, грабя путников и бросая вызов власти Альянса.",al={"dragonmaw lore","who are dragonmaw","wetlands orcs","предания драконьей пасти","кто такие драконья пасть","орки болотины"}},{q="Почему сил в Гавани Менетилов так не хватает?",a="Гавань Менетилов постоянно сталкивается с болотными животными, наступающими мурлоками и враждебными дворфами Черного Железа, пытающимися подорвать порт. Поскольку силы гарнизона заняты обороной стен и причалов, капитан Крепкий Кулак полагается на сторонних героев, чтобы наносить удары по далеким аванпостам орков.",al={"menethil defense","why are troops busy","harbor problems","оборона менетилов","почему войска заняты","проблемы гавани"}}},fp="27,382,17.420.0,24.388.0,34.173.0,35.179.0,56.260.0,50.200.0,43.254.0,41.278.0"}
P.entries["quest:4730"] = {n="Останки морской твари",s="На продуваемом ветрами побережье Темных берегов на сушу выбросило наполовину съеденные останки огромного морского млекопитающего, которые охраняют мурлоки-оппортунисты. Жрица Гвеннид Блай'Леггонд в Аубердине ищет образцы костей этих выброшенных гигантов, чтобы понять, почему обычно мирные морские звери гибнут на песке.",h="На продуваемом ветрами побережье Темных берегов на сушу выбросило наполовину съеденные останки огромного...",kw={"auberdine","beached sea creature","darkshore","gwennyth bly'leggonde","murloc","sea creature bones","teldrassil","temple of the moon","аубердин","останки морской твари","темные берега","гвеннид блай'леггонд","мурлок","кости морского существа","тельдрассил","храм луны"},ang={["class:Druid"]="Любое нарушение поведения морских обитателей — мрачное предзнаменование для Круга Кенария, указывающее на неестественную порчу, отравляющую прибрежных животных.",["class:Priest"]="Храм Луны финансирует и направляет это расследование, ища божественное прозрение о скверне, тревожащей воды Калимдора.",["faction:Alliance"]="Защита берегов вокруг Аубердина охраняет важные морские пути Альянса между Темными берегами, Тельдрассилом и восточными королевствами.",["race:NightElf"]="Выбросы на берег на Темных берегах болезненно задевают кальдораев, которые чтят природную гармонию и с ужасом наблюдают, как неспокойными становятся воды вокруг их нового дома — Тельдрассила."},sec={{t="Жуткая находка на берегу",b="К северу вдоль пустынных пляжей Темных берегов лежит гниющая, наполовину обглоданная туша гигантского морского млекопитающего. Волны бьются о ее оголенные ребра, а необычно свирепое племя мурлоков дочиста обгладывает кости. Зрелище одновременно печальное и тревожное: равновесие океана нарушается так же сильно, как и в оскверненных лесах на суше."},{t="Необычное выбрасывание на берег",b="По словам жрицы Гвеннид Блай'Леггонд, существа, которых выносит на берег, — обычно кроткие морские млекопитающие, обитающие в водах вокруг основания Тельдрассила. В отличие от агрессивных молотильщиков, эти мирные звери никогда не бросались на скалы по собственной воле. Храм Луны ведет учет образцов костей, чтобы выяснить, какая скверна или скрытая угроза гонит их из глубин умирать на побережье."}},faq={{q="Какое существо здесь выбросило на берег?",a="Скелет принадлежит крупному мирному морскому млекопитающему, которое обычно обитает в глубоких спокойных водах вокруг основания Тельдрассила. Это миролюбивые гиганты, не склонные к агрессии и не выбрасывающиеся на берег.",al={"what animal is this","what is the beached creature","sea monster bones","что это за животное","что за существо на берегу","кости морского чудища"}},{q="Почему морское существо выбросилось на берег?",a="Точная причина неизвестна, но жрица Гвеннид Блай'Леггонд отмечает, что для этого вида такое совершенно неестественно. Исследователи-ночные эльфы подозревают, что скрытое возмущение или скверна в окрестных морях сбивает существ с пути или вынуждает покидать родные места обитания.",al={"why did it beach","why are sea creatures dying","darkshore strandings","почему выбросилось на берег","почему гибнут морские существа","выбросы на темных берегах"}},{q="Кто такая Гвеннид Блай'Леггонд?",a="Гвеннид Блай'Леггонд — жрица, представляющая Храм Луны в Аубердине. Она координирует экологическое расследование на побережье Темных берегов, собирая останки скелетов, чтобы изучить недуг, поражающий местную морскую фауну.",al={"who turns in this quest","who is gwennyth","auberdine priestess","кому сдать это задание","кто такая гвеннид","жрица аубердина"}},{q="Почему мурлоки собрались вокруг туши?",a="Мурлоки — оппортунисты, которых привлек выброшенный гигант как легкий и обильный источник пищи. Стая у этой туши заметно сильнее и агрессивнее мурлоков, живущих ближе к Аубердину.",al={"why murlocs here","murlocs near bones","beach murlocs","почему здесь мурлоки","мурлоки у костей","мурлоки на берегу"}},{q="Где это существо обычно обитает?",a="Эти морские млекопитающие живут в открытых водах вокруг гигантских ветвей и корней Тельдрассила и в обычных условиях редко приближаются к берегам материка.",al={"where do these live","sea mammal habitat","teldrassil sea creatures","где они обитают","среда обитания морских млекопитающих","морские существа тельдрассила"}},{q="Как это связано с другими случаями выбрасывания на берег на Темных берегах?",a="На Темных берегах на сушу выбросило несколько морских видов, включая хищных молотильщиков и гигантских морских черепах. Хотя молотильщики по природе буйные, выброс мирных млекопитающих подтверждает, что морская аномалия затрагивает виды по всей прибрежной экосистеме.",al={"other beached sea creatures","beached thresher","beached sea turtle","другие морские существа на берегу","выброшенный молотильщик","останки морской черепахи"}}},fp="20,314,30.357.0,26.459.0,37.225.0,38.304.0,29.258.0,43.221.0,39.175.0,53.275.0"}
P.entries["quest:4731"] = {n="Останки морской черепахи",s="На побережье Темных берегов лежат останки морской черепахи со сломанной повозкой и ящиком, покрытым странными рунами. В отличие от другой морской жизни, оказавшейся на берегу естественным образом, это существо, судя по всему, было убито, когда служило вьючным животным.",h="На побережье Темных берегов лежат останки морской черепахи со сломанной повозкой и ящиком, покрытым странными...",kw={"ashenvale","auberdine","beached sea turtle","darkshore","greymist","gwennyth bly'leggonde","murloc","naga","temple of the moon","ясеневый лес","аубердин","останки морской черепахи","темные берега","серая мгла","гвеннид блай'леггонд","мурлок","нага","храм луны"},ang={["class:Druid"]="Вид благородной морской черепахи, порабощенной ради перевозки оружия и брошенной гнить среди падальщиков, показывает оскверняющее пренебрежение нага к диким животным.",["faction:Alliance"]="Расследование этих обломков предупреждает Аубердин и Дарнасс о маршрутах снабжения нага, угрожающих северу Калимдора.",["race:NightElf"]="Осквернение морской жизни нага ради военных перевозок — оскорбление для кальдораев, а обнаружение этих следов помогает Храму Луны отслеживать угрозы в направлении Ясеневого леса."},sec={{t="Вьючное животное",b="Побережье Темных берегов усеяно костями древних морских существ, но скелет этой черепахи рассказывает явно рукотворную историю. На ее огромном панцире закреплены расщепленные обломки покореженной повозки. Существо погибло не от болезни или потери ориентации, как другие выброшенные на берег: его загнали на скалы, пока оно тащило груз. Среди обломков повозки лежит контейнер с незнакомой змеиной резьбой, брошенный среди падальщиков, занявших гниющий панцирь."},{t="Вторжение нага",b="Когда Гвеннид Блай'Леггонд осматривает найденный ящик в Аубердине, она определяет, что он сделан нага. Эти змеиные исчадия часто используют крупных морских зверей, чтобы доставлять припасы и оружие на берег во время амфибийных атак. Учитывая место крушения на южных берегах Темных берегов, Гвеннид подозревает, что обоз погиб на пути к Ясеневому лесу, что указывает на растущие амбиции нага на севере Калимдора."}},faq={{q="Почему у этой морской черепахи на спине повозка?",a="Повозку закрепили на существе нага, которые используют гигантских морских черепах как живых вьючных животных для перевозки припасов, оружия и военного снаряжения из морских глубин на сушу.",al={"turtle carriage","why turtle has cart","sea turtle harness","повозка на черепахе","почему у черепахи телега","упряжь морской черепахи"}},{q="Кто сейчас обитает в останках?",a="Отряд сильных мурлоков Серой Мглы занял гигантский панцирь после гибели черепахи, превратив ее огромную выпотрошенную тушу в укрепленное прибрежное убежище.",al={"who lives in turtle","greymist murlocs turtle","what is guarding turtle","кто живет в черепахе","мурлоки серой мглы черепаха","кто охраняет черепаху"}},{q="Куда нужно отнести Ящик со странной пометкой?",a="Ящик нужно отнести Гвеннид Блай'Леггонд, посланнице Храма Луны, находящейся в прибрежном поселении Аубердин.",al={"where do i take the box","strangely marked box","turn in marked box","куда отнести ящик","ящик со странной пометкой","сдать ящик с пометкой"}},{q="Что означают пометки на ящике?",a="Пометки сделаны письменностью нага. Они указывают, что ящик и повозка были частью обоза снабжения нага, двигавшегося вдоль побережья, вероятно, на юг к Ясеневому лесу, пока не случилась беда.",al={"turtle box lore","who made the marked box","naga box","предания ящика черепахи","кто сделал ящик","ящик нага"}},{q="Почему Храм Луны интересуется выброшенными черепахами?",a="Жрицы Элуны изучают природные и военные угрозы, поражающие побережье Темных берегов. Найденные предметы, такие как этот ящик, отправляют в Дарнасс, чтобы ученые могли отследить передвижения врагов.",al={"why temple wants turtles","gwennyth darkshore mission","зачем храму черепахи","задание гвеннид на темных берегах"}},{q="Куда направлялась черепаха перед гибелью?",a="Судя по месту, где лежит туша на побережье, Гвеннид Блай'Леггонд подозревает, что нага гнали нагруженное существо на юг, возможно, к Ясеневому лесу.",al={"turtle destination","where was turtle going","куда шла черепаха","пункт назначения черепахи"}}},fp="18,249,17.515.0,18.488.1,53.185.0,40.155.0,39.149.0,37.193.1,60.216.0,46.175.1"}
P.entries["quest:4732"] = {n="Останки морской черепахи",s="Вдоль продуваемого ветрами побережья Темных берегов с пугающей частотой на берег выбрасывает выбеленные кости гигантских морских черепах. Расследование этих печальных случаев дает Гвеннид Блай'Леггонд в Аубердине образцы для изучения того, почему вымирает морская жизнь Калимдора.",h="Вдоль продуваемого ветрами побережья Темных берегов с пугающей частотой на берег выбрасывает выбеленные кости...",kw={"auberdine","beached","darkshore","greymist","gwennyth bly'leggonde","murloc","nordrassil","sea turtle","teldrassil","temple of the moon","аубердин","останки","выброшенные на берег","темные берега","серая мгла","гвеннид блай'леггонд","мурлок","нордрассил","морская черепаха","тельдрассил","храм луны"},ang={["class:Druid"]="Печальное появление на берегу этих древних обитателей океана — явный знак нарушенного равновесия природы после битвы на горе Хиджал и внезапного появления Тельдрассила.",["class:Priest"]="Служа Храму Луны и доставляя эти останки, вы помогаете Сестринству Элуны распознать незримый духовный недуг, расползающийся по водам Калимдора.",["race:NightElf"]="Храм Луны стремится почтить и понять угасающих существ, которые некогда мирно резвились под ветвями Нордрассила."},sec={{t="Россыпь костей",b="Окутанное туманом побережье Темных берегов усеяно останками огромных левиафанов и величественных морских черепах. Многие из этих древних рептилий дрейфовали на мелководье или сами выбирались на песок, чтобы умереть. Мурлоки Серой Мглы часто стаями облепляют громадные туши, обгладывая мясо до панциря и костей и устраивая вокруг падали грубые стоянки."},{t="Исчезающие воды",b="До Третьей войны морские черепахи, как известно, процветали в священных водах вокруг горы Хиджал и корней Мирового Древа, Нордрассила. После жертвы Нордрассила, принесенной ради победы над Пылающим Легионом, и последующего посадения Тельдрассила у северного берега Калимдора их число резко упало. Жрицы Элуны, такие как Гвеннид Блай'Леггонд, изучают эти прибрежные останки от имени Храма Луны, пытаясь понять, что губит этих кротких гигантов: темная магия, меняющееся море или утрата их древнего убежища."}},faq={{q="Почему морские черепахи выбрасываются на берег на Темных берегах?",a="Точная причина остается для ночных эльфов загадкой. Раньше морские черепахи процветали в водах под Мировым Древом Нордрассилом. После разрушения Нордрассила в Третьей войне и возведения Тельдрассила их число резко сократилось, и многие, похоже, намеренно расстаются с жизнью на мелководье Темных берегов.",al={"why do turtles die here","darkshore turtle mystery","why beached","почему черепахи умирают здесь","загадка черепах темных берегов","почему выбрасываются на берег"}},{q="Кто такая Гвеннид Блай'Леггонд?",a="Гвеннид Блай'Леггонд — ночная эльфийка, ученая и представительница Храма Луны в Аубердине. Ей поручено каталогизировать и изучать выброшенных на берег морских существ, чтобы выяснить, почему страдает живая природа Темных берегов.",al={"who is gwennyth","where to turn in turtle remains","auberdine researcher","кто такая гвеннид","куда сдать останки черепахи","исследовательница аубердина"}},{q="Почему мурлоки собираются вокруг останков черепах?",a="Местные мурлоки Серой Мглы — падальщики-оппортунисты: они добывают из громадных туш пищу и материалы. Часто они ставят свои прибрежные поселения рядом с выброшенными морскими черепахами и морскими тварями, чтобы обглодать их дочиста.",al={"why murlocs on turtle","greymist scavengers","murloc camps on beach","почему мурлоки на черепахе","падальщики серой мглы","стоянки мурлоков на берегу"}},{q="Какая связь у этих черепах с Нордрассилом?",a="По словам ночных эльфов, морские черепахи когда-то были обычны и резвились в чистых водах у подножия горы Хиджал и Мирового Древа Нордрассила. Яростное разрушение Нордрассила глубоко нарушило природное равновесие, после чего этих существ стали видеть все реже.",al={"nordrassil connection","hyjal turtles","mount hyjal turtle link","связь с нордрассилом","черепахи хиджала","черепахи горы хиджал"}},{q="Имеет ли Тельдрассил отношение к их упадку?",a="Жрицы отмечают, что с тех пор как вырос Тельдрассил, морских черепах видят все реже. Изменило ли новое Мировое Древо прибрежные течения, нарушило ли их миграцию или несет неестественную ауру, влияющую на жизнь океана, — Храм Луны изучает этот вопрос и сейчас.",al={"teldrassil effect on turtles","why did teldrassil change turtles","влияние тельдрассила на черепах","почему тельдрассил изменил черепах"}},{q="Много ли выброшенных на берег существ на Темных берегах?",a="Да. На длинном побережье Темных берегов лежит множество выброшенных морских тварей и морских черепах. Каждая туша дает уникальные образцы костей и тканей, по которым Гвеннид Блай'Леггонд восстанавливает картину экологической катастрофы, разворачивающейся на берегу.",al={"more beached quests","other beached turtles","beached sea creatures","другие задания с останками","другие выброшенные черепахи","выброшенные морские твари"}}},fp="18,269,17.368.0,16.560.0,53.324.0,29.250.0,51.227.0,52.294.0,55.301.0,53.247.0"}
P.entries["quest:4733"] = {n="Останки морской твари",s="На скалистых бухтах Сумеречной Излучины в прибое лежит колоссальная туша гигантского молотильщика. Он намного крупнее любых известных местных особей, и его внезапная смерть — часть тревожной череды глубоководных аномалий, беспокоящих ночных эльфов Темных берегов.",h="На скалистых бухтах Сумеречной Излучины в прибое лежит колоссальная туша гигантского молотильщика.",kw={"auberdine","beached sea creature","darkshore","gwennyth bly'leggonde","sea creature bones","temple of the moon","thresher","twilight shore","аубердин","останки морской твари","темные берега","гвеннид блай'леггонд","кости морской твари","храм луны","молотильщик","сумеречная излучина"},ang={["class:Druid"]="Выброшенные на берег морские хищники на вершине пищевой цепи — верный признак экосистемы в беде, что созвучно более широкой тревоге Круга Кенария на всех Темных берегах.",["class:Priest"]="Гвеннид Блай'Леггонд проводит исследование под покровительством Храма Луны, стремясь к равновесию и божественному прозрению через осязаемое научное изучение баланса моря.",["race:NightElf"]="Необъяснимый упадок и выбрасывание морской жизни на берег близ Тельдрассила задевает кальдораев за живое: они ждут от Элуны и Храма Луны истолкования столь мрачных знамений."},sec={{t="Гигант, выброшенный на берег",b="Сумеречная Излучина на юге Темных берегов часто усеяна плавником и морским мусором, но в этой бухте лежит нечто куда более поразительное: останки огромного молотильщика. Хотя падальщики и приливы уже начали его растаскивать, его массивный скелет затмевает любого обычного хищника здешнего мелководья. Он явно чужак в этих водах, и на скалы его вынесли то ли неестественная болезнь, то ли потеря ориентации, то ли более глубокое потрясение в Сокрытом Море."},{t="Бдение Храма",b="В Аубердине жрицы, представляющие Храм Луны, проявили живой интерес к мертвым гигантам, выбрасываемым на берег. Гвеннид Блай'Леггонд руководит сбором образцов скелетов, чтобы выяснить, что гонит таких глубоководных хищников к гибели. Колоссальных молотильщиков когда-то видели у корней Тельдрассила, но их число неуклонно падает, и жрицы опасаются, что хрупкое морское равновесие у северного берега Калимдора рушится."}},faq={{q="Что это за зверь, туша которого лежит на берегу?",a="Это скелет огромного молотильщика, хищного морского зверя. Он в несколько раз крупнее обычных молотильщиков, обитающих у побережья Темных берегов, поэтому его присутствие здесь крайне необычно.",al={"what is the beached sea creature","giant thresher darkshore","beached monster carcass","что за останки морской твари","гигантский молотильщик темные берега","туша монстра на берегу"}},{q="Откуда изначально взялось это существо?",a="Жрица Гвеннид Блай'Леггонд отмечает, что особи таких огромных размеров когда-то бродили в водах у Тельдрассила, но их число неуклонно снижается. Оно не обитает на ближнем мелководье Темных берегов.",al={"where do giant threshers live","thresher origin","где живут гигантские молотильщики","происхождение молотильщика"}},{q="Почему Храм Луны изучает эти туши?",a="Храм Луны стремится понять повсеместное явление выбрасывания на берег, поражающее побережье Темных берегов. Исследуя кости и останки, жрицы надеются определить, что гонит глубоководных зверей на сушу: порча, болезнь или внешние силы.",al={"why does gwennyth want bones","temple of the moon sea creatures","why study beached animals","зачем гвеннид нужны кости","морские твари храма луны","зачем изучать выброшенных животных"}},{q="Куда нужно отнести кости?",a="Кости морской твари относят Гвеннид Блай'Леггонд, исследовательнице из ночных эльфов, живущей в портовом городке Аубердин.",al={"where to turn in sea creature bones","who gets the thresher bones","куда сдать кости морской твари","кому отдать кости молотильщика"}},{q="Где на побережье находится эта туша?",a="Туша лежит в скалистой бухте на Сумеречной Излучине — южной прибрежной полосе Темных берегов.",al={"where is the beached creature","thresher location darkshore","twilight shore skeleton","где выброшенное существо","молотильщик темные берега где","скелет сумеречная излучина"}},{q="Выбрасываются ли на берег другие существа на Темных берегах?",a="Да. По всей длине побережья Темных берегов были выброшены разные морские звери и исполины, что вызвало продолжающееся расследование исследователей в Аубердине.",al={"other beached animals","beached sea creature questline","другие выброшенные животные","цепочка заданий про морских тварей"}}},fp="20,278,19.481.0,18.480.1,43.199.0,45.229.0,55.260.0,34.124.0,43.101.0,59.173.0"}
P.entries["quest:4736"] = {n="Поиски Менары Расщепительницы Бездны",s="Это задание отправляет многообещающих чернокнижников Альянса за море, в засушливые Степи, на поиски Менары Расщепительницы Бездны. Менара живет в башне Страхада Фарсана над Кабестаном и предлагает опытным чернокнижникам создать особые предметы и одеяния, усиливающие их власть над демонами.",h="Это задание отправляет многообещающих чернокнижников Альянса за море, в засушливые Степи, на поиски Менары...",kw={"briarthorn","enchanted gold bloodrobe","ironforge","menara voidrender","ratchet","strahad farsan","the barrens","warlock","остротерн","зачарованная золотая кроводежда","стальгорн","менара расщепительница бездны","кабестан","страхад фарсан","степи","чернокнижник"},ang={["class:Warlock"]="Это путешествие — важный обряд посвящения в высшее колдовство, ведущий прямо к созданию Зачарованной золотой кроводежды чернокнижника.",["faction:Alliance"]="Путь вглубь Степей требует пересекать враждебные земли, полагаясь на хрупкий нейтралитет Кабестана, чтобы добраться до башни Страхада.",["race:Gnome"]="Гномы-чернокнижники, проявившие осторожную сдержанность перед тайной магией и порчей скверны, обнаруживают, что Менара ценит практический контроль куда больше, чем бесплодное теоретическое баловство.",["race:Human"]="Люди, привыкшие к тайным культам Штормграда и Стальгорна, должны приспособиться к относительной открытости уединенной вершины Кабестана."},sec={{t="Зов из Стальгорна",b="Остротерн, сообщник, скрывающийся в темных уголках Стальгорна, замечает, когда чернокнижник вышел за пределы начальной демонологии, не поддавшись порче. Вместо того чтобы держать учеников взаперти под горой, он направляет их в Калимдор, хваля их дисциплину и призывая искать наставлений у мастера, намного более искусного в практической магии скверны."},{t="Убежище над Кабестаном",b="На утесах над гоблинским портом Кабестан стоит одинокая башня Страхада Фарсана. В мире, глубоко подозрительном к темному колдовству, адепты скверны ради выживания часто отбрасывают расовые и политические границы. Менара Расщепительница Бездны живет в убежище Страхада именно поэтому: она работает с чернокнижниками любой принадлежности, чтобы их опасное ремесло оставалось острым, а призванные исчадия — прочно подчиненными."}},faq={{q="Кто дает задание «Поиски Менары Расщепительницы Бездны»?",a="Задание дает Остротерн, действующий в темных закоулках Стальгорна и работающий с чернокнижниками Альянса, достигшими достаточного уровня дисциплины.",al={"quest giver","who gives quest","briarthorn location","персонаж, выдающий задания","кто дает задание","где остротерн"}},{q="Где можно найти Менару Расщепительницу Бездны?",a="Менара Расщепительница Бездны живет в башне Страхада Фарсана в Степях, на утесах прямо над гоблинским портовым городом Кабестан.",al={"menara voidrender location","where is menara voidrender","strahad farsan tower location","где менара расщепительница бездны","менара расщепительница бездны местонахождение","башня страхада фарсана"}},{q="Почему чернокнижнику Альянса приходится ехать на территорию Орды?",a="Чернокнижники по необходимости часто действуют вне обычной верности фракциям. Кабестан — нейтральный порт, которым управляет Картель Хитрая Шестеренка, а башня Страхада дает уединенное убежище, где адепты запретной магии могут собираться и учиться вдали от посторонних глаз.",al={"why go to the barrens","why travel to ratchet","barrens dangerous for alliance","зачем идти в степи","зачем ехать в кабестан","степи опасны для альянса"}},{q="Что предлагает Менара после выполнения задания?",a="Разговор с Менарой открывает возможность создать мощное облачение чернокнижника, начиная с задания собрать компоненты для Зачарованной золотой кроводежды.",al={"what does menara teach","quest reward","next quest after menara","чему учит менара","награда за задание","следующее задание после менары"}},{q="Менара Расщепительница Бездны принадлежит к Альянсу или к Орде?",a="Менара Расщепительница Бездны нейтральна к адептам темных искусств, откуда бы они ни были. Хотя она строга и колюча, она помогает любому дисциплинированному чернокнижнику, ищущему ее наставлений.",al={"menara faction","is menara friendly","фракция менары","дружелюбна ли менара"}},{q="Почему чернокнижники собираются вне зависимости от расы?",a="Как отмечает Менара, демонические существа, которых призывают чернокнижники, не различают рас, когда мстят неосторожным призывателям. Выживание и власть над Круговертью Пустоты требуют общих знаний и взаимной поддержки, а не фракционных склок.",al={"warlock unity","why do warlocks work together","единство чернокнижников","почему чернокнижники работают вместе"}}},fp="30,300,24.382.0,25.444.0,54.173.0,37.144.0,63.275.0,39.160.0,39.181.0,47.248.0"}
P.entries["quest:4737"] = {n="Поиски Менары Расщепительницы Бездны",s="Зеврост, циничный наставник чернокнижников, скрывающийся в Расселине Теней в Оргриммаре, отправляет опытных чернокнижников на поиски Менары Расщепительницы Бездны в Степях. Несмотря на суровые предостережения о неизбежной цене демонической порчи, он указывает честолюбивым чернокнижникам на опытного наставника, способного создавать могущественные магические одеяния.",h="Зеврост, циничный наставник чернокнижников, скрывающийся в Расселине Теней в Оргриммаре, отправляет опытных...",kw={"barrens","bloodrobe","cleft of shadow","fel magic","menara voidrender","ratchet","warlock robe","zevrost","степи","кроводежда","расселина теней","магия скверны","менара расщепительница бездны","кабестан","одеяние чернокнижника","зеврост"},ang={["class:Warlock"]="Это задание — важный обряд посвящения для чернокнижников Орды: под руководством Менары Расщепительницы Бездны они создают собственную легендарную Зачарованную золотую кроводежду.",["faction:Horde"]="Чернокнижникам Орды постоянно приходится сталкиваться с презрением традиционных шаманов и воинов, и убежище они находят лишь в укромных местах вроде Расселины Теней в Оргриммаре или на нейтральной земле возле Кабестана."},sec={{t="Предостережения из тени",b="Глубоко под Оргриммаром, в Расселине Теней, чернокнижники живут под покровом неохотной терпимости. Зеврост — один из самых желчных наставников темных искусств, он охотно насмехается над честолюбивыми учениками, стремящимися к мастерству. По его мнению, каждый, кто погружается глубже в магию Скверны, лишь мчится навстречу собственному порабощению. Он настаивает, что вопрос лишь во времени: демоническая зависимость полностью овладеет чернокнижником и превратит даже самого дисциплинированного ученого в раба Круговерти Пустоты."},{t="Путь в Кабестан",b="Несмотря на презрительные предсказания, Зеврост признает, что другие чернокнижники не разделяют его мрачного взгляда. До Оргриммара дошли слухи о Менаре Расщепительнице Бездны, искусной чернокнижнице, обосновавшейся на утесах над нейтральным портом гоблинов Кабестаном. Менара ищет перспективных учеников, чтобы вместе создавать особые орудия для управления их магической силой. Для чернокнижников, стремящихся продвинуться в своем ремесле, этот вызов становится началом создания легендарной Зачарованной золотой кроводежды."},{t="Прагматичное братство",b="Когда чернокнижник находит Менару высоко над Кабестаном, природа общества чернокнижников становится совершенно очевидной. Менара замечает, что чернокнижники должны отложить расовые и культурные распри и поддерживать друг друга: демоны, с которыми они заключают сделки, не знают предубеждений и не щадят никого, кто оступился. Обмен знаниями и создание защитных одеяний — не благородная благотворительность, а практическая необходимость, чтобы выжить среди враждебных существ, подчиненных их воле."}},faq={{q="Кто такой Зеврост?",a="Зеврост — орк, наставник чернокнижников, обитающий в Расселине Теней под Оргриммаром. Он глубоко циничен в отношении стремления к силе Скверны и считает всех честолюбивых чернокнижников глупцами, обреченными стать рабами демонической порчи.",al={"zevrost","zevrost lore","who starts in search of menara voidrender","зеврост","зеврост предания","кто начинает поиски менары расщепительницы бездны"}},{q="Кто такая Менара Расщепительница Бездны?",a="Менара Расщепительница Бездны — опытная чернокнижница, живущая в Степях на утесах над гоблинским портом Кабестан. Она наставляет начинающих чернокнижников и помогает им собирать редкие реагенты для создания могущественных церемониальных одеяний.",al={"menara voidrender","where is menara voidrender","who is menara","менара расщепительница бездны","где менара расщепительница бездны","кто такая менара"}},{q="Почему Зеврост считает всех чернокнижников глупцами?",a="Зеврост считает, что магия Скверны неизбежно развращает и порабощает всякого, кто пытается ею овладеть. По его мнению, ни у кого не хватает воли избежать зависимости, а стремление к большей силе лишь ускоряет падение.",al={"zevrost corruption","why does zevrost warn me","зеврост порча","почему зеврост предупреждает меня"}},{q="Где найти Менару Расщепительницу Бездны?",a="Менара находится в Степях, на высоких холмах над прибрежным портом Кабестан. Чтобы добраться до ее лагеря, чернокнижникам нужно пройти на восток через засушливую саванну.",al={"menara location","find menara voidrender","где менара","найти менару расщепительницу бездны"}},{q="Почему чернокнижники разных рас работают вместе?",a="Как объясняет Менара, призванные чернокнижниками демонические силы одинаково жестоки к каждому, кто не сумел их обуздать. Поскольку выживание зависит от абсолютной точности, чернокнижники регулярно делятся знаниями и инструментами независимо от культурных границ.",al={"warlock solidarity","why do warlocks band together","единство чернокнижников","почему чернокнижники держатся вместе"}},{q="Что происходит после встречи с Менарой Расщепительницей Бездны?",a="Менара Расщепительница Бездны сразу поручает чернокнижнику собрать по всему Азероту редкие и мощные материалы для создания Зачарованной золотой кроводежды — защитного одеяния, настроенного на энергии Скверны.",al={"next quest after menara","what does menara want","следующее задание после менары","что хочет менара"}}},fp="30,330,23.500.0,19.489.0,22.464.0,15.230.0,25.236.0,46.226.0,37.187.0,51.252.0,45.191.0"}
P.entries["quest:4738"] = {n="Поиски Менары Расщепительницы Бездны",s="Чернокнижника Альянса, желающего создать могущественные одеяния, тайные чернокнижники Квартала магов отправляют к Менаре Расщепительнице Бездны за Великое море. Высоко над нейтральным портом Кабестан Менара обучает темных заклинателей независимо от принадлежности к фракции опасным искусствам подчинения и создания артефактов.",h="Чернокнижника Альянса, желающего создать могущественные одеяния, тайные чернокнижники Квартала магов...",kw={"bloodrobe","demisette cloyce","enchanted gold bloodrobe","menara voidrender","ratchet","slaughtered lamb","the barrens","warlock quest","кроводежда","демизетта клойс","зачарованная золотая кроводежда","менара расщепительница бездны","кабестан","забитый ягненок","степи","задание чернокнижника"},ang={["class:Warlock"]="Этот обряд посвящения соединяет скрытые норы Штормграда с открытыми землями Калимдора и учит, что стремление к власти над демонами выходит за рамки смертных фракций.",["faction:Alliance"]="Это путешествие заставляет заклинателей Альянса покинуть привычные восточные земли и отправиться в дикие Степи, чтобы найти особое обучение."},sec={{t="Неохотная рекомендация",b="В темных склепах под «Забитым ягненком» в Штормграде наставница чернокнижников Демизетта Клойс известна строгими и неумолимыми требованиями. Когда начинающий чернокнижник готов создавать значительные предметы силы, Демизетта редко считает его действительно готовым. Тем не менее вышестоящие члены кабала приказывают продвинуть ученика и отправляют его далеко от безопасной столицы, чтобы он доказал свою доблесть."},{t="Башня над Кабестаном",b="Цель пути — засушливые холмы над гоблинским портом Кабестан в Степях. Там в каменной башне находится лаборатория Менары Расщепительницы Бездны. Вдали от строгих законов Штормграда и бдительных глаз Оргриммара Менара принимает учеников независимо от расы и политических пристрастий, ведь исчадия и демонические существа, с которыми имеют дело чернокнижники, одинаково злобны ко всякой смертной душе."}},faq={{q="Почему чернокнижника Альянса отправляют так далеко, в Степи?",a="Мало кто в Альянсе обладает магическими знаниями или свободой для создания сложных одеяний Скверны, таких как Зачарованная золотая кроводежда. Менара Расщепительница Бездны работает в уединенной башне над нейтральным портом Кабестан и дает редкое убежище, где чернокнижники любого происхождения могут изучать опасные ремесла вдали от столичной стражи и инквизиторов.",al={"why ratchet","why go to barrens","why menara voidrender","почему кабестан","почему идти в степи","почему менара расщепительница бездны"}},{q="Кто такая Демизетта Клойс?",a="Демизетта Клойс — старшая наставница чернокнижников из людей, которая тайно действует под «Забитым ягненком» в Квартале магов Штормграда. Строгая и оберегающая опасные знания, она отправляет учеников к Менаре, только если получает приказ от незримых сил, направляющих общину чернокнижников.",al={"demisette cloyce lore","who starts in search of menara","демизетта клойс предания","кто начинает поиски менары"}},{q="Волнует ли Менару Расщепительницу Бездны конфликт Альянса и Орды?",a="Нет. Менара прямо объясняет, что чернокнижники должны смотреть дальше расовых и фракционных границ. Демоны и силы иных миров, которых они призывают, одинаково свирепы ко всем, кто оступился, поэтому совместное выживание и общие темные искусства намного важнее смертных войн.",al={"is menara horde or alliance","does menara hate alliance","менара за орду или за альянс","ненавидит ли менара альянс"}},{q="Какой предмет Менара Расщепительница Бездны учит чернокнижника создавать?",a="Встреча с Менарой — первый шаг к тому, чтобы превратить Одеяние тайных знаний в легендарную Зачарованную золотую кроводежду — могущественное одеяние, наполненное редкими реагентами, тонким шитьем и связанной демонической энергией.",al={"what does menara teach","what robe is this for","bloodrobe quest","чему учит менара","для какого одеяния это","задание кроводежда"}},{q="Опасно ли чернокнижнику Альянса путешествовать в Кабестан?",a="Степи — в основном территория Орды, населенная враждебными животными, кентаврами и орочьими патрулями. Однако сам Кабестан — нейтральный порт, которым управляет Картель Хитрая Шестеренка, поэтому башня Менары доступна, если путник из Альянса держится берега или благополучно прибывает на корабле из Пиратской бухты.",al={"how dangerous is ratchet","is the barrens safe","насколько опасен кабестан","безопасны ли степи"}},{q="Почему Демизетта Клойс считает, что игрок не готов?",a="Демизетта считает создание предметов силы, наполненных Скверной, безрассудством для неопытных новичков. Артефакты чернокнижников требуют строгой дисциплины: малейшая ошибка при подчинении реагентов или демонических эссенций может погубить чернокнижника или выпустить в мир ужасы.",al={"why demisette doubts player","demisette warning","почему демизетта сомневается в игроке","предупреждение демизетты"}}},fp="30,323,26.438.0,23.419.0,59.366.0,24.286.0,65.253.0,61.198.0,58.290.0,55.248.0"}
P.entries["quest:4739"] = {n="Поиски Менары Расщепительницы Бездны",s="Это задание отправляет перспективных чернокнижников Орды из темных кварталов Подгорода через море в Кабестан. На вершине холма над портом наставница Менара Расщепительница Бездны ждет тех, кто готов создавать могущественные магические одеяния.",h="Это задание отправляет перспективных чернокнижников Орды из темных кварталов Подгорода через море в Кабестан.",kw={"barrens","enchanted gold bloodrobe","kaal soulreaper","menara voidrender","ratchet","strahad's tower","undercity","warlock","степи","зачарованная золотая кроводежда","каел жнец душ","менара расщепительница бездны","кабестан","башня страхада","подгород","чернокнижник"},ang={["class:Warlock"]="Это путешествие отмечает переход чернокнижника к продвинутой практике и открывает путь к созданию особых одеяний, настроенных на энергии Пустоты.",["faction:Horde"]="Задание показывает, как разрозненные группы чернокнижников Орды поддерживают подпольную сеть, охватывающую и Лордерон, и Калимдор.",["race:Undead"]="Начав путь в мрачных глубинах Подгорода, чернокнижники-Отрекшиеся должны отправиться за море, в выжженные солнцем пустоши Калимдора, чтобы продолжить свои тайные занятия."},sec={{t="Зов из тени",b="В столице Отрекшихся, Подгороде, Каел Жнец Душ наблюдает за растущим талантом практикующих чернокнижников. Видя, что чернокнижник перерос простейшие сглазы и подчиненных бесов, он призывает его искать особое обучение за Великим морем. Искусство подчинения демонов не терпит колебаний, и лишь опытные наставники могут обеспечить выживание чернокнижника среди переменчивых сил Пустоты."},{t="Башня над Кабестаном",b="На высоком утесе над гоблинским портом Кабестан стоит башня Страхада Фарсана. Вдали от бдительного суда городской стражи здесь собираются такие мастера, как Менара Расщепительница Бездны, чтобы обучать молодых посвященных. Чернокнижники разного происхождения откладывают племенную и политическую вражду перед суровой реальностью своего ремесла: демоны, с которыми они заключают сделки, без предубеждений пожрут человека, орка или Отрекшегося, если воля дрогнет."}},faq={{q="Кто выдает это задание?",a="Это задание выдает в Подгороде Каел Жнец Душ. Он замечает, когда чернокнижник достиг достаточной силы и опыта, чтобы извлечь пользу из продвинутого обучения у Менары Расщепительницы Бездны.",al={"quest giver","where to get quest","kaal soulreaper location","персонаж, выдающий задание","где взять задание","где каел жнец душ"}},{q="Где найти Менару Расщепительницу Бездны?",a="Менара живет в Степях, в каменной башне над портовым городом Кабестан вместе со Страхадом Фарсаном.",al={"where is menara","find menara voidrender","menara location","где менара","найти менару расщепительницу бездны","местонахождение менары"}},{q="Почему чернокнижникам Орды нужно идти так далеко, в Степи?",a="Демонические искусства практикуют в уединенных общинах, где чужие глаза не помешают. Менара Расщепительница Бездны проводит особое обучение и создает одеяния в башне Страхада, где чернокнижники любого происхождения учатся без вмешательства светских или религиозных властей.",al={"why ratchet","why travel to barrens","why go to menara","почему кабестан","почему идти в степи","зачем идти к менаре"}},{q="Что происходит после встречи с Менарой Расщепительницей Бездны?",a="Менара признает ваше обучение и предлагает провести вас через создание Зачарованной золотой кроводежды — так начинается цепочка заданий по сбору редких и опасных компонентов по всему Азероту.",al={"quest continuation","what does menara give me","next quest","продолжение задания","что даст мне менара","следующее задание"}},{q="Почему чернокнижники разных рас делятся знаниями?",a="Как объясняет Менара, демоны не знают пощады и не различают рас, если призыватель не смог их обуздать. Практическая необходимость выжить заставляет чернокнижников делиться приемами и беречь свое ремесло от общей катастрофы.",al={"warlock cooperation","why work together warlock","menara warlock lore","сотрудничество чернокнижников","почему чернокнижники работают вместе","предания менары"}},{q="Кто такой Страхад Фарсан?",a="Страхад Фарсан — мастер-чернокнижник, владеющий уединенной каменной башней над Кабестаном, которая служит убежищем и учебным центром для тех, кто стремится овладеть демоническими искусствами вдали от крупных оплотов фракций.",al={"strahad tower","who owns the tower in ratchet","strahad farsan","башня страхада","чья башня в кабестане","страхад фарсан"}}},fp="30,231,26.422.0,23.444.0,22.180.0,37.121.0,58.271.0,46.182.0,51.225.0,22.216.0"}
P.entries["quest:474"] = {n="Убить Нек'роша",s="Задание «Убить Нек'роша» стало завершением кампании Альянса против клана Драконьей Пасти в Болотине. Осадные машины орков выведены из строя, и искателям приключений приказано убить вождя Нек'роша, чтобы защитить Гавань Менетилов. Отрубленная голова, принесенная капитану Крепкому Кулаку, разрушает орочью угрозу прибрежному порту.",h="Задание «Убить Нек'роша» стало завершением кампании Альянса против клана Драконьей Пасти в Болотине.",kw={"captain stoutfist","catapult","chieftain","dragonmaw","ironforge","menethil harbor","nek'rosh","wetlands","капитан крепкий кулак","катапульта","вождь","драконья пасть","стальгорн","гавань менетилов","нек'рош","болотина"},ang={["class:Warrior"]="Схватка с вождем Нек'рошем в его собственном укрепленном лагере — высшее испытание воинской стойкости в бою с одним из самых свирепых орочьих командиров болот.",["faction:Alliance"]="Защита Гавани Менетилов оберегает главную морскую артерию, связывающую Стальгорн и Штормград с Калимдором и северными водами.",["race:Dwarf"]="Для дворфов Каз Модана Драконья Пасть — незаживающий шрам на границах их предков. Убийство Нек'роша напрямую защищает дороги дворфов и западную морскую торговлю Стальгорна."},sec={{t="Обезглавить Драконью Пасть",b="Орки Драконьей Пасти давно терроризируют болота Каз Модана, укрепившись в своих лагерях и угрожая морским путям Гавани Менетилов. Сожгя катапульты клана, защитники болот наносят удар прямо в голову змеи. Вождь Нек'рош, предводитель местного отряда, остается последним препятствием к снятию осады. Его гибель лишает остальных налетчиков Драконьей Пасти тактической слаженности."},{t="Защита гавани",b="Отрубленная голова Нек'роша, доставленная капитану Крепкому Кулаку в Гавань Менетилов, — огромная победа гарнизона Стальгорна. Лишившись и тяжелых осадных орудий, и вождя, Драконья Пасть получила удар, от которого вряд ли скоро оправится. Для осажденного порта, главной связи Альянса между Лордероном и Каз Моданом, гибель вождя означает, что причалы и торговые суда будут в безопасности от внезапного нападения."}},faq={{q="Кто такой Нек'рош?",a="Нек'рош — беспощадный вождь, возглавляющий остатки клана Драконьей Пасти в Болотине. Из своих лагерей он готовил нападение на Гавань Менетилов с помощью осадных катапульт, пока не вмешались искатели приключений Альянса.",al={"chieftain nek'rosh","who is nekrosh","nekrosh wetlands","вождь нек'рош","кто такой нек'рош","нек'рош болотина"}},{q="Почему Гавань Менетилов хочет смерти Нек'роша?",a="Нек'рош представлял прямую смертельную угрозу для Гавани Менетилов. Под его началом Драконья Пасть построила боевые катапульты, чтобы обстреливать порт и парализовать важные морские пути, связывающие Каз Модан с другими землями Альянса.",al={"why kill nekrosh","captain stoutfist motives","зачем убивать нек'роша","мотивы капитана крепкого кулака"}},{q="Кто приказывает убить Нек'роша?",a="Приказ следует сразу после поджога катапульт Драконьей Пасти. Отрубленная голова вождя в итоге доставляется капитану Крепкому Кулаку, командующему обороной Гавани Менетилов.",al={"who gives defeat nekrosh","where to turn in nekrosh head","кто выдает задание убить нек'роша","куда сдать голову нек'роша"}},{q="Что станет с кланом Драконьей Пасти после гибели Нек'роша?",a="Лишившись катапульт и вождя, отряд Драконьей Пасти жестоко страдает от потери руководства и боевого духа. Хотя отставшие бойцы все еще бродят по болотам, их наступление на Гавань Менетилов фактически сорвано.",al={"dragonmaw after nekrosh","what happens to wetlands orcs","драконья пасть после нек'роша","что стало с орками болотины"}},{q="Что клан Драконьей Пасти делает в Болотине?",a="Клан Драконьей Пасти обосновался в Болотине и на соседнем нагорье Грим Батола во время Второй войны. После поражения Орды отколовшиеся остатки клана задержались в болотах, грабя торговые пути и питая глубокую ненависть к Альянсу и дворфам Каз Модана.",al={"why are dragonmaw in wetlands","dragonmaw wetlands lore","почему драконья пасть в болотине","драконья пасть болотина предания"}},{q="Почему Гавань Менетилов так важна для Альянса?",a="Гавань Менетилов — единственный крупный морской порт королевства Стальгорн на западном побережье. Это главный узел для переправы войск, товаров и путников через Великое море в Калимдор и на север, в Лордерон.",al={"importance of menethil","menethil harbor strategic value","значение менетилов","гавань менетилов стратегическое значение"}}},fp="15,336,26.471.0,19.468.0,16.242.0,44.242.0,33.211.0,62.248.1,49.273.0,50.224.0"}
P.entries["quest:4740"] = {n="РАЗЫСКИВАЕТСЯ: Глубомрак!",s="РАЗЫСКИВАЕТСЯ: Глубомрак! — награда за голову от Альянса, объявленная на доске объявлений у таверны в Аубердине. Совет деревни требует смерти Глубомрака, опасного вождя мурлоков, которого винят в убийстве ночного эльфа-часового и потоплении торговых судов у Темных берегов. Искателям приключений предстоит пройти на юг вдоль туманного берега, выманить налетчика и свершить правосудие.",h="РАЗЫСКИВАЕТСЯ: Глубомрак!",kw={"auberdine","darkshore","glynda nal'shea","greymist","murkdeep","murloc","sentinels","wanted poster","аубердин","темные берега","глинда нал'шия","серая мгла","глубомрак","мурлок","часовые","объявление о розыске"},ang={["race:NightElf"]="Для кальдораев, защищающих Темные берега, убийство Глубомрака мстит за павшую сестру из Часовых и оберегает хрупкую связь, которую обеспечивают причалы Аубердина."},sec={{t="Угроза на туманных отмелях",b="Мурлоки Серой Мглы на побережье Темных берегов обычно считались лишь досадной помехой, но Глубомрак довел дело до открытой войны с Аубердином. Согласно объявлению у городской таверны, свирепое существо напрямую повинно в гибели как минимум одного ночного эльфа-часового и подозревается в порче или крушении двух грузовых судов в прибрежных водах. Из-за растущих морских потерь и набегов на берег Совет деревни Аубердин назначил публичную награду, чтобы покончить с разбушевавшимся вожаком мурлоков."},{t="Засада у хижин",b="Глубомрак не бродит без дела по открытому берегу. Он скрывается у южного побережья возле группы мурлочьих хижин вокруг костра. Любой, кто вторгнется в лагерь, вызывает организованную оборону: волны береговых бегунов и прибрежных ползунов Серой Мглы выходят из прибоя защищать поселение, а затем и сам Глубомрак появляется с авангардом, чтобы расправиться с нарушителями."},{t="Правосудие для павших",b="Возвращение в Аубердин с доказательством гибели Глубомрака — мрачная необходимость для Часовых. Часовой Глинда Нал'Шия выплачивает награду от имени совета. Со смертью вожака Серой Мглы путники и морские пути в туманах Темных берегов получают передышку от прибрежных диверсий."}},faq={{q="Где взять задание на Глубомрака?",a="Задание можно взять у объявления о розыске прямо у таверны в центре Аубердина, в Темных берегах.",al={"where to start wanted murkdeep","murkdeep quest start","auberdine wanted poster","где начать разыскивается глубомрак","задание глубомрак начало","объявление аубердин"}},{q="Почему совет Аубердина назначил награду за Глубомрака?",a="Глубомрак — особенно жестокий мурлок, убивший как минимум одного ночного эльфа-часового и подозреваемый в потоплении двух грузовых судов у берегов Темных берегов.",al={"why kill murkdeep","what did murkdeep do","murkdeep crimes","зачем убивать глубомрака","что сделал глубомрак","преступления глубомрака"}},{q="Где найти Глубомрака?",a="Глубомрак находится далеко к югу от Аубердина на пляже, где охраняет три мурлочьи хижины вокруг центрального костра.",al={"murkdeep location","where is murkdeep","murkdeep camp","местонахождение глубомрака","где глубомрак","лагерь глубомрака"}},{q="Почему Глубомрака нет в лагере мурлоков, когда я прихожу?",a="Глубомрак не стоит на виду. Когда вы входите между хижинами у костра, из океана выходят волны мурлоков Серой Мглы. Глубомрак появляется с последней волной, после того как убиты первые защитники.",al={"murkdeep not there","murkdeep spawn","how to summon murkdeep","глубомрака нет","появление глубомрака","как призвать глубомрака"}},{q="Кому сдавать задание после смерти Глубомрака?",a="Сообщите о смерти Глубомрака Часовому Глинде Нал'Шия, несущей службу в Аубердине.",al={"who to turn in murkdeep","murkdeep turn in","glynda nalshea location","кому сдать глубомрака","сдача задания глубомрак","где глинда нал'шия"}},{q="Отличаются ли мурлоки этого лагеря от других мурлоков Темных берегов?",a="Глубомрак командует мурлоками племени Серой Мглы, среди которых прибрежные разведчики и воины, действующие согласованными волнами для защиты своего прибрежного лагеря.",al={"greymist murlocs","murkdeep tribe","what murlocs are with murkdeep","мурлоки серой мглы","племя глубомрака","какие мурлоки с глубомраком"}}},fp="17,361,36.540.0,22.387.0,22.324.0,42.117.0,59.168.0,26.134.0,52.218.0,45.96.0,71.160.0"}
P.entries["quest:475"] = {n="Ветер тревоги",s="Ветер тревоги — раннее задание, которое дает Атридас Медвежья Шкура в Тельдрассиле: выяснить, почему нет вестей из Деревни Звездного Ветра. Великий страж Гаролас Талветрен охраняет неподалеку спящих Друидов Когтя, и его внезапное молчание говорит о неестественной опасности, подбирающейся к Мировому Древу.",h="Ветер тревоги — раннее задание, которое дает Атридас Медвежья Шкура в Тельдрассиле: выяснить, почему нет...",kw={"athridas bearmantle","ban'ethil","druids of the talon","emerald dream","gaerolas talvethren","starbreeze village","teldrassil","troubling breeze","ysera","атридас медвежья шкура","бен'этиль","друиды когтя","изумрудный сон","гаролас талветрен","деревня звездного ветра","тельдрассил","ветер тревоги","изера"},ang={["class:Druid"]="Друиды глубоко почитают Обитель Бен'этиль и спящих, связанных с Изерой, поэтому любое беспокойство их стражей становится для них срочным личным делом.",["race:NightElf"]="Для ночных эльфов охрана священного покоя Друидов Когтя — залог сохранения хрупкого равновесия их нового дома в Тельдрассиле."},sec={{t="Безмолвный страж",b="В поселениях на ветвях Тельдрассила связь обычно быстрая и размеренная. Атридас Медвежья Шкура полагается на вести от Гароласа Талветрена, Великого стража, которому поручено присматривать за Друидами Когтя, отдыхающими в Обители Бен'этиль. Эти спящие друиды хранят священный союз с Изерой в Изумрудном Сне, и потому их убежище жизненно важно для духовного равновесия молодого Мирового Древа. Когда вести с востока прекратились, над лесным пологом нависло тревожное предчувствие."},{t="Тревога в Звездном Ветре",b="Атридас просит путников отправиться на восток через лес в Деревню Звездного Ветра и лично найти Гароласа. Отсутствие гонцов — не простая небрежность: в глуши начали разливаться скверна и тревожить зверей. Встреча с Гароласом показывает, что чутье Атридаса не обмануло: в деревню пришла беда, угрожающая безопасности ближних лежбищ."}},faq={{q="Кто такой Атридас Медвежья Шкура?",a="Атридас Медвежья Шкура — видный ночной эльф-надзиратель в Тельдрассиле, следящий за благополучием леса и охраняющий покой убежищ своих спящих собратьев-друидов.",al={"athridas bearmantle","athridas lore","quest giver athridas","атридас медвежья шкура","атридас предания","атридас выдает задание"}},{q="Кто такой Гаролас Талветрен?",a="Гаролас Талветрен — Великий страж, избранный охранять спящих Друидов Когтя в соседней Обители Бен'этиль и обеспечивать их безопасность, пока их души блуждают в Изумрудном Сне.",al={"gaerolas talvethren","great warden gaerolas","who is gaerolas","гаролас талветрен","великий страж гаролас","кто такой гаролас"}},{q="Что такое Обитель Бен'этиль?",a="Обитель Бен'этиль — священная подземная полость в Тельдрассиле, где друиды-ночные эльфы подолгу спят, общаясь с Изерой и храня свои обеты в Изумрудном Сне.",al={"ban'ethil barrow den","banethil","what is ban'ethil","обитель бен'этиль","бен'этиль","что такое бен'этиль"}},{q="Почему Гаролас не выходил на связь?",a="Гаролас не мог передавать свои обычные донесения, потому что внезапная опасность и скверна начали угрожать Деревне Звездного Ветра и окрестному лесу, и он был занят борьбой за сохранение контроля.",al={"why was gaerolas silent","what happened to gaerolas","trouble in starbreeze","почему гаролас молчал","что случилось с гароласом","беда в звездном ветре"}},{q="Куда ведет это задание дальше?",a="Найдя Гароласа Талветрена в Деревне Звездного Ветра, вы получите от него поручение вернуться к Атридасу Медвежьей Шкуре в Доланаар с тяжелой вестью о соседних фурболгах Скрюченной Сосны, захваченных распространяющейся неестественной скверной.",al={"next quest","a troubling breeze followup","what comes after a troubling breeze","следующее задание","ветер тревоги продолжение","что после ветра тревоги"}},{q="О каком союзе с Изерой говорится в задании?",a="Друиды-ночные эльфы погружаются в долгий медитативный сон, чтобы бродить по Изумрудному Сну рядом с зеленым драконьим родом и Изерой, оберегая первозданный облик природы.",al={"pact with ysera","ysera druid pact","druids of the talon sleep","союз с изерой","друидский союз изеры","сон друидов когтя"}}},fp="18,302,16.513.0,20.392.1,27.190.0,27.198.0,33.181.0,32.200.0,32.215.1,51.177.0"}
P.entries["quest:476"] = {n="Порча Кривой Сосны",s="Порча Кривой Сосны — срочное курьерское задание в Тельдрассиле, которое выдает раненый великий страж Гаролас Талветрен. Оно предупреждает руководство ночных эльфов в Доланааре о том, что фурболги Кривой Сосны поддались демонической порче и захватили Деревню Звездного Ветра. Это сообщение подготавливает почву для военного и друидического вмешательства, чтобы порча не добралась до спящих друидов Обители Бен'этиль.",h="Порча Кривой Сосны — срочное курьерское задание в Тельдрассиле, которое выдает раненый великий страж Гаролас...",kw={"athridas bearmantle","ban'ethil barrow den","dolanaar","fel moss","furbolg","gaerolas talvethren","gnarlpine corruption","starbreeze village","ursal the mauler","атридас медвежья шкура","обитель бен'этиль","доланаар","мох скверны","фурболг","гаролас талветрен","порча кривой сосны","деревня звездного ветра","урсал изверг"},ang={["class:Druid"]="Угроза Обители Бен'этиль — вопрос выживания для Круга Кенария: спящие собратья беззащитны перед оскверненным племенем Кривой Сосны.",["race:NightElf"]="Падение Деревни Звездного Ветра — трагический удар: даже новорожденное Мировое Древо уже уязвимо для демонической порчи, с которой ночные эльфы так упорно боролись."},sec={{t="Отчаянное предупреждение",b="Гаролас Талветрен тяжело ранен и лежит возле руин Деревни Звездного Ветра: на него напали его бывшие союзники. Фурболги Кривой Сосны, которых долго считали мирными соседями и хранителями дикой природы, внезапно одичали. Будучи слишком слаб, чтобы самому принести весть, Гаролас поручает искателю приключений быстро доставить ее Атридасу Медвежьей Шкуре в Доланаар, пока безумие не распространилось дальше по ветвям Тельдрассила."},{t="Бич Мха Скверны",b="Донесение, доставленное Атридасу, раскрывает тревожную правду: фурболги не просто стали беспокойными, они подвергаются воздействию магии Скверны. Их вождь, Урсал Изверг, подчинил оскверненный Мох Скверны, разросшийся в Мировом Древе, и довел свой народ до яростного неистовства. Это открытие угрожает не только поселениям вроде Деревни Звездного Ветра — оно напрямую ставит под удар соседнюю Обитель Бен'этиль, где спящие друиды остаются совершенно беззащитными перед обезумевшим племенем."}},faq={{q="Что случилось с Деревней Звездного Ветра?",a="Деревня Звездного Ветра была захвачена и разграблена фурболгами Кривой Сосны после того, как их поразила магия Скверны. Внезапное нападение изгнало или перебило жителей, а Гаролас Талветрен остался в ловушке раненым.",al={"why is starbreeze abandoned","starbreeze village attacked","who destroyed starbreeze","почему звездный ветер заброшен","нападение на деревню звездного ветра","кто разрушил деревню звездного ветра"}},{q="Почему фурболги Кривой Сосны стали агрессивными?",a="Их вождь, Урсал Изверг, начал использовать злую силу Мха Скверны, растущего в Тельдрассиле. Темная магическая сущность довела племя до неукротимого яростного неистовства против бывших союзников — ночных эльфов.",al={"why are gnarlpine mad","gnarlpine madness","why attack furbolgs","почему кривая сосна безумна","безумие кривой сосны","почему фурболги нападают"}},{q="Кто такой Гаролас Талветрен?",a="Гаролас Талветрен — ночной эльф, великий страж спящих Друидов Когтя. На него напало племя Кривой Сосны, когда он шел к Обители Бен'этиль. Слишком ранен, чтобы дойти до Доланаара, он надеется на путников, которые донесут весть о беде.",al={"gaerolas","injured night elf starbreeze","гаролас","раненый ночной эльф звездный ветер"}},{q="Кто такой Атридас Медвежья Шкура?",a="Атридас Медвежья Шкура — влиятельный представитель власти ночных эльфов в Доланааре. Он отвечает за безопасность региона и помогает координировать ответ на возникающие угрозы Мировому Древу и его обитателям.",al={"athridas","athridas bearmantle dolanaar","атридас","атридас медвежья шкура доланаар"}},{q="Почему ночные эльфы беспокоятся об Обители Бен'этиль?",a="В Обители Бен'этиль находятся многочисленные друиды, погруженные в Изумрудный Сон. Если неистовые фурболги Кривой Сосны доберутся до курганов, спящие ночные эльфы окажутся совершенно беззащитными перед их нападением.",al={"ban'ethil threat","why ban'ethil barrow den matters","sleeping druids danger","угроза бен'этиль","почему важна обитель бен'этиль","опасность для спящих друидов"}},{q="Что такое Мох Скверны?",a="Мох Скверны — оскверненный растительный нарост в Тельдрассиле, зараженный темной демонической энергией. Его порча сводит с ума местных животных и фурболгов, когда те касаются его или используют.",al={"what is fel moss","fel moss teldrassil","что такое мох скверны","мох скверны тельдрассил"}}},fp="20,418,19.457.0,23.506.1,36.218.0,47.226.0,27.272.0,27.205.0,59.211.0,17.186.0"}
P.entries["quest:4761"] = {n="Тандрис Ветропряд",s="Тандрис Ветропряд — задание Альянса, связывающее разведку друида Терентиса среди местных фурболгов с руководством Аубердина. Убедившись в растущей агрессии соседнего племени Чернолесья, искатели приключений должны доложить напрямую старейшине Ветропряду. Старейшина стремится понять первопричины порчи, искажающей дикую природу Темных берегов.",h="Тандрис Ветропряд — задание Альянса, связывающее разведку друида Терентиса среди местных фурболгов с...",kw={"auberdine","blackwood","cliffspring","darkshore","furbolg","terenthis","thundris windweaver","аубердин","чернолесье","река скалистая","темные берега","фурболг","терентис","тандрис ветропряд"},ang={["class:Druid"]="Быстрая порча местных фурболгов и лесных жителей говорит о тяжелом нарушении равновесия природы, которое союзники Кенария и деревенские старейшины не вправе игнорировать.",["faction:Alliance"]="Защита Аубердина от враждебных лесных племен жизненно важна для безопасности линий снабжения Альянса и путников, пересекающих путь между Калимдором и Тельдрассилом.",["race:NightElf"]="Аубердин — главный порт и опорный пункт кальдорай на материковом побережье; доставляя сведения старейшине Ветропряду, вы напрямую помогаете своему народу сохранить священную глушь."},sec={{t="Донесение старейшине",b="После вашей разведки в оскверненных лагерях фурболгов на Темных берегах друид Терентис направляет вас к деревенскому старейшине Аубердина, Тандрису Ветропряду. Пока Терентис изучает распространяющуюся порчу в глуши, Тандрис занимается повседневными нуждами поселения и оценивает более широкие духовные и природные опасности, грозящие кальдорай. Донесение дает руководству ясное свидетельство того, что фурболги не просто защищают территорию, а разрушаются под действием неестественной злобы."},{t="Порча на побережье",b="Получив весть о лагере фурболгов, Тандрис подтверждает, что Аубердин уже давно борется с растущей враждебностью местных лесных жителей. Еще тревожнее самой агрессии подкрадывающаяся порча, заражающая почву, растения и воды Темных берегов. Полагая, что исцелить землю можно, лишь найдя источник заразы, Тандрис решает проследить порчу вверх по течению и привлекает способных союзников для исследования водных путей региона."}},faq={{q="Кто такой Тандрис Ветропряд?",a="Тандрис Ветропряд — старейшина Аубердина, мудрый управитель городских дел и повседневной жизни. Он тесно работает с часовыми и друидами, чтобы понять странную порчу, распространяющуюся по Темным берегам, и противостоять ей.",al={"thundris windweaver","auberdine elder","who is thundris","тандрис ветропряд","старейшина аубердина","кто такой тандрис"}},{q="Почему Терентис посылает вас к Тандрису?",a="Разведав лагеря фурболгов Чернолесья, Терентис решает, что руководство города необходимо уведомить. У Тандриса Ветропряда есть теории о том, почему животные и фурболги впадают в безумие, и ему нужны сведения из первых рук для организации ответных действий.",al={"why go to thundris","terenthis report","auberdine report","зачем идти к тандрису","донесение терентиса","донесение аубердин"}},{q="Что происходит с фурболгами на Темных берегах?",a="Местные фурболги Темных берегов становятся все агрессивнее, поддаваясь темной порче, которая искажает сам лес. Их враждебность — не простые пограничные споры, а следствие зловещей заразы, отравляющей землю.",al={"corrupted furbolgs","furbolg hostility","why are furbolgs mad","оскверненные фурболги","враждебность фурболгов","почему фурболги безумны"}},{q="Куда ведет это расследование дальше?",a="Старейшина Ветропряд подозревает, что источники воды Темных берегов могут нести причину гнили. Он тут же направляет искателей приключений взять пробу из реки Скалистой, чтобы выяснить, откуда идет загрязнение.",al={"next quest","what after thundris","cliffspring river quest","следующее задание","что после тандриса","задание река скалистая"}}},fp="19,387,21.513.0,26.490.0,27.244.0,40.267.0,47.232.0,40.208.0"}
P.entries["quest:4762"] = {n="Река Скалистая",s="Река Скалистая — крупная река на севере Темных берегов, которая быстро загрязняется и угрожает поселению Аубердин. Тандрис Ветропряд поручает исследователям Альянса набрать пробу воды из-под водопада у моста, чтобы подтвердить расползающуюся заразу. Тандрис подозревает более глубокий источник порчи за пределами берегов реки.",h="Река Скалистая — крупная река на севере Темных берегов, которая быстро загрязняется и угрожает поселению...",kw={"auberdine","blackwood","cliffspring","darkshore","felwood","river","taint","thundris","waterfall","windweaver","аубердин","чернолесье","река скалистая","темные берега","оскверненный лес","река","порча","тандрис","водопад","ветропряд"},ang={["class:Druid"]="Для друидов Круга Кенария вид чистых лесных вод, гниющих от затаившейся демонической порчи, — призыв к оружию ради очищения раненой природы Темных берегов.",["race:NightElf"]="Аубердин зависит от равновесия побережья Темных берегов, и гниль, растекающаяся в Туманный Предел, угрожает домам и средствам к жизни кальдорай."},sec={{t="Отравленная река",b="Стекая с восточных возвышенностей, Река Скалистая впадает в прибрежные мели у Туманного Предела, к северу от Аубердина. Недавно ее воды стали загрязняться, неся неестественную гниль к поселению ночных эльфов. Опасаясь, что поток отравит окрестные берега и запасы города, Тандрис Ветропряд посылает разведчиков вверх по реке набрать пробы из водоема под дорожным мостом."},{t="Корень зла в Оскверненном лесу",b="Хотя местные фурболги Чернолесья устроили лагеря вдоль реки и сильно возбуждены, Тандрис подозревает, что они лишь распространяют заразу, корень которой лежит в другом месте. Он называет источником Оскверненный лес и предсказывает, что проба подтвердит его догадку. Погибший лес на востоке был изуродован в Третью войну. Чтобы очистить воду, придется противостоять оскверненным фурболгам и очистить древние источники земли."}},faq={{q="Где взять пробу воды?",a="Идите на север от Аубердина до устья Реки Скалистой у Туманного Предела. Следуйте вверх по реке вглубь суши до первого водопада прямо под дорожным мостом и наполните пробирку в водоеме.",al={"where is the water sample","cliffspring river location","waterfall pool location","где проба воды","где река скалистая","где водоем у водопада"}},{q="Почему Река Скалистая загрязняется?",a="Тандрис подозревает, что грязь могут приносить фурболги Чернолесья, живущие вдоль реки, но считает, что корень их порчи лежит глубже. Для расследования ему нужна проба воды.",al={"why is river corrupted","what is poisoning darkshore water","cliffspring taint source","почему река осквернена","что отравляет воду темных берегов","источник порчи реки скалистой"}},{q="Кто такой Тандрис Ветропряд?",a="Тандрис Ветропряд — ученый и исследователь из ночных эльфов, живущий в Аубердине. Он изучает упадок природы, распространяющийся по Темным берегам, и пытается выяснить причины порчи в регионе.",al={"thundris windweaver lore","who gives cliffspring river quest","предания о тандрисе ветропряде","кто выдает задание река скалистая"}},{q="Виноваты ли фурболги в отравлении реки?",a="Тандрис подозревает, что они могут распространять заразу, но полагает, что источник их порчи лежит глубже. Проба воды должна помочь ему в расследовании.",al={"did furbolgs taint the water","blackwood furbolg corruption","фурболги отравили воду","порча фурболгов чернолесья"}},{q="Как эта река влияет на Аубердин?",a="Река Скалистая впадает в Туманный Предел к северу от города. Прибрежные течения грозят принести гнилые стоки прямо к берегу Аубердина, угрожая рыбным промыслам, растениям и запасам пресной воды.",al={"threat to auberdine","why does auberdine care about cliffspring","угроза аубердину","почему аубердину важна река скалистая"}},{q="Что будет после проверки пробы?",a="Тандрис благодарит вас за пробу и готовится дальше изучать оскверненных фурболгов Чернолесья, надеясь найти способ очистить их от порчи.",al={"quest after cliffspring river","what follows cliffspring river","задание после реки скалистой","что дальше после реки скалистой"}}},fp="21,357,18.431.0,19.459.1,36.229.0,42.179.1,27.198.0,53.164.1,37.223.0,38.149.1"}
P.entries["quest:4763"] = {n="Порабощенные фурболги Чернолесья",s="Следуя улике, найденной в оскверненных водах реки Скалистой, Тандрис Ветропряд посылает искателей приключений разорвать темные узы, душащие племя Чернолесья. Очистив их пищу водой из лунного колодца, вы выманиваете их демонического хозяина и разрушаете его власть над северным лагерем.",h="Следуя улике, найденной в оскверненных водах реки Скалистой, Тандрис Ветропряд посылает искателей приключений...",kw={"auberdine","blackwood","darkshore","furbolg","moonwell","satyr","talisman of corruption","thundris windweaver","xabraxxis","аубердин","чернолесье","темные берега","фурболг","лунный колодец","сатир","талисман порчи","тандрис ветропряд","ксабраксис"},ang={["class:Druid"]="Восстановление равновесия требует вырезать гниль с корнем. Сатир, использующий талисманы скверны, чтобы искажать исконных лесных созданий, делает схватку с Ксабраксисом неотложной задачей для Круга Кенария.",["class:Priest"]="Направлять чистую, исцеляющую милость Элуны через воду лунных колодцев — разительный контраст с губительной магией Тени и скверны, которую применяют сатиры.",["race:NightElf"]="Во время Войны Древних фурболги были давними союзниками кальдораев; видеть, как они подпадают под власть своих исконных врагов, сатиров, — горькая трагедия, которую ночные эльфы стремятся исправить."},sec={{t="Скрытый повелитель",b="Ночные эльфы Аубердина давно пытались понять, почему некогда мирные фурболги Чернолесья так яростно обратились против соседей. Расследование вдоль реки Скалистой показало, что причина порчи — вмешательство сатиров. Эти древние слуги Пылающего Легиона исподволь управляют племенем: они направляют через коварные талисманы магию скверны, искажают разум фурболгов и вгоняют их в звериную ярость."},{t="Разрыв оков",b="Чтобы выманить кукловода, Тандрис Ветропряд готовит простое, но действенное средство. Из северного поселения Чернолесья собирают обычную провизию — зерно, фрукты и орехи — и погружают ее в священную воду из лунного колодца Аубердина, очищая оскверненную пищу. Если поставить эту благословенную еду у центрального костра, находящиеся рядом фурболги ненадолго освобождаются от безумия, и вмешавшийся сатир-осквернитель Ксабраксис, прямо выдавший себя, в ярости появляется защищать свои извращенные владения."}},faq={{q="Почему фурболги Чернолесья агрессивны?",a="Их разум отравлен демоническим влиянием. Сатиры тайно поселились рядом с лагерями и направляют через зачарованные талисманы скверную магию, превращающую природные инстинкты фурболгов в бешеную жестокость.",al={"why furbolgs mad","why are furbolgs hostile","blackwood aggression","почему фурболги безумны","почему фурболги враждебны","агрессия чернолесья"}},{q="Кто такой Ксабраксис?",a="Ксабраксис — сатир-осквернитель, управляющий северным лагерем фурболгов Чернолесья. Он действует из тени, чтобы племя оставалось во власти безумия скверны, и поддерживает свой контроль с помощью Талисмана порчи.",al={"xabraxxis lore","who is the satyr","satyr boss darkshore","ксабраксис предания","кто такой сатир","босс сатир темные берега"}},{q="Излечит ли очищение пищи фурболгов навсегда?",a="Нет. Пища, пропитанная водой лунного колодца, лишь ненадолго рассеивает демонический морок, чтобы фурболги ощутили мир и выманили Ксабраксиса. Убийство сатира и захват его талисмана — значительная победа, но, как отмечает Тандрис Ветропряд, поиск постоянного лекарства для порабощенных племен потребует новых усилий.",al={"is the cure permanent","did we save the furbolgs","are furbolgs cured","постоянно ли лекарство","спасли ли мы фурболгов","исцелены ли фурболги"}},{q="Откуда пришла идея использовать воду из лунного колодца?",a="Лунные колодцы — священные источники, благословленные богиней Элуной, полные живительной магии, противостоящей скверне и нежити. Тандрис Ветропряд дает очищающую чашу, чтобы освященная вода нейтрализовала демонические яды в пище фурболгов.",al={"why moonwell water","moonwell cleansing bowl","почему вода лунного колодца","очищающая чаша лунного колодца"}},{q="Что происходит, когда чашу с едой ставят у костра?",a="Ближайшие фурболги ненадолго приходят в себя от кровожадности, мирно собираются вокруг благословенной еды и перестают нападать. Разъяренный тем, что его марионетки освобождаются от мучений, Ксабраксис тут же является, чтобы покарать вмешавшихся.",al={"bowl near bonfire","cleansing the furbolgs","чаша у костра","очищение фурболгов"}},{q="Кто такой Тандрис Ветропряд?",a="Тандрис Ветропряд — ночной эльф, исследователь и следователь, расквартированный в Аубердине. Он координирует усилия по выяснению первопричин расползающегося упадка природы Темных берегов и безумия местных животных.",al={"thundris windweaver lore","who gives the quest","тандрис ветропряд предания","кто выдает задание"}}},fp="23,308,15.435.0,21.515.1,42.215.0,17.216.0,52.314.1,51.262.0,57.237.1,27.222.0"}
P.entries["quest:4767"] = {n="Ветрокрыл",s="«Ветрокрыл» — задание Орды, которое дает Элу на вершине Заставы Вольного Ветра в Тысяче Игл. Мечтая сам стать всадником на ветрокрыле, Элу просит искателей приключений подняться на скалистые высоты Скального гнездовья и собрать яйца диких виверн, чтобы пополнить воздушные резервы Орды.",h="«Ветрокрыл» — задание Орды, которое дает Элу на вершине Заставы Вольного Ветра в Тысяче Игл.",kw={"elu","freewind post","highperch","thousand needles","wind rider","wyvern eggs","элу","застава вольного ветра","скальное гнездовье","тысяча игл","ветрокрыл","яйца виверн"},ang={["class:Hunter"]="Охотники, знакомые с приручением и нравом зверей, оценят опасность и точность, необходимые, чтобы забрать дикие кладки прямо из гнезда территориального хищника.",["faction:Horde"]="Виверны — основа транспортной сети Орды в Калимдоре, поэтому пополнение их стойл критически важно для связи и обороны на границах.",["race:Tauren"]="Всадники на ветрокрылах Заставы Вольного Ветра гордятся своим мастерством воздушного полета и считают уход за вивернами и их обучение почетным делом."},sec={{t="Зов неба",b="По всему Калимдору Орда во многом полагается на ветрокрылов, перевозящих гонцов, разведчиков и воинов на огромные расстояния. На Заставе Вольного Ветра юный таурен по имени Элу мечтает вступить в их почетные ряды. Поскольку потребности растущей Орды опережают число ездовых животных, Элу поручено помочь раздобыть новых виверн для мастеров-ветрокрылов, и желающие путники могут принять участие в этом важном деле."},{t="Восхождение на Скальное гнездовье",b="Скальное гнездовье возвышается на огромных плато Тысячи Игл и служит отличным местом гнездования диких виверн. Чтобы собрать годные яйца, нужно преодолеть скалы и сразиться со свирепо защищающими гнезда взрослыми особями, патрулирующими насесты. Добыв эти кладки, Элу надеется доказать свою преданность и начать трудный процесс выращивания и обучения виверн для вожатых полета Орды."}},faq={{q="Кто выдает это задание?",a="Задание выдает Элу, мечтающий стать всадником на ветрокрыле, на вершине Заставы Вольного Ветра в Тысяче Игл.",al={"wind rider quest giver","who starts wind rider","elu location","персонаж, выдающий задание ветрокрыл","кто начинает ветрокрыл","где элу"}},{q="Что нужно Элу?",a="Элу просит вас принести десять яиц виверны Скального гнездовья, собранных прямо из гнезд в Скальном гнездовье.",al={"wind rider objectives","what do i collect","wyvern eggs","цели ветрокрыла","что собирать","яйца виверн"}},{q="Где находится Скальное гнездовье?",a="Скальное гнездовье — возвышенное плато к северо-западу от Заставы Вольного Ветра и чуть южнее Заставы Белого Плеса. Естественный подъем, отмеченный тотемным столбом, ведет от дна каньона к местам гнездования.",al={"how to get to highperch","highperch entrance","where are wyvern eggs","как добраться до скального гнездовья","вход в скальное гнездовье","где яйца виверн"}},{q="Почему Орда собирает яйца диких виверн?",a="Мастера-ветрокрылы Орды сталкиваются с растущим спросом на воздушных скакунов на всех заставах, а одного разведения в неволе недостаточно. Выращивание виверн из диких кладок позволяет укротителям обучать новых скакунов для перевозок и разведки.",al={"why harvest wyvern eggs","lore behind wyvern eggs","зачем собирать яйца виверн","предания о яйцах виверн"}},{q="Враждебны ли дикие виверны?",a="Да. Дикие виверны свирепо охраняют свою территорию и потомство и сразу нападают на всех, кто приближается к их кладкам в Скальном гнездовье.",al={"will wyverns attack","wyvern danger","нападут ли виверны","опасность виверн"}},{q="Что Элу собирается делать с яйцами?",a="Элу надеется, что доставка яиц позволит ему начать официальное обучение всадника на ветрокрыле: растить существ и сближаться с ними, чтобы служить Орде в небе.",al={"elu wyverns","what happens to the eggs","элу виверны","что будет с яйцами"}}},fp="10,269,19.432.0,19.390.0,21.97.0,19.98.0,27.200.0,44.257.0,29.143.0,41.158.0"}
P.entries["quest:477"] = {n="Пересечение границ",s="«Пересечение границ» — шпионское задание, которое дает жрец Тени Алистер в Гробнице: разузнать о тайных действиях Даларана в Серебряном бору. Перехватив ящики со снабжением для лагеря Даларана близ Деревни Погребальных Костров, Отрекшиеся надеются выяснить, зачем Кирин-Тор поддерживает оплот людей — Янтарную мельницу.",h="«Пересечение границ» — шпионское задание, которое дает жрец Тени Алистер в Гробнице: разузнать о тайных...",kw={"ambermill","border crossings","dalaran crate","hillsbrad","pyrewood village","sepulcher","shadow priest allister","silverpine forest","янтарная мельница","пересечение границ","ящик даларана","хилсбрад","деревня погребальных костров","гробница","жрец тени алистер","серебряный бор"},ang={["class:Mage"]="Заклинатели Орды очень заинтересованы в перехвате магических грузов Даларана, чтобы выяснить, какие тайны и защитные чары использует Кирин-Тор в Лордероне.",["class:Priest"]="Служба под началом жреца Тени Алистера дает жрецам Отрекшихся прямую возможность защищать владения Культа Забытой Тени от святых и тайных соперников.",["race:Undead"]="Отрекшиеся не могут терпеть неподконтрольный форпост Даларана на своем южном фланге, особенно тот, что снабжается прямо под носом у Гробницы."},sec={{t="Снабжение на границе",b="Хотя Янтарная мельница остается главным оплотом уцелевшего сопротивления людей в восточной части Серебряного бора, маги Даларана не оставили их одних. Повозки с припасами и магическими принадлежностями тайно вывозят из Предгорий Хилсбрада через Серебряный бор для снабжения передовых застав и плацдармов. Один такой лагерь находится к северу от Деревни Погребальных Костров, и там дорогу охраняют люди Даларана."},{t="Подозрения Отрекшихся",b="Жрец Тени Алистер и руководство Отрекшихся в Гробнице считают пристальный интерес Даларана к Янтарной мельнице тревожным. По их мнению, захолустный городок едва ли оправдывает риск ресурсов и жизней Кирин-Тора на территории, занятой Отрекшимися, если на кону не стоит более важная стратегическая или магическая цель. Изучив ящики, Отрекшиеся получат прямые сведения о том, что Даларан отправляет на запад."},{t="Раскрытие груза",b="Вскрытый ящик чародеев содержит больше, чем простую провизию. Среди аккуратно упакованных тайных принадлежностей лежит связка старых пожелтевших карт Серебряного бора и всего западного Лордерона, а также загадочный магический кулон. Похоже, Даларан занят не обычным снабжением, а целенаправленной картографической и магической разведкой."}},faq={{q="Почему маги Даларана действуют в Серебряном бору?",a="Даларан действует из Янтарной мельницы, чтобы сохранить присутствие людей и Альянса в западном Лордероне. Жрец Тени Алистер подозревает, что у Кирин-Тора есть более глубокий скрытый мотив, помимо защиты сельской деревушки, и потому Отрекшиеся нападают на их линии снабжения.",al={"why is dalaran here","dalaran silverpine","why dalaran at ambermill","почему здесь даларан","даларан серебряный бор","зачем даларан в янтарной мельнице"}},{q="Где находятся ящики Даларана?",a="Ящики стоят в лагере, который содержат маги и стражи Даларана, прямо к северу от Деревни Погребальных Костров, в стороне от главной дороги.",al={"crate location","where are the crates","pyrewood camp","где ящик","где ящики","лагерь погребальных костров"}},{q="Что внутри ящика Даларана?",a="Allister does not know what Dalaran is shipping. He asks you to retrieve the contents of a crate from the camp north of Pyrewood Village so he can investigate.",al={"crate contents","what is in the box","содержимое ящика","что в ящике"}},{q="Кто такой жрец Тени Алистер?",a="Жрец Тени Алистер — видный предводитель Отрекшихся, находящийся в Гробнице в Серебряном бору. Он руководит разведкой и наступательными ударами против уцелевших людей и вторжений Даларана.",al={"shadow priest allister","who gives border crossings","жрец тени алистер","кто выдает пересечение границ"}},{q="Как припасы попадают в Серебряный бор?",a="Грузы везут на повозках с территории Даларана в Предгорьях Хилсбрада через пограничный перевал в Серебряный бор, а затем они попадают в лагеря близ Янтарной мельницы и Погребальных Костров.",al={"dalaran supply route","hillsbrad wagons","путь снабжения даларана","повозки хилсбрада"}},{q="Что следует после выполнения этого задания?",a="After inspecting the crate, take what you discover back to Shadow Priest Allister for study in the follow-up, Maps and Runes.",al={"what next","follow up quest","next quest","что дальше","следующее задание","продолжение задания"}}},fp="16,343,24.444.0,24.417.0,20.368.1,52.263.0,37.143.0,33.159.1,30.204.0,52.195.0,42.125.1"}
P.entries["quest:4770"] = {n="Путь домой",s="«Путь домой» — задание Орды: искателям приключений нужно спасти Паоку Ходячую Гору, молодого тауренского натуралиста, застрявшего в гнездовьях виверн в Скальном гнездовье. Потерявшись во время изучения опасных зверей, Паока должен безопасно спуститься со скал и вернуться к Заставе Белого Плеса.",h="«Путь домой» — задание Орды: искателям приключений нужно спасти Паоку Ходячую Гору, молодого тауренского...",kw={"escort","highperch","homeward bound","motega firemane","pao'ka swiftmountain","thousand needles","whitereach post","wyvern","сопровождение","скальное гнездовье","путь домой","мотега огненная грива","паока ходячая гора","тысяча игл","застава белого плеса","виверна"},ang={["faction:Horde"]="Виверны — важные союзники и ездовые животные Орды по всему Калимдору, поэтому дикие особи Скального гнездовья представляют большой природный и стратегический интерес.",["race:Tauren"]="Для тауренов связь между племенами и старейшинами превыше всего; глубокая ответственность Мотеги перед отцом Паоки показывает тесные общинные обязательства, которыми руководствуются их экспедиции."},sec={{t="Натуралист в беде",b="Паока Ходячая Гора сопровождал старейшину Мотега Огненная Грива из Мулгора в Тысячу Игл, чтобы изучать уникальную фауну дна каньона и его высоких каменных столбов. Из любопытства и самоуверенности Паока в одиночку пробрался на вершины Скального гнездовья, чтобы вблизи понаблюдать за местными вивернами. Территориальные звери прогнали его, и юный ученый несколько дней прятался среди скал, напуганный и оставшийся без помощи."},{t="Путь вниз по скалам",b="Скальное гнездовье кишит агрессивными вивернами, яростно охраняющими кладки и высокие насесты. Чтобы вернуть Паоку на ровную землю, нужно прорубить путь прямо сквозь гнездящихся хищников. Не готовый к открытому бою, перепуганный юноша целиком полагается на проходящих мимо путников Орды, которые отгоняют роящихся виверн, пока он не доберется до относительно безопасной тропы в каньоне, ведущей на восток."},{t="Облегчение и расплата",b="Добравшись до подножия скал, Паока может спокойно бежать домой, к Заставе Белого Плеса. Его опекун Мотега Огненная Грива потрясен рассказом о случившемся. Мотега обещал робкому отцу Паоки присматривать за мальчиком во время полевых исследований. Радуясь, что Паока пережил свою безрассудную вылазку, Мотега награждает его спасителей, но втайне сожалеет, что не приковал опрометчивого ученика к тотему."}},faq={{q="Кто такой Паока Ходячая Гора?",a="Паока Ходячая Гора — молодой тауренский ученик, отправившийся в Тысячу Игл с Мотегой Огненной Гривой, чтобы описывать и изучать диких существ. Юношеский энтузиазм привел к тому, что он без присмотра забрел в Скальное гнездовье.",al={"paoka","pao'ka","who is the escort npc","паока","паока ходячая гора","кто такой сопровождаемый персонаж"}},{q="Почему Паока прятался в Скальном гнездовье?",a="Он в одиночку отправился к насестам, чтобы получше рассмотреть местных виверн и их гнезда. Агрессивные звери напали на него, вынудили прятаться и оставили в ловушке на высоком плато.",al={"why is paoka in highperch","what happened to paoka","why is he stuck","почему паока в скальном гнездовье","что случилось с паокой","почему он застрял"}},{q="Кто такой Мотега Огненная Грива?",a="Мотега Огненная Грива — тауренский натуралист, живущий на Заставе Белого Плеса в Тысяче Игл. Отец Паоки поручил ему следить за безопасностью юноши во время научной экспедиции.",al={"motega","who is motega firemane","quest turn in npc","мотега","кто такой мотега огненная грива","персонаж сдачи задания"}},{q="Где находится Скальное гнездовье?",a="Скальное гнездовье — возвышенное плато и гнездовья виверн в западной части Тысячи Игл, к западу от Заставы Белого Плеса и к северо-западу от Заставы Вольного Ветра.",al={"highperch location","where is highperch","where do i escort him from","скальное гнездовье расположение","где скальное гнездовье","откуда сопровождать его"}},{q="Где находится Застава Белого Плеса?",a="Застава Белого Плеса — небольшой лагерь Орды к востоку от Скального гнездовья в Тысяче Игл, полевая база тауренских натуралистов, изучающих фауну каньона.",al={"whitereach location","where is whitereach post","белый плес расположение","где застава белого плеса"}},{q="Знал ли Мотега, что Паока пропал?",a="Нет. Паока тайком ушел в Скальное гнездовье, ничего не сказав Мотеге, поэтому Мотега совершенно не подозревал об опасности, грозившей ученику, пока вы не сообщили о спасении.",al={"did motega know","why didn't motega search for him","знал ли мотега","почему мотега не искал его"}}},fp="14,315,29.423.0,23.387.0,20.428.1,28.212.0,35.195.0,23.190.0,27.169.0,25.166.0,36.177.1"}
P.entries["quest:478"] = {n="Карты и руны",s="«Карты и руны» — разведывательное задание Отрекшихся в Серебряном бору. Обнаружив подозрительный груз, отправленный в Янтарную мельницу, искатели приключений забирают кулон с рунами и относят его жрецу Тени Алистеру в Гробницу для дальнейшего расследования.",h="«Карты и руны» — разведывательное задание Отрекшихся в Серебряном бору.",kw={"ambermill","dalaran crate","kirin tor","maps and runes","rune-inscribed pendant","shadow priest allister","silverpine forest","the sepulcher","янтарная мельница","ящик из даларана","кирин-тор","карты и руны","кулон с рунами","жрец тени алистер","серебряный бор","гробница"},ang={["class:Mage"]="Кулон с рунами несет характерные чары Кирин-Тора, показывающие особую традицию Даларана в области защитной и тайной магии.",["class:Priest"]="Хотя жрец Тени Алистер владеет мощной магией Тьмы, священные и теневые учения плохо подходят для распутывания сложных тайных формул, высеченных на кулоне.",["faction:Horde"]="Защита Серебряного бора от сил, лояльных Альянсу, вроде Кирин-Тора, позволяет Орде сохранить важный путь снабжения через север Лордерона.",["race:Undead"]="Уцелевшие маги Даларана держат форпосты неприятно близко к землям Подгорода. Отобрать у них зачарованные талисманы жизненно важно для защиты суверенитета Отрекшихся в Серебряном бору."},sec={{t="Скрытый груз",b="Перехватывая снабжение вокруг Янтарной мельницы, агенты Орды находят ящик из Даларана, спрятанный на приграничных путях. Вместо обычных припасов в нем лежат подробные карты местности и загадочный кулон с рунами. Понимая, чем грозит магия Даларана так близко к их границам, разведчики осторожно забирают артефакт, чтобы не встревожить окрестных людских часовых."},{t="Шепот в Гробнице",b="Вернувшись в Гробницу, разведчики передают найденный кулон жрецу Тени Алистеру. Руководство Отрекшихся понимает, что Кирин-Тор действует в Янтарной мельнице с определенной целью, но суть их замыслов остается неясной. Не сумев сам разгадать могучее волшебство, вплетенное в руны, Алистер решает обратиться к знатокам тайной магии среди нежити, чтобы раскрыть замысел Даларана."}},faq={{q="Что находится в ящике из Даларана?",a="В ящике лежат стратегические карты области Серебряного бора и странный кулон с рунами. Эти предметы показывают, что маги Даларана активно планируют действия вокруг города Янтарная мельница.",al={"what was in the crate","crate contents","dalaran crate loot","что было в ящике","содержимое ящика","добыча из ящика даларана"}},{q="Кто такой жрец Тени Алистер?",a="Жрец Тени Алистер — влиятельный представитель Отрекшихся в Гробнице. Он руководит местной разведкой и координирует оборону от враждебных остатков людей и агентов Кирин-Тора в Серебряном бору.",al={"who is allister","shadow priest allister lore","кто такой алистер","жрец тени алистер предания"}},{q="Почему Отрекшихся беспокоит Даларан в Янтарной мельнице?",a="Янтарная мельница служит действующим оплотом Кирин-Тора прямо на границе земель Лордерона, на которые претендуют Отрекшиеся. Любое перемещение тайных реликвий или скрытное движение войск — прямая угроза власти Подгорода над Серебряным бором.",al={"why ambermill matters","forsaken dalaran conflict","почему важна янтарная мельница","конфликт отрекшихся и даларана"}},{q="Сможет ли жрец Тени Алистер расшифровать кулон?",a="Нет. Алистер понимает, что артефакт принадлежит чародеям Даларана, но его чары не поддаются жреческому искусству, поэтому он ищет помощи у того, кто глубже владеет тайной магией.",al={"does allister know the runes","can allister read the pendant","знает ли алистер руны","может ли алистер прочитать кулон"}},{q="Куда ведет расследование дальше?",a="Расследование продолжается в задании «Анализ Далара»: кулон передают Далару Ткачу Рассвета, специалисту по тайной магии в Гробнице, способному разобрать магию Кирин-Тора.",al={"what is the next quest","after maps and runes","какое следующее задание","после карт и рун"}},{q="Какое задание предшествует «Картам и рунам»?",a="Это задание идет сразу после «Пересечения границ», где Отрекшиеся поручают агенту проверить подозрительные торговые ящики, которые ввозят в Серебряный бор с границ Даларана.",al={"prerequisite quest","maps and runes prereq","предыдущее задание","карты и руны требования"}}},fp="14,265,14.410.0,25.408.1,33.200.0,30.237.0,58.254.0,48.198.0,40.185.0,38.174.0"}
P.entries["quest:479"] = {n="Расследование в Янтарной Мельнице",s="«Расследование в Янтарной Мельнице» — задание Отрекшихся, которое выдает жрец Тени Алистер в Гробнице. Пока маги Даларана плетут чары в соседней Янтарной мельнице, Отрекшиеся должны сорвать их колдовство и отобрать магические фокусы, чтобы удержать Серебряный бор.",h="«Расследование в Янтарной Мельнице» — задание Отрекшихся, которое выдает жрец Тени Алистер в Гробнице.",kw={"allister","ambermill","dalar","dalaran","kirin tor","pendant","sepulcher","silverpine","алистер","янтарная мельница","далар","даларан","кирин-тор","кулон","гробница","серебряный бор"},ang={["class:Mage"]="Маги понимают, какая точная согласованность нужна для плетения масштабных тайных ритуалов, и видят, почему разрыв зачарованных фокусов Кирин-Тора нарушает их колдовство.",["faction:Horde"]="Защита Серебряного бора оберегает западные подступы к Лордерону от застав, лояльных Альянсу и верных Даларану.",["race:Undead"]="Остатки Кирин-Тора в Янтарной мельнице стоят на пороге земель Подгорода, и их магические замыслы — невыносимая угроза выживанию Отрекшихся."},sec={{t="Угроза с востока",b="Людской город Янтарная мельница расположен в холмах восточной части Серебряного бора; им прочно владеют маги и защитники, присягнувшие Кирин-Тору Даларана. Пока маги проводят огромный согласованный ритуал, сплетая магические энергии, жрец Тени Алистер и его соратник Далар видят прямую опасность. Если позволить Кирин-Тору беспрепятственно направлять свою силу, Отрекшихся могут полностью вымести из Серебряного бора."},{t="Срыв плетения",b="Пока Далар наблюдает и прослеживает потоки магии по лесу, Алистер отправляет агентов в Янтарную мельницу, чтобы ударить прямо по чародеям. Колдуны, маги и их защитники из Даларана носят зачарованные кулоны, помогающие сосредотачивать и согласовывать их искусство. Снятые с убитых чародеев талисманы нарушают ритуал и дают Гробнице драгоценное время, чтобы найти главаря, направляющего тайное плетение."}},faq={{q="Почему жрец Тени Алистер выбрал целью Янтарную мельницу?",a="Маги Кирин-Тора, засевшие в Янтарной мельнице, активно направляют мощные тайные энергии. Алистер опасается, что если их заклинание удастся, Отрекшиеся потеряют контроль над Серебряным бором.",al={"why attack ambermill","allister motive","ambermill threat","зачем атаковать янтарную мельницу","мотив алистера","угроза янтарной мельницы"}},{q="Для чего нужны кулоны Даларана?",a="Колдуны, маги и защитники Даларана носят эти кулоны как фокусы для своего искусства. Их изъятие ослабляет усилия чародеев и помогает Алистеру оценить магические успехи Кирин-Тора.",al={"what are dalaran pendants","pendant purpose","why collect pendants","что такое кулоны даларана","назначение кулонов","зачем собирать кулоны"}},{q="Где находится Янтарная мельница?",a="Янтарная мельница лежит среди восточных холмов Серебряного бора. От Гробницы идите на юг по главной дороге и сверните на развилке на восток, к городу.",al={"ambermill location","how to get to ambermill","where is ambermill","янтарная мельница расположение","как добраться до янтарной мельницы","где янтарная мельница"}},{q="Кто такой Далар и какова его роль?",a="Далар — Отрекшийся чародей, живущий в Гробнице рядом с жрецом Тени Алистером; ему поручено выслеживать и раскрывать магические источники, питающие магов Даларана в Янтарной мельнице.",al={"who is dalar","dalar role","dalar silverpine","кто такой далар","роль далара","далар серебряный бор"}},{q="Что происходит после добычи кулонов?",a="Добыча кулонов показывает, что ритуал Даларана уже далеко зашел; им руководит опытный маг, с которым нужно сразиться лично, чтобы полностью остановить колдовство.",al={"what happens next","ambermill investigations follow up","after dalaran pendants","что дальше","продолжение расследования в янтарной мельнице","после кулонов даларана"}},{q="Почему люди Даларана до сих пор в Серебряном бору?",a="До Третьей войны Даларан держал в этой области несколько застав и поселений. Даже после разрушения королевства уцелевшие силы Кирин-Тора продолжают удерживать Янтарную мельницу против Плети и Отрекшихся.",al={"why are dalaran humans here","kirin tor in silverpine","ambermill lore","почему люди даларана здесь","кирин-тор в серебряном бору","предания янтарной мельницы"}}},fp="24,275,22.436.0,20.432.0,50.198.0,39.190.0,27.167.0,37.190.0,43.171.1,50.219.0"}
P.entries["quest:480"] = {n="Ткач",s="«Ткач» — боевое задание, которое выдает жрец Тени Алистер в Гробнице, чтобы остановить магические действия Даларана в Серебряном бору. Верховный маг Даларана Атаэрик руководит попытками вновь пробудить мощный узел энергии силовых линий в этом краю. Убив верховного мага и забрав его посох, Отрекшиеся сорвут оккультные замыслы Даларана и укрепят свою власть над окрестными землями.",h="«Ткач» — боевое задание, которое выдает жрец Тени Алистер в Гробнице, чтобы остановить магические действия...",kw={"allister","ambermill","ataeric","dalaran","kirin tor","ley energy","sepulcher","silverpine","weaver","алистер","янтарная мельница","атаэрик","даларан","кирин-тор","энергия силовых линий","гробница","серебряный бор","ткач"},ang={["class:Mage"]="Управление силовыми линиями требует глубокого владения тайной геометрией; гибель Атаэрика показывает, насколько уязвимы такие хрупкие ритуалы, когда падают их главные проводники.",["class:Priest"]="Жрец Тени Алистер руководит этой операцией не заклинаниями священного исцеления, а холодной решимостью погасить источник тайной силы, пока он не расцвел.",["faction:Horde"]="Остатки Даларана по-прежнему враждебны Орде, поэтому любое расширение их тайной инфраструктуры напрямую угрожает землям Орды на севере Лордерона.",["race:Undead"]="Живые маги Даларана открыто оспаривают власть Отрекшихся над руинами Лордерона. Устранение их верховного мага необходимо, чтобы обезопасить окрестности Гробницы."},sec={{t="Разрыв нити силовой линии",b="После предварительной разведки Янтарной мельницы и действий Даларана в Серебряном бору Отрекшиеся узнали об опасной затее: волшебники пытаются подчинить и вновь пробудить дремлющий узел энергии силовых линий. Если не вмешаться, доступ к столь сосредоточенной тайной силе позволил бы Даларану укрепить свои позиции и угрожать власти Подгорода над югом Лордерона."},{t="Падение верховного мага",b="Жрец Тени Алистер понимает, что для срыва столь масштабного замысла нужно отсечь его голову. Дело направляет верховный маг Атаэрик — грозный чародей, укрывшийся за защитными чарами и другими магами. Его гибель и захват его посоха рассеют собранную магию, вернут энергии силовых линий в дремоту и сорвут планы Кирин-Тора в долине."}},faq={{q="Кто такой Ткач?",a="Ткачом называют верховного мага Атаэрика, могущественного заклинателя Даларана, находящегося в Серебряном бору. Ему поручено сплетать воедино и вновь пробуждать скрытые магические энергии силовых линий под этой местностью.",al={"who is the weaver","archmage ataeric","ataeric weaver","кто такой ткач","верховный маг атаэрик","атаэрик ткач"}},{q="Почему Отрекшиеся хотят убить верховного мага?",a="Если Даларан успешно задействует дремлющий узел энергии силовых линий, его маги получат огромный источник тайной силы прямо у порога Подгорода. Жрец Тени Алистер считает это недопустимой угрозой власти Отрекшихся и приказывает быстро устранить мага, пока узел не заработал в полную силу.",al={"why kill ataeric","forsaken dalaran conflict","why attack dalaran","зачем убивать атаэрика","отрекшиеся и даларан","почему атаковать даларан"}},{q="Что произойдет после победы над Атаэриком?",a="Когда Атаэрик убит, а его посох изъят, магическая сеть рушится. Собранные заклинания рассеиваются, силовая линия вновь засыпает, и Кирин-Тор лишается главного оплота тайной силы на юге Серебряного бора.",al={"after the weaver","quest outcome","what happens to ley node","после ткача","итог задания","что станет с узлом силовых линий"}},{q="Кто выдает это задание?",a="Приказ дает жрец Тени Алистер, представитель власти Отрекшихся в Гробнице в Серебряном бору, изучив прежние сведения о присутствии Даларана возле Янтарной мельницы.",al={"who gives the weaver","allister quest","quest giver weaver","кто выдает ткача","задание алистера","персонаж, выдающий задание ткач"}},{q="Чем важен посох Атаэрика?",a="Посох верховного мага Атаэрика — проводник и средоточие управления энергиями силовых линий края. Его захват гарантирует полный распад магии и дает Алистеру артефакт, который Отрекшиеся смогут изучить для собственных целей.",al={"ataerics staff","archmage staff purpose","why take the staff","посох атаэрика","назначение посоха верховного мага","зачем забирать посох"}},{q="Откуда в Серебряном бору взялось присутствие Даларана?",a="Несмотря на разрушение Даларана в Третьей войне, остатки Кирин-Тора удерживают укрепленные анклавы, форпосты и тайные опыты на соседних землях, например у Янтарной мельницы, пытаясь вернуть контроль и овладеть важными запасами магии.",al={"dalaran in silverpine","why are dalaran mages in silverpine","ambermill dalaran","даларан в серебряном бору","почему маги даларана в серебряном бору","янтарная мельница даларан"}}},fp="10,391,23.407.0,19.392.1,18.211.0,45.312.0,39.235.1,28.201.0,44.256.0,54.258.0"}
P.entries["quest:481"] = {n="Анализ Далара",s="«Анализ Далара» — задание Орды в Серебряном бору, связывающее разведку жреца Тени Алистера против Янтарной мельницы с тайными изысканиями Далара Ткача Рассвета. Найдя в даларанском ящике с припасами подвеску с рунами, герои приносят ее Далару в Гробницу для изучения. Артефакт показывает, что уцелевшие маги Даларана собирают огромную магическую силу для скрытой затеи.",h="«Анализ Далара» — задание Орды в Серебряном бору, связывающее разведку жреца Тени Алистера против Янтарной...",kw={"ambermill","dalar dawnweaver","dalaran","kirin tor","pendant","sepulcher","shadow priest allister","silverpine forest","янтарная мельница","далар ткач рассвета","даларан","кирин-тор","подвеска","гробница","жрец тени алистер","серебряный бор"},ang={["class:Mage"]="Маги-Отрекшиеся узнают в подвеске Кирин-Тора классический проводник даларанского плетения заклинаний — значит, их прежние собратья готовят грандиозное призывание.",["faction:Horde"]="Срыв замыслов Кирин-Тора в Серебряном бору защищает Восточные королевства от возрождающихся магических сил, лояльных Альянсу.",["race:Undead"]="Для Отрекшихся наблюдение за действиями Даларана у Янтарной мельницы важно, чтобы оберегать границы Серебряного бора и защищать Гробницу от вражеского колдовства."},sec={{t="Груз курьера",b="После налета на даларанский ящик с припасами в лагере к северу от Деревни Погребальных Костров жрец Тени Алистер получает подвеску с рунами, найденную под стопкой старых карт. Понимая, что ее чары выходят за пределы его духовного ведения, Алистер отправляет реликвию Далару Ткачу Рассвета, магу-ученому из Гробницы, лучше способному разгадать магические защитные чары Даларана."},{t="Козни Кирин-Тора",b="Изучив подвеску, Далар Ткач Рассвета определяет, что это особый проводник, издавна любимый высокопоставленными волшебниками Кирин-Тора для направления мощных магических энергий. Огромное число таких реликвий, поступающих прямо в укрепленную Янтарную мельницу, говорит о том, что волшебники готовят тайное предприятие великого размаха, и Далар решает заглянуть за их магические защиты, чтобы выяснить истинные намерения."}},faq={{q="Что такое подвеска с рунами?",a="Подвеска — тайный артефакт, которым старшие маги Кирин-Тора безопасно направляют большие объемы магической энергии. Ее обнаружение в пути указывает, что в Янтарную мельницу поставляют мощные накопители для высокоуровневого колдовства.",al={"what is pendant","kirin tor pendant lore","ambermill pendant","что такое подвеска","подвеска кирин-тора","подвеска янтарная мельница"}},{q="Почему жрец Тени Алистер отправляет подвеску Далару Ткачу Рассвета?",a="Жрец Тени Алистер в Гробнице в основном занимается магией тени и сбором сведений для Отрекшихся. Поскольку подвеска — сложная тайная реликвия даларанской работы, ее руны и назначение должен изучить знаток тайной магии, такой как Далар Ткач Рассвета.",al={"why dalar","who is dalar dawnweaver","why send to sepulcher","почему далар","кто такой далар ткач рассвета","почему отправить в гробницу"}},{q="Где находится Янтарная мельница и почему Отрекшиеся следят за ней?",a="Янтарная мельница — укрепленный человеческий город на юго-востоке Серебряного бора, которым управляют маги Даларана. Он расположен в глубине земель, на которые претендует леди Сильвана Ветрокрылая, и представляет для Отрекшихся непосредственную военную и магическую угрозу, поэтому за его границами ведется строгое наблюдение.",al={"why watch ambermill","ambermill wizards","dalaran in silverpine","зачем следить за янтарной мельницей","волшебники янтарной мельницы","даларан в серебряном бору"}},{q="Что произойдет после того, как Далар изучит подвеску?",a="Поняв, что Кирин-Тор копит тайные проводники для крупного предприятия, Далар в следующем задании, «Планы Даларана», своей магией заглядывает сквозь защитные щиты Янтарной мельницы, чтобы выяснить, что именно замышляют волшебники.",al={"what comes next","after dalar's analysis","dalaran intent","что дальше","после анализа далара","планы даларана"}},{q="Где найти Далара Ткача Рассвета?",a="Далар Ткач Рассвета находится внутри склепа в Гробнице — главном оплоте Отрекшихся в Серебряном бору, стоящем у большой дороги.",al={"dalar location","where is dalar","dalar dawnweaver silverpine","где далар","где найти далара","далар ткач рассвета серебряный бор"}},{q="Почему Кирин-Тор действует в Серебряном бору открыто?",a="Янтарная мельница была давним владением Даларана еще до того, как Плеть опустошила Лордерон. Несмотря на падение столицы и самого Даларана, уцелевшие волшебники сохранили Янтарную мельницу как действующий оплот и постоянно сталкиваются с расширением Отрекшихся.",al={"kirin tor silverpine","dalaran presence silverpine","кирин-тор серебряный бор","даларан в серебряном бору"}}},fp="16,423,17.393.0,22.429.1,35.236.0,69.299.0,58.295.0,46.256.1,36.142.0,60.257.0"}
P.entries["quest:4811"] = {n="Красный кристалл",s="Часовой Глинда Нал'Шия из Аубердина поручает путникам проверить слухи о таинственном красном кристалле в восточных горах Темных берегов. Поскольку поблизости множатся враждебные лунные совуха и их, похоже, тянет к этому образованию, Часовые хотят выяснить, существует ли аномалия на самом деле.",h="Часовой Глинда Нал'Шия из Аубердина поручает путникам проверить слухи о таинственном красном кристалле в...",kw={"auberdine","darkshore","glynda nal'shea","moonkin","red crystal","sentinels","аубердин","темные берега","глинда нал'шия","лунные совухи","красный кристалл","часовые"},ang={["class:Druid"]="Друиды тесно связаны духовно с лунными совухами и природным порядком Темных берегов, поэтому губительное или смущающее влияние кристалла — срочная экологическая проблема.",["faction:Alliance"]="Аубердин — главный прибрежный порт Альянса на севере Калимдора; любая неотвратимая угроза, собирающаяся в холмах, может отрезать гавань от глуши.",["race:NightElf"]="Движение лунных совухов — тревожное зрелище для кальдораев, почитающих этих существ как священных стражей Элуны и природы."},sec={{t="Тревожная перемена в глуши",b="Поколениями ночные эльфы Калимдора считали лунных совухов добрыми, таинственными существами, тесно связанными с дикой природой. Но в последние дни агрессивные стаи быстро размножились на склонах к востоку от Аубердина. Хотя некоторые приверженцы традиций по-прежнему почитают лунных совухов, Часовой Глинда Нал'Шия прежде всего заботится о безопасности поселения и не может игнорировать растущую опасность. По слухам, звери стекаются в одно место на восточных вершинах."},{t="Аномалия в восточных горах",b="Разведчики и странники принесли вести о неестественном красном кристалле, торчащем из каменистого склона высоко над Темными берегами. Поскольку на окутанном туманом побережье слухи расходятся легко, Глинда ищет тех, кто проверит все на месте и отделит вымысел от правды. Найденный багровый монолит подтверждает, что аномалия реальна, и Часовым остается гадать, почему местных лунных совухов необъяснимо тянет к нему и не означает ли его присутствие зловещего влияния на землю."}},faq={{q="Что такое красный кристалл на Темных берегах?",a="Это загадочное светящееся багровое образование в восточной горной гряде над Темными берегами. Поначалу Часовые почти ничего не знали о его происхождении — лишь то, что местных животных, особенно лунных совухов, непреодолимо влечет к нему.",al={"what is red crystal","darkshore crystal","red rock auberdine","что такое красный кристалл","кристалл темных берегов","красный камень аубердин"}},{q="Кто посылает искать красный кристалл?",a="Задание дает Часовой Глинда Нал'Шия, находящаяся в Аубердине. Она отвечает за защиту поселения и хочет лично убедиться в слухах о восточных горах.",al={"who gives the red crystal quest","glynda nalshea quest","auberdine crystal quest giver","кто выдает задание красный кристалл","задание глинды нал'шии","персонаж, выдающий задание кристалл аубердин"}},{q="Почему лунные совухи агрессивны возле кристалла?",a="Лунные совухи, которых прежде считали добрыми и таинственными существами, стали территориальными и непредсказуемыми. Часовой Глинда Нал'Шия подозревает, что внезапная перемена в поведении и рост числа связаны с силой, исходящей от таинственного красного кристалла.",al={"why are moonkin mad","angry moonkin darkshore","moonkin hostile","почему лунные совухи злые","злые лунные совухи темные берега","лунные совухи враждебны"}},{q="Где находится красный кристалл?",a="Кристалл лежит строго к востоку от Аубердина, высоко на неприступном восточном горном хребте Темных берегов, среди рыскающих лунных совухов.",al={"where to find red crystal","red crystal location","darkshore red crystal map","где найти красный кристалл","расположение красного кристалла","карта красного кристалла темные берега"}},{q="Считают ли ночные эльфы кристалл опасным?",a="Часовой Глинда Нал'Шия крайне осторожна. Хотя неясно, безвреден камень или зловещ, то, что он будоражит и собирает диких зверей, вызывает у Аубердина непосредственную тревогу за безопасность.",al={"is the crystal bad","is red crystal evil","опасен ли кристалл","красный кристалл зло"}},{q="Что происходит после обнаружения кристалла?",a="Сообщение Глинде о находке подтверждает слухи. Она сразу стремится выяснить его истинную природу, что приводит к попыткам очистить его и взять образец с помощью воды из лунного колодца Аубердина.",al={"what is after red crystal","as water cascades follow up","что после красного кристалла","продолжение задания с водой"}}},fp="15,295,31.466.0,28.464.0,37.253.0,42.200.0,57.260.0,33.141.0,55.204.0,44.197.1"}
P.entries["quest:4812"] = {n="Пока струится вода...",s="«Пока струится вода...» — задание Альянса в Темных берегах, в котором игроки проверяют природу загадочного красного кристалла, торчащего из восточной горной стены. Поливая его поверхность священной водой из лунного колодца Аубердина, игроки пытаются пробить его непрозрачную оболочку и выяснить, откуда он взялся.",h="«Пока струится вода...» — задание Альянса в Темных берегах, в котором игроки проверяют природу загадочного...",kw={"as water cascades","auberdine","darkshore","empty water tube","felwood","glynda nal'shea","moonwell","red crystal","пока струится вода","аубердин","темные берега","пустая пробирка","оскверненный лес","глинда нал'шия","лунный колодец","красный кристалл"},ang={["class:Druid"]="Друиды, оберегающие хрупкую экосистему Темных берегов, естественно с подозрением относятся к неестественным чужеродным образованиям, особенно на хребте под оскверненным Оскверненным лесом.",["faction:Alliance"]="Разведчики Альянса в Аубердине должны охранять побережье от надвигающейся скверны, ползущей с восточного нагорья.",["race:NightElf"]="Для кальдораев лунные колодцы — священные источники жизни и утешения. Использование их освященных вод как средства откровения показывает, насколько милость Элуны важна для борьбы с угрозами на их границах."},sec={{t="Очищение неведомого",b="После того как красный кристалл впервые замечен высоко на восточных утесах Темных берегов, Часовой Глинда Нал'Шия придумывает, как безопасно изучить его состав. Вода лунных колодцев несет мощную священную и исцеляющую магию, благословленную преданностью ночных эльфов Элуне. Глинда полагает, что если облить чуждый монолит водой из лунного колодца в Аубердине, начнется реакция, которая прорежет его странную непрозрачную оболочку, не разрушив ее полностью."},{t="Тень Оскверненного леса",b="Беспокойство Нал'Шия во многом связано с географией. Восточный хребет Темных берегов нависает под оскверненными возвышенностями Оскверненного леса, леса, искаженного демонической энергией во время Третьей войны. Если красный шпиль связан со скверной Оскверненного леса, обращаться с ним крайне опасно. Когда священная вода стекает по граням кристалла, гудящий камень ненадолго становится прозрачным — похоже, то, что заключено внутри, требует более пристального изучения."}},faq={{q="Где взять воду для этого задания?",a="Воду нужно набрать из лунного колодца в поселении ночных эльфов Аубердин с помощью пустого флакона, который выдает Часовой Глинда Нал'Шия.",al={"where is the moonwell","moonwell water location","fill empty water tube","где лунный колодец","где взять воду из лунного колодца","наполнить пустую пробирку"}},{q="Почему вода лунного колодца действует на кристалл?",a="Лунные колодцы хранят освященную, насыщенную магией воду, благословленную Элуной. Часовой Глинда Нал'Шия предполагает, что ее очищающая сила вступит в реакцию с чужеродной энергией камня и раскроет его скрытый состав.",al={"why moonwell water","moonwell magic on crystal","почему вода лунного колодца","магия лунного колодца на кристалл"}},{q="Где находится красный кристалл?",a="Загадочный красный кристалл находится у восточной горной стены Темных берегов, среди скалистых предгорий, отделяющих побережье от нагорья наверху.",al={"red crystal location","where is the crystal","red crystal darkshore","где красный кристалл","где кристалл","красный кристалл темные берега"}},{q="Почему Часовую Глинду беспокоит Оскверненный лес?",a="Оскверненный лес лежит прямо к востоку и выше Темных берегов и опустошен демонической скверной после Третьей войны. Поскольку кристалл появился около пограничного хребта, Глинда опасается, что у него то же мерзкое демоническое происхождение.",al={"glynda felwood","connection to felwood","глинда оскверненный лес","связь с оскверненным лесом"}},{q="Что произойдет, если полить кристалл водой?",a="Glynda expects the potent moonwell water to reveal a clue about the crystal's composition. Its reaction is discovered when you pour the water over it.",al={"pouring water result","what happens to the crystal","результат полива водой","что будет с кристаллом"}},{q="Кто выдает задание «Пока струится вода...»?",a="Задание выдает Часовой Глинда Нал'Шия в Аубердине сразу после разведывательного задания «Красный кристалл».",al={"quest giver","who starts as water cascades","кто выдает задание","кто начинает пока струится вода"}}},fp="17,295,21.453.0,21.441.1,40.150.0,43.212.0,33.153.0,45.204.0,52.150.1,38.127.0"}
P.entries["quest:4813"] = {n="Скрытые фрагменты",s="«Скрытые фрагменты» — завершающее задание в расследовании тайны красного кристалла, торчащего из утесов к востоку от Аубердина. Вооружившись очищенной водой из лунного колодца, вы возвращаетесь на место, чтобы осмотреть, что скрыто внутри странного образования, и доложить Часовому Глинде Нал'Шия.",h="«Скрытые фрагменты» — завершающее задание в расследовании тайны красного кристалла, торчащего из утесов к...",kw={"auberdine","bone fragments","darkshore","glynda nal'shea","jawbone","moonwell water","mysterious red crystal","аубердин","костные фрагменты","челюсть","темные берега","глинда нал'шия","вода лунного колодца","загадочный красный кристалл"},ang={["class:Druid"]="Загадочный минерал противостоит и естественному износу, и высокой магии, оставаясь любопытной аномалией на фоне привычного равновесия природы.",["race:NightElf"]="Обнаружение костей гуманоидов в странном кристалле у горных границ Ясеневого леса и Оскверненного леса требует от Часовых, охраняющих Темные берега, особой бдительности."},sec={{t="Мрачное открытие",b="Благословенная вода лунного колодца смывает мутность с багрового кристалла и обнажает то, что заключено под его гладкой поверхностью. Внутри плотного минерала застыли несколько мелких костных фрагментов и половина челюсти гуманоида. Камень, скрывающий их, необычайно прочен — даже мощные заклинания с трудом раскололи бы его. Что бы ни породило эти останки, они сохранились в жуткой изоляции над побережьем Темных берегов."},{t="Доклад в Аубердине",b="Когда вы возвращаетесь в Аубердин, Часовой Глинда Нал'Шия принимает к сведению ваше тревожное открытие. Вместо окончательных ответов оно лишь вызывает у местных ночных эльфов новые опасения. Глинда обещает представить находки городскому совету, но утешается тем, что странный кристалл расположен высоко на восточных утесах, достаточно далеко от города, и не представляет непосредственной опасности для жителей."}},faq={{q="Что заключено внутри красного кристалла?",a="Если омыть кристалл освященной водой из лунного колодца, он становится достаточно прозрачным, чтобы разглядеть глубоко внутри несколько костных фрагментов и половину челюсти гуманоида.",al={"what is in the crystal","what are the fragments","what bones are inside","что внутри кристалла","что за фрагменты","какие кости внутри"}},{q="Можно ли расколоть кристалл, чтобы осмотреть кости?",a="Нет. Кристалл исключительно прочен. Даже сильнейшие виды магии едва ли смогут разрушить его структуру, поэтому происхождение костей остается загадкой.",al={"can you break the crystal","opening the red crystal","можно ли разбить кристалл","открыть красный кристалл"}},{q="Кому вы докладываете о находках?",a="О своих находках вы докладываете Часовому Глинде Нал'Шия, которая находится в портовом городе Аубердин.",al={"who turns in the fragments within","quest turn in","glynda nalshea","кому сдавать скрытые фрагменты","сдать задание","глинда налшия"}},{q="Что Часовые собираются делать с кристаллом?",a="Часовой Глинда Нал'Шия планирует сообщить совету в Аубердине, чтобы тот обсудил возможные действия. Однако, поскольку кристалл находится высоко на восточных утесах, его не считают срочной угрозой.",al={"what happens next with the crystal","auberdine council crystal","что дальше с кристаллом","совет аубердина кристалл"}}},fp="20,303,17.492.1,22.437.0,39.162.1,52.189.1,34.101.0,45.211.1"}
P.entries["quest:482"] = {n="Планы Даларана",s="«Планы Даларана» — задание Серебряного бора, которое Далар Ткач Рассвета поручает жрецу Тени Алистеру. Изучив амулет с рунами, предназначенный для Кирин-Тора в Янтарной мельнице, Далар понимает, что волшебники намерены задействовать спящий узел энергии силовых линий под поселением, и руководство Отрекшихся в Гробнице планирует контрнаступление.",h="«Планы Даларана» — задание Серебряного бора, которое Далар Ткач Рассвета поручает жрецу Тени Алистеру.",kw={"ambermill","dalar dawnweaver","dalaran's intentions","kirin tor","ley energy","sepulcher","shadow priest allister","silverpine forest","янтарная мельница","далар ткач рассвета","планы даларана","кирин-тор","энергия силовых линий","гробница","жрец тени алистер","серебряный бор"},ang={["class:Mage"]="Маги Отрекшихся узнают методы Кирин-Тора: использование спящих силовых линий — эффективный способ создать мощный чародейский плацдарм без перевозки громоздких источников силы через глушь.",["class:Priest"]="Жрец Тени Алистер руководит обороной Отрекшихся в Гробнице, сочетая холодный военный прагматизм с темными учениями культа Забытой Тени для уничтожения живых угроз.",["race:Undead"]="Присутствие Даларана так глубоко в Серебряном бору — прямая угроза границам Отрекшихся; срыв ритуала с силовыми линиями защищает дороги между Тирисфалем и южными границами."},sec={{t="Спящая искра",b="Изучая амулет с рунами, найденный в ящике с припасами Даларана, Далар Ткач Рассвета вспоминает старое исследование Кирин-Тора. Янтарную мельницу маги выбрали не случайно: тихая деревня стоит прямо над спящим узлом энергии силовых линий. Для пробуждения такого подземного средоточия нужны огромные запасы магии, а зачарованные амулеты волшебников служат ключевыми элементами для направления и усиления этой силы."},{t="Угроза Серебряному бору",b="Отрекшиеся не могут терпеть укрепленный, питаемый силой форпост Кирин-Тора, угрожающий южным подступам к Гробнице и Тирисфальским лесам. Какой бы великий ритуал ни готовили маги, использование необузданных силовых линий дало бы Даларану огромное стратегическое преимущество в Лордероне. Далар срочно отправляет весть жрецу Тени Алистеру, чтобы выработать план, который задержит волшебников до завершения ритуала."}},faq={{q="Что Кирин-Тор пытается сделать в Янтарной мельнице?",a="Волшебники Даларана пытаются вновь пробудить спящий узел энергии силовых линий под Янтарной мельницей. Подключение к этой магической жиле дало бы им огромную силу, чтобы закрепиться здесь навсегда и осуществить более широкие планы в Серебряном бору.",al={"ambermill ley line","what are dalaran wizards doing in silverpine","ambermill purpose","силовая линия янтарная мельница","что делают маги даларана в серебряном бору","цель в янтарной мельнице"}},{q="Почему Далар отправляет вас к жрецу Тени Алистеру?",a="Жрец Тени Алистер — высокопоставленный военный и духовный предводитель Отрекшихся, расположившихся в Гробнице. Далар Ткач Рассвета предоставляет тайные знания и исследования, но тактические решения и наступательные меры против Даларана находятся в ведении Алистера.",al={"why tell allister","who is allister","dalar dawnweaver allister","почему говорить алистеру","кто такой алистер","далар ткач рассвета алистер"}},{q="Как амулеты волшебников связаны с их планами?",a="Пробуждение спящего узла силовых линий требует огромных запасов энергии. Волшебники Даларана носят зачарованные амулеты, которые служат проводниками и хранилищами этой магии. Если лишить магов этих амулетов, им будет труднее завершить активацию.",al={"kirin tor pendants","ambermill pendants","why collect pendants","амулеты кирин-тора","амулеты янтарной мельницы","зачем собирать амулеты"}}},fp="20,349,15.431.0,24.437.0,48.251.0,50.271.0,50.253.0"}
P.entries["quest:4821"] = {n="Странное яйцо",s="Среди тауренов Заставы Вольного Ветра ходят слухи о странном чужеродном яйце, которое яростно охраняют дикие змеи на дне каньона. Хагар Грозовое Копыто поручает авантюристам Орды найти и доставить образец, пока то, что скрыто внутри, не вырвалось на свободу.",h="Среди тауренов Заставы Вольного Ветра ходят слухи о странном чужеродном яйце, которое яростно охраняют дикие...",kw={"alien egg","arikara","freewind post","hagar lightninghoof","serpent den","serpent wild","serpents","thousand needles","странное яйцо","арикара","застава вольного ветра","хагар грозовое копыто","змеиное логово","змеиная дикость","змеи","тысяча игл"},ang={["class:Hunter"]="Охотники, знающие зверей Калимдора, сразу поймут, что гнезда выводка в каньоне скрывают нечто куда более древнее, чем обычные пустынные змеи.",["faction:Horde"]="Застава Вольного Ветра — главный форпост Орды в Тысяче Игл, поэтому сдерживание появляющихся верховных хищников — важная задача для защиты линий снабжения.",["race:Tauren"]="Живя над дном каньона на Заставе Вольного Ветра, таурены полагаются на понимание хрупкого равновесия местной фауны; чужеродный или неестественный змеиный выводок напрямую нарушает их дом."},sec={{t="Странное гнездо",b="На Заставу Вольного Ветра дошла весть о необычном яйце, замеченном в глубине змеиных логовищ, разбросанных по дну каньона под высокими каменными иглами. Местные змеи стерегут яйцо как собственный выводок и нападают на каждого путника, подошедшего слишком близко. Заинтригованный и обеспокоенный угрозой местным охотничьим угодьям, Хагар Грозовое Копыто просит отважных разведчиков найти кладку, обойти скользких часовых и добыть диковину для изучения."},{t="Пробуждение детеныша",b="Внимательно осмотрев добытое яйцо, Хагар обнаруживает нечто большее, чем обычную кладку рептилий. Скорлупа трескается сразу при прикосновении, и на свет появляется крылатое детеныш-чудовище, известное как молодой арикара. Вместо нападения новорожденное создание взмывает в небо, покидая деревянные помосты Заставы Вольного Ветра, — знак того, что в ветрах каньона пробуждаются куда более древние силы."}},faq={{q="Где найти Странное яйцо?",a="Яйцо лежит в одном из нескольких змеиных гнезд у подножий утесов Тысячи Игл, особенно к югу и северо-востоку от Заставы Вольного Ветра. Оно находится прямо на дне каньона в окружении враждебных местных змей.",al={"alien egg location","where is alien egg","egg spawn thousand needles","где странное яйцо","где найти странное яйцо","яйцо тысяча игл"}},{q="Почему местные змеи охраняют его?",a="Хотя яйцо принадлежит особому летающему змею, известному как арикара, обычные змеи каньона инстинктивно защищают его как часть собственной кладки и яростно оберегают гнездо от любопытных чужаков.",al={"why do serpents protect the egg","serpent behavior alien egg","почему змеи защищают яйцо","поведение змей странное яйцо"}},{q="Кто такой Хагар Грозовое Копыто?",a="Хагар Грозовое Копыто — таурен-разведчик и страж, находящийся высоко на Заставе Вольного Ветра в Тысяче Игл. Он следит за необычными перемещениями и угрозами природе на дне каньона и координирует усилия Орды по усмирению местных зверей.",al={"hagar lightninghoof lore","who is quest giver hagar","хагар грозовое копыто предания","кто такой хагар"}},{q="Что произойдет, если доставить яйцо?",a="Когда Хагар начинает осматривать яйцо, оно трескается, и из него появляется молодой арикара. Крылатый змей ненадолго пугает Хагара, затем взлетает и скрывается в небесах Тысячи Игл.",al={"what hatches from alien egg","what is inside the egg","кто вылупляется из странного яйца","что внутри яйца"}},{q="К чему приводит это задание?",a="Доставка яйца начинает цепочку Арикары и сразу ведет к заданию «Змеиная дикость», в котором Хагар стремится понять природу странных крылатых змей, поднимающихся в каньоне.",al={"next quest after alien egg","arikara chain next step","следующее задание после странного яйца","следующий шаг цепочки арикары"}},{q="Яйцо действительно из космоса?",a="В этом контексте «странное» означает нечто совершенно чужеродное, неестественное и незнакомое для местной экологии Тысячи Игл, а не существо, прилетевшее со звезд. Оно принадлежит легендарному ветряному змею Арикаре.",al={"is alien egg extraterrestrial","is egg alien","странное яйцо инопланетное","яйцо пришельца"}}},fp="9,260,14.474.0,21.400.1,33.237.0,39.227.1,27.240.0,38.191.1,29.189.1,38.216.1"}
P.entries["quest:483"] = {n="Реликвии Пробуждения",s="«Реликвии Пробуждения» — срочное спасательное задание: нужно спасти Друидов Когтя, спящих в Обители Бен'этиль. Оскверненные фурболги из племени Скрюченной Сосны захватили священные курганы и угрожают спящим друидам, чьи души блуждают в Изумрудном Сне. Без этих четырех ритуальных предметов спящих нельзя безопасно вернуть в мир яви.",h="«Реликвии Пробуждения» — срочное спасательное задание: нужно спасти Друидов Когтя, спящих в Обители Бен'этиль.",kw={"athridas bearmantle","ban'ethil barrow den","black feather quill","dolanaar","druids of the talon","emerald dream","gnarlpine","raven claw talisman","relics of wakening","rune of nesting","sapphire of sky","атридас медвежья шкура","обитель бен'этиль","черное перо","доланаар","друиды когтя","изумрудный сон","скрюченная сосна","талисман когтя ворона","реликвии пробуждения","руна размещения","небесный сапфир"},ang={["class:Druid"]="Для молодых друидов нападение на Бен'этиль — прямой удар по их братьям по Кенарию. Добыв реликвии, вы исполните долг по сохранению священного моста между смертной землей и Изумрудным Сном.",["race:NightElf"]="Осквернение курганной обители на ветвях самого Тельдрассила показывает, как быстро порча искажает племя Скрюченной Сосны и тревожит равновесие вашего нового дома."},sec={{t="Оскверненное святилище",b="Курганные обители — уединенные святилища, где друиды-ночные эльфы погружаются в глубокую спячку, пока странствуют по Изумрудному Сну. К западу от Доланаара извилистые коридоры Обители Бен'этиль захвачены роем оскверненных фурболгов из племени Скрюченной Сосны. Обезумев от мерзкой порчи, расползающейся по Тельдрассилу, бывшие союзники осквернили святилище и угрожают беззащитным спящим, которые даже не подозревают об опасности для их физических тел."},{t="Орудия возвращения",b="Друида, вошедшего в Сон, нельзя просто разбудить: резкое пробуждение без надлежащего духовного якоря может разрушить его разум или навсегда оставить дух в плену Сна. Чтобы провести тонкий обряд пробуждения, Атридасу Медвежьей Шкуре нужны четыре священные реликвии, запечатанные в сундуках по всей обители: Талисман Когтя Ворона, Черное перо, Небесный сапфир и Руна Размещения. Их возвращение — единственная надежда пробудить Друидов Когтя, прежде чем фурболги Скрюченной Сосны убьют или похитят их."}},faq={{q="Почему нельзя просто разбудить друидов?",a="Спячка друидов — очень тонкий транс, связывающий смертную оболочку с Изумрудным Сном. Если разбудить их неправильно или без защитных обрядов Реликвий Пробуждения, их сознание может навсегда остаться в Сне, отрезанное от физического тела.",al={"why need relics to wake druids","why wake ritual","why are relics necessary","зачем реликвии для пробуждения друидов","зачем ритуал пробуждения","почему нужны реликвии"}},{q="Кто такие Друиды Когтя?",a="Это друиды-ночные эльфы, обладающие силами Авианы: они могут принимать облик бурых воронов и повелевать ветрами. Многие из них погрузились в глубокое созерцание в курганных обителях Тельдрассила, чтобы общаться с духами природы и исцелять юное древо.",al={"druids of the talon","talon druids","who sleeps in ban'ethil","друиды когтя","кто спит в бен'этиль"}},{q="Почему фурболги Скрюченной Сосны нападают на курганную обитель?",a="Племя Скрюченной Сосны стало жертвой темной порчи, которая неуклонно отравляет животных и леса Тельдрассила. Некогда мирные соседи ночных эльфов, они лишились рассудка и стали жестокими, нападая на древние святилища вроде Бен'этиль.",al={"why are furbolgs in the barrow den","gnarlpine attacks","why furbolgs aggressive","почему фурболги в обители","нападения скрюченной сосны","почему фурболги агрессивны"}},{q="Какие четыре реликвии нужно вернуть?",a="Атридас Медвежья Шкура поручает искателям приключений собрать Талисман Когтя Ворона, Черное перо, Небесный сапфир и Руну Размещения, каждый из которых хранится в священном сундуке в Обители Бен'этиль.",al={"which relics","relics needed","names of relics","какие реликвии","нужные реликвии","названия реликвий"}},{q="Кто такой Атридас Медвежья Шкура?",a="Атридас — ночной эльф, живущий в Доланааре. Он следит за духовным здоровьем окрестных земель и организует борьбу с внезапной порчей, поразившей фурболгов Скрюченной Сосны и курганные обители.",al={"athridas bearmantle","quest giver dolanaar","атридас медвежья шкура","персонаж, выдающий задания, доланаар"}},{q="Где находится Обитель Бен'этиль?",a="Обитель Бен'этиль выкопана в холмах прямо к западу от поселения Доланаар на ветвях Тельдрассила.",al={"ban'ethil location","where is banethil","where is the den","где бен'этиль","расположение бен'этиль","где обитель"}}},fp="22,369,17.479.0,19.520.0,42.283.0,32.253.0,56.265.0,41.207.0,27.214.0,38.120.0"}
P.entries["quest:484"] = {n="Шкуры молодых кроколисков",s="Джеймс Халлоран, известный кожевник из Гавани Менетилов, нанимает путников добывать свежие шкуры молодых кроколисков из болот. Его выделанные кожи пользуются спросом у мореходов разных стран, поэтому надежная охота необходима для его дела. Доставка этого мягкого материала завоевывает его доверие и открывает путь к другим кожевенным поручениям.",h="Джеймс Халлоран, известный кожевник из Гавани Менетилов, нанимает путников добывать свежие шкуры молодых...",kw={"crocolisk","einar","james halloran","leather","menethil harbor","skins","tanning","wetlands","кроколиск","эйнар","джеймс халлоран","кожа","гавань менетилов","шкуры","кожевничество","болотина"},ang={["class:Hunter"]="Для охотников, проходящих через Болотину, просьба Халлорана — обычная полевая работа: снять чистые шкуры с местных хищников, не испортив кожу.",["faction:Alliance"]="Поддержка морской торговли Гавани Менетилов обеспечивает бесперебойную работу важных линий снабжения и экспорта через Великое море."},sec={{t="Экспорт гавани",b="Гавань Менетилов — важный морской узел, связывающий Восточные королевства с дальними континентами, но здесь также процветает местная торговля, основанная на ресурсах окрестных болот. Джеймс Халлоран наладил международную торговлю, выделывая прочные шкуры многочисленных местных рептилий-хищников. Купцы и корабли, уходящие из Менетила, везут кожаные изделия Халлорана в дальние порты, и его мастерской приходится постоянно поддерживать запас."},{t="Охота на молодых болотных хищников",b="Опытные охотники вроде Эйнара регулярно поставляют шкуры взрослых животных, но для особых предметов роскоши нужна кожа куда мягче, чем у взрослых болотных кроколисков. Чтобы восполнить нехватку, Халлоран полагается на странствующих искателей приключений, которые заходят в мелкие топи у палисада Менетила. Добыча целых шкур молодых зверей требует аккуратной охоты, чтобы они выдержали тщательную выделку Халлорана."}},faq={{q="Кто такой Джеймс Халлоран?",a="Джеймс Халлоран — мастер-кожевник из Гавани Менетилов. Его выделанные шкуры кроколисков славятся по всему миру и регулярно отправляются через Великое море в чужие порты.",al={"james halloran lore","who is the tanner","halloran menethil","джеймс халлоран","кто кожевник","халлоран менетил"}},{q="Почему Халлорану нужны именно шкуры молодых кроколисков?",a="Взрослые кроколиски дают прочную, плотную кожу для доспехов, а у молодых шкуры гораздо мягче и податливее. Эти нежные шкуры необходимы для некоторых предметов роскоши и тонкой кожевенной работы, для которой шкуры взрослых слишком жестки.",al={"why young crocs","softer skins","crocolisk hides use","зачем молодые кроколиски","мягкие шкуры","применение шкур кроколисков"}},{q="Кто такой Эйнар?",a="Эйнар — местный охотник в Болотине, работающий напрямую с Джеймсом Халлораном. Он регулярно ходит в болота, чтобы истреблять диких кроколисков и снабжать мастерскую в гавани сырыми шкурами.",al={"einar wetlands","hunter einar","einar lore","эйнар болотина","охотник эйнар","эйнар"}},{q="Где водятся эти молодые кроколиски?",a="Молодые кроколиски обитают в водоемах, камышах и болотистых мелководьях вокруг Гавани Менетилов, сразу за городскими воротами и причалами.",al={"croc locations","where are the young crocs","wetlands young crocs","где кроколиски","где молодые кроколиски","молодые кроколиски болотина"}},{q="Что будет после того, как отнести шкуры Халлорану?",a="Впечатленный качеством шкур, Халлоран сразу просит помочь с другими делами в его кожевенной мастерской, поручая обычную работу подмастерья, чтобы дело не стояло.",al={"quest followup","next quest after young crocolisk skins","halloran next task","следующее задание","продолжение после шкур молодых кроколисков","следующее задание халлорана"}},{q="Почему кожа кроколиска ценится в Гавани Менетилов?",a="Гавань Менетилов — оживленный торговый порт, связывающий Стальгорн и Штормград с заморскими землями вроде Калимдора. Необычные водонепроницаемые болотные шкуры, выделанные умелыми мастерами, высоко ценятся купцами и моряками, заходящими в город.",al={"menethil leather trade","crocolisk skin value","торговля кожей менетил","цена шкур кроколисков"}}},fp="21,342,17.508.0,31.463.0,22.181.0,58.246.0,13.196.0,39.145.0,50.201.0,53.240.0"}
P.entries["quest:4841"] = {n="Упокоение кентавров",s="«Упокоение кентавров» — карательное задание, которое выдает Дозорный утесов Долгорог на Заставе Вольного Ветра. Чтобы устранить угрозу, собирающуюся под скалами каньона, воины Орды наносят удар в самое сердце лагерей кентавров Галак на Утесе Треснувшего Копыта.",h="«Упокоение кентавров» — карательное задание, которое выдает Дозорный утесов Долгорог на Заставе Вольного...",kw={"cliffwatcher longhorn","freewind post","galak scout","galak windchaser","galak wrangler","pacify the centaur","splithoof crag","thousand needles","дозорный утесов долгорог","застава вольного ветра","разведчик галак","ветроход галак","укротитель галак","упокоение кентавров","утес треснувшего копыта","тысяча игл"},ang={["faction:Horde"]="Застава Вольного Ветра — важнейшая линия жизни Орды, связывающая Южные степи и сверкающие соляные равнины Великого Подъемника. Агрессивные кентавры под ее башнями угрожают каждому каравану в этой местности.",["race:Tauren"]="Для шу'хало вид лагерей кентавров, подступающих к поселению, пробуждает память о многовековой резне. Проредить Галак — вопрос чистого культурного выживания."},sec={{t="Угроза на дне каньона",b="Застава Вольного Ветра, стоящая на опасной пустынной мезе, дает тауренам господствующий обзор дна каньона Тысячи Игл. Но на высоте мало покоя, когда враги собираются прямо под канатами и подъемниками. Кентавры Галак разбили обширный военный лагерь прямо к северу, у стены каньона, на Утесе Треснувшего Копыта, и напрямую угрожают линиям снабжения и передвижению тауренов по Тысяче Игл."},{t="Возмездие и кровопролитие",b="Чтобы отразить растущую опасность, Дозорный утесов Долгорог посылает способных путников Орды беспощадно проредить ряды Галак. Таурены считают, что мало просто защищать подъемники: чтобы обезопасить Заставу Вольного Ветра, нужно сломить авангард кентавров в их собственном лагере. Уничтожение разведчиков, укротителей зверей и мистиков-ветроходов должно ослабить любой согласованный штурм заставы еще до его начала."}},faq={{q="Кто дает задание «Упокоение кентавров»?",a="Задание дает Дозорный утесов Долгорог на Заставе Вольного Ветра в Тысяче Игл. Он один из главных защитников заставы и следит за опасностями, таящимися в окрестных соляных равнинах и каньонах.",al={"quest giver","who starts pacify the centaur","cliffwatcher longhorn","персонаж, выдающий задания","кто начинает упокоение кентавров","дозорный утесов долгорог"}},{q="Где находятся кентавры Галак?",a="Кентавры Галак разбили лагерь прямо к северу от Заставы Вольного Ветра, у северной стены каньона Тысячи Игл, в местности под названием Утес Треснувшего Копыта.",al={"galak camp location","where is splithoof crag","centaur location","лагерь галак","где утес треснувшего копыта","где кентавры"}},{q="Почему таурены хотят убить кентавров?",a="Кентавры давно ведут жестокую, истребительную войну против кочевых тауренов по всему центральному Калимдору. Поскольку клан Галак разбил передовой лагерь у подножия Заставы Вольного Ветра, Дозорный утесов Долгорог требует скорого возмездия ради безопасности пустынного оплота Орды.",al={"why kill centaur","tauren centaur conflict","why revenge","зачем убивать кентавров","конфликт тауренов и кентавров","почему месть"}},{q="Каких кентавров нужно убить?",a="В задании нужно выследить в лагере на Утесе Треснувшего Копыта двенадцать разведчиков Галак, десять укротителей Галак и шесть ветроходов Галак.",al={"galak targets","which centaur to kill","quest objectives","цели галак","каких кентавров убить","цели задания"}},{q="Что будет после выполнения задания «Упокоение кентавров»?",a="Когда ряды Галак поредеют, Дозорный утесов Долгорог переключается на другие угрозы в регионе и направляет вас в следующее задание — «Наблюдение за Зловещим Тотемом».",al={"next quest","what follows pacify the centaur","quest chain after centaur","следующее задание","что после упокоения кентавров","цепочка заданий после кентавров"}},{q="Какое задание нужно выполнить перед этим?",a="Задание открывается после доставки «Письмо на Заставу Вольного Ветра», которое велит путникам доложить напрямую Дозорному утесов Долгорогу.",al={"prereq","previous quest","how to unlock pacify the centaur","предыдущее задание","как открыть упокоение кентавров","требования"}}},fp="18,257,28.442.0,25.431.0,39.201.0,36.159.0,42.290.0,39.146.0,47.165.0,43.144.0"}
P.entries["quest:486"] = {n="Урсал Изверг",s="Урсал Изверг — венец усилий Атридаса Медвежьей Шкуры по пробуждению спящих Друидов Когтя в Тельдрассиле. Чтобы разорвать неестественный сон, сковавший собратьев в Могильном логове, необходимо убить испорченного вождя фурболгов, нарушившего их призвание.",h="Урсал Изверг — венец усилий Атридаса Медвежьей Шкуры по пробуждению спящих Друидов Когтя в Тельдрассиле.",kw={"athridas","ban'ethil","bearmantle","cleft","druid","furbolg","gnarlpine","mauler","talon","teldrassil","ursal","атридас","бан'этил","медвежья шкура","расселина","друид","фурболг","сосновые лапы","изверг","коготь","тельдрассил","урсал"},ang={["class:Druid"]="Хранить священные обряды Изумрудного Сна крайне важно. Вмешательство Урсала в дела Друидов Когтя — тяжкое осквернение общения в духе Кенария.",["faction:Alliance"]="Защита внутренних дорог Тельдрассила и возрождение круга друидов укрепляют оплот ночных эльфов по мере их вхождения в состав Альянса.",["race:NightElf"]="Фурболги Сосновых Лап некогда были древними союзниками кальдораев. Убить их обезумевшего вожака Урсала — печальная необходимость ради защиты ваших сородичей и спящих друидов."},sec={{t="Сон, ставший кошмаром",b="Друиды Когтя уединились в Могильном логове Бан'этил, чтобы уснуть и общаться с Изумрудным Сном. Однако их мирный транс превратился в неразрывную тюрьму. Атридас Медвежья Шкура установил, что виновники — фурболги Сосновых Лап, и в особенности их свирепый вождь Урсал Изверг: он вмешался в священный обряд друидов и оставил их в ловушке между явью и Сном."},{t="Логово в Расселине",b="Сбор Реликвий Пробуждения был лишь половиной борьбы. Чтобы обряд Атридаса пробил духовный туман, сковавший друидов, источник помех следовало уничтожить. Урсал Изверг устроил логово в глубине Расселины — просевшего, оскверненного ущелья к северу от главной дороги через Тельдрассил. Гибель вождя фурболгов ослабляет его власть над разумом спящих."},{t="Признак более глубокой гнили",b="Смерть Урсала позволяет Атридасу провести обряд и спасти Друидов Когтя, но не излечивает недуг Тельдрассила. Как отмечает Атридас, когда вы возвращаетесь, свирепый фурболг лишь подчинялся более темной порче, расползающейся по ветвям Мирового Древа. Поражение Урсала освобождает спящих, но первопричина безумия, отравляющего племя Сосновых Лап, по-прежнему таится во тьме."}},faq={{q="Кто такой Урсал Изверг?",a="Урсал Изверг — свирепый испорченный вождь фурболгов Сосновых Лап, обитающий в Расселине в Тельдрассиле. Он вмешался в грезы Друидов Когтя и запер их в сне в Могильном логове.",al={"who is ursal","ursal lore","who is the boss in the cleft","кто такой урсал","урсал предания","кто босс в расселине"}},{q="Почему нужно убить Урсала, чтобы пробудить друидов?",a="Даже со священными Реликвиями Пробуждения обряд Атридаса Медвежьей Шкуры не подействует, пока Урсал жив. Его мерзкое вмешательство служит постоянным духовным якорем и не дает душам друидов вернуться в тела.",al={"why kill ursal","why does ursal need to die","relilcs of wakening purpose","зачем убивать урсала","почему урсал должен умереть","реликвии пробуждения зачем"}},{q="Где найти Урсала Изверга?",a="Урсал обитает в Расселине — заросшем овраге к северо-западу от Доланаара, ответвляющемся к северу от дороги в Дарнасс.",al={"ursal location","where is the cleft","how to find ursal","где урсал","где расселина","как найти урсала"}},{q="Спасает ли убийство Урсала фурболгов Сосновых Лап полностью?",a="Нет. Смерть Урсала освобождает спящих друидов, но Атридас предупреждает, что темная порча, терзающая фурболгов Сосновых Лап и леса Тельдрассила, сохраняется глубже в Мировом Древе.",al={"are furbolgs cured","did we save the furbolgs","is teldrassil saved","фурболги исцелены","спасли ли фурболгов","спасен ли тельдрассил"}},{q="Кто такие Друиды Когтя?",a="Друиды Когтя — секта ночных эльфов-друидов, преданная тотему грозовой вороны и наставлениям Авианы. Они погрузились в глубокий сон в Могильном логове, чтобы охранять дикую природу из Изумрудного Сна.",al={"druids of the talon","who is sleeping","what druids were saved","друиды когтя","кто спит","каких друидов спасли"}},{q="Кто такой Атридас Медвежья Шкура?",a="Атридас Медвежья Шкура — ночной эльф-друид, находящийся в Доланааре. Он посылает искателей приключений вернуть похищенные реликвии и убить Урсала, чтобы его собратьев можно было безопасно пробудить.",al={"athridas bearmantle","quest giver athridas","who gives ursal quest","атридас медвежья шкура","атридас выдает задание","кто дает задание про урсала"}}},fp="16,285,26.408.0,20.400.0,23.413.1,24.223.0,46.247.0,36.149.0,58.193.1,32.216.0,27.176.0"}
P.entries["quest:4865"] = {n="Змеиная дикость",s="Змеиная дикость — задание Орды в Тысяче Игл, связывающее находку странных яиц с древними легендами тауренов. После тревожного открытия на Заставе Вольного Ветра Хагар Грозовое Копыто отправляет искателей приключений на северо-запад к Мотеге Огненной Гриве на Заставе Белого Плеса, чтобы противостоять пробуждению Арикары.",h="Змеиная дикость — задание Орды в Тысяче Игл, связывающее находку странных яиц с древними легендами тауренов.",kw={"arikara","freewind post","hagar lightninghoof","motega firemane","sacred fire","serpent wild","thousand needles","whitereach post","арикара","застава вольного ветра","хагар грозовое копыто","мотега огненная грива","священное пламя","змеиная дикость","тысяча игл","застава белого плеса"},ang={["class:Shaman"]="Возмущения мстительных духов вроде Арикары показывают хрупкое равновесие стихийных и духовных сил, населяющих мезы каньона.",["faction:Horde"]="Чтобы пути снабжения через Тысячу Игл оставались открытыми, необходимо устранить мистические угрозы, способные терроризировать дорогу между Великим Подъемником и Фераласом.",["race:Tauren"]="Пробуждение Арикары превращает легенды в срочный кризис и испытывает духовное попечение тауренов, защищающих Тысячу Игл."},sec={{t="Легенда во плоти",b="Когда в Тысяче Игл начали появляться странные неестественные яйца, местные таурены опасались экологической катастрофы. Однако осмотр находок показал нечто гораздо более древнее и зловещее, чем обычные хищники: признаки, указывающие на духа мщения Арикару. Потрясенный ужасным подтверждением, Хагар Грозовое Копыто понимает, что каньону грозит мифическая опасность, которую давно считали лишь преданием у костра."},{t="Дорога к Белому Плесу",b="Понимая, что угроза выходит за рамки простой физической защиты, Хагар требует немедленно обратиться за советом к Мотеге Огненной Гриве. Мотега, дозорный и духовный наставник, сведущий в традиционных знамениях Игл, находится к северо-западу по дну каньона, на Заставе Белого Плеса. Его совет необходим, если Орда хочет понять и умилостивить либо уничтожить восстающего духа мщения."}},faq={{q="Кто дает задание «Змеиная дикость»?",a="Хагар Грозовое Копыто, находящийся высоко на Заставе Вольного Ветра в Тысяче Игл, выдает задание сразу после того, как вы осмотрите странные яйца, найденные по всему каньону.",al={"who gives serpent wild","serpent wild questgiver","hagar lightninghoof quest","кто дает змеиная дикость","змеиная дикость выдает задание","хагар грозовое копыто задание"}},{q="Где находится Мотега Огненная Грива?",a="Мотега Огненная Грива живет на Заставе Белого Плеса — небольшом лагере тауренов у дороги к северо-западу от Заставы Вольного Ветра, за развилкой, ведущей к Великому Подъемнику.",al={"where is motega firemane","motega firemane location","find motega","где мотега огненная грива","мотега огненная грива местонахождение","найти мотегу"}},{q="Кто или что такое Арикара?",a="Арикара — легендарный дух ветряного змея, воплощающий мщение в мифологии тауренов; слухи о его присутствии в Тысяче Игл представляют страшную духовную и физическую угрозу местным племенам.",al={"what is arikara","arikara lore","legend of arikara","что такое арикара","арикара предания","легенда об арикаре"}},{q="Какое задание нужно выполнить перед этим?",a="Вы должны выполнить задание «Странное яйцо»: добыть необычное яйцо у диких зверей каньона и доставить его Хагару Грозовому Копыту для осмотра.",al={"prereq for serpent wild","alien egg quest chain","serpent wild unlock","предыдущее задание змеиная дикость","цепочка странное яйцо","как открыть змеиная дикость"}},{q="Что происходит после встречи с Мотегой Огненной Гривой?",a="Разговор с Мотегой открывает задание «Священное пламя», с которого начинается подготовка к обряду, необходимому для противостояния духу Арикары.",al={"what comes after serpent wild","serpent wild follow up","sacred fire quest","что после змеиная дикость","продолжение змеиная дикость","задание священное пламя"}},{q="Почему Хагар Грозовое Копыто так встревожен?",a="Хагар считал рассказы об Арикаре просто сказками. Увидев воочию свидетельства появления духа мщения в каньоне, он приходит в ужас и тут же посылает за мудрым советом старейшин.",al={"why is hagar scared","hagar wiping brow","hagar reaction","почему хагар напуган","хагар вытирает лоб","реакция хагара"}}},fp="12,308,19.406.0,22.383.0,34.176.0,33.163.0,23.190.0,60.162.0,44.126.0,38.200.0"}
P.entries["quest:487"] = {n="Дорога в Дарнасс",s="Главной дороге, соединяющей поселение Доланаар со столицей ночных эльфов Дарнассом, постоянно угрожают испорченные фурболги Сосновых Лап. Жрица Луны Амара руководит разведчиками и путниками, чтобы этот важный торговый и почтовый путь оставался свободным от засад.",h="Главной дороге, соединяющей поселение Доланаар со столицей ночных эльфов Дарнассом, постоянно угрожают...",kw={"amara","ambusher","darnassus","dolanaar","furbolg","gnarlpine","nightwalker","road to darnassus","teldrassil","амара","нападающий","дарнасс","доланаар","фурболг","сосновые лапы","ночная ходунья","дорога в дарнасс","тельдрассил"},ang={["class:Priest"]="Помощь жрице Луны Амаре служит Сестринству Элуны, которое обеспечивает юному древу и духовное руководство, и воинскую защиту.",["faction:Alliance"]="Дарнасс — сердце присутствия Альянса на севере Калимдора; безопасное движение торговли и связи по его главной дороге крайне важно.",["race:NightElf"]="Сосновые Лапы некогда были благородными родичами дикой природы; убийство испорченных засадников на дороге в Дарнасс — мрачная необходимость, порожденная недугом Тельдрассила."},sec={{t="Осажденная жизненная артерия",b="Дорога, ведущая на запад от Доланаара к Дарнассу, — главная наземная артерия Тельдрассила. Ежедневно по ней должны двигаться важные товары, политические послания и путники, поддерживая связь между столицей и ветвями великого древа. Поскольку Тельдрассил относительно молод и дик, безопасные дороги критически важны для юных общин кальдораев."},{t="Угроза Сосновых Лап",b="Вместо мирных лесных жителей племя фурболгов Сосновых Лап в Тельдрассиле стало жертвой мерзкой порчи. Обезумев от недуга, поражающего ветви Мирового Древа, они нападают из тайных логов под хребтами. Устраивая засады у опушки вдоль дороги, фурболги Сосновых Лап охотятся на неосторожных гонцов и путников, превращая мирную прогулку по лесу в смертельное испытание."},{t="Бдение Часовых",b="Чтобы противостоять засадам, жрица Луны Амара несет дозор у Доланаара. Сочетая духовный авторитет жречества Элуны с воинственной бдительностью Часовых, она направляет способных искателей приключений убивать нападавших у их логов под дорогой, обеспечивая безопасный путь к вратам Дарнасса."}},faq={{q="Почему дорога между Доланааром и Дарнассом так опасна?",a="Испорченные фурболги Сосновых Лап устроили логова вдоль невысоких хребтов под дорогой. Обезумев от порчи, расползающейся по Тельдрассилу, они выходят из подлеска и устраивают засады на путников, гонцов и торговцев.",al={"why are furbolgs attacking","gnarlpine road attacks","why is the road unsafe","почему фурболги нападают","нападения сосновых лап на дороге","почему дорога опасна"}},{q="Кто такая жрица Луны Амара?",a="Жрица Луны Амара — иногда ее называют полным именем, Часовая Амара Ночная Ходунья, — командир ночных эльфов, находящаяся на западной окраине Доланаара. Она отвечает за безопасность дороги и координирует военные действия против близкой угрозы Сосновых Лап.",al={"who gives the road to darnassus quest","amara nightwalker","who is amara","кто дает задание дорога в дарнасс","амара","кто такая амара"}},{q="Почему фурболги Сосновых Лап агрессивны?",a="Фурболги исторически были союзниками и мирными соседями кальдораев. Однако племя Сосновых Лап в Тельдрассиле искажено странным недугом, поразившим Мировое Древо, — их разум стал жестоким, и они нападают на всех, кто входит в лес.",al={"why gnarlpine mad","furbolg corruption teldrassil","are gnarlpine evil","почему сосновые лапы безумны","порча фурболгов тельдрассил","сосновые лапы злые"}},{q="Где прячутся нападающие?",a="Нападающие обитают под утесами и смотровыми точками рядом с главной дорогой к западу от Доланаара: из своих логов они могут прыгать на путников, идущих к Дарнассу.",al={"where are gnarlpine ambushers","find ambushers","ambusher den location","где засадники сосновых лап","найти нападавших","логово нападавших"}},{q="Почему Дарнасс не пошлет полный гарнизон Часовых, чтобы очистить дорогу?",a="Силы Часовых растянуты по всему Тельдрассилу: им приходится бороться с зараженными греллами, испорченными древесными жителями и угрозами на побережье. Офицерам вроде Амары приходится полагаться на умелых путников и добровольцев, чтобы внутренние пути оставались свободными.",al={"where are the guards","why sentinels need help","darnassus patrol","где стража","почему часовым нужна помощь","патруль дарнасса"}},{q="Почему Амару называют и Жрицей Луны, и Часовой?",a="В обществе кальдораев Сестринство Элуны и военные Часовые тесно связаны. Нередко руководители жречества командуют войсками Часовых или всю жизнь служили воинами на передовой.",al={"amara rank","priestess or sentinel amara","amara nightwalker title","звание амары","жрица или часовая амара","амара ночная ходунья титул"}}},fp="21,269,22.385.0,20.418.0,20.319.0,60.230.0,28.272.0,42.264.0,31.172.0,70.246.0,57.234.0"}
P.entries["quest:488"] = {n="Просьба Зенна",s="Просьба Зенна — задание Альянса, которое выдает Зенн Грязное Копыто, одинокий сатир, скрывающийся к северу от дороги между Тенистой долиной и Доланааром. Он уговаривает рвущихся в бой искателей приключений охотиться на местных животных и собирать их части для его тайных замыслов, пользуясь доверчивостью и наивностью новичков в Тельдрассиле.",h="Просьба Зенна — задание Альянса, которое выдает Зенн Грязное Копыто, одинокий сатир, скрывающийся к северу от...",kw={"dolanaar","foulhoof","nightsaber","satyr","shadowglen","strigid","teldrassil","webwood","zenn","доланаар","грязное копыто","ночной саблезуб","сатир","тенистая долина","стригид","тельдрассил","паутинный","зенн"},ang={["class:Druid"]="Друиды поклялись хранить равновесие природы. Охота на ночных саблезубов, сов и пауков по просьбе исковерканного создания порчи оскорбляет учение Кенария.",["race:NightElf"]="Для молодого ночного эльфа подчиняться сатиру — глубокий позор. Сатиры — предки-предатели, оскверненные Пылающим Легионом, а помощь одному из них на ветвях Тельдрассила — преступление против природы и наследия кальдораев."},sec={{t="Сомнительная сделка",b="Путники, идущие из Тенистой долины по тропе к Доланаару, могут встретить Зенна Грязного Копыта, спокойно стоящего под ветвями Великого Древа. Вместо открытой враждебности сатир сулит материальную награду и тайны в обмен на простые поручения. Он просит искателей приключений добыть клыки ночных саблезубов, перья совят-стригидов и шелк паутинных пауков в окрестных лесах и заговорщицки шепчет, что договоренность должна остаться между ними."},{t="Шутка сатира",b="Сатиры — давние враги кальдораев, оскверненные демонической магией во время Войны Древних, поэтому одно присутствие Зенна в Тельдрассиле — оскорбление. Ничего не подозревающие искатели приключений, выполнившие его поручение, быстро понимают, что над ними посмеялись. Вместо сокровищ и великих тайн Зенн открыто смеется над тем, как легко путник поддался на уловку и послужил сатиру, и радуется, что одурачил наивного чужака и заставил его делать грязную работу."}},faq={{q="Кто такой Зенн Грязное Копыто?",a="Зенн Грязное Копыто — хитрый сатир, скрывающийся у тропы к западу от Тенистой долины на пути в Доланаар. В отличие от большинства сатиров, нападающих сразу, Зенн использует льстивые речи и ложные обещания, чтобы заставить наивных путников выполнять для него поручения.",al={"who is zenn","zenn foulhoof lore","satyr questgiver","кто такой зенн","зенн грязное копыто предания","сатир выдает задания"}},{q="Почему сатир выдает задания в Тельдрассиле?",a="Зенн притворяется мирным, чтобы одурачить неопытных искателей приключений, еще не знающих коварной, порочной природы сатиров. Он пользуется их рвением к работе и жаждой серебра, чтобы собрать реагенты, которые не может добыть сам, не навлекая на себя гнев Часовых.",al={"why is a satyr friendly","why can i talk to zenn","satyr in teldrassil","почему сатир дружелюбен","почему можно говорить с зенном","сатир в тельдрассиле"}},{q="Что Зенн делает с клыками, перьями и шелком?",a="Зенн утверждает, что эти части нужны как реагенты для его загадочных «дел в лесу». На деле ему нравится властвовать над смертными и использовать их труд в своих порочных целях, втайне насмехаясь над их доверчивостью.",al={"why does zenn want silk","zenn's reagents","what are the animal parts for","зачем зенну шелк","реагенты зенна","для чего части животных"}},{q="Почему ночным эльфам не следует доверять Зенну Грязному Копыту?",a="Сатиры когда-то были ночными эльфами, превращенными демонической силой Пылающего Легиона десять тысяч лет назад во время Войны Древних. Они — давние заклятые враги кальдораев и носители порчи, поэтому любая сделка с ними опасна и позорна.",al={"why hate satyrs","night elf satyr history","are satyrs evil","за что ненавидеть сатиров","ночные эльфы и сатиры история","сатиры злые"}},{q="Что происходит после выполнения задания «Просьба Зенна»?",a="Получив предметы, Зенн открыто насмехается над вами за глупость — вы послушались сатира. Осознав обман и позор помощи такому существу, искатели приключений получают указание искупить свою ошибку.",al={"after zenn's bidding","seek redemption quest","what next after zenn","после просьбы зенна","задание искупление вины","что дальше после зенна"}},{q="Где находится Зенн Грязное Копыто?",a="Он находится в Тельдрассиле, к северу от главной дороги, ведущей на запад из Тенистой долины к Доланаару.",al={"zenn foulhoof location","where is zenn","zenn map location","зенн грязное копыто где находится","где зенн","зенн на карте"}}},fp="14,313,17.484.0,16.443.1,21.242.0,43.271.0,53.232.0,46.278.0,45.230.1,31.116.0"}
P.entries["quest:4881"] = {n="Убийственный заговор",s="Убийственный заговор — задание Орды, которое начинается с находки перехваченных приказов кентавров в Тысяче Игл. Приказы раскрывают готовящийся удар по таурену Канати Серое Облако в его охотничьем лагере у Заставы Белого Плеса.",h="Убийственный заговор — задание Орды, которое начинается с находки перехваченных приказов кентавров в Тысяче...",kw={"assassination note","assassination plot","centaur","great lift","horde","kanati greycloud","thousand needles","whitereach post","записка убийцы","убийственный заговор","кентавр","великий подъемник","орда","канати серое облако","тысяча игл","застава белого плеса"},ang={["faction:Horde"]="Застава Белого Плеса служит небольшим аванпостом Орды к юго-западу от Великого Подъемника, поэтому выживание Канати важно для наблюдения за Тысячей Игл.",["race:Tauren"]="Вражда с кентаврами глубоко укоренилась в памяти тауренов. Защита Канати Серое Облако у Заставы Белого Плеса — прямое продолжение долгой борьбы за сохранность равнин и каньонов Калимдора от нападений кентавров."},sec={{t="Охотник во враждебных землях",b="Тысяча Игл давно остается спорной землей, где господствуют враждующие кланы кентавров и опасные звери. Когда таурен-воин Канати Серое Облако разбил охотничий лагерь у Заставы Белого Плеса, небольшого поста к юго-западу от Великого Подъемника, местные кентавры сочли это дерзким вторжением на свою территорию. Не довольствуясь тем, что он распугивает дичь, кентавры решили полностью избавиться от Серого Облака, чтобы отбить у Орды желание продвигаться дальше по каньону."},{t="Перехваченные приказы",b="Заговор раскрывается, когда путник находит письменный приказ с планом кентавров. В записке прямо назван Канати Серое Облако: его осуждают за дерзость и приказывают отряду собраться у Заставы Белого Плеса, чтобы уничтожить лагерь и всех, кто посмеет последовать за ним. Доставив послание Канати, вы предупредите охотника, и он подготовится немедленно дать отпор налетчикам."}},faq={{q="Что такое убийственный заговор?",a="Это согласованная засада, которую местные кентавры готовят на Канати Серое Облако, таурена, разбившего охотничий лагерь у Заставы Белого Плеса в Тысяче Игл. Кентавры хотят его смерти, чтобы Орда не закрепилась в каньоне.",al={"assassination plot overview","what is this quest about","centaur plot","убийственный заговор обзор","о чем это задание","заговор кентавров"}},{q="Кто такой Канати Серое Облако?",a="Канати Серое Облако — таурен, разбивший охотничий лагерь у Заставы Белого Плеса, небольшого поста к юго-западу от Великого Подъемника в Тысяче Игл. Лагерь так близко к каньонам кланов кентавров делает его главной мишенью.",al={"who is kanati","kanati greycloud","whitereach post npc","кто такой канати","канати серое облако","персонаж застава белого плеса"}},{q="Почему кентавры хотят убить Канати?",a="Кентавры считают присутствие Канати у Заставы Белого Плеса невыносимым вторжением в Тысячу Игл. Они хотят убить его, чтобы разрушить охотничий лагерь и отбить у будущих разведчиков Орды желание селиться в этом краю.",al={"why kill kanati","centaur motive","why do centaur attack","зачем убивать канати","мотив кентавров","почему кентавры нападают"}},{q="Где находится Застава Белого Плеса?",a="Застава Белого Плеса — небольшой лагерь тауренов в Тысяче Игл, расположенный к юго-западу от Великого Подъемника на дне каньона.",al={"whitereach post location","where is kanati's camp","where is whitereach","застава белого плеса где","где лагерь канати","где белый плес"}},{q="Могут ли игроки Альянса выполнить это задание?",a="Путники из Альянса тоже могут найти записку убийцы, но не могут доставить предупреждение: Канати Серое Облако — таурен Орды, и передать ее ему может только Орда.",al={"can alliance do this","alliance assassination note","alliance turn in","может ли альянс выполнить","записка убийцы альянс","сдать задание за альянс"}},{q="Что происходит после предупреждения Канати?",a="Получив предупреждение, Канати отказывается бежать. Вместо этого он готовится отразить нападающих, что напрямую ведет к обороне Заставы Белого Плеса, когда прибывает отряд кентавров.",al={"what happens next","next quest","protect kanati","что дальше","следующее задание","защитить канати"}}},fp="18,223,25.461.0,22.410.1,31.238.0,24.215.0,39.219.0,25.128.0,41.167.0,36.194.1"}
P.entries["quest:489"] = {n="Искупление вины",s="Искупление вины — задание, которое дают в Доланааре искателям приключений, которых обманом заставили выполнять грязную работу сатира Зенна Грязного Копыта. Совет Леса требует покаяния за вред лесным зверям и посылает вас обмануть коварного сатира, заставив его съесть оскверненные скверношишки.",h="Искупление вины — задание, которое дают в Доланааре искателям приключений, которых обманом заставили...",kw={"dolanaar","fel cone","kyra starsong","satyr","seek redemption","shayla nightbreeze","syral bladeleaf","teldrassil","zenn foulhoof","доланаар","скверношишка","кира песнь звезд","сатир","искупление вины","шайла ночной бриз","сирел остролист","тельдрассил","зенн грязное копыто"},ang={["class:Druid"]="Друиды считают равновесие Тельдрассила священным; охота на хищников и падальщиков по воле изгоя, оскверненного демонами, напрямую нарушает заветы стражей круга Кенария.",["race:NightElf"]="Для кальдораев помощь сатиру глубоко унизительна. Сатиры — древние враги, искаженные Пылающим Легионом во время Войны Древних, поэтому покаяние перед Советом Леса — вопрос чести их народа."},sec={{t="Исправленная глупость",b="Зенн Грязное Копыто, одинокий сатир, скрывающийся неподалеку от Доланаара, обманом заставляет прохожих исполнять его волю. Искатели приключений, по неведению убивавшие ночных саблезубов, сов-стригидов и паутинных пауков ради его извращенных прихотей, вскоре навлекают на себя резкое неодобрение Совета Леса. Совет не терпит осквернения природы, тем более со стороны своих союзников."},{t="Цена искупления",b="Предупредит ли вас Сирел Остролист, Часовой Кира Песнь Звезд или Часовой Шайла Ночной Бриз, смысл ясен: чтобы остаться желанным гостем в Тельдрассиле, нужно загладить вину. Вместо того чтобы идти на Грязное Копыто с оружием, стражи Доланаара велят вам воспользоваться его мерзким обжорством. Собрав в лесу дымящиеся оскверненные скверношишки, вы угостите ничего не подозревающее создание его же отравой."},{t="Квакающее возмездие",b="Под видом очередного услужливого посыльного с лакомством вы вручаете Грязному Копыту ядовитые шишки. Не подозревая о друидской ловушке, Зенн жадно пожирает угощение — и тут же превращается в беспомощную лягушку, лишенную своих гнусных замыслов и смиренную перед природой, которую хотел осквернить."}},faq={{q="Почему Совет Леса на меня сердит?",a="Вы приняли прежнее поручение Зенна Грязного Копыта и истребляли местных животных — ночных саблезубов, сов-стригидов и пауков — ради прихоти сатира. Совет считает бессмысленное убийство созданий природы осквернением Тельдрассила и требует искупить вину, чтобы остаться в добром расположении.",al={"why council mad","seek redemption why","why do i need redemption","почему совет сердится","искупление вины почему","зачем мне искупление"}},{q="Кто может дать мне это задание?",a="Это задание предлагают несколько стражей в Доланааре и его окрестностях после того, как вы закончите помогать Грязному Копыту. Поговорите с Сирел Остролист у северного дома, Часовым Кирой Песнь Звезд в таверне или Часовым Шайлой Ночной Бриз на западной дороге.",al={"quest givers","who starts seek redemption","where to get seek redemption","кто выдает задание","кто начинает искупление вины","где взять искупление вины"}},{q="Что такое скверношишки?",a="Скверношишки — оскверненные сосновые семена, падающие с искривленных ветвей Тельдрассила. Их легко узнать по жутковатым зеленым парам, поднимающимся из оболочки; в них заключена мерзкая магия, которую друиды обращают против ничего не подозревающих негодяев.",al={"fel cone","what is fel cone","where fel cones come from","скверношишка","что такое скверношишка","откуда скверношишки"}},{q="Почему предлагать шишки Скверны Зенну Грязное Копыто?",a="Совет ожидает, что вы преподадите урок Зенну Грязное Копыто. Он примет оскверненные шишки за безобидное угощение от того, кто прежде выполнял его поручения.",al={"why give zenn cones","foulhoof snack","fel cone trick","зачем давать шишки зенну","угощение грязное копыто","уловка с шишками скверны"}},{q="Почему сатир живет так близко к Доланаару?",a="Зенн Грязное Копыто держится неприметно на выемчатой поляне неподалеку от поселения, скрывая свою злобную натуру за ложной любезностью. Сатиры по всему Калимдору — древние слуги Пылающего Легиона, и присутствие Зенна показывает, как глубоко порча проникла в юное Мировое Древо.",al={"why is zenn near dolanaar","satyr in dolanaar","zenn foulhoof lore","почему зенн рядом с доланааром","сатир в доланааре","зенн грязное копыто предания"}},{q="Можно ли пропустить или отменить это задание, не испортив отношения?",a="Да. Хотя Совет Леса строго упрекает вас за помощь Грязному Копыту, отказ взять или выполнить задание не повредит вашей репутации у ночных эльфов Дарнасса.",al={"reputation loss","can i abandon seek redemption","fail seek redemption","потеря репутации","можно ли отменить искупление вины","провалить искупление вины"}}},fp="16,274,22.393.0,22.426.0,22.331.1,47.287.0,27.247.0,19.236.0,41.153.1,49.292.0,65.204.0"}
P.entries["quest:4904"] = {n="Долгожданная свобода",s="«Долгожданная свобода» — спасательная миссия на продуваемых ветрами шпилях Пика Темного Облака. Лакота Песня Ветра, женщина-таурен, плененная Арнаком Зловещим Тотемом, нуждается в защите, пока бежит из крепости похитителя и возвращается к подруге Талии Янтарной Шкуре на Заставе Вольного Ветра.",h="«Долгожданная свобода» — спасательная миссия на продуваемых ветрами шпилях Пика Темного Облака.",kw={"arnak grimtotem","darkcloud pinnacle","escort","free at last","freewind post","lakota windsong","thalia amberhide","thousand needles","арнак зловещий тотем","пик темного облака","сопровождение","долгожданная свобода","застава вольного ветра","лакота песня ветра","талия янтарная шкура","тысяча игл"},ang={["faction:Horde"]="Орда удерживает Заставу Вольного Ветра как важную крепость на юге Калимдора, поэтому беззаконие и похищения, совершаемые племенем Зловещего Тотема на Пике Темного Облака, — недопустимая угроза для дороги.",["race:Tauren"]="Клан Зловещего Тотема продолжает демонстрировать пренебрежение к миру и единству народа таурен, показывая свою жестокость в насильственных похищениях и братоубийстве прямо на глазах у Заставы Вольного Ветра."},sec={{t="Жестокое похищение",b="Агрессивное присутствие клана Зловещего Тотема в Тысяче Игл не ограничивается стычками за землю. Арнак Зловещий Тотем хотел взять Лакоту Песня Ветра в жены, но когда она отвергла его ухаживания, он прибег к насилию. Арнак вернулся ночью, убил брата Лакоты, когда тот попытался ее защитить, и утащил ее на Пик Темного Облака."},{t="Побег с Пика Темного Облака",b="Пик Темного Облака раскинулся на высоких деревянных подвесных мостах над Тысячей Игл и кишит враждебными воинами племени Зловещего Тотема. Чтобы сопроводить Лакоту, нужно пройти спуск и отбиваться от волн разбойников Зловещего Тотема, которые хотят вернуть ее в плен до того, как она достигнет дна каньона."},{t="Горькое возвращение",b="Благополучно спустившись с пика, Лакота добирается до безопасной Заставы Вольного Ветра. Ее подруга Талия Янтарная Шкура встречает новость с огромным облегчением, но глубоко скорбит о погибшем брате Лакоты и в знак благодарности отдает его оставшиеся вещи тем, кто привел ее домой живой."}},faq={{q="Почему Лакоту Песня Ветра взяли в плен?",a="Арнак Зловещий Тотем хотел жениться на Лакоте Песня Ветра. После ее отказа он ночью напал на ее дом, убил ее брата-защитника и против воли утащил ее на Пик Темного Облака.",al={"why is lakota captured","who kidnapped lakota","why did arnak take lakota","почему лакота в плену","кто похитил лакоту","зачем арнак забрал лакоту"}},{q="Где находится Пик Темного Облака?",a="Пик Темного Облака — группа высоких скальных шпилей, соединенных мостами, в северной части Тысячи Игл, к юго-востоку от Великого Подъемника и к югу от Курганов Иглошкурых.",al={"darkcloud pinnacle location","how to get to darkcloud pinnacle","where is lakota","где пик темного облака","как попасть на пик темного облака","где лакота"}},{q="Кто такой Арнак Зловещий Тотем?",a="Арнак — безжалостный член племени Зловещего Тотема, обосновавшийся на Пике Темного Облака. Помимо похищения Лакоты и убийства ее брата, он также преступник, которого власти Орды на Заставе Вольного Ветра приговорили к смерти.",al={"arnak lore","who is arnak","wanted arnak","арнак предыстория","кто такой арнак","арнак в розыске"}},{q="С кем поговорить после спасения?",a="Когда Лакота благополучно спустится со шпилей на дно каньона, вам нужно вернуться на Заставу Вольного Ветра на высоких утесах и поговорить с Талией Янтарной Шкурой.",al={"where to turn in free at last","who is thalia amberhide","turn in free at last","где сдать долгожданная свобода","кто такая талия янтарная шкура","сдать долгожданная свобода"}},{q="Почему племя Зловещего Тотема нападает во время побега?",a="Разбойники Арнака из племени Зловещего Тотема патрулируют вершины Пика Темного Облака и яростно устраивают засады на всех, кто пытается помочь его пленнице обрести свободу.",al={"why do bandits spawn","grimtotem bandits escort","почему появляются разбойники","разбойники зловещего тотема","сопровождение"}},{q="Что случилось с братом Лакоты?",a="Брат Лакоты погиб, пытаясь защитить ее от Арнака Зловещего Тотема во время похищения. Позже Талия отдает его семейные реликвии в награду за спасение его сестры.",al={"lakotas brother","who died saving lakota","what happened to lakota brother","брат лакоты","кто погиб спасая лакоту","что случилось с братом лакоты"}}},fp="12,261,18.346.0,30.295.0,19.306.0,33.200.0,36.174.0,23.214.0,41.153.0,46.148.0,33.182.0"}
P.entries["quest:491"] = {n="Жезл для Бетора",s="Это задание завершает противостояние в Крепости Фенриса: давно утраченная реликвия, Сплетенный жезл, возвращается Бетору Ледострелу в Подгороде. Много лет назад три ученика-мага создали жезл как символ товарищества, а когда Тул Коготь Ворона примкнул к Плети, жезл спрятали. Его возвращение закрывает горькую главу в прошлом Бетора.",h="Это задание завершает противостояние в Крепости Фенриса: давно утраченная реликвия, Сплетенный жезл...",kw={"bethor iceshard","fenris isle","fenris keep","magic quarter","silverpine","thule ravenclaw","undercity","woven wand","бетор ледострел","остров фенриса","крепость фенриса","магический квартал","серебряный бор","тул коготь ворона","подгород","сплетенный жезл"},ang={["class:Mage"]="Сплетенный жезл воплощает классическую тайную традицию: ученики-маги соединяют свои фокусы в знак товарищества — невинность, разрушенная, когда Плеть разорвала на части Даларан и Лордерон.",["race:Undead"]="Для магов из Отрекшихся вроде Бетора возвращение артефактов эпохи до чумы — горько-сладкое напоминание о смертных стремлениях и бывших друзьях, выбравших тиранию Короля-лича вместо свободной воли."},sec={{t="Символ распавшегося товарищества",b="Задолго до того, как Лордерон пал и лег в руины, три молодых мага соединили свои учебные жезлы в единый предмет — Сплетенный жезл. Он должен был символизировать их общие узы и устремления в магическом искусстве. Но когда Тул Коготь Ворона обратил свою верность к Королю-личу и принял Плеть, это товарищество необратимо распалось. Хотя Тул возненавидел прежнюю дружбу, он не смог уничтожить жезл и не мог вынести мысли оставить его в руках бывших соратников."},{t="Спрятан в крепости",b="Не желая ни расставаться с жезлом, ни уничтожать его, Тул отнес его на Остров Фенриса и спрятал на пыльной потайной полке в Крепости Фенриса. Годами нетронутые, его чары оставались спящими; Тул ни разу не применил его магию — как отметил Бетор, это сразу выдало бы его местонахождение. Возвращение жезла в Магический квартал Подгорода дарит Бетору редкую память о его смертной юности, найденную в логове предателя, который не мог ни любить друзей, ни отпустить их."}},faq={{q="Что такое Сплетенный жезл?",a="Сплетенный жезл — уникальный магический предмет, созданный давным-давно Тулом Когтем Ворона и двумя другими учениками-магами, одним из которых был Бетор Ледострел. Каждый внес свой первый учебный жезл, и их сплели вместе как материальный символ дружбы и общих тайных наук.",al={"woven wand","what is the wand","thule wand lore","сплетенный жезл","что за жезл","предыстория жезла тула"}},{q="Почему Тул Коготь Ворона украл жезл?",a="Когда Тул перешел на сторону Короля-лича, узы между соратниками распались. Хотя Тул возненавидел дружбу, которую жезл олицетворял, он был слишком собственнически настроен, чтобы расстаться с реликвией или позволить Бетору и другому товарищу сохранить ее. Поэтому он украл жезл и спрятал его на Острове Фенриса.",al={"why did thule take it","why steal the wand","thule stolen wand","зачем тул взял жезл","зачем красть жезл","украденный жезл тула"}},{q="Кто такой Бетор Ледострел?",a="Бетор Ледострел — маг-наставник из Отрекшихся, живущий в Магическом квартале Подгорода. При жизни он был ровесником и другом Тула Когтя Ворона, пока королевство не рухнуло, а Тул не отдал свою волю Плети.",al={"who is bethor","bethor iceshard lore","bethor undercity","кто такой бетор","бетор ледострел предыстория","бетор подгород"}},{q="Почему Тул не использовал магию Сплетенного жезла?",a="Если бы Тул хоть раз задействовал скрытые чары жезла, Бетор почувствовал бы отклик в магической ткани. Тул хранил жезл на забытой полке в Крепости Фенриса исключительно из злобы и собственничества, не трогая его силу.",al={"did thule use wand","wand power","why not use it","использовал ли тул жезл","сила жезла","почему не использовать"}},{q="Кто был третьим учеником, создавшим жезл?",a="Третьим учеником был Гюнтер Чародей, который сплел жезл вместе с Бетором и Тулом задолго до предательства Тула.",al={"third apprentice","three mages wand","third mage","третий ученик","три мага жезл","третий маг"}},{q="Где находился жезл до того, как его нашли?",a="Жезл был спрятан на пыльной полке в потайной нише Крепости Фенриса — твердыни на Острове Фенриса, где Тул Коготь Ворона устроил свою базу Плети.",al={"where was wand","hidden niche wand","fenris keep wand","где был жезл","жезл в нише","жезл крепость фенриса"}}},fp="14,332,31.518.0,18.487.1,23.286.0,39.297.0,23.219.0,44.249.0,54.120.0,45.172.0"}
P.entries["quest:492"] = {n="Новая чума",s="Это задание — мрачная кульминация первых исследований аптекаря Юхана в Брилле от имени Королевского фармацевтического общества. Собрав яд, кровь и мерзкие смеси по всем Тирисфальским лесам, Юхан посылает вас в подвал таверны «Петля висельника», чтобы испытать смертельное зелье на пленном горном пехотинце-дворфе.",h="Это задание — мрачная кульминация первых исследований аптекаря Юхана в Брилле от имени Королевского...",kw={"a new plague","apothecary johaan","brill","captured mountaineer","gallows end","plague","poison","royal apothecary society","tirisfal glades","новая чума","аптекарь юхан","брилл","пленный горный пехотинец","петля висельника","чума","яд","королевское фармацевтическое общество","тирисфальские леса"},ang={["faction:Alliance"]="Судьба пленного горного пехотинца показывает абсолютную безжалостность Отрекшихся к лазутчикам Альянса, обнаруженным в Лордероне.",["faction:Horde"]="Пока ваши союзники в Калимдоре могут сражаться за честь и выживание, Отрекшиеся добиваются победы хладнокровной алхимической войной, не щадящей ни друга, ни врага.",["race:Dwarf"]="Несчастный пленник показывает, как далеко простирается присутствие горных пехотинцев Стальгорна, которые рискуют смертью и тайными допросами, чтобы наблюдать за Тирисфальскими лесами.",["race:Undead"]="Проведение эксперимента Юхана дает возможность воочию увидеть бескомпромиссную доктрину выживания Отрекшихся и смертоносную работу Королевского фармацевтического общества."},sec={{t="Смертельная смесь",b="Все время, пока вы помогали аптекарю Юхану, ваши усилия вели к созданию смертельного токсина. Королевское фармацевтическое общество проводит амбициозную и тайную программу по приказу леди Сильваны Ветрокрылой: создать новую чуму, которая не действует на нежить, но уничтожает живых. На этом последнем этапе Юхан варит то, что иносказательно называет «особым напитком», и поручает вам дать его пленному врагу Отрекшихся."},{t="Подвал «Петли висельника»",b="Под Таверной «Петля висельника» в Брилле Стражи смерти держат сырой подвал, служащий временной камерой для пленных, ожидающих допроса или казни. Среди них сидит Пленный горный пехотинец — разведчик из отрядов Стальгорна, проникший в Тирисфальские леса. Непокорный и мучимый жаждой, он охотно берет напиток, не подозревая о его истинной алхимической начинке."},{t="Леденящая демонстрация",b="Когда ему протягивают флягу, горный пехотинец с радостью пьет, с тоской сравнивая напиток с Болтливым пивом и хвастаясь, что дворфийские паровые танки скоро придут ему на выручку. Яд действует почти мгновенно и убивает его на месте. Прощальные слова Юхана звучат пугающе ясно: этот смертельный напиток — лишь намек на то, что Темная Госпожа готовит остальному Азероту."}},faq={{q="Кто такой аптекарь Юхан?",a="Аптекарь Юхан — член Королевского фармацевтического общества, находящийся в городке Брилл в Тирисфальских лесах. Он руководит ранними исследованиями по созданию новой чумы для войны Отрекшихся и нанимает искателей приключений, чтобы собирать смертоносные реагенты в окрестных землях.",al={"apothecary johaan","who gives a new plague","johaan brilliance","аптекарь юхан","кто выдает новую чуму","юхан"}},{q="Почему в Брилле в плену дворф?",a="Горные пехотинцы Стальгорна ведут разведку в северных королевствах, следя за передвижениями Отрекшихся и изучая Чумные земли. Стражи смерти схватили этого разведчика в Тирисфале и заперли в подвале таверны, пока аптекари не нашли ему применение.",al={"dwarf in cellar","captured mountaineer","why is dwarf in tirisfal","дворф в подвале","пленный горный пехотинец","почему дворф в тирисфале"}},{q="Что происходит, когда вы даете пленнику напиток?",a="Дворф охотно берет сосуд, отчаянно желая утолить жажду после плена. Через мгновения после питья ядовитое зелье убивает его на месте, показывая безжалостную эффективность последней формулы чумы Юхана.",al={"does the dwarf die","drink result","mountaineer death","умирает ли дворф","результат напитка","смерть горного пехотинца"}},{q="Для чего нужны исследования Новой чумы?",a="Отрекшиеся стремятся создать новую чуму по приказу леди Сильваны Ветрокрылой. Их цель — разработать биологическое оружие, достаточно мощное, чтобы уничтожить как безмозглую Плеть, так и живые расы, угрожающие их владениям.",al={"why make new plague","royal apothecary society goal","dark lady plague","зачем создавать новую чуму","цель королевского фармацевтического общества","чума темной госпожи"}},{q="Где находится Пленный горный пехотинец?",a="Пленный горный пехотинец заключен внизу, в подвале Таверны «Петля висельника», в центре Брилла в Тирисфальских лесах.",al={"find captive dwarf","gallows end cellar","where is mountaineer","найти пленного дворфа","подвал петля висельника","где горный пехотинец"}},{q="Продолжается ли цепочка заданий после этого дворфа?",a="Это задание из четырех частей для аптекаря Юхана заканчивается смертью горного пехотинца. Однако исследования Новой чумы остаются главным делом по всему Лордерону и приведут вас к новым испытаниям в Подгороде и Гробнице.",al={"next quest","a new plague followup","after mountaineer dies","следующее задание","продолжение новой чумы","после смерти пехотинца"}}},fp="12,317,19.467.0,23.389.0,24.367.1,25.277.0,39.263.0,50.226.1,47.243.0,42.138.0,49.258.0"}
P.entries["quest:493"] = {n="Путешествие в предгорья Хилсбрада",s="«Путешествие в предгорья Хилсбрада» — курьерское задание Орды, связывающее исследования Отрекшихся в Серебряном бору с их форпостом в Мельнице Таррен. Получив секретные записи аптекаря Ренферрела, путник отправляется на юг, в спорные Предгорья Хилсбрада, чтобы доставить аптекарю Лидону важные биологические исследования. Это поручение отражает сильное давление, которое леди Сильвана Ветрокрылая оказывает на Королевское фармацевтическое общество, требуя создать оружие массового уничтожения.",h="«Путешествие в предгорья Хилсбрада» — курьерское задание Орды, связывающее исследования Отрекшихся в...",kw={"hillsbrad","lydon","new plague","renferrel","royal apothecary society","silverpine","sylvanas","tarren mill","хилсбрад","лидон","новая чума","ренферрел","королевское фармацевтическое общество","серебряный бор","сильвана","мельница таррен"},ang={["faction:Horde"]="Хотя орки и таурены в целом не одобряют подлые яды, помощь в утверждении господства Отрекшихся в Хилсбраде укрепляет позиции Орды в Восточных королевствах.",["profession:Herbalism"]="Исследования Ренферрела и Лидона во многом опираются на изучение и сбор ядовитой мутировавшей флоры на землях Лордерона.",["race:Undead"]="Для Отрекшихся доставка этих результатов — прямой вклад в выживание их народа и месть как живым, так и Плети."},sec={{t="Собственная чума",b="С тех пор как леди Сильвана Ветрокрылая вырвалась из железной хватки Короля-лича, она одержима единственной целью: создать Новую чуму, способную истребить и живых врагов, и Плеть. Для этого Королевское фармацевтическое общество работает под неослабным давлением Королевы банши. Лаборатории разделены расстоянием, поэтому исследователи, разбросанные по Лордерону, постоянно обмениваются необработанными химическими данными и результатами испытаний, чтобы ускорить свой зловещий прорыв."},{t="Дорога на юг",b="Аптекарь Ренферрел, работающий в Гробнице в Серебряном бору, поручает курьерам доставить его последние результаты коллеге, аптекарю Лидону. Путь ведет на юг через сумрачные сосновые леса, мимо мерцающего магического купола Даларана и вниз, на открытые холмистые пастбища Предгорий Хилсбрада. Там, у подножия Альтеракских гор, лежит Мельница Таррен — важный центр Отрекшихся и опорная база для лабораторий."}},faq={{q="Что содержится в результатах Ренферрела?",a="Результаты Ренферрела — это документация исследований, описывающая его опыты над местной фауной, флорой и биологическими токсинами. Они служат частями общей формулы, которую Королевское фармацевтическое общество составляет для своей драгоценной Новой чумы.",al={"what are the findings","renferrel research","what am i delivering","что за результаты","исследования ренферрела","что я доставляю"}},{q="Почему Королевское фармацевтическое общество так торопится?",a="Леди Сильвана Ветрокрылая требует немедленных результатов. Окруженные враждебными остатками людей, фанатичным Алым орденом и бродячей Плетью, Отрекшиеся уверены, что лишь окончательное биологическое оружие гарантирует их выживание и позволит отомстить Артасу.",al={"why rush plague","why under pressure","sylvanas pressure","зачем спешить с чумой","почему давление","давление сильваны"}},{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — старший исследователь Королевского фармацевтического общества, находящийся в Мельнице Таррен. Пользуясь большим уважением коллег, таких как Ренферрел, Лидон руководит смертоносными биологическими опытами в Предгорьях Хилсбрада, совершенствуя штаммы чумы с помощью местных припасов и пленников.",al={"who is lydon","apothecary lydon lore","кто такой лидон","аптекарь лидон предания"}},{q="Где находится Мельница Таррен?",a="Мельница Таррен расположена на севере Предгорий Хилсбрада, к югу от Альтеракских гор и к востоку от Серебряного бора. Если идти по главным дорогам на юг от Серебряного бора и свернуть на восток на перекрестке, можно прямо попасть в поселение.",al={"tarren mill location","how to get to tarren mill","where is hillsbrad","где мельница таррен","как добраться до мельницы таррен","где хилсбрад"}},{q="Почему Отрекшиеся передают результаты через пеших курьеров?",a="Отрекшиеся не могут рисковать арканной передачей, которую могут перехватить маги Кирин-Тора или соперничающие фракции. Пешие курьеры, идущие по проверенным охраняемым дорогам, позволяют незаметно переправлять смертоносные алхимические записи через границы регионов.",al={"why foot messenger","why courier delivery","почему пеший гонец","почему курьер"}},{q="Что происходит после того, как Лидон получает исследования?",a="Получив пакет, аптекарь Лидон сразу начинает изучать записи Ренферрела, чтобы использовать их в своих смесях, а затем поручает искателям приключений испытать улучшенные штаммы на местных жителях.",al={"what next after delivering","lydon reaction","что дальше после доставки","реакция лидона"}}},fp="30,484,21.501.0,14.434.0,36.244.0,51.260.0,24.271.0,21.245.0,61.239.0,43.226.1"}
P.entries["quest:494"] = {n="Время нанести удар",s="«Время нанести удар» — разведывательное задание Орды, которое переправляет разведчиков через границу Предгорий Хилсбрада в военный центр — Мельницу Таррен. Доставка зашифрованного сигнала Стража смерти Леш Верховному палачу Дарталии знаменует переход от тихого наблюдения к согласованным наступательным действиям против местных людей.",h="«Время нанести удар» — разведывательное задание Орды, которое переправляет разведчиков через границу...",kw={"deathstalker lesh","high executor darthalia","hillsbrad","hillsbrad foothills","scouting","tarren mill","varimathras","страж смерти леш","верховный палач дарталия","хилсбрад","предгорья хилсбрада","разведка","мельница таррен","вариматрас"},ang={["class:Rogue"]="Скрытный наблюдательный пост Леш и зашифрованные послания отражают мастерство Стражей смерти — элитной гильдии убийц и разведчиков Подгорода.",["faction:Horde"]="Это донесение вовлекает союзников Орды, не относящихся к нежити, глубже в стратегический конфликт между Отрекшимися и людскими поселениями на юге.",["race:Undead"]="Для агентов Отрекшихся доставка донесения Леш помогает укрепить восточные рубежи Лордерона против остатков людского Альянса."},sec={{t="Наблюдатель на границе",b="Страж смерти Леш, засевшая на возвышенности у границы между Серебряным бором и Предгорьями Хилсбрада, следит за передвижениями людей-поселенцев и ополчения в долине внизу. Стражи смерти служат глазами и ушами Подгорода и осматривают вражеские поселения до начала любых военных действий. Не желая покидать наблюдательный пост, Леш поручает проходящим путникам из Орды передать собранные сведения по дороге в Мельницу Таррен."},{t="Зашифрованный зов",b="Послание Леш намеренно туманно: «Крик ворона с запада зовет». Это сообщение, доставленное на восток по проторенным дорогам, сообщает Верховному палачу Дарталии, что оборона людей вокруг города Хилсбрад уязвима. Для Дарталии и владыки ужаса Вариматраса это означает, что настало время поднять силы Отрекшихся и начать кампанию против защитников Хилсбрада."}},faq={{q="Что означает послание Стража смерти Леш?",a="Фраза «Крик ворона с запада зовет» — зашифрованное разведывательное донесение. Она сообщает Верховному палачу Дарталии, что западные подступы к Хилсбраду плохо охраняются и готовы к немедленному наступлению.",al={"raven's cry meaning","what does the raven cry mean","lesh message","значение крика ворона","что значит крик ворона","послание леш"}},{q="Кто такая Верховный палач Дарталия?",a="Верховный палач Дарталия — верховный военный командир Отрекшихся в Предгорьях Хилсбрада. Находясь в укрепленной деревне Мельница Таррен, она руководит наступательными действиями против людей Южнобережья и тесно согласовывает стратегию с Вариматрасом в Подгороде.",al={"who is darthalia","darthalia role","кто такая дарталия","роль дарталии"}},{q="Почему Леш посылает курьера, а не идет сама?",a="Леш ведет важную разведку на западной окраине Хилсбрада. Если она покинет пост, у наблюдения Отрекшихся появится слепая зона, поэтому срочные донесения она поручает проходящим путникам из Орды.",al={"why doesn't lesh leave","why couriers","почему леш не уходит","почему курьеры"}},{q="Куда нужно доставить это послание?",a="Послание нужно нести по главной дороге на восток через Предгорья Хилсбрада к Мельнице Таррен — главному оплоту Орды в этом регионе.",al={"where do i go","message destination","куда идти","место доставки послания"}},{q="Почему Вариматрас участвует в делах Хилсбрада?",a="Как главный помощник Сильваны Ветрокрылой и советник-повелитель ужаса, Вариматрас руководит значительной частью военного и стратегического планирования Отрекшихся из Королевского квартала в Подгороде. Верховный палач Дарталия исполняет его указания по кампании на региональном фронте.",al={"varimathras hillsbrad","why varimathras","вариматрас хилсбрад","почему вариматрас"}},{q="Что происходит после получения этого послания?",a="Получив подтверждение, что Хилсбрад уязвим, Дарталия разрешает агрессивные наступательные удары и посылает защитников Орды разрушить фермы, ополчение и инфраструктуру города Хилсбрад.",al={"what happens next","after time to strike","что дальше","после время нанести удар"}}},fp="14,334,23.463.0,14.413.1,43.229.0,31.284.0,54.230.0,44.148.0,51.271.0,44.213.0"}
P.entries["quest:496"] = {n="Эликсир Страдания",s="В Мельнице Таррен аптекарь Лидон исполняет мрачное поручение Королевского фармацевтического общества — создавать смертоносные смеси против живых. Для своих жутких опытов он нанимает путников собирать животные реагенты в окрестных предгорьях.",h="В Мельнице Таррен аптекарь Лидон исполняет мрачное поручение Королевского фармацевтического общества —...",kw={"apothecary lydon","creeper ichor","elixir of suffering","gray bear tongue","hillsbrad foothills","royal apothecary society","tarren mill","аптекарь лидон","ихор ползуна","эликсир страдания","язык серого медведя","предгорья хилсбрада","королевское фармацевтическое общество","мельница таррен"},ang={["faction:Horde"]="Хотя другие союзники из Орды могут опасаться холодной жестокости биологических опытов, защита рубежа Мельницы Таррен от Южнобережья требует доверять алхимической войне Отрекшихся.",["race:Undead"]="Для агентов Отрекшихся помощь Лидону продвигает главную цель Королевского фармацевтического общества: создать разрушительное оружие, чтобы обеспечить выживание их народа среди живых людей."},sec={{t="Ядовитое предприятие",b="Мельница Таррен — военный оплот Отрекшихся в Предгорьях Хилсбрада, но также действующая исследовательская станция Королевского фармацевтического общества. Аптекарь Лидон, живущий среди живописной зелени, ненавидит нетронутую сельскую местность и мечтает увидеть людские поселения отравленными и покоренными. Для своего опытного «Эликсира Страдания» ему нужны местные биологические вещества, известные силой и ядовитостью."},{t="Сбор реагентов",b="Создание алхимических чум требует точных ингредиентов. Лидон посылает охотников в дикие земли вокруг Мельницы Таррен собрать языки местных серых медведей и редкий ихор мшистых ползунов. После очистки нечестивой алхимией эти органические жидкости становятся основой смертоносной смеси, призванной истребить живых захватчиков по всему Хилсбраду."}},faq={{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — член Королевского фармацевтического общества, находящийся в Мельнице Таррен. Верный алхимической традиции Отрекшихся, он ненавидит чистый, живой пейзаж Хилсбрада и посвящает время созданию сильных ядов для истребления людей.",al={"apothecary lydon","who gives elixir of suffering","lydon tarren mill","аптекарь лидон","кто дает эликсир страдания","лидон мельница таррен"}},{q="Зачем Лидону медвежьи языки и ихор ползунов?",a="Лидон исследует ядовитые убийственные вещества, чтобы сварить из них смертоносные смеси. Биологические свойства языков серых медведей и едкие выделения мшистых ползунов дают нестабильную алхимическую основу для его нового Эликсира Страдания.",al={"why bear tongues","what is creeper ichor for","elixir ingredients lore","зачем медвежьи языки","для чего ихор ползунов","ингредиенты эликсира"}},{q="Куда ведет это задание дальше?",a="Когда основные реагенты доставлены, Лидон смешивает их в пробный отвар. Затем он требует испытать смесь, чтобы измерить ее смертоносность на живых существах.",al={"next quest elixir of suffering","what happens after elixir of suffering","следующее задание эликсир страдания","что после эликсира страдания"}},{q="Какова цель Королевского фармацевтического общества в Хилсбраде?",a="Общество действует по приказу леди Сильваны Ветрокрылой, чтобы создать алхимическую чуму, способную истребить и людей, и Плеть. Мельница Таррен — удобный пограничный форпост для сбора биологического материала и испытаний образцов на местных силах Альянса.",al={"why are apothecaries in hillsbrad","forsaken poison goals","hillsbrad plague","зачем аптекари в хилсбраде","цели ядов отрекшихся","чума хилсбрада"}},{q="Где найти нужных существ?",a="Серые медведи бродят по центральным полям и лесам Предгорий Хилсбрада, а мшистые ползуны таятся в зарослях и лесистых местах у Мельницы Таррен.",al={"where are gray bears","where are moss creepers","bear and spider locations","где серые медведи","где мшистые ползуны","где медведи и пауки"}},{q="Почему Лидон в таком дурном настроении?",a="Как и многих алхимиков Отрекшихся, Лидона отвращают жизненная сила, чистый воздух и цветущая природа. Радость он находит лишь в смерти, тлении и удачной перегонке смертельных ядов.",al={"why is lydon unhappy","lydon clean air","почему лидон недоволен","лидон чистый воздух"}}},fp="19,250,18.459.0,18.369.0,24.265.0,51.247.0,32.175.1,62.274.0,43.174.0,32.179.0"}
P.entries["quest:4966"] = {n="Защитить Канати Серое Облако",s="«Защитить Канати Серое Облако» — задание Орды на Заставе Белого Плеса в Тысяче Игл. Искателей приключений предупредили, что кентавры-убийцы охотятся на тауренов Канати Серое Облако, и им предстоит встать рядом с ним и отразить нападение отряда убийц из племени Галак.",h="«Защитить Канати Серое Облако» — задание Орды на Заставе Белого Плеса в Тысяче Игл.",kw={"assassination plot","assassins","centaur","galak","kanati greycloud","thousand needles","whitereach post","заговор убийц","убийцы","кентавры","галак","канати серое облако","тысяча игл","застава белого плеса"},ang={["faction:Horde"]="Застава Белого Плеса служит важным наблюдательным пунктом в Тысяче Игл, и сохранить жизнь таким часовым, как Канати, жизненно важно для обеспечения операций Орды по всему каньону.",["race:Tauren"]="Кровная вражда между тауренами и кентаврами глубока, поэтому защита соплеменника от подлого убийства — вопрос выживания и чести."},sec={{t="Раскрытая засада",b="Находясь среди высоких песчаниковых шпилей Заставы Белого Плеса, таурен Канати Серое Облако узнает из перехваченных приказов кентавров о заговоре с целью убить именно его. Кентавры племени Галак, неустанно враждующие с кочевыми тауренами и их союзниками из Орды, не довольствуются набегами на пути снабжения: они стремятся уничтожить тех, кто селится в их каньонах."},{t="Оборона Заставы Белого Плеса",b="Поняв, что нападение неизбежно и что силы врага могут превосходить его первоначальные оценки, Канати просит путников на заставе сражаться рядом с ним. Когда убийцы Галак наносят удар, Канати стоит насмерть, полагаясь на клинки и заклинания союзников, чтобы сорвать засаду до того, как кентавры получат свою добычу."}},faq={{q="Кто такой Канати Серое Облако?",a="Канати Серое Облако — таурен, устроивший охотничий лагерь на Заставе Белого Плеса в Тысяче Игл, неподалеку от каньонов, которые местные кентавры считают своими.",al={"who is kanati","kanati greycloud lore","who is the quest giver","кто такой канати","канати серое облако предыстория","кто выдает задание"}},{q="Почему кентавры пытаются его убить?",a="Местные кентавры племени Галак считают тауренов и лагеря Орды врагами, вторгшимися на территорию их каньонов. Убив Канати, кентавры намерены избавить каньон от его охотничьего лагеря и от всех, кто мог бы последовать за ним.",al={"why do centaur attack kanati","centaur assassination reason","assassination plot why","почему кентавры нападают на канати","причина покушения кентавров","зачем заговор убийц"}},{q="Где происходит эта оборона?",a="Засада происходит прямо на Заставе Белого Плеса — небольшом форпосте Орды на каньонных тропах Тысячи Игл.",al={"where is this quest","protect kanati location","where does the ambush happen","где это задание","защитить канати местоположение","где происходит засада"}},{q="Какой клан кентавров нападает на Канати Серое Облако?",a="Убийцы принадлежат к племени Галак — самому значительному клану кентавров, населяющему каньоны и ущелья Тысячи Игл.",al={"what tribe attacks","who are the assassins","which centaur","какое племя нападает","кто такие убийцы","какие кентавры"}},{q="Что происходит после поражения убийц?",a="После гибели убийц Галак жизнь Канати спасена, а Застава Белого Плеса остается в безопасности. Канати благодарит защитников за то, что они встали рядом с ним во время внезапного нападения, и на этом цепочка обороны успешно завершается.",al={"what happens next","quest follow up","after protecting kanati","что дальше","продолжение задания","после защиты канати"}},{q="Сражается ли Канати Серое Облако в бою?",a="Да. Канати не трусит и не бежит: он сам вступает в схватку рядом с теми, кто откликнулся на его просьбу, и отбивает убийц, пришедших положить конец его дозору.",al={"does kanati help","kanati fighting","is kanati passive","помогает ли канати","канати сражается","канати пассивен"}}},fp="24,233,18.405.0,25.318.0,24.163.0,46.224.0,35.137.0,44.123.0,46.219.1,42.158.0"}
P.entries["quest:498"] = {n="Спасение",s="«Спасение» — раннее задание Орды, которое выдает Круск в Мельнице Таррен: героям предстоит проникнуть в Крепость Дарнхольд и освободить плененных орков-разведчиков. Лично отобранные Траллом разведчики попали в засаду, когда искали реликвию из прошлого Вождя, и оказались в плену у безжалостных людей-преступников из Синдиката.",h="«Спасение» — раннее задание Орды, которое выдает Круск в Мельнице Таррен: героям предстоит проникнуть в...",kw={"drull","durnholde keep","gol'dir","hillsbrad","krusk","syndicate","tarren mill","tog'thar","друлл","крепость дарнхольд","гол'дир","хилсбрад","круск","синдикат","мельница таррен","тог'тар"},ang={["class:Warrior"]="Освобождение товарищей по переднему краю из плена укрепляет воинское братство перед лицом бесчестных людей-бандитов.",["faction:Horde"]="Это задание знаменует раннюю попытку Орды противостоять расширению Синдиката на спорных холмах Лордерона.",["race:Orc"]="Вид орков-воинов в кандалах в Крепости Дарнхольд напоминает о болезненной истории лагерей, поэтому задание по их освобождению становится глубоко личным."},sec={{t="Неудачная разведка",b="Вождь Тралл отправил отборный отряд орков-воинов в Предгорья Хилсбрада с приказом тихо разузнать о растущей угрозе Синдиката и найти предмет, тесно связанный с историей Крепости Дарнхольд. Под началом Гол'дира разведчики приблизились к руинам крепости. Однако Синдикат подавил их числом, устроив засаду. Воин Круск сумел вырваться и, хромая, добрался через реку до Мельницы Таррен, а его товарищи Друлл, Тог'тар и Гол'дир были взяты живыми и закованы в цепи."},{t="Цепи в руинах",b="Дарнхольд хранит горькие воспоминания для орков: когда-то там располагалась штаб-квартира лагерей для интернированных Эдельаса Черноскала, где пленных орков доводили до апатии и обращали в рабов-гладиаторов. Вновь увидеть своих воинов закованными в железо за потрескавшимися каменными стенами Дарнхольда — невыносимое оскорбление для Орды. Чтобы освободить Друлла и Тог'тара, спасителям придется сразиться с тюремщиками Синдиката, у которых хранятся ключи от оков, а затем выяснить, что стало с их командиром-разведчиком Гол'диром."}},faq={{q="Зачем орков вообще отправили в Крепость Дарнхольд?",a="Вождь Тралл направил Гол'дира и его отряд разведчиков разузнать о бандитах Синдиката и добыть предмет из прошлого Дарнхольда, имеющий для Вождя огромное личное значение.",al={"why were they there","why durnholde","krusk mission","зачем они там были","почему дарнхольд","задание круска"}},{q="Кого нужно спасти из плена?",a="Друлл и Тог'тар — орки-разведчики, посланные Ордой под командованием Гол'дира. Бандиты Синдиката одолели их и заковали в кандалы с ядрами в руинах.",al={"who is drull","who is togthar","who are the hostages","кто такой друлл","кто такой тог'тар","кто заложники"}},{q="Где предводитель отряда, Гол'дир?",a="Когда Друлл и Тог'тар освобождены, Круск узнает, что их командира Гол'дира отделили от основной группы, и Синдикат перевез его в другое, неизвестное место.",al={"where is goldir","find goldir","what happened to goldir","где гол'дир","найти гол'дира","что случилось с гол'диром"}},{q="Кто держит разведчиков в плену?",a="Их удерживает Синдикат — аристократическая преступная сеть, действующая из руин Лордерона и Альтерака; пленных охраняют непосредственно тюремщики Синдиката в Дарнхольде.",al={"who captured them","who are the jailors","who runs durnholde","кто взял их в плен","кто такие тюремщики","кто управляет дарнхольдом"}},{q="К чему ведет эта цепочка заданий?",a="Освобождение разведчиков ведет прямо к заданию выследить Синдикат и проникнуть к нему, чтобы спасти Гол'дира, и в итоге раскрыть замыслы лорда Алидена Перенольда и найти памятную вещь Тареты Фокстон.",al={"what comes next","after the rescue","rescue chain","что дальше","после спасения","цепочка спасения"}},{q="Почему Крепость Дарнхольд имеет особое значение для Орды?",a="Дарнхольд — крепость, где Эдельас Черноскал вырастил Тралла как гладиатора и управлял системой лагерей для интернированных Альянса после Второй войны, пока Тралл не поднял восстание и не разрушил крепость.",al={"history of durnholde","why horde cares about durnholde","история дарнхольда","почему орда дорожит дарнхольдом"}}},fp="10,308,26.534.0,19.512.1,58.191.0,35.181.0,37.182.1,34.173.0,33.205.1,58.215.0"}
P.entries["quest:499"] = {n="Эликсир Страдания",s="В Мельнице Таррен аптекарь Лидон варит ядовитое зелье, которое должно послужить зловещему делу Королевского фармацевтического общества. Чтобы убедиться в его смертоносности, он приказывает немедленно испытать его на живом существе — его несчастном спутнике рядом.",h="В Мельнице Таррен аптекарь Лидон варит ядовитое зелье, которое должно послужить зловещему делу Королевского...",kw={"apothecary lydon","elixir of suffering","hillsbrad foothills","poison","royal apothecary society","tarren mill","toad","umpi","аптекарь лидон","эликсир страдания","предгорья хилсбрада","яд","королевское фармацевтическое общество","мельница таррен","жаба","ампи"},ang={["class:Druid"]="Друиду может показаться глубоко тревожным небрежное, бессердечное отравление безобидного земноводного во имя войны Отрекшихся.",["faction:Horde"]="Союзники, посещающие Мельницу Таррен, видят собственными глазами жуткие алхимические методы, которые применяет Королевское фармацевтическое общество.",["race:Undead"]="Для Отрекшихся испытание смертельных ядов — важнейшее дело в исполнении указа леди Сильваны об истреблении и Плети, и живых."},sec={{t="Ядовитое испытание",b="Аптекарь Лидон неустанно трудится в Мельнице Таррен над химическим оружием, способным исполнить великие замыслы Темной Госпожи: мором, который уничтожит и живых людей Альянса, и нежить Плети. Когда нужные реагенты собраны и настоялись, Лидон смешивает мерзкое варево в то, что называет Эликсиром Страдания, и жаждет увидеть его силу, прежде чем применять его шире."},{t="Судьба Ампи",b="Вместо того чтобы искать вражеского пленника или сбежавшего зверя, Лидон обращается к существу рядом с собой. Он велит искателю приключений дать свежесваренный яд своему помощнику Ампи — безобидной жабе, тихо сидящей у его ног. Одной дозы эликсира оказывается достаточно: земноводное гибнет на месте, и аптекарь убеждается, что его смертоносная формула действует именно так, как задумано."}},faq={{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — алхимик, представляющий Королевское фармацевтическое общество, живущий в поселении Отрекшихся Мельница Таррен в Предгорьях Хилсбрада. Он проводит дни за усовершенствованием ядов и алхимических смесей, призванных истребить врагов Отрекшихся.",al={"lydon","who is lydon","apothecary lydon tarren mill","лидон","кто такой лидон","аптекарь лидон мельница таррен"}},{q="Кто такой Ампи?",a="Ампи — обычная жаба, сидящая прямо возле рабочего стола аптекаря Лидона в Мельнице Таррен; Лидон в шутку назвал ее своим помощником.",al={"what is umpi","umpi the toad","who is the assistant","что такое ампи","ампи жаба","кто помощник"}},{q="Для чего нужен Эликсир Страдания?",a="Эликсир Страдания — экспериментальное химическое оружие, созданное для проверки ядовитых формул, призванных истребить и живых людей, и нежить Плети по воле леди Сильваны Ветрокрылой.",al={"what does the elixir do","why make elixir of suffering","что делает эликсир","зачем делать эликсир страдания"}},{q="Что происходит, если дать зелье Ампи?",a="Lydon asks you to give Umpi a taste to see whether the newly mixed elixir achieves its intended effect. The result is revealed during the test.",al={"does umpi die","what happens to the toad","умирает ли ампи","что случится с жабой"}},{q="Где проходит это испытание?",a="Испытание проходит в городке Отрекшихся Мельница Таррен на севере Предгорий Хилсбрада, прямо у варочной станции Лидона.",al={"where is lydon located","where do i find umpi","где находится лидон","где найти ампи"}},{q="Почему Королевское фармацевтическое общество испытывает яды на мелких животных?",a="Аптекари Отрекшихся обычно используют мелких существ и вредителей для предварительных испытаний, чтобы проверить скорость и смертоносность своих составов, прежде чем перейти к полевым испытаниям на более крупных целях или живых пленниках.",al={"why test on toads","apothecary society animal testing","зачем испытывать на жабах","опыты общества на животных"}}},fp="19,223,12.439.0,16.424.1,24.265.0,12.135.0,47.191.0,46.143.1,32.131.0,68.217.0"}
P.entries["quest:5"] = {n="Урчащий живот Трясунчика",s="Оказавшись один и в ужасе среди руин Вороньего Холма, параноидальный бродяга Трясунчик отчаянно жаждет настоящей еды после долгого питания сорняками и насекомыми. Он умоляет проходящих мимо искателей приключений отправиться на восток в Темнолесье и убедить Шеф-повара Груаля приготовить горячую порцию его знаменитых Темных пирожков с крабами.",h="Оказавшись один и в ужасе среди руин Вороньего Холма, параноидальный бродяга Трясунчик отчаянно жаждет...",kw={"chef grual","crab cakes","darkshire","growling gut","jitters","raven hill","scarlet raven tavern","шеф-повар груаль","пирожки с крабами","темнолесье","урчащий живот","трясунчик","вороний холм","таверна алый ворон"},ang={["faction:Alliance"]="Помощь Трясунчику связывает путников с хрупкими, борющимися поселениями и выжившими, цепляющимися за жизнь в темных уголках Сумеречного леса.",["profession:Cooking"]="Знаменитые Темные пирожки с крабами Шеф-повара Груаля показывают, как мастера кулинарии на границе обходятся местными экзотическими ингредиентами, когда обычные поставки не доходят до Сумеречного леса."},sec={{t="Голод в Вороньем Холме",b="Вороний Холм стал логовом голодной нежити и затаившихся зверей, и чудаковатый отшельник Трясунчик уже несколько недель прячется там в ловушке. Пробираясь под вечным мраком через ветхие лачуги, он выживал лишь на личинках из земли и диких сорняках. Лишенные цивилизованного уюта, его нервы и желудок на пределе."},{t="Мольба о пирожках с крабами",b="В отчаянии, мечтая хоть о чем-то, напоминающем о безопасности, Трясунчик грезит о пряных пирожках из таверны «Алый ворон» в Темнолесье. Он посылает путников по опасной дороге разыскать Шеф-повара Груаля, надеясь, что Груаль согласится испечь порцию Темных пирожков с крабами, чтобы утихомирить свой яростно урчащий живот."}},faq={{q="Кто такой Трясунчик?",a="Трясунчик — напуганный, параноидальный человек, прячущийся в разрушенном поселке Вороний Холм на западе Сумеречного леса. Он до ужаса боится нашествия нежити и постоянно живет в страхе голодной смерти и расправы.",al={"jitters","who is jitters","where is jitters","трясунчик","кто такой трясунчик","где трясунчик"}},{q="Где найти Шеф-повара Груаля?",a="Шеф-повар Груаль работает на кухне таверны «Алый ворон» в Темнолесье, на восточной стороне Сумеречного леса.",al={"chef grual location","find grual","scarlet raven chef","шеф-повар груаль местоположение","найти груаля","повар алого ворона"}},{q="Почему Трясунчик ест личинок?",a="Отрезанный от цивилизации полчищами бродячей нежити и хищных воргенов, Трясунчик несколько недель сидит в ловушке в разрушенном городке Вороний Холм и не имеет другой еды, кроме насекомых и растений, которые удается собрать.",al={"jitters eating bugs","why eats grubs","raven hill food","трясунчик ест жуков","почему ест личинок","еда вороний холм"}},{q="Какого блюда хочет Трясунчик?",a="Трясунчик мечтает о Темных пирожках с крабами — местном фирменном блюде, которое готовит Шеф-повар Груаль в таверне «Алый ворон».",al={"jitters food","crab cakes quest","what does jitters want to eat","еда трясунчика","задание пирожки с крабами","что хочет съесть трясунчик"}},{q="Что происходит после разговора с Шеф-поваром Груалем?",a="Шеф-повар Груаль готов приготовить еду для Трясунчика, но у него нет свежих ингредиентов, и он поручает искателю приключений собрать липкие паучьи лапки для Темных пирожков с крабами.",al={"after jitters growling gut","next quest jitters gut","chef grual task","после урчащий живот трясунчика","следующее задание трясунчика","поручение шеф-повара груаля"}},{q="Могут ли игроки Орды выполнить это задание?",a="Нет. И Трясунчик, и город Темнолесье относятся к Альянсу, поэтому это поручение доступно только искателям приключений Альянса.",al={"is jitters alliance only","horde jitters growling gut","только ли для альянса трясунчик","орда урчащий живот трясунчика"}}},fp="21,286,22.345.0,21.293.0,15.206.0,28.129.0,28.230.0,28.105.0,44.172.1,38.121.0"}
P.entries["quest:501"] = {n="Эликсир боли",s="По поручению аптекаря Лидона из Мельницы Таррен герои Орды должны добыть кровь горных львов, чтобы сварить новое смертоносное зелье. Задание показывает мрачную преданность Королевского фармацевтического общества совершенствованию Новой чумы и его презрение к природной жизненной силе Предгорий Хилсбрада.",h="По поручению аптекаря Лидона из Мельницы Таррен герои Орды должны добыть кровь горных львов, чтобы сварить...",kw={"apothecary lydon","elixir of pain","hillsbrad foothills","mountain lion blood","new plague","royal apothecary society","tarren mill","аптекарь лидон","эликсир боли","предгорья хилсбрада","кровь горного льва","новая чума","королевское фармацевтическое общество","мельница таррен"},ang={["faction:Horde"]="Союзникам Отрекшихся приходится мириться с мрачными методами алхимиков Мельницы Таррен и помогать в добыче диких зверей, чтобы укрепить оплоты Орды против соседних людских угроз.",["race:Undead"]="Для путников из числа Отрекшихся сбор реагентов для аптекаря Лидона напрямую служит воле Темной Госпожи и Королевского фармацевтического общества, утверждающих свои права в Лордероне."},sec={{t="Горький взгляд в Мельнице Таррен",b="Находясь в Мельнице Таррен, аптекарь Лидон не находит радости в окружающем пейзаже. Глядя из окна на цветущие луга и свежий горный воздух Хилсбрада, он считает неугасающую жизнь этого края оскорблением. Как и многие в Королевском фармацевтическом обществе, он предан леди Сильване Ветрокрылой и совершенствованию Новой чумы — созданной искусственно напасти, призванной принести смерть живым и возмездие их врагам."},{t="Ингредиенты для страданий",b="Для своей новейшей ядовитой смеси Лидон обращается к местной фауне, бродящей по предгорьям и склонам в сторону Альтеракских гор. Он полагает, что кровь горных львов обладает особыми свойствами, необходимыми для создания Эликсира боли, и посылает слуг в глушь за десятью пузырьками. Она послужит основой для продолжающихся химических испытаний Общества на спорном южном фронте."}},faq={{q="Кто выдает задание «Эликсир боли»?",a="Задание выдает аптекарь Лидон, алхимик из числа Отрекшихся, находящийся в поселении Мельница Таррен в Предгорьях Хилсбрада.",al={"quest giver elixir of pain","who starts elixir of pain","apothecary lydon quest","кто выдает эликсир боли","кто начинает эликсир боли","задание аптекаря лидона","эликсир боли задание"}},{q="Зачем аптекарю Лидону кровь горных львов?",a="Алхимические исследования Лидона показывают, что кровь горных львов — необходимый реагент для нового смертоносного зелья, эликсира, который должен продвинуть чумные опыты Королевского фармацевтического общества против живых врагов.",al={"why mountain lion blood","lion blood purpose","what is the blood for","зачем кровь горных львов","для чего кровь льва","зачем нужна кровь"}},{q="Где можно найти горных львов?",a="Горные львы бродят по открытым полям и холмам Предгорий Хилсбрада, а также по высоким обрывам, ведущим в Альтеракские горы.",al={"where are mountain lions","mountain lion locations hillsbrad","lion blood farming","где горные львы","горные львы хилсбрад","фарм крови льва"}},{q="Что такое Новая чума, о которой говорит Лидон?",a="Новая чума — биологическое оружие, которое по приказу леди Сильваны Ветрокрылой тщательно разрабатывает Королевское фармацевтическое общество Отрекшихся. Оно предназначено для уничтожения как Плети, так и живых.",al={"what is the new plague","royal apothecary society plague","forsaken plague","что такое новая чума","королевское фармацевтическое общество чума","чума отрекшихся"}},{q="Что будет после выполнения этого задания?",a="Сдача десяти пузырьков крови горных львов ведет прямо к следующему заданию, в котором аптекарь Лидон начинает испытывать свой новый эликсир.",al={"elixir of pain next quest","follow up elixir of pain","what follows elixir of pain","эликсир боли следующее задание","продолжение эликсира боли","что после эликсира боли"}},{q="Почему Лидон презирает пейзажи Хилсбрада?",a="Будучи нежитью на службе Темной Госпожи, Лидон ненавидит цветущую растительность, свежий воздух и неугасимую жизнь этого края и мечтает увидеть, как живой мир задохнется под ядовитыми творениями его Общества.",al={"why does lydon hate hillsbrad","why is lydon brooding","lydon window quote","почему лидон ненавидит хилсбрад","почему лидон мрачен","цитата лидона об окне"}}},fp="14,314,31.477.0,22.426.0,35.138.0,51.232.0,38.160.0,38.222.0,44.159.0,43.207.0"}
P.entries["quest:502"] = {n="Эликсир боли",s="По поручению аптекаря Лидона из Мельницы Таррен агенты Орды должны испытать новое биологическое зелье — Эликсир боли. Аптекарь из Отрекшихся выбирает в качестве ничего не подозревающего подопытного Стэнли, собаку фермера Рэя в Хилсбрадских полях.",h="По поручению аптекаря Лидона из Мельницы Таррен агенты Орды должны испытать новое биологическое зелье —...",kw={"apothecary lydon","elixir of pain","farmer ray","hillsbrad fields","royal apothecary society","stanley","tarren mill","аптекарь лидон","эликсир боли","фермер рэй","хилсбрадские поля","королевское фармацевтическое общество","стэнли","мельница таррен"},ang={["class:Hunter"]="Зрелище того, как кроткий домашний питомец жестоко превращается в дикого мутировавшего хищника, показывает неестественное извращение природы зверей алхимией Отрекшихся.",["faction:Horde"]="Союзников Отрекшихся напрямую вовлекают в их мрачные химические испытания против соседних человеческих ферм Хилсбрада.",["race:Undead"]="Этот опыт показывает безжалостные методы Королевского фармацевтического общества, которое ищет биологическое оружие ради выживания Отрекшихся, не считаясь с побочным ущербом."},sec={{t="Наука аптекарей",b="Работая в Мельнице Таррен, аптекарь Лидон проводит опыты от имени Королевского фармацевтического общества и леди Сильваны Ветрокрылой. Из свежей крови местных животных Лидон готовит нестабильную смесь, которую называет Эликсиром боли. Общество не довольствуется теорией алхимии: ему нужны полевые данные, чтобы наблюдать физиологическое действие экспериментальных ядов и мутагенов."},{t="Испытание на Стэнли",b="Чтобы испытать снадобье, не тревожа людей-защитников Хилсбрада, Лидон велит своим агентам отправиться на северную ферму в Хилсбрадских полях. Там живет Стэнли, с виду безобидная собака фермера Рэя. Агент подходит к ничего не подозревающему псу, налив зелье в ладонь, и дает дозу под видом обычного лакомства."},{t="Жестокая мутация",b="Истинная природа Эликсира боли проявляется сразу после приема. Это не просто смертельный яд, а ужасный мутаген: он вызывает мгновенную агонию и яростно превращает тело Стэнли в свирепого разъяренного волка. Зверь бросается на все вокруг, доказывая силу алхимической формулы Лидона."}},faq={{q="Для чего нужен Эликсир боли?",a="Аптекарь Лидон сварил Эликсир боли в рамках постоянных попыток Королевского фармацевтического общества создать биологическое оружие и сильные мутагены для леди Сильваны и Отрекшихся.",al={"elixir of pain goal","why make elixir of pain","lydon elixir purpose","цель эликсира боли","зачем делать эликсир боли","назначение эликсира лидона"}},{q="Кто такой Стэнли?",a="Стэнли — собака фермера Рэя, живущая возле большого фермерского дома на северной окраине Хилсбрадских полей.",al={"who is stanley","farmer ray dog","stanley the dog","кто такой стэнли","собака фермера рэя","пес стэнли"}},{q="Что произойдет, если дать Стэнли эликсир?",a="После приема эликсира Стэнли жестоко мутирует в свирепого бешеного волка, который тут же становится враждебным и нападает.",al={"stanley transformation","what does elixir do to dog","stanley wolf","превращение стэнли","что эликсир делает с собакой","стэнли волк"}},{q="Где находится Стэнли?",a="Стэнли бродит возле большого дома на северной ферме в Хилсбрадских полях, к юго-западу от Мельницы Таррен.",al={"find stanley","stanley location","where is farmer ray dog","найти стэнли","где стэнли","где собака фермера рэя"}},{q="Кто выдает задание на испытание эликсира?",a="Задание предлагает аптекарь Лидон, находящийся в поселении Отрекшихся Мельница Таррен в Предгорьях Хилсбрада, после того как вы соберете необходимые реагенты.",al={"elixir of pain questgiver","who gives elixir of pain","apothecary lydon quest","кто выдает эликсир боли","персонаж эликсир боли","задание аптекаря лидона"}},{q="Почему зелье испытывают на собаке фермера, а не на людях?",a="Испытание на домашнем животном в Хилсбрадских полях позволяет провести тихий и доступный опыт, не привлекая сразу внимания городского ополчения и вооруженной стражи Хилсбрада к сути алхимических испытаний.",al={"why test on dog","why stanley","why poison dog","почему на собаке","почему стэнли","зачем травить собаку"}}},fp="14,290,18.431.0,18.364.0,16.365.1,42.187.0,15.123.0,46.128.1,25.115.0,39.155.0,56.193.0"}
P.entries["quest:5041"] = {n="Снабжение Перекрестка",s="«Снабжение Перекрестка» — задание Орды от Торка: вернуть важные припасы, захваченные во время набегов свинобразов Иглогривых. Отбивая украденные ящики в колючих лагерях, герои помогают поддерживать Перекресток среди постоянных региональных конфликтов.",h="«Снабжение Перекрестка» — задание Орды от Торка: вернуть важные припасы, захваченные во время набегов...",kw={"barrens","caravan","crates","crossroads","quilboar","razormane","supplies","thork","степи","караван","ящики","перекресток","свинобразы","иглогривые","припасы","торк"},ang={["faction:Horde"]="Удержание Перекрестка необходимо для связи столиц Орды в Дуротаре и Мулгоре; возвращая захваченные грузы, вы помогаете приграничной заставе не остаться без припасов.",["race:Orc"]="Защита этих важных путей снабжения от свинобразов-воров — священный долг по охране растущих поселений новой Орды."},sec={{t="Спасательная нить в осаде",b="Перекресток — главный узел путешествий, торговли и обороны Орды в Степях. Для работы такого центра нужен постоянный поток грузов из Дуротара и Мулгора. Когда караван с припасами попадает в засаду, застава сразу испытывает нехватку провизии, инструментов и оружия, необходимых для жизни в суровой глуши."},{t="Свинобразы-воры",b="Налет совершили свинобразы Иглогривых, местные свиноподобные существа, оспаривающие господство Орды в центральном Калимдоре. Вместо того чтобы уничтожить похищенное, свинобразы утащили тяжелые ящики в свои укрепленные лагеря из колючих кустов, чтобы припрятать их. Торк поручает надежным воинам проникнуть вглубь земель Иглогривых и вернуть то, что по праву принадлежит Орде."}},faq={{q="Кто выдает это задание?",a="Это задание выдает Торк, офицер Орды, руководящий обороной и делами Перекрестка.",al={"quest giver","thork quest","who starts supplies for the crossroads","персонаж, выдающий задание","задание торка","кто начинает снабжение перекрестка"}},{q="Почему припасы вообще были украдены?",a="Караван с припасами, шедший к Перекрестку, попал в засаду агрессивных свинобразов Иглогривых, которые утащили ящики в свои ближние лагеря.",al={"caravan raid","why stolen","what happened to the supplies","налет на караван","почему украдены","что случилось с припасами"}},{q="Где найти украденные ящики?",a="Украденные ящики с припасами для Перекрестка разбросаны по земле в лагерях свинобразов Иглогривых к востоку и северо-востоку от Перекрестка.",al={"crate locations","where are supplies","find crates","где ящики","где припасы","найти ящики"}},{q="Почему Торку так важно вернуть эти припасы?",a="Перекресток — изолированный и оживленный узел, окруженный враждебными угрозами. Потерянные караваны угрожают повседневной работе и безопасности заставы, оставляя и солдат, и путников без необходимого.",al={"why care","crossroads importance","importance of supplies","почему это важно","важность перекрестка","важность припасов"}},{q="Какое задание предшествует этому?",a="Это задание следует за заданием «Прекратить набеги», в котором герои сначала наносят удар по силам Иглогривых, чтобы ослабить их натиск на торговые пути Орды.",al={"prerequisite","prev quest","disrupt the attacks","предыдущее задание","что до этого","прекратить набеги"}},{q="Кто такие Иглогривые?",a="Иглогривые — свирепое, ревниво охраняющее свои земли племя свинобразов, коренных жителей Степей. Они яростно нападают на караваны и оспаривают присутствие Орды на своих исконных землях.",al={"razormane quilboar","who are quilboar","razormane","иглогривые свинобразы","кто такие свинобразы","иглогривые"}}},fp="27,269,22.350.0,17.399.0,21.99.0,48.142.0,37.156.0,55.211.0,29.152.0,22.178.0"}
P.entries["quest:5042"] = {n="Сила Агамаггана",s="Сила Агамаггана — повторяемый ритуал, который предлагает плененный свинобраз Кривозуб в Лагере Таурахо. Получая в обмен красные Кровавые осколки, собранные в Степях, путники обретают могучую физическую силу, которую чтят величайшие воины племени Иглогривых. Она питает горькую месть Кривозуба предавшим его свинобразам из племени Дыбогрив.",h="Сила Агамаггана — повторяемый ритуал, который предлагает плененный свинобраз Кривозуб в Лагере Таурахо.",kw={"agamaggan","barrens","blood shards","bristleback","camp taurajo","mangletooth","quilboar","razormane","агамагган","степи","кровавые осколки","дыбогрив","лагерь таурахо","кривозуб","свинобраз","иглогривые"},ang={["class:Warrior"]="Для воинов, бросающихся в гущу сражений по всему Калимдору, необузданная мощь бога-вепря, которую направляет Кривозуб, дает несомненное физическое преимущество.",["faction:Horde"]="Стражи Лагеря Таурахо надежно держат Кривозуба под замком, но командиры Орды без особых колебаний используют жажду мести старого шамана против враждебных свинобразов.",["race:Tauren"]="Хотя таурены содержат Лагерь Таурахо и настороженно следят за Кривозубом, их шаманы почитают Агамаггана как древнего духа-хранителя земли, пусть даже фанатизм свинобразов исказил память о нем."},sec={{t="Мощь Великого Вепря",b="Свинобразы чтят древнего вепря-полубога Агамаггана: считается, что из его пролитой крови образовались колючие красные Кровавые осколки, разбросанные по Степям. Для свинобразов обращение к этим кристаллам — священный обряд, наделяющий бойцов переднего края устрашающей физической мощью. Находясь в плену в Лагере Таурахо, старый шаман Иглогривых Кривозуб охотно передает эту силу защитникам Орды, уверяя, что ваши враги будут трепетать так же, как перед самыми грозными воинами Иглогривых."},{t="Горькая месть шамана",b="Щедрость Кривозуба целиком продиктована злобой. Старый свинобраз, схваченный и запертый в клетке таурен, питает жгучую обиду на соперничающее племя Дыбогрив, которое винит в своем предательстве и падении. Поскольку он не может разорвать цепи и расправиться с ними сам, он использует древние дары Агамаггана как плату: награждает всякого, кто истребляет племена Дыбогрив и лишает их земли священных Кровавых осколков."}},faq={{q="Что дает Сила Агамаггана?",a="Направляя дремлющую силу полубога-вепря Агамаггана через кристаллические Кровавые осколки, это благословение наделяет получателя возросшей физической мощью, подобной свирепой силе самого яростного авангарда племени Иглогривых.",al={"what does agamaggan's strength do","agamaggans strength buff","strength blessing barrens","что дает сила агамаггана","сила агамаггана бафф","благословение силы степи"}},{q="Кто такой Кривозуб?",a="Кривозуб — пленный свинобраз из племени Иглогривых, которого держат в клетке в Лагере Таурахо на юге Степей. Глубоко озлобленный предательством соперничающего племени Дыбогрив, он охотно обменивает тайны свинобразов и божественные благословения на Кровавые осколки.",al={"who is mangletooth","caged quilboar taurajo","taurajo prisoner","кто такой кривозуб","свинобраз в клетке таурахо","пленник таурахо"}},{q="Что такое Кровавые осколки?",a="Кровавые осколки — красноватые кристаллические минералы, встречающиеся по всем Степям. Предания свинобразов гласят, что эти камни образовались там, где на землю пала кровь их покровителя-полубога, Великого Вепря Агамаггана, во время древней Войны Древних.",al={"what are blood shards","blood shard lore","where do blood shards come from","что такое кровавые осколки","предания о кровавых осколках","откуда берутся кровавые осколки"}},{q="Почему Кривозуб помогает Орде?",a="Помощь Кривозуба питается местью своим же сородичам. Преданный свинобразами Дыбогрив, он охотно дарует защитникам Орды благословения Агамаггана, пока те убивают его соперников и грабят их священные Кровавые осколки.",al={"why is mangletooth helping us","mangletooth motives","why help horde","почему кривозуб помогает нам","мотивы кривозуба","почему помогает орде"}},{q="Можно ли получить это благословение больше одного раза?",a="Да. Когда вы докажете свою стойкость Кривозубу, выполнив его вводное испытание, он будет и дальше навевать Силу Агамаггана и другие дары каждый раз, когда вы принесете ему еще четыре Кровавых осколка.",al={"is agamaggan's strength repeatable","repeatable blood shards","turn in more blood shards","повторяется ли сила агамаггана","повторяемое задание кровавые осколки","сдать еще кровавые осколки"}},{q="Чем отличаются племена Дыбогрив и Иглогривых?",a="Дыбогривы и Иглогривые — соперничающие племена свинобразов, спорящие за Степи. Кривозуб принадлежит к Иглогривым и презирает Дыбогривов, обвиняя их в интригах и в том, что они устроили его заточение.",al={"bristleback vs razormane","quilboar tribes barrens","why does mangletooth hate bristleback","дыбогривы и иглогривые","племена свинобразов степи","почему кривозуб ненавидит дыбогривов"}}},fp="20,359,23.509.0,27.434.0,37.238.0,19.252.0,22.253.0,36.236.0,45.203.0,68.210.0"}
P.entries["quest:5043"] = {n="Ловкость Агамаггана",s="Ловкость Агамаггана — повторяемый ритуал с кровавыми осколками, который предлагает плененный свинобраз Кривозуб в Лагере Таурахо. Принося кристаллические Кровавые осколки, добытые из земли Степей, путники получают благословение безошибочной быстроты и меткости древнего божества-вепря свинобразов.",h="Ловкость Агамаггана — повторяемый ритуал с кровавыми осколками, который предлагает плененный свинобраз...",kw={"agamaggan","agility","barrens","blood shards","mangletooth","quilboar","taurajo","агамагган","ловкость","степи","кровавые осколки","кривозуб","свинобраз","таурахо"},ang={["class:Hunter"]="Ловкость Агамаггана сосредоточена на безошибочной меткости и быстром выслеживании — достоинствах, глубоко ценимых стрелками, пересекающими открытые просторы Калимдора.",["class:Rogue"]="Кривозуб особенно насмехается над быстротой разбойников, не являющихся свинобразами, поэтому этот ритуал становится тихим торжеством, когда священная скорость зверя обращается против племен зарослей.",["faction:Horde"]="Силы Орды в Лагере Таурахо терпят присутствие Кривозуба и сделки с Кровавыми осколками лишь потому, что остаточная сила бога-вепря помогает их нелегкой кампании в Степях.",["race:Tauren"]="Таурены уважают силу Древних, погибших в Войне Древних, хотя сделка с запертым в клетке свинобразом в Таурахо — неловкий компромисс."},sec={{t="Сила Кровавых осколков",b="По всем Степям из почвы торчат странные багровые минералы, известные как Кровавые осколки, особенно рядом со стоянками свинобразов и огромными зарослями терний. Предания свинобразов гласят, что эти кристаллы образовались из пролитой крови Агамаггана, Великого Вепря-Древнего, погибшего в борьбе с Пылающим Легионом в Войне Древних. Даже запертый в деревянной клетке в Лагере Таурахо, старый свинобраз Кривозуб умеет направлять эту дремлющую божественную силу для всякого, кто принесет камни."},{t="Благословение вепрей-разведчиков",b="Охотники и разведчики свинобразов гордятся беспощадной меткостью и ослепительной быстротой в зарослях. За четыре Кровавых осколка Кривозуб призывает скрытую энергию павшего полубога, наделяя просителя хищными инстинктами и гибкой грацией лучших следопытов своего народа. Хотя к чужакам он относится с презрительным ворчанием, Кривозуб чтит уговор, вплетая силу Агамаггана во временный покров ловкости."}},faq={{q="Кто предлагает Ловкость Агамаггана?",a="Задание выдает Кривозуб, геомант-свинобраз, которого держат в плену в клетке в Лагере Таурахо на юге Степей. Несмотря на заточение Ордой, он охотно торгуется с искателями приключений, приносящими ему Кровавые осколки.",al={"who gives quest","quest giver","where is mangletooth","кто дает задание","персонаж, выдающий задания","где кривозуб"}},{q="Что такое Кровавые осколки?",a="Кровавые осколки — кристаллические камни, встречающиеся по всем Степям; их добывают в основном из убитых свинобразов и минеральных выходов близ терновых зарослей. Предания свинобразов гласят, что они образовались тысячелетия назад, когда кровь Великого Вепря-Древнего Агамаггана обагрила землю.",al={"blood shards lore","what is a blood shard","red crystals in barrens","предания о кровавых осколках","что такое кровавый осколок","красные кристаллы в степях"}},{q="Почему плененный свинобраз помогает членам Орды?",a="Верность Кривозуба принадлежит его богу Агамаггану и собственному выживанию. Хотя он презрительно фыркает на всех, кто не свинобраз, он охотно обменивает божественные благословения Агамаггана на Кровавые осколки, что позволяет ему обращаться со священной сущностью своего божества даже из клетки врага.",al={"why help us","mangletooth motives","why does mangletooth talk","почему помогает нам","мотивы кривозуба","почему кривозуб разговаривает"}},{q="Можно ли получить это благословение больше одного раза?",a="Да. Этот ритуал полностью повторяем. Пока вы приносите Кривозубу четыре новых Кровавых осколка, он вновь призывает благословение Великого Вепря.",al={"is this repeatable","can i redo this","repeatable buff","повторяется ли","можно ли повторить","повторяемый бафф"}},{q="Кто такой Агамагган?",a="Агамагган был исполинским вепрем-Древним, ходившим по Калимдору в древнюю мифическую эпоху. Во время Войны Древних десять тысяч лет назад он сражался с демонами Пылающего Легиона и пал. Его кровь питала Степи, породив их непроходимые иглошипы и племя свинобразов.",al={"who is agamaggan","boar god","great boar","кто такой агамагган","бог-вепрь","великий вепрь"}},{q="Какие еще благословения дает Кривозуб?",a="Помимо ловкости, Кривозуб предлагает обряды, чтящие другие стороны Агамаггана. В обмен на Кровавые осколки он может даровать благословения, усиливающие грубую физическую силу, мудрость разума, быстроту бега и кожу, толстую как иглошкура.",al={"other blood shard quests","other buffs","mangletooth rewards","другие задания кровавые осколки","другие бафы","награды кривозуба"}}},fp="19,288,25.518.0,27.440.0,31.224.0,22.268.0,48.269.0,45.152.0,18.305.0,46.237.0"}
P.entries["quest:5044"] = {n="Мудрость Агамаггана",s="Мудрость Агамаггана — повторяемое задание Орды, которое предлагает плененный свинобраз Кривозуб в Лагере Таурахо. Принося Кровавые осколки, собранные по Степям, заклинатели могут приобщиться к ритуальной магии древнего бога-вепря Агамаггана.",h="Мудрость Агамаггана — повторяемое задание Орды, которое предлагает плененный свинобраз Кривозуб в Лагере...",kw={"barrens","blood shards","boar god","camp taurajo","geomancer","mangletooth","quilboar","wisdom of agamaggan","степи","кровавые осколки","бог-вепрь","лагерь таурахо","геомант","кривозуб","свинобраз","мудрость агамаггана"},ang={["class:Mage"]="Маги, увлеченные магическим усилением, оценят первобытную геомантическую силу, которая через сущность Агамаггана направляется в чистый интеллект.",["class:Priest"]="Жрецы, изучающие местные верования, найдут прямую связь между божественной кровью Агамаггана и ритуалами укрепления разума интересной гранью первобытного божественного культа.",["class:Shaman"]="Геомантия свинобразов отражает стихийные призвания шаманизма, поэтому ритуалы осколков бога-вепря знакомы шаманам, но при этом по-своему дики.",["faction:Horde"]="Содержание Кривозуба Ордой в Лагере Таурахо дает воинам и мистикам удобную возможность использовать местную магию Степей против окрестных племен свинобразов."},sec={{t="Кровавые осколки и древняя сила",b="Свинобраз Кривозуб, находящийся в плену у Орды в Лагере Таурахо, обменивает магические тайны своего народа на багровые кристаллы, известные как осколки крови. Согласно верованиям свинобразов, эти осколки образовались из пролитой крови Агамаггана — громадного полубога-вепря, погибшего в Войне Древних. Кривозуб утверждает, что геоманты и шаманы его племен используют эти осколки, чтобы направлять божественную силу в свои обряды."},{t="Благословение разума",b="Если другие дары вызывают из осколков физическую стойкость или быстроту, то ритуал Мудрости направлен строго на интеллект и тайные способности. За четыре Кровавых осколка Кривозуб призывает дух бога-вепря в пользу игрока, желая ему хитрости в схватках, и прощается зловещим напоминанием о смертности."}},faq={{q="Кто такой Агамагган?",a="Агамагган — древний вепрь-полубог, сражавшийся с Пылающим Легионом в Войне Древних десять тысяч лет назад. Он пал в Степях, где его кровь впиталась в почву, породив гигантские терновые лозы и кристаллические Кровавые осколки.",al={"agamaggan lore","who is the boar god","boar ancient","предания об агамаггане","кто такой бог-вепрь","вепрь-древний"}},{q="Почему Кривозуб готов помогать Орде?",a="Кривозуб — плененный свинобраз, которого держат в клетке в Лагере Таурахо. Несмотря на жгучую ненависть его племени к Орде, жажда Кровавых осколков и желание выжить перевешивают его верность, и он дарует священные племенные благословения в обмен на осколки.",al={"why help mangletooth","mangletooth motive","captive quilboar","почему помогать кривозубу","мотив кривозуба","пленный свинобраз"}},{q="Что такое Кровавые осколки?",a="Кровавые осколки — красные минеральные образования, встречающиеся по всем землям свинобразов в Степях. Легенды свинобразов утверждают, что эти кристаллы образовались прямо из капель крови, пролитой полубогом Агамаггана при его гибели.",al={"blood shard lore","what are blood shards","red shards barrens","предания о кровавых осколках","что такое кровавые осколки","красные осколки степи"}},{q="Можно ли повторить этот ритуал больше одного раза?",a="Да. Когда Кривозуб поверит вам после первого показа Кровавых осколков, он будет принимать по четыре Кровавых осколка каждый раз, когда вы захотите обновить благословение.",al={"is wisdom of agamaggan repeatable","repeatable blood shards","turn in again","повторяется ли мудрость агамаггана","повторяемое задание кровавые осколки","сдать снова"}},{q="Поклоняются ли шаманы свинобразов другим божествам?",a="Свинобразы чтят Агамаггана превыше всех остальных, считая себя его прямыми потомками. Их шаманы и геоманты черпают магию природы и власть над землей непосредственно из его мифического наследия и останков.",al={"quilboar religion","geomancer gods","quilboar worship","религия свинобразов","боги геомантов","поклонение свинобразов"}},{q="Где, по словам Кривозуба, может состояться следующая встреча?",a="По завершении ритуала Кривозуб говорит вам рассказать о своей хитрости при следующей встрече, в этой смертной жизни или в следующей, признавая нескончаемое кровопролитие в Степях.",al={"mangletooth next life","mangletooth dialogue","кривозуб следующая жизнь","диалог кривозуба"}}},fp="19,249,30.435.0,20.355.0,17.245.0,45.254.0,22.222.0,40.178.0,41.216.0,57.208.0"}
P.entries["quest:5045"] = {n="Высокий дух",s="Высокий дух — ритуальное благословение, которое предлагает плененный геомант из племени Иглогривых Кривозуб в Лагере Таурахо. В обмен на кровавые осколки, отобранные у его соперников Дыбогривов, Кривозуб направляет древнюю силу Агамаггана, чтобы укрепить силу воли и духовную стойкость героя.",h="Высокий дух — ритуальное благословение, которое предлагает плененный геомант из племени Иглогривых Кривозуб в...",kw={"agamaggan","barrens","blood shards","bristleback","camp taurajo","mangletooth","razormane","rising spirit","агамагган","степи","кровавые осколки","дыбогрив","лагерь таурахо","кривозуб","иглогривые","высокий дух"},ang={["class:Priest"]="Жрецы увидят в единении свинобразов с Агамагганом первобытное выражение веры и духа, не уступающее организованным молитвам восточных церквей.",["class:Shaman"]="Шаманы понимают, как глубоко древние родословные и земные минералы могут связать духов земли со смертным воином.",["faction:Horde"]="Для странников Орды в Степях глубокая племенная ненависть Кривозуба к Дыбогривам превращает назойливого пленника в ценное тактическое преимущество."},sec={{t="Сила воли Иглогривых",b="Старейшина Иглогривых Кривозуб, запертый в клетке в Лагере Таурахо, глубоко сведущ в геомантии свинобразов и магии предков. Пока другие племена хвалятся грубой боевой яростью, Кривозуб гордится духовной преданностью своего народа создателю, Великому Вепрю Агамаггану. Он учит, что несломленный дух поддерживает воина, когда одной силы в бою не хватает, и ведет героев вперед, даже когда поражение кажется неизбежным."},{t="Сила кровавых осколков",b="Чтобы призвать это духовное возвышение, Кривозуб требует кровавые осколки — кристаллизованные фрагменты, пропитанные древней кровью Агамаггана, которая впиталась в красную землю десять тысяч лет назад. Принося ему осколки, собранные по всем Степям, особенно у его врагов Дыбогривов, вы даете ему необходимый духовный проводник, чтобы он сплел благословение высокого духа, укрепляющее вашу волю."}},faq={{q="Кто такой Кривозуб?",a="Кривозуб — старейшина свинобразов из племени Иглогривых, содержащийся в деревянной клетке в Лагере Таурахо. Хотя он пленник Орды, он готов делиться священными геомантическими ритуалами в обмен на кровавые осколки, используя путников для ударов по враждебному племени Дыбогривов.",al={"mangletooth lore","who is the caged boar","taurajo prisoner","кривозуб предания","кто такой кабан в клетке","пленник таурахо"}},{q="Что такое кровавые осколки?",a="Blood shards are red mineral crystals formed from the spilled blood of the Ancient Demigod Agamaggan, who died in the Barrens during the War of the Ancients. They hold potent residual magic that quillboar shamans and geomancers harness for boons and rituals.",al={"what are blood shards","blood shard lore","agamaggan blood","что такое кровавые осколки","предания о кровавых осколках","кровь агамаггана"}},{q="Почему Кривозуб помогает искателям приключений из Орды?",a="Кривозуб питает жгучую ненависть к враждебным свинобразам Дыбогривам. Обменивая благословения на кровавые осколки, он побуждает сильных искателей приключений истреблять Дыбогривов по всем Степям, продолжая вражду своего племени даже в клетке.",al={"why does mangletooth help","why is quillboar helping horde","почему кривозуб помогает","почему свинобраз помогает орде"}},{q="Что дает благословение «Высокий дух»?",a="Высокий дух — мощное благословение предков от Кривозуба, которое усиливает дух и внутреннюю решимость воина, черпая из неиссякаемой жизненной силы Агамаггана, чтобы сохранять надежду в изнурительных сражениях.",al={"rising spirit buff","what is rising spirit","высокий дух бафф","что такое высокий дух"}},{q="Кто такой Агамагган?",a="Агамагган — колоссальный Древний-вепрь, сражавшийся с Пылающим Легионом десять тысяч лет назад во время Войны Древних. Свинобразы почитают его как создателя и верят, что колючие заросли и красные кровавые осколки Степей проросли прямо из его павшего тела.",al={"agamaggan","the great boar","агамагган","великий вепрь"}},{q="Этот ритуал — разовый обмен?",a="Нет. Пока вы приносите Кривозубу четыре кровавых осколка, плененный старейшина готов проводить ритуал снова и снова, обновляя благословение перед тем, как вы отправитесь обратно в пустоши.",al={"repeat rising spirit","is rising spirit repeatable","повторить высокий дух","можно ли повторять высокий дух"}}},fp="13,287,26.448.0,25.406.0,19.267.0,22.258.0,44.251.0,40.214.0,17.277.0,32.184.0"}
P.entries["quest:5046"] = {n="Иглошкура",s="Иглошкура — повторяемый ритуал, который предлагает плененный свинобраз Кривозуб в Лагере Таурахо. Принося ему кровавые осколки, наполненные жизненной сущностью древнего бога-вепря Агамаггана, воины и странники могут получить мощное благословение закаленной кожи и стойкости перед боем.",h="Иглошкура — повторяемый ритуал, который предлагает плененный свинобраз Кривозуб в Лагере Таурахо.",kw={"agamaggan","barrens","blood shards","camp taurajo","mangletooth","quilboar","razorhide","агамагган","степи","кровавые осколки","лагерь таурахо","кривозуб","свинобраз","иглошкура"},ang={["class:Warrior"]="Бойцам передовой, входящим в опасные колючие заросли юга Степей, очень полезны магическая броня и закаленная шкура, смягчающие мощные удары.",["faction:Horde"]="Лагерь Таурахо служит оплотом Орды против постоянного натиска свинобразов, обращая почтение пленного Кривозуба к Агамаггану на пользу путникам.",["race:Tauren"]="Охотники Лагеря Таурахо присматривают за клеткой Кривозуба: хотя обряды свинобразов затрагивают священную землю Матери-Земли, их дикие служители редко делятся тайнами бесплатно."},sec={{t="Благословения бога-вепря",b="Свинобразы ведут свой род и силу прямо от Агамаггана, Великого Вепря, погибшего в битве с Пылающим Легионом тысячи лет назад. Его кровь впиталась в почву Степей и окаменела в кристаллические кровавые осколки, которые до сих пор гудят древней силой. Хотя свинобразы остаются заклятыми врагами Орды, Кривозуб, запертый в клетке в Лагере Таурахо, готов обменять их священные знания на эти драгоценные фрагменты."},{t="Закалка шкуры",b="От природы свинобразы обладают толстой шкурой и защитными иглами, но племенные воины призывают благословение Агамаггана «Иглошкура», чтобы еще лучше защититься от вражеских клинков и когтей. Направляя силу четырех кровавых осколков, Кривозуб воспроизводит этот племенной обряд для чужаков, магически усиливая защиту искателя приключений, чтобы его кости оставались целы, а кожа выдерживала ранения в глуши."}},faq={{q="Кто предлагает ритуал «Иглошкура»?",a="Задание выдает Кривозуб, заключенный свинобраз, которого держат в деревянной клетке в Лагере Таурахо на юге Степей. Когда вы докажете, что знакомы с кровавыми осколками, он предложит разные благословения в обмен на новые.",al={"who gives razorhide","mangletooth quest","who starts razorhide","кто дает иглошкура","задание кривозуба","кто начинает иглошкура"}},{q="Что такое кровавые осколки?",a="Кровавые осколки — кристаллические образования, встречающиеся по всем Степям. По верованиям свинобразов, они образовались из пролитой крови Древнего Вепря Агамаггана во время Войны Древних и хранят огромный запас первобытной магии.",al={"what are blood shards","blood shard lore","blood of agamaggan","что такое кровавые осколки","предания о кровавых осколках","кровь агамаггана"}},{q="Почему пленный свинобраз помогает путникам из Орды?",a="Кривозуб — пленник таурен в Лагере Таурахо. Сохраняя грубый нрав и верность своему богу, он жаждет кровавых осколков и готов учить чужаков обрядам свинобразов, чтобы их получить.",al={"why does mangletooth help","why is mangletooth in taurajo","friendly quilboar","почему кривозуб помогает","почему кривозуб в таурахо","дружелюбный свинобраз"}},{q="Какую защиту олицетворяет «Иглошкура»?",a="Иглошкура олицетворяет племенные обереги, которые свинобразы призывают перед боем. Она утолщает кожу и укрепляет кости, дополняя природную защиту сверхъестественной выносливостью Агамаггана.",al={"what does razorhide do","razorhide lore","protective blessing","что делает иглошкура","предания об иглошкуре","защитное благословение"}},{q="Можно ли получить «Иглошкуру» больше одного раза?",a="Да. Как и все дары Кривозуба, Иглошкура — повторяемый обмен. Всякий раз, когда вы приносите ему четыре кровавых осколка, он призовет благословение для вас.",al={"is razorhide repeatable","repeat razorhide","how many times can i do razorhide","иглошкура повторяется","повторить иглошкуру","сколько раз можно получить иглошкуру"}},{q="Где можно найти кровавые осколки?",a="Кровавые осколки обычно добывают у геомантов, охотников и воинов в разных лагерях свинобразов, зарослях и скалах по всем Степям.",al={"blood shard locations","where to get blood shards","farm blood shards","где найти кровавые осколки","где достать кровавые осколки","фарм кровавых осколков"}}},fp="9,299,25.464.0,18.398.0,32.224.0,22.246.0,54.209.0,49.204.0,41.162.0,32.156.0"}
P.entries["quest:5052"] = {n="Кровавые осколки Агамаггана",s="Кривозуб, плененный свинобраз из племени Иглогривых в Лагере Таурахо, раскрывает священное происхождение кровавых осколков, разбросанных по Степям. Эти красные минералы, наполненные жизненной сущностью павшего полубога Агамаггана, дают мощную магию предков тому, кто умеет направлять их силу. В обмен на осколки злопамятный пленник предлагает Орде первобытные дары своего бога.",h="Кривозуб, плененный свинобраз из племени Иглогривых в Лагере Таурахо, раскрывает священное происхождение...",kw={"agamaggan","barrens","blood shard","bristleback","camp taurajo","mangletooth","quilboar","razorfen","агамагган","степи","кровавый осколок","дыбогрив","лагерь таурахо","кривозуб","свинобраз","иглошкурые"},ang={["class:Shaman"]="Магия, заключенная в кровавых осколках, воплощает первозданную землю и дух, отражая, насколько глубоко созданные титанами и первобытные духи сформировали облик Калимдора.",["faction:Horde"]="Чтобы защитить Лагерь Таурахо, нужно подавить агрессивные племена Дыбогривов и Иглошкурых; используя злобу пленного свинобраза, можно обратить силу их собственного полубога против них.",["profession:Mining"]="Шахтеры, работающие на жилах по всем Степям, могут найти кровавые осколки прямо рядом с оловянной и медной рудой, добывая кристаллизованную кровь Древнего Стража.",["race:Tauren"]="Хотя таурены видят в свинобразах агрессивных соперников за скудную воду и дичь равнин, священная память о жертве Агамаггана в древней войне внушает духовное уважение."},sec={{t="Наследие бога-вепря",b="Согласно преданиям свинобразов, кровь Древнего бога-вепря Агамаггана не только вызвала рост гигантских колючих лабиринтов на засушливых равнинах, когда он пал десять тысяч лет назад во время Войны Древних. Его божественная кровь просочилась глубоко под землю, пропитав подземные минералы и кристаллизовавшись в кроваво-красные камни. Свинобразы чтят эти осколки как священные останки создателя, добывая их из рудных жил и священных мест, чтобы использовать как тотемы битвы и колдовства."},{t="Злоба из деревянной клетки",b="Caged at Camp Taurajo by the tauren, Mangletooth harbors a bitter grudge against his own kind, claiming his tribe betrayed and cast him out. Deprived of his freedom and his connection to the magic of his people, he eagerly strikes a bargain with adventurers. By exchanging blood shards, Mangletooth bypasses his captivity to channel Agamaggan's power directly into Horde champions, gleefully unleashing them as an instrument of vengeance against the very quilboar who turned their backs on him."},{t="Священные корни Иглошкурых",b="В заточении Кривозуб с благоговением говорит о величайшем святилище свинобразов на юге — землях Иглошкурых. Для Дыбогривов и Иглошкурых раскинувшиеся заросли Лабиринтов Иглошкурых и Курганов Иглошкурых буквально образованы колоссальным скелетом и клыками павшего полубога. Он предупреждает, что Курганы Иглошкурых находятся в самой разверстой пасти Агамаггана — священном пороге, который, как говорят, пожирает и сокрушает любых чужаков, вошедших без благосклонности бога-вепря."}},faq={{q="Что такое кровавые осколки?",a="Кровавые осколки — кристаллические красные камни, образовавшиеся, когда кровь Древнего Вепря Агамаггана впиталась в землю во время древней Войны Древних. Они хранят остатки божественной магии свинобразов, и их можно найти в рудных жилах или отобрать у свинобразов, носящих их как тотемы.",al={"what is a blood shard","blood shard lore","where do blood shards come from","что такое кровавый осколок","предания о кровавых осколках","откуда берутся кровавые осколки"}},{q="Почему Кривозуб готов помогать Орде?",a="Кривозуба бросило и предало собственное племя, прежде чем его захватили таурены Лагеря Таурахо. Озлобленный потерей положения и отрезанный от священной силы своего народа, он предлагает усилить искателей приключений из Орды, чтобы они покарали свинобразов, отвергших его.",al={"why does mangletooth help","is mangletooth friendly","why help captive quilboar","почему кривозуб помогает","дружелюбен ли кривозуб","зачем помогать пленному свинобразу"}},{q="Какие усиления дает Кривозуб?",a="Когда вы докажете, что понимаете ценность осколков, Кривозуб принимает кровавые осколки снова и снова в обмен на временные первобытные дары в честь Агамаггана, усиливающие такие качества, как ловкость, сила, интеллект, выносливость, броня и скорость передвижения по Степям.",al={"blood shard buffs","what do i get for blood shards","mangletooth boons","усиления за кровавые осколки","что получить за кровавые осколки","дары кривозуба"}},{q="Где находятся земли Иглошкурых и в чем их значение?",a="Земли Иглошкурых — плотный колючий оплот на самом юге Степей. Свинобразы считают их своим святейшим местом, веря, что высокие заросли выросли прямо из павшего тела Агамаггана, а Курганы Иглошкурых — это его колоссальная пасть.",al={"what is razorfen","why is razorfen holy","razorfen downs lore","что такое иглошкурые","почему земли иглошкурых священны","предания курганов иглошкурых"}},{q="Кем был Агамагган?",a="Агамагган был Древним Стражем — титаническим богом-вепрем, погибшим в битве с Пылающим Легионом десять тысяч лет назад. Из его пролитой крови выросли огромные острые как бритва заросли по всем Степям, а свинобразам он даровал рождение и мистическую силу.",al={"who is agamaggan","boar god","quilboar god","кто такой агамагган","бог-вепрь","бог свинобразов"}},{q="Могут ли шахтеры найти кровавые осколки в Степях?",a="Да. Поскольку кровь Агамаггана пропитала камни и минералы Степей, старатели и шахтеры иногда добывают кровавые осколки вместе с обычными оловянной и медной рудами.",al={"mining blood shards","can i mine blood shards","ore blood shards","добыча кровавых осколков","можно ли добыть кровавые осколки","руда кровавые осколки"}}},fp="25,400,21.504.0,24.494.0,23.451.0,22.288.0,45.279.0,36.262.0,48.269.0,18.264.0,44.174.0"}
P.entries["quest:5061"] = {n="Водный облик",s="Водный облик — завершающий обряд посвящения для друидов Альянса, которые учатся настраивать свой дух на глубокие воды. Собрав разделенные половины Подвески Морского Льва в Калимдоре и Восточных королевствах и скрепив их на Лунной поляне, посвящаемые возвращаются в Дарнасс, чтобы открыть новый облик.",h="Водный облик — завершающий обряд посвящения для друидов Альянса, которые учатся настраивать свой дух на...",kw={"aquatic form","cenarion enclave","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","pendant of the sea lion","sea lion","водный облик","анклав кенария","дарнасс","дендрит блеск звезд","матренгил медвежья лапа","лунная поляна","подвеска морского льва","морской лев"},ang={["class:Druid"]="Это задание — важная веха в вашем единении с природой: вы сможете быстро передвигаться под водой и неограниченно долго дышать под ее поверхностью.",["faction:Alliance"]="Завершение друидических испытаний дает Альянсу разведчиков, способных легко пересекать озера, реки и морские берега.",["race:NightElf"]="Для посвящаемых ночных эльфов возвращение из вневременных лесов Лунной поляны к юной кроне Тельдрассила подтверждает их долг защищать дикую природу Азерота в эпоху меняющегося равновесия."},sec={{t="Священная связь с глубинами",b="Для посвящаемого Круга Кенария превращение — не просто колдовство, а акт духовного единения с дикими силами Азерота. Доказав стойкость в темных прибрежных глубинах и пройдя испытания на Лунной поляне, молодые друиды-ночные эльфы получают собранную Подвеску Морского Льва от Дендрита Блеска Звезд. Доставив этот священный знак в Тельдрассил, посвящаемый доказывает, что чтит законы природы, управляющие воздухом, водой и дыханием."},{t="Возвращение в Дарнасс",b="В ветвях Анклава Кенария возвращения соискателя ждет старший наставник друидов Матренгил Медвежья Лапа. Испытания на побережьях Темных берегов и Западного Края требуют великой выносливости и внутренней гармонии. Предъявив собранную подвеску, посвящаемый показывает Матренгилу Медвежьей Лапе, что его разум и тело готовы сбросить смертный облик и принять быстрый, дышащий облик морского льва."}},faq={{q="Для чего нужно это задание?",a="Это задание — последний шаг в обучении друида Альянса Водному облику. Предъявив восстановленную Подвеску Морского Льва Матренгилу Медвежьей Лапе в Дарнассе, друид получает право на обучение водному облику.",al={"why do this quest","aquatic form purpose","what does this quest give","зачем делать это задание","цель водного облика","что дает это задание"}},{q="Кто отправляет вас обратно в Дарнасс?",a="Дендрит Блеск Звезд, старейшина Круга Кенария, обитающий в священном убежище Лунной поляны, отправляет вас обратно в Тельдрассил после того, как вы успешно завершите Испытание Морского Льва.",al={"who gives this quest","quest giver","dendrite starblaze","кто дает это задание","персонаж, выдающий задания","дендрит блеск звезд"}},{q="Кто завершает ваше обучение в Дарнассе?",a="Матренгил Медвежья Лапа, наставник друидов в Анклаве Кенария в Дарнассе, принимает вашу подвеску и обучает вас водному облику.",al={"quest hand in","who turns in aquatic form","mathrengyl bearwalker","сдача задания","кто принимает водный облик","матренгил медвежья лапа"}},{q="Что такое Подвеска Морского Льва?",a="Подвеска Морского Льва — священный талисман, созданный из двух подвесок испытаний, найденных в морских глубинах у берегов Темных берегов и Западного Края. Она служит осязаемым доказательством того, что друид овладел выносливостью и терпением, которых требуют морские существа.",al={"what is the pendant","pendant of the sea lion lore","что такое подвеска","предание о подвеске морского льва"}},{q="Выполняют ли друиды Орды именно это задание?",a="Нет. Друиды-таурены тоже проходят испытания на Лунной поляне, чтобы получить водный облик, но их путь ведет обратно к Тюраку Руническому Тотему на плато Громового Утеса, а не в Дарнасс.",al={"can tauren do this","is this quest alliance only","horde version","могут ли таурены выполнить это","задание только для Альянса","версия для Орды"}},{q="Где в Дарнассе находится Матренгил Медвежья Лапа?",a="Матренгил Медвежья Лапа живет в Анклаве Кенария, пышном убежище в северо-западном квартале Дарнасса, в ветвях Тельдрассила.",al={"where is mathrengyl","darnassus druid trainer location","где матренгил","наставник друидов дарнасса где"}}},fp="12,331,29.497.0,19.420.0,34.246.0,32.182.0,41.162.0,36.269.0,36.193.0,44.152.0"}
P.entries["quest:5062"] = {n="Священное пламя",s="Священное пламя — обряд посвящения Орды, связывающий изрезанные каньоны Тысячи Игл с высотами Громового Утеса. Чтобы призвать и изгнать мстительного ветряного змея Арикару, охотники должны собрать редкую Огненную агаву у Кипящего озера, чтобы Магата Зловещий Тотем превратила ее в ритуальный порошок.",h="Священное пламя — обряд посвящения Орды, связывающий изрезанные каньоны Тысячи Игл с высотами Громового Утеса.",kw={"arikara","boiling pool","darkcloud pinnacle","elder rise","incendia agave","magatha grimtotem","motega firemane","sacred fire","thousand needles","арикара","кипящее озеро","пик темного облака","вершина старейшин","огненная агава","магата зловещий тотем","мотега огненная грива","священное пламя","тысяча игл"},ang={["class:Shaman"]="Задание показывает практическое применение магии шаманов: стихийная сила может быть влита в природные растения, такие как Огненная агава.",["faction:Horde"]="Выполнение испытаний для старейшин укрепляет связи Орды на засушливых равнинах Калимдора.",["profession:Herbalism"]="У травников есть явное преимущество в поисках колючих кустов Огненной агавы под водой Кипящего озера.",["race:Tauren"]="Для охотников-тауренов почитание духов через ритуальную охоту и умение ориентироваться в политике старейшин на Вершине Старейшин — основа обряда взросления."},sec={{t="Разжечь дух",b="Чудовищного ветряного змея Арикару нельзя просто выследить на дне каньона — ее нужно призвать. Мотега Огненная Грива велит охотникам приготовить священное пламя жизни, древний ритуальный огонь, служащий маяком для духа-зверя. Для него нужно больше, чем обычный хворост, — редкая Огненная агава, растущая только у обжигающих вод Тысячи Игл."},{t="Кипящее озеро",b="Огненная агава растет у Кипящего озера — геотермального водоема у подножия Пика Темного Облака. Чтобы собрать колючее растение, придется пройти через обжигающую воду и нестабильных паровых элементалей, дрейфующих в тумане. Многие кусты растут под водой, и охотнику, посланному за ними, потребуется стойкость."},{t="Благословение старейшины",b="Одна сырая агава не разожжет ритуальную жаровню. Собранные растения нужно отнести высоко над равнинами на Вершину Старейшин в Громовом Утесе. Там старейшина-шаманка Магата Зловещий Тотем применяет свое мастерство, чтобы растереть и зачаровать листья в сильный ритуальный порошок, внешне желая увидеть, как мстительному зверю бросят вызов."}},faq={{q="Что такое священное пламя жизни?",a="Это ритуальный огонь, которым призывают мстительного змея-духа Арикару. Пока это священное пламя не зажжено, зверь остается скрытым и недосягаемым.",al={"sacred fire","what does the fire do","why light the sacred fire","священное пламя","что делает огонь","зачем зажигать священное пламя"}},{q="Где растет Огненная агава?",a="Огненную агаву можно найти в Кипящем озере и рядом с ним в Тысяче Игл, у подножия Пика Темного Облака. Многие колючие растения растут под горячей водой озера.",al={"where to find agave","incendia agave location","boiling pool agave","где найти агаву","где растет огненная агава","агава кипящее озеро"}},{q="Почему Магата Зловещий Тотем должна зачаровать агаву?",a="Сырому растению не хватает магической силы, чтобы зажечь священное пламя. Как могущественная шаманка, Магата вплетает в листья энергию стихий и превращает их в порошок, способный пробудить дремлющее пламя.",al={"why magatha","who enchants the agave","what does magatha do","почему магата","кто зачаровывает агаву","что делает магата"}},{q="Кто такая Арикара?",a="Арикара — грозный ветряной змей, рожденный нести возмездие тем, кто совершает ужасные преступления. Мотега Огненная Грива считает ее присутствие неминуемой опасностью, с которой должны справиться быстрые охотники.",al={"what is arikara","arikara lore","wind serpent boss","кто такая арикара","предание об арикаре","босс ветряной змей"}},{q="Кто выдает задание «Священное пламя»?",a="Мотега Огненная Грива дает задание в Тысяче Игл после того, как вы поможете ему с первыми поручениями, связанными с угрозой местных змеев.",al={"quest giver sacred fire","where to start sacred fire","кто выдает священное пламя","где начать священное пламя"}},{q="Почему Магата улыбается, услышав об Арикаре?",a="Магата находит удовольствие или удовлетворение в упоминании существа, рожденного лишь для наказания мерзких деяний, что намекает на ее мрачный взгляд на месть и племенную политику.",al={"magatha smiling","magatha reaction","why does magatha smile","магата улыбается","реакция магаты","почему магата улыбается"}}},fp="11,304,19.399.0,16.346.0,20.319.1,32.149.0,31.180.0,45.211.0,15.201.0,32.132.0,49.170.0"}
P.entries["quest:5064"] = {n="Наблюдение за Зловещим Тотемом",s="Дозорный утесов Долгорог поручает защитникам Орды проникнуть на Пик Темного Облака и выяснить, что замышляет неуловимый клан Зловещего Тотема. Трех неизвестных гонцов видели на плато, а охраняемые письма разбросаны по их горной деревне. Найдя эти тайные записки, можно раскрыть зреющий замысел, угрожающий поселениям тауренов Тысячи Игл.",h="Дозорный утесов Долгорог поручает защитникам Орды проникнуть на Пик Темного Облака и выяснить, что замышляет...",kw={"cliffwatcher longhorn","darkcloud pinnacle","freewind post","grimtotem","secret notes","spying","tauren","thousand needles","дозорный утесов долгорог","пик темного облака","застава вольного ветра","зловещий тотем","тайные записки","шпионаж","таурены","тысяча игл"},ang={["class:Rogue"]="Добыть три сундука на подвесных мостах и в густо патрулируемых постройках Пика Темного Облака — идеальная тайная операция, где скрытность важнее открытого боя.",["faction:Horde"]="Застава Вольного Ветра — важная линия жизни Орды на юге Калимдора. Любые подрывные замыслы Зловещего Тотема на Пике Темного Облака угрожают хрупким линиям снабжения между Степями и Танарисом.",["race:Tauren"]="Предательство клана Зловещего Тотема больно бьет по тауренам, чье общество ценит гармонию и честь рода. Открытие того, что сородичи тайно встречаются с неизвестными заговорщиками, угрожает всему, что построил Кэрн Кровавое Копыто."},sec={{t="Глаза на ветру",b="Застава Вольного Ветра стоит на высоких шпилях, но ее защитники вынуждены постоянно оглядываться на враждебных сородичей. Клан Зловещего Тотема давно враждебно и обиженно относится к Орде и держится за изолированные твердыни на Пике Темного Облака. Дозорный утесов Долгорог заметил перемену в их поведении, когда в течение нескольких недель прибыли три таинственных агента и тайно совещались с вождями клана. Долгорог подозревает, что эти посланники принесли приказы о выступлении или союзы, направленные против присутствия Громового Утеса в каньоне."},{t="Проникновение на Пик Темного Облака",b="Пик Темного Облака — укрепленная сеть отвесных плато, соединенных веревочными мостами. Чтобы проникнуть в деревню, придется пройти через плотные патрули враждебных воинов и шаманов Зловещего Тотема. Разведчики Долгорога подтвердили, что таинственные письма заперты в отдельных сундуках в центральных жилищах и на внешних утесах поселения. Чтобы добыть три тайные записки, нужно красться или пробиваться через все поселение и выкрасть личную переписку клана из-под бдительных глаз."},{t="Мрачные предзнаменования",b="Три добытые записки, возвращенные Дозорному утесов Долгорогу, подтверждают худшие опасения Заставы Вольного Ветра. Переписка показывает, что Зловещий Тотем не просто бряцает оружием, а активно взаимодействует с внешними агентами для скорого выступления. Хотя весь масштаб их замыслов остается скрытым, Долгорог тут же начинает разрабатывать планы защиты застав каньона от внезапного предательства."}},faq={{q="Кто посылает агентов на встречу со Зловещим Тотемом?",a="Дозорный утесов Долгорог знает лишь, что в последние недели на Пике Темного Облака видели трех агентов неизвестного происхождения. Личность их покровителей строго хранится в тайне в охраняемых записках.",al={"who visited grimtotem","grimtotem secret agents","who sent the notes","кто посещал зловещий тотем","тайные агенты зловещего тотема","кто прислал записки"}},{q="Где находится Пик Темного Облака?",a="Пик Темного Облака расположен в западной части Тысячи Игл, к юго-востоку от Великого Подъемника. Отмеченная синим тотемом тропа ведет по утесам плато в деревню, где деревянные мосты соединяют несколько высоких пиков.",al={"where is darkcloud pinnacle","how to get to darkcloud pinnacle","darkcloud pinnacle entrance","где пик темного облака","как попасть на пик темного облака","вход на пик темного облака"}},{q="Почему Зловещий Тотем враждебен к другим тауренам?",a="Зловещий Тотем считает тауренов выше всех прочих рас и яростно отвергает союз Кэрна Кровавого Копыта с Ордой. Хотя некоторые из Зловещего Тотема живут в Громовом Утесе в хрупком мире, кланы вроде обитающего на Пике Темного Облака открыто враждебны и Орде, и Альянсу.",al={"why do grimtotem hate horde","grimtotem vs thunder bluff","are grimtotem evil","почему зловещий тотем ненавидит орду","зловещий тотем и громовой утес","зловещий тотем злые"}},{q="Кто выдает задание «Наблюдение за Зловещим Тотемом»?",a="Дозорный утесов Долгорог дает задание на Заставе Вольного Ветра в Тысяче Игл, но лишь после того, как вы докажете свою надежность, выполнив прежние поручения заставы.",al={"who starts grimtotem spying","grimtotem spying quest giver","кто начинает наблюдение за зловещим тотемом","наблюдение за зловещим тотемом кто выдает"}},{q="Какие предварительные задания нужны перед этим?",a="Вы должны выполнить задания «Письмо на Заставу Вольного Ветра» и «Умиротворение кентавров», прежде чем Дозорный утесов Долгорог доверит вам шпионскую миссию против Зловещего Тотема.",al={"prereqs for grimtotem spying","how to unlock grimtotem spying","grimtotem spying chain","предыдущие задания наблюдения","как открыть наблюдение за зловещим тотемом","цепочка наблюдения за зловещим тотемом"}},{q="Что происходит, когда вы сдаете три тайные записки?",a="Прочитав их, Дозорный утесов Долгорог потрясен и называет новости мрачными. Он признает, что Застава Вольного Ветра должна срочно подготовить оборону против любого замысла, который готовит Зловещий Тотем.",al={"grimtotem spying completion","what do the notes say","завершение наблюдения за зловещим тотемом","что сказано в записках"}}},fp="16,381,16.574.0,34.512.0,13.410.1,49.216.0,36.216.0,46.303.0,37.166.0,54.181.0,53.213.1"}
P.entries["quest:5088"] = {n="Арикара",s="«Арикара» — завершение зловещего поручения, которое дает Магата Зловещий Тотем в Громовом Утесе. Убежденная, что древний ветряной змей преследует верховного вождя Кэрна Кровавого Копыта, старейшая шаманка посылает приключенцев Орды призвать и убить чудовище на погребальных шпилях Тысячи Игл.",h="«Арикара» — завершение зловещего поручения, которое дает Магата Зловещий Тотем в Громовом Утесе.",kw={"arikara","cairne bloodhoof","darkcloud pinnacle","incendia powder","magatha grimtotem","motega firemane","thousand needles","whitereach post","wind serpent","арикара","кэрн кровавое копыто","пик темного облака","порошок огненной агавы","магата зловещий тотем","мотега огненная грива","тысяча игл","застава белого плеса","ветряной змей"},ang={["class:Shaman"]="Шаманы-приключенцы заметят напряжение между стихийным ритуалом и политической интригой, а также нежелание Мотеги оспаривать непревзойденный духовный авторитет Магаты.",["faction:Horde"]="Воины Орды, поклявшиеся защищать Кэрна Кровавого Копыта, охотно выдвигаются в Тысячу Игл, чтобы устранить любую угрозу почтенному верховному вождю.",["race:Tauren"]="Для тауренов это задание затрагивает противоречие между древними обрядами предков и политическими переменами при Кэрне Кровавом Копыте, в которых посредничает вечно расчетливый клан Зловещего Тотема."},sec={{t="Зверь в дыму",b="Получив очищенный порошок огненной агавы, Магата Зловещий Тотем зачаровывает реагент, чтобы он служил катализатором призыва. Она предупреждает, что древние традиции тауренов слишком быстро изменились под влиянием нового союза Орды и навлекли месть Арикары, свирепого духа ветряного змея. Магата направляет героев на юг, в продуваемый ветрами каньон Тысячи Игл, и велит бросить порошок на ритуальный костер среди возвышенных мест погребения на Пике Темного Облака."},{t="Сомнения на Заставе Белого Плеса",b="Upon slaying the serpent on the burial needle and claiming its skin, adventurers deliver the remains to Motega Firemane at Whitereach Post. Rather than relief, Motega expresses genuine bewilderment. He finds it unbelievable that a primal spirit like Arikara would harbor malice toward Cairne Bloodhoof. Yet, unwilling to openly question Magatha's status as the tribe's most powerful shaman, Motega sets aside his suspicions and rewards the champion for protecting the chieftain."}},faq={{q="Кто такая Арикара?",a="Арикара — могущественный ветряной змей, которого призывают на вершине Пика Темного Облака в Тысяче Игл. Магата Зловещий Тотем утверждает, что зверя подтолкнули к мести современные отступления от традиций тауренов.",al={"what is arikara","arikara lore","who is the serpent","кто такая арикара","арикара предание","кто такой змей"}},{q="Почему Магата Зловещий Тотем хочет смерти Арикары?",a="Магата утверждает, что Арикара охотится на Кэрна Кровавого Копыта, верховного вождя тауренов. Она посылает вас уничтожить змея с помощью зачарованного порошка огненной агавы, пока он не стал угрозой для правителя Громового Утеса.",al={"magatha motivation","why kill arikara","why summon arikara","мотивы магаты","зачем убивать арикару","зачем призывать арикару"}},{q="Где находится священное пламя, чтобы призвать ее?",a="Незажженное священное пламя жизни находится на вершине уединенного шпиля на Пике Темного Облака в Тысяче Игл — возвышенном плато, где местные таурены хоронят своих мертвых.",al={"arikara location","where to summon arikara","sacred fire of life location","где арикара","где призвать арикару","где священное пламя жизни"}},{q="Почему Мотега Огненная Грива сомневается в этой охоте?",a="Magatha fears Arikara may be stalking Cairne and asks you to bring proof of the hunt to Motega. Motega's response is revealed when you deliver the remains.",al={"motega reaction","why is motega confused","cairne arikara make sense","реакция мотеги","почему мотега смущен","кэрн и арикара смысл"}},{q="Действительно ли Кэрну грозит опасность от Арикары?",a="Magatha says she fears Arikara may be stalking Cairne. The quest asks you to act on her warning; it does not establish the danger independently.",al={"was cairne really hunted","did arikara want cairne","magatha lying","охотились ли на кэрна","хотела ли арикара кэрна","магата лжет"}},{q="Какое задание предшествует этому в цепочке?",a="Это задание идет сразу после «Священного пламени», в котором приключенцы собирают огненную агаву в Кипящем озере в Тысяче Игл, чтобы Магата Зловещий Тотем зачаровала ее в порошок.",al={"arikara prereq","quest before arikara","sacred fire quest","предыдущее задание арикара","задание перед арикарой","задание священное пламя"}}},fp="7,290,20.477.0,24.478.1,15.199.0,45.201.0,47.170.0,45.155.1,42.144.1,41.182.0"}
P.entries["quest:509"] = {n="Эликсир агонии",s="В Мельнице Таррен аптекарь Лидон нанимает приключенцев Орды собрать ядовитые грибы на захваченной ферме в Предгорьях Хилсбрада. Эти ядовитые цветки Грязного Рыла — важное сырье для мрачных химических опытов Королевского фармацевтического общества. Полученная смесь должна помочь долгосрочному замыслу леди Сильваны уничтожить и живых, и Плеть.",h="В Мельнице Таррен аптекарь Лидон нанимает приключенцев Орды собрать ядовитые грибы на захваченной ферме в...",kw={"apothecary lydon","elixir of agony","hillsbrad","mudsnout blossom","nethander stead","new plague","royal apothecary society","tarren mill","аптекарь лидон","эликсир агонии","хилсбрад","цветок грязного рыла","владение нетандера","новая чума","королевское фармацевтическое общество","мельница таррен"},ang={["faction:Horde"]="Посланникам Орды в Мельнице Таррен приходится сочетать помощь союзникам-Отрекшимся с тревожной реальностью их химических опытов.",["profession:Herbalism"]="Травники и собиратели распознают в цветке Грязного Рыла редкий, чрезвычайно ядовитый грибной образец, процветающий на необработанной почве, оскверненной обитанием гноллов.",["race:Undead"]="Для агентов Отрекшихся помощь Лидону напрямую способствует жизненно важной работе Королевского фармацевтического общества по защите Лордерона и от человечества, и от Короля-лича."},sec={{t="Чума в разработке",b="Пока Плеть опустошает север, а Альянс держится в таких городах, как Южнобережье, Отрекшиеся ищут собственное расчетливое решение: создание особой смертоносной чумы. Аптекарь Лидон трудится в часовенных лабораториях Мельницы Таррен по поручению Темной Госпожи. Хотя сам он циничен и считает алхимию скучным трудом, Лидон усердно собирает в окрестностях сильные органические яды, чтобы варить эликсиры, способные ускорить взаимное уничтожение врагов Сильваны."},{t="Поля Владения Нетандера",b="К югу от Мельницы Таррен и к востоку от реки лежит Владение Нетандера — заброшенная человеческая ферма, захваченная свирепыми гноллами Грязного Рыла. Среди грязи и запущенной земли разрастаются странные зловонные грибы — цветки Грязного Рыла. Эти крупные едкие грибы содержат концентрированные органические яды, которые высоко ценит Королевское фармацевтическое общество. Чтобы добыть их, нужно пробиваться сквозь стаи гноллов или тихо пробираться мимо их неказистых лагерей."}},faq={{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — алхимик Королевского фармацевтического общества, расквартированный в Мельнице Таррен в Предгорьях Хилсбрада. Действуя от имени леди Сильваны Ветрокрылой, он занимается очисткой смертоносных смесей и разработкой новой чумы, способной сразить и живых смертных, и Плеть.",al={"lydon","who is lydon","apothecary lydon lore","лидон","кто такой лидон","аптекарь лидон предание"}},{q="Для чего нужны цветки Грязного Рыла?",a="Цветки Грязного Рыла — ядовитые зловонные грибы, собираемые во Владении Нетандера. Аптекарь Лидон использует их сильные природные токсичные свойства как основу для варки Эликсира агонии, части более широких исследований Отрекшихся в области химического и биологического оружия.",al={"mudsnout blossoms","what are the mushrooms for","blossom use","цветок грязного рыла","для чего грибы","применение цветков"}},{q="Где находится Владение Нетандера?",a="Владение Нетандера — заросшая ферма к югу от Мельницы Таррен, к востоку от большой реки, протекающей мимо Южнобережья. Ферму заняли агрессивные гноллы Грязного Рыла, которые охраняют поля, где растут грибы.",al={"nethander stead location","where is nethander stead","where are the gnolls","где владение нетандера","владение нетандера расположение","где гноллы"}},{q="Почему Отрекшиеся хотят создать новую чуму?",a="Леди Сильвана и Отрекшиеся ищут оружие, достаточно мощное, чтобы уничтожить и неумолимую Плеть, и враждебные живые расы Альянса. Создавая собственную чуму, Королевское фармацевтическое общество стремится обеспечить суверенитет и выживание Отрекшихся в Лордероне.",al={"why make a plague","forsaken plague reason","sylvanas plague","зачем делать чуму","причина чумы отрекшихся","чума сильваны"}},{q="Почему Лидон жалуется, что должен варить эти эликсиры?",a="Лидон несколько утомлен и мрачен: он замечает, что люди и Плеть и без посторонней помощи стремятся перебить друг друга. Однако поскольку леди Сильвана хочет ускорить их взаимное уничтожение, он выполняет приказы и продолжает варить смертоносные зелья.",al={"lydon attitude","why is lydon cynical","отношение лидона","почему лидон циничен"}},{q="Что происходит после сбора цветков?",a="Получив цветки Грязного Рыла, Лидон приступает к варке ядовитой смеси, и вскоре ему требуются дополнительные ингредиенты и испытания в полевых условиях, чтобы эликсир достиг максимальной смертоносности.",al={"next quest","what follows elixir of agony","следующее задание","что после эликсира агонии"}}},fp="15,377,22.526.0,29.448.0,24.280.0,36.270.0,33.226.0,48.283.0,59.277.0,43.197.0"}
P.entries["quest:513"] = {n="Эликсир агонии",s="Это поручение доставляет свежеразмятую Смесь Грязного Рыла аптекаря Лидона из Мельницы Таррен прямо в сердце Королевского фармацевтического общества в Подгороде. Мастеру аптекарю Фаранеллу нужна растительная масса, чтобы обработать ее коллоидом распада, продвигая разработку новой чумы Отрекшихся.",h="Это поручение доставляет свежеразмятую Смесь Грязного Рыла аптекаря Лидона из Мельницы Таррен прямо в сердце...",kw={"apothecarium","apothecary lydon","colloid of decay","elixir of agony","master apothecary faranell","mudsnout composite","new plague","undercity","апотекариум","аптекарь лидон","коллоид распада","эликсир агонии","мастер аптекарь фаранелл","смесь грязного рыла","новая чума","подгород"},ang={["faction:Horde"]="Орда полагается на территорию Отрекшихся для удержания севера Лордерона, и исследования Королевского фармацевтического общества — важная часть защиты этих уязвимых границ.",["race:Undead"]="Каждая партия сырого растительного материала, доставленная Фаранеллу, способствует конечному выживанию и суверенной обороне Отрекшихся и от живых, и от Плети."},sec={{t="Курьер в столицу",b="В постоянной работе Королевского фармацевтического общества региональные исследователи часто отправляют свои сырые находки в Подгород для особой очистки. Аптекарь Лидон размял местные цветки Грязного Рыла в смесь, но довести ее до смертоносной зрелости можно лишь с помощью передовых реагентов, которые хранятся только в лаборатории столицы."},{t="Спешка мастера",b="Мастер аптекарь Фаранелл работает под огромным давлением в Апотекариуме. Зажатая между постоянной тенью Плети на севере и агрессивным человеческим населением на юге, леди Сильвана Ветрокрылая потребовала могущественную новую чуму для защиты своего народа. Смесь Лидона дает Фаранеллу именно тот токсичный прорыв, которого ждет Темная Госпожа."}},faq={{q="Почему я должен доставить Смесь Грязного Рыла в Подгород?",a="У аптекаря Лидона в Мельнице Таррен нет особых реагентов, нужных для завершения этого этапа опыта. Мастер аптекарь Фаранелл хранит в Апотекариуме коллоид распада, которым нужно обработать Смесь Грязного Рыла, прежде чем она сможет перейти к следующей стадии.",al={"why go to undercity","mudsnout composite destination","why bring to faranell","зачем идти в подгород","куда нести смесь грязного рыла","зачем нести фаранеллу"}},{q="Кто такой Мастер аптекарь Фаранелл?",a="Мастер аптекарь Фаранелл возглавляет Королевское фармацевтическое общество из своей лаборатории в глубинах Подгорода. Он руководит всеми крупными химическими и алхимическими исследованиями Отрекшихся и подчиняется напрямую леди Сильване Ветрокрылой.",al={"who is faranell","master apothecary faranell lore","apothecarium leader","кто такой фаранелл","мастер аптекарь фаранелл предание","глава апотекариума"}},{q="Что за новая чума, о которой постоянно упоминают аптекари?",a="Новая чума — текущий проект Отрекшихся по приказу леди Сильваны. Она создается, чтобы уничтожить и живых, и нежить Плети, дав Отрекшимся абсолютное оружие против врагов.",al={"what is the new plague","forsaken plague project","why make a new plague","что такое новая чума","проект чумы отрекшихся","зачем делать новую чуму"}},{q="Где найти Мастера аптекаря Фаранелла?",a="Фаранелл обитает в Апотекариуме — юго-западном квартале Подгорода, целиком посвященном алхимии, изготовлению ядов и хирургическим опытам.",al={"where is faranell","faranell location","apothecarium location","где фаранелл","фаранелл расположение","где апотекариум"}},{q="Что пытается создать аптекарь Лидон?",a="Лидон готовит Эликсир агонии — крайне ядовитый токсин, сваренный из растений Хилсбрада и агентов распада, призванный доказать эффективность новых штаммов в полевых условиях.",al={"what is lydon making","elixir of agony purpose","lydon experiment","что делает лидон","назначение эликсира агонии","опыт лидона"}},{q="Почему Королевское фармацевтическое общество так торопится?",a="Отрекшиеся видят угрозы со всех сторон. Плеть Нордскола грозит захлестнуть их, а остатки человеческого сопротивления неустанно давят с юга, из-за чего срочно необходимо завершить разработку решающего биологического оружия.",al={"why rush","faranell busy","undercity threat","зачем спешка","фаранелл занят","угроза подгороду"}}},fp="15,304,24.340.0,20.392.0,62.260.0,34.225.0,56.214.0,44.160.0,42.179.0,46.242.0"}
P.entries["quest:5147"] = {n="Разыскивается: Арнак Зловещий Тотем",s="«Разыскивается: Арнак Зловещий Тотем» — награда за голову, объявленная Ордой на Заставе Вольного Ветра: требуется казнить жестокого изгнанника из племени Зловещего Тотема. Местные власти разыскивают Арнака за убийство и похищение человека на плато над каньоном.",h="«Разыскивается: Арнак Зловещий Тотем» — награда за голову, объявленная Ордой на Заставе Вольного Ветра...",kw={"arnak grimtotem","bounty","cliffwatcher longhorn","darkcloud pinnacle","freewind post","lakota windsong","outcast","thousand needles","арнак зловещий тотем","награда за голову","дозорный утесов долгорог","пик темного облака","застава вольного ветра","лакота песня ветра","изгой","тысяча игл"},ang={["faction:Horde"]="Застава Вольного Ветра — жизненно важная артерия Орды в Тысяче Игл, а уничтожение безжалостных отступников на Пике Темного Облака обеспечивает безопасность высот над дном каньона.",["race:Tauren"]="Для тауренов, верных Кэрну Кровавому Копыту, поиск Арнака — акт племенного правосудия: он должен ответить за убийство сородича и похищение Лакоты Песня Ветра, оскорбившие их традиции."},sec={{t="Жестокое преступление",b="Отношения между обычными тауренами Орды и замкнутым племенем Зловещего Тотема всегда были натянутыми, но Арнак зашел гораздо дальше политических трений. Объявленный изгоем, Арнак убил таурена и похитил его сестру, Лакоту Песня Ветра. В ответ на эти гнусные деяния Дозорный утесов Долгорог с Заставы Вольного Ветра объявил открытую награду за смерть таурена-изгоя."},{t="Пик Темного Облака",b="Арнак укрылся на высоких скалах Пика Темного Облака — обширной сети веревочных мостов и стоянок на плато, которые занимает клан Зловещего Тотема, неподалеку от входа в Курганы Иглошкурых. Вместе с Арнаком на этих продуваемых ветрами высотах заперта его пленница Лакота Песня Ветра. Она ждет спасения от любого, кто достаточно храбр, чтобы пробиться через мосты Зловещего Тотема."}},faq={{q="Кто такой Арнак Зловещий Тотем?",a="Арнак Зловещий Тотем — печально известный таурен-изгой, совершивший убийство и похитивший Лакоту Песня Ветра. Из-за его жестоких преступлений Застава Вольного Ветра назначила награду за его голову.",al={"who is arnak","arnak grimtotem lore","who is the wanted tauren","кто такой арнак","арнак зловещий тотем предыстория","кто разыскиваемый таурен"}},{q="Где найти Арнака Зловещего Тотема?",a="Он находится высоко на северных скалистых плато Пика Темного Облака в Тысяче Игл. Туда можно подняться по извилистой тропе к югу от Великого Подъемника и пересечь высокие деревянные мосты в сторону Курганов Иглошкурых.",al={"where is arnak","arnak grimtotem location","how to find arnak","где арнак","арнак зловещий тотем местонахождение","как найти арнака"}},{q="Кто такая Лакота Песня Ветра?",a="Лакота Песня Ветра — пленница-таурен, которую Арнак держит на Пике Темного Облака. Ее брата Арнак убил во время похищения, и она остается на плато, пока с Арнаком не разберутся.",al={"who is lakota","lakota windsong story","кто такая лакота","лакота песня ветра история"}},{q="Кто выплачивает награду?",a="Наградой ведает Дозорный утесов Долгорог на Заставе Вольного Ветра. Он награждает путников, которые приносят отрубленное копыто Арнака как доказательство того, что таурен-изгой предан правосудию.",al={"who turns in arnak","bounty turn in","cliffwatcher longhorn reward","кто принимает арнака","сдать награду","дозорный утесов долгорог награда"}},{q="Действует ли Арнак официально от имени племени Зловещего Тотема?",a="В объявлении Арнак прямо назван изгоем, что указывает: он действовал вне любых племенных законов. Тем не менее он укрылся в оплоте Зловещего Тотема — на Пике Темного Облака.",al={"is arnak with grimtotem","arnak tribe status","арнак со зловещим тотемом","статус арнака в племени"}},{q="Какое доказательство нужно для получения награды?",a="Охотникам нужно отрубить Копыто Арнака и вернуть его Дозорному утесов Долгорогу на Заставе Вольного Ветра, чтобы подтвердить его смерть и получить награду.",al={"what do i bring cliffwatcher longhorn","arnak proof","arnaks hoof","что принести дозорному утесов долгорогу","доказательство арнака","копыто арнака"}}},fp="24,219,16.400.0,18.352.0,23.168.0,35.217.0,23.192.0,29.172.0,52.190.0,43.128.0"}
P.entries["quest:515"] = {n="Эликсир агонии",s="Это поручение продолжает разработку новой чумы Королевского фармацевтического общества: курьер отправляется из Подгорода обратно в Мельницу Таррен. Мастер аптекарь Фаранелл усиливает Микстуру Грязного Рыла Лидона собственными составами гниения и требует прибрежные реагенты и алхимические зелья для запуска смертоносного варева.",h="Это поручение продолжает разработку новой чумы Королевского фармацевтического общества: курьер отправляется...",kw={"daggerspine","elixir of agony","faranell","lydon","mudsnout","tarren mill","torn fin","umpi","undercity","пронзающий гребень","эликсир агонии","фаранелл","лидон","грязное рыло","мельница таррен","рваный плавник","ампи","подгород"},ang={["faction:Horde"]="Мельница Таррен находится на грани постоянных пограничных стычек с Альянсом Южнобережья; ядовитые опыты Лидона призваны изменить баланс сил в регионе.",["race:Undead"]="Каждый очищенный реагент в этой цепочке заданий приближает Королевское фармацевтическое общество к исполнению желания леди Сильваны — создать абсолютное оружие против живых."},sec={{t="Коллоид гниения",b="Когда полевая работа аптекаря Лидона дала мощный состав из Цветков Грязного Рыла, собранных во Владении Нетандера, занятом гноллами, он отправил его прямо в Апотекариум в Подгороде. Мастер аптекарь Фаранелл, глава Королевского фармацевтического общества, сразу понял мрачный потенциал смеси. Обрадованный ее ядовитыми свойствами, Фаранелл добавил в нее свой особый коллоид гниения, а затем изложил, какие катализаторы нужны, чтобы превратить ее в полноценное оружие."},{t="Катализаторы с побережья",b="Для активации нестабильных заразных агентов нужны точные реагенты, которые Лидон должен собрать в Мельнице Таррен. Помимо восстанавливающего зелья из Крепкой крови тролля, питающего и стабилизирующего химическую реакцию, Фаранеллу требуются органические компоненты с южного берега Хилсбрада: чешуя змеевидных нага Пронзающего Гребня и глаза мурлоков Рваного Плавника."},{t="Жестокость в Мельнице Таррен",b="В Мельнице Таррен Лидон коротает часы ожидания в мрачных забавах: он регулярно травит, заражает и поднимает из мертвых свою несчастную подопытную нежить — Ампи. Доставка обогащенной смеси Фаранелла и прибрежных катализаторов приближает аптекаря к конечной цели — созданию нового штамма мучительной порчи, чтобы обрушить его на живые поселения Хилсбрада."}},faq={{q="Зачем для чумы нужен восстанавливающий эликсир из крови тролля?",a="В аптекарских смесях часто используют регенерирующие вещества, чтобы поддерживать, питать и быстро изменять агрессивные биологические агенты. Восстанавливающие свойства Крепкой крови тролля позволяют ядовитым культурам жить достаточно долго, чтобы вступить в реакцию с другими активными тканями.",al={"why troll blood","strong trolls blood purpose","trolls blood elixir plague","зачем кровь тролля","назначение крепкой крови тролля","эликсир из крови тролля чума"}},{q="Где найти чешую нага Пронзающего Гребня?",a="Чешую снимают с враждебных нага Пронзающего Гребня, обитающих на восточных пляжах Предгорий Хилсбрада, на берегу к востоку от города Альянса Южнобережье.",al={"daggerspine scales location","where are naga scales","where to get scales","где чешуя пронзающего гребня","где чешуя нага","где взять чешую"}},{q="Где добыть глаза мурлоков Рваного Плавника?",a="Глаза собирают у мурлоков Рваного Плавника, которые живут племенами на западном побережье Предгорий Хилсбрада, к западу от Южнобережья.",al={"torn fin eye location","where are torn fin murlocs","murloc eyes hillsbrad","глаза рваного плавника","где мурлоки рваного плавника","глаза мурлоков хилсбрад"}},{q="Кто такая Ампи?",a="Ампи — лягушка, которую аптекарь Лидон держит в Мельнице Таррен как своего «помощника». В свободные часы Лидон использует ее как расходного подопытного: раз за разом подвергает смертельным ядам и болезням, а потом снова воскрешает.",al={"who is umpi","umpi hillsbrad","lydon assistant umpi","кто такая ампи","ампи хилсбрад","помощница лидона ампи"}},{q="Почему Мастер аптекарь Фаранелл участвует в этом местном проекте?",a="Как глава Королевского фармацевтического общества, Фаранелл руководит всеми исследованиями новых биологических агентов и чум. Полевые аптекари вроде Лидона отправляют многообещающие находки прямо Фаранеллу в Подгород для доработки и одобрения.",al={"why faranell","master apothecary faranell role","royal apothecary society leader","почему фаранелл","роль мастера аптекаря фаранелла","глава королевского фармацевтического общества"}},{q="Что такое Микстура Грязного Рыла?",a="Это неочищенный ядовитый состав, который Лидон растер из Цветков Грязного Рыла — зловонных грибов, собранных во Владении Нетандера в Предгорьях Хилсбрада, кишащем гноллами. Заметив его необычайную заразность, Лидон отправил его в Подгород, где Фаранелл смешал его с коллоидами гниения, чтобы создать более смертоносную заразу.",al={"mudsnout mixture","gnoll poison","mudsnout composite","микстура грязного рыла","яд гноллов","состав грязного рыла"}}},fp="15,315,18.470.0,24.410.0,22.380.1,63.272.0,39.195.0,37.152.0,12.233.0,65.251.0,29.299.0"}
P.entries["quest:5151"] = {n="Механизм гипервместимости",s="После смертоносной засады кентавров на торговый караван в Тысяче Игл гоблин-изобретатель Визло Фингалет остался единственным выжившим. Отчаянно желая вернуть свое драгоценное изобретение, он нанимает авантюристов, чтобы те проникли в обломки, открыли железную клетку и сняли механизм с шеи свирепого хищника в клетке.",h="После смертоносной засады кентавров на торговый караван в Тысяче Игл гоблин-изобретатель Визло Фингалет...",kw={"centaur caravan","enraged panther","goblin engineering","hypercapacitor gizmo","panther cage key","thousand needles","whitereach post","wizlo bearingshiner","караван кентавров","разъяренная пантера","гоблинская инженерия","механизм гипервместимости","ключ от клетки пантеры","тысяча игл","застава белого плеса","визло фингалет"},ang={["class:Hunter"]="Разъяренная пантера в разбитом караване — необычайно грозный зверь, достаточно свирепый, чтобы напугать целый боевой отряд кентавров-мародеров.",["faction:Horde"]="Разведчики и путники Орды, действующие с Заставы Белого Плеса, непрерывно сражаются с хищными кланами кентавров, угрожающими торговым путям через центральный Калимдор.",["profession:Engineering"]="Лихорадочная погоня Визло за изобретением, назначение которого он толком не помнит, — пример хаотичной философии проб и ошибок, свойственной классической гоблинской инженерии."},sec={{t="Засада в Тысяче Игл",b="Караваны, идущие под высокими песчаными шпилями Тысячи Игл, проходят опасный путь. Враждебные кентавры рыщут по дну каньона, яростно охраняя свою территорию и нападая на всех путников, достаточно смелых, чтобы здесь пройти. Когда один такой торговый караван был разгромлен к северу от Заставы Белого Плеса, кентавры перебили путников и разграбили повозки, оставив лишь гоблина Визло Фингалета, который добрался до безопасного места, прихрамывая."},{t="Неожиданный страж",b="In the chaos of the raid, the centaur looted nearly every valuable scrap, but they gave one ruined wagon a wide berth. Bound inside a sturdy transport cage was a ferocious, enraged panther with Wizlo's prized hypercapacitor gizmo fastened directly around its neck. Daunted by the predator's snarling fury, the centaur abandoned the cage intact, forcing Wizlo to entrust its key to brave mercenaries capable of slaying the beast and reclaiming his gadget."},{t="Амбиции изобретателя",b="Как и подобает гоблину, страсть Визло к механическим чудесам часто опережает практическое понимание. Хотя он называет Механизм гипервместимости своим лучшим творением и рискует жизнями, чтобы вернуть его из лап верховного хищника, после возвращения он признает, что ему еще предстоит повозиться с ним, чтобы понять, что он на самом деле делает."}},faq={{q="Кто такой Визло Фингалет?",a="Визло Фингалет — гоблин-изобретатель и торговец, укрывшийся на Заставе Белого Плеса после того, как его караван был подвергнут засаде и уничтожен кентаврами на дне каньона Тысячи Игл.",al={"who is wizlo","wizlo bearingshiner lore","quest giver wizlo","кто такой визло","визло фингалет предыстория","визло персонаж, выдающий задания"}},{q="Почему механизм оказался на шее пантеры?",a="Во время перевозки или в хаосе засады кентавров устройство оказалось закрепленным на шее плененного зверя. Поскольку пантера была так страшна, нападавшие кентавры отказались прикасаться к клетке, невольно сделав хищника стражем устройства.",al={"why does the panther have the gizmo","panther necklace","collar gizmo","почему у пантеры механизм","ожерелье пантеры","механизм на шее"}},{q="Где находится разбитый караван?",a="Разбитый караван лежит к северу от Заставы Белого Плеса в Тысяче Игл, среди обломков повозок, окруженный враждебными лагерями кентавров.",al={"caravan location","where to find panther cage","cage location","где караван","где найти клетку с пантерой","где клетка"}},{q="Почему кентавры не разграбили клетку?",a="По словам Визло, разъяренная пантера настолько свирепа, что даже безжалостные кентавры-мародеры дрожали в ее присутствии и предпочли оставить зверя запертым в клетке, не рискуя ее открывать.",al={"why centaur left panther","centaur afraid of panther","why is cage untouched","почему кентавры оставили пантеру","кентавры боятся пантеры","почему клетка цела"}},{q="Что на самом деле делает Механизм гипервместимости?",a="Визло называет его своим лучшим механизмом, но, получив его обратно, признается, что ему еще нужно время, чтобы изучить его и повозиться с ним, чтобы понять, какую функцию он выполняет.",al={"what does gizmo do","hypercapacitor function","what is the gizmo","что делает механизм","функция гипервместимости","что за механизм"}},{q="Кому принадлежит Застава Белого Плеса?",a="Застава Белого Плеса — поселение тауренов, союзное Орде, расположенное среди плато каньона, чтобы следить за действиями кентавров и давать безопасный приют путникам Орды.",al={"whitereach post faction","is whitereach horde","фракция заставы белого плеса","застава белого плеса орда ли"}}},fp="20,320,21.433.0,20.454.0,19.336.1,27.185.0,43.260.0,37.143.0,37.198.0,47.187.1,29.165.0"}
P.entries["quest:516"] = {n="Погибель Берена",s="«Погибель Берена» — задание Орды, которое выдает жрец Тени Алистер из Гробницы. Агенты Отрекшихся узнали о тайном сборище Плети в уединенной пещере на юге холмов Серебряного бора и хотят уничтожить ее воинов до начала наступления.",h="«Погибель Берена» — задание Орды, которое выдает жрец Тени Алистер из Гробницы.",kw={"ambermill","beren's peril","berens peril","ravenclaw drudger","ravenclaw guardian","scourge","shadow priest allister","silverpine forest","the sepulcher","янтарная мельница","погибель берена","чернорабочий когтя ворона","страж когтя ворона","плеть","жрец тени алистер","серебряный бор","гробница"},ang={["class:Priest"]="Выполняя приказы жреца Тени Алистера, темные заклинатели помогают укреплять власть Гробницы, истребляя соперничающих ужасов из нежити.",["faction:Horde"]="Зачистка скрытых очагов Плети на границах Серебряного бора помогает укрепить положение северного Лордерона для всей Орды.",["race:Undead"]="Для Отрекшихся искоренение остатков Плети, таких как в Погибели Берена, — вопрос выживания, укрепляющий их суверенитет вопреки остаточной власти Короля-лича."},sec={{t="Упреждающий удар",b="Жрецу Тени Алистеру в Гробнице стало известно, что безмозглые слуги Короля-лича собираются в глубине южной части Серебряного бора. Если не вмешаться, эти силы Плети станут непосредственной угрозой для действий Отрекшихся по всему региону. Не дожидаясь нападения, Алистер велит разведчикам действовать первыми и уничтожить скопище в его укромном логове, пока оно не пришло в движение."},{t="Тайная пещера",b="Погибель Берена — малозаметная сеть пещер в холмах к югу от Янтарной мельницы, поселения под покровительством Даларана. Из-за коварной местности пещеру легко не заметить: к ней можно подойти, лишь обогнув южные склоны. В ее тенях обитают чернорабочие и стражи из Когтя Ворона — закрепившиеся остатки чумы, уничтожение которых помогает Отрекшимся удерживать шаткую власть над лесом."}},faq={{q="Что такое Погибель Берена?",a="Погибель Берена — уединенная пещера в гористых холмах южной части Серебряного бора, к югу от Янтарной мельницы. Она служит убежищем для остатков Плети — нежити Когтя Ворона.",al={"berens peril","where is berens peril","what is this cave","погибель берена","где погибель берена","что за пещера"}},{q="Кто выдает задание, связанное с Погибелью Берена?",a="Жрец Тени Алистер, находящийся в Гробнице в Серебряном бору, дает задание искателям приключений из Орды, узнав, что враждебная нежить готовит наступление из этой пещеры.",al={"who gives berens peril","quest giver berens peril","shadow priest allister quest","кто дает погибель берена","персонаж, выдающий задание погибель берена","задание жреца тени алистера"}},{q="Почему Отрекшиеся нападают там на нежить?",a="Нежить в Погибели Берена верна Королю-личу и входит в состав Плети. Отрекшиеся освободились от власти Короля-лича и активно борются за то, чтобы очистить свои земли от его оставшихся приспешников.",al={"why kill undead","why fight ravenclaw","arent forsaken undead","почему убивать нежить","почему сражаться с когтем ворона","разве отрекшиеся не нежить"}},{q="Как найти вход в пещеру?",a="Пещера скрыта в холмах к югу от Янтарной мельницы. Из-за крутых хребтов к входу нужно подходить с южной стороны холмов, а не напрямую с севера.",al={"how to get to berens peril","cave entrance location","where is the cave entrance","как добраться до погибели берена","где вход в пещеру","расположение входа в пещеру"}},{q="Какие враги обитают в Погибели Берена?",a="В пещере обитают рабы Плети, в частности чернорабочие Когтя Ворона и стражи Когтя Ворона, которые, по всей видимости, собираются для нападения на ближайшие поселения.",al={"berens peril mobs","what is inside berens peril","погибель берена мобы","что внутри погибели берена"}},{q="Какую роль играет Даларан в этом задании?",a="Даларан не играет прямой роли в самом задании, хотя находящуюся неподалеку Янтарную мельницу занимают человеческие маги из Даларана. Алистер упоминает их лишь как ориентир, чтобы разведчики нашли тайную пещеру.",al={"dalaran connection","ambermill connection","связь с даларан","связь с янтарной мельницей"}}},fp="13,289,19.433.0,15.428.0,22.200.0,41.184.0,48.209.0,41.183.0,35.168.0,44.196.0"}
P.entries["quest:517"] = {n="Эликсир агонии",s="Это задание — четвертая глава неустанной работы аптекаря Лидона над разрушительным ядом Отрекшихся в Мельнице Таррен. Когда смертоносный Эликсир агонии наконец сварен, Лидон отправляет героев Орды в Дун Гарок похитить бочонок дворфийского «Шиндигера» для доставки.",h="Это задание — четвертая глава неустанной работы аптекаря Лидона над разрушительным ядом Отрекшихся в Мельнице...",kw={"apothecary lydon","dun garok","dwarves","elixir of agony","hillsbrad","shindigger stout","tarren mill","umpi","аптекарь лидон","дун гарок","дворфы","эликсир агонии","хилсбрад","шиндигер","мельница таррен","ампи"},ang={["class:Rogue"]="Незаметно проскользнуть по людным столовым Дун Гарока — образец скрытного воровства прямо под носом у горных пехотинцев.",["faction:Horde"]="Подрыв присутствия Альянса в Дун Гароке помогает Мельнице Таррен удерживать шаткие позиции перед лицом неослабевающих угроз с юга.",["race:Dwarf"]="Превращение традиционного дворфийского эля в сосуд для химической бойни — глубокое оскорбление мастерства Стальгорна.",["race:Undead"]="Каждая партия, доведенная Лидоном до совершенства, приближает Отрекшихся к превращению смерти в оружие против живых врагов, подступающих к Лордерону."},sec={{t="Горькое варево",b="В сырых закоулках Мельницы Таррен аптекарь Лидон неустанно трудится на благо Королевского фармацевтического общества и леди Сильваны. Собрав смертоносные ингредиенты по всему Хилсбраду, он закончил свое новое зелье. Лидон не намерен тратить столь сильный состав на лягушек или бродячих собак: ему нужна настоящая проверка на живых противниках."},{t="Проникновение в Дун Гарок",b="Для своего опыта Лидону нужно неприметное средство доставки. К югу от Хилсбрада дворфы Стальгорна укрепили оплот Дун Гарок. Лидон велит агентам Орды проникнуть в подземные казармы и столовые, проскользнуть мимо дворфийских ружей и топоров и стащить ценный бочонок «Шиндигера»."},{t="Рецепт катастрофы",b="Лидон собирается подмешать свой смертоносный яд прямо в любимый напиток дворфов. После того как эликсир попадет в украденный бочонок, его можно будет подсунуть ничего не подозревающей цели под видом праздничного угощения, превратив любимый дворфийский стаут в орудие ужасной агонии."}},faq={{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — алхимик из числа Отрекшихся, находящийся в Мельнице Таррен. Представляя Королевское фармацевтическое общество, он проводит опыты по созданию смертоносных чум и эликсиров для Королевы банши, леди Сильваны.",al={"lydon","who gives this quest","apothecary lydon lore","лидон","кто дает это задание","аптекарь лидон предыстория"}},{q="Зачем Лидону бочонок «Шиндигера»?",a="Лидон хочет испытать готовый Эликсир агонии на живых целях. Подмешав яд в бочонок популярного дворфийского эля, он получает скрытый и действенный способ отравить своих жертв.",al={"why dwarven beer","why shindigger stout","purpose of the keg","почему дворфийское пиво","почему шиндигер","зачем бочонок"}},{q="Где находится Дун Гарок?",a="Дун Гарок — сильно укрепленный дворфийский редут на юго-востоке Предгорий Хилсбрада; его занимают горные пехотинцы и ружейники Стальгорна, охраняющие свои северные интересы.",al={"where is dun garok","dun garok location","where do i find the keg","где дун гарок","расположение дун гарока","где найти бочонок"}},{q="Кто такой Ампи?",a="Ампи — помощник аптекаря Лидона в Мельнице Таррен. Лидон шутливо замечает, что когда в лаборатории открывают банки с формальдегидом, Ампи заметно нервничает.",al={"umpi","who is umpi","lydon assistant","ампи","кто такой ампи","помощник лидона"}},{q="Какова конечная цель Эликсира агонии?",a="Эликсир агонии — экспериментальный яд, созданный Королевским фармацевтическим обществом для истребления живых; он служит кампании Отрекшихся по защите Лордерона от опорных пунктов людей и дворфов.",al={"what does elixir of agony do","plague purpose","forsaken poison goal","что делает эликсир агонии","цель чумы","цель яда отрекшихся"}},{q="Что будет после получения бочонка?",a="Когда бочонок окажется у вас, Лидон подмешает в «Шиндигер» ядовитый эликсир и поручит вам доставить отравленный эль ничего не подозревающей подопытной цели.",al={"next quest","what after dun garok","elixir part 5","следующее задание","что после дун гарока","эликсир часть 5"}}},fp="15,277,13.380.0,22.329.0,21.278.1,24.209.0,46.194.0,27.175.0,12.159.0,49.199.0,41.158.1"}
P.entries["quest:52"] = {n="Защита границы",s="«Защита границы» — задание Альянса, которое выдает Стражник Томас у восточного моста в Элвиннском лесу. Из-за ослабления военного присутствия Штормграда у границы дикие хищники осмелели и донимают путников и рабочих Лесопилки Восточной долины. Стражнику Томасу нужны умелые герои, чтобы проредить волков и медведей, угрожающих восточной границе.",h="«Защита границы» — задание Альянса, которое выдает Стражник Томас у восточного моста в Элвиннском лесу.",kw={"eastvale logging camp","elwynn forest","gray forest wolf","guard thomas","protect the frontier","prowler","young forest bear","лесопилка восточной долины","элвиннский лес","серый лесной волк","стражник томас","защита границы","подкрадывающийся хищник","молодой лесной медведь"},ang={["class:Hunter"]="Волки и медведи, рыщущие на востоке Элвиннского леса, — первое испытание навыков выслеживания и меткости на свирепой местной дичи.",["faction:Alliance"]="Обеспечение безопасности восточных дорог помогает сохранить поставки древесины из Восточной долины, поддерживая восстановление и оборону по всем землям Альянса."},sec={{t="Ослабевшая оборона",b="Хотя в Златоземье и Долине Североземья заметен гарнизон Штормграда, дальний восточный край Элвиннского леса защищен куда хуже. Стражник Томас стоит на посту у моста через реку и остается одним из немногих часовых между обжитыми землями и опасной глушью. Из-за нехватки ресурсов по всему королевству одинокие стражники полагаются на добровольцев, чтобы сохранить важные торговые пути."},{t="Угроза хищников",b="Лесопилка Восточной долины важна для поставок древесины в Штормград, но рубка деревьев у опушки приводит дровосеков к прямому столкновению с местной живностью. Подкрадывающиеся хищники, серые лесные волки и молодые лесные медведи становятся все агрессивнее и бродят возле дорог и лесных складов. Сокращение их числа временно облегчает положение рабочих, хотя Стражник Томас подозревает, что невидимая угроза в глубине леса гонит зверей к поселениям."}},faq={{q="Кто выдает задание «Защита границы»?",a="Задание дает Стражник Томас. Он стоит у восточного моста на главной дороге через Элвиннский лес и охраняет границу между глубиной леса и Восточной долиной.",al={"quest giver protect the frontier","who starts protect the frontier","guard thomas quest","кто выдает защиту границы","кто начинает защиту границы","задание стражника томаса"}},{q="Почему волки и медведи нападают на границу?",a="Агрессивные хищники часто выходят на дороги и рабочие участки возле Лесопилки Восточной долины. Хотя волки и медведи по природе территориальны, Стражник Томас отмечает, что нечто в глубине окрестной глуши, судя по всему, беспокоит их и гонит к людям.",al={"why are bears aggressive","why are wolves attacking eastvale","animal attacks elwynn","почему медведи агрессивны","почему волки нападают на восточную долину","нападения животных элвинн"}},{q="Где находится Лесопилка Восточной долины?",a="Лесопилка Восточной долины находится на востоке Элвиннского леса, чуть восточнее моста Стражника Томаса. Она поставляет необходимый лес для Штормграда и приграничных поселений.",al={"eastvale location","where is logging camp elwynn","eastvale camp","расположение восточной долины","где лесопилка элвинн","лагерь восточной долины"}},{q="Почему Стражник Томас охраняет мост в одиночку?",a="Регулярная армия и городская стража Штормграда крайне малочисленны на просторах королевства. На сторожевых постах у рек и дальних перекрестков часто стоят один-два стражника, поэтому для борьбы с крупными угрозами со стороны зверей приходится рассчитывать на странствующих героев.",al={"why is guard thomas alone","guard thomas post","stormwind guards eastvale","почему стражник томас один","пост стражника томаса","стража штормграда восточная долина"}},{q="Каких животных нужно истребить в этом задании?",a="Вам нужно убить восемь волков (подкрадывающихся хищников или серых лесных волков) и пять молодых лесных медведей, бродящих по лесам восточной части Элвиннского леса.",al={"protect the frontier targets","wolves and bears to kill","what mobs for protect the frontier","цели защиты границы","волки и медведи для убийства","какие мобы для защиты границы"}},{q="Что происходит после истребления зверей?",a="Доклад Стражнику Томасу приносит его благодарность и делает путь для лесозаготовительных караванов безопаснее. Однако он опасается, что темное влияние, растревожившее зверей, может принести лесу новые беды.",al={"protect the frontier follow up","turn in protect the frontier","продолжение защиты границы","сдать защиту границы"}}},fp="20,389,18.434.0,20.498.0,41.186.0,48.288.0,35.155.0,46.294.0,45.152.0,41.219.0"}
P.entries["quest:524"] = {n="Эликсир агонии",s="Эликсир агонии — итог зловещих алхимических опытов аптекаря Лидона в Мельнице Таррен. По поручению Королевского фармацевтического общества Лидон намерен испытать смертельный яд, замаскированный под украденный дворфийский эль, на пленных людях, содержащихся в поселении.",h="Эликсир агонии — итог зловещих алхимических опытов аптекаря Лидона в Мельнице Таррен.",kw={"apothecary lydon","captured farmers","dun garok","elixir of agony","high executor darthalia","hillsbrad","tainted keg","tarren mill","аптекарь лидон","пойманные крестьяне","дун гарок","эликсир агонии","верховный палач дарталия","хилсбрад","отравленный бочонок","мельница таррен"},ang={["faction:Horde"]="Этот мрачный эксперимент показывает темные, неприкрашенные стороны действий Отрекшихся и проверяет моральную стойкость других рас Орды, помогающих в Мельнице Таррен.",["race:Human"]="Убийство беспомощных лордеронских крестьян показывает холодную расчетливую жестокость, с которой Отрекшиеся относятся к своим бывшим живым сородичам.",["race:Undead"]="Для Отрекшихся совершенствование ядов Королевского фармацевтического общества крайне важно для выживания: оно любой ценой оберегает Предгорья Хилсбрада от возрождения людей."},sec={{t="Смертельный напиток",b="По всем Предгорьям Хилсбрада аптекарь Лидон собирает мерзкие ингредиенты и похищенный дворфийский эль из горной крепости Дун Гарок. Цель его проста и безжалостна: по поручению Королевского фармацевтического общества создать губительное новое зелье — Эликсир агонии. Смешанная темная жидкость помещается в с виду безобидный бочонок горного крепкого эля и ждет, когда сможет показать свою силу."},{t="Несчастные гости",b="Стражи смерти в Мельнице Таррен недавно согнали местных крестьян-людей, подозревая, что среди них скрывается неуловимый штормградский военный стратег. Когда пришла весть, что стратег погиб в Чумных землях, Верховный палач Дарталия решила, что уцелевшие селяне бесполезны для военной разведки. Вместо того чтобы отпустить их, она отдала их Лидону в качестве подопытных для его химических испытаний."},{t="Испытание зелья",b="Отравленный бочонок относят наверх, в камеру, и ставят на пыльный ковер перед изнывающими от жажды пленниками. Мучимые жаждой и не ведающие о жестокости Лидона, крестьяне жадно бросаются к бочке. Яд действует с ужасающей быстротой: спустя считаные мгновения после глотка дворфийского эля несчастные пленники падают замертво, доказывая сокрушительную смертоносность эликсира."}},faq={{q="Почему крестьян-людей вообще схватили?",a="Стражи смерти задержали их по подозрению, что военный стратег Королевства Штормград укрылся в их общине. Когда стратега нашли мертвым в Чумных землях, пленники перестали представлять для Верховного палача Дарталии ценность как источник сведений.",al={"why prisoners","why farmers locked up","tarren mill prisoners","почему пленники","почему крестьяне под замком","пленники мельницы таррен"}},{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — член Королевского фармацевтического общества Отрекшихся, расквартированный в Мельнице Таррен. Он создает и испытывает смертоносные хвори и яды, призванные истребить живых, часто используя в качестве подопытных пойманных местных жителей.",al={"apothecary lydon lore","who is lydon","lydon tarren mill","аптекарь лидон","кто такой лидон","лидон мельница таррен"}},{q="Откуда взялся эль в бочонке?",a="Эль был украден прямо у дворфов Дун Гарока — крепкой горной твердыни на юге Предгорий Хилсбрада. Лидон отравил украденную бочку своими едкими реагентами, чтобы смертельный яд выглядел как обычный дворфийский эль.",al={"source of the ale","dun garok ale","keg origin","источник эля","эль дун гарока","происхождение бочонка"}},{q="Что происходит, когда вы доставляете отравленный бочонок?",a="Когда отравленный бочонок ставят на ковер в их камере, изнывающие от жажды крестьяне тут же бросаются к нему и пьют. Через несколько секунд ядовитое зелье начинает действовать и убивает их всех на месте.",al={"what happens to the farmers","farmers drink keg","plagued brew result","что случится с крестьянами","крестьяне пьют из бочонка","результат зараженного эля"}},{q="Кто разрешил использовать пленников для испытаний?",a="Верховный палач Дарталия, командующая силами Отрекшихся в Мельнице Таррен, передала уцелевших пленников аптекарю Лидону, когда они перестали быть нужны ей в военных целях.",al={"who let lydon test on farmers","darthalia role","darthalia prisoners","кто разрешил лидону опыты на крестьянах","роль дарталии","дарталия пленники"}},{q="Чего добивается здесь Королевское фармацевтическое общество?",a="Королевское фармацевтическое общество неустанно трудится над созданием смертоносной хвори, способной уничтожить и Плеть, и живых. Полевые опыты вроде Эликсира агонии позволяют проверять новые способы доставки яда и определять степень его токсичности для человеческого организма.",al={"apothecary goals hillsbrad","why make elixir of agony","forsaken blight testing","цели аптекарей хилсбрад","зачем создавать эликсир агонии","испытания хвори отрекшихся"}}},fp="15,256,16.414.0,18.438.1,16.389.1,55.267.0,24.226.0,43.236.0,46.212.1,52.168.0,60.255.0"}
P.entries["quest:5261"] = {n="Иган Меховщик",s="Это короткое вводное задание направляет новоприбывших рекрутов в Долине Североземья к Игану Меховщику, местному скорняку, работающему у Аббатства Североземья. Поскольку у границ долины хищников становится все больше, Игану нужны умелые искатели приключений, чтобы охотиться на лесных волков и добывать шкуры.",h="Это короткое вводное задание направляет новоприбывших рекрутов в Долине Североземья к Игану Меховщику...",kw={"deputy willem","eagan peltskinner","northshire abbey","northshire valley","timber wolves","wolves across the border","заместитель судьи виллем","иган меховщик","аббатство североземья","долина североземья","лесные волки","волки за границей"},ang={["faction:Alliance"]="Каждое небольшое дело в Североземье помогает защитить родные земли Штормграда, пока основная армия королевства занята в других местах.",["race:Human"]="Для юных людей, покидающих Аббатство Североземья, помощь местным ремесленникам вроде Игана — первый урок защиты родины."},sec={{t="Разговор со скорняком",b="Долина Североземья может казаться пасторальной, но ее тихие сады и поля окружены диким лесом, кишащим лесными волками. Заместитель судьи Виллем часто направляет рекрутов за стены аббатства к Игану Меховщику, который работает неподалеку на землях аббатства. Иган рад занять новичков делом: проредить агрессивные стаи и добыть ценные шкуры для своего ремесла."},{t="Беда на границе",b="Растущее число волков вокруг Североземья — не просто досада: оно угрожает работникам, послушникам и обозам, идущим в долину и из нее. Направляя юных защитников к Игану, штормградские маршалы решают сразу две задачи: ближайшие тропы остаются безопасными, а немногочисленных оставшихся стражей гарнизона, и без того встревоженных обстановкой в Элвиннском лесу, не приходится отвлекать."}},faq={{q="Кто посылает вас поговорить с Иганом Меховщиком?",a="Заместитель судьи Виллем, стоящий у входа в Аббатство Североземья, направляет перспективных рекрутов к Игану, после того как знакомит их с проблемами безопасности долины.",al={"who gives this quest","who starts eagan peltskinner quest","кто выдает это задание","кто дает задание игана меховщика"}},{q="Где находится Иган Меховщик?",a="Иган Меховщик стоит у внешних стен Аббатства Североземья, с левой стороны главного здания, среди своих сушильных рам и снаряжения.",al={"where is eagan","eagan peltskinner location","find eagan","где иган","иган меховщик местонахождение","найти игана"}},{q="С чем нужно помочь Игану Меховщику?",a="Иган ищет искателя приключений, готового охотиться на агрессивных лесных волков, рыщущих в окрестных лесах, и принести их шкуры, что помогает очистить окрестности Североземья.",al={"what does eagan want","why hunt wolves","eagan purpose","что нужно игану","зачем охотиться на волков","цель игана"}},{q="Можно ли пропустить это задание и поговорить с Иганом напрямую?",a="Да. Иган предлагает свое охотничье задание любому, кто к нему подойдет. Это направляющее задание лишь дает формальную рекомендацию от Заместителя судьи Виллема.",al={"can i skip eagan quest","wolves across the border directly","можно ли пропустить задание игана","волки за границей напрямую"}},{q="Почему в Долине Североземья так много волков?",a="Долина Североземья граничит с густыми нетронутыми лесами, где свободно бродят лесные волки. Поскольку местные стражи рассеяны и заняты другими угрозами по всему королевству, популяция диких хищников росла без помех.",al={"why wolves in northshire","wolf problem elwynn","почему волки в североземье","проблема волков элвинн"}},{q="Какое задание следует после разговора с Иганом Меховщиком?",a="Разговор с Иганом сразу ведет к его просьбе охотиться на лесных волков за границей земель аббатства и собирать их прочные шкуры.",al={"next quest after eagan","what does eagan offer next","следующее задание после игана","что предлагает иган дальше"}}},fp="17,299,23.367.0,24.376.0,46.176.0,35.153.0,43.185.0,51.164.0,50.219.0,50.146.0"}
P.entries["quest:527"] = {n="Битва за Хилсбрад",s="Битва за Хилсбрад — первый удар кампании Отрекшихся по уничтожению человеческого поселения Хилсбрад. Это задание, выданное Верховным палачом Дарталией по приказу Вариматраса, направлено против крестьян и построек северных Хилсбрадских полей, чтобы лишить город продовольствия.",h="Битва за Хилсбрад — первый удар кампании Отрекшихся по уничтожению человеческого поселения Хилсбрад.",kw={"battle of hillsbrad","darthalia","farmer getz","farmer ray","hillsbrad fields","new plague","tarren mill","varimathras","битва за хилсбрад","дарталия","фермер гетц","фермер рэй","хилсбрадские поля","новая чума","мельница таррен","вариматрас"},ang={["faction:Alliance"]="Расправа над северными поселенцами показывает ужасающую реальность, с которой сталкиваются оставшиеся людские анклавы в Лордероне.",["faction:Horde"]="Пока Тралл проповедует честь, северная кампания, ведущаяся из Мельницы Таррен, раскрывает бескомпромиссную жестокость войны Сильваны против Альянса.",["race:Undead"]="Для Отрекшихся возвращение Лордерона означает истребление каждого уцелевшего очага живых, считающих их родину украденной землей."},sec={{t="Голод для сопротивления",b="Мельница Таррен — южный оплот империи Отрекшихся, обращенный к укрепившемуся населению людей, цепляющемуся за Предгорья Хилсбрада. Верховный палач Дарталия действует по строгим указаниям Вариматраса из Подгорода. Ее стратегия — полное истощение: прежде чем идти прямо на хорошо защищенный город Хилсбрад, она приказывает методично разрушить его земледелие. Удар по северным полям лишает человеческое ополчение важных припасов и сеет хаос среди усадеб."},{t="Сдерживающий бой",b="Более широкая кампания против людей в Хилсбраде служит мрачной тактической цели. Пока армии Отрекшихся сковывают и обескровливают местных защитников, Королевское фармацевтическое общество неустанно трудится над новой чумой, способной уничтожить и живых, и Плеть. Верховный палач Дарталия считает эти ранние стычки и гибель местных землевладельцев, таких как Фермер Рэй и Фермер Гетц, необходимыми шагами для подавления человеческой заразы, пока это конечное оружие не будет готово."}},faq={{q="Почему Отрекшиеся нападают на простых крестьян?",a="Крестьяне и работники ферм на Хилсбрадских полях — логистическая основа города Хилсбрад. Выкашивая их рабочую силу и убивая видных землевладельцев, таких как Фермер Рэй и Фермер Гетц, Отрекшиеся отрезают человеческий гарнизон от продовольствия и ослабляют его оборону перед прямым штурмом.",al={"why kill farmers","hillsbrad farm targets","why attack farms","зачем убивать крестьян","цели на фермах хилсбрада","зачем нападать на фермы"}},{q="Кто приказывает совершить это нападение?",a="Задание выдает Верховный палач Дарталия, военачальница Отрекшихся в Мельнице Таррен. Она подчиняется непосредственно повелителю ужаса Вариматрасу и леди Сильване Ветрокрылой.",al={"who gives quest","darthalia orders","who is darthalia","кто выдает задание","приказы дарталии","кто такая дарталия"}},{q="Какую роль в этой кампании играет Королевское фармацевтическое общество?",a="Дарталия отмечает, что обычная война против людей нужна, чтобы подавить живое население и выиграть время, пока аптекари Отрекшихся создают новую чуму, призванную полностью уничтожить их врагов.",al={"why the new plague","apothecaries hillsbrad","forsaken plague plan","зачем новая чума","аптекари хилсбрад","план чумы отрекшихся"}},{q="Где находятся Фермер Рэй и Фермер Гетц?",a="Оба землевладельца присматривают за северной частью Хилсбрадских полей. Фермера Рэя обычно можно найти у большого фермерского дома или в саду к востоку от него, а Фермер Гетц бывает в амбаре, во втором доме или на окружающих вспаханных участках.",al={"find farmer ray","find farmer getz","ray and getz location","найти фермера рэя","найти фермера гетца","где рэй и гетц"}},{q="Что происходит после завершения этого налета?",a="Возвращение к Дарталии с победой продвигает штурм к южным полям и самому городу Хилсбрад, а также открывает побочные операции, например сбор мрачных трофеев в задании «Сувениры смерти».",al={"battle of hillsbrad follow up","what comes next","chain progression","продолжение битвы за хилсбрад","что дальше","цепочка заданий"}},{q="Почему Дарталия угрожает своим солдатам?",a="Верховный палач Дарталия требует абсолютной дисциплины и беспощадности. Любое колебание или легкомыслие в отношении войны с Альянсом она считает изменой, наказуемой немедленной казнью на месте.",al={"darthalia dialogue","darthalia beheading threat","диалог дарталии","угроза обезглавливания дарталии"}}},fp="19,302,23.523.0,17.505.0,46.318.0,23.197.0,61.208.0,45.258.0,40.201.0,41.198.0"}
P.entries["quest:528"] = {n="Битва за Хилсбрад",s="Битва за Хилсбрад — военное задание Отрекшихся, которым руководит верховный палач Дарталия из Мельницы Таррен. После первых ударов по северным человеческим фермам оперативники Орды отправляются на юг, чтобы перебить бегущих хилсбрадских крестьян, искавших убежища в садах.",h="Битва за Хилсбрад — военное задание Отрекшихся, которым руководит верховный палач Дарталия из Мельницы Таррен.",kw={"battle of hillsbrad","dark lady","darthalia","deathstalkers","forsaken","hillsbrad fields","hillsbrad peasants","tarren mill","битва за хилсбрад","темная госпожа","дарталия","стражи смерти","отрекшиеся","хилсбрадские поля","хилсбрадские крестьяне","мельница таррен"},ang={["faction:Alliance"]="Убийство безоружных беженцев в южных садах подчеркивает беспощадную тотальную войну, которую Отрекшиеся ведут против последних живых подданных Лордерона.",["faction:Horde"]="Мельница Таррен — важный оплот Орды в предгорьях. Разгром Хилсбрада обеспечивает безопасность коммуникаций и снабжения Орды от вторжений Альянса.",["race:Undead"]="Для Отрекшихся эта чистка — практичная и бескомпромиссная мера: уничтожение живых работников лишает Альянс пропитания и закрепляет власть Темной Госпожи над южным Лордероном."},sec={{t="Сеять ужас на полях",b="Кампания против присутствия людей в Предгорьях Хилсбрада идет с холодным расчетом. После удара сил Орды по северным фермам по поселению прокатывается паника. Вместо того чтобы взяться за оружие, многие работники бегут на юг, в сады и на пастбища Хилсбрадских полей, надеясь спрятаться от наступающей нежити. Верховный палач Дарталия видит в их страхе не повод для милосердия, а стратегическую возможность окончательно сломить остатки рабочей силы и боевой дух Хилсбрада."},{t="Наступление Темной Госпожи",b="По прямому приказу из Мельницы Таррен чемпионы Орды выслеживают этих изгнанных с мест работников на полях. Лишенные защиты крестьяне методично уничтожаются, чтобы перекрыть Хилсбраду поставки продовольствия и сломить волю мирных жителей. Для Дарталии и Отрекшихся каждый убитый человек сильнее сжимает хватку смерти вокруг уцелевшего городка и гарантирует, что Лордерон останется в руках Отрекшихся."}},faq={{q="Почему Отрекшиеся нападают на простых крестьян?",a="Нападения на крестьян уничтожают земледельческую основу, которая кормит поселение Хилсбрад. Убивая работников, прячущихся в южных садах, верховный палач Дарталия добивается, чтобы город все глубже погружался в панику и голод, и это намного облегчает окончательное завоевание.",al={"why kill peasants","why target farmers","darthalia peasant plan","зачем убивать крестьян","зачем нападать на фермеров","план дарталии против крестьян"}},{q="Кто отдает приказ об этом нападении?",a="Верховный палач Дарталия, командир Отрекшихся, расквартированный в Мельнице Таррен, руководит всеми военными действиями против местных человеческих поселений от имени леди Сильваны Ветрокрылой.",al={"who gives battle of hillsbrad 2","quest giver battle of hillsbrad","darthalia orders","кто дает задание битва за хилсбрад","персонаж, выдающий задание битва за хилсбрад","приказы дарталии"}},{q="Откуда бежали эти крестьяне?",a="Они бежали с северных ферм Хилсбрада после прежних ударов Орды. Охваченные паникой и беззащитные, они укрылись среди деревьев и на пастбищах южных Хилсбрадских полей.",al={"where are peasants coming from","northern farms hillsbrad","откуда пришли крестьяне","северные фермы хилсбрада"}},{q="Где можно найти беглых крестьян?",a="Крестьяне разбросаны по южным садам и пастбищам Хилсбрадских полей, чуть южнее главной дороги, проходящей через предгорья.",al={"hillsbrad peasant location","where are hillsbrad peasants","где крестьяне хилсбрада","расположение крестьян хилсбрада","где найти крестьян"}},{q="Что происходит после убийства крестьян?",a="Когда южные поля очищены от работников, верховный палач Дарталия переносит кампанию на кузнеца Верринтана и кузницу, вооружающую защитников Хилсбрада, приближая бой к центру города.",al={"what is next after peasants","battle of hillsbrad next step","что дальше после крестьян","следующий шаг битвы за хилсбрад"}},{q="Почему Орда сражается здесь так беспощадно?",a="Человеческий город Хилсбрад — один из последних оставшихся оплотов Альянса в Лордероне. Отрекшиеся считают этот край своей законной территорией и стремятся изгнать или уничтожить любые анклавы Альянса, угрожающие их южной границе.",al={"why horde attacking hillsbrad","forsaken vs hillsbrad war","почему орда нападает на хилсбрад","отрекшиеся против хилсбрада","война за хилсбрад"}}},fp="19,271,27.478.0,23.422.0,47.266.0,24.186.0,35.185.0,40.148.0,38.220.1,45.259.0"}
P.entries["quest:529"] = {n="Битва за Хилсбрад",s="Эта операция — важнейший этап кампании Отрекшихся по завоеванию Предгорий Хилсбрада. Верховный палач Дарталия приказывает уничтожить местную кузницу на Хилсбрадских полях, чтобы лишить упрямых людей поставок оружия.",h="Эта операция — важнейший этап кампании Отрекшихся по завоеванию Предгорий Хилсбрада.",kw={"apprentice blacksmith","battle of hillsbrad","darthalia","hillsbrad fields","shipment of iron","tarren mill","verringtan","подмастерье кузнеца","битва за хилсбрад","дарталия","хилсбрадские поля","партия железа","мельница таррен","верринтан"},ang={["faction:Alliance"]="Убийство Верринтана и кража железа поселения лишают дальние фермы Южнобережья единственного средства самообороны.",["profession:Blacksmithing"]="Кузница Верринтана была бьющимся сердцем местного сопротивления и доказала, что наковальня может быть для захватчиков не менее опасна, чем полк пехоты.",["race:Undead"]="Для Отрекшихся уничтожение человеческой кузницы — прагматичный шаг к защите южных границ Лордерона и накоплению металла для их собственных военных усилий, которые идут нелегко."},sec={{t="Сломать наковальню",b="Наступление Отрекшихся через Предгорья Хилсбрада столкнулось с более упорным сопротивлением, чем ожидал верховный палач Дарталия. Сельские жители не желали разбегаться или уступать Стражам смерти и солдатам, посланным из Мельницы Таррен. Расследование показало, что местные крестьяне сражаются не просто вилами и косами: их вооружают для войны прямо на полях."},{t="Разорвать линию снабжения",b="На юго-западной окраине Хилсбрадских полей кузнец Верринтан и его подмастерья неустанно трудились у горна, превращая сырую руду в клинки и доспехи для ополчения. Отправив оперативника, чтобы убить Верринтана, перебить его подмастерьев и захватить запасенную партию железа, Дарталия намеревалась ослабить оборону поселения и направить его металл на будущий штурм Южнобережья."}},faq={{q="Почему верховный палач Дарталия выбрала целью именно кузнеца?",a="Городские жители и фермеры оказывают Отрекшимся неожиданное военное сопротивление. Дарталия выяснила, что кузнец Верринтан и его подмастерья куют оружие для ополчения, превращая обычных крестьян в вооруженную угрозу.",al={"why kill verringtan","blacksmith objective","verringtan quest","зачем убивать верринтана","цель кузнец","задание верринтан"}},{q="Где находится кузница?",a="Кузница стоит на юго-западной стороне Хилсбрадских полей, вокруг нее работают подмастерья, ходят стражи и местные патрули.",al={"verringtan location","where is the blacksmith","hillsbrad smithy","где верринтан","где кузнец","кузница хилсбрада"}},{q="Для чего нужна партия железа?",a="Дарталия конфискует железо для военной машины Отрекшихся. Она намерена использовать захваченное сырье, чтобы ковать оружие и припасы для планируемого штурма портового города Альянса — Южнобережья.",al={"what happens to the iron","iron shipment lore","что будет с железом","партия железа предания"}},{q="Как это вписывается в общую кампанию Битвы за Хилсбрад?",a="Это третий этап систематических усилий Дарталии по уничтожению присутствия людей в предгорьях: от истребления сельских работников и фермеров она переходит к лишению их руководства, снабжения и производственных мощностей.",al={"battle of hillsbrad chain","darthalia campaign","цепочка битва за хилсбрад","кампания дарталии"}},{q="Входят ли жители Хилсбрадских полей в военные силы Альянса?",a="Хотя жители полей культурно близки к Южнобережью и Альянсу, это в основном местные фермеры, работники и горожане, наспех создавшие ополчение, чтобы защитить свои дома от Отрекшихся.",al={"are hillsbrad farmers alliance","hillsbrad militia","фермеры хилсбрада альянс","ополчение хилсбрада"}},{q="Кто отдает приказ об этом ударе?",a="Верховный палач Дарталия, командующий офицер, руководящий операциями Отрекшихся из крепости Мельница Таррен.",al={"quest giver","who is darthalia","персонаж, выдающий задание","кто такая дарталия"}}},fp="19,249,18.390.0,24.422.0,68.262.0,28.129.0,38.214.0,64.233.0,65.211.0,23.123.0"}
P.entries["quest:530"] = {n="Месть мужа",s="Месть мужа — завершение трагической истории давнего предательства, пронесенной сквозь смерть. Роли Андреан, Отрекшийся, живущий в Подгороде, поручает путникам найти его бывшего друга Валдреда Морая, убившего его жену при жизни.",h="Месть мужа — завершение трагической истории давнего предательства, пронесенной сквозь смерть.",kw={"deliah","engraved ring","greymane wall","raleigh andrean","ring of scorn","silverpine forest","undercity","valdred moray","делия","кольцо с гравировкой","стена седогрива","роли андреан","кольцо презрения","серебряный бор","подгород","валдред морай"},ang={["faction:Horde"]="Свершение правосудия в Серебряном бору помогает защитить границы вокруг Подгорода от оставшихся человеческих разбойников.",["race:Undead"]="Холодная отстраненность Роли от умершей жены в сочетании с его неугасающей одержимостью ненавистью и местью — яркий портрет того, как нежизнь искажает психологию смертных."},sec={{t="Горькая память",b="Когда Роли Андреан получил кольцо с гравировкой, привезенное из Серебряного бора, оно пробудило воспоминания о смертной жизни, которые нежизнь почти стерла. Среди них было глубокое предательство: его близкий друг Валдред Морай убил жену Роли, Делию. Хотя холод Плети и последующее существование среди Отрекшихся притупили способность Роли к скорби и любви, его жажда мести осталась нетронутой."},{t="Правосудие у стены",b="Спасаясь от последствий своих поступков и ужасов Лордерона, Валдред Морай бежал на юг через Серебряный бор, отчаянно стремясь укрыться в замкнутом человеческом королевстве за Стеной Седогрива. Но огромные ворота оставались закрытыми для беженцев и изгоев. Прижатый к каменной кладке, Валдред встретил конец по воле преданного им друга, а его отрубленные руки отнесли обратно в Подгород."},{t="Холодные памятные вещи",b="Получив руки бывшего друга, Роли не чувствует ни прилива тепла, ни искупления — лишь холодную завершенность. Рассчитавшись, он без сожаления отдает обручальное кольцо Делии, называя его бесполезной безделушкой. Отрубленные руки Валдреда Морая остаются в Подгороде как мрачное постоянное напоминание Роли о смертном предательстве."}},faq={{q="Почему Роли нужны именно руки Валдреда?",a="Роли требует руки Валдреда, потому что ими была отнята жизнь его жены. Он намерен хранить их в Подгороде как постоянный трофей и напоминание о предательстве друга.",al={"why hands","valdred hands","raleigh wants hands","почему руки","руки валдреда","роли хочет руки"}},{q="Где прячется Валдред Морай?",a="Валдред Морай находится на дальнем юге Серебряного бора, у огромной Стены Седогрива: ему не удалось попасть в закрытое королевство Гилнеас.",al={"where is valdred","valdred location","valdred moray spot","где валдред","расположение валдреда","где валдред морай"}},{q="Почему Роли отдает обручальное кольцо?",a="В нежизни привязанность Роли к Делии угасла без остатка. Не способный ни скорбеть, ни любить, он видит в ее кольце пустую безделушку; ценность сохранила лишь злоба мести.",al={"why give ring away","ring of scorn lore","why discard ring","почему отдает кольцо","кольцо презрения предания","зачем выбросил кольцо"}},{q="Может ли Валдред Морай войти в Гилнеас?",a="Нет. Король Генн Седогрив приказал закрыть стену во время Третьей войны, чтобы отгородиться от остального мира и Плети. Валдред, как и многие отчаявшиеся беженцы, оказался у запертых ворот.",al={"greymane wall closed","why is valdred outside wall","стена седогрива закрыта","почему валдред за стеной"}},{q="Какие задания ведут к этому поручению?",a="Цепочка начинается с задания «Кольцо с гравировкой» в Серебряном бору, которое направляет вас в Подгород в задании «Роли, который живет в Подгороде» и открывает «Месть мужа».",al={"husband revenge chain","prerequisite quest","previous quest","цепочка месть мужа","предыдущее задание","необходимое задание"}}},fp="19,249,15.439.0,19.441.1,14.357.1,51.203.0,30.166.0,44.212.1,32.201.0,33.163.0"}
P.entries["quest:532"] = {n="Битва за Хилсбрад",s="Этот важный этап кампании Отрекшихся против владений вокруг Южнобережья направлен против гражданского руководства города Хилсбрад. Под началом Верховного палача Дарталии из Мельницы Таррен силы Орды наносят удар по судье Бернсайду, его совету и административным записям, чтобы полностью сокрушить человеческую власть в предгорьях.",h="Этот важный этап кампании Отрекшихся против владений вокруг Южнобережья направлен против гражданского...",kw={"battle of hillsbrad","darthalia","hillsbrad councilmen","hillsbrad proclamation","hillsbrad town registry","magistrate burnside","tarren mill","town hall","битва за хилсбрад","дарталия","хилсбрадские советники","хилсбрадская прокламация","городской реестр хилсбрада","судья бернсайд","мельница таррен","ратуша"},ang={["faction:Alliance"]="Убийство судьи Бернсайда и сожжение городского устава ознаменовали катастрофическое падение последнего законного местного правительства Хилсбрада.",["faction:Horde"]="Удар по ратуше подрывает способность Альянса координировать местное ополчение и надежно укрепляет южную границу Мельницы Таррен от контратак людей.",["race:Undead"]="Для Отрекшихся уничтожение человеческой власти в Хилсбраде — одновременно стратегическое расширение и безжалостное возмездие живым, оспаривающим границы Лордерона."},sec={{t="Обезглавливание городского совета",b="Даже понеся тяжелые потери на полях и в патрулях, человеческие защитники Хилсбрада цепляются за остатки гражданской власти. Верховный палач Дарталия понимает, что простые крестьяне и ополченцы сплачиваются вокруг своих городских лидеров. Чтобы город рухнул окончательно, агентов Отрекшихся посылают прямо в Ратушу — казнить судью Бернсайда и пятерых его советников и тем самым разорвать цепь командования."},{t="Уничтожение городских записей",b="Помимо убийств, Дарталия стремится полностью разрушить Хилсбрад в психологическом и административном смысле. Агенты должны сжечь Хилсбрадскую прокламацию — почитаемый политический документ, символ устава и гордости поселения. Вместе с ее уничтожением изымается городской реестр: уцелевшие сторонники Альянса лишаются официальных записей и списков жителей, а разведка Подгорода получает подробные сведения о местном населении."}},faq={{q="Кто отдает приказ об этом ударе?",a="Верховный палач Дарталия, командир Отрекшихся в Мельнице Таррен, организует нападение в рамках своей более широкой кампании по уничтожению поселений Альянса в предгорьях.",al={"who gives this quest","quest giver battle of hillsbrad","darthalia hillsbrad","кто дает это задание","персонаж, выдающий задания битва за хилсбрад","дарталия хилсбрад"}},{q="Кто такой судья Бернсайд?",a="Судья Бернсайд — судья и политический лидер человеческого города Хилсбрад. Находясь в ратуше вместе со своими советниками, он использует тайную магию, чтобы защитить остатки власти в поселении.",al={"magistrate burnside","who is burnside","hillsbrad leader","судья бернсайд","кто такой бернсайд","лидер хилсбрада"}},{q="Что такое Хилсбрадская прокламация?",a="Хилсбрадская прокламация — почитаемый политический устав, на видном месте хранящийся в Ратуше. Он воплощает законы и дух жителей города, поэтому его уничтожение становится сокрушительным ударом по гражданскому духу.",al={"what is the proclamation","hillsbrad proclamation lore","destroy proclamation","что такое прокламация","хилсбрадская прокламация предания","уничтожить прокламацию"}},{q="Зачем Дарталии городской реестр?",a="В городском реестре содержится полная перепись и гражданская документация населения Хилсбрада. Его похищение лишает уцелевших людей административной памяти, а Отрекшиеся получают важные сведения о том, кто остался в округе.",al={"why steal registry","hillsbrad town registry","what does registry do","зачем красть реестр","городской реестр хилсбрада","для чего нужен реестр"}},{q="Где происходит это сражение?",a="Цели находятся в большом здании Ратуши и вокруг него, в человеческом поселении Хилсбрад, расположенном в южных предгорьях между Мельницей Таррен и Южнобережьем.",al={"where is magistrate burnside","hillsbrad town hall location","where are councilmen","где судья бернсайд","ратуша хилсбрада где","где советники"}},{q="Какую роль играют советники?",a="Хилсбрадские советники — управляющий орган, помогающий судье Бернсайду. Это умелые заклинатели, защищающие как внутренние помещения Ратуши, так и прилегающую территорию.",al={"hillsbrad councilmen","who are councilmen","хилсбрадские советники","кто такие советники"}}},fp="19,335,29.444.0,24.472.0,23.179.0,27.221.0,35.223.0,42.237.0,33.182.0,33.185.0"}
P.entries["quest:5321"] = {n="Спящий пробудился",s="Керлониан Вечный Сумрак, недавно пробудившийся Друид-медведь, изо всех сил старается не уснуть на пути к Заставе Мейстры в Ясеневом лесу. Путешественникам, которым доверен его Рог Пробуждения, предстоит сопровождать вялого друида вдоль лесной границы: будить его, когда он погружается в дрему, и защищать от диких фурболгов и зловещих культистов.",h="Керлониан Вечный Сумрак, недавно пробудившийся Друид-медведь, изо всех сил старается не уснуть на пути к...",kw={"ashenvale","dark strand","darkshore","druid of the claw","evershade","horn of awakening","kerlonian","liladris","maestra's post","twilight vale","ясеневый лес","темная нить","темные берега","друид-медведь","вечный сумрак","рог пробуждения","керлониан","лиладрис","застава мейстры","сумеречная долина"},ang={["class:Druid"]="Друиды узнают тяжелую цену глубокого единения с Изумрудным Сном: долгая спячка часто оставляет бодрствующий разум медленно приходящим в полное сознание.",["faction:Alliance"]="Безопасный проход путников между Темными берегами и севером Ясеневого леса помогает поддерживать важные линии связи между Аубердином и дальними сторожевыми постами.",["race:NightElf"]="Для ночных эльфов Керлониан — привычное свидетельство недавнего потрясения их культуры: он олицетворяет тысячи друидов, откликнувшихся на зов рога во время Третьей войны и теперь привыкающих к дневному свету."},sec={{t="Дремлющий разум",b="Тысячелетиями Друиды-медведи спали в курганах, общаясь с духами природы через Изумрудный Сон. Хотя Третья война потребовала их пробуждения, стряхнуть многовековую спячку удается не каждому. Керлониан Вечный Сумрак отправился на юг из Темных берегов в Ясеневый лес на встречу с Лиладрис Лунная Река, но усталость одолела его вскоре после начала пути. Он беспомощно склонен внезапно засыпать посреди глуши, поэтому полагается на латунный Рог Пробуждения и проходящих мимо союзников, чтобы продолжать идти."},{t="Опасности на дороге",b="Путь из Темных берегов в Ясеневый лес далек от спокойного. Пока Керлониан бредет на юг, его уязвимое состояние привлекает агрессию окрестной глуши. В Сумеречной долине дорогу выслеживают оскверненные фурболги Чернолесья, а южнее, в Ясеневом лесу, в засадах таятся члены зловещего культа Темной Нити. Сопровождение сонного друида требует бдительности: Керлониан просто ляжет спать там, где стоит, если его не разбудить рогом."},{t="Прибытие на заставу",b="Пережив засады и добравшись до Заставы Мейстры, Керлониан тут же уходит искать другую удобную лужайку, чтобы продолжить прерванный сон. Его знакомая, Лиладрис Лунная Река, почти не удивлена его привычной рассеянности и встречает его с нежной досадой. Трудности Керлониана отражают остаточную растерянность, свойственную многим друидам, для которых мир яви режет глаз после вневременного покоя Сна."}},faq={{q="Почему Керлониан все время засыпает?",a="Керлониан Вечный Сумрак — Друид-медведь, лишь недавно очнувшийся от многовековой спячки в Изумрудном Сне. Возвращение в мир яви оставляет многих друидов растерянными и глубоко вялыми, поэтому без постоянных внешних раздражителей ему почти невозможно не заснуть.",al={"why is kerlonian sleeping","why is he so sleepy","druid falling asleep","почему керлониан спит","почему он такой сонный","друид засыпает"}},{q="Как разбудить Керлониана, когда он засыпает?",a="Нужно использовать Рог Пробуждения, который берется из сундука рядом с Керлонианом в начале пути. Когда он падает в дрему на тропе, звук рога приводит его в чувство, и он может продолжить путь.",al={"how to wake kerlonian","kerlonian horn","horn of awakening use","как разбудить керлониана","рог керлониана","использование рога пробуждения"}},{q="Кто ждет Керлониана на Заставе Мейстры?",a="Он направляется на встречу с Лиладрис Лунная Река, эльфийкой с Заставы Мейстры на севере Ясеневого леса. Она знает о его хронической сонливости и просто рада видеть, что он добрался целым.",al={"who is liladris","who is kerlonian meeting","кто такая лиладрис","с кем встречается керлониан"}},{q="Какие враги нападают по пути?",a="Дорога ведет мимо Сумеречной долины, где враждебные фурболги Чернолесья устраивают засады на отряд. Дальше на юг, в Ясеневом лесу, из тени бьют землекопы, адепты и культисты тайной Темной Нити.",al={"ambushes during escort","what attacks kerlonian","twilight vale ambush","засады при сопровождении","кто нападает на керлониана","засада в сумеречной долине"}},{q="Откуда взялось название «Спящий пробудился»?",a="Это легендарное приветствие, которое произносят Друиды-медведи, когда их призывают на службу во время Третьей войны, и оно подчеркивает природу Керлониана как пробудившегося оборотня.",al={"sleeper has awakened quote","druid voiceline","цитата спящий пробудился","реплика друида"}},{q="Что будет с рогом, если слишком долго медлить?",a="Рог Пробуждения действует ограниченное время, после чего исчезает из вашего инвентаря. Если сопровождение затягивается или его приходится начинать заново после неудачи, замену нужно взять из сундука у места отдыха Керлониана.",al={"horn expired","horn of awakening disappeared","рог исчез","рог пробуждения пропал"}}},fp="24,348,17.541.0,20.484.0,22.454.1,39.294.0,42.241.0,47.194.0,34.212.0,58.168.0,46.232.0"}
P.entries["quest:536"] = {n="На побережье",s="«На побережье» — задание Альянса, которое выдает лейтенант Фаррен Оринель в Южнобережье. Крайне недовольный переводом из Штормграда на границу, лейтенант стражи предпочитает пить эль, а не патрулировать, и нанимает искателей приключений, чтобы вычистить мурлоков Рваного Плавника, наступающих на Западное побережье.",h="«На побережье» — задание Альянса, которое выдает лейтенант Фаррен Оринель в Южнобережье.",kw={"down the coast","farren orinelle","hillsbrad","murloc","redpath","southshore","torn fin","western strand","на побережье","фаррен оринель","хилсбрад","мурлок","редпат","южнобережье","рваный плавник","западное побережье"},ang={["faction:Alliance"]="Южнобережье — главный прибрежный бастион Альянса на севере, поэтому даже мелкая халатность гарнизона угрожает выживанию города.",["race:Human"]="Леность Оринеля болезненно обнажает контраст между защищенным сердцем Штормграда и суровым выживанием северных поселений."},sec={{t="Неохотное назначение",b="Лейтенант Фаррен Оринель был переведен из городской стражи Штормграда с его вымощенными камнем улицами в далекий соленый порт Южнобережья. Считая город унылым, а рыбный запах гавани невыносимым, Оринель проводит дни за выпивкой в местной таверне вместо патрулирования передовой. Когда маршал Маркус Редпат приказывает ему защитить Южнобережье от окрестных опасностей, Оринель решает передоверить свои обязанности проходящим мимо наемникам."},{t="Угроза Рваного Плавника",b="Само задание связано с Западным побережьем — береговой линией к западу от Южнобережья. Хотя Оринель насмехается над угрозой «переросшей рыбы», племя мурлоков Рваного Плавника представляет настоящую опасность для прибрежных путешествий и местного судоходства. Они собираются в плотных лагерях у прибоя, и их охотники приливов и мистические оракулы легко устраивают засады на всех, кто уходит далеко от городских стен, так что зачистка берега — кровавое дело."}},faq={{q="Почему Фаррен Оринель не разбирается с мурлоками сам?",a="Фаррен считает Южнобережье нежеланной ссылкой после прежней жизни в городской страже Штормграда. Обиженный назначением и испытывая отвращение к прибрежному городку, он предпочитает сидеть в таверне с элем, а не идти в прибой сражаться с мурлоками, и потому платит искателям приключений за свою работу.",al={"why is farren drinking","farren orinelle personality","why hire adventurers","почему фаррен пьет","характер фаррена оринеля","почему нанимает искателей приключений"}},{q="Кто такой «старина Редпат», о котором говорит Оринель?",a="Он имеет в виду маршала Маркуса Редпата, маршала Южнобережья. Редпат отвечает за порядок и оборону осажденного поселения, в том числе отдает военные приказы, от которых лейтенант Оринель откровенно пытается увильнуть.",al={"who is redpath","magistrate redpath","orinelle commander","кто такой редпат","судья редпат","командир оринеля"}},{q="Где находятся мурлоки Рваного Плавника?",a="Мурлоки Рваного Плавника обитают на Западном побережье — прибрежных пляжах прямо к западу от Южнобережья в Предгорьях Хилсбрада.",al={"where are torn fin","murloc location hillsbrad","western strand location","где рваный плавник","мурлоки хилсбрад","где западное побережье"}},{q="Каких мурлоков нужно уничтожить?",a="Задание требует убить охотников приливов Рваного Плавника — бойцов передовой племени — и оракулов Рваного Плавника, использующих магию стихий и воды, чтобы усиливать сородичей.",al={"murloc targets","which murlocs kill","tidehunter oracle","цели мурлоки","каких мурлоков убивать","охотник приливов оракул"}},{q="Что происходит после зачистки пляжа для Оринеля?",a="После завершения зачистки Оринель понимает, что ему нужны вещественные доказательства, чтобы удовлетворить проверку маршала Редпата, и это запускает цепочку заданий по сбору физических доказательств гибели мурлоков.",al={"next quest after down the coast","down the coast chain","farrens proof next","следующее задание после на побережье","цепочка на побережье","доказательства фаррена дальше"}},{q="Мурлоки действительно опасны или это просто предлог?",a="Хотя Фаррен высмеивает этих существ как безобидную переросшую рыбу, Рваные Плавники многочисленны, агрессивны и расположены неприятно близко к докам Южнобережья, угрожая торговым путям и рыбакам.",al={"are murlocs dangerous hillsbrad","southshore murloc danger","опасны ли мурлоки хилсбрад","опасность мурлоков южнобережье"}}},fp="14,293,19.465.0,19.442.0,58.293.0,42.249.0,39.139.0,44.179.0,51.196.1,56.195.0"}
P.entries["quest:539"] = {n="Битва за Хилсбрад",s="Этот приказ Верховного палача Дарталии велит агентам Орды нанести удар в глубине Лазуритового рудника — важного железного рудника к югу от Хилсбрадских полей. Уничтожив штейгера Бондса и его рабочих, Отрекшиеся стремятся прервать поставки железа на оружейные склады Альянса и захватить туннели.",h="Этот приказ Верховного палача Дарталии велит агентам Орды нанести удар в глубине Лазуритового рудника —...",kw={"azurelode","bonds","darthalia","hillsbrad","iron","miners","southshore","tarren mill","undercity","лазуритовый рудник","бондс","дарталия","хилсбрад","железо","шахтеры","южнобережье","мельница таррен","подгород"},ang={["faction:Horde"]="Срыв главных поставок металла Альянса в Хилсбраде ослабляет давление на передовую у Мельницы Таррен и не дает людским войскам легко заменить снаряжение.",["profession:Mining"]="Лазуритовый рудник — одна из богатейших железных копей в предгорьях, поэтому он естественно становится яблоком раздора для всех, кто борется за ценные рудные жилы.",["race:Undead"]="Захват Лазуритового рудника обеспечивает Стражей смерти необходимым железом и обращает промышленность людей на вооружение армий Сильваны по всему Лордерону."},sec={{t="Прерывание поставок железа",b="Захватив во время прежних налетов Регистрационную книгу Хилсбрада, Верховный палач Дарталия определила, что Лазуритовый рудник — опора военной устойчивости людей в регионе. Рудник действует к югу от спорных полей и непрерывно добывает богатую железную руду для оружейников и арсеналов Альянса. Если оставить его нетронутым, силы Южнобережья смогут перевооружиться и усилить гарнизоны, а прежние победы Мельницы Таррен потеряют смысл."},{t="Решающее послание",b="Чтобы полностью остановить добычу, Дарталия бьет и по руководству, и по рабочим. Силам Орды приказано убить штейгера Бондса, человека, руководящего раскопками, и значительную часть его рабочих. Удар по темным шахтам посылает Южнобережью недвусмысленное сообщение: ни их линии снабжения, ни уединенные рабочие лагеря не недоступны для Отрекшихся."},{t="Добыча для Темной Госпожи",b="Помимо лишения Альянса военных материалов, этот штурм преследует для Подгорода и практическую цель. Захват рудника позволяет силам Сильваны Ветрокрылой присвоить богатые рудные жилы для своих литейных. Мельнице Таррен нужен постоянный запас металла для оружия и лат для войны по всему Лордерону, и бывшее достояние людей становится двигателем завоеваний Отрекшихся."}},faq={{q="Почему Лазуритовый рудник так важен для Отрекшихся?",a="Лазуритовый рудник поставляет высококачественную железную руду прямо на оружейные склады Альянса. Его захват лишает человеческие гарнизоны, например Южнобережья, материалов для ковки и отдает Подгороду богатый источник сырого металла для снаряжения сил Отрекшихся.",al={"why attack azurelode","azurelode mine purpose","why target the mine","зачем атаковать лазуритовый рудник","значение лазуритового рудника","почему рудник цель"}},{q="Кто такой штейгер Бондс?",a="Штейгер Бондс — человек, надзирающий за раскопками в Лазуритовом руднике. Он управляет шахтерами и может призвать стойких дворфов-защитников, когда его загонят в глубокие нижние залы.",al={"foreman bonds","who is bonds","who leads the mine","штейгер бондс","кто такой бондс","кто управляет рудником"}},{q="Где находится Лазуритовый рудник?",a="Лазуритовый рудник вырублен в холмах к югу от Хилсбрадских полей, к западу от Южнобережья, среди прибрежных утесов.",al={"where is azurelode mine","azurelode location","how to find the mine","где лазуритовый рудник","расположение лазуритового рудника","как найти рудник"}},{q="Как Дарталия узнала о работе рудника?",a="Дарталия узнала о ценности рудника для снабжения и о том, что он действует, изучив Регистрационную книгу Хилсбрада, которую оперативники Орды захватили во время прежних ударов по поселениям людей.",al={"how did darthalia know","town registry mine","hillsbrad intel","как дарталия узнала","регистрационная книга рудник","разведка хилсбрад"}},{q="Что произойдет после гибели штейгера Бондса?",a="Когда рудник выведен из строя, а его ресурсы переходят под контроль Отрекшихся, Верховный палач Дарталия усиливает наступление: Орда направляет внимание на уничтожение оставшейся инфраструктуры Хилсбрада и продвигается ближе к самому Южнобережью.",al={"what next battle of hillsbrad","after killing bonds","quest aftermath","что дальше битва за хилсбрад","после убийства бондса","последствия задания"}},{q="Защищает ли Альянс рудник?",a="Да. Помимо людей-шахтеров, работающих в штольнях, Альянс держит у входа вооруженную стражу, а штейгер Бондс держит наготове крепких дворфов-подкрепление в глубине туннелей.",al={"mine guards","alliance presence in azurelode","dwarves in mine","стража рудника","присутствие альянса в лазуритовом руднике","дворфы в руднике"}}},fp="19,299,24.454.0,18.389.0,24.402.1,51.235.0,21.187.0,36.121.0,55.191.0,42.247.1,34.187.0"}
P.entries["quest:541"] = {n="Битва за Хилсбрад",s="Этот важный этап кампании Отрекшихся в Хилсбраде направлен на дворфийскую крепость Дун Гарок. Верховный палач Дарталия посылает героев Орды разгромить дворфийский гарнизон, помогающий местным людям, и убить его командира, капитана Железная Гора.",h="Этот важный этап кампании Отрекшихся в Хилсбраде направлен на дворфийскую крепость Дун Гарок.",kw={"battle of hillsbrad","captain ironhill","dun garok","high executor darthalia","mountaineer","rifleman","tarren mill","thoradin's wall","битва за хилсбрад","капитан железная гора","дун гарок","верховный палач дарталия","горный стрелок","стрелок","мельница таррен","стена торадина"},ang={["faction:Horde"]="Удар по Дун Гароку отрезает важные военные подкрепления, которые Стальгорн послал на помощь осажденным людям Южнобережья.",["race:Dwarf"]="Дун Гарок воплощает стойкую верность Стальгорна своим союзникам-людям, которые выдерживают осаду Отрекшихся, удерживая северный рубеж.",["race:Undead"]="Для Отрекшихся уничтожение дворфийского гарнизона закрепляет юго-восток Лордерона и гарантирует, что никакой южный авангард Альянса не сможет легко пройти через Стену Торадина."},sec={{t="Проверка Альянса",b="Надавив на людей-фермеров и городское ополчение в предгорьях, Верховный палач Дарталия обращает ярость Мельницы Таррен против военного контингента Стальгорна. Дворфийские войска взялись за оружие в поддержку Южнобережья, укрепляя присутствие людей в Лордероне. Для Дарталии эта солидарность — препятствие, которое нужно сокрушить, доказав Альянсу, что помощь остаткам людей принесет лишь разорение."},{t="Падение Дун Гарока",b="Дун Гарок, прижатый к древним валам Стены Торадина на юго-востоке Хилсбрада, служит сильно укрепленным дворфийским бастионом. Чтобы взять форпост, нужно прорваться через ряды дисциплинированных горных пехотинцев, меткие стрелки и закаленных в боях жрецов. Штурм завершается смертью капитана Железная Гора, что ломает передовое тактическое командование Стальгорна в регионе и оставляет прочие людские анклавы в изоляции."}},faq={{q="Почему дворфы сражаются в Хилсбраде?",a="Дворфы Стальгорна прочно связаны с Альянсом и отправили на север, в Дун Гарок, вооруженные силы, чтобы помочь уцелевшим людям Южнобережья и Хилсбрада против экспансии Отрекшихся.",al={"why are there dwarves in hillsbrad","dwarves dun garok","why dwarves helping humans","почему дворфы в хилсбраде","дворфы дун гарок","почему дворфы помогают людям"}},{q="Где находится Дун Гарок?",a="Дун Гарок расположен в юго-восточном углу Предгорий Хилсбрада и встроен прямо в основание Стены Торадина.",al={"dun garok location","where is dun garok","find dun garok","расположение дун гарока","где дун гарок","найти дун гарок"}},{q="Кто такой капитан Железная Гора?",a="Капитан Железная Гора — дворфийский командир гарнизона Дун Гарока. Благодаря ему горные пехотинцы в регионе остаются организованными и боеспособными.",al={"captain ironhill","who is ironhill","dun garok leader","капитан железная гора","кто такой капитан железная гора","предводитель дун гарока"}},{q="Кто дает этот приказ?",a="Приказ разгромить дворфийский гарнизон отдает Верховный палач Дарталия, военный командир Отрекшихся, расквартированный в Мельнице Таррен.",al={"who gives quest","questgiver darthalia","darthalia hillsbrad","кто дает задание","дарталия выдает задание","дарталия хилсбрад"}},{q="Что будет, если силы Орды потерпят здесь неудачу?",a="Верховный палач Дарталия ясно дает понять, что провал недопустим, и предупреждает: всякого, кто не сможет сломить Дун Гарок, разжалуют и отправят рыть могилы обратно в Тирисфальские леса.",al={"what if fail","darthalia threat","consequences","что если провал","угроза дарталии","последствия"}},{q="Почему Дун Гарок так трудно штурмовать?",a="В отличие от сельского ополчения Хилсбрада, Дун Гарок защищают обученные дворфийские солдаты, стрелковые отряды и священники, которые сражаются плотным строем в укреплениях, расположенных под землей и на возвышении.",al={"dun garok elite","why is dun garok hard","dun garok defense","элита дун гарока","почему дун гарок трудно взять","оборона дун гарока"}}},fp="19,270,20.421.0,21.433.0,38.202.0,27.128.0,24.158.0,21.132.0,39.172.0,41.205.0"}
P.entries["quest:543"] = {n="Тиара Перенольда",s="Тиара Перенольда — поручение графа Ремингтона Риджвелла, аристократа из Штормграда. Он нанимает искателей приключений, чтобы они отправились на север, в опасные Руины Альтерака, и вернули утраченную королевскую реликвию. Корона некогда принадлежала павшей династии Альтерака, и, по слухам, ее хранит маг-огр.",h="Тиара Перенольда — поручение графа Ремингтона Риджвелла, аристократа из Штормграда.",kw={"alterac","crushridge","grel'borg","miser","perenolde","ridgewell","stormwind","tiara","альтерак","раздробленный хребет","грель'борг","скряга","перенольд","риджвелл","штормград","тиара"},ang={["faction:Alliance"]="Поход на север, в беззаконные Альтеракские горы, позволяет агентам Альянса уничтожить опасных огров Раздробленного Хребта и вернуть бесценные исторические артефакты для знати Штормграда.",["race:Dwarf"]="Созданная искусными ювелирами Стальгорна, тиара олицетворяет прославленное мастерство дворфийских ремесленников, чья тонкая работа пережила даже крах человеческого королевства.",["race:Human"]="Для людей Альянса тиара — неприятное напоминание о предательстве Альтерака во Второй войне, когда человеческая знать встала на сторону Орды против собственного народа."},sec={{t="Реликвия павшего королевства",b="Тиара Перенольда — изысканная реликвия павшего человеческого королевства Альтерак. Искусные дворфийские ювелиры Стальгорна изготовили этот богато украшенный венец и украсили его лучшими изумрудами для правящего рода Перенольдов. Однако во время Второй войны король Эйден Перенольд предал Великий Альянс, перейдя на сторону Орочьей Орды, что прямо привело к падению его королевства, его завоеванию и окончательному краху. В хаосе и после падения города Альтерак многие величайшие сокровища королевской династии исчезли в заснеженных обломках Альтеракских гор."},{t="Скряга в руинах",b="Тиара оказалась не в хранилище Альянса и не в королевской гробнице, а в жадных лапах Грель'борга Скряги. Грель'борг, маг-огр из племени огров Раздробленного Хребта, обитающих в руинах Альтерака, целыми днями роется в полуразрушенных камнях в поисках блестящих безделушек и брошенных богатств. Граф Ремингтон Риджвелл, страстный коллекционер исторических диковин из Штормграда, узнал, что тиара уцелела, и нанимает отважных наемников, чтобы они проникли вглубь земель огров, убили скрягу и вернули бесценную драгоценность в его личную галерею."}},faq={{q="Кто такие Перенольды?",a="Перенольды — королевский род, правивший северным человеческим королевством Альтерак. Во время Второй войны король Эйден Перенольд совершил государственную измену, сотрудничая с вторгшейся Орочьей Ордой, чтобы пощадить свое королевство. Его предательство раскрыл Альянс Лордерона, что привело к военной оккупации Альтерака, упразднению трона и последующему падению королевства в полное беззаконие и разорение.",al={"house of perenolde","who were the perenoldes","perenolde lore","род перенольдов","кто такие перенольды","предания о перенольдах"}},{q="Кто создал Тиару Перенольда?",a="Тиару выковали искусные ювелиры дворфийского города Стальгорн. Изготовленная из тонких металлов и украшенная блестящими изумрудами, она была символом знатности и богатства правящего дома Альтерака, пока королевство не пало.",al={"tiara origin","who crafted perenolde tiara","происхождение тиары","кто создал тиару перенольда"}},{q="У кого сейчас тиара?",a="Тиара попала в лапы Грель'борга Скряги, огра-мага-собирателя, бродящего по заснеженным Руинам Альтерака в северных холмах и жаждущего древних сокровищ, оставшихся от разрушенного человеческого города.",al={"grelborg","who has perenolde tiara","tiara location","грель'борг","у кого тиара перенольда","где тиара"}},{q="Зачем графу Ремингтону Риджвеллу тиара?",a="Граф Ремингтон Риджвелл — богатый дворянин и любитель древностей, живущий в Штормграде. Он ищет знаменитые артефакты и исторические диковины по всему Азероту, чтобы пополнить свою известную личную коллекцию, и нанимает умелых наемников, чтобы они добывали утраченные сокровища из опасных мест.",al={"remington ridgewell motive","why get the tiara","мотив ремингтона риджвелла","зачем получить тиару"}},{q="Где находятся Руины Альтерака?",a="Руины Альтерака лежат в холодных Альтеракских горах на севере Восточных королевств, к северу от Предгорий Хилсбрада и к северу от окрестностей Дарнхольда. Заброшенный город сейчас кишит враждебными ограми Раздробленного Хребта и разбойниками Синдиката.",al={"alterac ruins location","where is alterac","расположение руин альтерака","где альтерак"}},{q="Что происходит с тиарой после того, как вы ее вернете?",a="Получив грязную и потускневшую реликвию, граф Риджвелл поручает профессиональным реставраторам почистить и отполировать ее, а затем сразу выставляет как главный экспонат своей личной коллекции.",al={"tiara turn in","tiara fate","сдача тиары","судьба тиары"}}},fp="19,319,27.573.0,22.591.0,29.425.0,29.241.0,24.204.0,50.289.0,39.265.0,47.201.1"}
P.entries["quest:546"] = {n="Сувениры смерти",s="«Сувениры смерти» — задание, которое Страж смерти Самса в Мельнице Таррен дает воинам Орды, воюющим против человеческих поселений в Предгорьях Хилсбрада. Завидуя тем, кого отправили на передовую, Самса просит принести тридцать человеческих черепов, добытых в бою, для его мрачной коллекции.",h="«Сувениры смерти» — задание, которое Страж смерти Самса в Мельнице Таррен дает воинам Орды, воюющим против...",kw={"battle of hillsbrad","darthalia","deathguard samsa","forsaken","hillsbrad","hillsbrad human skull","souvenirs of death","tarren mill","битва за хилсбрад","дарталия","страж смерти самса","отрекшиеся","хилсбрад","человеческий череп хилсбрада","сувениры смерти","мельница таррен"},ang={["faction:Alliance"]="Систематический сбор отрубленных человеческих голов показывает, какая жестокая и смертельная угроза исходит от Отрекшихся для уцелевших жителей Хилсбрада.",["faction:Horde"]="Кампания против Хилсбрада — прямая попытка Орды сокрушить оставшиеся оплоты Альянса в Лордероне и обезопасить северные пути снабжения Мельницы Таррен.",["race:Undead"]="Страж смерти Самса отражает обыденную жестокость и глубокую враждебность, которую многие Отрекшиеся питают к живым людям, считающим их чудовищами."},sec={{t="Зависть стража",b="Пока Верховный палач Дарталия направляет всю военную мощь Отрекшихся против человеческих поселений Хилсбрада, Страж смерти Самса застрял на посту в Мельнице Таррен. Он питает горькую зависть к тем, кого послали грабить, жечь и разорять, и считает открытое убийство живых завидной привилегией, недоступной городским стражам."},{t="Жуткий трофей",b="Не имея возможности покинуть пост, Самса дает выход своей ненависти, собирая черепа жителей Хилсбрада, убитых в ходе кампании. Его просьба о тридцати черепах не связана ни с тайным ритуалом, ни с тактикой: это чисто личная прихоть — трофеи войны, в которой он мечтает сражаться сам."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Страж смерти Самса. Он стоит на посту в Мельнице Таррен — главном оплоте Отрекшихся на севере Предгорий Хилсбрада.",al={"quest giver","who gives souvenirs of death","samsa location","персонаж, выдающий задание","кто дает сувениры смерти","где самса"}},{q="Что нужно Стражу смерти Самсе?",a="Самса просит тридцать человеческих черепов Хилсбрада, которые достаются с убитых вами людей — бойцов и горожан — в Хилсбрадских полях и в городе Хилсбрад.",al={"quest goal","what items needed","skulls required","цель задания","какие предметы нужны","сколько черепов"}},{q="Зачем Самсе человеческие черепа?",a="Самса — страстный коллекционер жутких трофеев. Застряв в гарнизоне Мельницы Таррен, пока другие ведут тотальную войну, он собирает черепа, чтобы хоть так разделить радость убийства живых.",al={"why collect skulls","samsa motivation","what are skulls for","зачем собирать черепа","мотивы самсы","для чего черепа"}},{q="Когда становится доступно это задание?",a="Самса обращается к вам, только когда вы поступили на службу к Верховному палачу Дарталии и выполнили первое нападение в цепочке заданий «Битва за Хилсбрад».",al={"quest prerequisites","how to unlock","prereqs for souvenirs","требования задания","как открыть","предыдущие задания сувениры смерти"}},{q="Используются ли черепа для алхимии или магии Отрекшихся?",a="Нет. В отличие от поручений Королевского фармацевтического общества, которому нужны биологические реагенты для Новой чумы, просьба Самсы совершенно личная. Он считает отрубленные черепа красивыми и хранит их как сувениры войны.",al={"are skulls for apothecary","magic skulls","necromancy use","черепа для аптекаря","магические черепа","некромантия"}},{q="Какие люди дают черепа?",a="Черепа могут выпасть с любого фермера, крестьянина, ополченца и защитника из Хилсбрадских полей или города Хилсбрад, пока вы сражаетесь от имени Мельницы Таррен.",al={"where to farm skulls","which mobs drop skulls","hillsbrad humans","где добыть черепа","с кого падают черепа","люди хилсбрада"}}},fp="18,285,14.373.0,17.303.0,49.147.0,32.170.0,33.185.0,38.151.0,50.222.0,32.173.0"}
P.entries["quest:547"] = {n="Меч Гумберта",s="Разведывая Дун Гарок, оплот Стальгорна, по приказу Верховного палача Дарталии, Страж смерти Гумберт отошел от лагеря за дровами. Дворфы-разведчики обшарили его стоянку и унесли его личное оружие, и опозоренный часовой отчаянно хочет вернуть его, пока командир не заметила.",h="Разведывая Дун Гарок, оплот Стальгорна, по приказу Верховного палача Дарталии, Страж смерти Гумберт отошел от...",kw={"darthalia","deathguard","dun garok","firewood","hillsbrad","humbert","sword","tarren mill","дарталия","страж смерти","дун гарок","дрова","хилсбрад","гумберт","меч","мельница таррен"},ang={["faction:Horde"]="Каждый удар по Дун Гароку служит общей кампании по разрушению военной власти Стальгорна над Предгорьями Хилсбрада и защите Мельницы Таррен от вторжений с юга.",["race:Dwarf"]="Горные пехотинцы Дун Гарока не питают любви к Отрекшимся у своего порога и пользуются любой возможностью донимать часовых Мельницы Таррен и дочиста обирать их лагеря.",["race:Undead"]="Солдаты Отрекшихся в Хилсбраде знают о жестокой дисциплине Верховного палача Дарталии: за провал или небрежность в Мельнице Таррен следует беспощадная казнь, а не снисхождение."},sec={{t="Небрежность разведчика",b="По приказу Верховного палача Дарталии Страж смерти Гумберт скрытно наблюдал за Дун Гароком неподалеку от дворфийской крепости. Утром он ненадолго оставил пост без присмотра, чтобы набрать дров для кипячения воды. Этого хватило расчетливым дворфам Стальгорна. Вернувшись, Гумберт обнаружил, что лагерь разграблен, а его верный меч унесен в глубь хорошо защищенного бастиона."},{t="Страх перед стропилами",b="Потерять оружие из-за врага, за которым нужно следить, — позор, наказуемый смертью у Отрекшихся. Гумберт прекрасно знает: если Верховный палач Дарталия узнает о его промахе, она вздернет его на стропилах Мельницы Таррен. Не имея сил штурмовать крепость в одиночку, он рассчитывает на проходящих мимо искателей приключений из Орды, которые проникнут в Дун Гарок и вернут его клинок, пока Дарталия ничего не заподозрила."}},faq={{q="Кто такой Страж смерти Гумберт?",a="Страж смерти Гумберт — солдат Отрекшихся, расквартированный в Мельнице Таррен в Предгорьях Хилсбрада. Верховный палач Дарталия поручила ему разведку и наблюдение за Дун Гароком — сильно укрепленным дворфийским оплотом на юго-востоке предгорий.",al={"deathguard humbert","who is humbert","humbert","страж смерти гумберт","кто такой гумберт","гумберт"}},{q="Как Гумберт потерял свой меч?",a="Пока Гумберт вел наблюдение возле Дун Гарока, он отошел за дровами, чтобы утром вскипятить воду. В его отсутствие дворфы-разведчики нашли лагерь, обокрали его и унесли меч.",al={"how did humbert lose his weapon","who stole humbert's sword","stolen sword","как гумберт потерял оружие","кто украл меч гумберта","украденный меч"}},{q="Почему Гумберт так отчаянно хочет вернуть меч тайно?",a="Командир Гумберта, Верховный палач Дарталия, поддерживает в Мельнице Таррен строгую дисциплину. Гумберт боится, что, узнав о потере снаряжения из-за дворфов, за которыми он должен был следить, она казнит его и повесит на стропилах.",al={"why humbert worried","darthalia punishment","why fear darthalia","почему гумберт боится","наказание дарталии","почему бояться дарталии"}},{q="Где находится меч?",a="Дворфы-разведчики унесли меч в Дун Гарок. Его можно найти среди горных пехотинцев, стрелков и офицеров Стальгорна, занимающих бастион.",al={"sword location","where is humbert's sword","dun garok sword","где меч","где меч гумберта","меч дун гарок"}},{q="Украли ли дворфы у Гумберта что-нибудь еще?",a="Да. Помимо меча, дворфы-разведчики растащили остальное походное снаряжение Гумберта, включая шлем, нагрудник и штаны, которые остались у защитников Дун Гарока.",al={"humbert other gear","humbert armor pieces","humbert's pants","другие вещи гумберта","доспехи гумберта","штаны гумберта"}},{q="Что такое Дун Гарок?",a="Дун Гарок — оплот дворфов Стальгорна в юго-восточном углу Предгорий Хилсбрада, где они помогают защищать людей Хилсбрада и расположенный рядом Лазуритовый рудник. Гарнизон Альянса там находится в прямом и враждебном противостоянии с Отрекшимися Мельницы Таррен.",al={"dun garok fortress","dun garok lore","dwarves in hillsbrad","крепость дун гарок","предыстория дун гарока","дворфы в хилсбраде"}}},fp="15,329,20.425.0,19.435.0,26.235.0,31.231.0,58.246.0,27.167.0,49.182.0,18.279.0"}
P.entries["quest:5481"] = {n="Задание Толстяка",s="«Задание Толстяка» — поручение в Тирисфальских лесах от Гордо, бродячего поганища, который пытается собрать растения вдоль дороги в Брилл. Не способный к тонкой работе, он нанимает путников собрать Мракоцвет и доставить его своему хозяину, младшему аптекарю Холланду.",h="«Задание Толстяка» — поручение в Тирисфальских лесах от Гордо, бродячего поганища, который пытается собрать...",kw={"abomination","apothecary","brill","doom weed","gloom weed","gordo","holland","tirisfal glades","поганище","аптекарь","брилл","погибельник","мракоцвет","гордо","холланд","тирисфальские леса"},ang={["profession:Herbalism"]="Опытным травникам это задание покажется легким: их чутье легко выделяет заросли Мракоцвета среди зараженной травы.",["race:Undead"]="Для недавно восставших Отрекшихся, покидающих Могильник, это задание — первое знакомство с неуклюжим трудом поганищ и вспыльчивым нравом Королевского фармацевтического общества."},sec={{t="Неуклюжий работник",b="Гордо — поганище, бродящее по окрестностям между Могильником и Бриллом. Поганища хороши в грубом бою и переноске тяжестей, но их огромные сшитые руки почти не годятся для тонкой работы. Посланный на луга за ингредиентами для Королевского фармацевтического общества, Гордо быстро понимает, что его толстые пальцы давят больше стеблей, чем срывают, и начинает запугивать или подкупать прохожих, чтобы они сделали скучную работу за него."},{t="Досада аптекаря",b="Младший аптекарь Холланд ждет доставку на кладбище за ратушей Брилла, но поручение идет наперекосяк. Гордо совершенно неверно понял приказ и отправил путников собирать безвредный Мракоцвет вместо летучего Погибельника, нужного для алхимических исследований. Холланд крайне раздражен некомпетентностью сшитого гиганта и считает ошибочную доставку доказательством бесполезности поганища, после чего тут же поручает игроку исправить ошибку."}},faq={{q="Кто такой Гордо?",a="Гордо — поганище на службе Королевского фармацевтического общества. Он обходит луга к западу от Брилла, пытаясь выполнить рабочие поручения своего хозяина, младшего аптекаря Холланда.",al={"who is gordo","gordo tirisfal","gordo npc","what is gordo","кто такой гордо","гордо тирисфаль","гордо нпс","что такое гордо"}},{q="Почему Гордо нужна помощь в сборе трав?",a="Руки Гордо — огромные неуклюжие отростки из сшитой мертвой плоти. Ему просто не хватает ловкости, чтобы срывать нежные растения, не испортив их, поэтому он нанимает странствующих Отрекшихся искателей приключений.",al={"why does gordo need weeds","why can't gordo pick weeds","gordo hands","зачем гордо нужны травы","почему гордо не может собирать травы","руки гордо"}},{q="Кто такой мастер Холланд?",a="Младший аптекарь Холланд — алхимик Королевского фармацевтического общества, находящийся на кладбище Брилла. Он присматривает за Гордо и изучает местную флору и зараженную почву, чтобы помочь военным усилиям Отрекшихся.",al={"master holland","who is holland","apothecary holland","мастер холланд","кто такой холланд","аптекарь холланд"}},{q="Почему Холланд расстроен, когда ему приносят Мракоцвет?",a="Холланду никогда не был нужен Мракоцвет. Гордо совершенно неверно понял приказ и отправил искателей приключений за не тем растением. На самом деле Холланду требовался Погибельник — гораздо более сильный и опасный ингредиент для его смесей.",al={"why is holland mad","gloom weed mistake","wrong weed","почему холланд зол","ошибка с мракоцветом","не та трава"}},{q="Где можно найти Мракоцвет?",a="Мракоцвет растет низко над землей на диких полях между Могильником и Бриллом, особенно на открытых лугах к востоку от Фермы Соллидена.",al={"where to find gloom weed","gloom weed locations","finding gloom weed","где найти мракоцвет","места мракоцвета","поиск мракоцвета"}},{q="What happens after completing Gordo's Task?",a="Получив бесполезный Мракоцвет, младший аптекарь Холланд тут же отправляет вас обратно в поля с заданием «Погибельник» собрать те самые летучие растения, которые он просил изначально.",al={"what comes next","gordo's task follow up","next quest after gordo","что дальше","продолжение задания толстяка","следующее задание после гордо"}}},fp="12,264,16.465.0,23.484.1,13.201.0,41.229.0,22.218.0,54.217.1,30.150.0,43.198.1"}
P.entries["quest:5482"] = {n="Погибельник",s="«Погибельник» — задание, которое выдает младший аптекарь Холланд в Брилле: собрать ядовитые растения, растущие возле северных братских могил Тирисфаля. Холланд, раздраженный неуклюжими попытками сбора, предпринятыми порождением Гордо, нанимает проходящих мимо искателей приключений.",h="«Погибельник» — задание, которое выдает младший аптекарь Холланд в Брилле: собрать ядовитые растения...",kw={"brill","doom weed","gordo","junior apothecary holland","mass grave","rot hide gnolls","royal apothecary society","tirisfal glades","брилл","погибельник","гордо","младший аптекарь холланд","братская могила","гноллы гнилошкуры","королевское фармацевтическое общество","тирисфальские леса"},ang={["faction:Horde"]="Тревожные алхимические опыты в Брилле показывают, насколько Отрекшиеся отличаются от своих шаманистских и кочевых союзников в Калимдоре.",["profession:Herbalism"]="Хотя обычные травы для сбора растут по всем лесам, искаженные разновидности вроде погибельника показывают неестественные изменения растительного мира, вызванные чумой Плети.",["race:Undead"]="Служба младшим членам Королевского фармацевтического общества — обычный обряд для недавно пробудившихся Отрекшихся, желающих доказать свою полезность владениям Сильваны."},sec={{t="Аптекарские амбиции",b="Младший аптекарь Холланд ведет исследования от имени Королевского фармацевтического общества в поселении Брилл. Для продолжения опытов ему нужно много погибельника — отвратительного растения, которое заражает оскверненную почву Тирисфальских лесов. Убедившись, что Гордо не способен отличить нужные реагенты, Холланд обращается к более сноровистым рукам, чтобы спасти урожай."},{t="Сбор у братской могилы",b="Погибельник процветает в местах, сильно оскверненных смертью и чумой, и густо разрастается вокруг братской могилы к северу от кладбища Брилла. Сбор опасен из-за агрессивных гноллов Гнилошкуров, которые бродят по оскверненным курганам, роются в останках и защищают заросшие рвы."}},faq={{q="Зачем младшему аптекарю Холланду нужен погибельник?",a="Младшему аптекарю Холланду нужен погибельник для алхимических работ на благо Королевского фармацевтического общества. Он утверждает, что это прямо помогает леди Сильване Ветрокрылой, но его алчное рвение говорит о том, что он не меньше заинтересован в собственной карьере в обществе.",al={"holland doom weed","why doom weed","doom weed purpose","холланд погибельник","зачем погибельник","для чего нужен погибельник"}},{q="Почему Гордо не собирает травы сам?",a="Гордо — это порождение нежити, которому поручено собирать травы вокруг Брилла, но у него не хватает ума, чтобы отличать нужные растения. Холланд жалуется, что неуклюжее создание принесло совсем не те сорняки, и аптекарю пришлось нанимать способных искателей приключений.",al={"why not gordo","gordo task fail","who is gordo","почему не гордо","гордо не справился","кто такой гордо"}},{q="Где растет погибельник?",a="Погибельник растет среди зараженных растений вокруг братской могилы, к северу от кладбища за пределами Брилла. Он распространяется по почве, сильно отравленной погребальными рвами и остатками чумы.",al={"doom weed location","where is doom weed","mass grave weeds","погибельник где найти","где растет погибельник","братская могила травы"}},{q="Какие опасности таятся возле зарослей погибельника?",a="Земли вокруг братской могилы заполонили гноллы Гнилошкуры. Эти дикие, зараженные болезнями падальщики агрессивно нападают на всех, кто подходит к месту захоронений, пока те собирают траву.",al={"doom weed monsters","mass grave enemies","gnolls near brill","погибельник монстры","враги братской могилы","гноллы возле брилла"}},{q="Чем растения Тирисфаля интересны Королевскому фармацевтическому обществу?",a="Королевское фармацевтическое общество постоянно изучает растения, яды и грибы, измененные порчей, по всем Тирисфальским лесам. Реагенты вроде погибельника собирают, чтобы очищать токсины, находить алхимические средства исцеления и создавать новое оружие для Отрекшихся против их врагов.",al={"apothecary interest","royal apothecary society tirisfal","forsaken herb gathering","интерес аптекарей","королевское фармацевтическое общество тирисфаль","сбор трав отрекшихся"}},{q="Кто такая «Леди», о которой говорит Холланд?",a="Леди — это леди Сильвана Ветрокрылая, Королева банши и правительница Отрекшихся. Аптекари Подгорода и Брилла часто упоминают ее имя, поскольку их алхимические труды официально выполняются по ее приказу.",al={"who is the lady","holland lady sylvanas","the lady undercity","кто такая леди","холланд леди сильвана","леди подгород"}}},fp="9,259,20.366.0,22.333.0,50.278.0,43.266.0,26.209.0,45.201.0,66.262.0,39.211.0"}
P.entries["quest:549"] = {n="РАЗЫСКИВАЮТСЯ: сторонники Синдиката",s="Этот указ, вывешенный на доске объявлений Мельницы Таррен от имени леди Сильваны, приговаривает к смерти всех членов Синдиката. Отрекшиеся стремятся уничтожить разбойников, собирающихся в руинах Крепости Дарнхольд, прежде чем они начнут угрожать операциям Орды в предгорьях.",h="Этот указ, вывешенный на доске объявлений Мельницы Таррен от имени леди Сильваны, приговаривает к смерти всех...",kw={"durnholde keep","high executor darthalia","hillsbrad foothills","syndicate","syndicate rogue","syndicate watchman","tarren mill","wanted","крепость дарнхольд","верховный палач дарталия","предгорья хилсбрада","синдикат","разбойник синдиката","страж синдиката","мельница таррен","разыскивается"},ang={["class:Rogue"]="Синдикат держит в Дарнхольде умелых карманников и убийц из засады, так что это задание становится прямым столкновением соперничающих мастеров скрытности.",["faction:Horde"]="Крепость Дарнхольд хранит мрачные воспоминания как крепость-лагерь, где некогда держали в плену орков; уничтожение разбойников, засевших в ее руинах, имеет для Орды символическое значение.",["race:Undead"]="Для Отрекшихся уничтожение живых остатков знати Альтерака — практическая необходимость, чтобы обеспечить безраздельный контроль над холмами Лордерона."},sec={{t="Постоянный приказ о казни",b="Внезапное появление Синдиката к юго-востоку от Мельницы Таррен не осталось незамеченным Отрекшимися. Вместо переговоров или обращения с ними как с простыми изгнанными дворянами леди Сильвана Ветрокрылая и ее командиры видят в Синдикате живую заразу. Указ требует немедленной смерти и уточняет, что все приведенные пленники будут казнены без суда."},{t="Руины Дарнхольда",b="Некогда печально известная крепость-лагерь для интернированных, Крепость Дарнхольд теперь лежит в руинах и беззаконии. Разбойники и стражи Синдиката пробрались в ее обрушенные стены и башни и используют древний оплот как оперативный центр. Для Верховного палача Дарталии избавление руин от вооруженных бандитов необходимо, чтобы защитить дорогу и юго-восточные подступы к Мельнице Таррен."}},faq={{q="Кто вывесил объявление о награде за сторонников Синдиката?",a="Награда объявлена по прямому приказу леди Сильваны Ветрокрылой и вывешена на доске объявлений в Мельнице Таррен. Доказательства казни принимает Верховный палач Дарталия, военный командир поселения.",al={"who posted wanted syndicate personnel","who wants syndicate dead","bounty poster","кто вывесил разыскиваются сторонники синдиката","кто хочет смерти синдиката","автор объявления"}},{q="Где находятся эти члены Синдиката?",a="Они собираются среди разрушенных камней Крепости Дарнхольд к юго-востоку от Мельницы Таррен за рекой, а также у разрушенной сторожевой башни к югу от главной крепости.",al={"where are syndicate rogues","durnholde syndicate location","where to find watchmen","разбойники синдиката где","синдикат дарнхольд местоположение","где найти стражей"}},{q="Почему Отрекшиеся хотят убить их, а не взять в плен?",a="Отрекшиеся считают Синдикат вероломными паразитами и вооруженной угрозой своей территории. Указ прямо приказывает немедленно казнить всех взятых под стражу членов, так что плен совершенно бессмыслен.",al={"why kill syndicate","why no prisoners","darthalia syndicate","зачем убивать синдикат","почему без пленных","дарталия синдикат"}},{q="Что делает Синдикат в Крепости Дарнхольд?",a="Синдикат, состоящий в основном из опозоренной знати Альтерака и наемников, использует заброшенные крепости, руины и башни по всему Лордерону как опорные пункты для набегов на поселения, ограбления путников и восстановления своей разрушенной опоры власти.",al={"why syndicate in durnholde","syndicate purpose hillsbrad","durnholde keep occupiers","зачем синдикат в дарнхольде","цель синдиката хилсбрад","захватчики крепости дарнхольд"}},{q="Что будет после уничтожения этих приспешников Синдиката?",a="Сокращение рядов разбойников и стражей побуждает Верховного палача Дарталию объявить высокоприоритетную награду за их местного предводителя — барона Вардуса.",al={"what quest is next","after wanted syndicate personnel","next bounty","какое задание дальше","после разыскиваются сторонники синдиката","следующая награда"}}},fp="27,273,26.365.0,22.379.0,46.225.0,42.187.0,55.236.0,46.236.0,54.168.1"}
P.entries["quest:55"] = {n="Морбент Скверн",s="Это задание — последний расчет с Морбентом Скверном, некромантом, обитающим на возвышенностях над Кладбищем Вороньего Холма. Вооруженные зачарованной реликвией «Проклятье Морбента», герои отправляются скорбящим Свеном Йоргеном, чтобы разрушить защиту чародея и положить конец его террору в западном Сумеречном лесу.",h="Это задание — последний расчет с Морбентом Скверном, некромантом, обитающим на возвышенностях над Кладбищем...",kw={"duskwood","morbent fel","morbent's bane","necromancer","raven hill","raven hill cemetery","sven yorgen","сумеречный лес","морбент скверн","проклятье морбента","некромант","вороний холм","кладбище вороньего холма","свен йорген"},ang={["class:Paladin"]="Сразить мерзкого некроманта и очистить Вороний Холм от его неестественных чар — истинное призвание рыцарей Света.",["class:Priest"]="Осквернение Кладбища Вороньего Холма требует духовного очищения, поэтому рассеивание колдовских чар Скверна становится священным долгом.",["faction:Alliance"]="Убийство Морбента Скверна устраняет одну из страшнейших угроз жителям Сумеречного леса, делает дорогу безопасной и воздает должное страданиям западных поселений вроде Вороньего Холма."},sec={{t="Насест над мертвыми",b="Морбент Скверн устроил логово в заброшенном доме на скалистом гребне к востоку от лагеря Свена, над раскинувшимся Кладбищем Вороньего Холма. Оттуда некромант направлял волны нежити, чтобы терроризировать окрестный лес и осквернять могилы Сумеречного леса. Защищенный мощной темной магией и окруженный преданными рабами из нежити, он оставался неуязвим для обычной стали."},{t="Месть Свена",b="Свен Йорген обезумел от горя, когда темные силы зверски убили его семью и вынудили его скрываться. Хотя Свен знает, что истинные виновники резни на его ферме — загадочные Темные всадники Каражана, мерзкое колдовство Морбента Скверна продлевает кошмар этого края. Убийство некроманта — единственная осязаемая крупица справедливости, оставшаяся Свену в этой проклятой земле."},{t="Проклятье Морбента",b="Прямое нападение на Морбента Скверна — самоубийство без сверхъестественной помощи: его защитные чары отражают обычные удары. Чтобы обойти эту защиту, Свен вручает искателям приключений Проклятье Морбента — зачарованный артефакт, созданный специально для разрушения магического щита некроманта. После его применения преграда рушится, и Скверн становится уязвим для смертного удара."}},faq={{q="Кто такой Морбент Скверн?",a="Морбент Скверн — могущественный некромант, управляющий нежитью, наводнившей окрестности Вороньего Холма. Он скрывается в доме на холме над Кладбищем Вороньего Холма и использует темное колдовство, чтобы защищаться и мучить живых в Сумеречном лесу.",al={"morbent fel lore","who is morbent fel","morbent fel background","морбент скверн предания","кто такой морбент скверн","морбент скверн история"}},{q="Почему для убийства Морбента нужно Проклятье Морбента?",a="Морбент Скверн окружает себя мощными чарами, делающими его почти неуязвимым для обычного урона. Проклятье Морбента — зачарованная реликвия, созданная специально для рассеивания этих защитных чар, чтобы сделать его уязвимым.",al={"morbents bane","why use morbents bane","how to beat morbent fel","проклятье морбента","зачем проклятье морбента","как победить морбента скверна"}},{q="Как Свен Йорген связан с Морбентом Скверном?",a="Свен потерял семью и ферму из-за темных сил, наводнивших Сумеречный лес. Хотя за резню ответственны загадочные Темные всадники, некромантическая хватка Морбента Скверна над округой олицетворяет гнойное зло западного Сумеречного леса, что делает его главной целью мести Свена.",al={"why does sven want morbent dead","sven yorgen morbent fel","sven revenge","почему свен хочет смерти морбента","свен йорген морбент скверн","месть свена"}},{q="Где можно найти Морбента Скверна?",a="Он обитает на верхнем этаже ветхого разрушенного дома на холме к востоку от лагеря Свена Йоргена, возвышающегося над западной частью Кладбища Вороньего Холма.",al={"morbent fel location","where is morbent fel","morbent house","морбент скверн местоположение","где морбент скверн","дом морбента"}},{q="Убил ли Морбент Скверн семью Свена?",a="Нет. Семью Свена убили загадочные Темные всадники, искавшие Косу Элуны. Однако некромантия Морбента Скверна отравила окрестности и осквернила могилы Сумеречного леса, поэтому его уничтожение необходимо для возвращения покоя.",al={"did morbent kill sven family","who slaughtered sven family","убил ли морбент семью свена","кто убил семью свена"}},{q="Что происходит после смерти Морбента Скверна?",a="Возвращение Проклятья Морбента Свену приносит скорбящему отшельнику небольшое утешение. Хотя неуловимые Темные всадники остаются на свободе, гибель Скверна разрушает некромантическую хватку над Вороньим Холмом и укрепляет репутацию искателя приключений по всему Сумеречному лесу.",al={"after morbent fel","quest conclusion","does sven get peace","после морбента скверна","завершение задания","обретет ли свен покой"}}},fp="11,289,24.408.0,16.390.1,14.367.0,19.237.0,44.233.0,48.301.0,31.166.0,35.250.1,40.258.1"}
P.entries["quest:550"] = {n="Битва за Хилсбрад",s="Это задание знаменует завершение кампании Отрекшихся против человеческого поселения Хилсбрад. Разгромив местные силы Альянса, вы по приказу Верховного палача Дарталии несете официальную рекомендацию Вариматрасу в Подгород.",h="Это задание знаменует завершение кампании Отрекшихся против человеческого поселения Хилсбрад.",kw={"battle of hillsbrad","darthalia","hillsbrad foothills","royal quarter","sealed commendation","tarren mill","undercity","varimathras","битва за хилсбрад","дарталия","предгорья хилсбрада","королевский квартал","запечатанное рекомендательное письмо","мельница таррен","подгород","вариматрас"},ang={["faction:Horde"]="Отбросив силы Альянса в Лордероне, вы обеспечиваете Орде важный плацдарм в Восточных королевствах.",["race:Undead"]="Донесение о вашей победе над живыми Хилсбрада приносит прямую похвалу из Королевского квартала и подтверждает ваше место в растущей империи Темной Госпожи."},sec={{t="Решающая кампания",b="Кампания в Предгорьях Хилсбрада — жестокая борьба за юг Лордерона. В ходе затяжной серии ударов, координируемых из Мельницы Таррен, бойцы Орды уничтожили фермеров, ополчение, кузнецов и городских правителей человеческого поселения. Когда присутствие Альянса было подорвано, а земли перешли под контроль Отрекшихся, Верховный палач Дарталия составляет официальную рекомендацию, чтобы о подвигах исполнителя узнало высшее командование."},{t="Аудиенция у повелителя ужаса",b="Запечатанное письмо Дарталии ведет прямо в Королевский квартал Подгорода, к Вариматрасу. Повелитель ужаса стоит рядом с леди Сильваной Ветрокрылой и руководит военными операциями по всему Лордерону. Хотя Плеть, наступающая с северных Чумных земель, остается главной смертельной угрозой для Темной Госпожи, защита южных границ от уцелевших человеческих поселений жизненно важна для молодого государства Отрекшихся."}},faq={{q="Что это за задание?",a="Это заключительная сдача задания в длинной цепочке Битвы за Хилсбрад. Выполнив поручения Верховного палача Дарталии в Мельнице Таррен, вы получаете от нее запечатанное рекомендательное письмо, которое нужно лично доставить Вариматрасу в Подгород.",al={"battle of hillsbrad finale","hillsbrad final quest","quest 550","финал битвы за хилсбрад","последнее задание хилсбрада","задание 550"}},{q="Где сдать Запечатанное рекомендательное письмо Дарталии?",a="Его нужно сдать Вариматрасу, который стоит рядом с леди Сильваной Ветрокрылой в Королевском квартале Подгорода.",al={"where is varimathras","turn in commendation","darthalia letter turn in","где вариматрас","сдать рекомендательное письмо","сдать письмо дарталии"}},{q="Почему Вариматрасу есть дело до Хилсбрада?",a="Как главный военный помощник Темной Госпожи, Вариматрас отвечает за стратегическую оборону и расширение владений. Хотя Плеть на севере — величайшая угроза для Подгорода, человеческие поселения на юге постоянно тревожат рубежи Отрекшихся. Устранение угрозы в Хилсбраде защищает их южную границу.",al={"why varimathras","varimathras role in hillsbrad","почему вариматрас","роль вариматраса в хилсбраде"}},{q="Кто такая Верховный палач Дарталия?",a="Верховный палач Дарталия — старший командир Отрекшихся в Мельнице Таррен в Предгорьях Хилсбрада, руководящая наступлением на соседнее человеческое поселение.",al={"darthalia","who gave the quest","дарталия","кто выдал задание"}},{q="Ведет ли это задание к другим поручениям в Хилсбраде?",a="Нет. Доставка рекомендации Вариматрасу — официальное завершение сюжета Битвы за Хилсбрад, награда за прорыв обороны города.",al={"next quest after battle of hillsbrad","what comes after quest 550","следующее задание после битвы за хилсбрад","что после задания 550"}},{q="Почему Отрекшиеся вообще напали на Хилсбрад?",a="Город Хилсбрад — один из последних организованных оплотов людей в Лордероне. Он союзен Альянсу, и его ополчение и близость представляют непосредственную военную угрозу Мельнице Таррен и южным подступам к Подгороду.",al={"why attack hillsbrad","hillsbrad lore","зачем нападать на хилсбрад","предания хилсбрада"}}},fp="19,252,19.464.0,27.452.0,19.247.0,51.112.0,42.304.0,31.181.0,54.159.0,61.236.0"}
P.entries["quest:5502"] = {n="Опекун Орды",ang={["faction:Horde"]="Для Орды сила — это не только боевое мастерство, но и общая воля защищать и возвышать слабых, которые однажды понесут знамя Вождя.",["race:Orc"]="Культура орков ценит отвагу и честь, а сострадание к ребенку-сироте вроде Грунта воплощает благородство, которое Тралл стремится привить новой Орде."},sec={{t="An Orphan's Farewell",b="After the adventures of Children's Week, Grunth thanks his guardian for showing him more than he ever dreamed he would see. Remembering his parents' advice to rise above hardship, he says he hopes to become a hero like the adventurer. His final request is to return home and tell the matron about their time together."},{t="Home to the Valley of Honor",b="Returning to the orphanage in the Valley of Honor, adventurers return their young charge back into the care of Orphan Matron Battlewail. Taking responsibility for the young is considered a profound duty in the new Horde, where war has left countless children without parents. Battlewail commends your compassion as the true measure of a hero of the Horde, and Grunth parts ways with a beloved pet to ensure you remember the bond forged during your travels."}},faq={{q="В чем смысл этого задания?",a="This quest concludes the Horde's Children's Week festivities. Return Grunth and the Orcish Orphan Whistle to Orphan Matron Battlewail in the Valley of Honor.",al={"warden of the horde summary","childrens week ending horde","опекун орды краткое содержание","конец детской недели орда"}},{q="Кто такой Грунт?",a="Grunth is an orcish youth residing at the Orgrimmar Orphanage in the Valley of Honor. During Children's Week, he is paired with a Horde champion who takes him across Kalimdor to see legendary figures and grand sights.",al={"who is the orc orphan","grunth lore","кто такой орк-сирота","грунт предания"}},{q="What do I bring back to the matron?",a="Bring the Orcish Orphan Whistle back to Orphan Matron Battlewail when Grunth is ready to return home.",al={"orphan whistle return","return grunth whistle"}},{q="Кто присматривает за сиротами в Оргриммаре?",a="Orphan Matron Battlewail manages the Orgrimmar Orphanage in the Valley of Honor, dedicating her life to sheltering and raising the Horde's war orphans.",al={"orphan matron horde","who runs the orphanage","попечительница сирот орда","кто управляет приютом"}},{q="Why does Grunth want to return home?",a="His Children's Week outings are finished, and he wants to tell the matron about the adventures and the kind guardian who took him along.",al={"grunth return home","children week farewell"}},{q="Почему Детская неделя важна для Орды?",a="Десятилетия безжалостных войн с демонами, людьми и кентаврами оставили бесчисленных детей Орды без семей. Детская неделя — время, когда воины отходят от поля боя и чтят будущие поколения Дуротара и не только.",al={"childrens week lore","why care for orphans horde","предания детской недели","зачем заботиться о сиротах орды"}}},fp="21,218,20.317.0,27.456.0,34.157.0,14.217.0,35.101.0,38.151.0,36.136.0,46.247.0"}
P.entries["quest:5541"] = {n="Боеприпасы для Громострела",s="Оружейнику Хегнару Громострелу не хватает пуль и пороха для стрелков, тренирующихся возле Старой Наковальни. Пропавший ящик боеприпасов бросили в заснеженной глуши у Серой берлоги, когда курьера обратили в бегство голодные вендиго.",h="Оружейнику Хегнару Громострелу не хватает пуль и пороха для стрелков, тренирующихся возле Старой Наковальни.",kw={"ammo","anvilmar","coldridge","grizzled den","hegnar","loslor rudge","rumbleshot","wendigo","боеприпасы","старая наковальня","холодный кряж","серая берлога","хегнар","лослор рудж","громострел","вендиго"},ang={["class:Hunter"]="Каждый стрелок Холодной Гряды хорошо знает лавку Хегнара; пока на ее полках свежие порох и пули, вы никогда не выйдете в дикие земли с пустым ружьем.",["profession:Engineering"]="Дворфийскому огнестрелу и минометам нужны тонкий порох и ровные пули, поэтому товар Громострела необходим местным механикам и стрелкам.",["race:Dwarf"]="Дворфийское мастерство зависит от непрерывных поставок между кузнями Старой Наковальни и передовыми оружейниками вроде Громострела."},sec={{t="Бегство курьера",b="Лослор Рудж из Поселка Сталежара обеспечивает бесперебойные поставки торговцам по всему Дун Мороге, но местные звери часто мешают. Его последняя партия тяжелых боеприпасов так и не дошла до придорожной мастерской Хегнара Громострела. Остановившись у системы пещер, известной как Серая берлога, перепуганный курьер столкнулся с местными вендиго и бежал, бросив тяжелый деревянный ящик в снегу."},{t="Порох и пули",b="Хегнар Громострел держит оружейную лавку прямо у главной дороги, ведущей от Старой Наковальни. На поляне у его кузни постоянно толпятся стрелки Стальгорна, горные пехотинцы и дворфийские минометные расчеты, желающие пристрелять оружие и потренироваться боевыми зарядами. Без постоянных ящиков пороха и свинца от поставщиков вроде Лослора обучение стрельбе быстро останавливается."}},faq={{q="Где потеряли ящик с боеприпасами?",a="Испуганный посыльный Лослора Руджа уронил груз, остановившись лагерем у Серой берлоги — пещеры, кишащей вендиго, в снежных холмах к юго-западу от Караноса.",al={"ammo location","where is rumbleshot ammo","crate location","где боеприпасы","где боеприпасы громострела","где ящик"}},{q="Кто такой Хегнар Громострел?",a="Хегнар Громострел — дворф-оружейник, держащий оружейную лавку у дороги возле Старой Наковальни. Он снабжает порохом, пулями и огнестрельным оружием горных пехотинцев, охотников и осадные расчеты, тренирующиеся поблизости.",al={"who is hegnar","rumbleshot","hegnar rumbleshot","кто такой хегнар","громострел","хегнар громострел"}},{q="Почему курьера прогнали?",a="Посыльный совершил ошибку, расположившись лагерем возле Серой берлоги — логова свирепых территориальных вендиго, бродящих по холмам к юго-западу от Караноса.",al={"why courier ran","wendigo attack","courier story","почему курьер убежал","нападение вендиго","история курьера"}},{q="Почему у Хегнара Громострела закончились боеприпасы?",a="Дворфийские стрелки и минометные расчеты постоянно расходуют порох и свинец на учебные стрельбы возле лавки Хегнара, поэтому его товар в большом спросе.",al={"why low on ammo","rumbleshot out of ammo","почему мало боеприпасов","у громострела нет боеприпасов"}},{q="Кто такой Лослор Рудж?",a="Лослор Рудж — дворф, поставщик инженерных товаров в Поселке Сталежара, чье предприятие отправляет боеприпасы Хегнару Громострелу.",al={"loslor rudge","who is loslor","лослор рудж","кто такой лослор"}},{q="Портятся ли найденные боеприпасы в снегу?",a="Дворфийские боеприпасы традиционно упаковывают в тяжелые деревянные ящики с защитой от непогоды, чтобы черный порох оставался сухим и годным даже в морозных метелях Дун Морога.",al={"ammo ruined by snow","wet powder","боеприпасы испорчены снегом","мокрый порох"}}},fp="19,236,18.424.0,15.410.0,30.174.0,25.197.0,31.148.0,43.156.0,20.122.0,44.165.0"}
P.entries["quest:5545"] = {n="Тридцать три несчастья",s="Бригадир Раелен из Лесопилки Восточной долины не успевает в срок поставить древесину. Местные медведи и волки прогнали ее работников от свежесрубленного леса, и ценные связки бревен брошены в северных лесах. Она рассчитывает на отважных искателей приключений, которые войдут в кишащий зверями лес и вернут бревна, пока контракт не потерян.",h="Бригадир Раелен из Лесопилки Восточной долины не успевает в срок поставить древесину.",kw={"bears","bundle of wood","deputy rainer","eastvale","elwynn forest","logging camp","supervisor raelen","timber","wolves","медведи","связка бревен","заместитель судьи рейнер","восточная долина","элвиннский лес","лесопилка","бригадир раелен","древесина","волки"},ang={["class:Hunter"]="Пробираться по рощам, кишащим хищниками, возвращая припасы и справляясь с опасными зверями, — это прямо отвечает главным инстинктам выживания следопыта.",["faction:Alliance"]="Добыча леса в Восточной долине обеспечивает восстановление Штормграда и содержание региональных застав без дорогостоящих перебоев в поставках."},sec={{t="Горящий срок",b="Лесопилка Восточной долины поставляет важный лес для восстановления и обороны Королевства Штормград. Вести лесозаготовки на краю дикой местности опасно, и Бригадир Раелен сейчас в затруднении. Ее бригада отстала от графика по важной поставке леса, а время уходит."},{t="Хищники в лесу",b="Дело не в нехватке поваленных деревьев, а в агрессивных местных зверях. Голодные волки и медведи к северу от лесопилки прогнали дровосеков, и те бросили аккуратно связанные пучки бревен, разбросанные по лесу. Хотя городские власти о звериной угрозе предупреждены, Раелен не может ждать, пока стража очистит местность, и вынуждена нанять странствующих героев, чтобы те быстро собрали древесину."}},faq={{q="Кто такая Бригадир Раелен?",a="Бригадир Раелен руководит повседневной работой Лесопилки Восточной долины в восточной части Элвиннского леса. Она надзирает за бригадами дровосеков и следит, чтобы поставки леса удовлетворяли нужды Штормграда и местных поселений.",al={"supervisor raelen","raelen","eastvale supervisor","бригадир раелен","раелен","бригадир восточной долины"}},{q="Почему древесина брошена в лесу?",a="Рабочие уже срубили, обрезали и связали бревна в пучки, когда дикие медведи и рыскающие волки выгнали их с поляны. Опасаясь за жизнь, они бежали в лагерь, не увезя груз.",al={"why wood left","abandoned lumber","forest wood","почему брошено дерево","брошенная древесина","лес в чаще"}},{q="Почему Раелен упоминает Заместителя судьи Рейнера?",a="Раелен говорит, что сообщила Заместителю судьи Рейнеру об агрессивных хищниках. Любопытно, что Заместитель судьи Рейнер находится далеко, на другом краю Элвиннского леса, в Гарнизоне у Западного ручья, — значит, либо сообщения передавали по официальным каналам стражи, либо местная власть распределена по провинции слишком тонко.",al={"deputy rainer raelen","why deputy rainer","rainer connection","заместитель судьи рейнер раелен","почему рейнер","связь с рейнером"}},{q="Где нужна древесина?",a="Лесопилка Восточной долины снабжает лесом все королевство: от восстановления городской инфраструктуры до укрепления частоколов и мостов. Срыв сроков вредит местной экономике и останавливает стройки по всему Элвинну.",al={"who needs the wood","lumber delivery","timber purpose","кому нужна древесина","поставка леса","назначение древесины"}},{q="Почему дровосеки не могут забрать древесину сами?",a="Дровосеки — обычные рабочие, оснащенные для рубки деревьев, а не для борьбы с дикими хищниками. После нападения агрессивных волков и медведей никто из них не готов рисковать жизнью, возвращаясь в чащу безоружным.",al={"why loggers scared","why not loggers","loggers wolves","почему дровосеки боятся","почему не дровосеки","дровосеки волки"}},{q="Где найти связки бревен?",a="Связки срубленного леса лежат на земле в лесистых местах сразу к северу от Лесопилки Восточной долины, где работали люди, пока местные звери их не прогнали.",al={"wood location","where are bundles","find bundles","где древесина","где связки","найти связки"}}},fp="19,381,18.366.0,23.444.0,25.223.0,39.217.0,38.302.0,27.225.0,50.248.0,39.188.0"}
P.entries["quest:555"] = {n="Нежный черепаховый суп",s="Шеф-повар Джессен из Южнобережья гордится тем, что готовит лучшие блюда к северу от Штормграда, но недавние беспорядки лишили его запасов свежего мяса черепах-щелкунов. Чтобы вернуть в меню таверны свой знаменитый нежный черепаховый суп, он просит путешественников, разбирающихся в кулинарии, отважиться на опасные северные воды близ Даларана и озера Лордамер.",h="Шеф-повар Джессен из Южнобережья гордится тем, что готовит лучшие блюда к северу от Штормграда, но недавние...",kw={"chef jessen","cooking","dalaran","hillsbrad","lordamere lake","snapjaw","soothing turtle bisque","southshore","turtle meat","шеф-повар джессен","кулинария","даларан","хилсбрад","озеро лордамер","щелкун","нежный черепаховый суп","южнобережье","мясо черепахи"},ang={["faction:Alliance"]="Возвращение уюта в Южнобережье помогает поддерживать боевой дух местных жителей, пока город в изоляции противостоит враждебным разбойникам Синдиката и экспансии Отрекшихся.",["profession:Cooking"]="Шеф-повар Джессен делится своим мастерством только с собратьями по кулинарии и в награду дает вам рецепт, чтобы вы приготовили собственную порцию нежного черепахового супа.",["race:Human"]="Для людей, приезжих из южных королевств, стряпня Джессена — редкий вкус дома и гостеприимства на истерзанном севере."},sec={{t="Северный деликатес",b="Южнобережье остается одним из последних уцелевших прибрежных городков Альянса в Лордероне и гордо хранит мирную жизнь среди растущих смут в регионе. Шеф-повар Джессен утверждает, что его кухня не уступает ни одной таверне к северу от Штормграда, а посетители якобы приходят даже из Темнолесья в Сумеречном лесу ради его фирменного блюда — нежного черепахового супа. Этот наваристый восстанавливающий суп целиком зависит от свежего мяса черепах-щелкунов, обитающих в реках и озерах северных гор."},{t="Опасность на Лордамере",b="В более спокойные годы Джессен сам добывал мясо черепах, отправляясь за магический купол Даларана к восточным берегам озера Лордамер. Однако растущая напряженность, враждебные звери, Синдикат и вторжения Отрекшихся сделали сбор припасов за пределами города смертельно опасным для обычных горожан. Чтобы его котел продолжал кипеть, а посетители оставались довольны, повар полагается на вооруженных искателей приключений, готовых добывать мясо щелкунов вдоль речных берегов и северных побережий."}},faq={{q="Кто дает задание на нежный черепаховый суп?",a="Это задание посетившим его поварам предлагает шеф-повар Джессен, мастер кулинарии из прибрежного города Альянса Южнобережья в Предгорьях Хилсбрада.",al={"who gives soothing turtle bisque","where do i start soothing turtle bisque","chef jessen quest","кто дает нежный черепаховый суп","где начать нежный черепаховый суп","задание шеф-повара Джессена"}},{q="Почему шефу-повару Джессену нужна посторонняя помощь в добыче черепашьего мяса?",a="Раньше Джессен сам охотился на черепах-щелкунов возле Даларана и озера Лордамер, но из-за политических беспорядков и хищных зверей в регионе стало слишком опасно, и ему пришлось нанимать искателей приключений.",al={"why cant jessen get meat","why does jessen need turtles","почему джессен не может достать мясо","зачем джессену черепахи"}},{q="Где в этом регионе водятся черепахи-щелкуны?",a="Черепахи-щелкуны обитают вдоль пресноводной реки между Предгорьями Хилсбрада и Альтеракскими горами, а также на берегах озера Лордамер к северу от Даларана.",al={"turtle meat location","where are snapjaws","where to farm turtle meat","где мясо черепахи","где щелкуны","где добыть мясо черепахи"}},{q="Нужно ли уметь готовить, чтобы взять это задание?",a="Да. Шеф-повар Джессен делится этим заданием и своими кулинарными секретами только с путешественниками, обученными профессии «Кулинария», хотя определенный уровень навыка для принятия не требуется.",al={"is cooking required","cooking profession required","can anyone take soothing turtle bisque","нужна ли кулинария","нужна ли профессия кулинария","кто может взять нежный черепаховый суп"}},{q="Чем знаменита кухня Южнобережья?",a="Шеф-повар Джессен хвастается, что в Южнобережье подают лучшие блюда к северу от Штормграда, а его прославленный черепаховый суп якобы привлекал гостей даже из Темнолесья.",al={"southshore food","why is jessen famous","darkshire travel for bisque","еда южнобережья","чем знаменит джессен","темнолесье суп"}},{q="О каких беспорядках сокрушается шеф-повар Джессен?",a="Хилсбрад и Альтерак охвачены открытым конфликтом между Отрекшимися с севера, разбойниками Синдиката, бродящими среди руин, и дикими хищниками, изгнанными падением Лордерона, из-за чего путешествовать мирным жителям опасно.",al={"hillsbrad unrest","why is it dangerous now","what unrest","беспорядки в хилсбраде","почему сейчас опасно","какие беспорядки"}}},fp="22,334,19.495.0,18.473.0,48.147.0,61.203.0,46.175.0,47.178.0,35.180.0,39.212.0"}
P.entries["quest:556"] = {n="Каменные талисманы",s="«Каменные талисманы» — задание Орды, которое выдает Хранитель Бел'варил в Мельнице Таррен: добыть у агентов Даларана в Альтеракских горах магические артефакты связывания. Отрекшиеся хотят изучить тайные методы, которыми маги Даларана порабощают могущественных элементалей и командуют ими. Сбор этих инертных талисманов — основа исследований Магуса по подчинению элементалей.",h="«Каменные талисманы» — задание Орды, которое выдает Хранитель Бел'варил в Мельнице Таррен: добыть у агентов...",kw={"alterac mountains","binding","dalaran","elementals","hillsbrad foothills","keeper bel'varil","magus voidglare","stone tokens","tarren mill","worn stone token","альтеракские горы","связывание","даларан","элементали","предгорья хилсбрада","хранитель бел'варил","магус войдглар","каменные талисманы","мельница таррен","потертый каменный талисман"},ang={["class:Mage"]="Чародеи Даларана славятся умением подчинять элементалей своей воле; изучение этих талисманов показывает, как человеческие маги привязывают духов иных планов к материальным фокусам.",["class:Shaman"]="Хотя шаманы чтят элементалей на основе взаимных уз, волшебники Даларана используют тайные талисманы, чтобы подчинять и порабощать их — это противоречит духовной гармонии.",["race:Undead"]="Для Отрекшихся Мельницы Таррен раскрытие тайн магии Даларана жизненно важно, чтобы защитить Лордерон от человеческих чародеев, затаившихся за фиолетовым куполом."},sec={{t="Тайное подчинение",b="Маги Даларана давно обладают грозным мастерством управления элементалями: с помощью особых проводников и зачарованных фокусов они подчиняют существ из иных измерений. Хотя сам город скрыт под огромным фиолетовым куполом, его агенты и оставшиеся силы патрулируют окрестности, используя элементалей как рабочую силу и оборонительные ударные отряды. Маг Войдглар, исследователь тайной магии, работающий на Отрекшихся в Мельнице Таррен, стремится изучить точную магию, с помощью которой Даларан принуждает этих существ к повиновению."},{t="Сбор инертных образцов",b="Вместо того чтобы сразу требовать мощные и нестабильные магические предметы, Хранитель Бел'варил поручает агентам добыть потертые и поблекшие талисманы. Собрав эти истощенные обереги у персонала Даларана на окраинах и возле ближайшего лагеря для интернированных, Войдглар сможет безопасно изучить остаточные чары, не рискуя неконтролируемой реакцией иных миров. Эти выветрившиеся талисманы дают базовые теоретические знания, необходимые до испытаний более мощных механизмов связывания."}},faq={{q="Для чего нужны каменные талисманы?",a="Волшебники Даларана создают и носят эти каменные талисманы как магические фокусы для управления элементалями и их подчинения, заставляя существ из иных измерений служить стражами, часовыми и работниками.",al={"stone token purpose","why do dalaran wizards have stone tokens","what do the tokens do","назначение каменных талисманов","зачем магам даларана каменные талисманы","что делают талисманы"}},{q="Почему Магусу Войдглару нужны именно потертые талисманы?",a="Потертые каменные талисманы сохраняют основу магической матрицы заклинаний связывания Даларана, но их тайная сила угасла. Поэтому Магусу Войдглару гораздо безопаснее разбирать и изучать их, не опасаясь яростного ответа элементалей или взрывной магической отдачи во время первых опытов.",al={"why worn stone tokens","why not active tokens","почему потертые каменные талисманы","почему не активные талисманы"}},{q="Кто такой Хранитель Бел'варил?",a="Хранитель Бел'варил — Отрекшийся, выдающий задания в Мельнице Таррен в Предгорьях Хилсбрада. Он руководит тактическими операциями против человеческих сил в регионе и помогает исследователям вроде Магуса Войдглара, добывая магические артефакты и враждебные реагенты на соседних землях.",al={"belvaril","who gives stone tokens quest","бельварил","кто дает задание каменные талисманы"}},{q="Где силы Даларана хранят эти талисманы?",a="Талисманы носят волшебники Даларана и их персонал, занимающие пограничные земли между западным Хилсбрадом и Альтеракскими горами, особенно возле купола Даларана и руин старого лагеря для интернированных орков.",al={"where to find stone tokens","dalaran forces location","где найти каменные талисманы","где силы даларана"}},{q="Что происходит после доставки талисманов?",a="Когда Бел'варил осмотрит инертные образцы, Магус Войдглар переходит от теоретического изучения к физическому удержанию и поручает добыть более тяжелые наручи Связывания прямо у самих элементалей.",al={"what comes after stone tokens","stone tokens follow up","что после каменных талисманов","продолжение каменных талисманов"}},{q="Почему Орда изучает магию Даларана?",a="Отрекшиеся считают уцелевших магов Даларана прямой территориальной и магической угрозой в Лордероне. Разгадав их тайные методы, заклинатели Отрекшихся смогут противостоять действиям Кирин-Тора, защищать свои границы и, возможно, обратить силы элементалей себе на пользу.",al={"why horde wants dalaran magic","forsaken dalaran interest","почему орда хочет магию даларана","интерес отрекшихся к даларану"}}},fp="12,374,18.557.0,24.482.1,35.194.0,55.302.0,24.283.0,50.235.0,46.231.1,42.296.0"}
P.entries["quest:559"] = {n="Доказательство Фаррена",s="«Доказательство Фаррена» — задание Альянса в Южнобережье, которое выдает лейтенант Фаррен Оринель. Чтобы подтвердить своему начальнику, маршалу Редпату, успехи прибрежного патруля, Фаррен отправляет новобранцев собирать отрубленные головы мурлоков на Западном побережье.",h="«Доказательство Фаррена» — задание Альянса в Южнобережье, которое выдает лейтенант Фаррен Оринель.",kw={"farren","heads","hillsbrad","murloc","orinelle","redpath","southshore","strand","фаррен","головы","хилсбрад","мурлок","оринель","редпат","южнобережье","побережье"},ang={["faction:Alliance"]="Чтобы удержать Южнобережье, нужно обезопасить его берега от местных хищников, чтобы застава могла заняться угрозами со стороны Синдиката и Орды.",["profession:Cooking"]="Для поваров, готовящих рыбные блюда в Южнобережье, брезгливое отвращение Фаррена к морепродуктам непонятно, хотя сражения на пляже нередко приносят запасы сырого улова."},sec={{t="Неохотная просьба",b="После первых зачисток побережья на участке «На побережье» Лейтенант Фаррен Оринель оказался под пристальным вниманием маршала Редпата и городского начальства. Заявить о зачистке местных мурлоков — одно, а предъявить неопровержимые доказательства скептичным начальникам — совсем другое. Не желая пачкать руки кровавой разделкой, Фаррен поручает бродячим искателям приключений вернуться на берег и собрать осязаемое доказательство убийства."},{t="Жуткие доказательства",b="Задание ведет бойцов на запад от Южнобережья, на Западное побережье, где прибрежные мурлоки гнездятся на мелководье. Лейтенанту нужно десять отрубленных голов мурлоков, чтобы успокоить офицеров городского гарнизона. Сам Фаррен ненавидит этих тварей и признает, что омерзительный вид и запах рыболюдов-амфибий напрочь отбили у него аппетит к главному продукту и основной еде Южнобережья."}},faq={{q="Кто такой лейтенант Фаррен Оринель?",a="Лейтенант Фаррен Оринель — городской офицер Альянса, служащий в Южнобережье. Хотя он рвется доложить начальству об успехе, насильственную и грязную часть охраны побережья он предпочитает перепоручать толковым искателям приключений.",al={"farren orinelle","who gives farren's proof","lieutenant farren","фаррен оринель","кто дает доказательство фаррена","лейтенант фаррен"}},{q="Зачем Фаррену отрубленные головы мурлоков?",a="Маршала Редпата и городских чиновников не удовлетворили простые устные доклады о том, что Западное побережье зачищено. Они потребовали вещественных доказательств гибели мурлоков, прежде чем официально признать успех патруля.",al={"why murloc heads","farren proof reason","why collect heads","зачем головы мурлоков","причина доказательства фаррена","зачем собирать головы"}},{q="Где находятся эти мурлоки?",a="Мурлоки обитают на Западном побережье — прибрежных пляжах, тянущихся прямо на запад от Южнобережья к границе Серебряного бора.",al={"murloc head location","where is western strand","murloc spots hillsbrad","где головы мурлоков","где западное побережье","места мурлоков хилсбрад"}},{q="Что происходит после сдачи «Доказательства Фаррена»?",a="Фаррен просит сообщить о гибели мурлоков маршалу Редпату. Приняв доказательства, Редпат переключает внимание на угрозы на Восточном побережье, а позже передает приказы Штормграда о новом назначении Фаррена.",al={"next quest after farren's proof","farren quest chain","farren's proof followup","следующее задание после доказательства фаррена","цепочка заданий фаррена","продолжение доказательства фаррена"}},{q="Почему Фаррену противны мурлоки?",a="Фаррен находит ходячих двуногих рыб по своей природе отвратительными. Возня с их холодными склизкими останками окончательно отбила у него желание есть рыбу, и повседневная жизнь в рыбацкой общине Южнобережья стала для него мучением.",al={"farren fish","why doesn't farren like fish","фаррен рыба","почему фаррен не любит рыбу"}},{q="Кто такой маршал Редпат?",a="Маршал Редпат — командующий офицер в силах обороны города Южнобережья, отвечающий за то, чтобы младшие офицеры вроде Фаррена Оринеля отчитывались за безопасность региона.",al={"captain redpath","who is redpath","капитан редпат","кто такой редпат"}}},fp="14,256,18.467.0,15.392.0,34.226.0,42.222.0,32.138.0,45.214.1,39.217.0,23.187.0"}
P.entries["quest:56"] = {n="Ночной Дозор",s="Это задание выдает командир Алтея Чернодрев в Темнолесье: искателей приключений просят сократить число нежити, поднимающейся на соседнем Безмятежном кладбище. Штормград вывел из Темнолесья официальный гарнизон, и местное ополчение полагается на странствующих наемников, чтобы сдерживать наступающие ужасы.",h="Это задание выдает командир Алтея Чернодрев в Темнолесье: искателей приключений просят сократить число...",kw={"althea ebonlocke","darkshire","duskwood","night watch","skeletal mage","skeletal warrior","stormwind","tranquil gardens","алтея чернодрев","темнолесье","сумеречный лес","ночной дозор","скелет-маг","скелет-воин","штормград","безмятежное кладбище"},ang={["class:Paladin"]="Безмятежное кладбище — оскорбление для Света: оскверненные могилы павших горожан требуют освященной стали и праведного суда.",["class:Priest"]="Упокоить этих измученных неспокойных скелетов — акт духовного милосердия в краю, задыхающемся под зловещими проклятиями.",["faction:Alliance"]="Для сторонников Альянса это поручение обнажает горькую правду о равнодушии Штормграда: жителям окраин приходится проливать кровь ради собственного выживания без помощи короны."},sec={{t="Брошенные короной",b="Сумеречный лес некогда находился под защитой Штормграда, но когда ресурсы короны истощились, а в столице воцарились политические раздоры, корона отозвала своих солдат. Темнолесье осталось почти беззащитным перед наступающими тенями. В ответ жители леса создали Ночной Дозор — доморощенное ополчение, которое сейчас возглавляет командир Алтея Чернодрев. Оно стоит между проклятым лесом и оставшимися жителями города."},{t="Очистка Безмятежного кладбища",b="К югу от Темнолесья лежит Безмятежное кладбище — некогда мирное место упокоения, а теперь оно кишит неупокоенными скелетами и восставшими заклинателями. Поскольку силы Ночного Дозора опасно растянуты по границам Сумеречного леса, командир Чернодрев направляет прибывающих искателей приключений уничтожать скелетов-воинов и скелетов-магов, пока мертвецы кладбища не вышли на дороги."}},faq={{q="Почему Ночному Дозору нужна помощь со стороны?",a="Штормград отозвал из Сумеречного леса свой официальный гарнизон, и Темнолесье осталось один на один со своими бедами. Ночной Дозор — всего лишь местное ополчение, у которого нет ни людей, ни припасов, чтобы без посторонней помощи отбиться от растущего числа нежити на всей территории.",al={"why need help","why darkshire weak","why no guards","зачем нужна помощь","почему темнолесье слабое","почему нет стражи"}},{q="Кто такая командир Алтея Чернодрев?",a="Алтея Чернодрев — родственница бургомистра Темнолесья, лорда Элло Чернодрева, и решительный командир Ночного Дозора. Она взяла на себя обязанность организовать оборону города и собрать всех способных бойцов, готовых противостоять темным угрозам Сумеречного леса.",al={"who is althea","commander ebonlocke","althea ebonlocke lore","кто такая алтея","командир чернодрев","алтея чернодрев предания"}},{q="Где находится Безмятежное кладбище?",a="Безмятежное кладбище лежит к югу от Темнолесья. Это действующее место захоронений, ставшее жертвой темной магии, пропитавшей Сумеречный лес: мертвецы восстают и нападают на путников возле границ города.",al={"tranquil gardens location","where is cemetery","where to find skeletons","где безмятежное кладбище","где кладбище","где найти скелетов"}},{q="Какие существа восстают на Безмятежном кладбище?",a="Кладбище заполонили в основном оживленные скелеты-воины и скелеты-маги. В отличие от обычных трупов, эти останки сохранили остатки воинского мастерства и тайной силы, поэтому они смертельно опасны для простых горожан.",al={"what undead are there","skeletons in duskwood","какая там нежить","скелеты в сумеречном лесу"}},{q="Пришлет ли Штормград подкрепление?",a="Нет. Штормград отозвал своих стражей с постов и полностью предоставил отдаленную окраину Сумеречного леса самой себе.",al={"stormwind help duskwood","will stormwind send troops","штормград помощь сумеречный лес","пришлет ли штормград войска"}},{q="Положит ли это задание конец угрозе на кладбище?",a="Нет, истребление скелетов на Безмятежном кладбище — лишь первый шаг. Ночной Дозор сталкивается с растущими угрозами в глубине леса, и для борьбы с усиливающейся порчей на этой земле потребуются новые вылазки.",al={"is this the only quest","night watch chain","это единственное задание","цепочка ночного дозора"}}},fp="15,294,22.441.0,29.371.0,43.267.0,34.254.0,39.225.0,50.218.0,40.138.0,52.211.0"}
P.entries["quest:560"] = {n="Доказательство Фаррена",s="«Доказательство Фаррена» — короткое задание на доставку в Южнобережье: искатель приключений несет жуткую добычу — головы мурлоков — от лейтенанта Фаррена Оринеля маршалу Редпату. Позволив другому проделать кровавую работу по охоте на побережье, брезгливый лейтенант поручает ему и сам доклад. Это промежуточный шаг на пути к признанию в городе на побережье Хилсбрада.",h="«Доказательство Фаррена» — короткое задание на доставку в Южнобережье: искатель приключений несет жуткую...",kw={"alliance","errand boy","farren orinelle","farren's proof","hillsbrad foothills","marshal redpath","murloc heads","southshore","альянс","мальчик на побегушках","фаррен оринель","доказательство фаррена","предгорья хилсбрада","маршал редпат","головы мурлоков","южнобережье"},ang={["faction:Alliance"]="Каждое мелкое поручение в Южнобережье помогает укреплять главный оплот Альянса в Лордероне против враждебных сил, наступающих с севера и с моря.",["race:Human"]="Для людей общение с Фарреном и Редпатом — откровенный взгляд на натянутую бюрократию и усталость гарнизона Хилсбрада на границе."},sec={{t="Брезгливый офицер",b="Лейтенант Фаррен Оринель должен патрулировать и охранять южное побережье Предгорий Хилсбрада, однако у него слабый желудок для жестокой действительности приграничной войны. Отправив искателя приключений истреблять мурлоков, заполонивших пляжи, он отказывается даже прикасаться к отрубленным головам, принесенным в качестве доказательства. Вместо того чтобы лично нести окровавленные трофеи в командование Южнобережья, Фаррен охотно сваливает это поручение обратно на принесшего."},{t="Доклад Редпату",b="В Южнобережье маршал Редпат руководит обороной города и боевой готовностью на фоне растущих угроз со стороны Мельницы Таррен и диких зверей. Мешок с головами мурлоков, полученный через посыльного, а не от самого лейтенанта, его вовсе не удивляет. Понимая, что искатель приключений стал посыльным Фаррена, Редпат достаточно практичен, чтобы принять помощь: Южнобережью нужен весь усердный труд, какой только можно найти, чтобы удержать свои границы."}},faq={{q="Почему лейтенант Фаррен не доставляет головы мурлоков сам?",a="У лейтенанта Фаррена просто нет желания возиться с окровавленным мешком отрубленных голов мурлоков. Уже наняв искателя приключений для сражений, он находит гораздо удобнее поручить ему и грязную доставку маршалу Редпату.",al={"why farren not go","farren proof why deliver","why errand boy","почему фаррен не идет сам","доказательство фаррена зачем доставлять","почему посыльный"}},{q="Кто такой маршал Редпат?",a="Маршал Редпат — старший военный командир Альянса в Южнобережье. Он руководит местной обороной, координирует городскую стражу и занимается различными региональными угрозами, нависшими над человеческим поселением в Предгорьях Хилсбрада.",al={"who is redpath","marshal redpath lore","southshore marshal","кто такой редпат","маршал редпат предания","маршал южнобережья"}},{q="Что дальше в цепочке заданий после этой доставки?",a="Доставка доказательства ведет к новым поручениям от маршала Редпата и лейтенанта Фаррена и завершается официальными донесениями о размещении войск и бумагами, отправляемыми в столицу, в Штормград.",al={"what comes next","farren's proof next quest","redpath next quest","что дальше","доказательство фаррена следующее задание","следующее задание редпата"}},{q="Почему мурлоки — приоритет для гарнизона Южнобережья?",a="Племена мурлоков плотно гнездятся на пляжах побережья Хилсбрада. Если их не сдерживать, они грабят прибрежные пути снабжения, донимают местных рыбаков и угрожают южным подступам к Южнобережью, пока город и так занят Отрекшимися на севере.",al={"why kill murlocs","murloc problem southshore","hillsbrad murlocs","зачем убивать мурлоков","проблема мурлоков южнобережье","мурлоки хилсбрада"}},{q="Что маршал Редпат думает о поведении лейтенанта Фаррена?",a="Маршал Редпат хорошо знает привычки Фаррена и сухо замечает, что посыльный стал «мальчиком на побегушках у Фаррена». Тем не менее Редпат рад любой помощи, ведь Южнобережью приходится туго и нужны любые способные руки.",al={"redpath opinion on farren","does redpath like farren","мнение редпата о фаррене","нравится ли редпату фаррен"}},{q="Где в Южнобережье находится маршал Редпат?",a="Маршала Редпата можно найти возле центра города и здания совета в Южнобережье: он следит за повседневной обороной поселения.",al={"find redpath","where is marshal redpath","redpath location","найти редпата","где маршал редпат","местонахождение редпата"}}},fp="14,384,19.481.0,17.495.0,63.239.0,23.229.0,54.204.0,53.260.0,63.230.0,47.147.0"}
P.entries["quest:561"] = {n="Доказательство Фаррена",s="«Доказательство Фаррена» — задание Альянса на доставку в портовом городе Южнобережье. От имени маршала Редпата искатель приключений доставляет приказ лейтенанту Фаррену Оринелю: сосредоточить военные силы на нагах, наступающих на Восточное побережье.",h="«Доказательство Фаррена» — задание Альянса на доставку в портовом городе Южнобережье.",kw={"eastern strand","farren orinelle","farren's proof","hillsbrad","marshal redpath","naga","promotion","southshore","восточное побережье","фаррен оринель","доказательство фаррена","хилсбрад","маршал редпат","наги","повышение","южнобережье"},ang={["class:Warrior"]="Знакомое разочарование для воинов под знаменем Альянса — мелкая зависть и офицерские интриги, где боевое мастерство нередко сталкивается с честолюбием командиров.",["faction:Alliance"]="Этот разговор позволяет заглянуть в бюрократическое и карьерное соперничество, кипящее в гарнизоне Южнобережья: даже в осажденных северных форпостах офицеры борются за престиж."},sec={{t="Смена приказов",b="Военное руководство Южнобережья отбивается от окрестных угроз, но маршал Редпат по-прежнему внимателен к опасностям с моря на южном побережье. Получив свежие сведения о вторжениях нагов на Восточное побережье, Редпат посылает через город гонца к лейтенанту Фаррену Оринелю с прямым приказом: оставить второстепенные дела, уничтожить земноводную угрозу и докладывать о ходе дел лично маршалу."},{t="Соперничество на побережье",b="Получив сообщение, лейтенант Оринель выдает тихую неприязнь, зреющую среди офицеров гарнизона Южнобережья. Вместо добросовестного подчинения Оринель подозревает, что Редпат пользуется недавно полученными общими сведениями, чтобы присвоить заслугу за усмирение побережья. Решив не дать начальнику получить повышение за счет пота его солдат, Оринель тут же начинает замышлять собственный путь снискать расположение короны."}},faq={{q="Какова цель этой доставки?",a="Маршал Редпат намерен перенаправить солдат лейтенанта Фаррена Оринеля против нагов, наводнивших Восточное побережье Хилсбрада, и требует, чтобы Оринель лично докладывал ему, как только будет достигнут заметный успех.",al={"what does redpath want","why send message to farren","farren proof 3 objective","чего хочет редпат","зачем послание фаррену","доказательство фаррена 3 цель"}},{q="Почему Фаррен Оринель с горечью воспринимает приказы Редпата?",a="Оринель считает, что Редпат действует на основе тех же самых разведданных, которые они только что получили оба. Он опасается, что маршал намерен присвоить заслугу за очистку побережья и получить повышение за тяжелый труд Оринеля.",al={"farren redpath rivalry","why is orinelle mad","orinelle promotion","соперничество фаррена и редпата","почему оринель зол","повышение оринеля"}},{q="Где находится Восточное побережье?",a="Восточное побережье тянется вдоль южной морской береговой линии Предгорий Хилсбрада к юго-востоку от Южнобережья, где наступающие наги устроили на песке мерзкие лагеря.",al={"eastern strand location","where are the naga","hillsbrad coast","восточное побережье где","где наги","побережье хилсбрада"}},{q="Что будет после доставки этого сообщения?",a="После этой встречи Оринель придумывает собственный план вместо того, чтобы безропотно подчиниться власти Редпата, и направляет посыльных искателей приключений вдоль побережья к верховному командованию в задании «Ха, Штормград!».",al={"next quest","what happens next","stormwind ho follow up","следующее задание","что дальше","ха, штормград продолжение"}},{q="Какие командиры участвуют в этом разговоре?",a="Маршал Редпат — главный командир гарнизона Южнобережья, а лейтенант Фаррен Оринель служит под его началом полевым лейтенантом, руководящим береговой обороной.",al={"who are farren and redpath","southshore officers","farren orinelle and redpath","кто такие фаррен и редпат","офицеры южнобережья","фаррен оринель и редпат"}},{q="Требуется ли в этом задании сражаться?",a="Нет. Этот шаг — чисто внутреннее поручение по передаче сообщения между офицерами Южнобережья, хотя оно напрямую связано с военным ответом на враждебных нагов на берегу.",al={"is there fighting","do i fight naga","farrens proof combat","есть ли бой","нужно ли сражаться с нагами","доказательство фаррена бой"}}},fp="14,268,18.467.0,20.452.1,37.209.0,60.210.0,36.198.0,46.211.1,46.174.0,40.187.0"}
P.entries["quest:562"] = {n="Ха, Штормград!",s="Лейтенант Фаррен Оринель отчаянно хочет вырваться из Южнобережья и вернуться на юг, в Штормград. Услышав, что верховное командование Альянса опасается растущей угрозы со стороны наг, он видит шанс для карьеры и нанимает искателя приключений, чтобы тот истребил змеелюдов: так он присвоит заслугу себе и добьется перевода.",h="Лейтенант Фаррен Оринель отчаянно хочет вырваться из Южнобережья и вернуться на юг, в Штормград.",kw={"daggerspine","farren orinelle","hillsbrad foothills","naga","reassignment","samuelson","southshore","stormwind ho","пронзающий гребень","фаррен оринель","предгорья хилсбрада","наги","перевод","самуэльсон","южнобережье","ха, штормград"},ang={["faction:Alliance"]="Командная структура Альянса в Хилсбраде растянута до предела, и простые городские стражники оказываются беспомощны перед такими чудовищными угрозами, как наги Пронзающего Гребня.",["race:Human"]="Для людей, служащих в Лордероне, Южнобережье — мрачное напоминание об утраченной северной славе, резко контрастирующее с отстроенным величием и безопасностью Штормграда на юге."},sec={{t="Билет из Южнобережья",b="Южнобережье находится на самом острие Лордерона, зажатое между силами Отрекшихся, бандитами Синдиката и неутомимыми морскими тварями. Для лейтенанта Фаррена Оринеля, обычного стражника, привыкшего к городским пьяницам и мелким дракам в Штормграде, такая служба просто невыносима. Когда от его бывшего наставника приходит весть, что верховное командование Альянса все сильнее тревожится из-за наг, наступающих на побережье, Фаррен видит прекрасную возможность покинуть север."},{t="Чужая слава на побережье",b="Несмотря на высокие амбиции, Фаррен открыто признает свою трусость: сразиться в открытом бою со свирепыми сиренами и береговыми охотниками Пронзающего Гребня ему не по храбрости и не по силам. Вместо того чтобы рисковать шкурой, он поручает искателю приключений прочесать пляжи к юго-востоку от Южнобережья, проредить ряды наг и совершить боевые подвиги, нужные ему для внушительного донесения майору Самуэльсону в Штормград."}},faq={{q="Почему Фаррен Оринель хочет убить наг?",a="Сами наги его не волнуют: он хочет уехать из Южнобережья. От наставника Фаррен узнал, что верховное командование Альянса обеспокоено угрозой наг, поэтому успешные операции против них — быстрый путь к повышению или переводу обратно в Штормград.",al={"why naga","farren motive","why kill naga in southshore","почему нааги","мотив фаррена","зачем убивать наг в южнобережье"}},{q="Может ли лейтенант Фаррен Оринель сразиться с нагами сам?",a="Нет. Фаррен открыто признает, что он всего лишь городской стражник, способный разнимать пьяные драки в тавернах или арестовывать буйных попрошаек. Свирепые наги Пронзающего Гребня внушают ему ужас, и ему приходится целиком полагаться на приезжих искателей приключений.",al={"why doesn't farren fight","is farren weak","farren combat","почему фаррен не сражается","слаб ли фаррен","бой фаррена"}},{q="Где находятся наги Пронзающего Гребня?",a="Береговые охотники и сирены Пронзающего Гребня устроили лагеря на побережье прямо к юго-востоку от поселения Южнобережье и бродят по берегам Великого моря в Предгорьях Хилсбрада.",al={"where are naga","daggerspine location","southshore naga beach","где наги","пронзающий гребень расположение","наги на пляже южнобережья"}},{q="Кто такой майор Самуэльсон?",a="Майор Самуэльсон — бывший наставник Фаррена Оринель в страже Штормграда. Фаррен готовит для него отчеты об истребленных нагах в надежде, что Самуэльсон задействует нужные связи и добьется для него перевода обратно на юг.",al={"major samuelson","samuelson stormwind","who gets the letter","майор самуэльсон","самуэльсон штормград","кому письмо"}},{q="Что происходит после выполнения этого задания?",a="Когда угроза наг будет ослаблена, а Фаррен присвоит вашу работу себе, он отправит вас на юг, в Крепость Штормграда, чтобы вы лично передали майору Самуэльсону его отчет и просьбу о переводе.",al={"what comes next","next quest after stormwind ho","reassignment quest","что дальше","следующее задание после ха штормград","задание о переводе"}},{q="Почему Фаррен так ненавидит Южнобережье?",a="Фаррен считает Южнобережье мрачным и опасным пограничным постом, далеким от цивилизованной безопасности Штормграда. Из-за соседей-нежити и прибрежных чудовищ он с горечью называет его «Покинутым Светом портом».",al={"why does farren hate southshore","light forsaken port","почему фаррен ненавидит южнобережье","покинутый светом порт"}}},fp="13,322,26.475.0,25.402.0,47.272.0,54.243.0,39.195.0,23.229.0,40.184.1,40.215.0"}
P.entries["quest:5621"] = {n="Облачение Луны",s="Облачение Луны — вводный обряд служения для юных жрецов-ночных эльфов в Доланааре. Задание дает наставница жрецов Лорна Утренний Свет: неофит должен позаботиться о раненой Часовой Шае, патрулирующей лес к югу от поселения. Выполнение этого долга означает официальное признание неофита в Сестринстве Элуны.",h="Облачение Луны — вводный обряд служения для юных жрецов-ночных эльфов в Доланааре.",kw={"dolanaar","garments of the moon","in favor of elune","laurna morninglight","sentinel shaya","sisterhood of elune","teldrassil","доланаар","облачение луны","во имя элуны","лорна утренний свет","часовая шая","сестринство элуны","тельдрассил"},ang={["class:Priest"]="Этот обряд показывает два столпа жречества: исцеление раненых союзников целительной молитвой и защиту их от будущей опасности божественными оберегами.",["race:NightElf"]="Для кальдораев Сестринство Элуны и Часовые тысячелетиями действуют рука об руку, защищая леса и народ от наступающей тьмы."},sec={{t="Священное призвание",b="В ветвях Тельдрассила Сестринство Элуны заботится как о духовной жизни кальдораев, так и о практической защите их границ. Когда часовая Шайя ранена во время патруля в опасной глуши к югу от Доланаара, жрица-наставница Лорна Утренний Свет не может покинуть свой пост, чтобы оказать помощь. Вместо этого она поручает недавно обученной послушнице доказать свою преданность: залечить раны Шайи и укрепить ее здоровье защитной магией."},{t="Облачения Сестринства",b="Жрецы, восстановившие силы Часовой Шаи, возвращаются в Доланаар, чтобы получить официальные одеяния. Эти облачения означают, что юный послушник перешел от простых занятий к практическому, спасающему жизни служению под покровом Луны. В обществе кальдораев поддержка Часовых — не просто военная задача, а акт единения с Элуной и важнейший долг ради безопасности Тельдрассила."}},faq={{q="Кто дает задание «Облачение Луны»?",a="Задание дает Лорна Утренний Свет, наставница жрецов, живущая в северном здании Доланаара в Тельдрассиле.",al={"who gives garments of the moon","where to start garments of the moon","garments of the moon questgiver","кто дает облачение луны","с чего начать облачение луны","кто выдает задание облачение луны"}},{q="Кому нужна помощь в этом задании?",a="Часовая Шая, ночная эльфийка-стражница, раненная во время патруля в глуши, ждет помощи к югу от Доланаара.",al={"who do i heal","injured sentinel location","where is sentinel shaya","кого лечить","где раненый часовой","где часовая шая"}},{q="Какая магия нужна, чтобы помочь Часовой Шае?",a="Вы должны исцеляющей магией закрыть раны Часовой Шаи и наложить защитные чары, укрепляющие ее выносливость, а затем вернуться в Доланаар.",al={"what spells to cast on shaya","how to complete garments of the moon","shaya objective","какие заклинания на шаю","как выполнить облачение луны","цель шаи"}},{q="Может ли любой класс взять это задание?",a="Нет. Задание «Облачение Луны» предлагают только жрецам-ночным эльфам как ранний этап их духовного обучения.",al={"is garments of the moon priest only","garments of the moon class requirement","can druids do garments of the moon","облачение луны только для жрецов","облачение луны требования к классу","могут ли друиды облачение луны"}},{q="Что символизирует награда — одеяние?",a="Одеяние, которое вручает Лорна Утренний Свет, служит знаком посвящения: вы преданно послужили Элуне и заслужили признанное место среди местного жречества.",al={"garments of the moon robe meaning","robe reward lore","significance of garments of the moon","смысл одеяния облачение луны","предания об одеянии","значение облачения луны"}},{q="Как связаны это задание и «Во имя Элуны»?",a="«Во имя Элуны» — вводный призыв посетить наставницу в Доланааре. Оно не обязательно для получения «Облачения Луны», но его нельзя выполнить после завершения «Облачения Луны».",al={"in favor of elune prerequisite","in favor of elune missed","order of dolanaar priest quests","во имя элуны предварительное условие","пропустил во имя элуны","порядок заданий жрецов доланаара"}}},fp="20,354,16.470.0,27.414.0,42.124.0,32.135.0,46.140.0,30.119.0,36.178.0,66.208.0"}
P.entries["quest:5622"] = {n="Во имя Элуны",s="«Во имя Элуны» — обряд посвящения для юных жрецов-ночных эльфов, готовых покинуть укромные ветви Тенистой долины. По указанию жрицы Шанды послушники отправляются по тропе в Доланаар, чтобы получить дальнейшие наставления и обучение у Лорны Утреннего Света.",h="«Во имя Элуны» — обряд посвящения для юных жрецов-ночных эльфов, готовых покинуть укромные ветви Тенистой...",kw={"dolanaar","garments of the moon","in favor of elune","laurna morninglight","priest","shadowglen","shanda","teldrassil","доланаар","облачение луны","во имя элуны","лорна утренний свет","жрец","тенистая долина","шанда","тельдрассил"},ang={["class:Priest"]="Это задание означает ваш переход от простых занятий послушника к полноценному служению и ведет вас к получению первых освященных жреческих одеяний.",["race:NightElf"]="Сестринство Элуны — духовное сердце и историческое руководство общества кальдораев, поэтому путь в Доланаар — глубоко традиционный рубеж для верующих."},sec={{t="Покидая долину",b="Для неофита, служащего Элуне в уединенном убежище Альдрассила, обучение начинается с простых молитв и защитных призываний под присмотром жрицы Шанды. Но замкнутая жизнь Тенистой долины не может подготовить жрицу или жреца к смуте, охватившей большой мир. Когда неофит проявляет стойкую веру и дисциплину, Шанда отправляет его по тенистой лесной тропе в Доланаар для продолжения обучения."},{t="Шаг к жречеству",b="Прибытие в Доланаар — важный рубеж на божественном пути ночного эльфа. Там ждет Лорна Утренний Свет, уважаемая жрица, которой поручено готовить учеников к испытаниям, стоящим перед Тельдрассилом. Помимо продвинутого обучения лунному колдовству, прибытие в Доланаар готовит послушника к получению первых официальных облачений, означающих его положение в Сестринстве Элуны."}},faq={{q="Кто отправляет меня в это путешествие?",a="Жрица Шанда, наставница жрецов-ночных эльфов, живущая в ветвях Альдрассила в Тенистой долине, дает вам это напутствие, когда ваше начальное обучение завершено.",al={"quest giver","who starts in favor of elune","where do i get this quest","персонаж, выдающий задания","кто начинает во имя элуны","где взять это задание"}},{q="Куда идти, чтобы найти Лорну Утренний Свет?",a="Лорна Утренний Свет живет в Доланааре, первом крупном поселении к югу от ворот Тенистой долины в Тельдрассиле. Она находится в северном здании деревни.",al={"laurna morninglight location","where is dolanaar","where is morninglight","где лорна утренний свет","где доланаар","где утренний свет"}},{q="Может ли любой класс взять это задание?",a="Нет. Это задание предназначено именно для юных жрецов-ночных эльфов, делающих первые шаги в Сестринстве и служении Элуне.",al={"is this priest only","who can do in favor of elune","druid quest?","только для жрецов","кто может выполнить во имя элуны","задание друида"}},{q="Что будет после разговора с Лорной Утренним Светом?",a="Лорна Утренний Свет поприветствует вас и предложит испытание «Облачение Луны», проверяющее вашу способность защищать и исцелять раненых защитников, после чего вам вручат первые официальные жреческие одеяния.",al={"what comes next","followup quest","garments of the moon quest","что дальше","следующее задание","задание облачение луны"}},{q="Обязательно ли это задание для продолжения обучения жрецов?",a="Это необязательное вводное задание. Если вы дойдете до Доланаара сами, Лорна Утренний Свет все равно предложит обучение и последующие задания без этого вступления.",al={"do i have to do in favor of elune","can i skip in favor of elune","optional breadcrumb","обязательно ли во имя элуны","можно ли пропустить во имя элуны","необязательное задание"}},{q="Почему получение облачений так важно для Сестринства?",a="Одеяния в культуре ночных эльфов — не просто ткань, а священные символы, обозначающие чье-то официальное положение, преданность и готовность направлять благословения Богини Луны на службу своему народу.",al={"why robes matter","significance of garments","station of elune priestess","почему важны одеяния","значение облачений","положение жрицы элуны"}}},fp="17,264,17.441.0,26.398.0,29.166.0,50.172.0,30.142.0,50.194.0,52.189.0,55.201.0"}
P.entries["quest:5623"] = {n="Во имя Света!",s="«Во имя Света» — ранний этап для жрецов-новичков, обучающихся в Долине Североземья. Задание дает жрица Анетта: оно направляет начинающего служителя из уединенного аббатства в Златоземье. Там его ждет жрица Жозетта, чтобы углубить его духовную дисциплину и повести дальше по пути веры в Свет.",h="«Во имя Света» — ранний этап для жрецов-новичков, обучающихся в Долине Североземья.",kw={"anetta","church","elwynn forest","goldshire","holy light","josetta","northshire","priest quest","анетта","церковь","элвиннский лес","златоземье","свет","жозетта","североземье","задание жреца"},ang={["class:Priest"]="Этот обряд соединяет ваше уединенное обучение в Североземье с деятельным пастырским служением среди жителей и гарнизонов Элвиннского леса.",["faction:Alliance"]="Церковь Священного Света — один из главных столпов Альянса, воспитывающий преданных целителей, способных поддерживать защитников на передовой.",["race:Human"]="Для людей Штормграда поиск наставлений у жречества в Златоземье — важный шаг в поддержании нравственного и духовного стержня королевства."},sec={{t="За пределы Североземья",b="Аббатство Североземья дает новичкам кров и начальное обучение, но жреческая подготовка в Церкви Священного Света требует практического служения в мире. Когда неофит показывает базовое владение молитвой и божественным исцелением, жрица Анетта отправляет его на юг по залитым солнцем дорогам в Златоземье. Это путешествие означает переход от затворника-ученика к деятельному служителю прихода среди повседневных забот жителей Элвинна."},{t="Наставничество в Златоземье",b="В таверне «Гордость Льва» в Златоземье жрица Жозетта заботится о духовных нуждах местных жителей и наставляет растущих послушников. Жозетта опирается на основы, заложенные в аббатстве, и проверяет умение неофита утешать, оберегать верных и исцелять раненых. Оказавшись под ее руководством, юный жрец знакомится с обязанностями служителей Церкви во всем королевстве."}},faq={{q="Кто дает это задание и кому докладывать?",a="Задание дает жрица Анетта в Аббатстве Североземья, отправляя вас по дороге к жрице Жозетте в Златоземье.",al={"who gives in favor of the light","quest turn in","where to turn in in favor of the light","кто дает во имя света","сдача задания","где сдать во имя света"}},{q="Почему жреца так рано отправляют из Североземья?",a="Североземье дает основы знаний о Свете, но юные служители должны быстро начать служить настоящим общинам. Златоземье — это готовая приходская среда, где послушник может помогать простым горожанам и городской страже под руководством Жозетты.",al={"why go to goldshire","why leave northshire abbey","зачем идти в златоземье","зачем покидать аббатство североземья"}},{q="Где найти жрицу Жозетту в Златоземье?",a="Жрица Жозетта живет в таверне «Гордость Льва» в Златоземье и служит местной наставницей жрецов.",al={"where is priestess josetta","find josetta","josetta location","где жрица жозетта","найти жозетту","жозетта расположение"}},{q="Что будет после встречи с жрицей Жозеттой?",a="Жрица Жозетта сразу проверяет ваше обучение следующим заданием «Облачение Света»: нужно позаботиться о раненом стражнике и получить церемониальные жреческие одеяния.",al={"next quest after in favor of the light","what follows in favor of the light","следующее задание после во имя света","что дальше во имя света"}},{q="Доступно ли это задание только жрецам?",a="Да. Это задание — формальное духовное обучение в Церкви Священного Света, и его предлагают только послушникам-жрецам.",al={"can any class do in favor of the light","is this priest only","любой класс во имя света","только ли для жрецов"}},{q="Какую роль играет Церковь Священного Света в Элвиннском лесу?",a="Церковь дает утешение, духовное руководство и телесное исцеление горожанам и защитникам, которым все чаще приходится сталкиваться с бандитизмом и вторжениями диких зверей по всему лесу.",al={"church of the holy light role","priests in elwynn","роль церкви священного света","жрецы в элвиннском лесу"}}},fp="21,329,26.447.0,21.407.0,45.123.0,51.268.0,50.104.0,45.199.0,36.131.0,59.170.0"}
P.entries["quest:5624"] = {n="Облачение Света",s="«Облачение Света» — начальное испытание для жрецов-новичков в Златоземье, которое выдает жрица Жозетта. Вместо отвлеченного испытания веры церковь посылает послушника на восток, к Озеру Хрустальному, исцелить и укрепить раненого стражника Робертса. Выполнив этот долг, ученик доказывает свое мастерство целителя и получает первое официальное облачение, признанное Церковью Священного Света.",h="«Облачение Света» — начальное испытание для жрецов-новичков в Златоземье, которое выдает жрица Жозетта.",kw={"crystal lake","elwynn forest","garments of the light","goldshire","guard roberts","lesser heal","power word fortitude","priest robe","priestess josetta","озеро хрустальное","элвиннский лес","облачение света","златоземье","стражник робертс","малое исцеление","слово силы: стойкость","одеяние жреца","жрица жозетта"},ang={["class:Priest"]="Этот обряд посвящения связывает теоретическое богословие в Североземье с практической службой, подтверждая, что высшее призвание жреца — сохранять жизнь соратникам на передовой прямым исцелением и укрепляющими оберегами.",["faction:Alliance"]="Поскольку армия Штормграда перегружена и отсутствует в местных деревнях, городская стража во многом полагается на помощь послушников церкви, чтобы устоять перед надвигающимися угрозами.",["race:Human"]="Люди глубоко почитают Церковь Священного Света; получение облачения от жрицы поселения становится важной гражданской и духовной вехой в жизни послушника."},sec={{t="Практическое испытание веры",b="По традициям Церкви Священного Света новичков редко возвышают только за знание доктрины. Жрица Жозетта, наставляющая послушников, прибывающих в Златоземье из Аббатства Североземья, проверяет практическое владение божественной силой, прежде чем даровать официальное признание церкви. Когда в город доходит весть, что стражник Робертс лежит раненый у озера к востоку от Златоземья, Жозетта превращает обычное несчастье в испытание и отправляет молодого жреца помочь ему."},{t="Опора королевства",b="Задание требует большего, чем просто закрыть раны: послушник должен исцелить раны стражника целительными молитвами и укрепить его выносливость благословением стойкости. В это тяжелое время, когда армия Штормграда растянута, а местные гарнизоны осаждают кобольды и бандиты, Жозетта подчеркивает, что долг жречества напрямую связан с выживанием воинов. Возвращая стражника Робертса в строй, послушник сразу приносит пользу поселению и показывает, что способен поддерживать защитников под огнем."},{t="Облачение ордена",b="Вернувшись в Таверну Гордость Льва после лечения солдата, молодой жрец получает свой первый официальный комплект одеяний. Эти одежды означают внешнее одобрение и братство жречества Штормграда. Хотя носить их для дальнейшего обучения не обязательно, одеяния служат видимым свидетельством того, что церковь признает владельца посвященным служителем Света."}},faq={{q="Где найти стражника Робертса?",a="Стражник Робертс находится к востоку от Златоземья, у берегов Озера Хрустального. Его можно найти отдыхающим у дороги и кромки воды: он оправляется от ран, полученных во время дозора.",al={"guard roberts location","where is guard roberts","find guard roberts","где стражник робертс","местонахождение стражника робертса","найти стражника робертса"}},{q="Какие заклинания нужны для выполнения этого задания?",a="Вы должны помочь стражнику Робертсу: применить к нему «Малое исцеление» (2-й уровень), чтобы восстановить здоровье, затем «Слово силы: Стойкость», чтобы укрепить его выносливость, и вернуться к жрице Жозетте.",al={"spells needed","what spells do i cast on roberts","how to heal guard roberts","нужные заклинания","какие заклинания применить на робертса","как исцелить стражника робертса"}},{q="Кто такая жрица Жозетта?",a="Жрица Жозетта — наставница жрецов от Церкви Священного Света, живущая в Таверне Гордость Льва в Златоземье. Она опекает молодых послушников, покинувших Аббатство Североземья, и обучает их практическому служению и божественной магии.",al={"josetta lore","priestess josetta goldshire","who gives garments of the light","жозетта предания","жрица жозетта златоземье","кто выдает облачение света"}},{q="Почему Церковь выдает одеяния за это задание?",a="Одеяния — внешний знак того, что Церковь Священного Света официально одобряет послушника и поддерживает его служение. Выполнив это практическое задание по исцелению, неофит доказывает, что обладает умением и дисциплиной, достойными церковного облачения.",al={"why garments of the light","priest robe reward lore","church robes meaning","почему облачение света","награда жреца одеяние предания","значение церковных одеяний"}},{q="Могут ли другие классы выполнить это задание?",a="Нет. Это задание входит во вводную цепочку заданий класса специально для жрецов Альянса, освоивших основные молитвы исцеления и защиты.",al={"is garments of the light priest only","can paladins do garments of the light","priest class quest","облачение света только для жрецов","могут ли паладины облачение света","задание класса жрец"}},{q="Что происходит после выполнения «Облачения Света»?",a="«Облачение Света» завершает начальную цепочку посвящения жрецов 4-го уровня в Златоземье. Прямого продолжения нет, но жрица Жозетта и другие наставники по всему королевству предложат продвинутое обучение и новые испытания по мере роста вашего опыта.",al={"next quest after garments of the light","garments of the light followup","следующее задание после облачения света","облачение света продолжение"}}},fp="21,390,25.489.0,20.527.0,22.402.0,31.190.0,48.185.0,25.224.0,49.260.0,38.157.0,52.271.0"}
P.entries["quest:5625"] = {n="Облачение Света",s="«Облачение Света» — начальный обряд посвящения для юных жрецов-дворфов в Дун Мороге. По указанию наставника жрецов Максана Анвола в Караносе посвящаемый должен помочь раненому горному пехотинцу неподалеку от города, чтобы заслужить облачение.",h="«Облачение Света» — начальный обряд посвящения для юных жрецов-дворфов в Дун Мороге.",kw={"dun morogh","fortitude","garments of the light","holy light","ironforge","kharanos","lesser heal","maxan anvol","mountaineer dolf","priest","дун морог","стойкость","облачение света","свет","стальгорн","каранос","малое исцеление","максан анвол","горный стрелок дольф","жрец"},ang={["class:Priest"]="Этот обряд знаменует ваш переход от неопытного новичка к признанному служителю Света, которому доверено сохранять жизнь соратникам на передовой.",["faction:Alliance"]="Свет — духовная опора Альянса, дающая утешение и исцеление на поле боя солдатам, удерживающим рубеж против троггов, зверей и худших врагов.",["race:Dwarf"]="Горные пехотинцы Стальгорна охраняют опасные перевалы Дун Морога; помощь раненым разведчикам вроде Дольфа укрепляет важную связь между верой дворфов и военной обороной."},sec={{t="Неотложное испытание",b="Традиционно послушники Света проходят официальные испытания, чтобы доказать, что достойны носить церковное облачение. Однако в Караносе наставник жрецов Максан Анвол ценит практический результат выше церемоний. Когда местные патрули едва справляются с троггами и дикими зверями, теоретические экзамены отходят на второй план, если защитники истекают кровью на снегу."},{t="Помощь горным пехотинцам",b="Чтобы заслужить одеяния, молодых жрецов отправляют к югу от города искать горного пехотинца Дольфа, раненного при исполнении долга. Исцелив раны Дольфа целительными молитвами и укрепив его телосложение «Словом силы: Стойкость», посвящаемый доказывает, что его преданность напрямую превращается в выживание защитников Стальгорна."},{t="Одеяния Церкви",b="После помощи горному пехотинцу Максан Анвол вручает послушнику официальное облачение. Помимо защиты от холода Дун Морога, эти одеяния служат знаком отличия и показывают раненым путникам и местной страже, что рядом находится служитель Света, готовый помочь."}},faq={{q="Какова цель этого задания?",a="Задание проверяет, как жрец-новичок применяет на практике свои первые заклинания. Вместо академического экзамена наставник Максан Анвол отправляет вас найти раненого горного пехотинца Дольфа к югу от Караноса, исцелить его раны и укрепить его выносливость «Словом силы: Стойкость».",al={"what do i do","garments of the light goal","что делать","цель облачения света"}},{q="Кто такой Максан Анвол?",a="Максан Анвол — наставник жрецов-дворфов в Караносе. Прагматичный и скромный, он обучает молодых жрецов, прибывающих из Холодной долины, и подчеркивает прямую, спасающую жизни пользу Света, а не строгую официальную литургию.",al={"who is maxan anvol","kharanos priest trainer","кто такой максан анвол","наставник жрецов каранос"}},{q="Кто такой горный стрелок Дольф?",a="Дольф — горный стрелок Стальгорна, расквартированный неподалеку от Караноса, получивший ранения в патруле. Он ждет к югу от поселения и служит практическим испытанием для посвящаемых, которых посылают исцелить его раны и даровать ему стойкость.",al={"dolf location","who is dolf","где дольф","кто такой дольф"}},{q="Почему жрец получает особое облачение за это задание?",a="Облачения и одеяния наглядно показывают преданность и положение служителя Света. И жители, и солдаты, увидев жреца в одеянии, сразу понимают, что перед ними тот, кто способен лечить смертельные раны и давать духовное наставление.",al={"why do priests wear robes","priest garments lore","почему жрецы носят одеяния","облачение жреца предания"}},{q="Почему дворфы поклоняются Свету?",a="Дворфы Стальгорна переняли философию Света за века тесного культурного обмена и союза с людьми Лордерона и Штормграда. Жрецы-дворфы сочетают традиционную горную суровость с искренним почитанием добродетелей Света — сострадания, стойкости и защиты.",al={"dwarf light lore","do dwarves believe in the light","дворфы свет предания","верят ли дворфы в свет"}},{q="Что происходит после этого испытания?",a="Максан Анвол призывает новоиспеченного послушника отправиться в путь, оттачивать боевые заклинания и заклинания поддержки и проверять свои пределы вместе с другими путниками. Более трудные испытания церкви ждут жреца по мере роста его опыта и силы.",al={"what comes after garments of the light","next priest trial","что после облачения света","следующее испытание жреца"}}},fp="21,246,15.353.0,23.345.0,19.304.0,34.274.0,19.237.0,24.223.0,58.268.0,38.304.0,41.237.0"}
P.entries["quest:5626"] = {n="Во имя Света",s="«Во имя Света» — обряд посвящения молодого жреца, выводящий его из уединенных учебных земель Холодной долины в широкие просторы Дун Морога. По указанию Бранстока Халдера послушники идут через горный туннель в Каранос, чтобы продолжить обучение у наставника жрецов Максана Анвола. Это знак того, что послушник готов принять настоящую ответственность и заслужить традиционное облачение своего призвания.",h="«Во имя Света» — обряд посвящения молодого жреца, выводящий его из уединенных учебных земель Холодной долины...",kw={"branstock khalder","coldridge valley","dun morogh","in favor of the light","kharanos","light","maxan anvol","priest","vestments","брансток халдер","холодная долина","дун морог","во имя света","каранос","свет","максан анвол","жрец","облачение"},ang={["class:Priest"]="Это задание — веха для юных жрецов: оно означает их официальный переход от базовой подготовки к активной службе и получение первого облачения.",["race:Dwarf"]="Жречество дворфов сочетает духовную преданность с практической стойкостью, отправляя послушников прямо из горнов Холодной долины в суровые морозные ветра Дун Морога."},sec={{t="Прощание со Старой Наковальней",b="В уединенной колыбели Холодной долины жрецы-дворфы начинают обучение под присмотром наставников вроде Бранстока Халдера. Когда новичок проявляет достаточное усердие и понимание магии Света, его начальное обучение подходит к концу. Вместо того чтобы держать способных учеников под защитой в Старой Наковальне, Халдер направляет их за горы, в Каранос, где служение и оборона пересекаются с повседневными трудностями жителей Дун Морога."},{t="Шаг к Караносу",b="Чтобы добраться до Караноса, нужно пройти через Туннель Холодной долины в продуваемые ветрами снега центрального Дун Морога. В поселении ждет Максан Анвол, старший жрец, которому поручено вести учеников дальше простейших молитв. Анвол твердо уверен, что преданность Свету требует в равной мере нравственного характера, физической выносливости и несгибаемой воли. Для послушников, доказавших свою решимость под его руководством, Анвол готовит первое официальное облачение."}},faq={{q="Кто посылает вас в это путешествие?",a="Брансток Халдер, наставник жрецов-дворфов в Старой Наковальне в Холодной долине, посылает вас в Каранос, когда вы проявили достаточные способности в обращении со Светом для продвинутого обучения.",al={"who gives quest","quest giver","branstock khalder","кто выдает задание","персонаж, выдающий задания","брансток халдер"}},{q="Кто такой Максан Анвол?",a="Максан Анвол — наставник жрецов в горной деревне Каранос. Он ведет развивающихся жрецов и учит их сочетать преданность с физической выносливостью и силой духа.",al={"maxan anvol lore","who is maxan anvol","kharanos priest trainer","максан анвол предания","кто такой максан анвол","наставник жрецов каранос"}},{q="Что происходит после встречи с Максаном Анволом?",a="Максан Анвол предлагает вам доказать свое достоинство в задании «Облачение Света»: помочь раненым местным жителям, после чего вы получите первые официальные одеяния жреца.",al={"next quest","what follows in favor of the light","garments of the light","следующее задание","что после во имя света","облачение света"}},{q="Почему жрецы должны так рано покидать Холодную долину?",a="Холодная долина дает лишь основы боя и колдовства. Более крупные поселения вроде Караноса сталкиваются с насущными логистическими и оборонными угрозами и дают молодым жрецам реальный опыт служения своему народу.",al={"why leave coldridge","leaving anvilmar","why go to kharanos","зачем покидать холодную долину","уход из старой наковальни","зачем идти в каранос"}},{q="Получают ли жрецы-люди это же задание?",a="Жрецы-люди в Элвиннском лесу выполняют равнозначный обряд посвящения под тем же названием: Жрица Анетта в Североземье направляет их к жрице Жозетте в Златоземье.",al={"human in favor of the light","northshire version","люди во имя света","версия североземья"}},{q="Чем здесь отличается взгляд дворфов на Свет?",a="Дворфы придают огромное значение физической силе, воле и практической выносливости наряду с благочестием. Как отмечает Максан Анвол, служение Свету на холодных горных вершинах требует силы тела не меньше, чем веры.",al={"dwarf light beliefs","dwarves and the light","верования дворфов о свете","дворфы и свет"}}},fp="21,430,17.478.0,22.495.0,30.192.0,19.195.0,40.178.0,49.222.0,41.181.0,51.211.0"}
P.entries["quest:5627"] = {n="Звезды Элуны",s="«Звезды Элуны» — важная веха в единении юной жрицы ночных эльфов с Богиней Луны. Когда послушницы доказывают преданность своему народу, их приглашают в Храм Луны в Дарнассе, чтобы обучить священным умениям, присущим только Сестринству Элуны.",h="«Звезды Элуны» — важная веха в единении юной жрицы ночных эльфов с Богиней Луны.",kw={"darnassus","priestess alathea","returning home","sisterhood of elune","stars of elune","starshards","temple of the moon","дарнасс","жрица алатея","возвращение домой","сестринство элуны","звезды элуны","звездные осколки","храм луны"},ang={["class:Priest"]="Этот обряд знаменует разделение между жрицами кальдораев и жрецами других рас, открывая звездные заклинания, дарованные только Богиней Луны.",["faction:Alliance"]="Хотя жрецы-люди и дворфы проповедуют преданность Свету, преданность ночных эльфов Элуне привносит в ряды Альянса древнюю особую небесную магию.",["race:NightElf"]="Для кальдораев служение Элуне неотделимо от гражданской и культурной жизни; ответ на зов Сестринства означает взросление на службе Тельдрассилу."},sec={{t="Обряд преданности",b="Жрицы ночных эльфов черпают священную силу не из общих философских принципов Света, как люди и дворфы, а непосредственно от своей богини, Элуны. Когда послушница проявляет стойкую преданность на службе своему народу, Сестринство в Дарнассе признает это служение. Призванную в Храм Луны жрицу сочтут достойной более глубокого единения и откроют ей знания о священных заклинаниях, передававшихся на протяжении тысячелетий поклонения."},{t="Дары Богини Луны",b="Откликнувшись на зов жрицы Алатеи, посвященная получает прямое обучение священным таинствам, присущим ее народу, например Звездным осколкам. Эти заклинания направляют сияющие небесные гнев и милость Белой Госпожи. Это обучение означает, что послушница вышла за рамки базовой подготовки и готова отправиться за пределы защитного полога Тельдрассила во имя Элуны."}},faq={{q="Для чего нужно это задание?",a="«Звезды Элуны» — это официальное признание посвященной Сестринством Элуны. После выполнения жрица Алатея обучает юную жрицу расовым заклинаниям ночных эльфов, например Звездным осколкам, что отмечает ее рост как избранного сосуда Богини Луны.",al={"stars of elune quest","what do i get","why do this quest","задание звезды элуны","что я получу","зачем выполнять задание"}},{q="Кто выдает задание «Звезды Элуны»?",a="Задание сдается жрице Алатее, рукоположенной предводительнице Сестринства Элуны, пребывающей в величественном Храме Луны в Дарнассе.",al={"who gives stars of elune","quest giver stars of elune","where is alathea","кто дает звезды элуны","персонаж, выдающий задание звезды элуны","где алатея"}},{q="Почему это задание доступно только ночным эльфам?",a="Обряды, которым обучают в этом задании, принадлежат именно Сестринству Элуны, древнему жречеству, управляющему верой ночных эльфов. В отличие от других жречеств Альянса, изучающих всеобщий Свет, жрицы кальдораев получают свою особую магию непосредственно через единение с Элуной.",al={"can humans do this","is this night elf only","who can do stars of elune","могут ли люди","только для ночных эльфов","кто может выполнить звезды элуны"}},{q="К чему ведет это задание в сюжетной линии жрецов?",a="Это задание следует сразу за «Возвращением домой», которое направляет начинающую жрицу, помогавшую по всему Тельдрассилу, обратно в столицу, чтобы продолжить обучение в Храме Луны.",al={"what comes before stars of elune","stars of elune prereq","returning home quest","что перед звездами элуны","звезды элуны предыдущее задание","задание возвращение домой"}},{q="Какую магию Элуна дарует своим жрецам?",a="Жрицы, преданные Элуне, плетут лунный свет, звездный свет и тень. Особые ритуалы, такие как Звездные осколки, позволяют служительницам-кальдораям обрушивать на врагов раскаленный небесный огонь, сочетая божественный суд со звездным гневом.",al={"elune spells","night elf priest magic","starshards lore","заклинания элуны","магия жрицы ночных эльфов","звездные осколки предания"}},{q="Где в Дарнассе это происходит?",a="Это происходит в Храме Луны, сияющем мраморном святилище, которое возвышается над южным кварталом Дарнасса и служит религиозным сердцем народа кальдораев.",al={"stars of elune location","where is priestess alathea","temple of the moon location","где звезды элуны","где жрица алатея","где храм луны"}}},fp="14,264,18.458.0,25.404.0,34.271.0,26.150.0,44.284.0,55.200.0,52.222.0,40.184.0"}
P.entries["quest:5628"] = {n="Возвращение домой",s="«Возвращение домой» — это призыв, адресованный юным жрицам ночных эльфов, забредшим так далеко, как людские земли Элвиннского леса. Жрица Жозетта в Златоземье передает срочное сообщение из Дарнасса, веля послушнице вернуться в Храм Луны для дальнейшего духовного обучения у жрицы Алатеи.",h="«Возвращение домой» — это призыв, адресованный юным жрицам ночных эльфов, забредшим так далеко, как людские...",kw={"darnassus","elune","goldshire","priestess alathea","priestess josetta","returning home","stars of elune","temple of the moon","дарнасс","элуна","златоземье","жрица алатея","жрица жозетта","возвращение домой","звезды элуны","храм луны"},ang={["class:Priest"]="У каждого ордена жрецов глубокие традиции; для послушниц-кальдораев истинное продвижение в лунных обрядах может одобрить только старшие жрицы Храма Луны.",["faction:Alliance"]="Взаимное гостеприимство Церкви Священного Света в Элвиннском лесу и Сестринства Элуны в Дарнассе показывает растущие узы сотрудничества между расами Альянса.",["race:NightElf"]="Далекое странствие за море, в земли молодых рас, — путь честолюбивый, но зов Тельдрассила и благословения Элуны всегда возвращают кальдораев в их священные обители."},sec={{t="Весть в Златоземье",b="Ночные эльфы — необычное зрелище в Элвиннском лесу, и юная послушница среди человеческих поселений сразу привлекает внимание. Когда такая жрица приходит в Златоземье, жрица Жозетта встречает ее с теплом и новостями. Сестра Элуны пересекла континенты в поисках молодой служительницы с неотложным приказом из Храма Луны: пора вернуться в Калимдор и продолжить свое призвание."},{t="Зов храма",b="В сердце Дарнасса стоит Храм Луны — средоточие веры и власти ночных эльфов. Жрица Алатея и верховная жрица Тиранда Шелест Ветра руководят обучением Сестринства, внимательно присматривая за ученицами, даже когда любопытство уводит их за море. Вернувшихся посвященных встречают с материнской заботой и сразу направляют к более глубокому изучению небесных таинств Богини Луны."}},faq={{q="Почему жрицу ночных эльфов призывают из людских земель?",a="Юные жрицы ночных эльфов, отправившиеся в Восточные королевства, по-прежнему связаны со своим священным орденом в Тельдрассиле. Жрица Алатея следит за их успехами и призывает обратно в Храм Луны, когда они готовы изучать высшие обряды Элуны.",al={"why am i called back","why returning home","priest quest goldshire","почему меня зовут обратно","зачем возвращение домой","задание жреца златоземье"}},{q="Кто такая жрица Жозетта?",a="Жрица Жозетта — человеческая наставница жрецов в таверне «Гордость Льва» в Златоземье. Она служит Свету, но уважает приезжих послушниц-кальдораев и выступает посредницей, когда посланницы из Дарнасса приходят искать своих заблудших сородичей.",al={"who gives returning home","goldshire priest trainer","priestess josetta","кто дает возвращение домой","наставник жрецов златоземья","жрица жозетта"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — старшая сестра Элуны, обучающая послушниц в Храме Луны в Дарнассе. Тесно работая с верховной жрицей Тирандой Шелест Ветра, она следит за ростом и духовной преданностью начинающих жриц ночных эльфов.",al={"who is alathea","temple priest trainer","priestess alathea","кто такая алатея","наставница храма","жрица алатея"}},{q="Что происходит после возвращения в Дарнасс?",a="Когда вы доложите о возвращении жрице Алатее в Храме Луны, она благополучно встретит вас дома и поручит следующее духовное задание — «Звезды Элуны», которое глубже раскрывает священную силу, дарованную богиней.",al={"what comes next","next quest after returning home","followup quest","что дальше","следующее задание после возвращения домой","продолжение задания"}},{q="Чем это отличается от обычного пути обучения?",a="Это альтернативное вводное задание, созданное для жриц ночных эльфов, которые выбрали развитие в людских землях, например в Элвиннском лесу, вместо Тельдрассила. Оно возвращает их к расовым наставникам в Дарнассе, чтобы открыть расовые умения жрецов.",al={"do all priests do this","is this quest mandatory","elwynn priest quest","все ли жрецы делают это","обязательное ли задание","задание жреца элвиннский лес"}},{q="Как посланница нашла послушницу так далеко, в Элвиннском лесу?",a="Жрица Сестринства проделала путь из Дарнасса в Восточные королевства и оставила сообщение наставникам Альянса, таким как жрица Жозетта в Златоземье, чтобы они высматривали странствующую послушницу и направляли ее домой.",al={"how did they know i was here","who tracked me to goldshire","как узнали что я здесь","кто выследил меня в златоземье"}}},fp="14,308,19.426.0,22.452.0,58.256.0,25.249.0,25.244.0,42.232.0,51.296.0,67.225.0"}
P.entries["quest:5629"] = {n="Возвращение домой",s="«Возвращение домой» — обряд посвящения для юных жриц ночных эльфов, служащих по всему Тельдрассилу. Проявив себя в глуши, послушниц призывают в величественный Храм Луны в Дарнассе, чтобы предстать перед жрицей Алатеей и верховной жрицей Тирандой Шелест Ветра.",h="«Возвращение домой» — обряд посвящения для юных жриц ночных эльфов, служащих по всему Тельдрассилу.",kw={"darnassus","dolanaar","elune","laurna morninglight","priestess alathea","returning home","sisterhood of elune","teldrassil","temple of the moon","tyrande","дарнасс","доланаар","элуна","лорна утренний свет","жрица алатея","возвращение домой","сестринство элуны","тельдрассил","храм луны","тиранда"},ang={["class:Priest"]="Этот призыв отражает переход жрицы от обычной лесной послушницы к официальной служительнице Сестринства Элуны, подчиняющейся непосредственно Дарнассу.",["race:NightElf"]="Для кальдораев ответ на зов в Храм Луны означает единение с культурными корнями и под бдительным взором верховной жрицы Тиранды Шелест Ветра."},sec={{t="Призыв из Дарнасса",b="Жрицы, проводящие первые дни за уходом за ранеными и очищением скверны вокруг Доланаара, быстро привлекают внимание Сестринства Элуны. Наставница Лорна Утренний Свет перехватывает многообещающих посвященных и объясняет, что жрица Алатея прислала весть с просьбой о встрече. Помощь местным поселениям важна, но каждая преданная должна укреплять единение с Матерью-Луной и откликаться на высший зов веры."},{t="В Храме Луны",b="Путь ведет за ветви Тельдрассила, в величественное сердце Дарнасса — Храм Луны. Возвышаясь над городом в мягком сиянии милости Элуны, святилище служит и главным местом поклонения, и духовной столицей кальдораев. Приглашение в эти залы означает, что в вас больше не видят просто неопытную ученицу, а видят посвященную, признанную непосредственно руководством жречества."},{t="Благосклонность Тиранды и Алатеи",b="Когда путники предстают перед жрицей Алатеей, приветствие теплое и материнское. Алатея разделяет бдительную гордость руководства и отмечает, что и она, и верховная жрица Тиранда Шелест Ветра радуются, когда посвященные отправляются в неведомый внешний мир и возвращаются невредимыми. Это возвращение знаменует начало более глубоких священных испытаний под непосредственным наставничеством Алатеи."}},faq={{q="Кто выдает задание «Возвращение домой»?",a="Лорна Утренний Свет, наставница жрецов в Доланааре в Тельдрассиле, выдает задание, когда юная жрица ночных эльфов достигает достаточной подготовки и опыта.",al={"who gives returning home","returning home quest giver","laurna morninglight quest","кто дает возвращение домой","персонаж, выдающий задание возвращение домой","задание лорна утренний свет"}},{q="Где находится жрица Алатея?",a="Жрица Алатея живет в Храме Луны в Дарнассе, расположенном ближе к центру столицы ночных эльфов в Тельдрассиле.",al={"where is alathea","priestess alathea location","temple of the moon priestess","где алатея","где найти жрицу алатею","жрица храма луны"}},{q="Почему жрица Алатея хочет меня видеть?",a="Старейшины и руководство Сестринства Элуны отметили вашу самоотверженную службу в глуши Тельдрассила. Алатея считает, что вы готовы к углубленному обучению и более серьезным духовным заданиям.",al={"why summoned to darnassus","why go to temple of the moon","почему вызвали в дарнасс","зачем идти в храм луны"}},{q="Может ли взять это задание любой класс?",a="Нет. «Возвращение домой» предназначено именно для жриц ночных эльфов как часть раннего развития класса и священного посвящения в высшие обязанности Сестринства.",al={"is returning home for all classes","can druids do returning home","priest only quest","возвращение домой для всех классов","могут ли друиды","задание только для жрецов"}},{q="Какое задание следует за «Возвращением домой»?",a="Когда вы доложите жрице Алатее и завершите это поручение, она доверит вам следующее задание — «Звезды Элуны».",al={"what comes after returning home","returning home followup","next quest","что после возвращения домой","продолжение возвращения домой","следующее задание"}},{q="Какое значение имеет Храм Луны для ночных эльфов?",a="Храм Луны — главный центр поклонения богине Элуне и правящая обитель, где верховная жрица Тиранда Шелест Ветра направляет и Сестринство, и народ кальдораев.",al={"temple of the moon lore","darnassus moon temple","предания храма луны","лунный храм дарнасса"}}},fp="14,291,24.448.0,29.439.0,32.370.0,36.170.0,35.143.0,42.204.0,30.165.0,34.127.0,61.204.0"}
P.entries["quest:563"] = {n="Новое назначение",s="«Новое назначение» — кульминация стараний лейтенанта Фаррена Оринеля вырваться со службы в Южнобережье. Составив преувеличенный отчет о своих подвигах против прибрежных наг, Фаррен отправляет искателя приключений в Крепость Штормграда, чтобы тот передал документы его бывшему наставнику, майору Самуэльсону.",h="«Новое назначение» — кульминация стараний лейтенанта Фаррена Оринеля вырваться со службы в Южнобережье.",kw={"daggerspine","farren orinelle","major samuelson","reassignment","redpath","southshore","stormwind keep","пронзающий гребень","фаррен оринель","майор самуэльсон","новое назначение","редпат","южнобережье","крепость штормграда"},ang={["faction:Alliance"]="Это поручение показывает повседневную бюрократическую политику военных Альянса, где дальние пограничные гарнизоны вроде Южнобережья нередко сталкиваются с комфортными устремлениями офицеров, желающих вернуться в Штормград.",["race:Human"]="Доставка отчета обнажает контраст между измученными людьми-беженцами и защитниками, удерживающими рубеж в Лордероне, и политическими маневрами в высоких залах Крепости Штормграда."},sec={{t="Билет из Южнобережья",b="Лейтенант Фаррен Оринель не скрывает презрения к своему месту службы в Предгорьях Хилсбрада. Затерянный в Южнобережье, вдали от удобств столицы и под строгим надзором маршала Редпата, Фаррен проводит дни в замыслах о переводе на юг. Присвоив себе заслугу в уничтожении соседних наг из племени Пронзающего Гребня, он надеется предстать незаменимым закаленным в боях офицером, достойным повышения."},{t="Связи в крепости",b="Чтобы добиться нового назначения, не вызвав подозрений маршала Редпата, Фаррен полностью обходит местную цепочку командования. Он полагается на личные связи с майором Самуэльсоном, старшим офицером Крепости Штормграда, когда-то наставлявшим его. Передав отшлифованный отчет прямо в руки Самуэльсона, Фаррен гарантирует, что его мнимые достижения попадут на стол человека, имеющего власть переводить личный состав гарнизонов."},{t="Бюрократия за работой",b="Получив досье в Крепости Штормграда, майор Самуэльсон выказывает сдержанное одобрение инициативы своего бывшего ученика в борьбе с угрозой наг. Однако военная бюрократия движется медленно. Вместо немедленного перевода Самуэльсон лишь обещает рассмотреть отчет на плановой проверке личного состава в следующем месяце, и судьба Фаррена в Южнобережье остается неопределенной."}},faq={{q="Почему Фаррен Оринель хочет нового назначения?",a="Лейтенант Фаррен Оринель ненавидит службу в Южнобережье: он считает этот отдаленный северный форпост скучным, опасным и недостойным себя. Он мечтает вернуться к относительной роскоши и безопасности Штормграда и хочет использовать свои отчеты о нагах для обоснования перевода.",al={"why leave southshore","farren motive","why does farren want to leave","почему уехать из южнобережья","мотив фаррена","почему фаррен хочет уехать"}},{q="Кто такой майор Самуэльсон?",a="Майор Самуэльсон — высокопоставленный офицер Крепости Штормграда, ведающий назначениями городской стражи. До нынешнего поста он был наставником лейтенанта Фаррена Оринеля в начале его карьеры в столице.",al={"who is samuelson","samuelson lore","кто такой самуэльсон","самуэльсон предания"}},{q="Почему Фаррен не может доставить отчет сам?",a="Фаррен несет действующую службу в Южнобережье и не может покинуть пост без разрешения. Кроме того, он пытается обойти непосредственного начальника, маршала Редпата, который, вероятно, воспрепятствовал бы корыстной просьбе о переводе.",al={"why do i have to deliver it","why not deliver himself","почему я должен доставить","почему не доставит сам"}},{q="Фаррен действительно сам победил нага?",a="Нет. Фаррен отправил искателей приключений убивать нага Пронзающего Гребня на Восточном побережье, а затем использовал их успех в докладе в поддержку своей просьбы о новом назначении.",al={"did farren kill naga","farren report truth","убил ли фаррен наг","правда об отчете фаррена"}},{q="Фаррена действительно переводят обратно в Штормград?",a="Не сразу. Майор Самуэльсон лишь обещает рассмотреть отчет на проверке личного состава в следующем месяце. Фаррен остается на службе в Южнобережье в обозримом будущем, пока колеса военной бюрократии королевства медленно крутятся.",al={"does farren get reassigned","does transfer work","переведут ли фаррена","работает ли перевод"}},{q="Где находится майор Самуэльсон?",a="Майор Самуэльсон находится в Крепости Штормграда — оплоте в сердце Штормграда, где располагаются верховное командование и регентский совет.",al={"samuelson location","where is major samuelson","где самуэльсон","где найти майора самуэльсона"}}},fp="12,312,26.432.0,16.435.0,19.386.1,45.274.0,23.217.0,44.226.0,44.157.0,55.245.1,33.140.0"}
P.entries["quest:5630"] = {n="Возвращение домой",s="«Возвращение домой» — вызов для странствующих жрецов-ночных эльфов, оказавшихся далеко от Калимдора в заснеженных скалах Дун Морога. По указанию дворфа, наставника жрецов Максана Анвола, новичку велено вернуться в Храм Луны в Дарнасе и доложить жрице Алатее.",h="«Возвращение домой» — вызов для странствующих жрецов-ночных эльфов, оказавшихся далеко от Калимдора в...",ang={["class:Priest"]="Этот обряд посвящения вновь связывает странствующих служителей с руководством Сестринства Элуны, помогая сохранить преданность Богине Луны даже вдали от дома.",["race:NightElf"]="Для кальдорая, терпящего ледяные ветра Дун Морога, этот вызов означает долгожданное возвращение в знакомые святилища и древние леса Тельдрассила."},sec={{t="Зов из-за моря",b="Ночные эльфы, решившие начать приключения рядом с союзниками-дворфами, сталкиваются с лютым холодом Дун Морога, совсем непохожим на безмятежные леса Тельдрассила. В Караносе дворф-учитель жрецов Максан Анвол отмечает стойкость эльфа, а затем передает срочное сообщение: жрица Элуны заходила, разыскивая их, с приказом из Дарнасса, требующим немедленного возвращения."},{t="Храм Луны",b="Путь ведет обратно к священным ветвям Тельдрассила, прямо к Храму Луны. Там жрица Алатея приветствует странника, принимая его вновь в лоно Сестринства Элуны. Радуясь, что еще один преданный служитель вернулся невредимым из чужих земель, Алатея быстро готовит жреца к следующим обрядам служения, начиная со «Звезд Элуны»."}},faq={{q="Кто посылает меня с этим заданием?",a="Максан Анвол, дворф-учитель жрецов из Караноса в Дун Мороге, передает вам сообщение. Он замечает, что недавно заходила другая жрица-ночная эльфийка, разыскивавшая вас.",al={"quest giver","who starts returning home","maxan anvol","персонаж, выдающий задания","кто начинает возвращение домой","максан анвол"}},{q="Куда нужно отправиться, чтобы выполнить его?",a="Вы должны вернуться в Дарнасс на острове Тельдрассил на севере Калимдора. Жрица Алатея ждет вас в Храме Луны.",al={"turn in location","where is priestess alathea","where do i go","место сдачи","где жрица алатея","куда идти"}},{q="Почему Храм Луны призывает меня обратно?",a="Жрица Алатея и верховная жрица Тиранда Шелест Ветра следят за развитием молодых послушников. Алатея хочет убедиться в вашей безопасности, услышать о ваших странствиях под покровом Элуны и начать следующий этап вашего духовного обучения через «Звезды Элуны».",al={"why returning home","priest summons reason","зачем возвращаться домой","причина вызова жреца"}},{q="Что происходит после разговора с жрицей Алатеей?",a="Когда вы доложите о возвращении, жрица Алатея предложит задание «Звезды Элуны», продолжая ваши начальные обряды как жреца кальдораев.",al={"next quest","what comes next","следующее задание","что дальше"}},{q="Почему ночной эльф оказался в Дун Мороге на 10 уровне?",a="Ночные эльфы-искатели приключений часто отправляются в Восточные королевства на корабле из Темных берегов в Гавань Менетилов, чтобы исследовать земли Альянса или странствовать бок о бок с дворфами и гномами.",al={"why dun morogh","night elf in ironforge","почему дун морог","ночной эльф в айронфорже"}},{q="Доступно ли это задание другим расам?",a="Нет, это задание предназначено именно для жрецов-ночных эльфов, обучающихся за границей в землях дворфов, и направляет их обратно в культурный и духовный дом в Дарнассе.",al={"can dwarves do returning home","who can take this quest","могут ли дворфы взять возвращение домой","кто может взять это задание"}}},fp="14,279,24.419.0,22.379.0,27.196.0,37.143.0,46.259.0,51.143.0,51.187.0,39.174.0"}
P.entries["quest:5631"] = {n="Возвращение домой",s="«Возвращение домой» — задание жрецов Альянса: многообещающих послушников-ночных эльфов, странствующих за границей, призывают обратно в Тельдрассил. Под руководством Брата Джошуа в землях людей юного жреца вызывает в Храм Луны в Дарнасе жрица Алатея для углубленного обучения тайнам Элуны.",h="«Возвращение домой» — задание жрецов Альянса: многообещающих послушников-ночных эльфов, странствующих за...",kw={"brother joshua","darnassus","priest","priestess alathea","returning home","stars of elune","teldrassil","temple of the moon","tyrande","брат джошуа","дарнасс","жрец","жрица алатея","возвращение домой","звезды элуны","тельдрассил","храм луны","тиранда"},ang={["class:Priest"]="Это задание связывает братство Церкви Священного Света и Сестринства Элуны, отмечая миг, когда юный послушник возвращается к своему народу, чтобы освоить особые обряды кальдораев.",["faction:Alliance"]="Слаженное сотрудничество Брата Джошуа в Восточных королевствах и жриц в Дарнассе отражает духовную дипломатию, сохраняющую единство Альянса.",["race:NightElf"]="Для жрецов-ночных эльфов, бывших среди людей или дворфов за морем, это паломничество становится священным возвращением домой в святилища Тельдрассила."},sec={{t="Зов из-за морей",b="Хотя жрецы-ночные эльфы порой бывают в человеческих землях вроде Штормграда, чтобы разделить духовное братство с Церковью Священного Света, их глубочайшие узы связаны с Сестринством Элуны. Когда Брат Джошуа сообщает послушнику, что его искал посланник ночных эльфов, это означает конец ранних странствий. Родной храм требует его присутствия для углубленного обучения под руководством ближнего круга верховной жрицы Тиранды Шелест Ветра."},{t="Храм Луны",b="Возвращение через моря в Дарнасс приводит странника прямо в святилище Храма Луны. Жрица Алатея тепло встречает вернувшегося послушника, радуясь его благополучному пути через неспокойный мир. Благополучное возвращение молодых учеников — радость и для Алатеи, и для Тиранды, но также и пролог к более трудным духовным испытаниям."}},faq={{q="Почему Брат Джошуа дает указания жрецу-ночному эльфу?",a="Брат Джошуа служит Церкви Священного Света в землях людей, где молодые жрецы Альянса часто учатся вместе. Сестра Элуны посетила его залы, чтобы передать весть, призывающую вас в Дарнасс, и Джошуа передает этот вызов.",al={"why brother joshua","brother joshua night elf","who sends me home","почему брат джошуа","брат джошуа ночной эльф","кто отправляет меня домой"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — старшая участница Сестринства Элуны в Храме Луны в Дарнассе. Тесно работая с верховной жрицей Тирандой Шелест Ветра, она руководит обучением и продвижением многообещающих жрецов-ночных эльфов.",al={"priestess alathea","alathea darnassus","who is alathea","жрица алатея","алатея дарнасс","кто такая алатея"}},{q="Что происходит после прибытия в Храм Луны?",a="Когда вы доложите жрице Алатее о благополучном прибытии, она приветствует вас дома и посвящает в следующий обряд, начиная задание «Звезды Элуны», чтобы углубить вашу связь с Богиней Луны.",al={"quest after returning home","what is next","stars of elune quest","задание после возвращения домой","что дальше","задание звезды элуны"}},{q="Может ли любая раса Альянса выполнить это задание?",a="Этот вызов предназначен для жрецов-ночных эльфов, ушедших далеко от Калимдора в начале обучения. Он гарантирует их возвращение в родной дом для изучения расовых традиций жречества под руководством Сестринства Элуны.",al={"is this night elf only","can humans do returning home","who can pick up returning home","только ли для ночных эльфов","могут ли люди взять возвращение домой","кто может взять возвращение домой"}},{q="Где находится Храм Луны?",a="Храм Луны стоит в южном районе Дарнасса на ветвях Тельдрассила. Он служит духовным сердцем культуры ночных эльфов и престолом власти верховной жрицы Тиранды Шелест Ветра.",al={"temple of the moon location","where is the temple","where is alathea","где храм луны","где находится храм","где алатея"}},{q="Почему Алатея упоминает Тиранду Шелест Ветра?",a="Тиранда Шелест Ветра — Верховная жрица Элуны и духовная предводительница ночных эльфов. Старшие жрицы вроде Алатеи действуют от ее имени, следя за тем, чтобы все послушники, представляющие их веру за границей, находились под наблюдением и обучались по стандартам Тиранды.",al={"why tyrande mentioned","tyrande whisperwind priestess","alathea and tyrande","почему упомянута тиранда","тиранда шелест ветра жрица","алатея и тиранда"}}},fp="14,314,21.478.0,22.380.0,64.272.0,25.248.0,51.209.0,36.234.0,40.219.0,45.266.0"}
P.entries["quest:5632"] = {n="Возвращение домой",s="«Возвращение домой» — призыв, который получают перспективные жрецы-ночные эльфы, служащие за пределами столицы. Жрица Алатея вызывает послушников в Храм Луны в Дарнассе, чтобы отметить их рост в Сестринстве Элуны и дать им дальнейшее наставление.",h="«Возвращение домой» — призыв, который получают перспективные жрецы-ночные эльфы, служащие за пределами...",kw={"darnassus","nara meideros","priest quest","priestess alathea","returning home","sisterhood of elune","stars of elune","temple of the moon","tyrande whisperwind","дарнасс","нара мейдерос","задание жрецов","жрица алатея","возвращение домой","сестринство элуны","звезды элуны","храм луны","тиранда шелест ветра"},ang={["class:Priest"]="Этот призыв — важная веха на вашем пути жреца: он награждает вашу раннюю службу прямым общением с Сестринством Элуны и дальнейшим обучением у него.",["faction:Alliance"]="Сестринство Элуны — духовное сердце ночных эльфов в Альянсе, оно готовит умелых целителей и божественных воителей к встрече с угрозами по всему Калимдору.",["race:NightElf"]="Для кальдораев благополучное возвращение в Храм Луны — глубокое возвращение домой, укрепляющее непреходящее культурное и духовное лидерство жрецов Элуны."},sec={{t="Посланница Сестринства",b="Пока молодые жрецы странствуют вдали, служа своему народу, их духовный рост не остается незамеченным. Когда послушник навещает Нару Мейдерос в Парке Штормграда, к нему прибывает посланница Сестринства Элуны со срочной вестью: руководство ордена требует его присутствия в Дарнассе. Это одновременно проверка и обряд признания, знаменующий переход от неопытного новичка к действующему служителю Матери Луны."},{t="Аудиенция в Храме Луны",b="Призыв направляет путника прямо к жрице Алатее в главное святилище Дарнасса — Храм Луны. Сестринство, во главе которого стоит верховная жрица Тиранда Шелест Ветра, пристально следит за своими разбросанными по миру членами. Благополучное возвращение на земли храма чтит общину и богиню и показывает, что милость Элуны направляла и хранила жреца в первых испытаниях в диких землях."}},faq={{q="Почему жрица призывает меня обратно в Дарнасс?",a="Жрица Алатея и Сестринство Элуны следят за духовным развитием своих учеников. Вас вызывают в Храм Луны из-за ваших быстрых успехов на пути ордена, что ведет прямо к более глубокому обучению и священному благословению.",al={"why returning home","reason for summons","why visit alathea","почему возвращение домой","причина вызова","зачем идти к алатее"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — высокопоставленная наставница Сестринства Элуны, находящаяся в Храме Луны. Работая непосредственно под началом верховной жрицы Тиранды Шелест Ветра, она обучает перспективных жрецов-ночных эльфов и посвящает их в священные обряды.",al={"who is alathea","alathea lore","priestess alathea identity","кто такая алатея","алатея предания","кто такая жрица алатея"}},{q="Куда ведет этот призыв дальше?",a="Доклад жрице Алатее сразу ведет к испытанию «Звезды Элуны» — древнему заданию жрецов, в котором вы учитесь направлять небесную силу богини на защиту своего народа.",al={"what quest is after returning home","next step in returning home","stars of elune lead in","какое задание после возвращения домой","следующий шаг возвращения домой","звезды элуны продолжение"}},{q="Кто посылает весть через Нару Мейдерос?",a="Посланница, отправленная непосредственно Сестринством Элуны, передала весть Наре Мейдерос. Орден поддерживает связь с жрицами, находящимися за границей, например с Нарой в Парке Штормграда, чтобы следить за своими послушниками.",al={"who sent nara","messenger of the sisterhood","кто послал нару","посланница сестринства"}},{q="Получают ли этот призыв другие расы или классы?",a="Нет. Это задание связано именно со жречеством ночных эльфов и Сестринством Элуны. Послушники других рас и вер обращаются за продвижением к собственным духовным наставникам и священным орденам.",al={"can non night elves do this","is this priest only","могут ли не ночные эльфы выполнить","только для жрецов"}},{q="Почему Алатея упоминает Тиранду Шелест Ветра?",a="Тиранда Шелест Ветра — верховная жрица Элуны и верховная предводительница как Сестринства, так и правительства ночных эльфов. Алатея работает непосредственно под ее началом в Храме Луны и следит за тем, чтобы воля и духовное наставление Тиранды доходили до каждого послушника.",al={"tyrande connection","tyrande alathea relation","связь с тирандой","тиранда и алатея"}}},fp="14,253,31.449.0,34.414.0,52.253.0,25.246.0,34.201.0,44.231.0,47.206.0,45.261.0"}
P.entries["quest:5633"] = {n="Возвращение домой",s="«Возвращение домой» — призыв для жрецов-ночных эльфов, находящихся в Стальгорне, вернуться в Храм Луны в Дарнассе. Посланница Сестринства разыскивала странствующих послушников и направляла их обратно к жрице Алатее для срочного обучения и духовных обязанностей.",h="«Возвращение домой» — призыв для жрецов-ночных эльфов, находящихся в Стальгорне, вернуться в Храм Луны в...",kw={"braenna flintcrag","darnassus","priest quest","priestess alathea","returning home","stars of elune","temple of the moon","браэнна кремнескал","дарнасс","задание жрецов","жрица алатея","возвращение домой","звезды элуны","храм луны"},ang={["class:Priest"]="Это задание возвращает вас из ранних странствий среди союзников Альянса к главному духовному дому жрецов-ночных эльфов — Храму Луны.",["faction:Alliance"]="Сотрудничество дворфов-священников Стальгорна и Сестринства Элуны в Дарнассе показывает, как фракции Альянса согласованно поддерживают странствующих искателей приключений.",["race:NightElf"]="Покинуть Калимдор ради Восточных королевств — редкое путешествие для молодого кальдорая, но наставление Элуны и жречества Тиранды достигает и Великого моря."},sec={{t="Вызов из Горного города",b="Даже странствуя далеко от Тельдрассила в шумных подземных залах Стальгорна, жрецы-ночные эльфы остаются связаны с Сестринством Элуны. Браэнна Кремнескал, наставница жрецов из дворфов в Мистическом квартале, передает сообщение, оставленное посетившей город жрицей ночных эльфов. Посланница искала молодых учеников вдали от дома и принесла весть, что наставники требуют их немедленного возвращения в столицу."},{t="Храм Луны",b="По прибытии в Храм Луны в Дарнассе вернувшиеся послушники докладывают прямо жрице Алатее. Встречая ученика под бдительным взором верховной жрицы Тиранды Шелест Ветра, Алатея выражает облегчение по поводу благополучного путешествия через моря. Срочный призыв становится порогом к более глубокой преданности и открывает путь к священным обязанностям, таким как «Звезды Элуны»."}},faq={{q="Кто выдает это задание?",a="Задание выдает Браэнна Кремнескал, наставница жрецов из дворфов, которую можно найти в Мистическом квартале Стальгорна.",al={"who gives returning home","quest giver returning home","braenna flintcrag location","кто дает возвращение домой","персонаж, выдающий задание возвращение домой","где браэнна кремнескал"}},{q="Кому нужно доложить в Дарнассе?",a="Вы должны поговорить с жрицей Алатеей, которая находится в Храме Луны в Дарнассе.",al={"where to turn in returning home","priestess alathea location","turn in returning home","где сдать возвращение домой","где жрица алатея","сдать задание возвращение домой"}},{q="Почему Сестринство призывает жрецов обратно?",a="Сестринство Элуны пристально следит за своими послушниками. Когда послушник доказывает свои способности вдали от дома, руководство в Дарнассе вызывает его для углубленного обучения и священных обрядов, таких как «Звезды Элуны».",al={"why returning home","why go back to darnassus","почему возвращение домой","зачем возвращаться в дарнасс"}},{q="Доступно ли это задание другим классам?",a="Нет, это задание предназначено именно для жрецов-ночных эльфов, которые в начале своих приключений добрались до Дун Мороге и Стальгорна.",al={"can warriors do returning home","priest only quest","могут ли воины выполнить возвращение домой","задание только для жрецов"}},{q="Что происходит после сдачи этого задания?",a="Жрица Алатея приветствует вас в Дарнассе и предлагает следующее задание «Звезды Элуны», которое глубже раскрывает учение богини.",al={"returning home next quest","followup to returning home","возвращение домой следующее задание","продолжение возвращения домой"}},{q="Откуда Браэнна знает, что нужно искать вас?",a="Жрица, посланная прямо из Храма Луны, прошла через Стальгорн в поисках послушников и оставила местным наставникам, таким как Браэнна, четкие указания отправлять всех странствующих ночных эльфов домой.",al={"why does braenna know me","ironforge priestess message","откуда браэнна знает меня","сообщение жрицы в стальгорне"}}},fp="14,273,31.415.0,22.389.0,22.104.0,32.94.0,43.227.0,41.135.0,41.145.0,38.207.0"}
P.entries["quest:5634"] = {n="Молитва отчаяния",s="«Молитва отчаяния» — обряд посвящения для начинающих жрецов-людей в Штормграде. Его дает верховная жрица Лорена в Соборе Света, и он отмечает преданность послушника делу сохранения жизни в неспокойных землях Альянса. Пройдя это духовное обучение, жрецы получают экстренное благословение, чтобы исцелять собственные раны, когда все остальное бессильно.",h="«Молитва отчаяния» — обряд посвящения для начинающих жрецов-людей в Штормграде.",kw={"cathedral of light","cathedral square","desperate prayer","high priestess laurena","holy light","laurena","priest","stormwind","собор света","соборная площадь","молитва отчаяния","верховная жрица лорена","свет","лорена","жрец","штормград"},ang={["class:Priest"]="Этот обряд знаменует ваш переход от ученика-послушника к действующему служителю Света, способному выжить в смертельных испытаниях в полевых условиях.",["faction:Alliance"]="Сохранение целителей на передовой с помощью таких благословений, как «Молитва отчаяния», жизненно важно для поддержки солдат Альянса на опасных рубежах.",["race:Human"]="Жрецы-люди получают это учение непосредственно от иерархии Собора Света, что подтверждает роль Штормграда как главного центра веры людей."},sec={{t="Мольба во тьме",b="Жрецов, служащих в Соборе Света, учат направлять свою веру вовне, чтобы защищать соратников, врачевать смертельные раны и карать зло. Но даже самые преданные служители Света оказываются в одиночестве, в ловушке или на грани человеческой выносливости. «Молитва отчаяния» — это глубоко личное экстренное обращение, отчаянный крик о божественном вмешательстве, когда жизнь послушника висит на волоске."},{t="Благословение собора",b="Верховная жрица Лорена надзирает за многими служителями церкви на Соборной площади Штормграда и решает, когда послушник достоин более глубоких тайн учения. Проявив истинную преданность добродетелям Света по всему королевству, послушники-люди получают этот священный урок не просто как средство выживания, но и как торжественное подтверждение того, что их дальнейшая служба по-прежнему необходима королевству."}},faq={{q="Для чего нужна «Молитва отчаяния»?",a="«Молитва отчаяния» — экстренное воззвание к Свету, доступное жрецам-людям и жрецам-дворфам. Оно позволяет раненому жрецу мгновенно призвать божественную энергию, чтобы залечить собственные тяжелые раны, не тратя время на длинные заклинания.",al={"what does desperate prayer do","why desperate prayer","desperate prayer purpose","что делает молитва отчаяния","зачем нужна молитва отчаяния","назначение молитвы отчаяния"}},{q="Кто дает этот урок в Штормграде?",a="Верховная жрица Лорена, служащая в величественном Соборе Света на Соборной площади Штормграда, дает этот урок, когда послушник проявил достаточную преданность и опыт в большом мире.",al={"who teaches desperate prayer","where to get desperate prayer","high priestess laurena quest","кто учит молитве отчаяния","где получить молитву отчаяния","задание верховной жрицы лорены"}},{q="Почему жрецы получают именно это обучение?",a="Жрецы Света часто бросаются в опасность, чтобы помочь другим. «Молитва отчаяния» служит священной защитой: когда целители оказываются брошены или тяжело ранены, их вера может сохранить им жизнь.",al={"why do priests get desperate prayer","lore behind desperate prayer","почему жрецы получают молитву отчаяния","предание молитвы отчаяния"}},{q="Может ли любой искатель приключений выучить «Молитву отчаяния» здесь?",a="Нет. Это задание и урок строго предназначены для жрецов, чтущих учение Света и обучающихся под руководством Церкви Света.",al={"can anyone learn desperate prayer","is this quest priest only","может ли любой выучить молитву отчаяния","задание только для жрецов"}},{q="Где проходит этот обряд?",a="Он проходит в Соборе Света — возвышающемся духовном сердце Альянса, расположенном в северном районе Штормграда.",al={"desperate prayer location","where is laurena","где молитва отчаяния","где лорена"}},{q="Свойственна ли «Молитва отчаяния» только жрецам-людям?",a="В землях Альянса «Молитва отчаяния» доступна и людям, и дворфам среди духовенства, поскольку оба народа чтут Свет в рамках тесно связанных церковных традиций, сосредоточенных вокруг Штормграда и Стальгорна.",al={"do other races get desperate prayer","dwarf desperate prayer","получают ли другие расы молитву отчаяния","молитва отчаяния дворфы"}}},fp="16,372,18.426.0,24.414.0,40.245.0,36.209.0,46.233.0,47.159.0,32.139.0,44.210.0"}
P.entries["quest:5635"] = {n="Молитва отчаяния",s="«Молитва отчаяния» — вводное задание для начинающих жрецов Альянса, служащих Церкви Священного Света. Проявив преданность и дисциплину в Элвиннском лесу, многообещающие служители вызываются в Собор Света Штормграда, чтобы продолжить священное обучение под руководством верховной жрицы Лорены.",h="«Молитва отчаяния» — вводное задание для начинающих жрецов Альянса, служащих Церкви Священного Света.",kw={"cathedral of light","desperate prayer","goldshire","high priestess laurena","holy light","priest","priestess josetta","stormwind","собор света","молитва отчаяния","златоземье","верховная жрица лорена","свет","жрец","жрица жозетта","штормград"},ang={["class:Priest"]="Это задание знаменует ваш официальный переход от послушника прихода в Златоземье к признанному ученику, которого доверяют старшему руководству Собора Света.",["faction:Alliance"]="Церковь Священного Света остается одной из сильнейших культурных и нравственных опор, объединяющих Альянс в эпоху нарастающих угроз.",["race:Human"]="Для людей, верных Свету, вход в величественный Собор Света — глубокое паломничество, подтверждающее ваш долг перед духовным сердцем королевства."},sec={{t="Вызов в столицу",b="Жрецы-новички, служащие в отдаленных поселениях Элвиннского леса, начинают свой путь под руководством местных наставников, таких как жрица Жозетта в Златоземье. Когда ученик проявляет себя в духе и делах, весть быстро доходит до старших жрецов в столице. Признанием становится прямой вызов в величественный Собор Света — духовное сердце Королевства Штормград, — означающий, что пора принять более глубокие и официальные обязанности в служении вере."},{t="Наставления Верховной жрицы",b="По прибытии в Собор служители представляются верховной жрице Лорене. Как одна из выдающихся руководительниц Церкви в городе, Лорена отвечает за духовные основы и практическую подготовку недавно возвышенных жрецов. Ее наставления готовят верующих к суровым испытаниям, стоящим перед Альянсом, и передают важнейшие знания о чудесах Света, включая жизненно важную мольбу о спасении, известную среди людей как «Молитва отчаяния»."}},faq={{q="Для чего нужно задание «Молитва отчаяния»?",a="Задание направляет многообещающих жрецов 10 уровня из Златоземья в Собор Света Штормграда, где начинающие служители встречаются с верховной жрицей Лореной для продолжения священного обучения.",al={"desperate prayer quest","what is desperate prayer quest","why do desperate prayer","задание молитва отчаяния","что за задание молитва отчаяния","зачем нужна молитва отчаяния"}},{q="Кто выдает задание «Молитва отчаяния»?",a="Жрица Жозетта, наставница жрецов в таверне «Гордость Льва» в Златоземье, передает вызов, когда вы докажете свою преданность.",al={"who starts desperate prayer","desperate prayer quest giver","кто начинает молитву отчаяния","персонаж, выдающий задание молитва отчаяния"}},{q="Кто такая верховная жрица Лорена?",a="Верховная жрица Лорена — одна из старших руководительниц Церкви Священного Света. Она живет в Соборе Света Штормграда, где обучает опытных служителей.",al={"who is laurena","high priestess laurena lore","кто такая лорена","верховная жрица лорена предания"}},{q="Где находится Собор Света?",a="Собор Света возвышается над Соборной площадью в северном квартале Штормграда и служит духовным центром для жрецов и паладинов королевства.",al={"where is cathedral of light","cathedral location stormwind","где собор света","расположение собора штормград"}},{q="Почему задание называется «Молитва отчаяния»?",a="Оно открывает жрецу углубленное обучение в Штормграде, где жрецы-люди традиционно изучают воззвание «Молитва отчаяния» — мольбу к Свету о немедленном спасении собственной жизни.",al={"why called desperate prayer","desperate prayer name meaning","почему называется молитва отчаяния","значение названия молитва отчаяния"}},{q="Получают ли это задание другие расы или классы?",a="Эта цепочка заданий предназначена для жрецов, покидающих Элвиннский лес, чтобы начать высшее обучение в столице — Штормграде.",al={"can dwarves do desperate prayer quest","is desperate prayer priest only","могут ли дворфы взять молитву отчаяния","только ли для жрецов молитва отчаяния"}}},fp="16,314,24.479.0,32.465.0,50.188.0,37.140.0,30.166.0,40.168.0,40.212.0,41.135.0"}
P.entries["quest:5636"] = {n="Молитва отчаяния",s="«Молитва отчаяния» — задание жрецов Альянса, возвращающее странствующих служителей Света в Штормград. Его начинает жрица-ночная эльфийка Лорна Утренний Свет в Доланааре; оно призывает жрецов-людей, посетивших Тельдрассил, вернуться домой для важного духовного обучения у верховной жрицы Лорены.",h="«Молитва отчаяния» — задание жрецов Альянса, возвращающее странствующих служителей Света в Штормград.",kw={"cathedral of light","desperate prayer","dolanaar","high priestess laurena","laurna morninglight","priest quest","stormwind","teldrassil","собор света","молитва отчаяния","доланаар","верховная жрица лорена","лорна утренний свет","задание жреца","штормград","тельдрассил"},ang={["class:Priest"]="Это задание — важный обряд посвящения на 10 уровне: оно возвращает жрецов в лоно Собора Света, чтобы изучить особые расовые дары веры.",["faction:Alliance"]="Вызов показывает растущее сотрудничество внутри Альянса: жрицы ночных эльфов охотно согласуют действия с руководством церкви в Штормграде.",["race:NightElf"]="Хотя ночные эльфы почитают Богиню Луны Элуну, жрица Лорна Утренний Свет вежливо уважает чужеземных последователей Света, идущих под сенью Тельдрассила."},sec={{t="Весть из дома",b="Во время пребывания в древних ветвях Тельдрассила жрецы, верные Свету, могут привлечь внимание местного Сестринства Элуны. В Доланааре жрица Лорна Утренний Свет неожиданно становится посредницей: она сообщает, что другой жрец преодолел континенты, разыскивая вас. Понимая срочность вызова, Лорна советует вам без промедления вернуться на родину, желая добра вашей вере и даруя благословение Элуны."},{t="Вызов в Штормград",b="Путь лежит через Великое море к величественному Собору Света в сердце Штормграда. Там верховная жрица Лорена руководит духовным ростом верных Альянса. Служители, рано проявившие себя, вызываются к ней, чтобы постичь более глубокие таинства веры, в частности экстренное воззвание «Молитва отчаяния» — спасительный дар, доверяемый лишь преданным ученикам в их темный час."}},faq={{q="Кто выдает задание «Молитва отчаяния» в Тельдрассиле?",a="Задание выдает Лорна Утренний Свет, наставница жрецов из ночных эльфов в Доланааре, что в Тельдрассиле. Она передает срочное сообщение, оставленное жрецом из ваших родных земель.",al={"who gives desperate prayer","desperate prayer quest giver teldrassil","laurna morninglight quest","кто дает молитву отчаяния","персонаж, выдающий задание молитва отчаяния тельдрассил","задание лорны утреннего света"}},{q="Куда ведет это задание?",a="Задание направляет вас в Собор Света в Штормграде, где нужно лично поговорить с верховной жрицей Лореной.",al={"where do i go","turn in desperate prayer","where is laurena","куда идти","сдать молитву отчаяния","где лорена"}},{q="Почему ночная эльфийка отправляет жреца в Штормград?",a="Жрецы ночных эльфов почитают Элуну, но чужеземные жрецы, например люди или дворфы, прибывшие в Тельдрассил, по-прежнему следуют традициям Света. Лорна Утренний Свет уважает их веру и передает сообщения от религиозной иерархии их родины.",al={"why does a night elf send me to stormwind","night elf holy light","почему ночная эльфийка отправляет меня в штормград","ночные эльфы и свет"}},{q="Какова награда за выполнение этого задания?",a="Доклад верховной жрице Лорене открывает путь к углубленному духовному наставничеству и позволяет изучить «Молитву отчаяния» — мгновенную исцеляющую молитву, доступную только жрецам-людям и дворфам.",al={"desperate prayer reward","what spell do i get","награда молитва отчаяния","какое заклинание я получу"}},{q="Могут ли жрецы-ночные эльфы взять это задание?",a="Нет. Жрецы ночных эльфов поклоняются Элуне и изучают «Звездные осколки», а не «Молитву отчаяния». Этот вызов предназначен именно для жрецов-людей, исследующих Калимдор на низких уровнях.",al={"can night elves do desperate prayer","night elf priest desperate prayer","могут ли ночные эльфы взять молитву отчаяния","жрец ночной эльф молитва отчаяния"}},{q="Как вернуться в Штормград из Тельдрассила?",a="Нужно пройти через Дарнасс в Деревню Рут'теран, сесть на корабль до Аубердина на Темных берегах, затем на другом корабле пересечь море до Гавани Менетилов в Болотине и отправиться на юг через Лок Модан и Дун Морог, а затем через Подземный поезд в Штормград.",al={"how to get to stormwind from dolanaar","teldrassil to stormwind route","как добраться до штормграда из доланаара","путь из тельдрассила в штормград"}}},fp="16,300,19.476.0,24.457.0,52.185.0,27.129.0,51.279.0,45.188.0,47.204.0,52.254.0"}
P.entries["quest:5637"] = {n="Молитва отчаяния",s="«Молитва отчаяния» — задание-обряд посвящения, призывающее многообещающих жрецов-дворфов из Дун Морога в величественный Собор Света в Штормграде. Верховная жрица Лорена вызывает растущих служителей, чтобы они углубили свою преданность и освоили особые священные приемы. Оно знаменует переход жреца от местного обучения к более широкому служению Альянсу.",h="«Молитва отчаяния» — задание-обряд посвящения, призывающее многообещающих жрецов-дворфов из Дун Морога в...",kw={"cathedral of light","desperate prayer","dun morogh","kharanos","laurena","maxan anvol","priest","stormwind","собор света","молитва отчаяния","дун морог","каранос","лорена","максан анвол","жрец","штормград"},ang={["class:Priest"]="Это задание — веха вашего духовного пути, соединяющая обычное приходское служение с высшими священными приемами, которым учит непосредственно руководство Церкви.",["faction:Alliance"]="Духовное сотрудничество Стальгорна и Штормграда обеспечивает единство последователей Света вне расовых границ.",["race:Dwarf"]="Путешествие в Собор Штормграда укрепляет общий духовный завет между горным королевством Стальгорн и человеческим государством Штормград."},sec={{t="Вызов в Собор",b="Жрецы, начавшие службу среди снегов Дун Морога, со временем перерастают наставления местных учителей вроде Максана Анвола в Караносе. Когда послушник подает настоящие надежды, приходит официальный вызов от самой верховной жрицы Лорены. Такое прямое внимание руководства Собора Света означает, что молодой жрец готов к более глубоким тайнам и большей ответственности внутри веры."},{t="Узы между королевствами",b="Хотя в Стальгорне есть свои священные традиции в Мистическом квартале, Церковь Священного Света в Штормграде служит духовным центром и для людей, и для дворфов. Путь на юг через Подземный поезд связывает дворфийских служителей с более широкой церковной общиной и укрепляет духовное братство двух союзных королевств."}},faq={{q="Почему верховная жрица Лорена призывает жрецов-дворфов в Штормград?",a="Верховная жрица Лорена руководит высшим религиозным обучением в Соборе Света. Когда местные наставники, такие как Максан Анвол, видят, что служитель освоил основы, они направляют его к Лорене для обучения мощным приемам, например «Молитве отчаяния».",al={"why laurena call me","why go to stormwind priest","who is high priestess laurena","почему лорена зовет меня","зачем жрецу идти в штормград","кто такая верховная жрица лорена"}},{q="Что такое «Молитва отчаяния» в преданиях?",a="«Молитва отчаяния» — экстренное воззвание, которое используют клирики Света среди людей и дворфов. На грани смерти жрец издает инстинктивный, настойчивый крик веры, мгновенно затягивающий раны и возвращающий силы.",al={"desperate prayer lore","what is desperate prayer","how does desperate prayer work","предания молитва отчаяния","что такое молитва отчаяния","как работает молитва отчаяния"}},{q="Где происходит это задание?",a="Вызов начинается в Караносе в Дун Мороге, где Максан Анвол велит вам отправиться в Штормград. Он заканчивается в Соборе Света на Соборной площади Штормграда, где правит верховная жрица Лорена.",al={"quest location","where do i go","where is laurena","место задания","куда идти","где лорена"}},{q="Почему жрец-дворф учится у Верховной жрицы-человека?",a="Дворфы и люди разделяют веру в Свет, и этот союз окреп во время Второй войны. Хотя жрецы-дворфы часто служат в Мистическом квартале Стальгорна, Собор Света в Штормграде — один из главных центров веры, принимающий всех последователей Света из Альянса.",al={"why human trainer dwarf","dwarf church of light","ironforge vs stormwind light","почему наставник человек у дворфа","церковь света дворфы","стальгорн или штормград свет"}},{q="Как молодому путнику добраться до Штормграда из Дун Морога?",a="Самый быстрый и безопасный путь лежит через Город механиков в Стальгорне, где Подземный поезд ведет прямо под горами в Квартал Дворфов Штормграда.",al={"how to get to stormwind","travel to stormwind dwarf","deeprun tram","как добраться до штормграда","путь в штормград дворфу","подземный поезд"}},{q="Кто такой Максан Анвол?",a="Максан Анвол — дворф, учитель жрецов из Караноса в Дун Мороге. Он присматривает за начинающими клириками и учит их основам, пока они не станут достаточно дисциплинированными, чтобы учиться у высшего церковного руководства в Штормграде.",al={"maxan anvol lore","who gave quest","kharanos priest trainer","предания максан анвол","кто выдал задание","наставник жрецов каранос"}}},fp="16,353,26.418.0,21.360.0,67.277.0,37.245.0,33.220.0,60.290.0,60.190.0,19.226.0"}
P.entries["quest:5638"] = {n="Молитва отчаяния",s="Молитва отчаяния — задание-вызов для начинающих жрецов, посещающих Парк в Штормграде. По указанию жрицы-ночной эльфийки Нары Мейдерос новички-клерики отправляются через каналы в Собор Света, чтобы продолжить священное обучение у верховной жрицы Лорены. Это момент, когда посвященный переходит от обычной службы к более глубокому, особому единению со Светом.",h="Молитва отчаяния — задание-вызов для начинающих жрецов, посещающих Парк в Штормграде.",kw={"cathedral of light","desperate prayer","high priestess laurena","holy light","nara meideros","priest quest","stormwind","the park","собор света","молитва отчаяния","верховная жрица лорена","свет","нара мейдерос","задание жреца","штормград","парк"},ang={["class:Priest"]="Этот вызов знаменует официальное посвящение жреца в высшие духовные дисциплины и открывает путь к овладению спасительным призывом — «Молитвой отчаяния».",["faction:Alliance"]="Сотрудничество Нары Мейдерос в Парке и духовенства на Соборной площади подчеркивает тихую солидарность священных орденов Дарнасса и Штормграда.",["race:Human"]="Собор Света — главное святилище людского богослужения на юге Восточных королевств, поэтому наставничество Лорены становится культурной и духовной вехой."},sec={{t="Слово в Парке",b="В тихой роще Парка жрицы-ночные эльфийки, такие как Нара Мейдерос, поддерживают единение с Элуной среди шума Штормграда. Но узы веры между духовными наставниками Альянса преодолевают культурные границы. Когда посланник с Соборной площади ищет многообещающего ученика, Нара передает вызов с тихим ободрением и уверяет посвященного, что зов несет добрые вести, а не тревогу."},{t="Зов Собора",b="Пройдя по Соборной площади и ступив под высокие белокаменные арки Собора Света, посвященный является к верховной жрице Лорене. Будучи одной из старших духовных предводительниц Штормграда, Лорена ведет молодых служителей дальше простых начальных молитв. Она открывает им священное воззвание — Молитву отчаяния, личную мольбу о божественном вмешательстве, способную мгновенно исцелить тяжелые раны, когда служитель Света стоит на пороге смерти."}},faq={{q="Кто отправляет меня на это задание?",a="Жрица Нара Мейдерос, клерик-ночная эльфийка из Парка в Штормграде, передает весть о том, что руководство Собора ищет вас.",al={"quest giver","who gives desperate prayer","nara meideros","персонаж, выдающий задания","кто дает молитву отчаяния","нара мейдерос"}},{q="К кому нужно явиться в Штормграде?",a="Вам нужно поговорить с верховной жрицей Лореной, которая находится в Соборе Света на Соборной площади Штормграда.",al={"where to go","quest turn in","who is laurena","куда идти","сдача задания","кто такая лорена"}},{q="В чем значение Молитвы отчаяния?",a="Молитва отчаяния — важная дисциплина, которой обучают клериков Света среди людей и дворфов. Это мгновенное воззвание, призывающее божественную милость, которая мгновенно исцеляет произносящего в минуты крайней опасности.",al={"what does desperate prayer do","priest ability lore","desperate prayer spell","что делает молитва отчаяния","предания о способности жреца","заклинание молитва отчаяния"}},{q="Почему ночная эльфийка направляет жрецов в человеческий собор?",a="Хотя жрицы-ночные эльфийки поклоняются Элуне, а не Свету, которому служат люди и дворфы, духовные ордена Штормграда поддерживают тесные связи и взаимное уважение и передают друг другу вести, когда клерикам Альянса нужно обучение.",al={"why nara meideros","park to cathedral","night elf elune stormwind","почему нара мейдерос","из парка в собор","ночной эльф элуна штормград"}},{q="На каком этапе обучения приходит этот вызов?",a="Этот вызов приходит примерно на десятом уровне опыта и означает, что молодой жрец достаточно проявил себя в полевых условиях, чтобы осваивать более сложные божественные обряды.",al={"what level is this","when do i get desperate prayer","какой уровень","когда получить молитву отчаяния"}},{q="Где находится Собор Света?",a="Собор Света возвышается над Соборной площадью в северной части Штормграда, между Кварталом Дворфов и Парком.",al={"cathedral location","where is cathedral square","где собор","где соборная площадь"}}},fp="16,409,18.435.0,25.477.0,27.162.0,40.118.0,45.228.0,60.239.0,50.169.0,40.144.0"}
P.entries["quest:5639"] = {n="Молитва отчаяния",s="Молитва отчаяния — обряд посвящения для жрецов-дворфов, достигших зрелости в Стальгорне. По указанию верховного жреца Рохана аколиты отправляются через Подземный поезд в Штормград, чтобы продолжить обучение у верховной жрицы Лорены. Прибытие в величественный Собор Света знаменует переход посвященного к более глубоким тайнам исцеления и выживания.",h="Молитва отчаяния — обряд посвящения для жрецов-дворфов, достигших зрелости в Стальгорне.",kw={"cathedral of light","desperate prayer","ironforge","laurena","mystic ward","priest","rohan","stormwind","собор света","молитва отчаяния","стальгорн","лорена","мистический квартал","жрец","рохан","штормград"},ang={["class:Priest"]="Это паломничество знаменует ваш переход от местного обучения в Стальгорне к более широкой иерархии Церкви Священного Света.",["faction:Alliance"]="Совместное обучение священников отражает глубокий духовный союз и институциональное сотрудничество Стальгорна и Штормграда.",["race:Dwarf"]="Для молодых дворфов Каз Модана поездка в Штормград — это первое знакомство с культурой людей, величественной архитектурой и общей духовной преданностью."},sec={{t="Вызов в Штормград",b="В каменных сводах Мистического квартала Стальгорна верховный жрец Рохан наставляет дворфов-посвященных, преданных Свету. Когда аколит проявляет достаточную дисциплину и веру, Рохан направляет его на юго-запад, в человеческое королевство Штормград. Клерики людей и дворфов связаны тесными духовными узами, а высшее богословское обучение сосредоточено в величественных залах Штормграда."},{t="Собор Света",b="Прибыв по Подземному поезду, аколиты поднимаются на Соборную площадь. Там, в величественном Соборе Света, верховная жрица Лорена испытывает кандидатов от имени Церкви. Ее наставления посвящены отчаянным мольбам, к которым жрец прибегает в горниле битвы, когда телесные силы иссякают и смерть близка."}},faq={{q="Кто отправляет меня на это задание?",a="Это задание дает верховный жрец Рохан. Он возглавляет духовенство дворфов в Зале Тайн в Мистическом квартале Стальгорна.",al={"who gives quest","quest giver","rohan location","кто дает задание","персонаж, выдающий задания","где рохан"}},{q="Куда нужно отправиться, чтобы выполнить это задание?",a="Вам нужно отправиться в Собор Света в центре Соборной площади Штормграда. Верховная жрица Лорена ждет в главном святилище.",al={"where is laurena","where to turn in","stormwind turn in","где лорена","куда сдавать","сдача задания в штормграде"}},{q="Как лучше всего добраться из Стальгорна в Штормград?",a="Самый безопасный и быстрый путь — Подземный поезд, инженерное чудо, построенное гномами. Вход находится в восточной части Стальгорна и ведет прямо в Квартал Дворфов Штормграда.",al={"how to get to stormwind","travel to stormwind","tram location","как добраться до штормграда","путь в штормград","где поезд"}},{q="Почему жрецу-дворфу нужно учиться в человеческом городе?",a="Церковь Священного Света глубоко коренится в человеческой традиции, а главный центр обучения — Собор Света. Священники дворфов и людей действуют сообща, делясь учениями и традициями по всему Альянсу.",al={"why stormwind","dwarf human church","why laurena","почему штормград","церковь дворфов и людей","почему лорена"}},{q="Какую способность открывает это обучение?",a="Эта цепочка заданий приобщает вас к изучению Молитвы отчаяния — мгновенной молитвы самосохранения, которая быстро восстанавливает здоровье жреца в тяжелых ситуациях.",al={"quest reward","what spell do i get","desperate prayer ability","награда за задание","какое заклинание я получу","способность молитва отчаяния"}},{q="Есть ли в этом задании бои?",a="Нет. Это задание — чистое паломничество и поручение посланника: вам нужно безопасно добраться из Стальгорна в Штормград и представиться верховной жрице Лорене.",al={"is there fighting","quest combat","travel quest","есть ли бой","бой в задании","задание на путешествие"}}},fp="16,346,22.399.0,22.379.0,27.132.0,39.161.0,56.217.0,52.225.0,39.167.0,31.166.0"}
P.entries["quest:5640"] = {n="Молитва отчаяния",s="Молитва отчаяния — задание для юных жрецов-людей и дворфов, посещающих Дарнасс, которое направляет их обратно к собственным духовным традициям в Штормграде. Жрица Алатея понимает, что ночные эльфы черпают силу в Элуне, а последователям Света следует искать наставников своей веры. Завершив это путешествие, аколит возвращается к верховной жрице Лорене в Соборе Света.",h="Молитва отчаяния — задание для юных жрецов-людей и дворфов, посещающих Дарнасс, которое направляет их обратно...",kw={"alathea","cathedral of light","darnassus","desperate prayer","elune","holy light","laurena","stormwind","алатея","собор света","дарнасс","молитва отчаяния","элуна","свет","лорена","штормград"},ang={["class:Priest"]="Это задание показывает, что священная магия Альянса разделена между почитанием Элуны и преданностью Свету, и направляет юных аколитов обратно к их настоящим наставникам.",["race:Dwarf"]="Жрецы-дворфы, почитающие Свет, тесно связаны с собором Штормграда и осваивают высшие воззвания вместе со своими собратьями-людьми.",["race:Human"]="Жрецам-людям вдали от дома напоминают, что их истинный духовный дом и обучение ждут в Соборе Света в Штормграде.",["race:NightElf"]="Сестры Элуны из числа ночных эльфов с вежливым почтением признают силу чужих верований, но хранят строгую преданность одной лишь Матери Луне."},sec={{t="Два пути веры",b="Жрецы Альянса черпают силу из принципиально разных священных источников. В Дарнассе жречество Элуны служит богине луны, направляя ее мягкое сияние и небесный гнев. Когда аколиты-люди и дворфы приходят под ветви Тельдрассила, наставницы вроде жрицы Алатеи вежливо признают эту границу: она чтит Элуну и уважает Свет, но не может обучать другую расу глубоким молитвам, связанным с совсем иной верой."},{t="Возвращение в Собор",b="Чтобы овладеть способностями, рожденными абсолютной верой, например призывом божественного вмешательства в самый темный час, посвященным Света велят вернуться домой. Верховная жрица Лорена руководит обучением под высокими мраморными арками Собора Света Штормграда и готова провести вернувшихся жрецов к более глубоким обрядам их призвания."}},faq={{q="Почему жрица из Дарнасса отправляет меня в Штормград?",a="Жрица Алатея обучает путям богини луны Элуны. Поскольку люди и дворфы черпают веру и чудеса из Света, Алатея вежливо направляет их к наставникам их собственной традиции, например к верховной жрице Лорене в Штормграде.",al={"why go to stormwind","why alathea sends me away","darnassus to stormwind priest quest","почему в штормград","почему алатея отправляет меня","задание жреца из дарнасса в штормград"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — жрица-ночная эльфийка, служащая в Храме Луны в Дарнассе. Она наставляет будущих последователей Элуны и почтительно направляет приезжих жрецов, посещающих Мировое древо.",al={"alathea lore","who is alathea","предания об алатее","кто такая алатея"}},{q="Кто такая верховная жрица Лорена?",a="Верховная жрица Лорена — духовная предводительница людей, находящаяся в Соборе Света в Штормграде. Она наставляет многообещающих служителей Света, помогая им овладеть высшими молитвами и суровыми обязанностями.",al={"who is laurena","high priestess laurena stormwind","кто такая лорена","верховная жрица лорена штормград"}},{q="Что такое Молитва отчаяния в преданиях?",a="Молитва отчаяния — мгновенный призыв о божественной помощи, когда жрец близок к смерти или в смертельной опасности. Это отличительное воззвание, дарованное верным служителям Света, которым нужно немедленное исцеление.",al={"what is desperate prayer","desperate prayer ability lore","что такое молитва отчаяния","предания о способности молитва отчаяния"}},{q="Могут ли ночные эльфы обучать Свету?",a="Нет. Ночные эльфы почти исключительно почитают Элуну и направляют ее лунную силу. Они относятся ко Свету с дипломатическим уважением, но не проповедуют его и не обучают его особым молитвам, оставляя это жречеству людей и дворфов.",al={"do night elves know the light","elune vs holy light","знают ли ночные эльфы свет","элуна и свет"}},{q="Где найти верховную жрицу Лорену?",a="Верховная жрица Лорена живет на Соборной площади Штормграда и находится в Соборе Света среди собратьев-клириков и паладинов Серебряной Длани.",al={"laurena location","where is laurena","где лорена","где найти лорену"}}},fp="16,401,18.489.0,23.366.0,49.249.0,25.207.0,30.240.0,37.220.0,37.241.0,40.165.0"}
P.entries["quest:5643"] = {n="Страж Тьмы",s="Страж Тьмы — жреческое задание для троллей-жрецов племени Черного Копья, которые оказались далеко от дома в столице Отрекшихся, Подгороде. Эльталисте признает, что молодой тролль достаточно возмужал для священных обрядов своего племени, и отправляет его обратно в Оргриммар. В Аллее Духов его ждет наставник жрецов Ур'кьо, который введет его в важную ступень духовной защиты.",h="Страж Тьмы — жреческое задание для троллей-жрецов племени Черного Копья, которые оказались далеко от дома в...",kw={"aelthalyste","orgrimmar","rite of passage","shadowguard","troll priest","undercity","ur'kyo","valley of spirits","эльталисте","оргриммар","обряд перехода","страж тьмы","тролль-жрец","подгород","ур'кьо","аллея духов"},ang={["class:Priest"]="Этот обряд отмечает важную веху на пути жреца, отделяя общие основы магии Света и Тьмы от особых культурных традиций его народа.",["race:Troll"]="Для племени Черного Копья обучение жреческому делу неотделимо от общения с лоа и защиты племени — это наследие хранит Ур'кьо в Аллее Духов.",["race:Undead"]="Наставницы вроде Эльталисте признают особые традиции своих живых союзников и следят за тем, чтобы приезжие тролли получали обучение у собственных старейшин, а не учение Отрекшихся."},sec={{t="Призыв через континенты",b="Даже в мраке Подгорода узы веры и племенных традиций остаются крепкими. Наставница жрецов из числа Отрекшихся Эльталисте внимательно наблюдает за приезжими троллями-жрецами и замечает, когда посвященный достаточно окреп для испытаний своей культуры. Вместо того чтобы навязывать им мрачную философию Культа Забытой Тени, она направляет тролля обратно через Великое море, к древним обычаям его собственных старейшин."},{t="Аллея Духов",b="Прибыв в Дуротар, жрец отправляется в мистический уголок Оргриммара — Аллею Духов. Там Ур'кьо заботится о духовных нуждах и древних ритуалах племени Черного Копья. Он приветствует вернувшегося посвященного и готовит его к важному обряду перехода, который связывает узы жреца с лоа и практические заклинания, необходимые для защиты от вреда."}},faq={{q="Кто дает это задание?",a="Задание дает Эльталисте, наставница жрецов, живущая в Военном квартале Подгорода. Она замечает, когда тролль-жрец достиг зрелости, необходимой для духовных испытаний его племени.",al={"quest giver","where do i start","who gives shadowguard","кто выдает задание","где начать","кто дает страж тьмы"}},{q="Почему наставница из Подгорода отправляет меня в Оргриммар?",a="Жрецы Отрекшихся исповедуют Культ Забытой Тьмы, а тролли Черного Копья черпают духовную силу в лоа и племенных традициях. Эльталисте уважает это разделение и отправляет начинающих жрецов-троллей домой, чтобы они изучили свои особые расовые умения у собственного старейшины.",al={"why go to orgrimmar","undercity to orgrimmar","why ur'kyo","почему в оргриммар","из подгорода в оргриммар","почему ур'кьо"}},{q="Кто такой Ур'кьо?",a="Ур'кьо — известный наставник жрецов-троллей племени Черного Копья, живущий в Аллее Духов в Оргриммаре. Он является учителем и наставником в духовных обычаях и обрядах перехода троллей.",al={"ur'kyo lore","who is urkyo","priest trainer ur'kyo","ур'кьо предания","кто такой ур'кьо","наставник жрецов ур'кьо"}},{q="В чем значение умения «Страж Тьмы»?",a="Страж Тьмы — защитный оберег, свойственный только жрецам-троллям. Он призывает теневых духов и благословения лоа и проявляется в виде вращающихся теней, которые наносят ответный удар любому врагу, безрассудно напавшему на заклинателя.",al={"what is shadowguard","shadowguard spell lore","why is it important","что такое страж тьмы","предания о заклинании страж тьмы","почему это важно"}},{q="Получают ли это задание другие расы?",a="Этот призыв предназначен исключительно для троллей-жрецов племени Черного Копья, которые оказались в Подгороде примерно к двадцатому году жизненного опыта. У жрецов Отрекшихся есть собственные обряды и обучение в рамках Культа Забытой Тени.",al={"can undead do this","is this troll only","priest race quest","могут ли нежить","только для троллей","задание жрецов разных рас"}},{q="Где в Оргриммаре находится Ур'кьо?",a="Ур'кьо можно найти в Аллее Духов — южном районе Оргриммара, отведенном троллям Черного Копья и их мистическим практикам.",al={"where is ur'kyo","urkyo location","find ur'kyo","где ур'кьо","местонахождение ур'кьо","найти ур'кьо"}}},fp="11,383,27.423.0,21.376.0,22.200.0,51.276.0,14.192.0,52.211.0,34.241.0,37.145.0"}
P.entries["quest:5644"] = {n="Всепожирающая чума",s="«Всепожирающая чума» — задание-обряд посвящения для жрецов Отрекшихся, отправляющихся далеко от Лордерона. Наставник жрецов Отрекшихся Майлз Уэльш в Громовом Утесе направляет ученика обратно за моря, к Эльталисте в Подгороде, чтобы тот получил фирменное проявление магии Тьмы.",h="«Всепожирающая чума» — задание-обряд посвящения для жрецов Отрекшихся, отправляющихся далеко от Лордерона.",kw={"aelthalyste","devouring plague","forsaken","miles welsh","shadow priest","thunder bluff","undercity","war quarter","эльталисте","всепожирающая чума","отрекшиеся","майлз уэльш","жрец тьмы","громовой утес","подгород","военный квартал"},ang={["class:Priest"]="Это задание — важная веха в обучении жреца Отрекшихся: от базовых основ он переходит к грозным традициям Тьмы, свойственным нежити.",["faction:Horde"]="Задание показывает материально-технические и духовные связи, соединяющие далекие форпосты Орды в Мулгоре с темным сердцем Подгорода.",["race:Undead"]="В отличие от Света, которому они служили при жизни, жрецы Отрекшихся принимают суровые недуги и магию Тьмы, и Всепожирающая чума воплощает их особую культурную магию."},sec={{t="Призыв домой",b="Во время пребывания в Громовом Утесе жрецов Отрекшихся, овладевших божественными и теневыми дисциплинами, оценивает Майлз Уэльш, посланник Культа Забытой Тени среди тауренов. Признав, что аколит достаточно окреп, Майлз велит ему вернуться в Руины Лордерона, а не пытается сам передать эти высшие тайны в Калимдоре."},{t="Тайны Эльталисте",b="Под руинами города, в Военном квартале Подгорода, ждет Эльталисте — одна из ведущих наставниц жрецов Отрекшихся. Она следит за развитием аколитов, плетущих тени, и следит за тем, чтобы могучая, истощающая порча, известная как Всепожирающая чума, доверялась лишь тем, кто способен управлять ее оскверняющей силой и не поддаться ей."}},faq={{q="Кто отправляет вас на это задание?",a="Майлз Уэльш, наставник жрецов Отрекшихся из Прудов Видений под Вершиной Духов в Громовом Утесе, отправляет вас в это путешествие, когда ваши способности достаточно разовьются.",al={"who starts devouring plague quest","quest giver devouring plague","miles welsh role","кто дает задание всепожирающая чума","выдающий задание всепожирающая чума","роль майлза уэльша"}},{q="Где находится Эльталисте?",a="Эльталисте живет в Военном квартале Подгорода, среди тренировочных площадок и темных каналов, где собираются жрецы Отрекшихся.",al={"aelthalyste location","where is aelthalyste","devouring plague turn in","местонахождение эльталисте","где эльталисте","сдача задания всепожирающая чума"}},{q="Почему Майлз Уэльш не может сам обучить этому заклинанию?",a="Некоторые основополагающие тайны теневой веры Отрекшихся доверены лишь мастерам-наставникам вроде Эльталисте в сердце Подгорода. Уэльш чтит эту иерархию и отправляет достойных адептов домой на испытание.",al={"why travel to undercity","why see aelthalyste","undercity priest trainer","зачем ехать в подгород","зачем идти к эльталисте","наставник жрецов подгорода"}},{q="Что такое Всепожирающая чума с точки зрения преданий?",a="Это разрушительное проклятие, которое применяет Культ Забытой Тени: оно поражает жертву губительной магической заразой, поглощающей ее жизненные силы, чтобы исцелить заклинателя.",al={"what is devouring plague","lore of devouring plague","forsaken disease spell","что такое всепожирающая чума","предания о всепожирающей чуме","болезнь отрекшихся заклинание"}},{q="Доступно ли это задание другим расам?",a="Нет. Задание «Всепожирающая чума» связано исключительно с жречеством Отрекшихся и отражает особую философию и магические практики, рожденные выжившими нежитью Лордерона.",al={"can trolls do devouring plague quest","can orcs do devouring plague","is this quest undead only","могут ли тролли задание всепожирающая чума","могут ли орки","только для нежити"}},{q="Почему наставник Отрекшихся вообще находится в Громовом Утесе?",a="После принятия Отрекшихся в Орду столицы обменялись дипломатами и наставниками. Жрецы вроде Майлза Уэльша представляют духовные традиции Подгорода и помогают Отрекшимся, путешествующим по Калимдору.",al={"why are undead in thunder bluff","forsaken in thunder bluff lore","miles welsh thunder bluff","почему нежить в громовом утесе","отрекшиеся в громовом утесе предания","майлз уэльш громовой утес"}}},fp="16,291,14.384.0,26.361.0,28.184.0,29.139.0,46.211.0,49.177.0,39.171.0,62.235.0"}
P.entries["quest:5645"] = {n="Бесстрашие",s="«Бесстрашие» — вызов для жрецов-дворфов, возвращающий перспективных учеников в великие залы Стальгорна. Верховный жрец Рохан ждет в Мистическом квартале, чтобы проверить их дисциплину и передать учения, соответствующие их растущей стойкости.",h="«Бесстрашие» — вызов для жрецов-дворфов, возвращающий перспективных учеников в великие залы Стальгорна.",kw={"alathea","fear ward","hall of mysteries","ironforge","laurena","mystic ward","priest","rohan","алатея","защита от страха","зал тайн","стальгорн","лорена","мистический квартал","жрец","рохан"},ang={["class:Priest"]="Этот призыв отмечает ваше взросление в жречестве и дает право изучить особые священные приемы, отточенные стойким духовенством Стальгорна.",["faction:Alliance"]="Жречества Альянса поддерживают тесную связь между столицами, посылая аколитов через границы учиться у мастеров-духовников в Стальгорне.",["race:Dwarf"]="Возвращение к Рохану чтит особое сочетание непоколебимой веры, телесной стойкости и боевой доблести вашего народа на службе Свету."},sec={{t="Призыв в Стальгорн",b="Жрецов Альянса, служащих вдали от дома, местные наставники обычно направляют с докладом к высшему духовенству их ордена. Для учеников-дворфов этот путь ведет прямо к верховному жрецу Рохану в сердце Мистического квартала Стальгорна. Этот вызов отмечает перелом, когда простая духовная практика уступает место более глубокому, проверенному испытаниями применению священной магии."},{t="Испытания стойкости",b="Верховный жрец Рохан не просто обучает литургии: по традиции дворфов Свет — это щит и непреклонный оплот в телесной схватке. Явка на это испытание означает, что посвященный пережил крещение огнем в большом мире и обладает мужеством, нужным, чтобы одолеть сам страх на передовой."}},faq={{q="Какова цель этого задания?",a="Это официальный призыв от местных наставников жрецов к верховному жрецу Рохану в Стальгорне: он направляет опытных посвященных на углубленное обучение, чтобы они обрели особые духовные дары, которыми владеет жречество города.",al={"why do i have to go to rohan","what does a lack of fear do","priest quest level 20 ironforge","зачем идти к рохану","что дает бесстрашие","задание жреца 20 уровня стальгорн"}},{q="Кто такой верховный жрец Рохан?",a="Верховный жрец Рохан — старший предводитель жречества дворфов в Стальгорне. Он обучает учеников в Зале Тайн в Мистическом квартале, делая упор на стойкую преданность и боевую выносливость.",al={"who is rohan","high priest rohan lore","кто такой рохан","верховный жрец рохан предания"}},{q="Где найти верховного жреца Рохана?",a="Рохан находится в Зале Тайн, расположенном в Мистическом квартале в западной части Стальгорна.",al={"where is rohan","rohan location","how to find high priest rohan","где рохан","местонахождение рохана","как найти верховного жреца рохана"}},{q="Почему задание называется «Бесстрашие»?",a="Задание представляет подготовку жреца к получению Защиты от страха — особого защитного благословения, взращенного дворфами, преданными Свету, чтобы оберегать разум от паники и сверхъестественного ужаса.",al={"meaning of lack of fear","fear ward quest","смысл бесстрашия","задание защита от страха"}},{q="Кто отправляет жреца в Стальгорн?",a="Посвященных обычно направляют местные наставники, например верховная жрица Лорена в Штормграде или жрица Алатея в Дарнассе, которые велят ученикам почтить свое наследие или учиться под руководством Рохана.",al={"who starts a lack of fear","quest givers for lack of fear","кто дает бесстрашие","выдающие задание бесстрашие"}},{q="Есть ли в этом задании бой?",a="Нет. Для задания нужно отправиться в Стальгорн и поговорить с верховным жрецом Роханом, который обучает Защите от страха.",al={"do i have to fight","is there combat in a lack of fear","нужно ли сражаться","есть ли бой в бесстрашии"}}},fp="14,258,22.369.0,23.326.0,34.231.0,25.202.0,37.112.0,36.203.0,34.221.0,31.103.0"}
P.entries["quest:5646"] = {n="Всепожирающая чума",s="«Всепожирающая чума» — задание-посвящение для жрецов из числа Отрекшихся, отправившихся в Калимдор учиться у племени Черного Копья. Жрец-тролль, наставник Ур'кьо в Оргриммаре, направляет перспективных новичков из Отрекшихся обратно домой, в Подгород, где Эльталисте ждет, чтобы передать им более глубокие учения Культа Забытой Тени.",h="«Всепожирающая чума» — задание-посвящение для жрецов из числа Отрекшихся, отправившихся в Калимдор учиться у...",kw={"aelthalyste","devouring plague","forsaken priest","orgrimmar","shadow priest","undercity","ur'kyo","war quarter","эльталисте","всепожирающая чума","жрец отрекшихся","оргриммар","жрец тьмы","подгород","ур'кьо","военный квартал"},ang={["class:Priest"]="Жрецы Отрекшихся опираются на особые расовые учения о тени и распаде и учатся направлять свои телесные муки в разрушительные проклятия, такие как «Всепожирающая чума».",["faction:Horde"]="Совместные обязанности по обучению, которые делят Ур'кьо в Дуротаре и Эльталисте в Тирисфале, показывают практическое сотрудничество и взаимное уважение, связывающие далекие столицы Орды.",["race:Undead"]="Возвращение в Военный квартал Подгорода напоминает искателям приключений из Отрекшихся, что их истинная верность и духовные корни лежат под руинами Лордерона, как бы далеко ни уводили их обязанности перед Ордой."},sec={{t="Обмен верованиями",b="Орки и таурены мало склонны к жреческому служению, но тролли Черного Копья и Отрекшиеся связаны в Орде необычным богословским союзом. В Оргриммаре наставник жрецов, тролль Ур'кьо, ведет тех, кого влечет духовная сила. Однако он понимает, что новички из Отрекшихся должны в итоге овладеть зловещими искусствами, присущими их состоянию. В знак взаимного уважения между их народами Ур'кьо отправляет странствующих Отрекшихся обратно в Лордерон для завершения обучения."},{t="Военный квартал Подгорода",b="Под руинами Лордерона жрица Эльталисте заботится о пастве в Военном квартале Подгорода. Жрецы Отрекшихся идут одиноким, суровым путем, который определен Культом Забытой Тени: они смягчают болезненное прикосновение Света разрушительной порчей магии Тени. Когда новичок достигает достаточного мастерства, Эльталисте призывает его к себе, чтобы наделить недугом, известным их народу как «Всепожирающая чума»."}},faq={{q="Кто отправляет меня на это задание?",a="Ур'кьо, жрец-тролль и наставник, которого можно найти среди духов в Оргриммаре, предлагает это задание жрецам из числа Отрекшихся, достигшим двадцатого уровня силы.",al={"quest giver","who starts devouring plague","ur'kyo location","персонаж, выдающий задания","кто начинает всепожирающая чума","где находится ур'кьо"}},{q="Куда мне нужно отправиться?",a="Вы должны пересечь Великое море и добраться до Подгорода в Тирисфальских лесах. Найдите жрицу Эльталисте, которая руководит обучением жрецов Отрекшихся в Военном квартале.",al={"where do i turn this in","aelthalyste location","undercity priest trainer","где сдать задание","где находится эльталисте","учитель жрецов в подгороде"}},{q="Почему Ур'кьо отправляет Отрекшихся обратно в Лордерон?",a="Ур'кьо чтит договоренность с жрицей Эльталисте. Тролли-жрецы Тьмы понимают лоа и духов, но Отрекшиеся владеют темными искусствами, связанными именно с их нежитью природой, и им необходимо обучение непосредственно у их собственных предводителей.",al={"why go back to undercity","why does troll priest send me away","зачем возвращаться в подгород","почему жрец-тролль отсылает меня"}},{q="В чем значение «Всепожирающей чумы»?",a="«Всепожирающая чума» — мощный недуг, присущий только Отрекшимся, практикующим магию Тени. Он наносит целям разрушительную болезнь и одновременно перекачивает их жизненную силу прямо к заклинателю.",al={"what is devouring plague lore","forsaken priest plague","предания всепожирающая чума","чума жреца отрекшихся"}},{q="Могут ли другие расы Орды взять это задание?",a="Нет. Это задание предлагается исключительно жрецам из числа Отрекшихся и отражает их связь с особыми учениями Тени их родины.",al={"can trolls do this","is this quest undead only","могут ли тролли это сделать","задание только для нежити"}},{q="Как это вписывается в отношения жрецов Орды?",a="Орда опирается на взаимный обмен между знахарями и жрецами-колдунами Черного Копья в Калимдоре и жрецами Тьмы из числа Отрекшихся в Восточных королевствах: каждые направляют путников к наставникам, лучше всего подходящим их культуре.",al={"trolls and undead priests","horde priest lore","тролли и жрецы нежити","предания жрецов орды"}}},fp="16,324,20.493.0,28.433.0,27.158.0,22.168.0,48.239.0,49.194.0,40.136.0,46.220.0"}
P.entries["quest:5648"] = {n="Одеяния духовности",kw={"durotar","fortitude","garments of spirituality","grunt kor'ja","lesser heal","proudmoore","razor hill","tai'jin","дуротар","стойкость","одеяния духовности","грунт кор'джа","малое исцеление","праудмур","колючий холм","тай'джин"},ang={["class:Priest"]="Этот обряд посвящения — главное раннее испытание для жрецов Орды в Дуротаре: он подтверждает их навыки полевой помощи и приносит им первые облачения.",["faction:Horde"]="Выживание Грунта Кор'джи напрямую укрепляет оборону Колючего Холма от людей Кул Тираса, засевших поблизости.",["race:Troll"]="Наставничество Тай'джин соединяет древнюю духовность троллей с практическим долгом на поле боя и помогает юным троллям Черного Копья защищать союзников своей верой."},sec={{t="Испытание целителя",b="В засушливых зарослях к югу от Колючего Холма Орда ведет непрерывные стычки с остатками сил верховного адмирала Даэлина Праудмура. Вместо абстрактных обрядов наставница-троллиха Тай'джин проверяет выдержку будущих жрецов в настоящей боевой сортировке раненых. Новичкам поручено найти Грунта Кор'джу, воина, тяжело раненного при отражении нападения лазутчиков-людей, залечить ее раны и укрепить ее телосложение, пока она не погибла."},{t="Облачения верных",b="Возвращение Кор'джи боеспособности доказывает готовность юного жреца нести бремя духовной традиции Орды. В знак признательности за спасение защитницы передовой Тай'джин дарует «Одеяния духовности». Для союзников-орков и троллей Черного Копья эти одеяния означают, что их носитель — не просто ученик, изучающий заклинания, а надежная опора, способная сохранить жизнь воинам Орды в бою."}},faq={{q="Кто такая Грунт Кор'джа и почему ей нужно исцеление?",a="Грунт Кор'джа — воин Орды, несущий службу к югу от Колючего Холма. Она была ранена в стычке с уцелевшими солдатами экспедиции Кул Тираса адмирала Праудмура, которые все еще тревожат побережье Дуротара.",al={"grunt korja","who is korja","injured grunt south","грунт корджа","кто такая корджа","раненый грунт на юге"}},{q="Где найти Тай'джин?",a="Тай'джин находится в Колючем Холме в Дуротаре. Она служит духовной наставницей и учителем жрецов для молодых искателей приключений Орды, покидающих Долину Испытаний.",al={"taijin location","who gives garments of spirituality","priest trainer razor hill","где тай'джин","кто дает одеяния духовности","учитель жрецов колючий холм"}},{q="Какие способности нужны, чтобы исцелить Кор'джу?",a="Жрецы должны залечить раны Кор'джи с помощью «Малого исцеления» и укрепить ее выносливость благословением «Слова силы: Стойкость», а затем вернуться к Тай'джин.",al={"which spells to use","how to complete garments of spirituality","korja spells","какие заклинания использовать","как выполнить одеяния духовности","заклинания для кор'джи"}},{q="Почему солдаты Кул Тираса все еще сражаются в Дуротаре?",a="После вторжения и поражения верховного адмирала Праудмура остатки его флота рассеялись вдоль восточного побережья Дуротара. Они продолжают предпринимать отчаянные набеги и создавать опорные пункты, как крепость Тирагард.",al={"proudmoore troops durotar","why humans in razor hill","kul tiras remnants","войска праудмура в дуротаре","почему люди в колючем холме","остатки кул тираса"}},{q="В чем значение полученных одеяний?",a="Одеяния, которые вручает Тай'джин, знаменуют переход новичка в действующие целители Орды. Пройдя это практическое испытание, ученик получает право носить облачение своего призвания.",al={"garments reward lore","why give a robe","priest vestments razor hill","предания о награде одеяния","зачем дают одеяние","облачение жреца колючий холм"}},{q="Какое задание предшествует «Одеяниям духовности»?",a="Это испытание следует за заданием «В пользу духовности» — вводным заданием, которое предлагает Тай'джин, когда жрец получает достаточную начальную подготовку в Колючем Холме.",al={"prerequisite quest","before garments of spirituality","how to start garments","предыдущее задание","перед одеяниями духовности","как начать одеяния духовности"}}},fp="24,382,16.462.0,25.429.0,50.208.0,25.154.0,40.154.0,53.209.0,49.192.0,45.157.0"}
P.entries["quest:5649"] = {n="В пользу духовности",s="«В пользу духовности» — основополагающий обряд посвящения для юных жрецов Черного Копья, покидающих Долину Испытаний. Ощущая направление Кен'джая явиться к наставнице жрецов Тай'джин в Колючем Холме, новички делают первые настоящие шаги за пределы уединенного учебного логова к более широким испытаниям Дуротара. Путь показывает, как непросто Черному Копью сохранять равновесие между уважением к наследию троллей-предков и вхождением в недавно созданную Орду.",h="«В пользу духовности» — основополагающий обряд посвящения для юных жрецов Черного Копья, покидающих Долину...",kw={"darkspear","durotar","in favor of spirituality","ken'jai","priest","razor hill","tai'jin","valley of trials","черное копье","дуротар","в пользу духовности","кен'джай","жрец","колючий холм","тай'джин","долина испытаний"},ang={["class:Priest"]="Это задание знаменует ваш выход из каньона новичков, чтобы получить официальное обучение и облачение от Тай'джин в Колючем Холме.",["faction:Horde"]="Оно показывает, как разные культуры взаимодействуют в Дуротаре, соединяя дикие традиции Островов Эха с военным форпостом Колючий Холм.",["race:Troll"]="Это задание показывает напряжение, с которым Черное Копье сталкивается каждый день, балансируя между верностью Орде и сохранением древней племенной духовности."},sec={{t="Уход из Красного каньона",b="Освоив основные обряды под руководством Кен'джая в уединенной Долине Испытаний, аколиты Черного Копья готовы покинуть место обучения. Извилистые тропы в Дуротаре ведут прямо к поселению на перекрестке — Колючему Холму. Для юного жреца это путешествие — важная веха: от простых упражнений на выживание в пыли к духовной и культурной ответственности за племя."},{t="Старые веры и новые союзы",b="Кен'джай откровенен насчет положения Черного Копья в Орде Тралла. Хотя тролли высоко ценят верность орков и их уроки чести, не всякая традиция предков спокойно уживается под взглядами союзников. Духовные наставники Черного Копья учат своих учеников тихо хранить наследие, твердо держась своей самобытности и продолжая служить Орде. Тай'джин в Колючем Холме приобщает этих аколитов к этому более глубокому пониманию и направляет их к самостоятельности и силе общины."}},faq={{q="Кто дает задание «В пользу духовности»?",a="Задание дает Кен'джай, наставник жрецов из числа троллей, находящийся в Логове в Долине Испытаний.",al={"who starts in favor of spirituality","quest giver in favor of spirituality","kenjai priest quest","кто начинает в пользу духовности","кто выдает задание в пользу духовности","кен'джай задание жреца"}},{q="Где найти Тай'джин?",a="Тай'джин живет в казармах Колючего Холма, к востоку от центра поселения, вдоль главной дороги Дуротара.",al={"tai'jin location","where is tai jin","find tai'jin","где тай'джин","как найти тай'джин","тай'джин местонахождение"}},{q="Какие классы могут взять это задание?",a="Это задание предлагается исключительно жрецам-троллям, начинающим свой путь в Дуротаре.",al={"is this quest priest only","who can take in favor of spirituality","priest class quest razor hill","только ли для жрецов","кто может взять в пользу духовности","классовое задание жреца колючий холм"}},{q="Почему Кен'джай подчеркивает необходимость хранить некоторые традиции в тайне?",a="Кен'джай понимает, что орки — верные соратники, ценящие честь, но не всякий древний обряд или обычай троллей они встречают благосклонно. Он учит юных жрецов скромно чтить наследие предков, чтобы сохранять согласие в Орде.",al={"why secret troll traditions","orc troll friction religion","why practice in secret","почему тайные традиции троллей","трения орков и троллей религия","почему практиковать тайно"}},{q="Чему Тай'джин учит юного жреца по прибытии?",a="Тай'джин объясняет, что Черное Копье стало сильнее, приспособившись к жизни в Орде. Вместо того чтобы ждать и забирать силу у павших врагов, племя теперь готовится заранее и вступает в бой уже усиленным.",al={"taijin speech","what does tai jin say","darkspear adaptation","речь тай'джин","что говорит тай'джин","приспособление черного копья"}},{q="Какое задание следует сразу после «В пользу духовности»?",a="После сдачи этого задания Тай'джин предлагает «Одеяния духовности», которое отправляет аколита помочь раненому солдату Орды на местности.",al={"what comes after in favor of spirituality","in favor of spirituality follow up","next priest quest after taijin","что после в пользу духовности","продолжение в пользу духовности","следующее задание жреца после тай'джин"}}},fp="24,462,22.427.0,28.509.0,45.105.0,25.114.0,35.86.0,58.247.0,54.233.0,56.142.0"}
P.entries["quest:5650"] = {n="Одеяния Тьмы",s="«Одеяния Тьмы» — основополагающий обряд посвящения для начинающих священников Отрекшихся в Брилле. Темный священник Берил поручает неофитам исцелить и укрепить раненого Стража смерти, проверяя их владение магией поддержки, прежде чем они углубятся в Тень.",h="«Одеяния Тьмы» — основополагающий обряд посвящения для начинающих священников Отрекшихся в Брилле.",kw={"brill","dark cleric beryl","deathguard kel","fortitude","garments of darkness","lesser heal","priest","shadow","tirisfal glades","брилл","темный священник берил","страж смерти кел","стойкость","одеяния тьмы","малое исцеление","священник","тень","тирисфальские леса"},ang={["class:Priest"]="Этот обряд воплощает философию священничества Отрекшихся: баланс мрачной пользы Тени и незаменимого долга укреплять и исцелять союзников.",["race:Undead"]="Для Отрекшихся магия исцеления — практичное средство выживания, помогающее поддерживать бойцов передовой, таких как Страж смерти Кел, в схватках с гноллами и остатками Плети."},sec={{t="Равновесие Тьмы и Света",b="Хотя священничество Отрекшихся черпает известность и особую самобытность в тени и тьме, его старейшины признают неизменную практическую необходимость исцеления. Темный священник Берил учит, что понимание тьмы требует понимания света и восстанавливающих искусств. Священнику, ищущему лишь разрушения, советуют вместо этого изучать тайную магию: истинное призвание священничества — укреплять и беречь соратников не меньше, чем поражать врагов."},{t="Долг на кладбище",b="Чтобы доказать мастерство, неофита отправляют к северу от кладбища Брилла на помощь Стражу смерти Келу. Кел охраняет местность от рыскающих стай гноллов и получил ранения, удерживая рубеж. Врачуя его раны исцеляющими заклинаниями и укрепляя его выносливость защитными чарами, послушник доказывает, что способен поддерживать защитников Тирисфальских лесов, и получает облачение Берил и допуск к высшим таинствам священничества."}},faq={{q="Почему священники Отрекшихся используют магию исцеления, если их сила исходит из тьмы?",a="Темный священник Берил объясняет, что хотя священники Отрекшихся черпают исключительную силу в Тени, исцеление остается необходимым. Прежде чем овладеть тьмой, послушник должен постичь магию поддержки и восстановления, чтобы защитники Отрекшихся оставались на ногах на поле боя.",al={"why do undead heal","forsaken priest healing lore","shadow vs light undead","почему нежить лечит","исцеление священников отрекшихся","тень и свет нежить"}},{q="Кто такой Страж смерти Кел?",a="Страж смерти Кел — часовой Отрекшихся, расположившийся к северу от кладбища в Брилле. Он защищает местные поселения от агрессивных стай гноллов, бродящих по лесам, и нуждается в помощи, когда получает ранения при исполнении долга.",al={"deathguard kel lore","who is deathguard kel","wounded deathguard","страж смерти кел","кто такой страж смерти кел","раненый страж смерти"}},{q="Кто выдает это задание?",a="Темный священник Берил, наставник священников в Брилле, в Тирисфальских лесах, предлагает это задание после того, как вы выполните предварительное — «Во славу Тьмы».",al={"who starts garments of darkness","garments of darkness quest giver","кто начинает одеяния тьмы","одеяния тьмы кто выдает задание"}},{q="Какое облачение вручают по завершении испытания?",a="Берил вручает сшитую на заказ мантию как знак положения и достижения: она означает, что священник освоил основные обязанности и признан собратьями.",al={"what robe do you get","garments reward priest","какую мантию дают","одеяния награда священник"}},{q="С какими угрозами сражался Страж смерти Кел?",a="Кел был ранен в бою с местными гноллами, которые населяют дикие земли Тирисфальских лесов к северу от кладбища Брилла.",al={"what attacked kel","kel gnolls","кто напал на кела","кел гноллы"}},{q="На какие темные силы намекает темный священник Берил?",a="Берил намекает на приемы Тени, свойственные только священникам Отрекшихся, — особые проявления магии Тьмы и ментального недуга, неизвестные священникам других рас.",al={"forsaken priest unique spells","darker powers hint","уникальные заклинания священников отрекшихся","намек на темные силы"}}},fp="20,264,27.460.0,23.433.0,77.263.0,22.212.0,21.158.0,52.170.0,41.134.0,50.174.0"}
P.entries["quest:5651"] = {n="Во славу Тьмы",s="«Во славу Тьмы» знаменует переход священника Отрекшихся от начальных склепов Могильника к углубленному обучению в Брилле. По поручению темного священника Дьюстена юный ученик отправляется учиться у темного священника Берил, чтобы постичь тонкий баланс между Светом и Тенью.",h="«Во славу Тьмы» знаменует переход священника Отрекшихся от начальных склепов Могильника к углубленному...",kw={"beryl","brill","deathknell","duesten","light","priest","shadow","tirisfal","берил","брилл","могильник","дьюстен","свет","священник","тень","тирисфаль"},ang={["class:Priest"]="Это задание воплощает основную философию священничества Отрекшихся: владеть и Светом, и Тенью с холодной рассудительностью, а не с религиозным трепетом.",["race:Undead"]="Путь из Могильника в Брилл — обычная первая вылазка в более широкий мир Отрекшихся, показывающая неофитам, как их народ отстраивается среди руин Лордерона."},sec={{t="Путь, проложенный в гнили",b="Хотя священники других рас чтят Свет как незапятнанный источник нравственной добродетели, Отрекшиеся подходят к вере сквозь суровую призму собственной нежизни. Как учит темный священник Дьюстен, Отрекшиеся были выкованы в скверне и брошены, как падаль. Их выживание требует понимать и Свет, и Тень без сентиментальности. «Во славу Тьмы» направляет новых учеников из замкнутого кладбища Могильника навстречу более широкой действительности, ждущей их в Тирисфальских лесах."},{t="Обучение в Брилле",b="Дорога на северо-восток от Могильника приводит юного священника через деревянный крытый мост в разрушенную деревушку Брилл. Там, в верхних покоях местного трактира, темный священник Берил ждет, чтобы испытать решимость неофита. Берил ценит честолюбие и холодную практичность выше слепой преданности и требует, чтобы священник Отрекшихся применял божественную силу как оружие и инструмент, а не как моральную опору."}},faq={{q="Для чего нужно это задание?",a="Это обряд посвящения для священников Отрекшихся, покидающих Могильник. Темный священник Дьюстен посылает вас к темному священнику Берил в Брилл, чтобы продолжить обучение и получить следующее испытание.",al={"what does this quest do","why in favor of darkness","in favor of darkness purpose","что дает это задание","зачем во славу тьмы","во славу тьмы назначение"}},{q="Почему священники Отрекшихся используют Свет, если принимают тьму?",a="Клирики Отрекшихся признают, что мир держится на равновесии Света и Тени. Хотя Свет причиняет нестерпимую боль плоти нежити, а их истоки лежат в гнили и тьме, они изучают обе силы из практичности и необходимости.",al={"why do undead priests use light","forsaken priest lore","light and shadow undead","почему нежить использует свет","священники отрекшихся предания","свет и тень нежить"}},{q="Где найти темного священника Берил?",a="Темный священник Берил находится в городке Брилл, к северо-востоку от Могильника. Он живет на втором этаже таверны «Петля висельника» в восточной части поселения.",al={"where is dark cleric beryl","beryl location","find beryl","где темный священник берил","берил местонахождение","найти берил"}},{q="Что следует за этим заданием?",a="Разговор с темным священником Берил завершает это задание и открывает следующее — «Одеяния Тьмы», в котором он проверяет, как вы умеете лечить и поддерживать союзников с помощью новообретенных умений.",al={"what comes next","next quest after in favor of darkness","in favor of darkness followup","что дальше","следующее задание после во славу тьмы","во славу тьмы продолжение"}},{q="Кто такой темный священник Дьюстен?",a="Темный священник Дьюстен — наставник священников в Могильнике. Он помогает только что пробудившимся священникам Отрекшихся осознать свое мучительное существование и овладеть духовными силами.",al={"who gives this quest","duesten lore","dark cleric duesten","кто выдает это задание","дьюстен предания","темный священник дьюстен"}},{q="Почему Берил ставит честолюбие выше веры?",a="Священники Отрекшихся считают традиционную набожную веру недостаточной после того, как их покинули силы, которым они поклонялись при жизни. Темный священник Берил ждет, что ученики будут полагаться на личное честолюбие, настойчивость и практическую силу, чтобы выжить.",al={"beryl dialogue meaning","why ambition not faith","forsaken faith","смысл слов берил","почему честолюбие а не вера","вера отрекшихся"}}},fp="20,304,20.495.0,20.409.0,34.199.0,63.260.0,34.172.0,31.192.0,27.187.0,43.232.0"}
P.entries["quest:5654"] = {n="Обессиливающий сглаз",s="«Обессиливающий сглаз» — раннее задание-обряд для юных жрецов-троллей племени Черного Копья, уже проявивших себя в Колючем Холме. Тай'джин посылает неофита на север, в Оргриммар, к Ур'кьо, чтобы тот был принят в духовный круг племени и обучен темным искусствам лоа.",h="«Обессиливающий сглаз» — раннее задание-обряд для юных жрецов-троллей племени Черного Копья, уже проявивших...",kw={"darkspear","durotar","hex of weakness","loa","orgrimmar","sen'jin village","tai'jin","ur'kyo","valley of spirits","черное копье","дуротар","обессиливающий сглаз","лоа","оргриммар","деревня сен'джин","тай'джин","ур'кьо","аллея духов"},ang={["class:Priest"]="В отличие от догматов Света или Забытой Тени, жречество троллей опирается на глубокое единение с первобытными духами, сочетая племенные сглазы с привычными заклинаниями Тени и исцеления.",["faction:Horde"]="Путь из Колючего Холма в Аллею Духов отражает включение культуры троллей в укрепленные стены растущей столицы Тралла.",["race:Troll"]="Этот обряд отмечает ваш переход от новичка в Колючем Холме к признанному жрецу племени Черного Копья, изучающему древние проклятия, передаваемые из поколения в поколение."},sec={{t="Призыв в круг",b="Начинающий жрец-тролль в Дуротаре продолжает обучение в казармах Колючего Холма под присмотром Тай'джин. Когда послушник достаточно овладевает базовым равновесием духовного единения и магии Тени, начальное наставничество заканчивается. Тай'джин направляет многообещающего священника прочь от Колючего Холма на север, через каньоны красной земли, к столице Орды, где старейшие мастера руководят более широкими магическими традициями племени."},{t="Старые обычаи в Аллее Духов",b="В Оргриммаре племя Черного Копья хранит собственное культурное убежище в Аллее Духов, отделенное от лязгающих кузниц и воинских площадок орков. Здесь, среди высоких тотемов и тенистых хижин, старейшина-жрец Ур'кьо ждет новых посвященных. Войти в его круг — значит принять древние обычаи троллей джунглей: сочетать почтение к лоа предков с мощными проклятиями и сглазами, лишающими противника сил в бою."}},faq={{q="Для чего нужно это задание?",a="Задание отражает официальное продвижение неофита в жречестве племени Черного Копья. Тай'джин посылает развивающихся жрецов-троллей с побережья Дуротара к Ур'кьо в Оргриммар, торжественно принимая их во внутренний круг духовных мастеров племени.",al={"why do this quest","hex of weakness purpose","what does hex of weakness quest do","зачем это задание","обессиливающий сглаз назначение","что дает задание обессиливающий сглаз"}},{q="Кто такая Тай'джин?",a="Тай'джин — наставница жрецов-троллей в казармах Колючего Холма в Дуротаре. Она ведет юнейших заклинателей племени Черного Копья через ранние испытания, прежде чем отправить их в столицу.",al={"who is quest giver","tai'jin lore","taijin","кто выдает задание","тай'джин предания","тайджин"}},{q="Кто такой Ур'кьо?",a="Ур'кьо — старейший наставник жрецов-троллей, живущий в Аллее Духов в Оргриммаре. Он руководит продвинутым духовным обучением, передавая жрецам племени Черного Копья племенные сглазы и глубокие обряды предков.",al={"who is ur'kyo","urkyo priest trainer","ur-kyo","кто такой ур'кьо","ур'кьо наставник жрецов","уркьо"}},{q="Где находится Аллея Духов?",a="Аллея Духов — уединенный болотистый район в западной части Оргриммара. Это главный дом троллей племени Черного Копья в орочьем городе-крепости: здесь находятся их наставники, жилища и тотемы.",al={"valley of spirits location","where is ur'kyo","where to find ur'kyo","аллея духов расположение","где ур'кьо","где найти ур'кьо"}},{q="На какой магии сосредоточено это обучение?",a="Жрецы племени Черного Копья призывают «старые обычаи», черпая силу у лоа и в древних традициях троллей джунглей. Не полагаясь только на Свет, которому следуют люди или дворфы, жрецы-тролли сочетают исцеляющую магию духов с ослабляющими проклятиями, такими как «Обессиливающий сглаз».",al={"troll priest magic","what are the old ways","hex lore","магия жрецов троллей","что такое старые обычаи","предания о сглазе"}},{q="Могут ли выполнить это задание не тролли?",a="Нет. Это задание связано с культурными традициями и особыми заклинаниями троллей племени Черного Копья. Жрецов из числа нежити направляют к их собственным наставникам и теневым учениям в Тирисфале и Подгороде.",al={"can undead do this","is this troll only","может ли нежить выполнить","только для троллей"}}},fp="15,304,23.451.0,37.478.0,34.252.0,15.202.0,14.205.0,31.208.0,47.277.0,36.213.0"}
P.entries["quest:567"] = {n="Вооружены и очень опасны!",s="Это объявление о розыске, вывешенное в Мельнице Таррен, обрекает на казнь четырех видных людей Хилсбрада. Верховный палач Дарталия объявила их опасными врагами Отрекшихся из-за конкретных убийств и засад на обозы.",h="Это объявление о розыске, вывешенное в Мельнице Таррен, обрекает на казнь четырех видных людей Хилсбрада.",kw={"apothecary eli","citizen wilkes","clerk horrace whitesteed","dangerous","deathguard toma","deathstalker fry","farmer kalaba","high executor darthalia","hillsbrad","miner hackett","tarren mill","undercity","аптекарь эли","горожанин уилкс","клерк гораций белоконь","вооружены и очень опасны","страж смерти тома","страж смерти фрай","фермер калаба","верховный палач дарталия","хилсбрад","шахтер хакетт","мельница таррен","подгород"},ang={["class:Rogue"]="Выслеживание скрывшихся вожаков на вражеской земле напоминает скрытное ремесло Стража смерти Фрая, чью гибель мстит это поручение.",["faction:Horde"]="Чтобы удержать Предгорья Хилсбрада, нужно сломить самых яростных вожаков человеческого ополчения и обеспечить безопасность передвижений Орды по региону.",["race:Undead"]="Мстить за павших Стражей смерти, аптекарей и Стражей смерти — повод для мрачной гордости любого верного слуги Темной Госпожи."},sec={{t="Дело возмездия",b="Линия фронта в Предгорьях Хилсбрада жестока и лична. Для верховного палача Дарталии и гарнизона Отрекшихся в Мельнице Таррен обычные жители Хилсбрада стали смертоносными бойцами. В объявлении названы четверо, чье сопротивление стоило жизни Отрекшимся и ценных грузов из Подгорода."},{t="Цели Мельницы Таррен",b="В объявлении названы: клерк Гораций Белоконь — за убийство Стража смерти Томы, горожанин Уилкс — за убийство аптекаря Эли, шахтер Хакетт — за убийство Стража смерти Фрая и фермер Калаба — за срыв обозов с припасами из Подгорода. Каждая цель действует в своем очаге сопротивления Хилсбрада и остается неуловимой в хаосе большого конфликта."}},faq={{q="Кто вывесил объявление «Вооружены и очень опасны!»?",a="Верховный палач Дарталия, командующая силами Отрекшихся в Мельнице Таррен, назначила награду за голову четырех видных людей Хилсбрада.",al={"who posted dangerous","who gave dangerous quest","darthalia bounty","кто вывесил объявление","кто выдал задание вооружены и очень опасны","награда дарталии"}},{q="Почему разыскивают именно этих людей?",a="Каждый из них нанес удар по Отрекшимся: клерк Гораций Белоконь убил Стража смерти Тому, горожанин Уилкс убил аптекаря Эли, шахтер Хакетт сразил Стража смерти Фрая, а фермер Калаба подстерег важные припасы, посланные из Подгорода.",al={"why are they dangerous","what did they do","hillsbrad targets crime","почему они опасны","что они сделали","цели хилсбрада преступления"}},{q="Где находятся цели?",a="Все четверо укрылись в поселениях и рабочих местах людей в Предгорьях Хилсбрада, прячась среди горожан, на фермах и в шахтах.",al={"where to find targets","dangerous quest locations","hackett location","где найти цели","места задания вооружены и очень опасны","где хакетт"}},{q="Какова стратегическая цель этого поручения?",a="Помимо простой мести, устранение этих вожаков подрывает местное сопротивление людей и защищает патрули и линии снабжения Отрекшихся между Мельницей Таррен и Подгородом.",al={"why kill them","hillsbrad bounty goal","tarren mill strategy","зачем их убивать","цель награды хилсбрада","стратегия мельницы таррен"}},{q="Связано ли это с Битвой за Хилсбрад?",a="Да. Цели этого задания живут на тех самых фермах, в шахтах и центрах городов, которые силы Отрекшихся штурмуют во время наступления в рамках Битвы за Хилсбрад.",al={"battle of hillsbrad connection","darthalia battle","hillsbrad offensive","связь с битвой за хилсбрад","дарталия битва","наступление на хилсбрад"}},{q="Кому сдают задание после их гибели?",a="Доказательства их устранения передают прямо верховному палачу Дарталии в Мельнице Таррен.",al={"who completes dangerous","dangerous turn in","darthalia turn in","кто завершает вооружены и очень опасны","сдача задания","дарталия сдать"}}},fp="10,235,23.338.0,22.381.0,33.142.0,37.241.0,30.144.0,47.175.0,45.160.0,44.91.0"}
P.entries["quest:5672"] = {n="Благодать Элуны",s="Благодать Элуны — обряд признания, который предлагают преданным жрецам из числа ночных эльфов в Дарнассе. Когда жрецы доказывают свою веру и дисциплину в первых странствиях, их призывают к жрице Алатее, чтобы они получили более глубокие наставления в божественных тайнах Богини Луны.",h="Благодать Элуны — обряд признания, который предлагают преданным жрецам из числа ночных эльфов в Дарнассе.",kw={"alathea","darnassus","elune","elune's grace","priest quest","priestess alathea","sisterhood of elune","temple of the moon","алатея","дарнасс","элуна","благодать элуны","задание жреца","жрица алатея","сестринство элуны","храм луны"},ang={["class:Priest"]="Этот обряд знаменует разделение между верой кальдораев и учениями людского и дворфийского духовенства, основанными на Свете, и прочно связывает ремесло жреца с защитой Элуны.",["race:NightElf"]="Для кальдораев Благодать Элуны — непрерывная связь с древними традициями, сохраненными в Сестринстве Элуны."},sec={{t="Священное призвание",b="В Храме Луны в Дарнассе Сестринство Элуны ведет молодых послушниц и послушников от первых молитв к владению лунной магией. Ночные эльфы смотрят на Свет не так, как люди или дворфы: их вера неразрывно связана с Матерью Луной, Элуной. Когда начинающий жрец достигает важного рубежа в своей преданности, старшие наставники замечают это и признают ученика готовым принять большую божественную силу."},{t="Благословения Богини Луны",b="Жрица Алатея передает этот призыв от имени Сестринства. Она признает, что преданность послушника возвысила его над обычной паствой и открыла ему доступ к традициям, сохраненным на протяжении тысячелетий. Принятие обряда скрепляет связь жреца с Элуной и открывает особые защитные покровы и лунные воззвания, свойственные вере кальдораев."}},faq={{q="Для чего нужно это задание?",a="Задание отмечает духовный рубеж для жрецов из числа ночных эльфов. Оно призывает послушника обратно в Дарнасс, чтобы жрица Алатея признала его рост и посвятила в высшие расовые учения Сестринства Элуны.",al={"why do elunes grace","what does elunes grace do","purpose of quest","зачем благодать элуны","что делает благодать элуны","цель задания"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — уважаемая наставница Сестринства Элуны, живущая в Дарнассе. Она присматривает за растущими жрецами-кальдораями и помогает им углублять единение с Богиней Луны.",al={"alathea role","who gives quest","who is alathea","роль алатеи","кто выдает задание","кто такая алатея"}},{q="Почему этот дар доступен только ночным эльфам?",a="В отличие от жрецов-людей и дворфов, черпающих силу из Света, жрецы-ночные эльфы напрямую почитают Элуну. Воззвания сестринства, такие как Благодать Элуны, отражают лунную защиту и оборонительные чары, которые кальдораи развивали тысячи лет.",al={"why only night elves","racial ability lore","elune priest difference","почему только ночные эльфы","расовая способность предания","отличие жрецов элуны"}},{q="Где проходит эта церемония?",a="На призыв отвечают в Дарнассе, в Храме Луны, где собирается и обучает жречество города.",al={"where is alathea","quest location","darnassus temple","где алатея","место задания","храм дарнасса"}},{q="Получают ли другие жрецы Альянса подобное призвание?",a="Да. Каждая культура подходит к жречеству по-своему: люди и дворфы изучают принципы Света у своих наставников в Штормграде и Стальгорне и получают расовые умения, отличные от лунной магии ночных эльфов.",al={"do humans get this","dwarf priest equivalent","other races","получают ли люди","жрец дворф аналог","другие расы"}},{q="О каком состоянии преданности говорит Алатея?",a="Алатея говорит о духовной стойкости и зрелости, обретенных в испытаниях большого мира. Выживание, дисциплина и неизменная верность добродетелям Элуны доказывают, что послушник может безопасно направлять более могущественные лунные благословения.",al={"attained a state","alathea dialogue","what devotion","достиг состояния","диалог алатеи","какая преданность"}}},fp="13,277,16.450.0,29.361.0,34.238.0,25.192.0,41.267.0,36.125.0,52.248.0,47.231.0"}
P.entries["quest:5674"] = {n="Благодать Элуны",s="Благодать Элуны — обряд посвящения для растущих жрецов из числа ночных эльфов, знак их готовности владеть божественными дарами, присущими их народу. Из отдаленных поселений вроде Доланаара кандидатов направляют в священный Храм Луны в Дарнассе, где они предстают перед жрицей Алатеей и доказывают свою преданность.",h="Благодать Элуны — обряд посвящения для растущих жрецов из числа ночных эльфов, знак их готовности владеть...",kw={"darnassus","dolanaar","elune's grace","laurna morninglight","priestess alathea","sisterhood of elune","teldrassil","temple of the moon","дарнасс","доланаар","благодать элуны","лорна утренний свет","жрица алатея","сестринство элуны","тельдрассил","храм луны"},ang={["class:Priest"]="Этот обряд знаменует важный переход для жрецов-ночных эльфов: их сущность опирается на особую небесную магию Сестринства Элуны, а не на общие священные практики.",["race:NightElf"]="Паломничество в Храм Луны подтверждает центральную роль поклонения Элуне в обществе кальдораев и призывает далеких послушников домой, в сердце Дарнасса."},sec={{t="Священный рубеж",b="Путь жреца в Сестринстве Элуны не сводится к освоению обычных молитв исцеления и кары. По мере роста опыта послушники достигают порога, за которым их признают готовыми принять благословения, доступные только кальдораям. Местные наставницы, такие как Лорна Утренний Свет в Доланааре, не вправе передавать эти глубокие умения и отправляют многообещающих учеников обратно в культурное и духовное сердце ордена."},{t="Прием в храме",b="Задание направляет посвящаемых через Тельдрассил в величественный Храм Луны в Дарнассе. Там, под взором верховного жречества, жрица Алатея оценивает, действительно ли проситель готов принять защитный покров богини. Изучение Благодати Элуны символизирует истинную зрелость в жречестве и соединяет нераскрытый потенциал с официальным служением богине."}},faq={{q="Для чего нужно это задание?",a="Это задание отправляет обратно в Дарнасс жрецов-ночных эльфов, набравшихся достаточного практического опыта. Оно служит обрядом перехода: жрецов направляют к жрице Алатее в Храм Луны, чтобы испытать их и обучить защитному искусству, известному как Благодать Элуны.",al={"what does this quest do","elunes grace quest purpose","why visit alathea","что делает это задание","цель задания благодать элуны","зачем идти к алатее"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — высокопоставленная наставница жрецов, живущая в Храме Луны в Дарнассе. Она руководит официальным обучением и продвижением послушников-ночных эльфов и следит, чтобы у них была духовная сосредоточенность, необходимая для сложных расовых молитв.",al={"priestess alathea lore","who is alathea","alathea darnassus","предания о жрице алатее","кто такая алатея","алатея дарнасс"}},{q="Почему местные наставники не могут обучить этому умению?",a="Наставницы в отдаленных поселениях, как Лорна Утренний Свет, обучают новичков основам, но священные благословения, присущие только кальдораям, сестринство доверяет лишь при официальном посвящении. Чтобы пройти проверку и получить эти глубокие дары, послушники должны явиться в главное святилище ордена в Дарнассе.",al={"why not train in dolanaar","why go to darnassus","почему не учиться в доланааре","зачем идти в дарнасс","почему не в доланааре","почему в дарнасс"}},{q="Что на самом деле означает Благодать Элуны в вере кальдораев?",a="Благодать Элуны — прямая защитная опека Богини Луны. Сотканная молитвой, она ослабляет силу входящих ударов и отражает оберегающее присутствие Элуны над ее верными защитниками, когда рядом опасность.",al={"what is elunes grace","elunes grace lore","что такое благодать элуны","предания благодать элуны"}},{q="Могут ли жрецы других рас получить это благословение?",a="Нет. Искусство Благодати Элуны строго связано с древней верой и поклонением кальдораев. Ему обучают только жрецов-ночных эльфов, напрямую общающихся с Богиней Луны.",al={"can humans learn elunes grace","is elunes grace night elf only","могут ли люди выучить благодать элуны","только ли для ночных эльфов"}},{q="Где начинается и заканчивается этот путь?",a="Призыв передает наставница Лорна Утренний Свет в поселении Доланаар на Тельдрассиле, отправляя послушника на запад, в Храм Луны в Дарнассе.",al={"quest start and end","where to go","начало и конец задания","куда идти"}}},fp="13,317,18.457.0,22.402.0,34.257.0,25.261.0,43.317.0,61.239.0,49.197.0,38.172.0"}
P.entries["quest:5676"] = {n="Волшебное искажение",s="Волшебное искажение — обряд посвящения для жрецов Альянса в Штормграде, который проводит верховная жрица Лорена в Соборе Света. Достигнув более глубокого единения с верой, жрец обучается защитным покровам против враждебных владеющих тайной магией. Это практическая защита Церкви от необузданного колдовства и мятежных заклинателей.",h="Волшебное искажение — обряд посвящения для жрецов Альянса в Штормграде, который проводит верховная жрица...",kw={"anti-magic","arcane feedback","cathedral of light","high priestess laurena","holy light","human priest","laurena","priest","stormwind","антимагия","волшебное искажение","собор света","верховная жрица лорена","свет","жрец-человек","лорена","жрец","штормград"},ang={["class:Priest"]="Этот обряд расширяет тактический арсенал жреца и дает средства подавлять противников, использующих ману, когда божественная дипломатия бессильна.",["faction:Alliance"]="По мере роста напряженности с мятежными кабалами и темными практиками на Восточных королевствах Альянс полагается на своих жрецов в нейтрализации магических угроз.",["race:Human"]="Жрецы-люди в Штормграде проходят особую доктринальную подготовку Собора Света, сочетающую праведную преданность со строгой дисциплиной в борьбе с магией."},sec={{t="Щит против тайной магии",b="В залитых солнцем кельях Собора Света верховная жрица Лорена напоминает послушникам об извечной опасности — тайной магии. Свет приносит исцеление, тепло и божественный порядок, а необузданные магические силы переменчивы и нередко влекут порчу или катастрофу. Чтобы выстоять против чернокнижников, мятежных чародеев и магических тварей, преданных жрецов учат, что вера порой должна становиться действенным оберегом от окружающих заклинаний."},{t="Обратить поток вспять",b="Волшебное искажение учит разум и дух наказывать враждебных заклинателей за направление силы против верных. Эта дисциплина не просто отражает магические залпы, а возвращает тайную энергию к источнику, сжигая запасы маны заклинателя и причиняя мучения. Лорена передает это заклинание жрецам-людям, выходящим в большой мир, чтобы посланники Собора никогда не странствовали беззащитными перед колдовством."}},faq={{q="Для чего нужно задание «Волшебное искажение»?",a="Задание отражает растущее мастерство жреца-человека под руководством Церкви Священного Света. Верховная жрица Лорена обучает его особому защитному обряду, позволяющему противостоять враждебным заклинателям и отвечать им ударом.",al={"arcane feedback quest","what is arcane feedback","why do this quest","задание волшебное искажение","что такое волшебное искажение","зачем выполнять задание"}},{q="Кто дает это задание и где ее найти?",a="Задание дает верховная жрица Лорена. Она находится в Соборе Света — великом духовном центре Альянса на Соборной площади Штормграда.",al={"who gives arcane feedback","arcane feedback quest giver","where is laurena","кто дает волшебное искажение","выдающий задание волшебное искажение","где лорена"}},{q="Почему Церковь Священного Света считает тайную магию врагом?",a="Церковь учит полагаться на нравственную ясность, преданность и божественную благодать. Тайная магия, напротив, черпает из переменчивых, затягивающих сил, которые исторически привлекали вторжения демонов и приносили разруху по всему Азероту, поэтому жрецы-люди видят в неукрощенном колдовстве постоянную угрозу.",al={"why do priests hate arcane","church vs arcane","is arcane bad","почему жрецы ненавидят тайную магию","церковь против тайной магии","плоха ли тайная магия"}},{q="Как в общих чертах действует защита «Волшебное искажение»?",a="Заклинание создает вокруг жреца ответную ауру. Когда враждебное заклинание попадает в покров, входящая магия вызывает отдачу, которая истощает запасы маны нападающего и наносит ему физический шок.",al={"how does arcane feedback work","arcane feedback lore","как работает волшебное искажение","предания волшебное искажение"}},{q="Может ли любой жрец научиться этому у Лорены?",a="В Штормграде эта дисциплина рассчитана на жрецов-людей как часть их церковных традиций и отражает боевые учения, которые преподают в Соборе Света.",al={"can dwarves learn arcane feedback","who can get arcane feedback","priest racial spell","могут ли дворфы выучить волшебное искажение","кто может получить волшебное искажение","расовое заклинание жреца"}},{q="Какого уровня ожидают от послушника, проходящего это обучение?",a="Жрецов призывают освоить эту технику примерно на двадцатом круге опыта — в пору, когда послушники оставляют обычные церковные обязанности и отправляются в опасные пограничные земли.",al={"what level for arcane feedback","arcane feedback level requirement","какой уровень для волшебного искажения","требования к уровню волшебное искажение"}}},fp="15,357,27.450.0,23.448.0,49.239.0,49.175.0,68.296.0,52.222.0,39.202.0,63.185.0"}
P.entries["quest:5677"] = {n="Волшебное искажение",s="«Волшебное искажение» — задание жрецов, которое выдает верховный жрец Рохан в Стальгорне жрецам-людям, посетившим Каз Модан. Рохан направляет начинающего жреца домой, в Собор Света в Штормграде, чтобы тот получил наставления, подходящие именно традициям людей. Это важный этап развития, когда молодые ученики начинают осваивать расовые проявления своей веры.",h="«Волшебное искажение» — задание жрецов, которое выдает верховный жрец Рохан в Стальгорне жрецам-людям...",kw={"arcane feedback","cathedral of light","high priest rohan","high priestess laurena","ironforge","mystic ward","priest quest","stormwind","волшебное искажение","собор света","верховный жрец рохан","верховная жрица лорена","стальгорн","мистический квартал","задание жреца","штормград"},ang={["class:Priest"]="Это задание — важная веха: жрецы узнают, что разные расы направляют и выражают Свет через особые культурные традиции.",["race:Dwarf"]="Наставники-дворфы, такие как верховный жрец Рохан, чтят союз с людьми, но хранят особые обряды Каз Модана внутри собственного народа.",["race:Human"]="Жрецов-людей мягко отзывают из дворфийских святилищ обратно в Штормград, чтобы они укрепились в священных путях Собора Света."},sec={{t="Мягкое напоминание",b="Когда жрец-человек ищет высшего духовного наставничества в залах Мистического квартала, верховный жрец Рохан встречает его с почтением, но обозначает границу. Хотя жрецы-дворфы и жрецы-люди одинаково преданы Свету, каждая цивилизация развивает собственные обряды, дисциплины и защитные молитвы. Вместо того чтобы раскрывать тайны Стальгорна, Рохан отправляет людей-священников к культурным корням в Элвиннский лес, чтобы они освоили наследие своего народа."},{t="Возвращение в Собор",b="По возвращении в Штормград послушник докладывает верховной жрице Лорене в величественном Соборе Света. Лорена рада, что наставления Рохана достигли путника, и приветствует его как раз тогда, когда его зарождающиеся силы начинают раскрываться. Это возвращение открывает путь к более глубокому посвящению в духовные практики Королевства Штормград и готовит служителей к тому, чтобы использовать Свет против растущих угроз, окружающих государство."}},faq={{q="Почему верховный жрец Рохан отказывается обучать жрецов-людей?",a="Верховный жрец Рохан уважает жрецов-людей, но у дворфийского духовенства есть особые обряды и благословения, передаваемые по их культурной линии. Он считает, что жрецы-люди должны изучать особые, специальные приемы, которые хранят их собственные наставники в Штормграде.",al={"why send to stormwind","why rohan won't train","dwarf priest won't train me","почему отправляют в штормград","почему рохан не обучает","жрец-дворф не хочет обучать меня"}},{q="Кто такая верховная жрица Лорена?",a="Верховная жрица Лорена — видная духовная предводительница и наставница в Соборе Света в Штормграде. Она следит за ростом многообещающих жрецов-людей, направляя их промежуточное обучение и обряды.",al={"high priestess laurena","who is laurena","cathedral priest trainer","верховная жрица лорена","кто такая лорена","наставник жрецов в соборе"}},{q="Где найти верховного жреца Рохана?",a="Верховный жрец Рохан находится в Зале Тайн в Мистическом квартале, в великом горном городе дворфов Стальгорне.",al={"rohan location","where is high priest rohan","find rohan","где рохан","где верховный жрец рохан","найти рохана"}},{q="В чем смысл этого задания?",a="Это задание-указатель: оно направляет жрецов-людей среднего уровня из земель дворфов обратно в главный расовый центр обучения — Собор Света, где они смогут изучать духовные приемы, свойственные их расе.",al={"arcane feedback quest purpose","why do this quest","what does this quest do","цель задания волшебное искажение","зачем это задание","что дает это задание"}}},fp="15,380,20.477.0,23.446.0,57.267.0,30.223.0,37.131.0,34.219.0"}
P.entries["quest:5678"] = {n="Волшебное искажение",s="«Волшебное искажение» — задание жрецов Альянса, которое направляет жрецов-людей, обучающихся в Дарнассе, домой, в Штормград. Жрица Алатея из Храма Луны отправляет их в путь, что подчеркивает глубокий культурный разрыв в отношении к магии между ночными эльфами и Восточными королевствами. По возвращении в Собор Света верховная жрица Лорена готовит послушника к более глубокому богословскому обучению.",h="«Волшебное искажение» — задание жрецов Альянса, которое направляет жрецов-людей, обучающихся в Дарнассе...",kw={"arcane feedback","cathedral of light","darnassus","high priestess laurena","holy light","priest quest","priestess alathea","stormwind","волшебное искажение","собор света","дарнасс","верховная жрица лорена","свет","задание жреца","жрица алатея","штормград"},ang={["class:Priest"]="Это паломничество — важный порог на вашем духовном пути, напоминающий о резком философском разрыве между сестринством Элуны и догмами Света.",["race:Human"]="Возвращение в Штормград приводит вас домой, в сердце Церкви Священного Света, вдали от замкнутого и скептичного жречества кальдорай.",["race:NightElf"]="Откровенная настороженность жрицы Алатеи отражает извечный страх кальдорай, что вмешательство молодых смертных рас в тайную магию приведет к новой катастрофе."},sec={{t="Неохотный вызов",b="Жрица Алатея опекает приезжих жрецов в тихих залах Храма Луны в Дарнассе. Хотя она признает официальный союз между кальдорай и людьми Штормграда, она глубоко сомневается в магических и духовных практиках людей. Общество ночных эльфов считает тайную силу изначально нестабильной и опасной — таково наследие десяти тысячелетий скорби после Войны Древних. Даже божественные обряды людей, стирающие грань между сияющей верой и тайной механикой, заметно тревожат жречество ночных эльфов."},{t="Возвращение в Собор",b="Несмотря на колебания, Алатея чтит узы между расами Альянса и отпускает послушника откликнуться на зов Собора Света. Верховная жрица Лорена разослала гонцов за море, чтобы собрать растущих жрецов-людей для высшего обучения. Вернувшись в Штормград, послушник покидает залитые луной рощи Элуны ради величественных каменных святилищ и золотого сияния Света."}},faq={{q="Почему жрица Алатея хочет, чтобы я покинул Дарнасс?",a="Жрица Алатея выполняет вызов, присланный вашим начальством в Штормграде, но ей также не по себе от богословских практик людей. Она открыто признает свое глубокое недоверие к тайной магии, божественной или нет, и потому охотно отправляет послушников-людей в их собственные великие соборы.",al={"why alathea sends me away","why return to stormwind","alathea arcane feedback","почему алатея отсылает меня","зачем возвращаться в штормград","алатея волшебное искажение"}},{q="Почему ночные эльфы не доверяют жреческой магии людей?",a="Культура ночных эльфов во многом определена катастрофическим Расколом, вызванным безрассудным тайным колдовством десять тысяч лет назад. Поклонение кальдорай сосредоточено на Элуне, и их жрицы с глубоким подозрением относятся к любой традиции, граничащей с тайными манипуляциями или включающей их, даже если ее исповедуют союзники по Свету.",al={"why night elves hate arcane","night elf arcane distrust","elune vs holy light","почему ночные эльфы не любят тайную магию","недоверие ночных эльфов к тайной магии","элуна и свет"}},{q="Кто такая верховная жрица Лорена?",a="Верховная жрица Лорена — видная духовная предводительница Собора Света в Штормграде. Она следит за обучением и продвижением начинающих жрецов-людей, направляя их понимание Света по мере роста их силы.",al={"who is laurena","high priestess laurena stormwind","кто такая лорена","верховная жрица лорена штормград"}},{q="К чему ведет это задание?",a="Доклад верховной жрице Лорене означает переход к более высокому жреческому обучению людей в Штормграде и открывает дисциплину и благословения, свойственные людям, приверженным Свету.",al={"what comes after arcane feedback","arcane feedback reward lore","что после волшебного искажения","награда за волшебное искажение"}}},fp="15,405,19.552.0,23.430.0,54.311.0,49.344.0,30.240.0,31.200.0"}
P.entries["quest:5679"] = {n="Всепожирающая чума",s="«Всепожирающая чума» — обряд обучения для жрецов Отрекшихся, доказавших преданность магии Тьмы. Жрица Эльталисте в Подгороде дает это знание, знаменуя посвящение послушника в одно из самых страшных проклятий жречества нежити.",h="«Всепожирающая чума» — обряд обучения для жрецов Отрекшихся, доказавших преданность магии Тьмы.",kw={"aelthalyste","devouring plague","forsaken","lordaeron","priest","shadow","undercity","war quarter","эльталисте","всепожирающая чума","отрекшиеся","лордерон","жрец","тьма","подгород","военный квартал"},ang={["class:Priest"]="Этот обряд дает жрецам Отрекшихся одно из самых узнаваемых расовых заклинаний, напрямую связывая их выживание с порчей, которую они насылают на врагов.",["faction:Horde"]="Если другие союзники Орды полагаются на духов предков или равновесие стихий, то Отрекшиеся приносят в общий арсенал фракции беспощадные проклятия, подобные болезням.",["race:Undead"]="Чумное колдовство Тьмы отражает отход Отрекшихся от традиционного лордеронского богослужения после Третьей войны."},sec={{t="Проклятие Тьмы",b="В мрачных кельях Военного квартала жрица Эльталисте наставляет Отрекшихся в суровых искусствах Тьмы. Если живые жрецы других рас взывают за силой к Свету или духам предков, то Отрекшиеся выработали собственные духовные учения. Всепожирающая чума воплощает их философию: наносить врагам страдания, а похищенную жизненную силу вливать в собственные разлагающиеся тела."},{t="Испытание мастерства",b="Эльталисте не отдает знание о чуме легко. Это заклинание считается оружием сильной злобы, призванным переломить ход борьбы против Плети и Алого ордена. Передавая заклинание, Эльталисте велит ученикам оттачивать власть над ним неустанной практикой и предупреждает, что тех, кто стремится овладеть темными искусствами, ждут куда более суровые испытания."}},faq={{q="В чем смысл этого задания?",a="Задание служит формальным уроком для жрецов Отрекшихся, достигших опытного уровня. Поговорив с жрицей Эльталисте, жрец узнает, как накладывать Всепожирающую чуму — характерную порчу Тьмы, свойственную только нежити.",al={"why do devouring plague","what does devouring plague quest do","devouring plague purpose","зачем всепожирающая чума","что дает задание всепожирающая чума","цель всепожирающей чумы"}},{q="Кто такая жрица Эльталисте?",a="Жрица Эльталисте — наставница жрецов Отрекшихся в Военном квартале Подгорода. Она следит за развитием начинающих заклинателей Тьмы и добивается, чтобы они эффективно применяли свои разрушительные дары на благо Отрекшихся.",al={"who is aelthalyste","aelthalyste lore","aelthalyste undercity","кто такая эльталисте","эльталисте предания","эльталисте подгород"}},{q="Могут ли жрецы других рас изучить Всепожирающую чуму у Эльталисте?",a="Нет. Всепожирающая чума — тайное заклинание, доступное только жрецам Отрекшихся. Тролли, люди, ночные эльфы и дворфы общаются с иными духовными силами и вместо этого обладают собственными расовыми учениями.",al={"can trolls learn devouring plague","is devouring plague undead only","other races devouring plague","могут ли тролли выучить всепожирающую чуму","всепожирающая чума только для нежити","другие расы всепожирающая чума"}},{q="Где сдать это задание?",a="Жрицу Эльталисте можно найти в Военном квартале Подгорода среди наставников и жрецов Отрекшихся.",al={"aelthalyste location","where is devouring plague quest","undercity priest trainer location","где эльталисте","где задание всепожирающая чума","наставник жрецов подгород"}},{q="Почему жрецы Отрекшихся специализируются на чуме и магии Тьмы?",a="Из-за своего посмертного состояния жрецы Отрекшихся терпят сильную физическую боль, когда направляют Свет. Поэтому многие обращаются к учениям Тьмы, используя порчу, проклятия и похищенную жизненную силу, чтобы выживать и воевать.",al={"why forsaken shadow priests","lore behind undead priests","forsaken priest magic","почему жрецы отрекшихся тьма","предания о жрецах нежити","магия жрецов отрекшихся"}},{q="О каких испытаниях говорит Эльталисте?",a="Эльталисте предупреждает, что по мере роста силы жреца испытания, ожидающие его в Лордероне, будут суровее. Владение темной магией привлекает опасное внимание и смертельных врагов и требует полного мастерства над каждым проклятием в арсенале послушника.",al={"tests later meaning","future tests aelthalyste","what tests","какие испытания","будущие испытания эльталисте","что за испытания"}}},fp="16,281,21.464.0,17.391.0,34.237.0,29.233.0,67.210.0,30.140.0,62.242.0,39.236.0"}
P.entries["quest:57"] = {n="Ночной Дозор",s="По прямому поручению командира Алтеи Чернодрев искатели приключений отправляются в захваченные нежитью курганы Сумеречного леса, чтобы сократить число неупокоенных мертвецов. Эта продолжающаяся кампания направлена против скелетов-чудовищ, выбирающихся с Безмятежного кладбища и из Вороньего Холма. Отражение скелетной напасти необходимо, чтобы хрупкое убежище — Темнолесье — не пало окончательно во тьму.",h="По прямому поручению командира Алтеи Чернодрев искатели приключений отправляются в захваченные нежитью...",kw={"althea ebonlocke","darkshire","duskwood","night watch","raven hill","skeletal fiend","skeletal horror","tranquil gardens","алтея чернодрев","темнолесье","сумеречный лес","ночной дозор","вороний холм","скелет-чудовище","скелетный ужас","безмятежное кладбище"},ang={["class:Paladin"]="Для Серебряной Длани и рыцарей Света столкновение с оскверненными мертвецами на Безмятежном кладбище — священный долг: очистить поруганные места упокоения.",["class:Priest"]="Жрецы, ступающие по оскверненной земле Вороньего Холма, видят неприкрытое надругательство над погребальными обычаями и силой веры приносят тихий покой измученным душам.",["faction:Alliance"]="Темнолесье — хрупкая юго-восточная граница Альянса в южной части Восточных королевств. Помощь Ночному Дозору помогает городу оставаться пригодным плацдармом, а не окончательно пасть в руины.",["race:Human"]="Многие скелеты, встающие из земли Сумеречного леса, — предки живых жителей Штормграда и Темнолесья, поэтому для защитников-людей эта битва глубоко личная."},sec={{t="Мертвые не знают покоя",b="Трагическое превращение Сумеречного леса из зеленого края, некогда называвшегося Светлой рощей, в окутанные туманом сумерки сделало его кладбища неестественно беспокойными. Командир Алтея Чернодрев, возглавляющая добровольческое ополчение Темнолесья — Ночной Дозор, ведет бесконечную осаду. Без помощи Штормграда ее силы растянуты опасно тонко. Сообщения об оживших скелетах и ужасах, поднимающихся из земли, грозят захлестнуть восточные поселения, и ополчение вынуждено набирать любых крепких путников, готовых войти в мертвые земли."},{t="Оскверненная земля",b="Кампания ведет новобранцев к двум очагам некромантических волнений: Безмятежному кладбищу к югу от города и обширным заросшим просторам кладбища Вороньего Холма далеко на западе. Скелеты выбираются из забытых гробниц и неглубоких придорожных могил, оживленные темной магией, застрявшей в сумрачном лесу. Уничтожение этих тварей дает осажденным жителям Темнолесья жизненно важную передышку, хотя это нескончаемая борьба с укоренившимся злом."}},faq={{q="Почему Ночной Дозор полагается на путников, а не на стражу Штормграда?",a="Штормград почти бросил Сумеречный лес на произвол судьбы, оставив оборону региона командиру Алтее Чернодрев и ее местному добровольческому ополчению. Из-за внутренних политических раздоров и пропавшего короля столица не присылает подкреплений гарнизона, и Ночному Дозору приходится нанимать проходящих мимо искателей приключений.",al={"why no stormwind help","where is stormwind army","why darkshire alone","почему нет помощи штормграда","где армия штормграда","почему темнолесье одно"}},{q="Откуда берутся скелеты?",a="Скелеты-чудовища выбираются из освященной земли Безмятежного кладбища и обширного кладбища Вороньего Холма. Темные магические силы, пронизывающие лес, потревожили захоронения многовековой давности и подняли древние останки как безмозглых свирепых стражей.",al={"skeletons duskwood origin","why are there skeletons","undead source duskwood","скелеты сумеречный лес","откуда скелеты","источник нежити сумеречный лес"}},{q="Кто возглавляет Ночной Дозор?",a="Ночным Дозором командует командир Алтея Чернодрев. Она родственница правителя Темнолесья, лорда Элло Чернодрева, лично руководит обороной города и координирует действия против нежити и чудовищ Сумеречного леса.",al={"night watch leader","who is althea ebonlocke","commander ebonlocke","глава ночного дозора","кто такая алтея чернодрев","командир чернодрев"}},{q="Чем отличаются Безмятежное кладбище и Вороний Холм?",a="Безмятежное кладбище лежит сразу к югу от Темнолесья и представляет собой непосредственную локальную угрозу городу. Кладбище Вороньего Холма, расположенное через лес далеко на западе, — огромное место захоронений, ставшее средоточием нежити Сумеречного леса.",al={"tranquil gardens vs raven hill","which graveyard is better","graveyard locations duskwood","безмятежное кладбище или вороний холм","какое кладбище лучше","расположение кладбищ сумеречный лес"}},{q="Что будет после уничтожения этих скелетов?",a="Уничтожение скелетов-чудовищ — лишь один этап кампании Алтеи. Ночной Дозор постоянно следит за растущими угрозами в лесу — от вурдалаков и скелетов до более опасной нежити и зловещих некромантов, направляющих ее в глубине Сумеречного леса.",al={"what next night watch","night watch questline","after night watch 2","что дальше ночной дозор","цепочка заданий ночного дозора","после ночного дозора 2"}},{q="Почему Темнолесье постоянно в опасности?",a="Некогда мирная провинция Королевства Штормград под названием Светлая роща, Сумеречный лес был поглощен магическими сумерками и поражен темными проклятиями. Теперь леса наводнены одичавшими воргенами, прожорливыми пауками и неупокоенной нежитью, и Темнолесье осталось последним оплотом живых людей в этой местности.",al={"why duskwood dangerous","darkshire danger","what cursed duskwood","почему сумеречный лес опасен","опасность темнолесья","что прокляло сумеречный лес"}}},fp="15,389,20.537.0,12.482.0,73.312.0,36.275.0,26.240.0,63.272.0,43.279.0,36.302.0"}
P.entries["quest:5713"] = {n="Каждый выстрел – в цель",s="Неся срочное сообщение в Аубердин, Часовой Айнаша попала в засаду и была отравлена враждебным фурболгом по имени Марош Бесчестный и его отрядом следопытов. Обездвиженная при приготовлении противоядия, она рассчитывает на путников поблизости, которые отобьют нападающих, чтобы она выжила и выполнила свой долг.",h="Неся срочное сообщение в Аубердин, Часовой Айнаша попала в засаду и была отравлена враждебным фурболгом по...",kw={"ambush","antidote","aynasha","darkshore","furbolg","lor'danel","maestra's post","marosh","onaeya","sentinel","засада","противоядие","айнаша","темные берега","фурболг","лор'данель","застава мейстры","марош","ойнея","часовой"},ang={["class:Hunter"]="Айнаша показывает непоколебимую решимость стрелка: она продолжает посылать меткие выстрелы в заросли, даже поддаваясь сильному яду.",["faction:Alliance"]="Если держать лесные тропы свободными от агрессивных стай фурболгов, путь между Ясеневым лесом и оплотами Альянса на севере остается безопасным.",["race:NightElf"]="Защищая Айнашу, вы сохраняете и сестру Часовых, и важные сообщения, которые передаются между заставами Ясеневого леса и севера Темных берегов."},sec={{t="Засада на лесной дороге",b="Тропы северного Калимдора стали опасными: порча все глубже укореняется среди диких обитателей. Часовой Айнаша шла в Аубердин с важными донесениями, когда ее перехватили враждебные фурболги. Под началом Мароша Бесчестного нападавшие ударили быстро и ввели изнуряющий яд, из-за которого разведчица едва держалась на ногах и не могла продолжить путь пешком."},{t="Удержать рубеж",b="Хотя Айнаша умело обращается с природными снадобьями, приготовить и принять противоядие под сенью леса требует времени, которого у нее нет, пока за ней охота. Пока следопыты Мароша приближаются, Айнаше приходится полагаться на путников, охраняющих ее позицию. Несмотря на слабеющие силы, она поднимает лук и осыпает заросли огнем прикрытия, решив, что ни она, ни ее донесение не погибнут в глуши."},{t="Доложить на Заставу Мейстры",b="Когда нападение отбито, а Марош убит, противоядие возвращает Айнаше достаточно сил, чтобы завершить путь в Аубердин. Чтобы застава на юге, в Ясеневом лесу, узнала об агрессивных действиях фурболгов, угрожающих региональным путям снабжения, она просит своих защитников доложить напрямую Часовому Ойнее на Заставе Мейстры."}},faq={{q="Кто такая Часовой Айнаша?",a="Часовой Айнаша — разведчица из ночных эльфов, доставляющая важные сообщения через границы Темных берегов и Ясеневого леса. Искусная лучница, знаток выживания в лесу, она едва не погибла от неожиданной засады с ядом во время службы.",al={"sentinel aynasha","aynasha","who is aynasha","часовой айнаша","айнаша","кто такая айнаша"}},{q="Кто напал на Часового Айнашу?",a="Ее поджидала в засаде стая враждебных фурболгов во главе с Марошем Бесчестным. Во время первой стычки они отравили ее, надеясь одолеть обездвиженную разведчицу, пока она не оправилась.",al={"who attacked her","marosh the devious","marosh","who poisoned her","кто напал на нее","марош бесчестный","марош","кто ее отравил"}},{q="Куда направлялась Часовой Айнаша?",a="Айнаша шла в Аубердин, чтобы доставить важное донесение, но Марош и его следопыты задержали ее на дороге.",al={"where was aynasha going","aynasha destination","lor'danel","куда шла айнаша","цель айнаши","лор'данель"}},{q="Почему вы должны доложить Часовому Ойнее?",a="Поскольку Айнаше нужно немедленно спешить в Аубердин, чтобы передать сообщение, она просит вас отправиться на юг, на Заставу Мейстры в Ясеневом лесу, и сообщить Часовому Ойнее о враждебности фурболгов.",al={"sentinel onaeya","why maestra's post","onaeya","часовой ойнея","почему застава мейстры","ойнея"}},{q="Почему фурболги в этой местности враждебны?",a="На Темных берегах и в Ясеневом лесу многие племена фурболгов поддались демонической порче и безумию после Третьей войны, из-за чего без разбора нападают на Часовых и случайных путников.",al={"why are furbolgs attacking","furbolg hostility","corrupted furbolg","почему фурболги нападают","враждебность фурболгов","оскверненные фурболги"}},{q="Сражается ли Айнаша во время засады?",a="Да. Хотя яд едва позволяет ей стоять, она поддерживает своего защитника огнем из лука, пока готовит противоядие.",al={"does aynasha help","aynasha bow","does she fight","помогает ли айнаша","лук айнаши","сражается ли она"}}},fp="19,310,25.400.0,16.406.0,24.340.1,24.233.0,30.184.0,37.125.0,39.198.0,41.207.0,37.155.0"}
P.entries["quest:5722"] = {n="В поисках потерянного ранца",s="«В поисках потерянного ранца» — задание Орды, которое дает Рахауро на Вершине Старейшин в Громовом Утесе. По поручению Мудрой старухи Магаты Зловещего Тотема искателей приключений направляют под Оргриммар, в Огненную пропасть, найти останки Маура Зловещего Тотема, посланника, погибшего после того, как обнаружил нечто необычное среди троггов.",h="«В поисках потерянного ранца» — задание Орды, которое дает Рахауро на Вершине Старейшин в Громовом Утесе.",kw={"elder rise","magatha grimtotem","maur grimtotem","ragefire chasm","rahauro","searching for the lost satchel","thunder bluff","troggs","вершина старейшин","магата зловещий тотем","маур зловещий тотем","огненная пропасть","рахауро","в поисках потерянного ранца","громовой утес","трогги"},ang={["faction:Horde"]="Пока Тралл занят уничтожением темных культистов прямо под столицей Орды, грозовые шепоты из Мулгора говорят о том, что Зловещий Тотем преследует в той же пещере собственные тихие цели.",["race:Tauren"]="Намерения племени Зловещего Тотема часто резко расходятся с открытым руководством Кэрна Кровавого Копыта, поэтому скрытное любопытство Магаты к подземным существам под городом союзников заслуживает пристального внимания."},sec={{t="Задание Зловещего Тотема под Оргриммаром",b="Пока вождь Тралл и его советники заняты присутствием Совета Теней в Огненной пропасти, племя Зловещего Тотема преследует собственные тайные интересы. Магата Зловещий Тотем на Вершине Старейшин в Громовом Утесе узнает, что ее посланник Маур Зловещий Тотем спустился в подземную пещеру под Оргриммаром, чтобы изучить троггов и попытаться вступить с ними в переговоры. Маур не вернулся, но ходят слухи, что незадолго до гибели он сделал любопытную находку."},{t="Павший посланник",b="Действуя от имени Магаты, ее помощник Рахауро отправляет воинов прямо в пропасть. В глубине туннелей, залитых лавой, у лагерей троггов лежит изуродованное тело Маура, жестоко избитого грубыми дубинами и голыми кулаками. Твари совсем не тронули его вещи, оставив имущество тауренов и все секреты, которые он искал, агентам Магаты."}},faq={{q="Кто посылает искателей приключений на это задание?",a="Задание выдает Рахауро, помощник Магаты Зловещего Тотема на Вершине Старейшин в Громовом Утесе.",al={"quest giver","who starts searching for the lost satchel","where to get quest","персонаж, выдающий задания","кто начинает в поисках потерянного ранца","где взять задание"}},{q="Кто такой Маур Зловещий Тотем?",a="Маур был агентом племени Зловещего Тотема, посланным Магатой Зловещим Тотемом в Огненную пропасть, чтобы разведать обстановку и попытаться наладить связь с троггами. Его забили до смерти в глубине пещеры.",al={"maur grimtotem","who was maur","what happened to maur","маур зловещий тотем","кто такой маур","что случилось с мауром"}},{q="Почему Магату Зловещий Тотем заинтересовала Огненная пропасть?",a="Магату интересовали трогги, заполонившие туннели под Оргриммаром, и она послала Маура попытаться наладить с ними связь. Когда перед смертью Маур нашел среди них нечто необычное, она захотела, чтобы его находку доставили прямо ей.",al={"magatha troggs","why magatha cares about ragefire","why send maur","магата трогги","почему магату интересует огненная пропасть","зачем послали маура"}},{q="Где находится тело Маура Зловещего Тотема?",a="Тело Маура лежит в глубине Огненной пропасти под Оргриммаром, избитое, неподалеку от земель троггов вдоль подземных троп.",al={"find maur","maur grimtotem location","where is maurs body","найти маура","где маур зловещий тотем","где тело маура"}},{q="Обобрали ли трогги Маура после убийства?",a="Нет. Трогги мало заботятся о богатстве, инструментах и письменных бумагах, поэтому одежда и ранец Маура остались нетронутыми рядом с его изломанными останками.",al={"trogg loot","was maur robbed","добыча троггов","ограбили ли маура"}},{q="Что будет после того, как найдено тело Маура?",a="При осмотре тела Маура вы найдете его ранец, что открывает следующее задание «Возвращение потерянной сумки»: доставить его находки Магате Зловещий Тотем в Громовой Утес.",al={"follow up quest","next quest after lost satchel","what to do with satchel","следующее задание","какое задание после потерянного ранца","что делать с ранцем"}}},fp="30,335,37.466.0,19.397.1,36.106.0,22.189.0,55.237.0,41.132.0,43.138.0,40.170.1"}
P.entries["quest:5723"] = {n="Испытание силы врага",s="«Испытание силы врага» — задание Орды, которое выдает Рахауро на Вершине Старейшин в Громовом Утесе от имени Магаты Зловещего Тотема. После провального дипломатического шага под Оргриммаром, закончившегося гибелью посланников, таурены стремятся отомстить и истребляют троггов, заполонивших Огненную пропасть.",h="«Испытание силы врага» — задание Орды, которое выдает Рахауро на Вершине Старейшин в Громовом Утесе от имени...",kw={"elder rise","magatha grimtotem","orgrimmar","ragefire chasm","rahauro","testing an enemy's strength","thunder bluff","troggs","вершина старейшин","магата зловещий тотем","оргриммар","огненная пропасть","рахауро","испытание силы врага","громовой утес","трогги"},ang={["class:Shaman"]="У троггов есть собственные грубые духовные практики: они повелевают первобытными стихиями в лавовых туннелях, являя собой извращенное зеркало благородных шаманских традиций.",["faction:Horde"]="Это задание показывает солидарность между разными народами Орды: Громовой Утес тратит силы и воинов, чтобы защитить основания Оргриммара.",["race:Orc"]="Хотя задание дано руководством тауренов, оно напрямую защищает сердце орочьей столицы от троггов, прорывающих туннели под городом.",["race:Tauren"]="Кровь дипломатов-тауренов обагрила камни Огненной пропасти, и потому этот штурм становится актом прямого возмездия от имени Вершины Старейшин."},sec={{t="Дипломатия сталкивается с дикостью",b="Когда подземные трогги впервые выбрались из огненных расселин под орочьей столицей Оргриммаром, Мудрая старуха Магата Зловещий Тотем предложила мир. Она отправила в глубины посланников-тауренов для переговоров с этими существами. Ответ был жестоким и мгновенным: трогги без колебаний перебили делегатов. Сочтя расправу непростительным оскорблением тауренов и растущей угрозой для всей Орды, Магата решила ответить на дикость решительной силой."},{t="Угроза под Оргриммаром",b="Таурен Рахауро, действуя в Громовом Утесе как доверенное лицо Магаты, руководит военным ответом. Он направляет воинов проникнуть в Огненную пропасть, найти скопления троггов и уничтожить их передовых воинов и шаманов. Нанося удар в глубину их подземных владений, Орда стремится сократить число троггов прежде, чем их туннели позволят им свободно хлынуть на улицы Оргриммара наверху."}},faq={{q="Почему задание для подземелья Оргриммара выдают в Громовом Утесе?",a="Задание исходит от руководства тауренов. Магата Зловещий Тотем лично отправила дипломатов в Огненную пропасть на переговоры с троггами, и после гибели этих посланников ее помощник Рахауро взялся организовать воинов на Вершине Старейшин в Громовом Утесе, чтобы отомстить за них.",al={"why thunder bluff","quest start thunder bluff","rahauro location","почему громовой утес","начало задания громовой утес","где рахауро"}},{q="Кто такой Рахауро?",a="Рахауро — таурен, выдающий задания на Вершине Старейшин в Громовом Утесе. Он действует от имени Магаты Зловещего Тотема и руководит вылазками в Огненную пропасть, чтобы истреблять троггов и возвращать реликвии, потерянные во время прежних неудачных дипломатических миссий.",al={"who is rahauro","rahauro npc","rahauro elder rise","кто такой рахауро","рахауро нпс","рахауро вершина старейшин"}},{q="Почему Магата Зловещий Тотем пыталась заключить мир с троггами?",a="Магата задумывала это как жест доброй воли: она хотела наладить отношения с подземными существами, а не сразу проливать кровь. Однако трогги оказались неспособны или не пожелали вести мирную беседу и перебили ее посланников по прибытии.",al={"why peace with troggs","magatha trogg diplomacy","why negotiate with troggs","почему мир с троггами","дипломатия магаты с троггами","зачем вести переговоры с троггами"}},{q="Каких врагов нужно убить для этого задания?",a="Вам нужно войти в Огненную пропасть под Оргриммаром и убить как троггов Огненной пропасти, так и шаманов Огненной пропасти, чтобы сломить их передовые ряды и ослабить поддержку заклинателей.",al={"which mobs to kill","quest targets","ragefire troggs","каких мобов убить","цели задания","трогги огненной пропасти"}},{q="Можно ли выполнять это задание вместе с другими заданиями подземелья?",a="Да. Рахауро также выдает задание «В поисках потерянного ранца», которое отправляет искателей приключений в ту же пропасть на поиски останков неудачной дипломатической группы, поэтому выполнять оба задания одновременно удобно.",al={"other rfc quests","lost satchel quest","ragefire chasm quests","другие задания огненной пропасти","задание потерянный ранец","задания огненная пропасть"}},{q="Откуда приходят трогги?",a="Трогги выбрались из глубоких вулканических трещин под Дуротаром. Как отмечает Рахауро по завершении задания, Орда по-прежнему мало знает о происхождении этих диких пещерных жителей и о том, почему они решили прорыть ход наверх, в Оргриммар.",al={"trogg origin rfc","where do troggs come from","why are troggs under orgrimmar","происхождение троггов","откуда берутся трогги","почему трогги под оргриммаром"}}},fp="27,301,24.496.0,28.421.0,68.293.0,15.246.0,52.282.0,44.183.0,58.219.0,33.252.0"}
P.entries["quest:5724"] = {n="Возвращение потерянной сумки",s="Это поручение завершает поиски Маура Зловещего Тотема в глубинах Огненной пропасти под Оргриммаром. Найдя убитого таурена, крепко сжимающего свой ранец, искателям приключений предстоит доставить найденную сумку Рахауро на Вершину Старейшин в Громовом Утесе.",h="Это поручение завершает поиски Маура Зловещего Тотема в глубинах Огненной пропасти под Оргриммаром.",kw={"elder rise","grimtotem satchel","magatha","maur grimtotem","ragefire chasm","rahauro","returning the lost satchel","thunder bluff","вершина старейшин","сумка маура зловещего тотема","магата","маур зловещий тотем","огненная пропасть","рахауро","возвращение потерянной сумки","громовой утес"},ang={["faction:Horde"]="Трогги и культисты угрожают туннелям под Оргриммаром, а тайное присутствие агентов Зловещего Тотема под крепостью Тралла вызывает политические вопросы без ответов.",["race:Tauren"]="У клана Зловещего Тотема непростые отношения с народом Кэрна Кровавого Копыта, поэтому любая тайная операция последователей Магаты в Оргриммаре вызывает подозрения."},sec={{t="Мрачная находка",b="Под красными скалами и в огненных глубинах Огненной пропасти Маур Зловещий Тотем принял жестокую смерть от рук троггов. Даже мертвым он не разжал рук, обхвативших личную сумку, и охранял ее содержимое до последнего вздоха. Вынув сумку из окоченевших пальцев, вы получаете единственную зацепку о том, что привело члена клана Зловещего Тотема в вулканические пещеры под столицей Тралла."},{t="Интерес Магаты",b="Когда вы доставляете сумку Рахауро на Вершину Старейшин, становится ясно, что за поручением стояла сама Магата Зловещий Тотем. Рахауро с благодарностью принимает посылку, желая понять, почему напрасно погиб один из членов клана Магаты, и вручает награду, одобренную непосредственно Мудрой старухой. Что нес Маур и зачем Магата отправила его в кишащие троггами расселины Оргриммара, известно лишь руководству клана Зловещего Тотема."}},faq={{q="Где находится Маур Зловещий Тотем?",a="Тело Маура Зловещего Тотема лежит в глубине подземелья Огненная пропасть под Оргриммаром, в окружении враждебных троггов.",al={"maur grimtotem corpse","find maur grimtotem","where is maur","тело маура зловещего тотема","найти маура зловещего тотема","где маур"}},{q="Кому сдавать сумку?",a="Сумку Маура Зловещего Тотема нужно вернуть Рахауро, который стоит на Вершине Старейшин в Громовом Утесе.",al={"turn in lost satchel","where is rahauro","satchel turn in","сдать потерянную сумку","где рахауро","сдача сумки"}},{q="Почему Маур Зловещий Тотем оказался в Огненной пропасти?",a="Рахауро заявляет, что не знает, почему соплеменник Магаты должен был напрасно погибнуть, но Магата Зловещий Тотем лично приказала организовать поиски, что говорит о том, что Маур действовал по делам клана.",al={"why was maur in rfc","maur mission","what was maur doing","почему маур в огненной пропасти","миссия маура","что делал маур"}},{q="Что лежит в Сумке Маура Зловещего Тотема?",a="Точное содержимое посыльному не раскрывается. Маур ревностно охранял сумку до самой смерти, и ее передают Рахауро нераскрытой от имени Магаты.",al={"what was in the bag","satchel contents","что было в сумке","содержимое сумки"}},{q="Что убило Маура Зловещего Тотема?",a="Мауру устроили засаду и убили дикие трогги, населяющие туннели Огненной пропасти.",al={"how did maur die","who killed maur","как погиб маур","кто убил маура"}},{q="Кто стоит за этим заданием?",a="Хотя на Вершине Старейшин с вами имеет дело Рахауро, награда и указание исходят непосредственно от Мудрой старухи Магаты Зловещего Тотема.",al={"who sent rahauro","magatha connection","кто послал рахауро","связь магаты"}}},fp="26,255,16.403.0,18.455.1,32.116.0,32.101.0,41.179.0,37.169.0,27.92.0,24.123.0"}
P.entries["quest:5725"] = {n="Силы разрушения...",s="Это задание выдает повелитель ужаса Вариматрас в Подгороде и отправляет героев Орды в глубины Огненной пропасти под Оргриммаром. Леди Сильвана Ветрокрылая ищет два темных тома, которыми владеет демонический культ Пламенеющего Клинка, чтобы подпитать свою долгую войну против Плети и Короля-лича.",h="Это задание выдает повелитель ужаса Вариматрас в Подгороде и отправляет героев Орды в глубины Огненной...",kw={"incantations from the nether","lich king","ragefire chasm","searing blade","spells of shadow","sylvanas","undercity","varimathras","магическая формула пустоты","король-лич","огненная пропасть","пламенеющий клинок","заклинания тьмы","сильвана","подгород","вариматрас"},ang={["class:Warlock"]="Добыча книг «Заклинания Тьмы» и «Магическая формула Пустоты» — привычное дело для тех, кто вырывает опасные тайны Легиона у безрассудных культистов.",["faction:Horde"]="Разгром Пламенеющего Клинка помогает укрепить основания Оргриммара, даже если магическая добыча уплывает в хранилища Подгорода.",["race:Undead"]="Для воителей Отрекшихся путь через Великое море ради разграбления недр Оргриммара служит и союзу с Ордой, и главной цели Темной Госпожи — уничтожить Плеть."},sec={{t="Одолженный арсенал",b="Пока орки Тралла заняты истреблением культистов Пламенеющего Клинка, затаившихся прямо под их столицей, Отрекшиеся видят возможность в оккультных запасах культа. Вариматрас по приказу Сильваны Ветрокрылой посылает лазутчиков проникнуть в Огненную пропасть и завладеть двумя демоническими гримуарами: «Заклинания Тьмы» и «Магическая формула Пустоты». По мнению Темной Госпожи, дары демонов гораздо лучше служат дисциплинированной воле Отрекшихся, чем пропадают впустую у мелких культистов."},{t="Война за освобождение",b="Когда тома добыты, Вариматрас раскрывает их более широкое назначение. Темная магия в них должна усилить продолжающуюся кампанию Сильваны против Плети. Забирая каждую крупицу запретной силы, Отрекшиеся надеются разорвать хватку Короля-лича на Лордероне и полностью освободить оставшуюся нежить от его ментального рабства."}},faq={{q="Зачем Вариматрасу книги из-под Оргриммара?",a="Культисты Пламенеющего Клинка в Огненной пропасти владеют мощными демоническими томами. Леди Сильвана считает, что эти артефакты Пылающего Легиона пропадают зря у простых культистов, и хочет обратить их темные знания против Короля-лича.",al={"why varimathras ragefire","undercity ragefire quest reason","why steal books","зачем вариматрасу огненная пропасть","причина задания подгород огненная пропасть","зачем красть книги"}},{q="Какие книги вас посылают добыть?",a="Вам нужно забрать две книги заклинаний у культистов и чернокнижников Пламенеющего Клинка: «Заклинания Тьмы» и «Магическая формула Пустоты».",al={"what books","power to destroy books","ragefire book drops","какие книги","книги силы разрушения","книги огненная пропасть добыча"}},{q="Где в Подгороде находится Вариматрас?",a="Вариматрас стоит рядом с леди Сильваной Ветрокрылой в Королевском квартале Подгорода.",al={"varimathras location","where is varimathras","turn in location","где вариматрас","местонахождение вариматраса","где сдать задание"}},{q="Как это связано с общими целями Отрекшихся?",a="Сильвана собирает любые возможные средства для войны против Плети. Завладев запретными демоническими тайнами, Отрекшиеся получают больше магических рычагов, чтобы сокрушить власть Короля-лича над нежитью.",al={"forsaken motivation","why does sylvanas need spells","undercity lich king plot","мотивы отрекшихся","зачем сильване заклинания","подгород заговор короля-лича"}},{q="Знает ли Тралл, что Отрекшиеся забирают эти книги?",a="Пока руководство Орды в Оргриммаре занято очисткой своих улиц от предателей и демонов, особый приказ Вариматраса подается как тихое дело Темной Госпожи, а не как официальное совместное решение Орды.",al={"does thrall know","orgrimmar undercity secret books","shadow council books orc reaction","знает ли тралл","оргриммар подгород тайные книги","совет теней книги реакция орков"}},{q="Что представляет собой Пламенеющий Клинок?",a="Пламенеющий Клинок — тайная секта Совета Теней, действующая прямо в Огненной пропасти под Оргриммаром и практикующая темную демоническую магию под самым носом у Вождя.",al={"what is searing blade","searing blade ragefire","ragefire cultists","что такое пламенеющий клинок","пламенеющий клинок огненная пропасть","культисты огненной пропасти"}}},fp="23,288,18.494.0,22.344.0,58.238.0,35.126.0,47.89.0,53.203.0,53.239.0,26.182.0"}
P.entries["quest:5726"] = {n="Тайные враги",s="«Тайные враги» — первая часть расследования вождя Тралла о проникновении культистов в Дуротар. Зная, что сторонники демонов действуют прямо под носом у Орды, Тралл поручает многообещающему молодому герою добыть Лейтенантский знак отличия в Скале Черепа, чтобы начать тайную операцию.",h="«Тайные враги» — первая часть расследования вождя Тралла о проникновении культистов в Дуротар.",kw={"burning blade","durotar","hidden enemies","lieutenant's insignia","orgrimmar","skull rock","thrall","пылающий клинок","дуротар","тайные враги","лейтенантский знак отличия","оргриммар","скала черепа","тралл"},ang={["class:Warlock"]="Чернокнижникам Орды приходится действовать осторожно: практикуя магию Скверны под строгим надзором Тралла, они призваны искоренить культистов, чье безудержное служение демонам угрожает самому существованию Оргриммара.",["faction:Horde"]="Это задание — решающий миг, когда вождь Тралл лично доверяет герою защиту сердца новой Орды от демонического подрыва.",["race:Orc"]="Для орков, стремящихся преодолеть кровавый дурман и позор демонического проклятия, охота на Пылающий Клинок — личная борьба за то, чтобы демоническая скверна не отравила их народ во второй раз."},sec={{t="Гниль в Дуротаре",b="Пока молодая Орда пытается создать надежный дом в Дуротаре, вождь Тралл сталкивается с коварной угрозой, куда более смертоносной, чем набеги кентавров или вторжения свинобразов: изменой изнутри. Демонический культ, известный как Пылающий Клинок, укоренился прямо у ворот Оргриммара, питаясь остатками демонической порчи и жаждой темной силы. Тралл понимает, что, послав официальных стражей Кор'крона или известных командиров, он лишь заставит культистов спрятаться глубже. Ему нужен тот, кто не связан с громкими именами, — его осторожные глаза и уши."},{t="Проникновение в Скалу Черепа",b="К востоку от Оргриммара лежит Скала Черепа — суровая пещера, кишащая чернокнижниками, демонами Бездны и фанатичными культистами. Тралл отправляет героя прямо в это гнездо с особой целью: добыть Лейтенантский знак отличия у одного из предводителей Пылающего Клинка. Эта эмблема — не просто боевой трофей, а важный пропуск, дающий владельцу доступ к скрытой иерархии культа и позволяющий провести более глубокую операцию, чтобы выяснить, кто направляет действия культа из тени."}},faq={{q="Кто выдает задание «Тайные враги»?",a="Задание выдает сам вождь Тралл в Аллее Мудрости в Оргриммаре — после того как вы доложите Оргнилу Душегрызу.",al={"hidden enemies questgiver","who starts hidden enemies","where to start hidden enemies","тайные враги кто выдает","кто начинает тайные враги","где начать тайные враги"}},{q="Какова цель задания «Тайные враги»?",a="Тралл поручает вам отправиться в Скалу Черепа к востоку от Оргриммара, убить культистов Пылающего Клинка и принести Лейтенантский знак отличия.",al={"hidden enemies objective","what do i need for hidden enemies","тайные враги цель","что нужно для тайные враги"}},{q="Почему Тралл просто не отправит элитных стражей зачистить Скалу Черепа?",a="Тралл опасается, что открытое военное вмешательство позволит настоящим заговорщикам скрыться и глубже спрятать порчу. Неизвестный герой может тихо добыть пропуск и проникнуть в сеть, не насторожив высокопоставленных предателей, дергающих за ниточки.",al={"why thrall needs adventurers","why not send the army","почему тралл нанимает героев","почему не послать армию"}},{q="Что такое Скала Черепа?",a="Скала Черепа — уединенная система пещер на восточном побережье Дуротара, к северо-востоку от Оргриммара. Это тайная крепость и место призыва демонов для культа Пылающего Клинка.",al={"where is skull rock","what is skull rock cave","где скала черепа","что такое пещера скала черепа"}},{q="Для чего нужен Лейтенантский знак отличия?",a="Знак служит доказательством звания среди культистов. Тралл планирует с его помощью внедрить своего агента в ряды Пылающего Клинка, чтобы узнать, кто руководит их действиями.",al={"what is the insignia for","lieutenants insignia purpose","для чего знак отличия","лейтенантский знак отличия назначение"}},{q="Какие еще задания можно выполнить вместе с этим?",a="Герои, входящие в Скалу Черепа, часто выполняют задание «Скала Черепа», собирая ошейники культистов, и могут добыть Око Пылающей Тени у предводителя культа Газз'уза, чтобы начать задание «Пылающие тени».",al={"skull rock quests","quests in skull rock","задания скала черепа","задания в скале черепа"}}},fp="14,320,22.586.0,23.509.0,35.146.0,35.145.0,66.266.0,19.185.0,43.198.0,54.199.0"}
P.entries["quest:5727"] = {n="Тайные враги",s="После обнаружения деятельности культа в Скале Черепа вождь Тралл поручает вам проникнуть в Пылающий Клинок в самом Оргриммаре. Предъявив знак лейтенанта культа чернокнижнику Нииру Огненному Клинку, вы проверяете его верность и приоткрываете завесу над Советом Теней, действующим прямо под городом.",h="После обнаружения деятельности культа в Скале Черепа вождь Тралл поручает вам проникнуть в Пылающий Клинок в...",kw={"burning blade","cleft of shadow","insignia","neeru fireblade","orgrimmar","ragefire chasm","shadow council","thrall","пылающий клинок","расселина теней","знак отличия","нииру огненный клинок","оргриммар","огненная пропасть","совет теней","тралл"},ang={["class:Warlock"]="Нииру заявляет, что выступает за чернокнижников, ищущих законного положения в Орде, но его предательство грозит навлечь суровое осуждение на всех, кто практикует магию Скверны под властью Тралла.",["faction:Horde"]="Известие о том, что демонические культы открыто действуют под самим основанием Оргриммара, угрожает самому существованию молодой Орды.",["race:Orc"]="Для орков, стремящихся избавиться от наследия кровожадности и демонической порчи, возрождение Совета Теней под их столицей — жуткое эхо темного прошлого на Дреноре."},sec={{t="Хитрый план Вождя",b="Вместо прямого удара по зловещим силам в Расселине Теней Тралл выбирает хитрость, а не спешку. Он прекрасно знает, что Нииру Огненный Клинок притворяется верным, втайне служа культистам. Немедленный удар по Нииру лишь встревожит его хозяев и оборвет след, ведущий вглубь заговора. Поэтому Тралл передает знак, отобранный у культа в Дуротаре, и велит вам выдать себя за новичка, чтобы выяснить, что знает Нииру."},{t="Скрытый хозяин Расселины",b="В мрачных пещерах Расселины Теней, у входа в Огненную пропасть, Нииру Огненный Клинок быстро клюет на приманку. Приняв вас за недавно повышенного лейтенанта своего ордена, чернокнижник открыто насмехается над неведением Тралла. Он раскрывает, что Пылающий Клинок и ответвления вроде Пламенеющего Клинка — лишь ширмы, напрямую подчиняющиеся Совету Теней, который служит воле Пылающего Легиона. Он хвастается, что заставил Вождя бросить верных солдат против культистов в пропасти, используя армии самого Тралла, чтобы отсеять слабых."}},faq={{q="Почему Тралл оставляет Нииру в живых, если знает, что тот предатель?",a="Тралл позволяет Нииру жить, потому что разоблаченный предатель ценнее мертвого. Если казнить его сразу, Совет Теней просто заменит его кем-то, кого труднее обнаружить. Держа Нииру под присмотром, Тралл превращает чернокнижника в невольный источник сведений о передвижениях культа в Оргриммаре.",al={"why thrall trust neeru","why keep neeru alive","neeru traitor","почему тралл доверяет нииру","почему оставить нииру живым","нииру предатель"}},{q="Кто такой Нииру Огненный Клинок?",a="Нииру Огненный Клинок — орк-чернокнижник, живущий в Расселине Теней. Внешне он делает вид, что помогает Траллу превратить чернокнижников в верных слуг Орды. На деле он предводитель культа Пылающего Клинка и от имени Совета Теней плетет измену под городом.",al={"neeru backstory","who is neeru","нииру история","кто такой нииру"}},{q="Какова связь между Пылающим Клинком и Советом Теней?",a="Как раскрывает Нииру, Пылающий Клинок — не самостоятельная секта, а ветвь самого Совета Теней. Совет держит несколько дочерних культов, включая Пламенеющий Клинок в Огненной пропасти, чтобы разделять, обманывать и контролировать честолюбивых последователей под верховной властью Пылающего Легиона.",al={"burning blade shadow council connection","are burning blade shadow council","пылающий клинок совет теней связь","пылающий клинок и совет теней"}},{q="Кто возглавляет культистов в Огненной пропасти?",a="Культ Пламенеющего Клинка в пропасти под Оргриммаром возглавляют сатир Баззалан и орк-чернокнижник Жергош Призыватель Духов. Нииру использует героев Тралла для борьбы с ними, чтобы и проредить сторонников Орды, и испытать своих подчиненных.",al={"ragefire chasm leaders","searing blade leaders","предводители огненной пропасти","предводители пламенеющего клинка"}},{q="Как я получил Лейтенантский знак отличия?",a="Знак был добыт во время первого расследования Тралла о деятельности культа в Дуротаре, а именно у культистов Пылающего Клинка, действовавших из Скалы Черепа.",al={"where lieutenant insignia comes from","insignia source","откуда знак отличия","источник знака отличия"}}},fp="14,322,21.465.0,25.577.1,61.333.1,23.287.1,74.314.1,45.280.0,43.173.0"}
P.entries["quest:5728"] = {n="Тайные враги",s="«Тайные враги» — ключевое задание на проникновение, данное вождем Траллом, чтобы уничтожить коварный культ, процветающий под Оргриммаром. Обманув предателя Нииру Огненного Клинка и убедив его, что вы союзник, Тралл отправляет вас в раскаленные глубины Огненной пропасти, чтобы убить верховных командиров Пламенеющего Клинка.",h="«Тайные враги» — ключевое задание на проникновение, данное вождем Траллом, чтобы уничтожить коварный культ...",kw={"bazzalan","cleft of shadow","hidden enemies","jergosh the invoker","neeru fireblade","ragefire chasm","searing blade","shadow council","thrall","баззалан","расселина теней","тайные враги","жергош призыватель духов","нииру огненный клинок","огненная пропасть","пламенеющий клинок","совет теней","тралл"},ang={["class:Warlock"]="Хотя Тралл терпит чернокнижников, практикующих темные искусства для защиты Орды, Жергош и Пламенеющий Клинок переходят грань, становясь предательскими слугами демонических хозяев.",["faction:Horde"]="Демоническая порча в сердце Дуротара угрожает всему, что новая Орда боролась создать; очистка Огненной пропасти жизненно важна для сохранения ее нелегко доставшейся самостоятельности.",["race:Orc"]="Для орков, ищущих искупления за кровавый дурман, уничтожение остатков Совета Теней под Оргриммаром — вопрос глубокого культурного выживания и чести."},sec={{t="Рак под улицами",b="Оргриммар строился как убежище для свободного народа орков, но в его основании таются старые демонические оковы. Под шумными рынками лежит Расселина Теней, ведущая глубже, в подземные туннели Огненной пропасти. В этих вулканических глубинах набирают силу остатки Совета Теней — Пламенеющий Клинок, практикующий темные искусства и замышляющий изнутри, из собственной столицы, свергнуть молодую Орду."},{t="Игра в двойного агента",b="Прямой штурм без разведданных оставил бы сеть Совета Теней нетронутой. Тралл придумал тайный план, использовав вас, чтобы выманить сведения у Нииру Огненного Клинка, внешне покорного чернокнижника в Расселине Теней. Уверенный в вашей преданности их извращенному делу, Нииру невольно выдал имена подземных предводителей культа: порочного сатира Баззалана и чернокнижника Жергоша Призывателя Духов."},{t="Обезглавливание Пламенеющего Клинка",b="Тралл поручает вам спуститься в Огненную пропасть и убить Баззалана и Жергоша, повергнув культистов в хаос. Важно, чтобы убийства нельзя было приписать вам: Нииру не должен узнать, кто совершил расправу, ведь Тралл намерен держать чернокнижника под наблюдением. Гибель этих главарей потрясет культ и даст молодому городу Орды драгоценную передышку."}},faq={{q="Кто отдает приказ об убийстве в задании «Тайные враги»?",a="Вождь Тралл лично дает это поручение в Аллее Мудрости в Оргриммаре, доверяя вам щекотливую шпионскую работу ради безопасности городских низов.",al={"who gives hidden enemies","hidden enemies quest giver","thrall ragefire quest","кто выдает тайные враги","тайные враги персонаж, выдающий задание","тралл задание огненная пропасть"}},{q="Почему Тралл просто не казнит Нииру Огненного Клинка?",a="Тралл предпочитает держать Нииру в живых под наблюдением. Зная, кто предатель, разведчики Вождя могут следить за перепиской Совета Теней и предугадывать будущие заговоры, а не позволять скрытому преемнику занять его место.",al={"why not kill neeru","why keep neeru alive","neeru fireblade traitor","почему не убить нииру","почему оставить нииру живым","нииру огненный клинок предатель"}},{q="Где находятся Баззалан и Жергош Призыватель Духов?",a="Оба предводителя обитают в глубинах Огненной пропасти — подземелья, доступного через Расселину Теней в Оргриммаре. Жергош занимает вулканический уступ, откуда командует культистами, а сатир Баззалан скрывается в возвышенной пещере неподалеку.",al={"where is bazzalan","where is jergosh","ragefire chasm bosses","где баззалан","где жергош","боссы огненной пропасти"}},{q="Что представляет собой Пламенеющий Клинок?",a="Пламенеющий Клинок — местная секта, связанная с Пылающим Клинком и Советом Теней. Ее члены поклоняются демоническим силам и практикуют магию Скверны под Оргриммаром, надеясь в итоге свергнуть Тралла и вновь поработить Орду.",al={"what is searing blade","searing blade cult","burning blade orgrimmar","что такое пламенеющий клинок","культ пламенеющего клинка","пылающий клинок оргриммар"}},{q="Почему сатир вроде Баззалана действует под орочьим городом?",a="Сатиры — древние слуги Пылающего Легиона. Баззалан служит демоническим наставником и подстрекателем, направляя смертных культистов Пламенеющего Клинка исполнять волю Легиона прямо под ногами Тралла.",al={"why is there a satyr in orgrimmar","bazzalan lore","satyr in ragefire","почему сатир в оргриммаре","баззалан предания","сатир в огненной пропасти"}},{q="Как это задание вписывается в общее прохождение Огненной пропасти?",a="«Тайные враги» — кульминация цепочки заданий Тралла о проникновении. Оно сочетается с другими заданиями подземелья в Огненной пропасти и направляет игроков убить главных человекоподобных боссов подземелья одним согласованным ударом.",al={"is hidden enemies ragefire","rfc quest line","hidden enemies chain","тайные враги огненная пропасть","цепочка заданий огненной пропасти","цепочка тайные враги"}}},fp="14,323,28.426.0,24.430.1,30.409.2,37.166.0,48.242.1,51.232.0,26.228.0,57.211.0,60.230.0"}
P.entries["quest:5729"] = {n="Тайные враги",s="«Тайные враги» — важный этап расследования вождя Тралла о проникновении культистов в Оргриммар. Казнив предводителей Пылающего Клинка под городом, игрок получает задание еще глубже внедриться и стать доверенным лицом Нииру Огненного Клинка.",h="«Тайные враги» — важный этап расследования вождя Тралла о проникновении культистов в Оргриммар.",kw={"bazzalan","burning blade","cleft of shadow","hidden enemies","jergosh","neeru fireblade","orgrimmar","ragefire chasm","shadow council","thrall","баззалан","пылающий клинок","расселина теней","тайные враги","жергош","нииру огненный клинок","оргриммар","огненная пропасть","совет теней","тралл"},ang={["class:Rogue"]="Это задание — классический пример операции по внедрению: уничтожить сеть агента и сразу занять место его самого доверенного соратника.",["class:Warlock"]="Нииру Огненный Клинок открыто стоит среди учителей чернокнижников в Расселине Теней, показывая, как близко новая Орда Тралла соседствует с темной магией, не поддаваясь откровенной порче.",["faction:Horde"]="Задание подчеркивает прагматичную дипломатию и государственное мышление Тралла: он использует контрразведку, чтобы обезопасить Оргриммар изнутри, а не полагается лишь на грубую силу.",["race:Orc"]="Орки, стремящиеся избавиться от демонического наследия старой Орды, должны выкорчевать Пылающий Клинок из недр Оргриммара, чтобы защитить свою честь."},sec={{t="Ход Тралла",b="После убийства Баззалана и Жергоша Призывателя Духов в Огненной пропасти Тралл видит возможность. Вместо того чтобы разоблачить Нииру Огненного Клинка сразу, Вождь решает играть вдолгую. Нииру встревожен внезапной потерей своих подземных лейтенантов, и в местном культе образовалась пустота в руководстве. Тралл посылает вас обратно в сумрачные глубины Расселины Теней, чтобы вы предстали надежным союзником, способным заполнить эту пустоту."},{t="Обман чернокнижника",b="Когда к нему обращаются в Расселине Теней, Нииру Огненный Клинок явно в ярости из-за внезапной гибели своих сообщников. Не зная, что стоящий перед ним искатель приключений сам казнил их по приказу Тралла, Нииру проклинает «доброхотов», разоривших Огненную пропасть. Застигнутый врасплох быстрым ударом, Нииру начинает терять бдительность рядом с игроком, а Тралл получает возможность следить за влиянием Совета Теней прямо изнутри Оргриммара."}},faq={{q="Почему Тралл не казнит Нииру Огненного Клинка сразу?",a="Тралл предпочитает держать разоблаченного врага там, где можно за ним наблюдать. Пока Нииру считает, что его прикрытие цело, Тралл может следить за перепиской Пылающего Клинка и отследить его связи с Советом Теней, используя игрока как внедренного агента.",al={"why spare neeru","why does thrall let neeru live","neeru alive","зачем щадить нииру","почему тралл оставляет нииру в живых","нииру жив"}},{q="Кто такие Баззалан и Жергош?",a="Баззалан был сатиром, а Жергош Призыватель Духов — орком-чернокнижником. Действуя в глубине Огненной пропасти под Оргриммаром, они были полевыми командирами и заговорщиками культа Пылающего Клинка, пока Тралл не приказал их убить.",al={"bazzalan","jergosh","who died in ragefire","баззалан","жергош","кто погиб в огненной пропасти"}},{q="Знает ли Нииру, что вы убили его лейтенантов?",a="Нет. Нииру изливает ярость, считая, что неизвестные агенты Тралла застали их врасплох и перебили, и совершенно не подозревает, что искатель приключений, выражающий ему сочувствие и предлагающий помощь, и есть убийца.",al={"does neeru know","neeru knows who killed them","знает ли нииру","нииру знает, кто их убил"}},{q="Где находится Нииру Огненный Клинок?",a="Нииру Огненный Клинок обитает в Расселине Теней — подземной пещере в глубине Оргриммара, где собираются чернокнижники, разбойники и заклинатели тьмы, обособленно от остального города.",al={"neeru location","find neeru","where is neeru fireblade","где нииру","найти нииру","где нииру огненный клинок"}},{q="Что такое Пылающий Клинок?",a="Пылающий Клинок, изначально свирепый клан с Дренора, выродился в демонический культ, которым управлял Совет Теней. В Калимдоре его остатки стремятся подорвать новую Орду Тралла и вернуть рабство у демонов.",al={"burning blade","burning blade cult","пылающий клинок","культ пылающего клинка"}},{q="Что происходит после разговора с Нииру?",a="Заручившись доверием Нииру и выслушав его сетования о потерях в Огненной пропасти, вы возвращаетесь к Траллу в Крепость Громмаш, чтобы доложить об успехе и завершить цепочку внедрения.",al={"what next","quest continuation","что дальше","продолжение задания"}}},fp="14,264,15.468.0,23.473.1,60.270.0,30.229.0,46.190.0,33.189.0,26.217.0,37.189.1"}
P.entries["quest:5730"] = {n="Тайные враги",s="«Тайные враги» — завершение операции вождя Тралла по внедрению в шабаш Пылающего Клинка в Оргриммаре и его оценке. Вернувшись к Траллу после того, как заручились доверием Нииру Огненного Клинка, вы передаете важные сведения о растущем влиянии культа в Калимдоре.",h="«Тайные враги» — завершение операции вождя Тралла по внедрению в шабаш Пылающего Клинка в Оргриммаре и его...",kw={"ashenvale","barrens","burning blade","cleft of shadows","hidden enemies","neeru fireblade","ragefire chasm","searing blade","shadow council","thrall","ясеневый лес","степи","пылающий клинок","расселина теней","тайные враги","нииру огненный клинок","огненная пропасть","пламенеющий клинок","совет теней","тралл"},ang={["class:Rogue"]="Это задание отражает раннее шпионское ремесло Орды: глубокое прикрытие, контрразведка и терпение важнее немедленного столкновения.",["class:Warlock"]="Нииру Огненный Клинок олицетворяет опасную грань практики скверны и показывает, как легко темные искусства из разрешенного государством средства превращаются в откровенное подчинение Совету Теней.",["faction:Horde"]="Раскрытие измены в самих границах Оргриммара доказывает, что юная Орда должна защищаться от древней демонической порчи изнутри, сражаясь с внешними врагами."},sec={{t="Раскрытый культ",b="По просьбе вождя Тралла агент отнес Лейтенантский знак отличия, взятый у Скалы Черепа, Нииру Огненному Клинку — чернокнижнику, открыто живущему в Расселине Теней, а позже нанес удар по предводителям Пламенеющего Клинка в глубине Огненной пропасти. Играя роль готового на все новобранца и принося знаки павших культистов, агент завоевывает доверие Огненного Клинка, и тот невольно раскрывает более широкую сеть, стоящую за его действиями."},{t="Шепот Совета Теней",b="Думая, что обрел верного лейтенанта, Нииру Огненный Клинок признает, что потеря в Огненной пропасти — неудача для Пламенеющего Клинка, но заявляет, что великие замыслы Совета Теней остаются в силе. Он сообщает, что у его хозяев есть действующие агенты не только в Степях, но и глубже, в чащах Ясеневого леса. Эта весть застает Вождя врасплох: демонический заговор простирается далеко за пределы подземных туннелей столицы."},{t="Бдительность Вождя",b="Вместо немедленной казни Нииру Тралл выбирает осторожный путь. Пока Нииру не знает о своем разоблачении, Орда может следить за его перепиской и прослеживать щупальца культа в Дуротаре, Степях и Ясеневом лесу. Вождь готовит разведчиков и шпионов для проверки этих местных ответвлений, понимая, что искоренение демонической порчи требует точности, а не безрассудной спешки."}},faq={{q="В чем цель этого задания?",a="Вам нужно добраться из Расселины Теней в Аллею Мудрости в Оргриммаре и поговорить с вождем Траллом, рассказав, что Нииру Огненный Клинок поведал о планах Совета Теней.",al={"hidden enemies goal","what to do hidden enemies 5","thrall turn in","цель тайные враги","что делать тайные враги 5","сдать задание тралу"}},{q="Почему Нииру Огненный Клинок мне доверяет?",a="В ходе цепочки «Тайные враги» вы добыли Лейтенантский знак отличия у Пылающего Клинка на Скале Черепа и вручили его Нииру, выдав себя за честолюбивого неофита культа, и убедили его, что вы верный соратник.",al={"why neeru trusts me","tricking neeru","fireblade infiltration","почему нииру мне доверяет","обмануть нииру","внедрение к огненному клинку"}},{q="Почему Тралл не арестует и не казнит Нииру Огненного Клинка сразу?",a="Нииру гораздо полезнее живым и несведущим. Пока он думает, что его прикрытие цело, разведчики Тралла могут следить за его посланиями и отследить его контакты до более крупных ячеек Совета Теней по всему Калимдору.",al={"why is neeru alive","why not kill neeru","why thrall leaves neeru","почему нииру жив","почему не убить нииру","почему тралл оставляет нииру"}},{q="Что нового узнает Тралл из этого доклада?",a="Тралл узнает, что культ под Оргриммаром поддерживает Совет Теней и что его агенты активно замышляют операции и в Степях, и в чащах Ясеневого леса.",al={"what did thrall learn","shadow council ashenvale","neeru secret","что узнал тралл","совет теней ясеневый лес","тайна нииру"}},{q="Пылающий Клинок и Пламенеющий Клинок — это одно и то же?",a="Пламенеющий Клинок — местная секта, действующая в Огненной пропасти под Оргриммаром и являющаяся ответвлением более широкого культа Пылающего Клинка, которым управляет демонический Совет Теней.",al={"burning blade vs searing blade","ragefire chasm cults","cult differences","пылающий клинок и пламенеющий клинок","культы огненной пропасти","различия культов"}},{q="Продолжается ли эта цепочка заданий где-либо?",a="Тралл велит вам отдохнуть и обещает позвать позже, но прямого задания, которое сразу продолжало бы именно эту линию тайного внедрения, нет.",al={"hidden enemies followup","next quest after hidden enemies","where does thrall send you next","продолжение тайных врагов","следующее задание после тайных врагов","куда тралл отправит дальше"}}},fp="14,287,15.454.1,30.485.2,24.412.1,31.184.0,34.223.1,64.212.1,56.182.1,57.188.0,40.157.0"}
P.entries["quest:5761"] = {n="Убить тварь",s="Нииру Огненный Клинок, орк-чернокнижник из Расселины Теней в Оргриммаре, посылает бойцов Орды в глубь Огненной пропасти охотиться на Тарагамана Ненасытного. Заявляя, что действует по приказу вождя Тралла, Нииру требует сердце огромного стража Скверны как доказательство падения демонического культа.",h="Нииру Огненный Клинок, орк-чернокнижник из Расселины Теней в Оргриммаре, посылает бойцов Орды в глубь...",kw={"cleft of shadows","felguard","neeru fireblade","orgrimmar","ragefire chasm","searing blade","slaying the beast","taragaman","расселина теней","страж Скверны","нииру огненный клинок","оргриммар","огненная пропасть","пламенеющий клинок","убить тварь","тарагаман"},ang={["class:Warlock"]="Работая в Расселине Теней рядом с Нииру, чернокнижники воочию видят, как трудно балансировать на политическом канате тем, кто практикует магию Скверны под бдительным взором Тралла.",["faction:Horde"]="Очистка демонического присутствия, гноящегося прямо под столицей Орды, — вопрос немедленного выживания города для каждой расы Оргриммара.",["race:Orc"]="Для орков, стремящихся избавиться от наследия проклятия демонической крови, обнаружить стража Скверны и демонический культ прямо под троном Тралла — нестерпимый позор."},sec={{t="Угроза под городом",b="Под красной земляной поверхностью Оргриммара лежит Огненная пропасть — пылающая подземная расселина, кишащая троггами, зверями и тайными агентами Пламенеющего Клинка. В Расселине Теней наверху Нииру Огненный Клинок представляется верным слугой, которому Тралл поручил очистить это демоническое гнездо. Он указывает прямо на Тарагамана Ненасытного, огромного стража Скверны в сердце пещеры, называя демона вдохновителем подземного культа."},{t="Обман чернокнижника",b="Сердце Тарагамана, доставленное Нииру Огненному Клинку, приносит высокую похвалу и обещания, что Тралл будет удовлетворен. На деле Тарагаман — не настоящий вожак культа, а заменимый головорез. Направив героев Орды на демона, Нииру дает Траллу заметную победу, чтобы развеять подозрения, и оберегает от пристального внимания истинное руководство Пламенеющего Клинка и его глубинные операции под Оргриммаром."}},faq={{q="Кто такой Тарагаман Ненасытный?",a="Тарагаман Ненасытный — могучий страж Скверны, стоящий на скалистой площадке в сердце Огненной пропасти. Нииру Огненный Клинок называет его предводителем культистов Пламенеющего Клинка, гнездящихся под Оргриммаром.",al={"who is taragaman","what is taragaman","taragaman lore","кто такой тарагаман","что такое тарагаман","предания о тарагамане"}},{q="Кто выдает задание «Убить тварь»?",a="Нииру Огненный Клинок выдает это задание в своей палатке в Расселине Теней — пещерном квартале чернокнижников Оргриммара.",al={"quest giver slaying the beast","who gives this quest","neeru fireblade quest","кто выдает убить тварь","кто дает это задание","задание нииру огненного клинка"}},{q="Зачем Нииру нужно сердце Тарагамана?",a="Нииру утверждает, что сердце нужно, чтобы доказать вождю Траллу, что демоническая угроза под Оргриммаром уничтожена.",al={"why get the heart","taragaman heart purpose","why does neeru want the heart","зачем сердце","для чего сердце тарагамана","зачем нииру сердце"}},{q="Тарагаман действительно предводитель Пламенеющего Клинка?",a="Нииру Огненный Клинок называет его предводителем. Тарагаман — грозный страж Скверны, обитающий среди культистов Пламенеющего Клинка в сердце Огненной пропасти.",al={"is taragaman the real leader","who leads searing blade","taragaman leader","настоящий ли тарагаман лидер","кто возглавляет пламенеющий клинок","лидер тарагаман"}},{q="Где находится Тарагаман?",a="Тарагаман Ненасытный стоит на каменной площадке, окруженной лавой, в средней части Огненной пропасти, среди культистов Пламенеющего Клинка.",al={"taragaman location","where is the beast","where to find taragaman","где тарагаман","где тварь","где найти тарагамана"}},{q="Как это задание связано с «Тайными врагами»?",a="В цепочке «Тайные враги» Тралл расследует проникновение Совета Теней в Оргриммар и присматривает за Нииру Огненным Клинком. Нииру дает это задание, чтобы показать Траллу видимые успехи против Пламенеющего Клинка.",al={"connection to hidden enemies","hidden enemies questline","thrall and neeru","связь с тайными врагами","цепочка тайные враги","тралл и нииру"}}},fp="17,289,25.472.0,23.417.1,30.204.0,38.115.0,38.122.1,54.153.1,27.145.0,46.226.1"}
P.entries["quest:5762"] = {n="Хеминг Эрнестуэй",s="Это поручение отправляет путников через море — от соляных равнин Калимдора в парные джунгли Тернистой долины. Крейвел Углебрад, оборотистый торговец с Виражей на Миражах, просит искателей приключений доставить давно задержанную посылку со специальными припасами знаменитому охотнику на крупного зверя Хемингу Эрнестуэю.",h="Это поручение отправляет путников через море — от соляных равнин Калимдора в парные джунгли Тернистой долины.",kw={"ammunition","hemet nesingwary","kravel koalbeard","kravel's crate","mirage raceway","shimmering flats","stranglethorn vale","боеприпасы","хеминг эрнестуэй","крейвел углебрад","сундук крейвела","виражи на миражах","мерцающая равнина","тернистая долина"},ang={["class:Hunter"]="Доставка специальных боеприпасов Хемингу Эрнестуэю знакомит следопытов с самым известным сафари на крупного зверя в Азероте.",["race:Dwarf"]="Доставка особых боеприпасов между двумя плутоватыми знакомыми-дворфами показывает, как далеко разбредаются выходцы из Стальгорна в погоне за монетой и добычей."},sec={{t="Доставка через континенты",b="На слепящих просторах Мерцающей равнины торговля идет бойко, но грузы порой запаздывают. Крейвел Углебрад наконец получает задержавшийся ящик, предназначенный одному из его богатых покровителей — Хемингу Эрнестуэю. Хеминг покинул Тысячу Игл задолго до прибытия посылки и заранее заплатил за ее пересылку в свой охотничий лагерь в глуши Тернистой долины. Вместо того чтобы самому совершать тяжелый путь, Крейвел нанимает странствующих искателей приключений, готовых преодолеть океан."},{t="Боеприпасы для охоты",b="Разыскав экспедицию Эрнестуэя к северу от Лагеря Гром'гол, вы узнаете, что в тяжелом ящике лежат специальные крупнокалиберные боеприпасы, необходимые для охоты на опасных хищников, бродящих по джунглям. Хеминг сразу замечает на снаряжении посыльного характерную белую корку соляных равнин и радуется, что старая дружба с хитрецом Крейвелом принесла его сафари столь нужную огневую мощь."}},faq={{q="Где начинается и заканчивается эта доставка?",a="Доставка начинается у Крейвела Углебрада на Виражах на Миражах, на Мерцающей равнине на юге Тысячи Игл. Она завершается на другом краю света, в лагере экспедиции Хеминга Эрнестуэя на севере Тернистой долины, чуть севернее Гром'гола.",al={"quest start and end","where is hemet","where do i go","начало и конец задания","где хеминг","куда идти"}},{q="Что находится в Сундуке Крейвела?",a="В ящике лежат боеприпасы особого калибра для оружия охотников на крупного зверя. Хеминг Эрнестуэй заказал эти особые патроны, чтобы пробивать толстые шкуры самых свирепых зверей Тернистой долины.",al={"whats in the crate","crate contents","kravel package","что в ящике","содержимое ящика","посылка крейвела"}},{q="Почему Крейвел не доставил ящик сам?",a="Крейвел — предприимчивый торговец-дворф, занятый своими вложениями и затеями на Виражах на Миражах. Вместо того чтобы бросить свой пост и пересекать моря, он предпочитает нанять проходящих искателей приключений на деньги, которые Эрнестуэй заплатил заранее.",al={"why kravel hire someone","why does kravel need help","зачем крейвел нанимает","почему крейвелу нужна помощь"}},{q="Как Хеминг узнает, откуда прибыл посыльный?",a="Получив посылку, Хеминг сразу замечает по запаху и виду характерную соляную корку на одежде посыльного и отмечает, что она именно с Мерцающей равнины, а не обычная пустынная пыль.",al={"desert salt","hemet dialogue salt","пустынная соль","диалог хеминга о соли"}},{q="Какие отношения связывают Крейвела и Хеминга?",a="Хеминг — давний и выгодный клиент Крейвела. Крейвел уважает его тугой кошелек, а Хеминг с теплом считает Крейвела «старым прохвостом», который вечно что-то затевает.",al={"kravel and hemet history","do they know each other","история крейвела и хеминга","знакомы ли они"}},{q="Кто такой Хеминг Эрнестуэй?",a="Хеминг Эрнестуэй — знаменитый стрелок-дворф, писатель и охотник на крупного зверя, возглавляющий нескончаемое сафари в опасных глубинах Тернистой долины.",al={"who is hemet","nesingwary lore","кто такой хеминг","предания об эрнестуэе"}}},fp="16,316,27.507.0,23.417.0,39.265.0,30.179.0,44.241.0,48.209.0,51.178.0,24.157.0"}
P.entries["quest:579"] = {n="Библиотека Штормграда",s="В глубине Королевской библиотеки Крепости Штормграда главный библиотекарь Донал Товальд ведает собранием исторических трудов и описаний земель. По приказу юного короля Андуина Ринна выделены средства на переписывание этих трудов для горожан и ученых, приносящих официальные библиотечные свитки. Эта услуга позволяет искателям приключений изучить историю, фракции и легенды Азерота из первых рук.",h="В глубине Королевской библиотеки Крепости Штормграда главный библиотекарь Донал Товальд ведает собранием...",kw={"anduin wrynn","books","donyal tovald","library scrip","lore tomes","stormwind keep","stormwind library","transcription","андуин ринн","книги","донал товальд","библиотечный свиток","тома преданий","крепость штормграда","библиотека штормграда","переписывание"},ang={["class:Mage"]="Для приверженцев тайной магии Королевская библиотека — важный светский архив королевства: в нем хранятся немагические исторические сочинения, которые дополняют изучение тайных искусств в Квартале магов.",["faction:Alliance"]="Библиотека хранит общие триумфы и трагедии Альянса Лордерона и напоминает горожанам об исторических узах между людьми, дворфами, гномами и высшими эльфами.",["race:Human"]="Лишившись бесчисленных архивов при разорении старого Штормграда в Первой войне, ученые-люди высоко ценят сохранение и копирование всех хроник, переживших восстановление королевства."},sec={{t="Королевский указ о знаниях",b="Пока верховный лорд Болвар Фордрагон и леди Катрана Престор ведают обороной и придворной политикой в отсутствие короля Вариана, юный король Андуин направил королевские средства на образование. Понимая, что знание истории важно для будущего королевства, Андуин взял под покровительство переписывание древних рукописей и исторических дневников. Королевская библиотека в залах Крепости Штормграда служит не только хранилищем государственных тайн, но и собранием, где предания сохраняются в записях и копируются для тех, кто состоит на королевской службе."},{t="Обмен свитков",b="Переписывание хрупкого пергамента вручную требует много времени, чернил и королевского дозволения. Чтобы управлять этой раздачей, главный библиотекарь Донал Товальд принимает официальные библиотечные свитки, выдаваемые искателям приключений и ученым по землям Альянса. Взамен Товальд предоставляет верные копии исторических томов — от древней истории Восточных королевств до описаний дальних земель, — давая представление о конфликтах за стенами столицы."}},faq={{q="Для чего нужно задание Библиотеки Штормграда?",a="Это задание позволяет сдать Библиотечный свиток главному библиотекарю Доналу Товальду в обмен на читаемые книги преданий. Они рассказывают о прошлом различных сюжетов, людей и земель Альянса по всему Азероту.",al={"what does this quest do","stormwind library quest purpose","why do this quest","что дает это задание","зачем библиотека штормграда","зачем выполнять задание"}},{q="Кто такой Донал Товальд?",a="Донал Товальд — библиотекарь, заведующий Королевской библиотекой в Крепости Штормграда. Он ведает собранием письменных хроник королевства и исполняет распоряжение Андуина раздавать копии достойным ученым и искателям приключений.",al={"who is donyal tovald","librarian stormwind","who gives the books","кто такой донал товальд","библиотекарь штормграда","кто выдает книги"}},{q="Где получить Библиотечный свиток?",a="Библиотечные свитки выдают за особые задания на землях Альянса — у ученых, магистратов и чиновников, поощряющих исследования и интерес к миру.",al={"where do i get library scrip","how to get library scrip","library scrip source","где взять библиотечный свиток","как получить библиотечный свиток","источник библиотечного свитка"}},{q="Почему юный король Андуин финансирует библиотеку?",a="Король Андуин Ринн придает большое личное значение учению и образованию. Даже будучи ребенком, правящим под руководством регента Болвара Фордрагона, он выделил королевские средства, чтобы сделать копии исторических томов королевства доступными для всех.",al={"why does anduin care about books","anduin library funding","king anduin books","почему андуину важны книги","финансирование библиотеки андуином","король андуин книги"}},{q="Где в Штормграде находится библиотека?",a="Королевская библиотека находится в Крепости Штормграда — огромной цитадели, возвышающейся в восточной части города. Донала Товальда можно найти внутри, среди высоких полок и читальных столов.",al={"where is stormwind library","royal library location","where is donyal tovald located","где библиотека штормграда","расположение королевской библиотеки","где донал товальд"}},{q="Могу ли я читать полученные книги?",a="Да. Каждая книга из библиотеки — читаемый игровой предмет, раскрывающий колорит, сюжетный фон и контекст различных легенд и исторических событий мира Warcraft.",al={"are the books readable","can you open the books","do books do anything","можно ли читать книги","можно ли открыть книги","есть ли польза от книг"}}},fp="17,403,29.547.0,18.488.0,51.220.0,21.232.0,36.190.0,45.242.0,42.202.0,31.193.0"}
